CREATE TABLE wp_bible_verses (
    id INT AUTO_INCREMENT PRIMARY KEY,
    testament VARCHAR(50),
    book VARCHAR(50),
    chapter INT,
    verse INT,
    text TEXT,
    reference VARCHAR(20)
);

INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 1, 'فِي الْبَدْءِ خَلَقَ اللهُ السَّمَاوَاتِ وَالْأَرْضَ.', 'تكوين 1:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 2, 'وَكَانَتِ الْأَرْضُ خَرِبَةً وَخَالِيَةً، وَعَلَى وَجْهِ الْغَمْرِ ظُلْمَةٌ، وَرُوحُ اللهِ يَرِفُّ عَلَى وَجْهِ الْمِيَاهِ.', 'تكوين 1:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 3, 'وَقَالَ اللهُ׃ «لِيَكُنْ نُورٌ»، فَكَانَ نُورٌ.', 'تكوين 1:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 4, 'وَرَأَى اللهُ النُّورَ أَنَّهُ حَسَنٌ. وَفَصَلَ اللهُ بَيْنَ النُّورِ وَالظُّلْمَةِ.', 'تكوين 1:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 5, 'وَدَعَا اللهُ النُّورَ نَهَارًا، وَالظُّلْمَةُ دَعَاهَا لَيْلًا. وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا وَاحِدًا.', 'تكوين 1:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 6, 'وَقَالَ اللهُ׃ «لِيَكُنْ جَلَدٌ فِي وَسَطِ الْمِيَاهِ. وَلْيَكُنْ فَاصِلًا بَيْنَ مِيَاهٍ وَمِيَاهٍ».', 'تكوين 1:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 7, 'فَعَمِلَ اللهُ الْجَلَدَ، وَفَصَلَ بَيْنَ الْمِيَاهِ الَّتِي تَحْتَ الْجَلَدِ وَالْمِيَاهِ الَّتِي فَوْقَ الْجَلَدِ. وَكَانَ كَذَلِكَ.', 'تكوين 1:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 8, 'وَدَعَا اللهُ الْجَلَدَ سَمَاءً. وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا ثَانِيًا.', 'تكوين 1:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 9, 'وَقَالَ اللهُ׃ «لِتَجْتَمِعِ الْمِيَاهُ تَحْتَ السَّمَاءِ إِلَى مَكَانٍ وَاحِدٍ، وَلْتَظْهَرِ الْيَابِسَةُ». وَكَانَ كَذَلِكَ.', 'تكوين 1:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 10, 'وَدَعَا اللهُ الْيَابِسَةَ أَرْضًا، وَمُجْتَمَعَ الْمِيَاهِ دَعَاهُ بِحَارًا. وَرَأَى اللهُ ذَلِكَ أَنَّهُ حَسَنٌ.', 'تكوين 1:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 11, 'وَقَالَ اللهُ׃ «لِتُنْبِتِ الْأَرْضُ عُشْبًا وَبَقْلًا يُبْزِرُ بِزْرًا، وَشَجَرًا ذَا ثَمَرٍ يَعْمَلُ ثَمَرًا كَجِنْسِهِ، بِزْرُهُ فِيهِ عَلَى الْأَرْضِ». وَكَانَ كَذَلِكَ.', 'تكوين 1:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 12, 'فَأَخْرَجَتِ الْأَرْضُ عُشْبًا وَبَقْلًا يُبْزِرُ بِزْرًا كَجِنْسِهِ، وَشَجَرًا يَعْمَلُ ثَمَرًا بِزْرُهُ فِيهِ كَجِنْسِهِ. وَرَأَى اللهُ ذَلِكَ أَنَّهُ حَسَنٌ.', 'تكوين 1:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 13, 'وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا ثَالِثًا.', 'تكوين 1:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 14, 'وَقَالَ اللهُ׃ «لِتَكُنْ أَنْوَارٌ فِي جَلَدِ السَّمَاءِ لِتَفْصِلَ بَيْنَ النَّهَارِ وَاللَّيْلِ، وَتَكُونَ لِآيَاتٍ وَأَوْقَاتٍ وَأَيَّامٍ وَسِنِينٍ.', 'تكوين 1:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 15, 'وَتَكُونَ أَنْوَارًا فِي جَلَدِ السَّمَاءِ لِتُنِيرَ عَلَى الْأَرْضِ». وَكَانَ كَذَلِكَ.', 'تكوين 1:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 16, 'فَعَمِلَ اللهُ النُّورَيْنِ الْعَظِيمَيْنِ׃ النُّورَ الْأَكْبَرَ لِحُكْمِ النَّهَارِ، وَالنُّورَ الْأَصْغَرَ لِحُكْمِ اللَّيْلِ، وَالنُّجُومَ.', 'تكوين 1:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 17, 'وَجَعَلَهَا اللهُ فِي جَلَدِ السَّمَاءِ لِتُنِيرَ عَلَى الْأَرْضِ،', 'تكوين 1:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 18, 'وَلِتَحْكُمَ عَلَى النَّهَارِ وَاللَّيْلِ، وَلِتَفْصِلَ بَيْنَ النُّورِ وَالظُّلْمَةِ. وَرَأَى اللهُ ذَلِكَ أَنَّهُ حَسَنٌ.', 'تكوين 1:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 19, 'وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا رَابِعًا.', 'تكوين 1:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 20, 'وَقَالَ اللهُ׃ «لِتَفِضِ الْمِيَاهُ زَحَّافَاتٍ ذَاتَ نَفْسٍ حَيَّةٍ، وَلْيَطِرْ طَيْرٌ فَوْقَ الْأَرْضِ عَلَى وَجْهِ جَلَدِ السَّمَاءِ».', 'تكوين 1:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 21, 'فَخَلَقَ اللهُ التَّنَانِينَ الْعِظَامَ، وَكُلَّ ذَوَاتِ الْأَنْفُسِ الْحيَّةِ الدَّبَّابَةِ الْتِى فَاضَتْ بِهَا الْمِيَاهُ كَأَجْنَاسِهَا، وَكُلَّ طَائِرٍ ذِي جَنَاحٍ كَجِنْسِهِ. وَرَأَى اللهُ ذَلِكَ أَنَّهُ حَسَنٌ.', 'تكوين 1:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 22, 'وَبَارَكَهَا اللهُ قَائِلًا׃ «أَثْمِرِي وَاكْثُرِي وَامْلَإِي الْمِيَاهَ فِي الْبِحَارِ. وَلْيَكْثُرِ الطَّيْرُ عَلَى الْأَرْضِ».', 'تكوين 1:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 23, 'وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا خَامِسًا.', 'تكوين 1:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 24, 'وَقَالَ اللهُ׃ «لِتُخْرِجِ الْأَرْضُ ذَوَاتِ أَنْفُسٍ حَيَّةٍ كَجِنْسِهَا׃ بَهَائِمَ، وَدَبَّابَاتٍ، وَوُحُوشَ أَرْضٍ كَأَجْنَاسِهَا». وَكَانَ كَذَلِكَ.', 'تكوين 1:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 25, 'فَعَمِلَ اللهُ وُحُوشَ الْأَرْضِ كَأَجْنَاسِهَا، وَالْبَهَائِمَ كَأَجْنَاسِهَا، وَجَمِيعَ دَبَّابَاتِ الْأَرْضِ كَأَجْنَاسِهَا. وَرَأَى اللهُ ذَلِكَ أَنَّهُ حَسَنٌ.', 'تكوين 1:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 26, 'وَقَالَ اللهُ׃ «نَعْمَلُ الْإِنْسَانَ عَلَى صُورَتِنَا كَشَبَهِنَا، فَيَتَسَلَّطُونَ عَلَى سَمَكِ الْبَحْرِ وَعَلَى طَيْرِ السَّمَاءِ وَعَلَى الْبَهَائِمِ، وَعَلَى كُلِّ الْأَرْضِ، وَعَلَى جَمِيعِ الدَّبَّابَاتِ الَّتِي تَدِبُّ عَلَى الْأَرْضِ».', 'تكوين 1:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 27, 'فَخَلَقَ اللهُ الْإِنْسَانَ عَلَى صُورَتِهِ. عَلَى صُورَةِ اللهِ خَلَقَهُ. ذَكَرًا وَأُنْثَى خَلَقَهُمْ.', 'تكوين 1:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 28, 'وَبَارَكَهُمُ اللهُ وَقَالَ لَهُمْ׃ «أَثْمِرُوا وَاكْثُرُوا وَامْلَأُوا الْأَرْضَ، وَأَخْضِعُوهَا، وَتَسَلَّطُوا عَلَى سَمَكِ الْبَحْرِ وَعَلَى طَيْرِ السَّمَاءِ وَعَلَى كُلِّ حَيَوَانٍ يَدِبُّ عَلَى الْأَرْضِ».', 'تكوين 1:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 29, 'وَقَالَ اللهُ׃ «إِنِّي قَدْ أَعْطَيْتُكُمْ كُلَّ بَقْلٍ يُبْزِرُ بِزْرًا عَلَى وَجْهِ كُلِّ الْأَرْضِ، وَكُلَّ شَجَرٍ فِيهِ ثَمَرُ شَجَرٍ يُبْزِرُ بِزْرًا لَكُمْ يَكُونُ طَعَامًا.', 'تكوين 1:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 30, 'وَلِكُلِّ حَيَوَانِ الْأَرْضِ وَكُلِّ طَيْرِ السَّمَاءِ وَكُلِّ دَبَّابَةٍ عَلَى الْأَرْضِ فِيهَا نَفْسٌ حَيَّةٌ، أَعْطَيْتُ كُلَّ عُشْبٍ أَخْضَرَ طَعَامًا». وَكَانَ كَذَلِكَ.', 'تكوين 1:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 1, 31, 'وَرَأَى اللهُ كُلَّ مَا عَمِلَهُ فَإِذَا هُوَ حَسَنٌ جِدًّا. وَكَانَ مَسَاءٌ وَكَانَ صَبَاحٌ يَوْمًا سَادِسًا.', 'تكوين 1:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 1, 'فَأُكْمِلَتِ السَّمَاوَاتُ وَالْأَرْضُ وَكُلُّ جُنْدِهَا.', 'تكوين 2:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 2, 'وَفَرَغَ اللهُ فِي الْيَوْمِ السَّابِعِ مِنْ عَمَلِهِ الَّذِي عَمِلَ. فَاسْتَرَاحَ فِي الْيَوْمِ السَّابِعِ مِنْ جَمِيعِ عَمَلِهِ الَّذِي عَمِلَ.', 'تكوين 2:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 3, 'وَبَارَكَ اللهُ الْيَوْمَ السَّابِعَ وَقَدَّسَهُ، لِأَنَّهُ فِيهِ اسْتَرَاحَ مِنْ جَمِيعِ عَمَلِهِ الَّذِي عَمِلَ اللهُ خَالِقًا.', 'تكوين 2:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 4, 'هَذِهِ مَبَادِئُ السَّمَاوَاتِ وَالْأَرْضِ حِينَ خُلِقَتْ، يَوْمَ عَمِلَ الرَّبُّ الْإِلَهُ الْأَرْضَ وَالسَّمَاوَاتِ.', 'تكوين 2:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 5, 'كُلُّ شَجَرِ الْبَرِّيَّةِ لَمْ يَكُنْ بَعْدُ فِي الْأَرْضِ، وَكُلُّ عُشْبِ الْبَرِّيَّةِ لَمْ يَنْبُتْ بَعْدُ، لِأَنَّ الرَّبَّ الْإِلَهَ لَمْ يَكُنْ قَدْ أَمْطَرَ عَلَى الْأَرْضِ، وَلَا كَانَ إِنْسَانٌ لِيَعْمَلَ الْأَرْضَ.', 'تكوين 2:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 6, 'ثُمَّ كَانَ ضَبَابٌ يَطْلَعُ مِنَ الْأَرْضِ وَيَسْقِي كُلَّ وَجْهِ الْأَرْضِ.', 'تكوين 2:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 7, 'وَجَبَلَ الرَّبُّ الْإِلَهُ آدَمَ تُرَابًا مِنَ الْأَرْضِ، وَنَفَخَ فِي أَنْفِهِ نَسَمَةَ حَيَاةٍ. فَصَارَ آدَمُ نَفْسًا حَيَّةً.', 'تكوين 2:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 8, 'وَغَرَسَ الرَّبُّ الْإِلَهُ جَنَّةً فِي عَدْنٍ شَرْقًا، وَوَضَعَ هُنَاكَ آدَمَ الَّذِي جَبَلَهُ.', 'تكوين 2:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 9, 'وَأَنْبَتَ الرَّبُّ الْإِلَهُ مِنَ الْأَرْضِ كُلَّ شَجَرَةٍ شَهِيَّةٍ لِلنَّظَرِ وَجَيِّدَةٍ لِلْأَكْلِ، وَشَجَرَةَ الْحَيَاةِ فِي وَسَطِ الْجَنَّةِ، وَشَجَرَةَ مَعْرِفَةِ الْخَيْرِ وَالشَّرِّ.', 'تكوين 2:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 10, 'وَكَانَ نَهْرٌ يَخْرُجُ مِنْ عَدْنٍ لِيَسْقِيَ الْجَنَّةَ، وَمِنْ هُنَاكَ يَنْقَسِمُ فَيَصِيرُ أَرْبَعَةَ رُؤُوسٍ׃', 'تكوين 2:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 11, 'اِسْمُ الْوَاحِدِ فِيشُونُ، وَهُوَ الْمُحِيطُ بِجَمِيعِ أَرْضِ الْحَوِيلَةِ حَيْثُ الذَّهَبُ.', 'تكوين 2:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 12, 'وَذَهَبُ تِلْكَ الْأَرْضِ جَيِّدٌ. هُنَاكَ الْمُقْلُ وَحَجَرُ الْجَزْعِ.', 'تكوين 2:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 13, 'وَاسْمُ النَّهْرِ الثَّانِى جِيحُونُ، وَهُوَ الْمُحِيطُ بِجَمِيعِ أَرْضِ كُوشٍ.', 'تكوين 2:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 14, 'وَاسْمُ النَّهْرِ الثَّالِثِ حِدَّاقِلُ، وَهُوَ الْجَارِي شَرْقِيَّ أَشُّورَ. وَالنَّهْرُ الرَّابِعُ الْفُرَاتُ.', 'تكوين 2:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 15, 'وَأَخَذَ الرَّبُّ الْإِلَهُ آدَمَ وَوَضَعَهُ فِي جَنَّةِ عَدْنٍ لِيَعْمَلَهَا وَيَحْفَظَهَا.', 'تكوين 2:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 16, 'وَأَوْصَى الرَّبُّ الْإِلَهُ آدَمَ قَائِلًا׃ «مِنْ جَمِيعِ شَجَرِ الْجَنَّةِ تَأْكُلُ أَكْلًا،', 'تكوين 2:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 17, 'وَأَمَّا شَجَرَةُ مَعْرِفَةِ الْخَيْرِ وَالشَّرِّ فَلَا تَأْكُلْ مِنْهَا، لِأَنَّكَ يَوْمَ تَأْكُلُ مِنْهَا مَوْتًا تَمُوتُ».', 'تكوين 2:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 18, 'وَقَالَ الرَّبُّ الْإِلَهُ׃ «لَيْسَ جَيِّدًا أَنْ يَكُونَ آدَمُ وَحْدَهُ، فَأَصْنَعَ لَهُ مُعِينًا نَظِيرَهُ».', 'تكوين 2:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 19, 'وَجَبَلَ الرَّبُّ الْإِلَهُ مِنَ الْأَرْضِ كُلَّ حَيَوَانَاتِ الْبَرِّيَّةِ وَكُلَّ طُيُورِ السَّمَاءِ، فَأَحْضَرَهَا إِلَى آدَمَ لِيَرَى مَاذَا يَدْعُوهَا، وَكُلُّ مَا دَعَا بِهِ آدَمُ ذَاتَ نَفْسٍ حَيَّةٍ فَهُوَ اسْمُهَا.', 'تكوين 2:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 20, 'فَدَعَا آدَمُ بِأَسْمَاءٍ جَمِيعَ الْبَهَائِمِ وَطُيُورَ السَّمَاءِ وَجَمِيعَ حَيَوَانَاتِ الْبَرِّيَّةِ. وَأَمَّا لِنَفْسِهِ فَلَمْ يَجِدْ مُعِينًا نَظِيرَهُ.', 'تكوين 2:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 21, 'فَأَوْقَعَ الرَّبُّ الْإِلَهُ سُبَاتًا عَلَى آدَمَ فَنَامَ، فَأَخَذَ وَاحِدَةً مِنْ أَضْلَاعِهِ وَمَلَأَ مَكَانَهَا لَحْمًا.', 'تكوين 2:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 22, 'وَبَنَى الرَّبُّ الْإِلَهُ الضِّلْعَ الَّتِي أَخَذَهَا مِنْ آدَمَ امْرَأَةً وَأَحْضَرَهَا إِلَى آدَمَ.', 'تكوين 2:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 23, 'فَقَالَ آدَمُ׃ «هَذِهِ الْآنَ عَظْمٌ مِنْ عِظَامِي وَلَحْمٌ مِنْ لَحْمِي. هَذِهِ تُدْعَى امْرَأَةً لِأَنَّهَا مِنِ امْرِءٍ أُخِذَتْ».', 'تكوين 2:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 24, 'لِذَلِكَ يَتْرُكُ الرَّجُلُ أَبَاهُ وَأُمَّهُ وَيَلْتَصِقُ بِامْرَأَتِهِ وَيَكُونَانِ جَسَدًا وَاحِدًا.', 'تكوين 2:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 2, 25, 'وَكَانَا كِلَاهُمَا عُرْيَانَيْنِ، آدَمُ وَامْرَأَتُهُ، وَهُمَا لَا يَخْجَلَانِ.', 'تكوين 2:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 1, 'وَكَانَتِ الْحَيَّةُ أَحْيَلَ جَمِيعِ حَيَوَانَاتِ الْبَرِّيَّةِ الَّتِي عَمِلَهَا الرَّبُّ الْإِلَهُ، فَقَالَتْ لِلْمَرْأَةِ׃ «أَحَقًّا قَالَ اللهُ لَا تَأْكُلَا مِنْ كُلِّ شَجَرِ الْجَنَّةِ؟»', 'تكوين 3:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 2, 'فَقَالَتِ الْمَرْأَةُ لِلْحَيَّةِ׃ «مِنْ ثَمَرِ شَجَرِ الْجَنَّةِ نَأْكُلُ،', 'تكوين 3:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 3, 'وَأَمَّا ثَمَرُ الشَّجَرَةِ الَّتِي فِي وَسَطِ الْجَنَّةِ فَقَالَ اللهُ׃ لَا تَأْكُلَا مِنْهُ وَلَا تَمَسَّاهُ لِئَلَّا تَمُوتَا».', 'تكوين 3:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 4, 'فَقَالَتِ الْحَيَّةُ لِلْمَرْأَةِ׃ «لَنْ تَمُوتَا!', 'تكوين 3:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 5, 'بَلِ اللهُ عَالِمٌ أَنَّهُ يَوْمَ تَأْكُلَانِ مِنْهُ تَنْفَتِحُ أَعْيُنُكُمَا وَتَكُونَانِ كَاللهِ عَارِفَيْنِ الْخَيْرَ وَالشَّرَّ».', 'تكوين 3:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 6, 'فَرَأَتِ الْمَرْأَةُ أَنَّ الشَّجَرَةَ جَيِّدَةٌ لِلْأَكْلِ، وَأَنَّهَا بَهِجَةٌ لِلْعُيُونِ، وَأَنَّ الشَّجَرَةَ شَهِيَّةٌ لِلنَّظَرِ. فَأَخَذَتْ مِنْ ثَمَرِهَا وَأَكَلَتْ، وَأَعْطَتْ رَجُلَهَا أَيْضًا مَعَهَا فَأَكَلَ.', 'تكوين 3:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 7, 'فَانْفَتَحَتْ أَعْيُنُهُمَا وَعَلِمَا أَنَّهُمَا عُرْيَانَانِ. فَخَاطَا أَوْرَاقَ تِينٍ وَصَنَعَا لِأَنْفُسِهِمَا مَآزِرَ.', 'تكوين 3:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 8, 'وَسَمِعَا صَوْتَ الرَّبِّ الْإِلَهِ مَاشِيًا فِي الْجَنَّةِ عِنْدَ هُبُوبِ رِيحِ النَّهَارِ، فَاخْتَبَأَ آدَمُ وَامْرَأَتُهُ مِنْ وَجْهِ الرَّبِّ الْإِلَهِ فِي وَسَطِ شَجَرِ الْجَنَّةِ.', 'تكوين 3:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 9, 'فَنَادَى الرَّبُّ الْإِلَهُ آدَمَ وَقَالَ لَهُ׃ «أَيْنَ أَنْتَ؟».', 'تكوين 3:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 10, 'فَقَالَ׃ «سَمِعْتُ صَوْتَكَ فِي الْجَنَّةِ فَخَشِيتُ، لِأَنِّي عُرْيَانٌ فَاخْتَبَأْتُ».', 'تكوين 3:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 11, 'فَقَالَ׃ «مَنْ أَعْلَمَكَ أَنَّكَ عُرْيَانٌ؟ هَلْ أَكَلْتَ مِنَ الشَّجَرَةِ الَّتِي أَوْصَيْتُكَ أَنْ لَا تَأْكُلَ مِنْهَا؟»', 'تكوين 3:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 12, 'فَقَالَ آدَمُ׃ «الْمَرْأَةُ الَّتِي جَعَلْتَهَا مَعِي هِيَ أَعْطَتْنِي مِنَ الشَّجَرَةِ فَأَكَلْتُ».', 'تكوين 3:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 13, 'فَقَالَ الرَّبُّ الْإِلَهُ لِلْمَرْأَةِ׃ «مَا هَذَا الَّذِي فَعَلْتِ؟» فَقَالَتِ الْمَرْأَةُ׃ «الْحَيَّةُ غَرَّتْنِي فَأَكَلْتُ».', 'تكوين 3:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 14, 'فَقَالَ الرَّبُّ الْإِلَهُ لِلْحَيَّةِ׃ «لِأَنَّكِ فَعَلْتِ هَذَا، مَلْعُونَةٌ أَنْتِ مِنْ جَمِيعِ الْبَهَائِمِ وَمِنْ جَمِيعِ وُحُوشِ الْبَرِّيَّةِ. عَلَى بَطْنِكِ تَسْعَيْنَ وَتُرَابًا تَأْكُلِينَ كُلَّ أَيَّامِ حَيَاتِكِ.', 'تكوين 3:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 15, 'وَأَضَعُ عَدَاوَةً بَيْنَكِ وَبَيْنَ الْمَرْأَةِ، وَبَيْنَ نَسْلِكِ وَنَسْلِهَا. هُوَ يَسْحَقُ رَأْسَكِ، وَأَنْتِ تَسْحَقِينَ عَقِبَهُ».', 'تكوين 3:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 16, 'وَقَالَ لِلْمَرْأَةِ׃ «تَكْثِيرًا أُكَثِّرُ أَتْعَابَ حَبَلِكِ، بِالْوَجَعِ تَلِدِينَ أَوْلَادًا. وَإِلَى رَجُلِكِ يَكُونُ اشْتِيَاقُكِ وَهُوَ يَسُودُ عَلَيْكِ».', 'تكوين 3:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 17, 'وَقَالَ لِآدَمَ׃ «لِأَنَّكَ سَمِعْتَ لِقَوْلِ امْرَأَتِكَ وَأَكَلْتَ مِنَ الشَّجَرَةِ الَّتِي أَوْصَيْتُكَ قَائِلًا׃ لَا تَأْكُلْ مِنْهَا، مَلْعُونَةٌ الْأَرْضُ بِسَبَبِكَ. بِالتَّعَبِ تَأْكُلُ مِنْهَا كُلَّ أَيَّامِ حَيَاتِكَ.', 'تكوين 3:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 18, 'وَشَوْكًا وَحَسَكًا تُنْبِتُ لَكَ، وَتَأْكُلُ عُشْبَ الْحَقْلِ.', 'تكوين 3:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 19, 'بِعَرَقِ وَجْهِكَ تَأْكُلُ خُبْزًا حَتَّى تَعُودَ إِلَى الْأَرْضِ الَّتِي أُخِذْتَ مِنْهَا. لِأَنَّكَ تُرَابٌ، وَإِلَى تُرَابٍ تَعُودُ».', 'تكوين 3:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 20, 'وَدَعَا آدَمُ اسْمَ امْرَأَتِهِ «حَوَّاءَ» لِأَنَّهَا أُمُّ كُلِّ حَيٍّ.', 'تكوين 3:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 21, 'وَصَنَعَ الرَّبُّ الْإِلَهُ لِآدَمَ وَامْرَأَتِهِ أَقْمِصَةً مِنْ جِلْدٍ وَأَلْبَسَهُمَا.', 'تكوين 3:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 22, 'وَقَالَ الرَّبُّ الْإِلَهُ׃ «هُوَذَا الْإِنْسَانُ قَدْ صَارَ كَوَاحِدٍ مِنَّا عَارِفًا الْخَيْرَ وَالشَّرَّ. وَالْآنَ لَعَلَّهُ يَمُدُّ يَدَهُ وَيَأْخُذُ مِنْ شَجَرَةِ الْحَيَاةِ أَيْضًا وَيَأْكُلُ وَيَحْيَا إِلَى الْأَبَدِ».', 'تكوين 3:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 23, 'فَأَخْرَجَهُ الرَّبُّ الْإِلَهُ مِنْ جَنَّةِ عَدْنٍ لِيَعْمَلَ الْأَرْضَ الَّتِي أُخِذَ مِنْهَا.', 'تكوين 3:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 3, 24, 'فَطَرَدَ الْإِنْسَانَ، وَأَقَامَ شَرْقِيَّ جَنَّةِ عَدْنٍ الْكَرُوبِيمَ، وَلَهِيبَ سَيْفٍ مُتَقَلِّبٍ لِحِرَاسَةِ طَرِيقِ شَجَرَةِ الْحَيَاةِ.', 'تكوين 3:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 1, 'وَعَرَفَ آدَمُ حَوَّاءَ امْرَأَتَهُ فَحَبِلَتْ وَوَلَدَتْ قَايِينَ. وَقَالَتِ׃ «اقْتَنَيْتُ رَجُلًا مِنْ عِنْدِ الرَّبِّ».', 'تكوين 4:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 2, 'ثُمَّ عَادَتْ فَوَلَدَتْ أَخَاهُ هَابِيلَ. وَكَانَ هَابِيلُ رَاعِيًا لِلْغَنَمِ، وَكَانَ قَايِينُ عَامِلًا فِي الْأَرْضِ.', 'تكوين 4:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 3, 'وَحَدَثَ مِنْ بَعْدِ أَيَّامٍ أَنَّ قَايِينَ قَدَّمَ مِنْ أَثْمَارِ الْأَرْضِ قُرْبَانًا لِلرَّبِّ،', 'تكوين 4:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 4, 'وَقَدَّمَ هَابِيلُ أَيْضًا مِنْ أَبْكَارِ غَنَمِهِ وَمِنْ سِمَانِهَا. فَنَظَرَ الرَّبُّ إِلَى هَابِيلَ وَقُرْبَانِهِ،', 'تكوين 4:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 5, 'وَلَكِنْ إِلَى قَايِينَ وَقُرْبَانِهِ لَمْ يَنْظُرْ. فَاغْتَاظَ قَايِينُ جِدًّا وَسَقَطَ وَجْهُهُ.', 'تكوين 4:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 6, 'فَقَالَ الرَّبُّ لِقَايِينَ׃ «لِمَاذَا اغْتَظْتَ؟ وَلِمَاذَا سَقَطَ وَجْهُكَ؟', 'تكوين 4:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 7, 'إِنْ أَحْسَنْتَ أَفَلَا رَفْعٌ؟ وَإِنْ لَمْ تُحْسِنْ فَعِنْدَ الْبَابِ خَطِيَّةٌ رَابِضَةٌ، وَإِلَيْكَ اشْتِيَاقُهَا وَأَنْتَ تَسُودُ عَلَيْهَا».', 'تكوين 4:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 8, 'وَكَلَّمَ قَايِينُ هَابِيلَ أَخَاهُ. وَحَدَثَ إِذْ كَانَا فِي الْحَقْلِ أَنَّ قَايِينَ قَامَ عَلَى هَابِيلَ أَخِيهِ وَقَتَلَهُ.', 'تكوين 4:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 9, 'فَقَالَ الرَّبُّ لِقَايِينَ׃ «أَيْنَ هَابِيلُ أَخُوكَ؟» فَقَالَ׃ «لَا أَعْلَمُ! أَحَارِسٌ أَنَا لِأَخِي؟»', 'تكوين 4:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 10, 'فَقَالَ׃ «مَاذَا فَعَلْتَ؟ صَوْتُ دَمِ أَخِيكَ صَارِخٌ إِلَيَّ مِنَ الْأَرْضِ.', 'تكوين 4:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 11, 'فَالْآنَ مَلْعُونٌ أَنْتَ مِنَ الْأَرْضِ الَّتِي فَتَحَتْ فَاهَا لِتَقْبَلَ دَمَ أَخِيكَ مِنْ يَدِكَ.', 'تكوين 4:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 12, 'مَتَى عَمِلْتَ الْأَرْضَ لَا تَعُودُ تُعْطِيكَ قُوَّتَهَا. تَائِهًا وَهَارِبًا تَكُونُ فِي الْأَرْضِ».', 'تكوين 4:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 13, 'فَقَالَ قَايِينُ لِلرَّبِّ׃ «ذَنْبِي أَعْظَمُ مِنْ أَنْ يُحْتَمَلَ.', 'تكوين 4:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 14, 'إِنَّكَ قَدْ طَرَدْتَنِي الْيَوْمَ عَنْ وَجْهِ الْأَرْضِ، وَمِنْ وَجْهِكَ أَخْتَفِي وَأَكُونُ تَائِهًا وَهَارِبًا فِي الْأَرْضِ، فَيَكُونُ كُلُّ مَنْ وَجَدَنِي يَقْتُلُنِي».', 'تكوين 4:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 15, 'فَقَالَ لَهُ الرَّبُّ׃ «لِذَلِكَ كُلُّ مَنْ قَتَلَ قَايِينَ فَسَبْعَةَ أَضْعَافٍ يُنْتَقَمُ مِنْهُ». وَجَعَلَ الرَّبُّ لِقَايِينَ عَلَامَةً لِكَيْ لَا يَقْتُلَهُ كُلُّ مَنْ وَجَدَهُ.', 'تكوين 4:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 16, 'فَخَرَجَ قَايِينُ مِنْ لَدُنِ الرَّبِّ، وَسَكَنَ فِي أَرْضِ نُودٍ شَرْقِيَّ عَدْنٍ.', 'تكوين 4:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 17, 'وَعَرَفَ قَايِينُ امْرَأَتَهُ فَحَبِلَتْ وَوَلَدَتْ حَنُوكَ. وَكَانَ يَبْنِي مَدِينَةً، فَدَعَا اسْمَ الْمَدِينَةِ كَاسْمِ ابْنِهِ حَنُوكَ.', 'تكوين 4:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 18, 'وَوُلِدَ لِحَنُوكَ عِيرَادُ. وَعِيرَادُ وَلَدَ مَحُويَائِيلَ. وَمَحُويَائِيلُ وَلَدَ مَتُوشَائِيلَ. وَمَتُوشَائِيلُ وَلَدَ لَامَكَ.', 'تكوين 4:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 19, 'وَاتَّخَذَ لَامَكُ لِنَفْسِهِ امْرَأَتَيْنِ׃ اسْمُ الْوَاحِدَةِ عَادَةُ، وَاسْمُ الْأُخْرَى صِلَّةُ.', 'تكوين 4:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 20, 'فَوَلَدَتْ عَادَةُ يَابَالَ الَّذِي كَانَ أَبًا لِسَاكِنِي الْخِيَامِ وَرُعَاةِ الْمَوَاشِي.', 'تكوين 4:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 21, 'وَاسْمُ أَخِيهِ يُوبَالُ الَّذِي كَانَ أَبًا لِكُلِّ ضَارِبٍ بِالْعُودِ وَالْمِزْمَارِ.', 'تكوين 4:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 22, 'وَصِلَّةُ أَيْضًا وَلَدَتْ تُوبَالَ قَايِينَ الضَّارِبَ كُلَّ آلَةٍ مِنْ نُحَاسٍ وَحَدِيدٍ. وَأُخْتُ تُوبَالَ قَايِينَ نَعْمَةُ.', 'تكوين 4:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 23, 'وَقَالَ لَامَكُ لِامْرَأَتَيْهِ عَادَةَ وَصِلَّةَ׃ «اسْمَعَا قَوْلِي يَا امْرَأَتَيْ لَامَكَ، وَأَصْغِيَا لِكَلَامِي. فَإِنِّي قَتَلْتُ رَجُلًا لِجُرْحِي، وَفَتىً لِشَدْخِي.', 'تكوين 4:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 24, 'إِنَّهُ يُنْتَقَمُ لِقَايِينَ سَبْعَةَ أَضْعَافٍ، وَأَمَّا لِلَامَكَ فَسَبْعَةً وَسَبْعِينَ».', 'تكوين 4:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 25, 'وَعَرَفَ آدَمُ امْرَأَتَهُ أَيْضًا، فَوَلَدَتِ ابْنًا وَدَعَتِ اسْمَهُ شِيثًا، قَائِلَةً׃ «لِأَنَّ اللهَ قَدْ وَضَعَ لِي نَسْلًا آخَرَ عِوَضًا عَنْ هَابِيلَ». لِأَنَّ قَايِينَ كَانَ قَدْ قَتَلَهُ.', 'تكوين 4:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 4, 26, 'وَلِشِيثَ أَيْضًا وُلِدَ ابْنٌ فَدَعَا اسْمَهُ أَنُوشَ. حِينَئِذٍ ابْتُدِئَ أَنْ يُدْعَى بِاسْمِ الرَّبِّ.', 'تكوين 4:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 1, 'هَذَا كِتَابُ مَوَالِيدِ آدَمَ، يَوْمَ خَلَقَ اللهُ الْإِنْسَانَ. عَلَى شَبَهِ اللهِ عَمِلَهُ.', 'تكوين 5:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 2, 'ذَكَرًا وَأُنْثَى خَلَقَهُ، وَبَارَكَهُ وَدَعَا اسْمَهُ آدَمَ يَوْمَ خُلِقَ.', 'تكوين 5:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 3, 'وَعَاشَ آدَمُ مِئَةً وَثَلَاثِينَ سَنَةً، وَوَلَدَ وَلَدًا عَلَى شَبَهِهِ كَصُورَتِهِ وَدَعَا اسْمَهُ شِيثًا.', 'تكوين 5:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 4, 'وَكَانَتْ أَيَّامُ آدَمَ بَعْدَ مَا وَلَدَ شِيثًا ثَمَانِيَ مِئَةِ سَنَةٍ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 5, 'فَكَانَتْ كُلُّ أَيَّامِ آدَمَ الَّتِي عَاشَهَا تِسْعَ مِئَةٍ وَثَلَاثِينَ سَنَةً، وَمَاتَ.', 'تكوين 5:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 6, 'وَعَاشَ شِيثُ مِئَةً وَخَمْسَ سِنِينَ، وَوَلَدَ أَنُوشَ.', 'تكوين 5:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 7, 'وَعَاشَ شِيثُ بَعْدَ مَا وَلَدَ أَنُوشَ ثَمَانِيَ مِئَةٍ وَسَبْعَ سِنِينَ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 8, 'فَكَانَتْ كُلُّ أَيَّامِ شِيثَ تِسْعَ مِئَةٍ وَاثْنَتَيْ عَشَرَةَ سَنَةً، وَمَاتَ.', 'تكوين 5:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 9, 'وَعَاشَ أَنُوشُ تِسْعِينَ سَنَةً، وَوَلَدَ قِينَانَ.', 'تكوين 5:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 10, 'وَعَاشَ أَنُوشُ بَعْدَ مَا وَلَدَ قِينَانَ ثَمَانِيَ مِئَةٍ وَخَمْسَ عَشَرَةَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 11, 'فَكَانَتْ كُلُّ أَيَّامِ أَنُوشَ تِسْعَ مِئَةٍ وَخَمْسَ سِنِينَ، وَمَاتَ.', 'تكوين 5:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 12, 'وَعَاشَ قِينَانُ سَبْعِينَ سَنَةً، وَوَلَدَ مَهْلَلْئِيلَ.', 'تكوين 5:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 13, 'وَعَاشَ قِينَانُ بَعْدَ مَا وَلَدَ مَهْلَلْئِيلَ ثَمَانِيَ مِئَةٍ وَأَرْبَعِينَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 14, 'فَكَانَتْ كُلُّ أَيَّامِ قِينَانَ تِسْعَ مِئَةٍ وَعَشْرَ سِنِينَ، وَمَاتَ.', 'تكوين 5:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 15, 'وَعَاشَ مَهْلَلْئِيلُ خَمْسًا وَسِتِّينَ سَنَةً، وَوَلَدَ يَارَدَ.', 'تكوين 5:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 16, 'وَعَاشَ مَهْلَلْئِيلُ بَعْدَ مَا وَلَدَ يَارَدَ ثَمَانِيَ مِئَةٍ وَثَلَاثِينَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 17, 'فَكَانَتْ كُلُّ أَيَّامِ مَهْلَلْئِيلَ ثَمَانِيَ مِئَةٍ وَخَمْسًا وَتِسْعِينَ سَنَةً، وَمَاتَ.', 'تكوين 5:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 18, 'وَعَاشَ يَارَدُ مِئَةً وَاثْنَتَيْنِ وَسِتِّينَ سَنَةً، وَوَلَدَ أَخْنُوخَ.', 'تكوين 5:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 19, 'وَعَاشَ يَارَدُ بَعْدَ مَا وَلَدَ أَخْنُوخَ ثَمَانِيَ مِئَةِ سَنَةٍ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 20, 'فَكَانَتْ كُلُّ أَيَّامِ يَارَدَ تِسْعَ مِئَةٍ وَاثْنَتَيْنِ وَسِتِّينَ سَنَةً، وَمَاتَ.', 'تكوين 5:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 21, 'وَعَاشَ أَخْنُوخُ خَمْسًا وَسِتِّينَ سَنَةً، وَوَلَدَ مَتُوشَالَحَ.', 'تكوين 5:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 22, 'وَسَارَ أَخْنُوخُ مَعَ اللهِ بَعْدَ مَا وَلَدَ مَتُوشَالَحَ ثَلَاثَ مِئَةِ سَنَةٍ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 23, 'فَكَانَتْ كُلُّ أَيَّامِ أَخْنُوخَ ثَلَاثَ مِئَةٍ وَخَمْسًا وَسِتِّينَ سَنَةً.', 'تكوين 5:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 24, 'وَسَارَ أَخْنُوخُ مَعَ اللهِ، وَلَمْ يُوجَدْ لِأَنَّ اللهَ أَخَذَهُ.', 'تكوين 5:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 25, 'وَعَاشَ مَتُوشَالَحُ مِئَةً وَسَبْعًا وَثَمَانِينَ سَنَةً، وَوَلَدَ لَامَكَ.', 'تكوين 5:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 26, 'وَعَاشَ مَتُوشَالَحُ بَعْدَ مَا وَلَدَ لَامَكَ سَبْعَ مِئَةٍ وَاثْنَتَيْنِ وَثَمَانِينَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 27, 'فَكَانَتْ كُلُّ أَيَّامِ مَتُوشَالَحَ تِسْعَ مِئَةٍ وَتِسْعًا وَسِتِّينَ سَنَةً، وَمَاتَ.', 'تكوين 5:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 28, 'وَعَاشَ لَامَكُ مِئَةً وَاثْنَتَيْنِ وَثَمَانِينَ سَنَةً، وَوَلَدَ ابْنًا.', 'تكوين 5:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 29, 'وَدَعَا اسْمَهُ نُوحًا، قَائِلًا׃ «هَذَا يُعَزِّينَا عَنْ عَمَلِنَا وَتَعَبِ أَيْدِينَا مِنْ قِبَلِ الْأَرْضِ الَّتِي لَعَنَهَا الرَّبُّ».', 'تكوين 5:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 30, 'وَعَاشَ لَامَكُ بَعْدَ مَا وَلَدَ نُوحًا خَمْسَ مِئَةٍ وَخَمْسًا وَتِسْعِينَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 5:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 31, 'فَكَانَتْ كُلُّ أَيَّامِ لَامَكَ سَبْعَ مِئَةٍ وَسَبْعًا وَسَبْعِينَ سَنَةً، وَمَاتَ.', 'تكوين 5:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 5, 32, 'وَكَانَ نُوحٌ ابْنَ خَمْسِ مِئَةِ سَنَةٍ. وَوَلَدَ نُوحٌ׃ سَامًا، وَحَامًا، وَيَافَثَ.', 'تكوين 5:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 1, 'وَحَدَثَ لَمَّا ابْتَدَأَ النَّاسُ يَكْثُرُونَ عَلَى الْأَرْضِ، وَوُلِدَ لَهُمْ بَنَاتٌ،', 'تكوين 6:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 2, 'أَنَّ أَبْنَاءَ اللهِ رَأَوْا بَنَاتِ النَّاسِ أَنَّهُنَّ حَسَنَاتٌ. فَاتَّخَذُوا لِأَنْفُسِهِمْ نِسَاءً مِنْ كُلِّ مَا اخْتَارُوا.', 'تكوين 6:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 3, 'فَقَالَ الرَّبُّ׃ «لَا يَدِينُ رُوحِي فِي الْإِنْسَانِ إِلَى الْأَبَدِ، لِزَيَغَانِهِ، هُوَ بَشَرٌ. وَتَكُونُ أَيَّامُهُ مِئَةً وَعِشْرِينَ سَنَةً».', 'تكوين 6:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 4, 'كَانَ فِي الْأَرْضِ طُغَاةٌ فِي تِلْكَ الْأَيَّامِ. وَبَعْدَ ذَلِكَ أَيْضًا إِذْ دَخَلَ بَنُو اللهِ عَلَى بَنَاتِ النَّاسِ وَوَلَدْنَ لَهُمْ أَوْلَادًا، هَؤُلَاءِ هُمُ الْجَبَابِرَةُ الَّذِينَ مُنْذُ الدَّهْرِ ذَوُو اسْمٍ.', 'تكوين 6:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 5, 'وَرَأَى الرَّبُّ أَنَّ شَرَّ الْإِنْسَانِ قَدْ كَثُرَ فِي الْأَرْضِ، وَأَنَّ كُلَّ تَصَوُّرِ أَفْكَارِ قَلْبِهِ إِنَّمَا هُوَ شِرِّيرٌ كُلَّ يَوْمٍ.', 'تكوين 6:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 6, 'فَحَزِنَ الرَّبُّ أَنَّهُ عَمِلَ الْإِنْسَانَ فِي الْأَرْضِ، وَتَأَسَّفَ فِي قَلْبِهِ.', 'تكوين 6:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 7, 'فَقَالَ الرَّبُّ׃ «أَمْحُو عَنْ وَجْهِ الْأَرْضِ الْإِنْسَانَ الَّذِي خَلَقْتُهُ، الْإِنْسَانَ مَعَ بَهَائِمَ وَدَبَّابَاتٍ وَطُيُورِ السَّمَاءِ، لِأَنِّي حَزِنْتُ أَنِّي عَمِلْتُهُمْ».', 'تكوين 6:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 8, 'وَأَمَّا نُوحٌ فَوَجَدَ نِعْمَةً فِي عَيْنَيِ الرَّبِّ.', 'تكوين 6:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 9, 'هَذِهِ مَوَالِيدُ نُوحٍ׃ كَانَ نُوحٌ رَجُلًا بَارًّا كَامِلًا فِي أَجْيَالِهِ. وَسَارَ نُوحٌ مَعَ اللهِ.', 'تكوين 6:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 10, 'وَوَلَدَ نُوحٌ ثَلَاثَةَ بَنِينَ׃ سَامًا، وَحَامًا، وَيَافَثَ.', 'تكوين 6:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 11, 'وَفَسَدَتِ الْأَرْضُ أَمَامَ اللهِ، وَامْتَلَأَتِ الْأَرْضُ ظُلْمًا.', 'تكوين 6:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 12, 'وَرَأَى اللهُ الْأَرْضَ فَإِذَا هِيَ قَدْ فَسَدَتْ، إِذْ كَانَ كُلُّ بَشَرٍ قَدْ أَفْسَدَ طَرِيقَهُ عَلَى الْأَرْضِ.', 'تكوين 6:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 13, 'فَقَالَ اللهُ لِنُوحٍ׃ «نِهَايَةُ كُلِّ بَشَرٍ قَدْ أَتَتْ أَمَامِي، لِأَنَّ الْأَرْضَ امْتَلَأَتْ ظُلْمًا مِنْهُمْ. فَهَا أَنَا مُهْلِكُهُمْ مَعَ الْأَرْضِ.', 'تكوين 6:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 14, 'اِصْنَعْ لِنَفْسِكَ فُلْكًا مِنْ خَشَبِ جُفْرٍ. تَجْعَلُ الْفُلْكَ مَسَاكِنَ، وَتَطْلِيهِ مِنْ دَاخِلٍ وَمِنْ خَارِجٍ بِالْقَارِ.', 'تكوين 6:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 15, 'وَهَكَذَا تَصْنَعُهُ׃ ثَلَاثَ مِئَةِ ذِرَاعٍ يَكُونُ طُولُ الْفُلْكِ، وَخَمْسِينَ ذِرَاعًا عَرْضُهُ، وَثَلَاثِينَ ذِرَاعًا ارْتِفَاعُهُ.', 'تكوين 6:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 16, 'وَتَصْنَعُ كَوًّا لِلْفُلْكِ، وَتُكَمِّلُهُ إِلَى حَدِّ ذِرَاعٍ مِنْ فَوْقُ. وَتَضَعُ بَابَ الْفُلْكِ فِي جَانِبِهِ. مَسَاكِنَ سُفْلِيَّةً وَمُتَوَسِّطَةً وَعُلْوِيَّةً تَجْعَلُهُ.', 'تكوين 6:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 17, 'فَهَا أَنَا آتٍ بِطُوفَانِ الْمَاءِ عَلَى الْأَرْضِ لِأُهْلِكَ كُلَّ جَسَدٍ فِيهِ رُوحُ حَيَاةٍ مِنْ تَحْتِ السَّمَاءِ. كُلُّ مَا فِي الْأَرْضِ يَمُوتُ.', 'تكوين 6:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 18, 'وَلَكِنْ أُقِيمُ عَهْدِي مَعَكَ، فَتَدْخُلُ الْفُلْكَ أَنْتَ وَبَنُوكَ وَامْرَأَتُكَ وَنِسَاءُ بَنِيكَ مَعَكَ.', 'تكوين 6:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 19, 'وَمِنْ كُلِّ حَيٍّ مِنْ كُلِّ ذِي جَسَدٍ، اثْنَيْنِ مِنْ كُلٍّ تُدْخِلُ إِلَى الْفُلْكِ لِاسْتِبْقَائِهَا مَعَكَ. تَكُونُ ذَكَرًا وَأُنْثَى.', 'تكوين 6:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 20, 'مِنَ الطُّيُورِ كَأَجْنَاسِهَا، وَمِنَ الْبَهَائِمِ كَأَجْنَاسِهَا، وَمِنْ كُلِّ دَبَّابَاتِ الْأَرْضِ كَأَجْنَاسِهَا. اثْنَيْنِ مِنْ كُلٍّ تُدْخِلُ إِلَيْكَ لِاسْتِبْقَائِهَا.', 'تكوين 6:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 21, 'وَأَنْتَ، فَخُذْ لِنَفْسِكَ مِنْ كُلِّ طَعَامٍ يُؤْكَلُ وَاجْمَعْهُ عِنْدَكَ، فَيَكُونَ لَكَ وَلَهَا طَعَامًا».', 'تكوين 6:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 6, 22, 'فَفَعَلَ نُوحٌ حَسَبَ كُلِّ مَا أَمَرَهُ بِهِ اللهُ. هَكَذَا فَعَلَ.', 'تكوين 6:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 1, 'وَقَالَ الرَّبُّ لِنُوحٍ׃ «ادْخُلْ أَنْتَ وَجَمِيعُ بَيْتِكَ إِلَى الْفُلْكِ، لِأَنِّي إِيَّاكَ رَأَيْتُ بَارًّا لَدَيَّ فِي هَذَا الْجِيلِ.', 'تكوين 7:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 2, 'مِنْ جَمِيعِ الْبَهَائِمِ الطَّاهِرَةِ تَأْخُذُ مَعَكَ سَبْعَةً سَبْعَةً ذَكَرًا وَأُنْثَى. وَمِنَ الْبَهَائِمِ الَّتِي لَيْسَتْ بِطَاهِرَةٍ اثْنَيْنِ׃ ذَكَرًا وَأُنْثَى.', 'تكوين 7:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 3, 'وَمِنْ طُيُورِ السَّمَاءِ أَيْضًا سَبْعَةً سَبْعَةً׃ ذَكَرًا وَأُنْثَى. لِاسْتِبْقَاءِ نَسْلٍ عَلَى وَجْهِ كُلِّ الْأَرْضِ.', 'تكوين 7:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 4, 'لِأَنِّي بَعْدَ سَبْعَةِ أَيَّامٍ أَيْضًا أُمْطِرُ عَلَى الْأَرْضِ أَرْبَعِينَ يَوْمًا وَأَرْبَعِينَ لَيْلَةً. وَأَمْحُو عَنْ وَجْهِ الْأَرْضِ كُلَّ قَائِمٍ عَمِلْتُهُ».', 'تكوين 7:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 5, 'فَفَعَلَ نُوحٌ حَسَبَ كُلِّ مَا أَمَرَهُ بِهِ الرَّبُّ.', 'تكوين 7:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 6, 'وَلَمَّا كَانَ نُوحٌ ابْنَ سِتِّ مِئَةِ سَنَةٍ صَارَ طُوفَانُ الْمَاءِ عَلَى الْأَرْضِ،', 'تكوين 7:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 7, 'فَدَخَلَ نُوحٌ وَبَنُوهُ وَامْرَأَتُهُ وَنِسَاءُ بَنِيهِ مَعَهُ إِلَى الْفُلْكِ مِنْ وَجْهِ مِيَاهِ الطُّوفَانِ.', 'تكوين 7:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 8, 'وَمِنَ الْبَهَائِمِ الطَّاهِرَةِ وَالْبَهَائِمِ الَّتِي لَيْسَتْ بِطَاهِرَةٍ، وَمِنَ الطُّيُورِ وَكُلِّ مَا يَدِبُّ عَلَى الْأَرْضِ׃', 'تكوين 7:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 9, 'دَخَلَ اثْنَانِ اثْنَانِ إِلَى نُوحٍ إِلَى الْفُلْكِ، ذَكَرًا وَأُنْثَى، كَمَا أَمَرَ اللهُ نُوحًا.', 'تكوين 7:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 10, 'وَحَدَثَ بَعْدَ السَّبْعَةِ الْأَيَّامِ أَنَّ مِيَاهَ الطُّوفَانِ صَارَتْ عَلَى الْأَرْضِ.', 'تكوين 7:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 11, 'فِي سَنَةِ سِتِّ مِئَةٍ مِنْ حَيَاةِ نُوحٍ، فِي الشَّهْرِ الثَّانِي، فِي الْيَوْمِ السَّابِعَ عَشَرَ مِنَ الشَّهْرِ فِي ذَلِكَ اليَوْمِ، انْفَجَرَتْ كُلُّ يَنَابِيعِ الْغَمْرِ الْعَظِيمِ، وَانْفَتَحَتْ طَاقَاتُ السَّمَاءِ.', 'تكوين 7:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 12, 'وَكَانَ الْمَطَرُ عَلَى الْأَرْضِ أَرْبَعِينَ يَوْمًا وَأَرْبَعِينَ لَيْلَةً.', 'تكوين 7:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 13, 'فِي ذَلِكَ الْيَوْمِ عَيْنِهِ دَخَلَ نُوحٌ، وَسَامٌ وَحَامٌ وَيَافَثُ بَنُو نُوحٍ، وَامْرَأَةُ نُوحٍ، وَثَلَاثُ نِسَاءِ بَنِيهِ مَعَهُمْ إِلَى الْفُلْكِ.', 'تكوين 7:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 14, 'هُمْ وَكُلُّ الْوُحُوشِ كَأَجْنَاسِهَا، وَكُلُّ الْبَهَائِمِ كَأَجْنَاسِهَا، وَكُلُّ الدَّبَّاباتِ الَّتِي تَدِبُّ عَلَى الْأَرْضِ كَأَجْنَاسِهَا، وَكُلُّ الطُّيُورِ كَأَجْنَاسِهَا׃ كُلُّ عُصْفُورٍ، كُلُّ ذِي جَنَاحٍ.', 'تكوين 7:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 15, 'وَدَخَلَتْ إِلَى نُوحٍ إِلَى الْفُلْكِ، اثْنَيْنِ اثْنَيْنِ مِنْ كُلِّ جَسَدٍ فِيهِ رُوحُ حَيَاةٍ.', 'تكوين 7:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 16, 'وَالدَّاخِلَاتُ دَخَلَتْ ذَكَرًا وَأُنْثَى، مِنْ كُلِّ ذِي جَسَدٍ، كَمَا أَمَرَهُ اللهُ. وَأَغْلَقَ الرَّبُّ عَلَيْهِ.', 'تكوين 7:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 17, 'وَكَانَ الطُّوفَانُ أَرْبَعِينَ يَوْمًا عَلَى الْأَرْضِ. وَتَكَاثَرَتِ الْمِيَاهُ وَرَفَعَتِ الْفُلْكَ، فَارْتَفَعَ عَنِ الْأَرْضِ.', 'تكوين 7:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 18, 'وَتَعَاظَمَتِ الْمِيَاهُ وَتَكَاثَرَتْ جِدًّا عَلَى الْأَرْضِ، فَكَانَ الْفُلْكُ يَسِيرُ عَلَى وَجْهِ الْمِيَاهِ.', 'تكوين 7:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 19, 'وَتَعَاظَمَتِ الْمِيَاهُ كَثِيرًا جِدًّا عَلَى الْأَرْضِ، فَتَغَطَّتْ جَمِيعُ الْجِبَالِ الشَّامِخَةِ الَّتِي تَحْتَ كُلِّ السَّمَاءِ.', 'تكوين 7:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 20, 'خَمْسَ عَشَرَةَ ذِرَاعًا فِي الِارْتِفَاعِ تَعَاظَمَتِ الْمِيَاهُ، فَتَغَطَّتِ الْجِبَالُ.', 'تكوين 7:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 21, 'فَمَاتَ كُلُّ ذِي جَسَدٍ كَانَ يَدِبُّ عَلَى الْأَرْضِ مِنَ الطُّيُورِ وَالْبَهَائِمِ وَالْوُحُوشِ، وَكُلُّ الزَّحَّافَاتِ الَّتِي كَانَتْ تَزْحَفُ عَلَى الْأَرْضِ، وَجَمِيعُ النَّاسِ.', 'تكوين 7:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 22, 'كُلُّ مَا فِي أَنْفِهِ نَسَمَةُ رُوحِ حَيَاةٍ مِنْ كُلِّ مَا فِي الْيَابِسَةِ مَاتَ.', 'تكوين 7:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 23, 'فَمَحَا اللهُ كُلَّ قَائِمٍ كَانَ عَلَى وَجْهِ الْأَرْضِ׃ النَّاسَ، وَالْبَهَائِمَ، وَالدَّبَّابَاتِ، وَطُيُورَ السَّمَاءِ. فَانْمَحَتْ مِنَ الْأَرْضِ. وَتَبَقَّى نُوحٌ وَالَّذِينَ مَعَهُ فِي الْفُلْكِ فَقَطْ.', 'تكوين 7:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 7, 24, 'وَتَعَاظَمَتِ الْمِيَاهُ عَلَى الْأَرْضِ مِئَةً وَخَمْسِينَ يَوْمًا.', 'تكوين 7:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 1, 'ثُمَّ ذَكَرَ اللهُ نُوحًا وَكُلَّ الْوُحُوشِ وَكُلَّ الْبَهَائِمِ الَّتِي مَعَهُ فِي الْفُلْكِ. وَأَجَازَ اللهُ رِيحًا عَلَى الْأَرْضِ فَهَدَأَتِ الْمِيَاهُ.', 'تكوين 8:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 2, 'وَانْسَدَّتْ يَنَابِيعُ الْغَمْرِ وَطَاقَاتُ السَّمَاءِ، فَامْتَنَعَ الْمَطَرُ مِنَ السَّمَاءِ.', 'تكوين 8:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 3, 'وَرَجَعَتِ الْمِيَاهُ عَنِ الْأَرْضِ رُجُوعًا مُتَوَالِيًا. وَبَعْدَ مِئَةٍ وَخَمْسِينَ يَوْمًا نَقَصَتِ الْمِيَاهُ،', 'تكوين 8:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 4, 'وَاسْتَقَرَّ الْفُلْكُ فِي الشَّهْرِ السَّابِعِ، فِي الْيَوْمِ السَّابِعَ عَشَرَ مِنَ الشَّهْرِ، عَلَى جِبَالِ أَرَارَاطَ.', 'تكوين 8:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 5, 'وَكَانَتِ الْمِيَاهُ تَنْقُصُ نَقْصًا مُتَوَالِيًا إِلَى الشَّهْرِ الْعَاشِرِ. وَفِي الْعَاشِرِ فِي أَوَّلِ الشَّهْرِ، ظَهَرَتْ رُؤُوسُ الْجِبَالِ.', 'تكوين 8:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 6, 'وَحَدَثَ مِنْ بَعْدِ أَرْبَعِينَ يَوْمًا أَنَّ نُوحًا فَتَحَ طَاقَةَ الْفُلْكِ الَّتِي كَانَ قَدْ عَمِلَهَا', 'تكوين 8:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 7, 'وَأَرْسَلَ الْغُرَابَ، فَخَرَجَ مُتَرَدِّدًا حَتَّى نَشِفَتِ الْمِيَاهُ عَنِ الْأَرْضِ.', 'تكوين 8:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 8, 'ثُمَّ أَرْسَلَ الْحَمَامَةَ مِنْ عِنْدِهِ لِيَرَى هَلْ قَلَّتِ الْمِيَاهُ عَنْ وَجْهِ الْأَرْضِ،', 'تكوين 8:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 9, 'فَلَمْ تَجِدِ الْحَمَامَةُ مَقَرًّا لِرِجْلِهَا، فَرَجَعَتْ إِلَيْهِ إِلَى الْفُلْكِ لِأَنَّ مِيَاهًا كَانَتْ عَلَى وَجْهِ كُلِّ الْأَرْضِ. فَمَدَّ يَدَهُ وَأَخَذَهَا وَأَدْخَلَهَا عِنْدَهُ إِلَى الْفُلْكِ.', 'تكوين 8:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 10, 'فَلَبِثَ أَيْضًا سَبْعَةَ أَيَّامٍ أُخَرَ وَعَادَ فَأَرْسَلَ الْحَمَامَةَ مِنَ الْفُلْكِ،', 'تكوين 8:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 11, 'فَأَتَتْ إِلَيْهِ الْحَمَامَةُ عِنْدَ الْمَسَاءِ، وَإِذَا وَرَقَةُ زَيْتُونٍ خَضْرَاءُ فِي فَمِهَا. فَعَلِمَ نُوحٌ أَنَّ الْمِيَاهَ قَدْ قَلَّتْ عَنِ الْأَرْضِ.', 'تكوين 8:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 12, 'فَلَبِثَ أَيْضًا سَبْعَةَ أَيَّامٍ أُخَرَ وَأَرْسَلَ الْحَمَامَةَ فَلَمْ تَعُدْ تَرْجِعُ إِلَيْهِ أَيْضًا.', 'تكوين 8:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 13, 'وَكَانَ فِي السَّنَةِ الْوَاحِدَةِ وَالسِّتِّ مِئَةٍ، فِي الشَّهْرِ الْأَوَّلِ فِي أَوَّلِ الشَّهْرِ، أَنَّ الْمِيَاهَ نَشِفَتْ عَنِ الْأَرْضِ. فَكَشَفَ نُوحٌ الْغِطَاءَ عَنِ الْفُلْكِ وَنَظَرَ، فَإِذَا وَجْهُ الْأَرْضِ قَدْ نَشِفَ.', 'تكوين 8:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 14, 'وَفِي الشَّهْرِ الثَّانِي، فِي الْيَوْمِ السَّابِعِ وَالْعِشْرِينَ مِنَ الشَّهْرِ، جَفَّتِ الْأَرْضُ.', 'تكوين 8:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 15, 'وَكَلَّمَ اللهُ نُوحًا قَائِلًا׃', 'تكوين 8:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 16, '«اخْرُجْ مِنَ الْفُلْكِ أَنْتَ وَامْرَأَتُكَ وَبَنُوكَ وَنِسَاءُ بَنِيكَ مَعَكَ.', 'تكوين 8:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 17, 'وَكُلَّ الْحَيَوَانَاتِ الَّتِي مَعَكَ مِنْ كُلِّ ذِي جَسَدٍ׃ الطُّيُورِ، وَالْبَهَائِمِ، وَكُلَّ الدَّبَّابَاتِ الَّتِي تَدِبُّ عَلَى الْأَرْضِ، أَخْرِجْهَا مَعَكَ. وَلْتَتَوَالَدْ فِي الْأَرْضِ وَتُثْمِرْ وَتَكْثُرْ عَلَى الْأَرْضِ».', 'تكوين 8:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 18, 'فَخَرَجَ نُوحٌ وَبَنُوهُ وَامْرَأَتُهُ وَنِسَاءُ بَنِيهِ مَعَهُ.', 'تكوين 8:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 19, 'وَكُلُّ الْحَيَوَانَاتِ، كُلُّ الدَّبَّابَاتِ، وَكُلُّ الطُّيُورِ، كُلُّ مَا يَدِبُّ عَلَى الْأَرْضِ، كَأَنْوَاعِهَا خَرَجَتْ مِنَ الْفُلْكِ.', 'تكوين 8:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 20, 'وَبَنَى نُوحٌ مَذْبَحًا لِلرَّبِّ. وَأَخَذَ مِنْ كُلِّ الْبَهَائِمِ الطَّاهِرَةِ وَمِنْ كُلِّ الطُّيُورِ الطَّاهِرَةِ وَأَصْعَدَ مُحْرَقَاتٍ عَلَى الْمَذْبَحِ،', 'تكوين 8:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 21, 'فَتَنَسَّمَ الرَّبُّ رَائِحَةَ الرِّضَا. وَقَالَ الرَّبُّ فِي قَلْبِهِ׃ «لَا أَعُودُ أَلْعَنُ الْأَرْضَ أَيْضًا مِنْ أَجْلِ الْإِنْسَانِ، لِأَنَّ تَصَوُّرَ قَلْبِ الْإِنْسَانِ شِرِّيرٌ مُنْذُ حَدَاثَتِهِ. وَلَا أَعُودُ أَيْضًا أُمِيتُ كُلَّ حَيٍّ كَمَا فَعَلْتُ.', 'تكوين 8:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 8, 22, 'مُدَّةَ كُلِّ أَيَّامِ الْأَرْضِ׃ زَرْعٌ وَحَصَادٌ، وَبَرْدٌ وَحَرٌّ، وَصَيْفٌ وَشِتَاءٌ، وَنَهَارٌ وَلَيْلٌ، لَا تَزَالُ».', 'تكوين 8:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 1, 'وَبَارَكَ اللهُ نُوحًا وَبَنِيهِ وَقَالَ لَهُمْ׃ «أَثْمِرُوا وَاكْثُرُوا وَامْلَأُوا الْأَرْضَ.', 'تكوين 9:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 2, 'وَلْتَكُنْ خَشْيَتُكُمْ وَرَهْبَتُكُمْ عَلَى كُلِّ حَيَوَانَاتِ الْأَرْضِ وَكُلِّ طُيُورِ السَّمَاءِ، مَعَ كُلِّ مَا يَدِبُّ عَلَى الْأَرْضِ، وَكُلِّ أَسْمَاكِ الْبَحْرِ. قَدْ دُفِعَتْ إِلَى أَيْدِيكُمْ.', 'تكوين 9:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 3, 'كُلُّ دَابَّةٍ حَيَّةٍ تَكُونُ لَكُمْ طَعَامًا. كَالْعُشْبِ الْأَخْضَرِ دَفَعْتُ إِلَيْكُمُ الْجَمِيعَ.', 'تكوين 9:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 4, 'غَيْرَ أَنَّ لَحْمًا بِحَيَاتِهِ، دَمِهِ، لَا تَأْكُلُوهُ.', 'تكوين 9:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 5, 'وَأَطْلُبُ أَنَا دَمَكُمْ لِأَنْفُسِكُمْ فَقَطْ. مِنْ يَدِ كُلِّ حَيَوَانٍ أَطْلُبُهُ. وَمِنْ يَدِ الْإِنْسَانِ أَطْلُبُ نَفْسَ الْإِنْسَانِ، مِنْ يَدِ الْإِنْسَانِ أَخِيهِ.', 'تكوين 9:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 6, 'سَافِكُ دَمِ الْإِنْسَانِ بِالْإِنْسَانِ يُسْفَكُ دَمُهُ. لِأَنَّ اللهَ عَلَى صُورَتِهِ عَمِلَ الْإِنْسَانَ.', 'تكوين 9:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 7, 'فَأَثْمِرُوا أَنْتُمْ وَاكْثُرُوا وَتَوَالَدُوا فِي الْأَرْضِ وَتَكَاثَرُوا فِيهَا».', 'تكوين 9:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 8, 'وَكَلَّمَ اللهُ نُوحًا وَبَنِيهِ مَعهُ قَائِلًا׃', 'تكوين 9:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 9, '«وَهَا أَنَا مُقِيمٌ مِيثَاقِي مَعَكُمْ وَمَعَ نَسْلِكُمْ مِنْ بَعْدِكُمْ،', 'تكوين 9:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 10, 'وَمَعَ كُلِّ ذَوَاتِ الْأَنْفُسِ الْحَيَّةِ الَّتِي مَعَكُمْ׃ الطُّيُورِ وَالْبَهَائِمِ وَكُلِّ وُحُوشِ الْأَرْضِ الَّتِي مَعَكُمْ، مِنْ جَمِيعِ الْخَارِجِينَ مِنَ الْفُلْكِ حَتَّى كُلُّ حَيَوَانِ الْأَرْضِ.', 'تكوين 9:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 11, 'أُقِيمُ مِيثَاقِي مَعَكُمْ فَلَا يَنْقَرِضُ كُلُّ ذِي جَسَدٍ أَيْضًا بِمِيَاهِ الطُّوفَانِ. وَلَا يَكُونُ أَيْضًا طُوفَانٌ لِيُخْرِبَ الْأَرْضَ».', 'تكوين 9:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 12, 'وَقَالَ اللهُ׃ «هَذِهِ عَلَامَةُ الْمِيثَاقِ الَّذِي أَنَا وَاضِعُهُ بَيْنِي وَبَيْنَكُمْ، وَبَيْنَ كُلِّ ذَوَاتِ الْأَنْفُسِ الْحَيَّةِ الَّتِي مَعَكُمْ إِلَى أَجْيَالِ الدَّهْرِ׃', 'تكوين 9:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 13, 'وَضَعْتُ قَوْسِي فِي السَّحَابِ فَتَكُونُ عَلَامَةَ مِيثَاقٍ بَيْنِي وَبَيْنَ الْأَرْضِ.', 'تكوين 9:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 14, 'فَيَكُونُ مَتَى أَنْشُرْ سَحَابًا عَلَى الْأَرْضِ، وَتَظْهَرِ الْقَوْسُ فِي السَّحَابِ،', 'تكوين 9:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 15, 'أَنِّي أَذْكُرُ مِيثَاقِي الَّذِي بَيْنِي وَبَيْنَكُمْ وَبَيْنَ كُلِّ نَفْسٍ حَيَّةٍ فِي كُلِّ جَسَدٍ. فَلَا تَكُونُ أَيْضًا الْمِيَاهُ طُوفَانًا لِتُهْلِكَ كُلَّ ذِي جَسَدٍ.', 'تكوين 9:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 16, 'فَمَتَى كَانَتِ الْقَوْسُ فِي السَّحَابِ، أُبْصِرُهَا لِأَذْكُرَ مِيثَاقًا أَبَدِيًّا بَيْنَ اللهِ وَبَيْنَ كُلِّ نَفْسٍ حَيَّةٍ فِي كُلِّ جَسَدٍ عَلَى الْأَرْضِ».', 'تكوين 9:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 17, 'وَقَالَ اللهُ لِنُوحٍ׃ «هَذِهِ عَلَامَةُ الْمِيثَاقِ الَّذِي أَنَا أَقَمْتُهُ بَيْنِي وَبَيْنَ كُلِّ ذِي جَسَدٍ عَلَى الْأَرْضِ».', 'تكوين 9:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 18, 'وَكَانَ بَنُو نُوحٍ الَّذِينَ خَرَجُوا مِنَ الْفُلْكِ سَامًا وَحَامًا وَيَافَثَ. وَحَامٌ هُوَ أَبُو كَنْعَانَ.', 'تكوين 9:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 19, 'هَؤُلَاءِ الثَّلَاثَةُ هُمْ بَنُو نُوحٍ. وَمِنْ هَؤُلَاءِ تَشَعَّبَتْ كُلُّ الْأَرْضِ.', 'تكوين 9:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 20, 'وَابْتَدَأَ نُوحٌ يَكُونُ فَلَّاحًا وَغَرَسَ كَرْمًا.', 'تكوين 9:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 21, 'وَشَرِبَ مِنَ الْخَمْرِ فَسَكِرَ وَتَعَرَّى دَاخِلَ خِبَائِهِ.', 'تكوين 9:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 22, 'فَأَبْصَرَ حَامٌ أَبُو كَنْعَانَ عَوْرَةَ أَبِيهِ، وَأَخْبَرَ أَخَوَيْهِ خَارِجًا.', 'تكوين 9:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 23, 'فَأَخَذَ سَامٌ وَيَافَثُ الرِّدَاءَ وَوَضَعَاهُ عَلَى أَكْتَافِهِمَا وَمَشَيَا إِلَى الْوَرَاءِ، وَسَتَرَا عَوْرَةَ أَبِيهِمَا وَوَجْهَاهُمَا إِلَى الْوَرَاءِ. فَلَمْ يُبْصِرَا عَوْرَةَ أَبِيهِمَا.', 'تكوين 9:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 24, 'فَلَمَّا اسْتَيْقَظَ نُوحٌ مِنْ خَمْرِهِ، عَلِمَ مَا فَعَلَ بِهِ ابْنُهُ الصَّغِيرُ،', 'تكوين 9:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 25, 'فَقَالَ׃ «مَلْعُونٌ كَنْعَانُ! عَبْدَ الْعَبِيدِ يَكُونُ لإِخْوَتِهِ».', 'تكوين 9:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 26, 'وَقَالَ׃ «مُبَارَكٌ الرَّبُّ إِلَهُ سَامٍ. وَلْيَكُنْ كَنْعَانُ عَبْدًا لَهُمْ.', 'تكوين 9:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 27, 'لِيَفْتَحِ اللهُ لِيَافَثَ فَيَسْكُنَ فِي مَسَاكِنِ سَامٍ، وَلْيَكُنْ كَنْعَانُ عَبْدًا لَهُمْ».', 'تكوين 9:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 28, 'وَعَاشَ نُوحٌ بَعْدَ الطُّوفَانِ ثَلَاثَ مِئَةٍ وَخَمْسِينَ سَنَةً.', 'تكوين 9:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 9, 29, 'فَكَانَتْ كُلُّ أَيَّامِ نُوحٍ تِسْعَ مِئَةٍ وَخَمْسِينَ سَنَةً، وَمَاتَ.', 'تكوين 9:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 1, 'وَهَذِهِ مَوَالِيدُ بَنِي نُوحٍ׃ سَامٌ وَحَامٌ وَيَافَثُ. وَوُلِدَ لَهُمْ بَنُونَ بَعْدَ الطُّوفَانِ.', 'تكوين 10:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 2, 'بَنُو يَافَثَ׃ جُومَرُ وَمَاجُوجُ وَمَادَاي وَيَاوَانُ وَتُوبَالُ وَمَاشِكُ وَتِيرَاسُ.', 'تكوين 10:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 3, 'وَبَنُو جُومَرَ׃ أَشْكَنَازُ وَرِيفَاثُ وَتُوجَرْمَةُ.', 'تكوين 10:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 4, 'وَبَنُو يَاوَانَ׃ أَلِيشَةُ وَتَرْشِيشُ وَكِتِّيمُ وَدُودَانِيمُ.', 'تكوين 10:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 5, 'مِنْ هَؤُلَاءِ تَفَرَّقَتْ جَزَائِرُ الْأُمَمِ بِأَرَاضِيهِمْ، كُلُّ إِنْسَانٍ كَلِسَانِهِ حَسَبَ قَبَائِلِهِمْ بِأُمَمِهِمْ.', 'تكوين 10:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 6, 'وَبَنُو حَامٍ׃ كُوشُ وَمِصْرَايِمُ وَفُوطُ وَكَنْعَانُ.', 'تكوين 10:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 7, 'وَبَنُو كُوشَ׃ سَبَا وَحَوِيلَةُ وَسَبْتَةُ وَرَعْمَةُ وَسَبْتَكَا. وَبَنُو رَعْمَةَ׃ شَبَا وَدَدَانُ.', 'تكوين 10:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 8, 'وَكُوشُ وَلَدَ نِمْرُودَ الَّذِي ابْتَدَأَ يَكُونُ جَبَّارًا فِي الْأَرْضِ،', 'تكوين 10:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 9, 'الَّذِي كَانَ جَبَّارَ صَيْدٍ أَمَامَ الرَّبِّ. لِذَلِكَ يُقَالُ׃ «كَنِمْرُودَ جَبَّارُ صَيْدٍ أَمَامَ الرَّبِّ».', 'تكوين 10:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 10, 'وَكَانَ ابْتِدَاءُ مَمْلَكَتِهِ بَابِلَ وَأَرَكَ وَأَكَّدَ وَكَلْنَةَ، فِي أَرْضِ شِنْعَارَ.', 'تكوين 10:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 11, 'مِنْ تِلْكَ الْأَرْضِ خَرَجَ أَشُّورُ وَبَنَى نِينَوَى وَرَحُوبُوتَ عَيْرَ وَكَالَحَ', 'تكوين 10:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 12, 'وَرَسَنَ، بَيْنَ نِينَوَى وَكَالَحَ، هِيَ الْمَدِينَةُ الْكَبِيرَةُ.', 'تكوين 10:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 13, 'وَمِصْرَايِمُ وَلَدَ׃ لُودِيمَ وَعَنَامِيمَ وَلَهَابِيمَ وَنَفْتُوحِيمَ', 'تكوين 10:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 14, 'وَفَتْرُوسِيمَ وَكَسْلُوحِيمَ. الَّذِينَ خَرَجَ مِنْهُمْ فِلِشْتِيمُ وَكَفْتُورِيمُ.', 'تكوين 10:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 15, 'وَكَنْعَانُ وَلَدَ׃ صِيْدُونَ بِكْرَهُ، وَحِثًّا', 'تكوين 10:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 16, 'وَالْيَبُوسِيَّ وَالْأَمُورِيَّ وَالْجِرْجَاشِيَّ', 'تكوين 10:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 17, 'وَالْحِوِّيَّ وَالْعَرْقِيَّ وَالسِّينِيَّ', 'تكوين 10:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 18, 'وَالْأَرْوَادِيَّ وَالصَّمَارِيَّ وَالْحَمَاتِيَّ. وَبَعْدَ ذَلِكَ تَفَرَّقَتْ قَبَائِلُ الْكَنْعَانِيِّ.', 'تكوين 10:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 19, 'وَكَانَتْ تُخُومُ الْكَنْعَانِيِّ مِنْ صَيْدُونَ، حِينَمَا تَجِيءُ نَحْوَ جَرَارَ إِلَى غَزَّةَ، وَحِينَمَا تَجِيءُ نَحْوَ سَدُومَ وَعَمُورَةَ وَأَدْمَةَ وَصَبُويِيمَ إِلَى لَاشَعَ.', 'تكوين 10:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 20, 'هَؤُلَاءِ بَنُو حَامٍ حَسَبَ قَبَائِلِهِمْ كَأَلْسِنَتِهِمْ بِأَرَاضِيهِمْ وَأُمَمِهِمْ.', 'تكوين 10:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 21, 'وَسَامٌ أَبُو كُلِّ بَنِي عَابِرَ، أَخُو يَافَثَ الْكَبِيرُ، وُلِدَ لَهُ أَيْضًا بَنُونَ.', 'تكوين 10:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 22, 'بَنُو سَامٍ׃ عِيلَامُ وَأَشُّورُ وَأَرْفَكْشَادُ وَلُودُ وَأَرَامُ.', 'تكوين 10:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 23, 'وَبَنُو أَرَامَ׃ عُوصُ وَحُولُ وَجَاثَرُ وَمَاشُ.', 'تكوين 10:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 24, 'وَأَرْفَكْشَادُ وَلَدَ شَالَحَ، وَشَالَحُ وَلَدَ عَابِرَ.', 'تكوين 10:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 25, 'وَلِعَابِرَ وُلِدَ ابْنَانِ׃ اسْمُ الْوَاحِدِ فَالَجُ لِأَنَّ فِي أَيَّامِهِ قُسِمَتِ الْأَرْضُ. وَاسْمُ أَخِيهِ يَقْطَانُ.', 'تكوين 10:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 26, 'وَيَقْطَانُ وَلَدَ׃ أَلْمُودَادَ وَشَالَفَ وَحَضَرْمَوْتَ وَيَارَحَ', 'تكوين 10:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 27, 'وَهَدُورَامَ وَأُوزَالَ وَدِقْلَةَ', 'تكوين 10:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 28, 'وَعُوبَالَ وَأَبِيمَايِلَ وَشَبَا', 'تكوين 10:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 29, 'وَأُوفِيرَ وَحَوِيلَةَ وَيُوبَابَ. جَمِيعُ هَؤُلَاءِ بَنُو يَقْطَانَ.', 'تكوين 10:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 30, 'وَكَانَ مَسْكَنُهُمْ مِنْ مِيشَا حِينَمَا تَجِيءُ نَحْوَ سَفَارَ جَبَلِ الْمَشْرِقِ.', 'تكوين 10:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 31, 'هَؤُلَاءِ بَنُو سَامٍ حَسَبَ قَبَائِلِهِمْ كَأَلْسِنَتِهِمْ بِأَرَاضِيهِمْ حَسَبَ أُمَمِهِمْ.', 'تكوين 10:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 10, 32, 'هَؤُلَاءِ قَبَائِلُ بَنِي نُوحٍ حَسَبَ مَوَالِيدِهِمْ بِأُمَمِهِمْ. وَمِنْ هَؤُلَاءِ تَفَرَّقَتِ الْأُمَمُ فِي الْأَرْضِ بَعْدَ الطُّوفَانِ.', 'تكوين 10:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 1, 'وَكَانَتِ الْأَرْضُ كُلُّهَا لِسَانًا وَاحِدًا وَلُغَةً وَاحِدَةً.', 'تكوين 11:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 2, 'وَحَدَثَ فِي ارْتِحَالِهِمْ شَرْقًا أَنَّهُمْ وَجَدُوا بُقْعَةً فِي أَرْضِ شِنْعَارَ وَسَكَنُوا هُنَاكَ.', 'تكوين 11:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 3, 'وَقَالَ بَعْضُهُمْ لِبَعْضٍ׃ «هَلُمَّ نَصْنَعُ لِبْنًا وَنَشْوِيهِ شَيًّا». فَكَانَ لَهُمُ اللِّبْنُ مَكَانَ الْحَجَرِ، وَكَانَ لَهُمُ الْحُمَرُ مَكَانَ الطِّينِ.', 'تكوين 11:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 4, 'وَقَالُوا׃ «هَلُمَّ نَبْنِ لِأَنْفُسِنَا مَدِينَةً وَبُرْجًا رَأْسُهُ بِالسَّمَاءِ. وَنَصْنَعُ لِأَنْفُسِنَا اسْمًا لِئَلَّا نَتَبَدَّدَ عَلَى وَجْهِ كُلِّ الْأَرْضِ».', 'تكوين 11:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 5, 'فَنَزَلَ الرَّبُّ لِيَنْظُرَ الْمَدِينَةَ وَالْبُرْجَ اللَّذَيْنِ كَانَ بَنُو آدَمَ يَبْنُونَهُمَا.', 'تكوين 11:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 6, 'وَقَالَ الرَّبُّ׃ «هُوَذَا شَعْبٌ وَاحِدٌ وَلِسَانٌ وَاحِدٌ لِجَمِيعِهِمْ، وَهَذَا ابْتِدَاؤُهُمْ بِالْعَمَلِ. وَالْآنَ لَا يَمْتَنِعُ عَلَيْهِمْ كُلُّ مَا يَنْوُونَ أَنْ يَعْمَلُوهُ.', 'تكوين 11:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 7, 'هَلُمَّ نَنْزِلْ وَنُبَلْبِلْ هُنَاكَ لِسَانَهُمْ حَتَّى لَا يَسْمَعَ بَعْضُهُمْ لِسَانَ بَعْضٍ».', 'تكوين 11:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 8, 'فَبَدَّدَهُمُ الرَّبُّ مِنْ هُنَاكَ عَلَى وَجْهِ كُلِّ الْأَرْضِ، فَكَفُّوا عَنْ بُنْيَانِ الْمَدِينَةِ،', 'تكوين 11:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 9, 'لِذَلِكَ دُعِيَ اسْمُهَا «بَابِلَ» لِأَنَّ الرَّبَّ هُنَاكَ بَلْبَلَ لِسَانَ كُلِّ الْأَرْضِ. وَمِنْ هُنَاكَ بَدَّدَهُمُ الرَّبُّ عَلَى وَجْهِ كُلِّ الْأَرْضِ.', 'تكوين 11:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 10, 'هَذِهِ مَوَالِيدُ سَامٍ׃ لَمَّا كَانَ سَامٌ ابْنَ مِئَةِ سَنَةٍ وَلَدَ أَرْفَكْشَادَ، بَعْدَ الطُّوفَانِ بِسَنَتَيْنِ.', 'تكوين 11:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 11, 'وَعَاشَ سَامٌ بَعْدَ مَا وَلَدَ أَرْفَكْشَادَ خَمْسَ مِئَةِ سَنَةٍ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 12, 'وَعَاشَ أَرْفَكْشَادُ خَمْسًا وَثَلَاثِينَ سَنَةً وَوَلَدَ شَالَحَ.', 'تكوين 11:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 13, 'وَعَاشَ أَرْفَكْشَادُ بَعْدَ مَا وَلَدَ شَالَحَ أَرْبَعَ مِئَةٍ وَثَلَاثَ سِنِينَ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 14, 'وَعَاشَ شَالَحُ ثَلَاثِينَ سَنَةً وَوَلَدَ عَابِرَ.', 'تكوين 11:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 15, 'وَعَاشَ شَالَحُ بَعْدَ مَا وَلَدَ عَابِرَ أَرْبَعَ مِئَةٍ وَثَلَاثَ سِنِينَ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 16, 'وَعَاشَ عَابِرُ أَرْبَعًا وَثَلَاثِينَ سَنَةً وَوَلَدَ فَالَجَ.', 'تكوين 11:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 17, 'وَعَاشَ عَابِرُ بَعْدَ مَا وَلَدَ فَالَجَ أَرْبَعَ مِئَةٍ وَثَلَاثِينَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 18, 'وَعَاشَ فَالَجُ ثَلَاثِينَ سَنَةً وَوَلَدَ رَعُوَ.', 'تكوين 11:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 19, 'وَعَاشَ فَالَجُ بَعْدَ مَا وَلَدَ رَعُوَ مِئَتَيْنِ وَتِسْعَ سِنِينَ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 20, 'وَعَاشَ رَعُو اثْنَتَيْنِ وَثَلَاثِينَ سَنَةً وَوَلَدَ سَرُوجَ.', 'تكوين 11:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 21, 'وَعَاشَ رَعُو بَعْدَ مَا وَلَدَ سَرُوجَ مِئَتَيْنِ وَسَبْعَ سِنِينَ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 22, 'وَعَاشَ سَرُوجُ ثَلَاثِينَ سَنَةً وَوَلَدَ نَاحُورَ.', 'تكوين 11:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 23, 'وَعَاشَ سَرُوجُ بَعْدَ مَا وَلَدَ نَاحُورَ مِئَتَيْ سَنَةٍ، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 24, 'وَعَاشَ نَاحُورُ تِسْعًا وَعِشْرِينَ سَنَةً وَوَلَدَ تَارَحَ.', 'تكوين 11:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 25, 'وَعَاشَ نَاحُورُ بَعْدَ مَا وَلَدَ تَارَحَ مِئَةً وَتِسْعَ عَشَرَةَ سَنَةً، وَوَلَدَ بَنِينَ وَبَنَاتٍ.', 'تكوين 11:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 26, 'وَعَاشَ تَارَحُ سَبْعِينَ سَنَةً، وَوَلَدَ أَبْرَامَ وَنَاحُورَ وَهَارَانَ.', 'تكوين 11:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 27, 'وَهَذِهِ مَوَالِيدُ تَارَحَ׃ وَلَدَ تَارَحُ أَبْرَامَ وَنَاحُورَ وَهَارَانَ. وَوَلَدَ هَارَانُ لُوطًا.', 'تكوين 11:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 28, 'وَمَاتَ هَارَانُ قَبْلَ تَارَحَ أَبِيهِ فِي أَرْضِ مِيلَادِهِ فِي أُورِ الْكَلْدَانِيِّينَ.', 'تكوين 11:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 29, 'وَاتَّخَذَ أَبْرَامُ وَنَاحُورُ لِأَنْفُسِهِمَا امْرَأَتَيْنِ׃ اسْمُ امْرَأَةِ أَبْرَامَ سَارَايُ، وَاسْمُ امْرَأَةِ نَاحُورَ مِلْكَةُ بِنْتُ هَارَانَ، أَبِي مِلْكَةَ وَأَبِي يِسْكَةَ.', 'تكوين 11:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 30, 'وَكَانَتْ سَارَايُ عَاقِرًا لَيْسَ لَهَا وَلَدٌ.', 'تكوين 11:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 31, 'وَأَخَذَ تَارَحُ أَبْرَامَ ابْنَهُ، وَلُوطًا بْنَ هَارَانَ، ابْنَ ابْنِهِ، وَسَارَايَ كَنَّتَهُ امْرَأَةَ أَبْرَامَ ابْنِهِ، فَخَرَجُوا مَعًا مِنْ أُورِ الْكَلْدَانِيِّينَ لِيَذْهَبُوا إِلَى أَرْضِ كَنْعَانَ. فَأَتَوْا إِلَى حَارَانَ وَأَقَامُوا هُنَاكَ.', 'تكوين 11:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 11, 32, 'وَكَانَتْ أَيَّامُ تَارَحَ مِئَتَيْنِ وَخَمْسَ سِنِينَ. وَمَاتَ تَارَحُ فِي حَارَانَ.', 'تكوين 11:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 1, 'وَقَالَ الرَّبُّ لِأَبْرَامَ׃ «اذْهَبْ مِنْ أَرْضِكَ وَمِنْ عَشِيرَتِكَ وَمِنْ بَيْتِ أَبِيكَ إِلَى الْأَرْضِ الَّتِي أُرِيكَ.', 'تكوين 12:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 2, 'فَأَجْعَلَكَ أُمَّةً عَظِيمَةً وَأُبَارِكَكَ وَأُعَظِّمَ اسْمَكَ، وَتَكُونَ بَرَكَةً.', 'تكوين 12:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 3, 'وَأُبَارِكُ مُبَارِكِيكَ، وَلَاعِنَكَ أَلْعَنُهُ. وَتَتَبَارَكُ فِيكَ جَمِيعُ قَبَائِلِ الْأَرْضِ».', 'تكوين 12:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 4, 'فَذَهَبَ أَبْرَامُ كَمَا قَالَ لَهُ الرَّبُّ وَذَهَبَ مَعَهُ لُوطٌ. وَكَانَ أَبْرَامُ ابْنَ خَمْسٍ وَسَبْعِينَ سَنَةً لَمَّا خَرَجَ مِنْ حَارَانَ.', 'تكوين 12:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 5, 'فَأَخَذَ أَبْرَامُ سَارَايَ امْرَأَتَهُ، وَلُوطًا ابْنَ أَخِيهِ، وَكُلَّ مُقْتَنَيَاتِهِمَا الَّتِي اقْتَنَيَا وَالنُّفُوسَ الَّتِي امْتَلَكَا فِي حَارَانَ. وَخَرَجُوا لِيَذْهَبُوا إِلَى أَرْضِ كَنْعَانَ. فَأَتَوْا إِلَى أَرْضِ كَنْعَانَ.', 'تكوين 12:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 6, 'وَاجْتَازَ أَبْرَامُ فِي الْأَرْضِ إِلَى مَكَانِ شَكِيمَ إِلَى بَلُّوطَةِ مُورَةَ. وَكَانَ الْكَنْعَانِيُّونَ حِينَئِذٍ فِي الْأَرْضِ.', 'تكوين 12:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 7, 'وَظَهَرَ الرَّبُّ لِأَبْرَامَ وَقَالَ׃ «لِنَسْلِكَ أُعْطِي هَذِهِ الْأَرْضَ». فَبَنَى هُنَاكَ مَذْبَحًا لِلرَّبِّ الَّذِي ظَهَرَ لَهُ.', 'تكوين 12:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 8, 'ثُمَّ نَقَلَ مِنْ هُنَاكَ إِلَى الْجَبَلِ شَرْقِيَّ بَيْتِ إِيلٍ وَنَصَبَ خَيْمَتَهُ. وَلَهُ بَيْتُ إِيلَ مِنَ الْمَغْرِبِ وَعَايُ مِنَ الْمَشْرِقِ. فَبَنَى هُنَاكَ مَذْبَحًا لِلرَّبِّ وَدَعَا بِاسْمِ الرَّبِّ.', 'تكوين 12:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 9, 'ثُمَّ ارْتَحَلَ أَبْرَامُ ارْتِحَالًا مُتَوَالِيًا نَحْوَ الْجَنُوبِ.', 'تكوين 12:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 10, 'وَحَدَثَ جُوعٌ فِي الْأَرْضِ، فَانْحَدَرَ أَبْرَامُ إِلَى مِصْرَ لِيَتَغَرَّبَ هُنَاكَ، لِأَنَّ الْجُوعَ فِي الْأَرْضِ كَانَ شَدِيدًا.', 'تكوين 12:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 11, 'وَحَدَثَ لَمَّا قَرُبَ أَنْ يَدْخُلَ مِصْرَ أَنَّهُ قَالَ لِسَارَايَ امْرَأَتِهِ׃ «إِنِّي قَدْ عَلِمْتُ أَنَّكِ امْرَأَةٌ حَسَنَةُ الْمَنْظَرِ.', 'تكوين 12:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 12, 'فَيَكُونُ إِذَا رَآكِ الْمِصْرِيُّونَ أَنَّهُمْ يَقُولُونَ׃ هَذِهِ امْرَأَتُهُ. فَيَقْتُلُونَنِي وَيَسْتَبْقُونَكِ.', 'تكوين 12:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 13, 'قُولِي إِنَّكِ أُخْتِي، لِيَكُونَ لِي خَيْرٌ بِسَبَبِكِ وَتَحْيَا نَفْسِي مِنْ أَجْلِكِ».', 'تكوين 12:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 14, 'فَحَدَثَ لَمَّا دَخَلَ أَبْرَامُ إِلَى مِصْرَ أَنَّ الْمِصْرِيِّينَ رَأَوْا الْمَرْأَةَ أَنَّهَا حَسَنَةٌ جِدًّا.', 'تكوين 12:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 15, 'وَرَآهَا رُؤَسَاءُ فِرْعَوْنَ وَمَدَحُوهَا لَدَى فِرْعَوْنَ، فَأُخِذَتِ الْمَرْأَةُ إِلَى بَيْتِ فِرْعَوْنَ،', 'تكوين 12:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 16, 'فَصَنَعَ إِلَى أَبْرَامَ خَيْرًا بِسَبَبِهَا، وَصَارَ لَهُ غَنَمٌ وَبَقَرٌ وَحَمِيرٌ وَعَبِيدٌ وَإِمَاءٌ وَأُتُنٌ وَجِمَالٌ.', 'تكوين 12:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 17, 'فَضَرَبَ الرَّبُّ فِرْعَوْنَ وَبَيْتَهُ ضَرَبَاتٍ عَظِيمَةً بِسَبَبِ سَارَايَ امْرَأَةِ أَبْرَامَ.', 'تكوين 12:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 18, 'فَدَعَا فِرْعَوْنُ أَبْرَامَ وَقَالَ׃ «مَا هَذَا الَّذِي صَنَعْتَ بِي؟ لِمَاذَا لَمْ تُخْبِرْنِي أَنَّهَا امْرَأَتُكَ؟', 'تكوين 12:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 19, 'لِمَاذَا قُلْتَ׃ هِيَ أُخْتِي، حَتَّى أَخَذْتُهَا لِي لِتَكُونَ زَوْجَتِي؟ وَالْآنَ هُوَذَا امْرَأَتُكَ! خُذْهَا وَاذْهَبْ!».', 'تكوين 12:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 12, 20, 'فَأَوْصَى عَلَيْهِ فِرْعَوْنُ رِجَالًا فَشَيَّعُوهُ وَامْرَأَتَهُ وَكُلَّ مَا كَانَ لَهُ.', 'تكوين 12:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 1, 'فَصَعِدَ أَبْرَامُ مِنْ مِصْرَ هُوَ وَامْرَأَتُهُ وَكُلُّ مَا كَانَ لَهُ، وَلُوطٌ مَعَهُ إِلَى الْجَنُوبِ.', 'تكوين 13:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 2, 'وَكَانَ أَبْرَامُ غَنِيًّا جِدًّا فِي الْمَوَاشِي وَالْفِضَّةِ وَالذَّهَبِ.', 'تكوين 13:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 3, 'وَسَارَ فِي رِحْلَاتِهِ مِنَ الْجَنُوبِ إِلَى بَيْتِ إِيلَ، إِلَى الْمَكَانِ الَّذِي كَانَتْ خَيْمَتُهُ فِيهِ فِي الْبَدَاءَةِ، بَيْنَ بَيْتِ إِيلَ وَعَايَ،', 'تكوين 13:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 4, 'إِلَى مَكَانِ الْمَذْبَحِ الَّذِي عَمِلَهُ هُنَاكَ أَوَّلًا. وَدَعَا هُنَاكَ أَبْرَامُ بِاسْمِ الرَّبِّ.', 'تكوين 13:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 5, 'وَلُوطٌ السَّائِرُ مَعَ أَبْرَامَ، كَانَ لَهُ أَيْضًا غَنَمٌ وَبَقَرٌ وَخِيَامٌ.', 'تكوين 13:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 6, 'وَلَمْ تَحْتَمِلْهُمَا الْأَرْضُ أَنْ يَسْكُنَا مَعًا، إِذْ كَانَتْ أَمْلَاكُهُمَا كَثِيرَةً، فَلَمْ يَقْدِرَا أَنْ يَسْكُنَا مَعًا.', 'تكوين 13:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 7, 'فَحَدَثَتْ مُخَاصَمَةٌ بَيْنَ رُعَاةِ مَوَاشِي أَبْرَامَ وَرُعَاةِ مَوَاشِي لُوطٍ. وَكَانَ الْكَنْعَانِيُّونَ وَالْفَرِزِّيُّونَ حِينَئِذٍ سَاكِنِينَ فِي الْأَرْضِ.', 'تكوين 13:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 8, 'فَقَالَ أَبْرَامُ لِلُوطٍ׃ «لَا تَكُنْ مُخَاصَمَةٌ بَيْنِي وَبَيْنَكَ، وَبَيْنَ رُعَاتِي وَرُعَاتِكَ، لِأَنَّنَا نَحْنُ أَخَوَانِ.', 'تكوين 13:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 9, 'أَلَيْسَتْ كُلُّ الْأَرْضِ أَمَامَكَ؟ اعْتَزِلْ عَنِّي. إِنْ ذَهَبْتَ شِمَالًا فَأَنَا يَمِينًا، وَإِنْ يَمِينًا فَأَنَا شِمَالًا».', 'تكوين 13:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 10, 'فَرَفَعَ لُوطٌ عَيْنَيْهِ وَرَأَى كُلَّ دَائِرَةِ الْأُرْدُنِّ أَنَّ جَمِيعَهَا سَقْيٌ، قَبْلَمَا أَخْرَبَ الرَّبُّ سَدُومَ وَعَمُورَةَ، كَجَنَّةِ الرَّبِّ، كَأَرْضِ مِصْرَ. حِينَمَا تَجِيءُ إِلَى صُوغَرَ.', 'تكوين 13:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 11, 'فَاخْتَارَ لُوطٌ لِنَفْسِهِ كُلَّ دَائِرَةِ الْأُرْدُنِّ، وَارْتَحَلَ لُوطٌ شَرْقًا. فَاعْتَزَلَ الْوَاحِدُ عَنِ الْآخَرِ.', 'تكوين 13:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 12, 'أَبْرَامُ سَكَنَ فِي أَرْضِ كَنْعَانَ، وَلُوطٌ سَكَنَ فِي مُدُنِ الدَّائِرَةِ، وَنَقَلَ خِيَامَهُ إِلَى سَدُومَ.', 'تكوين 13:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 13, 'وَكَانَ أَهْلُ سَدُومَ أَشْرَارًا وَخُطَاةً لَدَى الرَّبِّ جِدًّا.', 'تكوين 13:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 14, 'وَقَالَ الرَّبُّ لِأَبْرَامَ، بَعْدَ اعْتِزَالِ لُوطٍ عَنْهُ׃ «ارْفَعْ عَيْنَيْكَ وَانْظُرْ مِنَ الْمَوْضِعِ الَّذِي أَنْتَ فِيهِ شِمَالًا وَجَنُوبًا وَشَرْقًا وَغَرْبًا،', 'تكوين 13:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 15, 'لِأَنَّ جَمِيعَ الْأَرْضِ الَّتِي أَنْتَ تَرَى لَكَ أُعْطِيهَا وَلِنَسْلِكَ إِلَى الْأَبَدِ.', 'تكوين 13:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 16, 'وَأَجْعَلُ نَسْلَكَ كَتُرَابِ الْأَرْضِ، حَتَّى إِذَا اسْتَطَاعَ أَحَدٌ أَنْ يَعُدَّ تُرَابَ الْأَرْضِ فَنَسْلُكَ أَيْضًا يُعَدُّ.', 'تكوين 13:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 17, 'قُمِ امْشِ فِي الْأَرْضِ طُولَهَا وَعَرْضَهَا، لِأَنِّي لَكَ أُعْطِيهَا».', 'تكوين 13:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 13, 18, 'فَنَقَلَ أَبْرَامُ خِيَامَهُ وَأَتَى وَأَقَامَ عِنْدَ بَلُّوطَاتِ مَمْرَا الَّتِي فِي حَبْرُونَ، وَبَنَى هُنَاكَ مَذْبَحًا لِلرَّبِّ.', 'تكوين 13:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 1, 'وَحَدَثَ فِي أَيَّامِ أَمْرَافَلَ مَلِكِ شِنْعَارَ، وَأَرْيُوكَ مَلِكِ أَلَّاسَارَ، وَكَدَرْلَعَوْمَرَ مَلِكِ عِيلَامَ، وَتِدْعَالَ مَلِكِ جُويِيمَ،', 'تكوين 14:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 2, 'أَنَّ هَؤُلَاءِ صَنَعُوا حَرْبًا مَعَ بَارَعَ مَلِكِ سَدُومَ، وَبِرْشَاعَ مَلِكِ عَمُورَةَ، وَشِنْآبَ مَلِكِ أَدْمَةَ، وَشِمْئِيبَرَ مَلِكِ صَبُويِيمَ، وَمَلِكِ بَالَعَ الَّتِي هِيَ صُوغَرُ.', 'تكوين 14:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 3, 'جَمِيعُ هَؤُلَاءِ اجْتَمَعُوا مُتَعَاهِدِينَ إِلَى عُمْقِ السِّدِّيمِ الَّذِي هُوَ بَحْرُ الْمِلْحِ.', 'تكوين 14:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 4, 'اِثْنَتَيْ عَشَرَةَ سَنَةً اسْتُعْبِدُوا لِكَدَرْلَعَوْمَرَ، وَالسَّنَةَ الثَّالِثَةَ عَشَرَةَ عَصَوْا عَلَيْهِ.', 'تكوين 14:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 5, 'وَفِي السَّنَةِ الرَّابِعَةَ عَشَرْةَ أَتَى كَدَرْلَعَوْمَرُ وَالْمُلُوكُ الَّذِينَ مَعَهُ وَضَرَبُوا الرَّفَائِيِّينَ فِي عَشْتَارُوثَ قَرْنَايِمَ، وَالزُّوزِيِّينَ فِي هَامَ، وَالْإِيمِيِّينَ فِي شَوَى قَرْيَتَايِمَ،', 'تكوين 14:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 6, 'وَالْحُورِيِّينَ فِي جَبَلِهِمْ سَعِيرَ إِلَى بُطْمَةِ فَارَانَ الَّتِي عِنْدَ الْبَرِّيَّةِ.', 'تكوين 14:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 7, 'ثُمَّ رَجَعُوا وَجَاءُوا إِلَى عَيْنِ مِشْفَاطَ الَّتِي هِيَ قَادِشُ. وَضَرَبُوا كُلَّ بِلَادِ الْعَمَالِقَةِ، وَأَيْضًا الْأَمُورِيِّينَ السَّاكِنِينَ فِي حَصُّونَ تَامَارَ.', 'تكوين 14:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 8, 'فَخَرَجَ مَلِكُ سَدُومَ، وَمَلِكُ عَمُورَةَ، وَمَلِكُ أَدْمَةَ، وَمَلِكُ صَبُويِيمَ، وَمَلِكُ بَالَعَ، الَّتِي هِيَ صُوغَرُ، وَنَظَمُوا حَرْبًا مَعَهُمْ فِي عُمْقِ السِّدِّيمِ.', 'تكوين 14:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 9, 'مَعَ كَدَرْلَعَوْمَرَ مَلِكِ عِيلَامَ، وَتِدْعَالَ مَلِكِ جُويِيمَ، وَأَمْرَافَلَ مَلِكِ شِنْعَارَ، وَأَرْيُوكَ مَلِكِ أَلَّاسَارَ. أَرْبَعَةُ مُلُوكٍ مَعَ خَمْسَةٍ.', 'تكوين 14:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 10, 'وَعُمْقُ السِّدِّيمِ كَانَ فِيهِ آبَارُ حُمَرٍ كَثِيرَةٌ. فَهَرَبَ مَلِكَا سَدُومَ وَعَمُورَةَ وَسَقَطَا هُنَاكَ، وَالْبَاقُونَ هَرَبُوا إِلَى الْجَبَلِ.', 'تكوين 14:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 11, 'فَأَخَذُوا جَمِيعَ أَمْلَاكِ سَدُومَ وَعَمُورَةَ وَجَمِيعَ أَطْعِمَتِهِمْ وَمَضَوْا.', 'تكوين 14:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 12, 'وَأَخَذُوا لُوطًا ابْنَ أَخِي أَبْرَامَ وَأَمْلَاكَهُ وَمَضَوْا، إِذْ كَانَ سَاكِنًا فِي سَدُومَ.', 'تكوين 14:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 13, 'فَأَتَى مَنْ نَجَا وَأَخْبَرَ أَبْرَامَ الْعِبْرَانِيَّ. وَكَانَ سَاكِنًا عِنْدَ بَلُّوطَاتِ مَمْرَا الْأَمُورِيِّ، أَخِي أَشْكُولَ وَأَخِي عَانِرَ. وَكَانُوا أَصْحَابَ عَهْدٍ مَعَ أَبْرَامَ.', 'تكوين 14:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 14, 'فَلَمَّا سَمِعَ أَبْرَامُ، أَنَّ أَخَاهُ سُبِيَ جَرَّ غِلْمَانَهُ الْمُتَمَرِّنِينَ، وِلْدَانَ بَيْتِهِ، ثَلَاثَ مِئَةٍ وَثَمَانِيَةَ عَشَرَ، وَتَبِعَهُمْ إِلَى دَانَ.', 'تكوين 14:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 15, 'وَانْقَسَمَ عَلَيْهِمْ لَيْلًا هُوَ وَعَبِيدُهُ فَكَسَّرَهُمْ وَتَبِعَهُمْ إِلَى حُوبَةَ الَّتِي عَنْ شِمَالِ دِمَشْقَ.', 'تكوين 14:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 16, 'وَاسْتَرْجَعَ كُلَّ الْأَمْلَاكِ، وَاسْتَرْجَعَ لُوطًا أَخَاهُ أَيْضًا وَأَمْلَاكَهُ، وَالنِّسَاءَ أَيْضًا وَالشَّعْبَ.', 'تكوين 14:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 17, 'فَخَرَجَ مَلِكُ سَدُومَ لِاسْتِقْبَالِهِ، بَعْدَ رُجُوعِهِ مِنْ كَسْرَةِ كَدَرْلَعَوْمَرَ وَالْمُلُوكِ الَّذِينَ مَعَهُ إِلَى عُمْقِ شَوَى، الَّذِي هُوَ عُمْقُ الْمَلِكِ.', 'تكوين 14:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 18, 'وَمَلْكِي صَادِقُ، مَلِكُ شَالِيمَ، أَخْرَجَ خُبْزًا وَخَمْرًا. وَكَانَ كَاهِنًا لِلهِ الْعَلِيِّ.', 'تكوين 14:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 19, 'وَبَارَكَهُ وَقَالَ׃ «مُبَارَكٌ أَبْرَامُ مِنَ اللهِ الْعَلِيِّ مَالِكِ السَّمَاوَاتِ وَالْأَرْضِ،', 'تكوين 14:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 20, 'وَمُبَارَكٌ اللهُ الْعَلِيُّ الَّذِي أَسْلَمَ أَعْدَاءَكَ فِي يَدِكَ». فَأَعْطَاهُ عُشْرًا مِنْ كُلِّ شَيْءٍ.', 'تكوين 14:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 21, 'وَقَالَ مَلِكُ سَدُومَ لِأَبْرَامَ׃ «أَعْطِنِي النُّفُوسَ، وَأَمَّا الْأَمْلَاكَ فَخُذْهَا لِنَفْسِكَ».', 'تكوين 14:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 22, 'فَقَالَ أَبْرَامُ لِمَلِكِ سَدُومَ׃ «رَفَعْتُ يَدِي إِلَى الرَّبِّ الْإِلَهِ الْعَلِيِّ مَالِكِ السَّمَاءِ وَالْأَرْضِ،', 'تكوين 14:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 23, 'لَا آخُذَنَّ لَا خَيْطًا وَلَا شِرَاكَ نَعْلٍ وَلَا مِنْ كُلِّ مَا هُوَ لَكَ، فَلَا تَقُولُ׃ أَنَا أَغْنَيْتُ أَبْرَامَ.', 'تكوين 14:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 14, 24, 'لَيْسَ لِي غَيْرُ الَّذِي أَكَلَهُ الْغِلْمَانُ، وَأَمَّا نَصِيبُ الرِّجَالِ الَّذِينَ ذَهَبُوا مَعِي׃ عَانِرَ وَأَشْكُولَ وَمَمْرَا، فَهُمْ يَأْخُذُونَ نَصِيبَهُمْ».', 'تكوين 14:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 1, 'بَعْدَ هَذِهِ الْأُمُورِ صَارَ كَلَامُ الرَّبِّ إِلَى أَبْرَامَ فِي الرُّؤْيَا قَائِلًا׃ «لَا تَخَفْ يَا أَبْرَامُ. أَنَا تُرْسٌ لَكَ. أَجْرُكَ كَثِيرٌ جِدًّا».', 'تكوين 15:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 2, 'فَقَالَ أَبْرَامُ׃ «أَيُّهَا السَّيِّدُ الرَّبُّ، مَاذَا تُعْطِينِي وَأَنَا مَاضٍ عَقِيمًا، وَمَالِكُ بَيْتِي هُوَ أَلِيعَازَرُ الدِّمَشْقِيُّ؟»', 'تكوين 15:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 3, 'وَقَالَ أَبْرَامُ أَيْضًا׃ «إِنَّكَ لَمْ تُعْطِنِي نَسْلًا، وَهُوَذَا ابْنُ بَيْتِي وَارِثٌ لِي».', 'تكوين 15:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 4, 'فَإِذَا كَلَامُ الرَّبِّ إِلَيْهِ قَائِلًا׃ «لَا يَرِثُكَ هَذَا، بَلِ الَّذِي يَخْرُجُ مِنْ أَحْشَائِكَ هُوَ يَرِثُكَ».', 'تكوين 15:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 5, 'ثُمَّ أَخْرَجَهُ إِلَى خَارِجٍ وَقَالَ׃ «انْظُرْ إِلَى السَّمَاءِ وَعُدَّ النُّجُومَ إِنِ اسْتَطَعْتَ أَنْ تَعُدَّهَا». وَقَالَ لَهُ׃ «هَكَذَا يَكُونُ نَسْلُكَ».', 'تكوين 15:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 6, 'فَآمَنَ بِالرَّبِّ فَحَسِبَهُ لَهُ بِرًّا.', 'تكوين 15:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 7, 'وَقَالَ لَهُ׃ «أَنَا الرَّبُّ الَّذِي أَخْرَجَكَ مِنْ أُورِ الْكَلْدَانِيِّينَ لِيُعْطِيَكَ هَذِهِ الْأَرْضَ لِتَرِثَهَا».', 'تكوين 15:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 8, 'فَقَالَ׃ «أَيُّهَا السَّيِّدُ الرَّبُّ، بِمَاذَا أَعْلَمُ أَنِّي أَرِثُهَا؟»', 'تكوين 15:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 9, 'فَقَالَ لَهُ׃ «خُذْ لِي عِجْلَةً ثُلَاثِيَّةً، وَعَنْزَةً ثُلَاثِيَّةً، وَكَبْشًا ثُلَاثِيًّا، وَيَمَامَةً وَحَمَامَةً».', 'تكوين 15:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 10, 'فَأَخَذَ هَذِهِ كُلَّهَا وَشَقَّهَا مِنَ الْوَسَطِ، وَجَعَلَ شِقَّ كُلِّ وَاحِدٍ مُقَابِلَ صَاحِبِهِ. وَأَمَّا الطَّيْرُ فَلَمْ يَشُقَّهُ.', 'تكوين 15:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 11, 'فَنَزَلَتِ الْجَوَارِحُ عَلَى الْجُثَثِ، وَكَانَ أَبْرَامُ يَزْجُرُهَا.', 'تكوين 15:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 12, 'وَلَمَّا صَارَتِ الشَّمْسُ إِلَى الْمَغِيبِ، وَقَعَ عَلَى أَبْرَامَ سُبَاتٌ، وَإِذَا رُعْبَةٌ مُظْلِمَةٌ عَظِيمَةٌ وَاقِعَةٌ عَلَيْهِ.', 'تكوين 15:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 13, 'فَقَالَ لِأَبْرَامَ׃ «اعْلَمْ يَقِينًا أَنَّ نَسْلَكَ سَيَكُونُ غَرِيبًا فِي أَرْضٍ لَيْسَتْ لَهُمْ، وَيُسْتَعْبَدُونَ لَهُمْ. فَيُذِلُّونَهُمْ أَرْبَعَ مِئَةِ سَنَةٍ.', 'تكوين 15:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 14, 'ثُمَّ الْأُمَّةُ الَّتِي يُسْتَعْبَدُونَ لَهَا أَنَا أَدِينُهَا، وَبَعْدَ ذَلِكَ يَخْرُجُونَ بِأَمْلَاكٍ جَزِيلَةٍ.', 'تكوين 15:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 15, 'وَأَمَّا أَنْتَ فَتَمْضِي إِلَى آبَائِكَ بِسَلَامٍ وَتُدْفَنُ بِشَيْبَةٍ صَالِحَةٍ.', 'تكوين 15:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 16, 'وَفِي الْجِيلِ الرَّابِعِ يَرْجِعُونَ إِلَى هَهُنَا، لِأَنَّ ذَنْبَ الْأَمُورِيِّينَ لَيْسَ إِلَى الْآنَ كَامِلًا».', 'تكوين 15:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 17, 'ثُمَّ غَابَتِ الشَّمْسُ فَصَارَتِ الْعَتَمَةُ، وَإِذَا تَنُّورُ دُخَانٍ وَمِصْبَاحُ نَارٍ يَجُوزُ بَيْنَ تِلْكَ الْقِطَعِ.', 'تكوين 15:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 18, 'فِي ذَلِكَ الْيَوْمِ قَطَعَ الرَّبُّ مَعَ أَبْرَامَ مِيثَاقًا قَائِلًا׃ «لِنَسْلِكَ أُعْطِي هَذِهِ الْأَرْضَ، مِنْ نَهْرِ مِصْرَ إِلَى النَّهْرِ الْكَبِيرِ، نَهْرِ الْفُرَاتِ.', 'تكوين 15:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 19, 'الْقِينِيِّينَ وَالْقَنِزِّيِّينَ وَالْقَدْمُونِيِّينَ', 'تكوين 15:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 20, 'وَالْحِثِّيِّينَ وَالْفَرِزِّيِّينَ وَالرَّفَائِيِّينَ', 'تكوين 15:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 15, 21, 'وَالْأَمُورِيِّينَ وَالْكَنْعَانِيِّينَ وَالْجِرْجَاشِيِّينَ وَالْيَبُوسِيِّينَ».', 'تكوين 15:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 1, 'وَأَمَّا سَارَايُ امْرَأَةُ أَبْرَامَ فَلَمْ تَلِدْ لَهُ. وَكَانَتْ لَهَا جَارِيَةٌ مِصْرِيَّةٌ اسْمُهَا هَاجَرُ،', 'تكوين 16:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 2, 'فَقَالَتْ سَارَايُ لِأَبْرَامَ׃ «هُوَذَا الرَّبُّ قَدْ أَمْسَكَنِي عَنِ الْوِلَادَةِ. ادْخُلْ عَلَى جَارِيَتِي لَعَلِّي أُرْزَقُ مِنْهَا بَنِينَ». فَسَمِعَ أَبْرَامُ لِقَوْلِ سَارَايَ.', 'تكوين 16:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 3, 'فَأَخَذَتْ سَارَايُ امْرَأَةُ أَبْرَامَ هَاجَرَ الْمِصْرِيَّةَ جَارِيَتَهَا، مِنْ بَعْدِ عَشَرِ سِنِينَ لإِقَامَةِ أَبْرَامَ فِي أَرْضِ كَنْعَانَ، وَأَعْطَتْهَا لِأَبْرَامَ رَجُلِهَا زَوْجَةً لَهُ.', 'تكوين 16:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 4, 'فَدَخَلَ عَلَى هَاجَرَ فَحَبِلَتْ. وَلَمَّا رَأَتْ أَنَّهَا حَبِلَتْ صَغُرَتْ مَوْلَاتُهَا فِي عَيْنَيْهَا.', 'تكوين 16:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 5, 'فَقَالَتْ سَارَايُ لِأَبْرَامَ׃ «ظُلْمِي عَلَيْكَ! أَنَا دَفَعْتُ جَارِيَتِي إِلَى حِضْنِكَ، فَلَمَّا رَأَتْ أَنَّهَا حَبِلَتْ صَغُرْتُ فِي عَيْنَيْهَا. يَقْضِي الرَّبُّ بَيْنِي وَبَيْنَكَ».', 'تكوين 16:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 6, 'فَقَالَ أَبْرَامُ لِسَارَايَ׃ «هُوَذَا جَارِيَتُكِ فِي يَدِكِ. افْعَلِي بِهَا مَا يَحْسُنُ فِي عَيْنَيْكِ». فَأَذَلَّتْهَا سَارَايُ، فَهَرَبَتْ مِنْ وَجْهِهَا.', 'تكوين 16:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 7, 'فَوَجَدَهَا مَلَاكُ الرَّبِّ عَلَى عَيْنِ الْمَاءِ فِي الْبَرِّيَّةِ، عَلَى الْعَيْنِ الَّتِي فِي طَرِيقِ شُورَ.', 'تكوين 16:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 8, 'وَقَالَ׃ «يَا هَاجَرُ جَارِيَةَ سَارَايَ، مِنْ أَيْنَ أَتَيْتِ؟ وَإِلَى أَيْنَ تَذْهَبِينَ؟». فَقَالَتْ׃ «أَنَا هَارِبَةٌ مِنْ وَجْهِ مَوْلَاتِي سَارَايَ».', 'تكوين 16:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 9, 'فَقَالَ لَهَا مَلَاكُ الرَّبِّ׃ «ارْجِعِي إِلَى مَوْلَاتِكِ وَاخْضَعِي تَحْتَ يَدَيْهَا».', 'تكوين 16:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 10, 'وَقَالَ لَهَا مَلَاكُ الرَّبِّ׃ «تَكْثِيرًا أُكَثِّرُ نَسْلَكِ فَلَا يُعَدُّ مِنَ الْكَثْرَةِ».', 'تكوين 16:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 11, 'وَقَالَ لَهَا مَلَاكُ الرَّبِّ׃ «هَا أَنْتِ حُبْلَى، فَتَلِدِينَ ابْنًا وَتَدْعِينَ اسْمَهُ إِسْمَاعِيلَ، لِأَنَّ الرَّبَّ قَدْ سَمِعَ لِمَذَلَّتِكِ.', 'تكوين 16:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 12, 'وَإِنَّهُ يَكُونُ إِنْسَانًا وَحْشِيًّا، يَدُهُ عَلَى كُلِّ وَاحِدٍ، وَيَدُ كُلِّ وَاحِدٍ عَلَيْهِ، وَأَمَامَ جَمِيعِ إِخْوَتِهِ يَسْكُنُ».', 'تكوين 16:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 13, 'فَدَعَتِ اسْمَ الرَّبِّ الَّذِي تَكَلَّمَ مَعَهَا׃ «أَنْتَ إِيلُ رُئِي». لِأَنَّهَا قَالَتْ׃ «أَهَهُنَا أَيْضًا رَأَيْتُ بَعْدَ رُؤْيَةٍ؟».', 'تكوين 16:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 14, 'لِذَلِكَ دُعِيَتِ الْبِئْرُ «بِئْرَ لَحَيْ رُئِي». هَا هِيَ بَيْنَ قَادِشَ وَبَارَدَ.', 'تكوين 16:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 15, 'فَوَلَدَتْ هَاجَرُ لِأَبْرَامَ ابْنًا. وَدَعَا أَبْرَامُ اسْمَ ابْنِهِ الَّذِي وَلَدَتْهُ هَاجَرُ «إِسْمَاعِيلَ».', 'تكوين 16:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 16, 16, 'كَانَ أَبْرَامُ ابْنَ سِتٍّ وَثَمَانِينَ سَنَةً لَمَّا وَلَدَتْ هَاجَرُ إِسْمَاعِيلَ لِأَبْرَامَ.', 'تكوين 16:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 1, 'وَلَمَّا كَانَ أَبْرَامُ ابْنَ تِسْعٍ وَتِسْعِينَ سَنَةً ظَهَرَ الرَّبُّ لِأَبْرَامَ وَقَالَ لَهُ׃ «أَنَا اللهُ الْقَدِيرُ. سِرْ أَمَامِي وَكُنْ كَامِلًا،', 'تكوين 17:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 2, 'فَأَجْعَلَ عَهْدِي بَيْنِي وَبَيْنَكَ، وَأُكَثِّرَكَ كَثِيرًا جِدًّا».', 'تكوين 17:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 3, 'فَسَقَطَ أَبْرَامُ عَلَى وَجْهِهِ. وَتَكَلَّمَ اللهُ مَعَهُ قَائِلًا׃', 'تكوين 17:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 4, '«أَمَّا أَنَا فَهُوَذَا عَهْدِي مَعَكَ، وَتَكُونُ أَبًا لِجُمْهُورٍ مِنَ الْأُمَمِ،', 'تكوين 17:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 5, 'فَلَا يُدْعَى اسْمُكَ بَعْدُ أَبْرَامَ بَلْ يَكُونُ اسْمُكَ إِبْرَاهِيمَ، لِأَنِّي أَجْعَلُكَ أَبًا لِجُمْهُورٍ مِنَ الْأُمَمِ.', 'تكوين 17:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 6, 'وَأُثْمِرُكَ كَثِيرًا جِدًّا، وَأَجْعَلُكَ أُمَمًا، وَمُلُوكٌ مِنْكَ يَخْرُجُونَ.', 'تكوين 17:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 7, 'وَأُقِيمُ عَهْدِي بَيْنِي وَبَيْنَكَ، وَبَيْنَ نَسْلِكَ مِنْ بَعْدِكَ فِي أَجْيَالِهِمْ، عَهْدًا أَبَدِيًّا، لِأَكُونَ إِلَهًا لَكَ وَلِنَسْلِكَ مِنْ بَعْدِكَ.', 'تكوين 17:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 8, 'وَأُعْطِي لَكَ وَلِنَسْلِكَ مِنْ بَعْدِكَ أَرْضَ غُرْبَتِكَ، كُلَّ أَرْضِ كَنْعَانَ مُلْكًا أَبَدِيًّا. وَأَكُونُ إِلَهَهُمْ».', 'تكوين 17:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 9, 'وَقَالَ اللهُ لِإِبْرَاهِيمَ׃ «وَأَمَّا أَنْتَ فَتَحْفَظُ عَهْدِي، أَنْتَ وَنَسْلُكَ مِنْ بَعْدِكَ فِي أَجْيَالِهِمْ.', 'تكوين 17:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 10, 'هَذَا هُوَ عَهْدِي الَّذِي تَحْفَظُونَهُ بَيْنِي وَبَيْنَكُمْ، وَبَيْنَ نَسْلِكَ مِنْ بَعْدِكَ׃ يُخْتَنُ مِنْكُمْ كُلُّ ذَكَرٍ،', 'تكوين 17:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 11, 'فَتُخْتَنُونَ فِي لَحْمِ غُرْلَتِكُمْ، فَيَكُونُ عَلَامَةَ عَهْدٍ بَيْنِي وَبَيْنَكُمْ.', 'تكوين 17:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 12, 'اِبْنَ ثَمَانِيَةِ أَيَّامٍ يُخْتَنُ مِنْكُمْ كُلُّ ذَكَرٍ فِي أَجْيَالِكُمْ׃ وَلِيدُ الْبَيْتِ، وَالْمُبْتَاعُ بِفِضَّةٍ مِنْ كُلِّ ابْنِ غَرِيبٍ لَيْسَ مِنْ نَسْلِكَ.', 'تكوين 17:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 13, 'يُخْتَنُ خِتَانًا وَلِيدُ بَيْتِكَ وَالْمُبْتَاعُ بِفِضَّتِكَ، فَيَكُونُ عَهْدِي فِي لَحْمِكُمْ عَهْدًا أَبَدِيًّا.', 'تكوين 17:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 14, 'وَأَمَّا الذَّكَرُ الْأَغْلَفُ الَّذِي لَا يُخْتَنُ فِي لَحْمِ غُرْلَتِهِ فَتُقْطَعُ تِلْكَ النَّفْسُ مِنْ شَعْبِهَا. إِنَّهُ قَدْ نَكَثَ عَهْدِي».', 'تكوين 17:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 15, 'وَقَالَ اللهُ لِإِبْرَاهِيمَ׃ «سَارَايُ امْرَأَتُكَ لَا تَدْعُو اسْمَهَا سَارَايَ، بَلِ اسْمُهَا سَارَةُ.', 'تكوين 17:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 16, 'وَأُبَارِكُهَا وَأُعْطِيكَ أَيْضًا مِنْهَا ابْنًا. أُبَارِكُهَا فَتَكُونُ أُمَمًا، وَمُلُوكُ شُعُوبٍ مِنْهَا يَكُونُونَ».', 'تكوين 17:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 17, 'فَسَقَطَ إِبْرَاهِيمُ عَلَى وَجْهِهِ وَضَحِكَ، وَقَالَ فِي قَلْبِهِ׃ «هَلْ يُولَدُ لِابْنِ مِئَةِ سَنَةٍ؟ وَهَلْ تَلِدُ سَارَةُ وَهِيَ بِنْتُ تِسْعِينَ سَنَةً؟».', 'تكوين 17:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 18, 'وَقَالَ إِبْرَاهِيمُ لِلهِ׃ «لَيْتَ إِسْمَاعِيلَ يَعِيشُ أَمَامَكَ!».', 'تكوين 17:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 19, 'فَقَالَ اللهُ׃ «بَلْ سَارَةُ امْرَأَتُكَ تَلِدُ لَكَ ابْنًا وَتَدْعُو اسْمَهُ إِسْحَاقَ. وَأُقِيمُ عَهْدِي مَعَهُ عَهْدًا أَبَدِيًّا لِنَسْلِهِ مِنْ بَعْدِهِ.', 'تكوين 17:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 20, 'وَأَمَّا إِسْمَاعِيلُ فَقَدْ سَمِعْتُ لَكَ فِيهِ. هَا أَنَا أُبَارِكُهُ وَأُثْمِرُهُ وَأُكَثِّرُهُ كَثِيرًا جِدًّا. اِثْنَيْ عَشَرَ رَئِيسًا يَلِدُ، وَأَجْعَلُهُ أُمَّةً كَبِيرَةً.', 'تكوين 17:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 21, 'وَلَكِنْ عَهْدِي أُقِيمُهُ مَعَ إِسْحَاقَ الَّذِي تَلِدُهُ لَكَ سَارَةُ فِي هَذَا الْوَقْتِ فِي السَّنَةِ الْآتِيَةِ».', 'تكوين 17:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 22, 'فَلَمَّا فَرَغَ مِنَ الْكَلَامِ مَعَهُ صَعِدَ اللهُ عَنْ إِبْرَاهِيمَ.', 'تكوين 17:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 23, 'فَأَخَذَ إِبْرَاهِيمُ إِسْمَاعِيلَ ابْنَهُ، وَجَمِيعَ وِلْدَانِ بَيْتِهِ، وَجَمِيعَ الْمُبْتَاعِينَ بِفِضَّتِهِ، كُلَّ ذَكَرٍ مِنْ أَهْلِ بَيْتِ إِبْرَاهِيمَ، وَخَتَنَ لَحْمَ غُرْلَتِهِمْ فِي ذَلِكَ الْيَوْمِ عَيْنِهِ كَمَا كَلَّمَهُ اللهُ.', 'تكوين 17:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 24, 'وَكَانَ إِبْرَاهِيمُ ابْنَ تِسْعٍ وَتِسْعِينَ سَنَةً حِينَ خُتِنَ فِي لَحْمِ غُرْلَتِهِ،', 'تكوين 17:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 25, 'وَكَانَ إِسْمَاعِيلُ ابْنُهُ ابْنَ ثَلَاثَ عَشَرَةَ سَنَةً حِينَ خُتِنَ فِي لَحْمِ غُرْلَتِهِ.', 'تكوين 17:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 26, 'فِي ذَلِكَ الْيَوْمِ عَيْنِهِ خُتِنَ إِبْرَاهِيمُ وَإِسْمَاعِيلُ ابْنُهُ.', 'تكوين 17:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 17, 27, 'وَكُلُّ رِجَالِ بَيْتِهِ وِلْدَانِ الْبَيْتِ وَالْمُبْتَاعِينَ بِالْفِضَّةِ مِنِ ابْنِ الْغَرِيبِ خُتِنُوا مَعَهُ.', 'تكوين 17:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 1, 'وَظَهَرَ لَهُ الرَّبُّ عِنْدَ بَلُّوطَاتِ مَمْرَا وَهُوَ جَالِسٌ فِي بَابِ الْخَيْمَةِ وَقْتَ حَرِّ النَّهَارِ،', 'تكوين 18:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 2, 'فَرَفَعَ عَيْنَيْهِ وَنَظَرَ وَإِذَا ثَلَاثَةُ رِجَالٍ وَاقِفُونَ لَدَيْهِ. فَلَمَّا نَظَرَ رَكَضَ لِاسْتِقْبَالِهِمْ مِنْ بَابِ الْخَيْمَةِ وَسَجَدَ إِلَى الْأَرْضِ،', 'تكوين 18:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 3, 'وَقَالَ׃ «يَا سَيِّدُ، إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ فَلَا تَتَجَاوَزْ عَبْدَكَ.', 'تكوين 18:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 4, 'لِيُؤْخَذْ قَلِيلُ مَاءٍ وَاغْسِلُوا أَرْجُلَكُمْ وَاتَّكِئُوا تَحْتَ الشَّجَرَةِ،', 'تكوين 18:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 5, 'فَآخُذَ كِسْرَةَ خُبْزٍ، فَتُسْنِدُونَ قُلُوبَكُمْ ثُمَّ تَجْتَازُونَ، لِأَنَّكُمْ قَدْ مَرَرْتُمْ عَلَى عَبْدِكُمْ». فَقَالُوا׃ «هَكَذَا تَفْعَلُ كَمَا تَكَلَّمْتَ».', 'تكوين 18:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 6, 'فَأَسْرَعَ إِبْرَاهِيمُ إِلَى الْخَيْمَةِ إِلَى سَارَةَ، وَقَالَ׃ «أَسْرِعِي بِثَلَاثِ كَيْلَاتٍ دَقِيقًا سَمِيذًا. اعْجِنِي وَاصْنَعِي خُبْزَ مَلَّةٍ».', 'تكوين 18:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 7, 'ثُمَّ رَكَضَ إِبْرَاهِيمُ إِلَى الْبَقَرِ وَأَخَذَ عِجْلًا رَخْصًا وَجَيِّدًا وَأَعْطَاهُ لِلْغُلَامِ فَأَسْرَعَ لِيَعْمَلَهُ.', 'تكوين 18:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 8, 'ثُمَّ أَخَذَ زُبْدًا وَلَبَنًا، وَالْعِجْلَ الَّذِي عَمِلَهُ، وَوَضَعَهَا قُدَّامَهُمْ. وَإِذْ كَانَ هُوَ وَاقِفًا لَدَيْهِمْ تَحْتَ الشَّجَرَةِ أَكَلُوا.', 'تكوين 18:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 9, 'وَقَالُوا لَهُ׃ «أَيْنَ سَارَةُ امْرَأَتُكَ؟» فَقَالَ׃ «هَا هِيَ فِي الْخَيْمَةِ».', 'تكوين 18:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 10, 'فَقَالَ׃ «إِنِّي أَرْجِعُ إِلَيْكَ نَحْوَ زَمَانِ الْحَيَاةِ وَيَكُونُ لِسَارَةَ امْرَأَتِكَ ابْنٌ». وَكَانَتْ سَارَةُ سَامِعَةً فِي بَابِ الْخَيْمَةِ وَهُوَ وَرَاءَهُ.', 'تكوين 18:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 11, 'وَكَانَ إِبْرَاهِيمُ وَسَارَةُ شَيْخَيْنِ مُتَقَدِّمَيْنِ فِي الْأَيَّامِ، وَقَدِ انْقَطَعَ أَنْ يَكُونَ لِسَارَةَ عَادَةٌ كَالنِّسَاءِ.', 'تكوين 18:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 12, 'فَضَحِكَتْ سَارَةُ فِي بَاطِنِهَا قَائِلَةً׃ «أَبَعْدَ فَنَائِي يَكُونُ لِي تَنَعُّمٌ، وَسَيِّدِي قَدْ شَاخَ؟».', 'تكوين 18:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 13, 'فَقَالَ الرَّبُّ لِإِبْرَاهِيمَ׃ «لِمَاذَا ضَحِكَتْ سَارَةُ قَائِلَةً׃ أَفَبِالْحَقِيقَةِ أَلِدُ وَأَنَا قَدْ شِخْتُ؟', 'تكوين 18:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 14, 'هَلْ يَسْتَحِيلُ عَلَى الرَّبِّ شَيْءٌ؟ فِي الْمِيعَادِ أَرْجِعُ إِلَيْكَ نَحْوَ زَمَانِ الْحَيَاةِ وَيَكُونُ لِسَارَةَ ابْنٌ».', 'تكوين 18:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 15, 'فَأَنْكَرَتْ سَارَةُ قَائِلَةً׃ «لَمْ أَضْحَكْ». لِأَنَّهَا خَافَتْ. فَقَالَ׃ «لَا! بَلْ ضَحِكْتِ».', 'تكوين 18:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 16, 'ثُمَّ قَامَ الرِّجَالُ مِنْ هُنَاكَ وَتَطَلَّعُوا نَحْوَ سَدُومَ. وَكَانَ إِبْرَاهِيمُ مَاشِيًا مَعَهُمْ لِيُشَيِّعَهُمْ.', 'تكوين 18:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 17, 'فَقَالَ الرَّبُّ׃ «هَلْ أُخْفِي عَنْ إِبْرَاهِيمَ مَا أَنَا فَاعِلُهُ،', 'تكوين 18:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 18, 'وَإِبْرَاهِيمُ يَكُونُ أُمَّةً كَبِيرَةً وَقَوِيَّةً، وَيَتَبَارَكُ بِهِ جَمِيعُ أُمَمِ الْأَرْضِ؟', 'تكوين 18:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 19, 'لِأَنِّي عَرَفْتُهُ لِكَيْ يُوصِيَ بَنِيهِ وَبَيْتَهُ مِنْ بَعْدِهِ أَنْ يَحْفَظُوا طَرِيقَ الرَّبِّ، لِيَعْمَلُوا بِرًّا وَعَدْلًا، لِكَيْ يَأْتِيَ الرَّبُّ لِإِبْرَاهِيمَ بِمَا تَكَلَّمَ بِهِ».', 'تكوين 18:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 20, 'وَقَالَ الرَّبُّ׃ «إِنَّ صُرَاخَ سَدُومَ وَعَمُورَةَ قَدْ كَثُرَ، وَخَطِيَّتُهُمْ قَدْ عَظُمَتْ جِدًّا.', 'تكوين 18:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 21, 'أَنْزِلُ وَأَرَى هَلْ فَعَلُوا بِالتَّمَامِ حَسَبَ صُرَاخِهَا الْآتِي إِلَيَّ، وَإِلَا فَأَعْلَمُ».', 'تكوين 18:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 22, 'وَانْصَرَفَ الرِّجَالُ مِنْ هُنَاكَ وَذَهَبُوا نَحْوَ سَدُومَ، وَأَمَّا إِبْرَاهِيمُ فَكَانَ لَمْ يَزَلْ قَائِمًا أَمَامَ الرَّبِّ.', 'تكوين 18:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 23, 'فَتَقَدَّمَ إِبْرَاهِيمُ وَقَالَ׃ «أَفَتُهْلِكُ الْبَارَّ مَعَ الْأَثِيمِ؟', 'تكوين 18:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 24, 'عَسَى أَنْ يَكُونَ خَمْسُونَ بَارًّا فِي الْمَدِينَةِ. أَفَتُهْلِكُ الْمَكَانَ وَلَا تَصْفَحُ عَنْهُ مِنْ أَجْلِ الْخَمْسِينَ بَارًّا الَّذِينَ فِيهِ؟', 'تكوين 18:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 25, 'حَاشَا لَكَ أَنْ تَفْعَلَ مِثْلَ هَذَا الْأَمْرِ، أَنْ تُمِيتَ الْبَارَّ مَعَ الْأَثِيمِ، فَيَكُونُ الْبَارُّ كَالْأَثِيمِ. حَاشَا لَكَ! أَدَيَّانُ كُلِّ الْأَرْضِ لَا يَصْنَعُ عَدْلًا؟»', 'تكوين 18:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 26, 'فَقَالَ الرَّبُّ׃ «إِنْ وَجَدْتُ فِي سَدُومَ خَمْسِينَ بَارًّا فِي الْمَدِينَةِ، فَإِنِّي أَصْفَحُ عَنِ الْمَكَانِ كُلِّهِ مِنْ أَجْلِهِمْ».', 'تكوين 18:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 27, 'فَأَجَابَ إِبْرَاهِيمُ وَقَالَ׃ «إِنِّي قَدْ شَرَعْتُ أُكَلِّمُ الْمَوْلَى وَأَنَا تُرَابٌ وَرَمَادٌ.', 'تكوين 18:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 28, 'رُبَّمَا نَقَصَ الْخَمْسُونَ بَارًّا خَمْسَةً. أَتُهْلِكُ كُلَّ الْمَدِينَةِ بِالْخَمْسَةِ؟» فَقَالَ׃ «لَا أُهْلِكُ إِنْ وَجَدْتُ هُنَاكَ خَمْسَةً وَأَرْبَعِينَ».', 'تكوين 18:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 29, 'فَعَادَ يُكَلِّمُهُ أَيْضًا وَقَالَ׃ «عَسَى أَنْ يُوجَدَ هُنَاكَ أَرْبَعُونَ». فَقَالَ׃ «لَا أَفْعَلُ مِنْ أَجْلِ الْأَرْبَعِينَ».', 'تكوين 18:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 30, 'فَقَالَ׃ «لَا يَسْخَطِ الْمَوْلَى فَأَتَكَلَّمَ. عَسَى أَنْ يُوجَدَ هُنَاكَ ثَلَاثُونَ». فَقَالَ׃ «لَا أَفْعَلُ إِنْ وَجَدْتُ هُنَاكَ ثَلَاثِينَ».', 'تكوين 18:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 31, 'فَقَالَ׃ «إِنِّي قَدْ شَرَعْتُ أُكَلِّمُ الْمَوْلَى. عَسَى أَنْ يُوجَدَ هُنَاكَ عِشْرُونَ». فَقَالَ׃ «لَا أُهْلِكُ مِنْ أَجْلِ الْعِشْرِينَ».', 'تكوين 18:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 32, 'فَقَالَ׃ «لَا يَسْخَطِ الْمَوْلَى فَأَتَكَلَّمَ هَذِهِ الْمَرَّةَ فَقَطْ. عَسَى أَنْ يُوجَدَ هُنَاكَ عَشْرَةٌ». فَقَالَ׃ «لَا أُهْلِكُ مِنْ أَجْلِ الْعَشْرَةِ».', 'تكوين 18:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 18, 33, 'وَذَهَبَ الرَّبُّ عِنْدَمَا فَرَغَ مِنَ الْكَلَامِ مَعَ إِبْرَاهِيمَ، وَرَجَعَ إِبْرَاهِيمُ إِلَى مَكَانِهِ.', 'تكوين 18:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 1, 'فَجَاءَ الْمَلَاكَانِ إِلَى سَدُومَ مَسَاءً، وَكَانَ لُوطٌ جَالِسًا فِي بَابِ سَدُومَ. فَلَمَّا رَآهُمَا لُوطٌ قَامَ لِاسْتِقْبَالِهِمَا، وَسَجَدَ بِوَجْهِهِ إِلَى الْأَرْضِ.', 'تكوين 19:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 2, 'وَقَالَ׃ «يَا سَيِّدَيَّ، مِيلَا إِلَى بَيْتِ عَبْدِكُمَا وَبِيتَا وَاغْسِلَا أَرْجُلَكُمَا، ثُمَّ تُبَكِّرَانِ وَتَذْهَبَانِ فِي طَرِيقِكُمَا». فَقَالَا׃ «لَا، بَلْ فِي السَّاحَةِ نَبِيتُ».', 'تكوين 19:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 3, 'فَأَلَحَّ عَلَيْهِمَا جِدًّا، فَمَالَا إِلَيْهِ وَدَخَلَا بَيْتَهُ، فَصَنَعَ لَهُمَا ضِيَافَةً وَخَبَزَ فَطِيرًا فَأَكَلَا.', 'تكوين 19:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 4, 'وَقَبْلَمَا اضْطَجَعَا أَحَاطَ بِالْبَيْتِ رِجَالُ الْمَدِينَةِ، رِجَالُ سَدُومَ، مِنَ الْحَدَثِ إِلَى الشَّيْخِ، كُلُّ الشَّعْبِ مِنْ أَقْصَاهَا.', 'تكوين 19:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 5, 'فَنَادَوْا لُوطًا وَقَالُوا لَهُ׃ «أَيْنَ الرَّجُلَانِ اللَّذَانِ دَخَلَا إِلَيْكَ اللَّيْلَةَ؟ أَخْرِجْهُمَا إِلَيْنَا لِنَعْرِفَهُمَا».', 'تكوين 19:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 6, 'فَخَرَجَ إِلَيْهِمْ لُوطٌ إِلَى الْبَابِ وَأَغْلَقَ الْبَابَ وَرَاءَهُ', 'تكوين 19:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 7, 'وَقَالَ׃ «لَا تَفْعَلُوا شَرًّا يَا إِخْوَتِي.', 'تكوين 19:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 8, 'هُوَذَا لِي ابْنَتَانِ لَمْ تَعْرِفَا رَجُلًا. أُخْرِجُهُمَا إِلَيْكُمْ فَافْعَلُوا بِهِمَا كَمَا يَحْسُنُ فِي عُيُونِكُمْ. وَأَمَّا هَذَانِ الرَّجُلَانِ فَلَا تَفْعَلُوا بِهِمَا شَيْئًا، لِأَنَّهُمَا قَدْ دَخَلَا تَحْتَ ظِلِّ سَقْفِي».', 'تكوين 19:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 9, 'فَقَالُوا׃ «ابْعُدْ إِلَى هُنَاكَ». ثُمَّ قَالُوا׃ «جَاءَ هَذَا الْإِنْسَانُ لِيَتَغَرَّبَ، وَهُوَ يَحْكُمُ حُكْمًا. الْآنَ نَفْعَلُ بِكَ شَرًّا أَكْثَرَ مِنْهُمَا». فَأَلَحُّوا عَلَى الْرَّجُلِ لُوطٍ جِدًّا وَتَقَدَّمُوا لِيُكَسِّرُوا الْبَابَ،', 'تكوين 19:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 10, 'فَمَدَّ الرَّجُلَانِ أَيْدِيَهُمَا وَأَدْخَلَا لُوطًا إِلَيْهِمَا إِلَى الْبَيْتِ وَأَغْلَقَا الْبَابَ.', 'تكوين 19:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 11, 'وَأَمَّا الرِّجَالُ الَّذِينَ عَلَى بَابِ الْبَيْتِ فَضَرَبَاهُمْ بِالْعَمَى، مِنَ الصَّغِيرِ إِلَى الْكَبِيرِ، فَعَجِزُوا عَنْ أَنْ يَجِدُوا الْبَابَ.', 'تكوين 19:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 12, 'وَقَالَ الرَّجُلَانِ لِلُوطٍ׃ «مَنْ لَكَ أَيْضًا هَهُنَا؟ أَصْهَارَكَ وَبَنِيكَ وَبَنَاتِكَ وَكُلَّ مَنْ لَكَ فِي الْمَدِينَةِ، أَخْرِجْ مِنَ الْمَكَانِ،', 'تكوين 19:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 13, 'لِأَنَّنَا مُهْلِكَانِ هَذَا الْمَكَانَ، إِذْ قَدْ عَظُمَ صُرَاخُهُمْ أَمَامَ الرَّبِّ، فَأَرْسَلَنَا الرَّبُّ لِنُهْلِكَهُ».', 'تكوين 19:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 14, 'فَخَرَجَ لُوطٌ وَكَلَّمَ أَصْهَارَهُ الْآخِذِينَ بَنَاتِهِ وَقَالَ׃ «قُومُوا اخْرُجُوا مِنْ هَذَا الْمَكَانِ، لِأَنَّ الرَّبَّ مُهْلِكٌ الْمَدِينَةَ». فَكَانَ كَمَازِحٍ فِي أَعْيُنِ أَصْهَارِهِ.', 'تكوين 19:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 15, 'وَلَمَّا طَلَعَ الْفَجْرُ كَانَ الْمَلَاكَانِ يُعَجِّلَانِ لُوطًا قَائِلَيْنِ׃ «قُمْ خُذِ امْرَأَتَكَ وَابْنَتَيْكَ الْمَوْجُودَتَيْنِ لِئَلَّا تَهْلِكَ بِإِثْمِ الْمَدِينَةِ».', 'تكوين 19:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 16, 'وَلَمَّا تَوَانَى، أَمْسَكَ الرَّجُلَانِ بِيَدِهِ وَبِيَدِ امْرَأَتِهِ وَبِيَدِ ابْنَتَيْهِ، لِشَفَقَةِ الرَّبِّ عَلَيْهِ، وَأَخْرَجَاهُ وَوَضَعَاهُ خَارِجَ الْمَدِينَةِ.', 'تكوين 19:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 17, 'وَكَانَ لَمَّا أَخْرَجَاهُمْ إِلَى خَارِجٍ أَنَّهُ قَالَ׃ «اهْرُبْ لِحَيَاتِكَ. لَا تَنْظُرْ إِلَى وَرَائِكَ، وَلَا تَقِفْ فِي كُلِّ الدَّائِرَةِ. اهْرُبْ إِلَى الْجَبَلِ لِئَلَّا تَهْلِكَ».', 'تكوين 19:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 18, 'فَقَالَ لَهُمَا لُوطٌ׃ «لَا يَا سَيِّدُ.', 'تكوين 19:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 19, 'هُوَذَا عَبْدُكَ قَدْ وَجَدَ نِعْمَةً فِي عَيْنَيْكَ، وَعَظَّمْتَ لُطْفَكَ الَّذِي صَنَعْتَ إِلَيَّ بِاسْتِبْقَاءِ نَفْسِي، وَأَنَا لَا أَقْدِرُ أَنْ أَهْرُبَ إِلَى الْجَبَلِ لَعَلَّ الشَّرَّ يُدْرِكُنِي فَأَمُوتَ.', 'تكوين 19:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 20, 'هُوَذَا الْمَدِينَةُ هَذِهِ قَرِيبَةٌ لِلْهَرَبِ إِلَيْهَا وَهِيَ صَغِيرَةٌ. أَهْرُبُ إِلَى هُنَاكَ. أَلَيْسَتْ هِيَ صَغِيرَةً؟ فَتَحْيَا نَفْسِي».', 'تكوين 19:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 21, 'فَقَالَ لَهُ׃ «إِنِّي قَدْ رَفَعْتُ وَجْهَكَ فِي هَذَا الْأَمْرِ أَيْضًا، أَنْ لَا أَقْلِبَ الْمَدِينَةَ الَّتِي تَكَلَّمْتَ عَنْهَا.', 'تكوين 19:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 22, 'أَسْرِعِ اهْرُبْ إِلَى هُنَاكَ لِأَنِّي لَا أَسْتَطِيعُ أَنْ أَفْعَلَ شَيْئًا حَتَّى تَجِيءَ إِلَى هُنَاكَ». لِذَلِكَ دُعِيَ اسْمُ الْمَدِينَةِ «صُوغَرَ».', 'تكوين 19:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 23, 'وَإِذْ أَشْرَقَتِ الشَّمْسُ عَلَى الْأَرْضِ دَخَلَ لُوطٌ إِلَى صُوغَرَ،', 'تكوين 19:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 24, 'فَأَمْطَرَ الرَّبُّ عَلَى سَدُومَ وَعَمُورَةَ كِبْرِيتًا وَنَارًا مِنْ عِنْدِ الرَّبِّ مِنَ السَّمَاءِ.', 'تكوين 19:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 25, 'وَقَلَبَ تِلْكَ الْمُدُنَ، وَكُلَّ الدَّائِرَةِ، وَجَمِيعَ سُكَّانِ الْمُدُنِ، وَنَبَاتِ الْأَرْضِ.', 'تكوين 19:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 26, 'وَنَظَرَتِ امْرَأَتُهُ مِنْ وَرَائِهِ فَصَارَتْ عَمُودَ مِلْحٍ.', 'تكوين 19:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 27, 'وَبَكَّرَ إِبْرَاهِيمُ فِي الْغَدِ إِلَى الْمَكَانِ الَّذِي وَقَفَ فِيهِ أَمَامَ الرَّبِّ،', 'تكوين 19:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 28, 'وَتَطَلَّعَ نَحْوَ سَدُومَ وَعَمُورَةَ، وَنَحْوَ كُلِّ أَرْضِ الدَّائِرَةِ، وَنَظَرَ وَإِذَا دُخَانُ الْأَرْضِ يَصْعَدُ كَدُخَانِ الْأَتُونِ.', 'تكوين 19:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 29, 'وَحَدَثَ لَمَّا أَخْرَبَ اللهُ مُدُنَ الدَّائِرَةِ أَنَّ اللهَ ذَكَرَ إِبْرَاهِيمَ، وَأَرْسَلَ لُوطًا مِنْ وَسَطِ الِانْقِلَابِ. حِينَ قَلَبَ الْمُدُنَ الَّتِي سَكَنَ فِيهَا لُوطٌ.', 'تكوين 19:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 30, 'وَصَعِدَ لُوطٌ مِنْ صُوغَرَ وَسَكَنَ فِي الْجَبَلِ، وَابْنَتَاهُ مَعَهُ، لِأَنَّهُ خَافَ أَنْ يَسْكُنَ فِي صُوغَرَ. فَسَكَنَ فِي الْمَغَارَةِ هُوَ وَابْنَتَاهُ.', 'تكوين 19:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 31, 'وَقَالَتِ الْبِكْرُ لِلصَّغِيرَةِ׃ «أَبُونَا قَدْ شَاخَ، وَلَيْسَ فِي الْأَرْضِ رَجُلٌ لِيَدْخُلَ عَلَيْنَا كَعَادَةِ كُلِّ الْأَرْضِ.', 'تكوين 19:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 32, 'هَلُمَّ نَسْقِي أَبَانَا خَمْرًا وَنَضْطَجِعُ مَعَهُ، فَنُحْيِي مِنْ أَبِينَا نَسْلًا».', 'تكوين 19:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 33, 'فَسَقَتَا أَبَاهُمَا خَمْرًا فِي تِلْكَ اللَّيْلَةِ، وَدَخَلَتِ الْبِكْرُ وَاضْطَجَعَتْ مَعَ أَبِيهَا، وَلَمْ يَعْلَمْ بِاضْطِجَاعِهَا وَلَا بِقِيَامِهَا.', 'تكوين 19:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 34, 'وَحَدَثَ فِي الْغَدِ أَنَّ الْبِكْرَ قَالَتْ لِلصَّغِيرَةِ׃ «إِنِّي قَدِ اضْطَجَعْتُ الْبَارِحَةَ مَعَ أَبِي. نَسْقِيهِ خَمْرًا اللَّيْلَةَ أَيْضًا فَادْخُلِي اضْطَجِعِي مَعَهُ، فَنُحْيِيَ مِنْ أَبِينَا نَسْلًا».', 'تكوين 19:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 35, 'فَسَقَتَا أَبَاهُمَا خَمْرًا فِي تِلْكَ اللَّيْلَةِ أَيْضًا، وَقَامَتِ الصَّغِيرَةُ وَاضْطَجَعَتْ مَعَهُ، وَلَمْ يَعْلَمْ بِاضْطِجَاعِهَا وَلَا بِقِيَامِهَا،', 'تكوين 19:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 36, 'فَحَبِلَتِ ابْنَتَا لُوطٍ مِنْ أَبِيهِمَا.', 'تكوين 19:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 37, 'فَوَلَدَتِ الْبِكْرُ ابْنًا وَدَعَتِ اسْمَهُ «مُوآبَ»، وَهُوَ أَبُو الْمُوآبِيِّينَ إِلَى الْيَوْمِ.', 'تكوين 19:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 19, 38, 'وَالصَّغِيرَةُ أَيْضًا وَلَدَتِ ابْنًا وَدَعَتِ اسْمَهُ «بِنْ عَمِّي»، وَهُوَ أَبُو بَنِي عَمُّونَ إِلَى الْيَوْمِ.', 'تكوين 19:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 1, 'وَانْتَقَلَ إِبْرَاهِيمُ مِنْ هُنَاكَ إِلَى أَرْضِ الْجَنُوبِ، وَسَكَنَ بَيْنَ قَادِشَ وَشُورَ، وَتَغَرَّبَ فِي جَرَارَ.', 'تكوين 20:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 2, 'وَقَالَ إِبْرَاهِيمُ عَنْ سَارَةَ امْرَأَتِهِ׃ «هِيَ أُخْتِي». فَأَرْسَلَ أَبِيمَالِكُ مَلِكُ جَرَارَ وَأَخَذَ سَارَةَ.', 'تكوين 20:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 3, 'فَجَاءَ اللهُ إِلَى أَبِيمَالِكَ فِي حُلْمِ اللَّيْلِ وَقَالَ لَهُ׃ «هَا أَنْتَ مَيِّتٌ مِنْ أَجْلِ الْمَرْأَةِ الَّتِي أَخَذْتَهَا، فَإِنَّهَا مُتَزَوِّجَةٌ بِبَعْلٍ».', 'تكوين 20:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 4, 'وَلَكِنْ لَمْ يَكُنْ أَبِيمَالِكُ قَدِ اقْتَرَبَ إِلَيْهَا، فَقَالَ׃ «يَا سَيِّدُ، أَأُمَّةً بَارَّةً تَقْتُلُ؟', 'تكوين 20:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 5, 'أَلَمْ يَقُلْ هُوَ لِي׃ إِنَّهَا أُخْتِي، وَهِيَ أَيْضًا نَفْسُهَا قَالَتْ׃ هُوَ أَخِي؟ بِسَلَامَةِ قَلْبِي وَنَقَاوَةِ يَدَيَّ فَعَلْتُ هَذَا».', 'تكوين 20:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 6, 'فَقَالَ لَهُ اللهُ فِي الْحُلْمِ׃ «أَنَا أَيْضًا عَلِمْتُ أَنَّكَ بِسَلَامَةِ قَلْبِكَ فَعَلْتَ هَذَا. وَأَنَا أَيْضًا أَمْسَكْتُكَ عَنْ أَنْ تُخْطِئَ إِلَيَّ، لِذَلِكَ لَمْ أَدَعْكَ تَمَسُّهَا.', 'تكوين 20:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 7, 'فَالْآنَ رُدَّ امْرَأَةَ الرَّجُلِ، فَإِنَّهُ نَبِيٌّ، فَيُصَلِّيَ لِأَجْلِكَ فَتَحْيَا. وَإِنْ كُنْتَ لَسْتَ تَرُدُّهَا، فَاعْلَمْ أَنَّكَ مَوْتًا تَمُوتُ، أَنْتَ وَكُلُّ مَنْ لَكَ».', 'تكوين 20:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 8, 'فَبَكَّرَ أَبِيمَالِكُ فِي الْغَدِ وَدَعَا جَمِيعَ عَبِيدِهِ، وَتَكَلَّمَ بِكُلِّ هَذَا الْكَلَامِ فِي مَسَامِعِهِمْ، فَخَافَ الرِّجَالُ جِدًّا.', 'تكوين 20:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 9, 'ثُمَّ دَعَا أَبِيمَالِكُ إِبْرَاهِيمَ وَقَالَ لَهُ׃ «مَاذَا فَعَلْتَ بِنَا؟ وَبِمَاذَا أَخْطَأْتُ إِلَيْكَ حَتَّى جَلَبْتَ عَلَيَّ وَعَلَى مَمْلَكَتِي خَطِيَّةً عَظِيمَةً؟ أَعْمَالًا لَا تُعْمَلُ عَمِلْتَ بِي».', 'تكوين 20:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 10, 'وَقَالَ أَبِيمَالِكُ لِإِبْرَاهِيمَ׃ «مَاذَا رَأَيْتَ حَتَّى عَمِلْتَ هَذَا الشَّيْءَ؟»', 'تكوين 20:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 11, 'فَقَالَ إِبْرَاهِيمُ׃ «إِنِّي قُلْتُ׃ لَيْسَ فِي هَذَا الْمَوْضِعِ خَوْفُ اللهِ الْبَتَّةَ، فَيَقْتُلُونَنِي لِأَجْلِ امْرَأَتِي.', 'تكوين 20:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 12, 'وَبِالْحَقِيقَةِ أَيْضًا هِيَ أُخْتِي ابْنَةُ أَبِي، غَيْرَ أَنَّهَا لَيْسَتِ ابْنَةَ أُمِّي، فَصَارَتْ لِي زَوْجَةً.', 'تكوين 20:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 13, 'وَحَدَثَ لَمَّا أَتَاهَنِي اللهُ مِنْ بَيْتِ أَبِي أَنِّي قُلْتُ لَهَا׃ هَذَا مَعْرُوفُكِ الَّذِي تَصْنَعِينَ إِلَيَّ׃ فِي كُلِّ مَكَانٍ نَأْتِي إِلَيْهِ قُولِي عَنِّي׃ هُوَ أَخِي».', 'تكوين 20:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 14, 'فَأَخَذَ أَبِيمَالِكُ غَنَمًا وَبَقَرًا وَعَبِيدًا وَإِمَاءً وَأَعْطَاهَا لِإِبْرَاهِيمَ، وَرَدَّ إِلَيْهِ سَارَةَ امْرَأَتَهُ.', 'تكوين 20:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 15, 'وَقَالَ أَبِيمَالِكُ׃ «هُوَذَا أَرْضِي قُدَّامَكَ. اسْكُنْ فِي مَا حَسُنَ فِي عَيْنَيْكَ».', 'تكوين 20:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 16, 'وَقَالَ لِسَارَةَ׃ «إِنِّي قَدْ أَعْطَيْتُ أَخَاكِ أَلْفًا مِنَ الْفِضَّةِ. هَا هُوَ لَكِ غِطَاءُ عَيْنٍ مِنْ جِهَةِ كُلِّ مَا عِنْدَكِ وَعِنْدَ كُلِّ وَاحِدٍ، فَأُنْصِفْتِ».', 'تكوين 20:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 17, 'فَصَلَّى إِبْرَاهِيمُ إِلَى اللهِ، فَشَفَى اللهُ أَبِيمَالِكَ وَامْرَأَتَهُ وَجَوَارِيَهُ فَوَلَدْنَ.', 'تكوين 20:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 20, 18, 'لِأَنَّ الرَّبَّ كَانَ قَدْ أَغْلَقَ كُلَّ رَحِمٍ لِبَيْتِ أَبِيمَالِكَ بِسَبَبِ سَارَةَ امْرَأَةِ إِبْرَاهِيمَ.', 'تكوين 20:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 1, 'وَافْتَقَدَ الرَّبُّ سَارَةَ كَمَا قَالَ، وَفَعَلَ الرَّبُّ لِسَارَةَ كَمَا تَكَلَّمَ.', 'تكوين 21:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 2, 'فَحَبِلَتْ سَارَةُ وَوَلَدَتْ لِإِبْرَاهِيمَ ابْنًا فِي شَيْخُوخَتِهِ، فِي الْوَقْتِ الَّذِي تَكَلَّمَ اللهُ عَنْهُ.', 'تكوين 21:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 3, 'وَدَعَا إِبْرَاهِيمُ اسْمَ ابْنِهِ الْمَوْلُودِ لَهُ، الَّذِي وَلَدَتْهُ لَهُ سَارَةُ «إِسْحَاقَ».', 'تكوين 21:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 4, 'وَخَتَنَ إِبْرَاهِيمُ إِسْحَاقَ ابْنَهُ وَهُوَ ابْنُ ثَمَانِيَةِ أَيَّامٍ كَمَا أَمَرَهُ اللهُ.', 'تكوين 21:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 5, 'وَكَانَ إِبْرَاهِيمُ ابْنَ مِئَةِ سَنَةٍ حِينَ وُلِدَ لَهُ إِسْحَاقُ ابْنُهُ.', 'تكوين 21:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 6, 'وَقَالَتْ سَارَةُ׃ «قَدْ صَنَعَ إِلَيَّ اللهُ ضِحْكًا. كُلُّ مَنْ يَسْمَعُ يَضْحَكُ لِي».', 'تكوين 21:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 7, 'وَقَالَتْ׃ «مَنْ قَالَ لِإِبْرَاهِيمَ׃ سَارَةُ تُرْضِعُ بَنِينَ؟ حَتَّى وَلَدْتُ ابْنًا فِي شَيْخُوخَتِهِ!».', 'تكوين 21:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 8, 'فَكَبِرَ الْوَلَدُ وَفُطِمَ. وَصَنَعَ إِبْرَاهِيمُ وَلِيمَةً عَظِيمَةً يَوْمَ فِطَامِ إِسْحَاقَ.', 'تكوين 21:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 9, 'وَرَأَتْ سَارَةُ ابْنَ هَاجَرَ الْمِصْرِيَّةِ الَّذِي وَلَدَتْهُ لِإِبْرَاهِيمَ يَمْزَحُ،', 'تكوين 21:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 10, 'فَقَالَتْ لِإِبْرَاهِيمَ׃ «اطْرُدْ هَذِهِ الْجَارِيَةَ وَابْنَهَا، لِأَنَّ ابْنَ هَذِهِ الْجَارِيَةِ لَا يَرِثُ مَعَ ابْنِي إِسْحَاقَ».', 'تكوين 21:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 11, 'فَقَبُحَ الْكَلَامُ جِدًّا فِي عَيْنَيْ إِبْرَاهِيمَ لِسَبَبِ ابْنِهِ.', 'تكوين 21:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 12, 'فَقَالَ اللهُ لِإِبْرَاهِيمَ׃ «لَا يَقْبُحُ فِي عَيْنَيْكَ مِنْ أَجْلِ الْغُلَامِ وَمِنْ أَجْلِ جَارِيَتِكَ. فِي كُلِّ مَا تَقُولُ لَكَ سَارَةُ اسْمَعْ لِقَوْلِهَا، لِأَنَّهُ بِإِسْحَاقَ يُدْعَى لَكَ نَسْلٌ.', 'تكوين 21:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 13, 'وَابْنُ الْجَارِيَةِ أَيْضًا سَأَجْعَلُهُ أُمَّةً لِأَنَّهُ نَسْلُكَ».', 'تكوين 21:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 14, 'فَبَكَّرَ إِبْرَاهِيمُ صَبَاحًا وَأَخَذَ خُبْزًا وَقِرْبَةَ مَاءٍ وَأَعْطَاهُمَا لِهَاجَرَ، وَاضِعًا إِيَّاهُمَا عَلَى كَتِفِهَا، وَالْوَلَدَ، وَصَرَفَهَا. فَمَضَتْ وَتَاهَتْ فِي بَرِّيَّةِ بِئْرِ سَبْعٍ.', 'تكوين 21:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 15, 'وَلَمَّا فَرَغَ الْمَاءُ مِنَ الْقِرْبَةِ طَرَحَتِ الْوَلَدَ تَحْتَ إِحْدَى الْأَشْجَارِ،', 'تكوين 21:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 16, 'وَمَضَتْ وَجَلَسَتْ مُقَابِلَهُ بَعِيدًا نَحْوَ رَمْيَةِ قَوْسٍ، لِأَنَّهَا قَالَتْ׃ «لَا أَنْظُرُ مَوْتَ الْوَلَدِ». فَجَلَسَتْ مُقَابِلَهُ وَرَفَعَتْ صَوْتَهَا وَبَكَتْ.', 'تكوين 21:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 17, 'فَسَمِعَ اللهُ صَوْتَ الْغُلَامِ، وَنَادَى مَلَاكُ اللهِ هَاجَرَ مِنَ السَّمَاءِ وَقَالَ لَهَا׃ «مَا لَكِ يَا هَاجَرُ؟ لَا تَخَافِي، لِأَنَّ اللهَ قَدْ سَمِعَ لِصَوْتِ الْغُلَامِ حَيْثُ هُوَ.', 'تكوين 21:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 18, 'قُومِي احْمِلِي الْغُلَامَ وَشُدِّي يَدَكِ بِهِ، لِأَنِّي سَأَجْعَلُهُ أُمَّةً عَظِيمَةً».', 'تكوين 21:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 19, 'وَفَتَحَ اللهُ عَيْنَيْهَا فَأَبْصَرَتْ بِئْرَ مَاءٍ، فَذَهَبَتْ وَمَلَأَتِ الْقِرْبَةَ مَاءً وَسَقَتِ الْغُلَامَ.', 'تكوين 21:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 20, 'وَكَانَ اللهُ مَعَ الْغُلَامِ فَكَبِرَ، وَسَكَنَ فِي الْبَرِّيَّةِ، وَكَانَ يَنْمُو رَامِيَ قَوْسٍ.', 'تكوين 21:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 21, 'وَسَكَنَ فِي بَرِّيَّةِ فَارَانَ، وَأَخَذَتْ لَهُ أُمُّهُ زَوْجَةً مِنْ أَرْضِ مِصْرَ.', 'تكوين 21:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 22, 'وَحَدَثَ فِي ذَلِكَ الزَّمَانِ أَنَّ أَبِيمَالِكَ وَفِيكُولَ رَئِيسَ جَيْشِهِ كَلَّمَا إِبْرَاهِيمَ قَائِلَيْنِ׃ «اللهُ مَعَكَ فِي كُلِّ مَا أَنْتَ صَانِعٌ.', 'تكوين 21:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 23, 'فَالْآنَ احْلِفْ لِي بِاللهِ هَهُنَا أَنَّكَ لَا تَغْدُرُ بِي وَلَا بِنَسْلِي وَذُرِّيَّتِي، كَالْمَعْرُوفِ الَّذِي صَنَعْتُ إِلَيْكَ تَصْنَعُ إِلَيَّ وَإِلَى الْأَرْضِ الَّتِي تَغَرَّبْتَ فِيهَا».', 'تكوين 21:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 24, 'فَقَالَ إِبْرَاهِيمُ׃ «أَنَا أَحْلِفُ».', 'تكوين 21:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 25, 'وَعَاتَبَ إِبْرَاهِيمُ أَبِيمَالِكَ لِسَبَبِ بِئْرِ الْمَاءِ الَّتِي اغْتَصَبَهَا عَبِيدُ أَبِيمَالِكَ.', 'تكوين 21:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 26, 'فَقَالَ أَبِيمَالِكُ׃ «لَمْ أَعْلَمْ مَنْ فَعَلَ هَذَا الْأَمْرَ. أَنْتَ لَمْ تُخْبِرْنِي، وَلَا أَنَا سَمِعْتُ سِوَى الْيَوْمِ».', 'تكوين 21:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 27, 'فَأَخَذَ إِبْرَاهِيمُ غَنَمًا وَبَقَرًا وَأَعْطَى أَبِيمَالِكَ، فَقَطَعَا كِلَاهُمَا مِيثَاقًا.', 'تكوين 21:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 28, 'وَأَقَامَ إِبْرَاهِيمُ سَبْعَ نِعَاجٍ مِنَ الْغَنَمِ وَحْدَهَا.', 'تكوين 21:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 29, 'فَقَالَ أَبِيمَالِكُ لِإِبْرَاهِيمَ׃ «مَا هِيَ هَذِهِ السَّبْعُ النِّعَاجِ الَّتِي أَقَمْتَهَا وَحْدَهَا؟»', 'تكوين 21:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 30, 'فَقَالَ׃ «إِنَّكَ سَبْعَ نِعَاجٍ تَأْخُذُ مِنْ يَدِي، لِكَيْ تَكُونَ لِي شَهَادَةً بِأَنِّي حَفَرْتُ هَذِهِ الْبِئْرَ».', 'تكوين 21:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 31, 'لِذَلِكَ دَعَا ذَلِكَ الْمَوْضِعَ «بِئْرَ سَبْعٍ»، لِأَنَّهُمَا هُنَاكَ حَلَفَا كِلَاهُمَا.', 'تكوين 21:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 32, 'فَقَطَعَا مِيثَاقًا فِي بِئْرِ سَبْعٍ، ثُمَّ قَامَ أَبِيمَالِكُ وَفِيكُولُ رَئِيسُ جَيْشِهِ وَرَجَعَا إِلَى أَرْضِ الْفِلِسْطِينِيِّينَ.', 'تكوين 21:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 33, 'وَغَرَسَ إِبْرَاهِيمُ أَثْلًا فِي بِئْرِ سَبْعٍ، وَدَعَا هُنَاكَ بِاسْمِ الرَّبِّ الْإِلَهِ السَّرْمَدِيِّ.', 'تكوين 21:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 21, 34, 'وَتَغَرَّبَ إِبْرَاهِيمُ فِي أَرْضِ الْفِلِسْطِينِيِّينَ أَيَّامًا كَثِيرَةً.', 'تكوين 21:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 1, 'وَحَدَثَ بَعْدَ هَذِهِ الْأُمُورِ أَنَّ اللهَ امْتَحَنَ إِبْرَاهِيمَ، فَقَالَ لَهُ׃ «يَا إِبْرَاهِيمُ!». فَقَالَ׃ «هَأَنَذَا».', 'تكوين 22:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 2, 'فَقَالَ׃ «خُذِ ابْنَكَ وَحِيدَكَ، الَّذِي تُحِبُّهُ، إِسْحَاقَ، وَاذْهَبْ إِلَى أَرْضِ الْمُرِيَّا، وَأَصْعِدْهُ هُنَاكَ مُحْرَقَةً عَلَى أَحَدِ الْجِبَالِ الَّذِي أَقُولُ لَكَ».', 'تكوين 22:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 3, 'فَبَكَّرَ إِبْرَاهِيمُ صَبَاحًا وَشَدَّ عَلَى حِمَارِهِ، وَأَخَذَ اثْنَيْنِ مِنْ غِلْمَانِهِ مَعَهُ، وَإِسْحَاقَ ابْنَهُ، وَشَقَّقَ حَطَبًا لِمُحْرَقَةٍ، وَقَامَ وَذَهَبَ إِلَى الْمَوْضِعِ الَّذِي قَالَ لَهُ اللهُ.', 'تكوين 22:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 4, 'وَفِي الْيَوْمِ الثَّالِثِ رَفَعَ إِبْرَاهِيمُ عَيْنَيْهِ وَأَبْصَرَ الْمَوْضِعَ مِنْ بَعِيدٍ،', 'تكوين 22:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 5, 'فَقَالَ إِبْرَاهِيمُ لِغُلَامَيْهِ׃ «اجْلِسَا أَنْتُمَا هَهُنَا مَعَ الْحِمَارِ، وَأَمَّا أَنَا وَالْغُلَامُ فَنَذْهَبُ إِلَى هُنَاكَ وَنَسْجُدُ، ثُمَّ نَرْجِعُ إِلَيْكُمَا».', 'تكوين 22:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 6, 'فَأَخَذَ إِبْرَاهِيمُ حَطَبَ الْمُحْرَقَةِ وَوَضَعَهُ عَلَى إِسْحَاقَ ابْنِهِ، وَأَخَذَ بِيَدِهِ النَّارَ وَالسِّكِّينَ. فَذَهَبَا كِلَاهُمَا مَعًا.', 'تكوين 22:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 7, 'وَكَلَّمَ إِسْحَاقُ إِبْرَاهِيمَ أَبِاهُ وَقَالَ׃ «يَا أَبِي!». فَقَالَ׃ «هَأَنَذَا يَا ابْنِي». فَقَالَ׃ «هُوَذَا النَّارُ وَالْحَطَبُ، وَلَكِنْ أَيْنَ الْخَرُوفُ لِلْمُحْرَقَةِ؟».', 'تكوين 22:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 8, 'فَقَالَ إِبْرَاهِيمُ׃ «اللهُ يَرَى لَهُ الْخَرُوفَ لِلْمُحْرَقَةِ يَا ابْنِي». فَذَهَبَا كِلَاهُمَا مَعًا.', 'تكوين 22:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 9, 'فَلَمَّا أَتَيَا إِلَى الْمَوْضِعِ الَّذِي قَالَ لَهُ اللهُ، بَنَى هُنَاكَ إِبْرَاهِيمُ الْمَذْبَحَ وَرَتَّبَ الْحَطَبَ وَرَبَطَ إِسْحَاقَ ابْنَهُ وَوَضَعَهُ عَلَى الْمَذْبَحِ فَوْقَ الْحَطَبِ.', 'تكوين 22:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 10, 'ثُمَّ مَدَّ إِبْرَاهِيمُ يَدَهُ وَأَخَذَ السِّكِّينَ لِيَذْبَحَ ابْنَهُ.', 'تكوين 22:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 11, 'فَنَادَاهُ مَلَاكُ الرَّبِّ مِنَ السَّمَاءِ وَقَالَ׃ «إِبْرَاهِيمُ! إِبْرَاهِيمُ!». فَقَالَ׃ «هَأَنَذَا».', 'تكوين 22:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 12, 'فَقَالَ׃ «لَا تَمُدَّ يَدَكَ إِلَى الْغُلَامِ وَلَا تَفْعَلْ بِهِ شَيْئًا، لِأَنِّي الْآنَ عَلِمْتُ أَنَّكَ خَائِفٌ اللهَ، فَلَمْ تُمْسِكِ ابْنَكَ وَحِيدَكَ عَنِّي».', 'تكوين 22:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 13, 'فَرَفَعَ إِبْرَاهِيمُ عَيْنَيْهِ وَنَظَرَ وَإِذَا كَبْشٌ وَرَاءَهُ مُمْسَكًا فِي الْغَابَةِ بِقَرْنَيْهِ، فَذَهَبَ إِبْرَاهِيمُ وَأَخَذَ الْكَبْشَ وَأَصْعَدَهُ مُحْرَقَةً عِوَضًا عَنِ ابْنِهِ.', 'تكوين 22:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 14, 'فَدَعَا إِبْرَاهِيمُ اسْمَ ذَلِكَ الْمَوْضِعِ «يَهْوَهْ يِرْأَهْ». حَتَّى إِنَّهُ يُقَالُ الْيَوْمَ׃ «فِي جَبَلِ الرَّبِّ يُرَى».', 'تكوين 22:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 15, 'وَنَادَى مَلَاكُ الرَّبِّ إِبْرَاهِيمَ ثَانِيَةً مِنَ السَّمَاءِ', 'تكوين 22:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 16, 'وَقَالَ׃ «بِذَاتِي أَقْسَمْتُ، يَقُولُ الرَّبُّ، أَنِّي مِنْ أَجْلِ أَنَّكَ فَعَلْتَ هَذَا الْأَمْرَ، وَلَمْ تُمْسِكِ ابْنَكَ وَحِيدَكَ،', 'تكوين 22:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 17, 'أُبَارِكُكَ مُبَارَكَةً، وَأُكَثِّرُ نَسْلَكَ تَكْثِيرًا كَنُجُومِ السَّمَاءِ وَكَالرَّمْلِ الَّذِي عَلَى شَاطِئِ الْبَحْرِ، وَيَرِثُ نَسْلُكَ بَابَ أَعْدَائِهِ،', 'تكوين 22:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 18, 'وَيَتَبَارَكُ فِي نَسْلِكَ جَمِيعُ أُمَمِ الْأَرْضِ، مِنْ أَجْلِ أَنَّكَ سَمِعْتَ لِقَوْلِي».', 'تكوين 22:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 19, 'ثُمَّ رَجَعَ إِبْرَاهِيمُ إِلَى غُلَامَيْهِ، فَقَامُوا وَذَهَبُوا مَعًا إِلَى بِئْرِ سَبْعٍ. وَسَكَنَ إِبْرَاهِيمُ فِي بِئْرِ سَبْعٍ.', 'تكوين 22:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 20, 'وَحَدَثَ بَعْدَ هَذِهِ الْأُمُورِ أَنَّ إِبْرَاهِيمَ أُخْبِرَ وَقِيلَ لَهُ׃ «هُوَذَا مِلْكَةُ قَدْ وَلَدَتْ هِيَ أَيْضًا بَنِينَ لِنَاحُورَ أَخِيكَ׃', 'تكوين 22:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 21, 'عُوصًا بِكْرَهُ، وَبُوزًا أَخَاهُ، وَقَمُوئِيلَ أَبَا أَرَامَ،', 'تكوين 22:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 22, 'وَكَاسَدَ وَحَزْوًا وَفِلْدَاشَ وَيِدْلَافَ وَبَتُوئِيلَ».', 'تكوين 22:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 23, 'وَوَلَدَ بَتُوئِيلُ رِفْقَةَ. هَؤُلَاءِ الثَّمَانِيَةُ وَلَدَتْهُمْ مِلْكَةُ لِنَاحُورَ أَخِي إِبْرَاهِيمَ.', 'تكوين 22:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 22, 24, 'وَأَمَّا سُرِّيَّتُهُ، وَاسْمُهَا رَؤُومَةُ، فَوَلَدَتْ هِيَ أَيْضًا׃ طَابَحَ وَجَاحَمَ وَتَاحَشَ وَمَعْكَةَ.', 'تكوين 22:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 1, 'وَكَانَتْ حَيَاةُ سَارَةَ مِئَةً وَسَبْعًا وَعِشْرِينَ سَنَةً، سِنِي حَيَاةِ سَارَةَ.', 'تكوين 23:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 2, 'وَمَاتَتْ سَارَةُ فِي قَرْيَةِ أَرْبَعَ، الَّتِي هِيَ حَبْرُونُ، فِي أَرْضِ كَنْعَانَ. فَأَتَى إِبْرَاهِيمُ لِيَنْدُبَ سَارَةَ وَيَبْكِيَ عَلَيْهَا.', 'تكوين 23:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 3, 'وَقَامَ إِبْرَاهِيمُ مِنْ أَمَامِ مَيِّتِهِ وَكَلَّمَ بَنِي حِثَّ قَائِلًا׃', 'تكوين 23:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 4, '«أَنَا غَرِيبٌ وَنَزِيلٌ عِنْدَكُمْ. أَعْطُونِي مُلْكَ قَبْرٍ مَعَكُمْ لِأَدْفِنَ مَيْتِي مِنْ أَمَامِي».', 'تكوين 23:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 5, 'فَأَجَابَ بَنُو حِثَّ إِبْرَاهِيمَ قَائِلِينَ لَهُ׃', 'تكوين 23:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 6, '«اِسْمَعْنَا يَا سَيِّدِي. أَنْتَ رَئِيسٌ مِنَ اللهِ بَيْنَنَا. فِي أَفْضَلِ قُبُورِنَا ادْفِنْ مَيْتَكَ، لَا يَمْنَعُ أَحَدٌ مِنَّا قَبْرَهُ عَنْكَ حَتَّى لَا تَدْفِنَ مَيْتَكَ».', 'تكوين 23:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 7, 'فَقَامَ إِبْرَاهِيمُ وَسَجَدَ لِشَعْبِ الْأَرْضِ، لِبَنِي حِثَّ،', 'تكوين 23:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 8, 'وَكَلَّمَهُمْ قَائِلًا׃ «إِنْ كَانَ فِي نُفُوسِكُمْ أَنْ أَدْفِنَ مَيْتِي مِنْ أَمَامِي، فَاسْمَعُونِي وَالْتَمِسُوا لِي مِنْ عِفْرُونَ بْنِ صُوحَرَ', 'تكوين 23:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 9, 'أَنْ يُعْطِيَنِي مَغَارَةَ الْمَكْفِيلَةِ الَّتِي لَهُ، الَّتِي فِي طَرَفِ حَقْلِهِ. بِثَمَنٍ كَامِلٍ يُعْطِينِي إِيَّاهَا فِي وَسَطِكُمْ مُلْكَ قَبْرٍ».', 'تكوين 23:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 10, 'وَكَانَ عِفْرُونُ جَالِسًا بَيْنَ بَنِي حِثَّ، فَأَجَابَ عِفْرُونُ الْحِثِّيُّ إِبْرَاهِيمَ فِي مَسَامِعِ بَنِي حِثَّ، لَدَى جَمِيعِ الدَّاخِلِينَ بَابَ مَدِينَتِهِ قَائِلًا׃', 'تكوين 23:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 11, '«لَا يَا سَيِّدِي، اسْمَعْنِي. اَلْحَقْلُ وَهَبْتُكَ إِيَّاهُ، وَالْمَغَارَةُ الَّتِي فِيهِ لَكَ وَهَبْتُهَا. لَدَى عُيُونِ بَنِي شَعْبِي وَهَبْتُكَ إِيَّاهَا. ادْفِنْ مَيْتَكَ».', 'تكوين 23:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 12, 'فَسَجَدَ إِبْرَاهِيمُ أَمَامَ شَعْبِ الْأَرْضِ،', 'تكوين 23:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 13, 'وَكَلَمَ عِفْرُونَ فِي مَسَامِعِ شَعْبِ الْأَرْضِ قَائِلًا׃ «بَلْ إِنْ كُنْتَ أَنْتَ إِيَّاهُ فَلَيْتَكَ تَسْمَعُنِي. أُعْطِيكَ ثَمَنَ الْحَقْلِ. خُذْ مِنِّي فَأَدْفِنَ مَيْتِي هُنَاكَ».', 'تكوين 23:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 14, 'فَأَجَابَ عِفْرُونُ إِبْرَاهِيمَ قَائِلًا لَهُ׃', 'تكوين 23:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 15, '«يَا سَيِّدِي، اسْمَعْنِي. أَرْضٌ بِأَرْبَعِ مِئَةِ شَاقِلِ فِضَّةٍ، مَا هِيَ بَيْنِي وَبَيْنَكَ؟ فَادْفِنْ مَيْتَكَ».', 'تكوين 23:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 16, 'فَسَمِعَ إِبْرَاهِيمُ لِعِفْرُونَ، وَوَزَنَ إِبْرَاهِيمُ لِعِفْرُونَ الْفِضَّةَ الَّتِي ذَكَرَهَا فِي مَسَامِعِ بَنِي حِثَّ. أَرْبَعَ مِئَةِ شَاقِلِ فِضَّةٍ جَائِزَةٍ عِنْدَ التُّجَّارِ.', 'تكوين 23:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 17, 'فَوَجَبَ حَقْلُ عِفْرُونَ الَّذِي فِي الْمَكْفِيلَةِ الَّتِي أَمَامَ مَمْرَا، الْحَقْلُ وَالْمَغَارَةُ الَّتِي فِيهِ، وَجَمِيعُ الشَّجَرِ الَّذِي فِي الْحَقْلِ الَّذِي فِي جَمِيعِ حُدُودِهِ حَوَالَيْهِ،', 'تكوين 23:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 18, 'لِإِبْرَاهِيمَ مُلْكًا لَدَى عُيُونِ بَنِي حِثَّ، بَيْنَ جَمِيعِ الدَّاخِلِينَ بَابَ مَدِينَتِهِ.', 'تكوين 23:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 19, 'وَبَعْدَ ذَلِكَ دَفَنَ إِبْرَاهِيمُ سَارَةَ امْرَأَتَهُ فِي مَغَارَةِ حَقْلِ الْمَكْفِيلَةِ أَمَامَ مَمْرَا، الَّتِي هِيَ حَبْرُونُ، فِي أَرْضِ كَنْعَانَ،', 'تكوين 23:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 23, 20, 'فَوَجَبَ الْحَقْلُ وَالْمَغَارَةُ الَّتِي فِيهِ لِإِبْرَاهِيمَ مُلْكَ قَبْرٍ مِنْ عِنْدِ بَنِي حِثَّ.', 'تكوين 23:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 1, 'وَشَاخَ إِبْرَاهِيمُ وَتَقَدَّمَ فِي الْأَيَّامِ. وَبَارَكَ الرَّبُّ إِبْرَاهِيمَ فِي كُلِّ شَيْءٍ.', 'تكوين 24:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 2, 'وَقَالَ إِبْرَاهِيمُ لِعَبْدِهِ كَبِيرِ بَيْتِهِ الْمُسْتَوْلِي عَلَى كُلِّ مَا كَانَ لَهُ׃ «ضَعْ يَدَكَ تَحْتَ فَخْذِي،', 'تكوين 24:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 3, 'فَأَسْتَحْلِفَكَ بِالرَّبِّ إِلَهِ السَّمَاءِ وَإِلَهِ الْأَرْضِ أَنْ لَا تَأْخُذَ زَوْجَةً لِابْنِي مِنْ بَنَاتِ الْكَنْعَانِيِّينَ الَّذِينَ أَنَا سَاكِنٌ بَيْنَهُمْ،', 'تكوين 24:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 4, 'بَلْ إِلَى أَرْضِي وَإِلَى عَشِيرَتِي تَذْهَبُ وَتَأْخُذُ زَوْجَةً لِابْنِي إِسْحَاقَ».', 'تكوين 24:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 5, 'فَقَالَ لَهُ الْعَبْدُ׃ «رُبَّمَا لَا تَشَاءُ الْمَرْأَةُ أَنْ تَتْبَعَنِي إِلَى هَذِهِ الْأَرْضِ. هَلْ أَرْجِعُ بِابْنِكَ إِلَى الْأَرْضِ الَّتِي خَرَجْتَ مِنْهَا؟»', 'تكوين 24:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 6, 'فَقَالَ لَهُ إِبْرَاهِيمُ׃ «احْتَرِزْ مِنْ أَنْ تَرْجِعَ بِابْنِي إِلَى هُنَاكَ.', 'تكوين 24:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 7, 'اَلرَّبُّ إِلَهُ السَّمَاءِ الَّذِي أَخَذَنِي مِنْ بَيْتِ أَبِي وَمِنْ أَرْضِ مِيلَادِي، وَالَّذِي كَلَّمَنِي وَالَّذِي أَقْسَمَ لِي قَائِلًا׃ لِنَسْلِكَ أُعْطِي هَذِهِ الْأَرْضَ، هُوَ يُرْسِلُ مَلَاكَهُ أَمَامَكَ، فَتَأْخُذُ زَوْجَةً لِابْنِي مِنْ هُنَاكَ.', 'تكوين 24:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 8, 'وَإِنْ لَمْ تَشَإِ الْمَرْأَةُ أَنْ تَتْبَعَكَ، تَبَرَّأْتَ مِنْ حَلْفِي هَذَا. أَمَّا ابْنِي فَلَا تَرْجِعْ بِهِ إِلَى هُنَاكَ».', 'تكوين 24:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 9, 'فَوَضَعَ الْعَبْدُ يَدَهُ تَحْتَ فَخْذِ إِبْرَاهِيمَ مَوْلَاهُ، وَحَلَفَ لَهُ عَلَى هَذَا الْأَمْرِ.', 'تكوين 24:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 10, 'ثُمَّ أَخَذَ الْعَبْدُ عَشْرَةَ جِمَالٍ مِنْ جِمَالِ مَوْلَاهُ، وَمَضَى وَجَمِيعُ خَيْرَاتِ مَوْلَاهُ فِي يَدِهِ. فَقَامَ وَذَهَبَ إِلَى أَرَامِ النَّهْرَيْنِ إِلَى مَدِينَةِ نَاحُورَ.', 'تكوين 24:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 11, 'وَأَنَاخَ الْجِمَالَ خَارِجَ الْمَدِينَةِ عِنْدَ بِئْرِ الْمَاءِ وَقْتَ الْمَسَاءِ، وَقْتَ خُرُوجِ الْمُسْتَقِيَاتِ.', 'تكوين 24:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 12, 'وَقَالَ׃ «أَيُّهَا الرَّبُّ إِلَهَ سَيِّدِي إِبْرَاهِيمَ، يَسِّرْ لِي الْيَوْمَ وَاصْنَعْ لُطْفًا إِلَى سَيِّدِي إِبْرَاهِيمَ.', 'تكوين 24:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 13, 'هَا أَنَا وَاقِفٌ عَلَى عَيْنِ الْمَاءِ، وَبَنَاتُ أَهْلِ الْمَدِينَةِ خَارِجَاتٌ لِيَسْتَقِينَ مَاءً.', 'تكوين 24:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 14, 'فَلْيَكُنْ أَنَّ الْفَتَاةَ الَّتِي أَقُولُ لَهَا׃ أَمِيلِي جَرَّتَكِ لِأَشْرَبَ، فَتَقُولَ׃ اشْرَبْ وَأَنَا أَسْقِي جِمَالَكَ أَيْضًا، هِيَ الَّتِي عَيَّنْتَهَا لِعَبْدِكَ إِسْحَاقَ. وَبِهَا أَعْلَمُ أَنَّكَ صَنَعْتَ لُطْفًا إِلَى سَيِّدِي».', 'تكوين 24:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 15, 'وَإِذْ كَانَ لَمْ يَفْرَغْ بَعْدُ مِنَ الْكَلَامِ، إِذَا رِفْقَةُ الَّتِي وُلِدَتْ لِبَتُوئِيلَ ابْنِ مِلْكَةَ امْرَأَةِ نَاحُورَ أَخِي إِبْرَاهِيمَ، خَارِجَةٌ وَجَرَّتُهَا عَلَى كَتِفِهَا.', 'تكوين 24:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 16, 'وَكَانَتِ الْفَتَاةُ حَسَنَةَ الْمَنْظَرِ جِدًّا، وَعَذْرَاءَ لَمْ يَعْرِفْهَا رَجُلٌ. فَنَزَلَتْ إِلَى الْعَيْنِ وَمَلَأَتْ جَرَّتَهَا وَطَلَعَتْ.', 'تكوين 24:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 17, 'فَرَكَضَ الْعَبْدُ لِلِقَائِهَا وَقَالَ׃ «اسْقِينِي قَلِيلَ مَاءٍ مِنْ جَرَّتِكِ».', 'تكوين 24:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 18, 'فَقَالَتِ׃ «اشْرَبْ يَا سَيِّدِي». وَأَسْرَعَتْ وَأَنْزَلَتْ جَرَّتَهَا عَلَى يَدِهَا وَسَقَتْهُ.', 'تكوين 24:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 19, 'وَلَمَّا فَرَغَتْ مِنْ سَقْيِهِ قَالَتْ׃ «أَسْتَقِي لِجِمَالِكَ أَيْضًا حَتَّى تَفْرَغَ مِنَ الشُّرْبِ».', 'تكوين 24:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 20, 'فَأَسْرَعَتْ وَأَفْرَغَتْ جَرَّتَهَا فِي الْمَسْقَاةِ، وَرَكَضَتْ أَيْضًا إِلَى الْبِئْرِ لِتَسْتَقِيَ، فَاسْتَقَتْ لِكُلِّ جِمَالِهِ.', 'تكوين 24:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 21, 'وَالرَّجُلُ يَتَفَرَّسُ فِيهَا صَامِتًا لِيَعْلَمَ׃ أَأَنْجَحَ الرَّبُّ طَرِيقَهُ أَمْ لَا.', 'تكوين 24:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 22, 'وَحَدَثَ عِنْدَمَا فَرَغَتِ الْجِمَالُ مِنَ الشُّرْبِ أَنَّ الرَّجُلَ أَخَذَ خِزَامَةَ ذَهَبٍ وَزْنُهَا نِصْفُ شَاقِلٍ وَسِوَارَيْنِ عَلَى يَدَيْهَا وَزْنُهُمَا عَشْرَةُ شَوَاقِلِ ذَهَبٍ.', 'تكوين 24:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 23, 'وَقَالَ׃ «بِنْتُ مَنْ أَنْتِ؟ أَخْبِرِينِي׃ هَلْ فِي بَيْتِ أَبِيكِ مَكَانٌ لَنَا لِنَبِيتَ؟»', 'تكوين 24:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 24, 'فَقَالَتْ لَهُ׃ «أَنَا بِنْتُ بَتُوئِيلَ ابْنِ مِلْكَةَ الَّذِي وَلَدَتْهُ لِنَاحُورَ».', 'تكوين 24:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 25, 'وَقَالَتْ لَهُ׃ «عِنْدَنَا تِبْنٌ وَعَلَفٌ كَثِيرٌ، وَمَكَانٌ لِتَبِيتُوا أَيْضًا».', 'تكوين 24:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 26, 'فَخَرَّ الرَّجُلُ وَسَجَدَ لِلرَّبِّ،', 'تكوين 24:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 27, 'وَقَالَ׃ «مُبَارَكٌ الرَّبُّ إِلَهُ سَيِّدِي إِبْرَاهِيمَ الَّذِي لَمْ يَمْنَعْ لُطْفَهُ وَحَقَّهُ عَنْ سَيِّدِي. إِذْ كُنْتُ أَنَا فِي الطَّرِيقِ، هَدَانِي الرَّبُّ إِلَى بَيْتِ إِخْوَةِ سَيِّدِي».', 'تكوين 24:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 28, 'فَرَكَضَتِ الْفَتَاةُ وَأَخْبَرَتْ بَيْتَ أُمِّهَا بِحَسَبِ هَذِهِ الْأُمُورِ.', 'تكوين 24:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 29, 'وَكَانَ لِرِفْقَةَ أَخٌ اسْمُهُ لَابَانُ، فَرَكَضَ لَابَانُ إِلَى الرَّجُلِ خَارِجًا إِلَى الْعَيْنِ.', 'تكوين 24:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 30, 'وَحَدَثَ أَنَّهُ إِذْ رَأَى الْخِزَامَةَ وَالسِّوَارَيْنِ عَلَى يَدَيْ أُخْتِهِ، وَإِذْ سَمِعَ كَلَامَ رِفْقَةَ أُخْتِهِ قَائِلَةً׃ «هَكَذَا كَلَّمَنِي الرَّجُلُ»، جَاءَ إِلَى الرَّجُلِ، وَإِذَا هُوَ وَاقِفٌ عِنْدَ الْجِمَالِ عَلَى الْعَيْنِ.', 'تكوين 24:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 31, 'فَقَالَ׃ «ادْخُلْ يَا مُبَارَكَ الرَّبِّ، لِمَاذَا تَقِفُ خَارِجًا وَأَنَا قَدْ هَيَّأْتُ الْبَيْتَ وَمَكَانًا لِلْجِمَالِ؟».', 'تكوين 24:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 32, 'فَدَخَلَ الرَّجُلُ إِلَى الْبَيْتِ وَحَلَّ عَنِ الْجِمَالِ، فَأَعْطَى تِبْنًا وَعَلَفًا لِلْجِمَالِ، وَمَاءً لِغَسْلِ رِجْلَيْهِ وَأَرْجُلِ الرِّجَالِ الَّذِينَ مَعَهُ.', 'تكوين 24:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 33, 'وَوُضِعَ قُدَّامَهُ لِيَأْكُلَ. فَقَالَ׃ «لَا آكُلُ حَتَّى أَتَكَلَّمَ كَلَامِي». فَقَالَ׃ «تَكَلَّمْ».', 'تكوين 24:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 34, 'فَقَالَ׃ «أَنَا عَبْدُ إِبْرَاهِيمَ،', 'تكوين 24:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 35, 'وَالرَّبُّ قَدْ بَارَكَ مَوْلَايَ جِدًّا فَصَارَ عَظِيمًا، وَأَعْطَاهُ غَنَمًا وَبَقَرًا وَفِضَّةً وَذَهَبًا وَعَبِيدًا وَإِمَاءً وَجِمَالًا وَحَمِيرًا.', 'تكوين 24:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 36, 'وَوَلَدَتْ سَارَةُ امْرَأَةُ سَيِّدِي ابْنًا لِسَيِّدِي بَعْدَ مَاشَاخَتْ، فَقَدْ أَعْطَاهُ كُلَّ مَا لَهُ.', 'تكوين 24:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 37, 'وَاسْتَحْلَفَنِي سَيِّدِي قَائِلًا׃ لَا تَأْخُذْ زَوْجَةً لِابْنِي مِنْ بَنَاتِ الْكَنْعَانِيِّينَ الَّذِينَ أَنَا سَاكِنٌ فِي أَرْضِهِمْ،', 'تكوين 24:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 38, 'بَلْ إِلَى بَيْتِ أَبِي تَذْهَبُ وَإِلَى عَشِيرَتِي، وَتَأْخُذُ زَوْجَةً لِابْنِي.', 'تكوين 24:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 39, 'فَقُلْتُ لِسَيِّدِي׃ رُبَّمَا لَا تَتْبَعُنِي الْمَرْأَةُ.', 'تكوين 24:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 40, 'فَقَالَ لِي׃ إِنَّ الرَّبَّ الَّذِي سِرْتُ أَمَامَهُ يُرْسِلُ مَلَاكَهُ مَعَكَ وَيُنْجِحُ طَرِيقَكَ، فَتَأْخُذُ زَوْجَةً لِابْنِي مِنْ عَشِيرَتِي وَمِنْ بَيْتِ أَبِي.', 'تكوين 24:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 41, 'حِينَئِذٍ تَتَبَرَّأُ مِنْ حَلْفِي حِينَمَا تَجِيءُ إِلَى عَشِيرَتِي. وَإِنْ لَمْ يُعْطُوكَ فَتَكُونُ بَرِيئًا مِنْ حَلْفِي.', 'تكوين 24:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 42, 'فَجِئْتُ الْيَوْمَ إِلَى الْعَيْنِ، وَقُلْتُ׃ أَيُّهَا الرَّبُّ إِلَهُ سَيِّدِي إِبْرَاهِيمَ، إِنْ كُنْتَ تُنْجِحُ طَرِيقِي الَّذِي أَنَا سَالِكٌ فِيهِ،', 'تكوين 24:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 43, 'فَهَا أَنَا وَاقِفٌ عَلَى عَيْنِ الْمَاءِ، وَلْيَكُنْ أَنَّ الْفَتَاةَ الَّتِي تَخْرُجُ لِتَسْتَقِيَ وَأَقُولُ لَهَا׃ اسْقِينِي قَلِيلَ مَاءٍ مِنْ جَرَّتِكِ،', 'تكوين 24:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 44, 'فَتَقُولَ لِيَ׃ اشْرَبْ أَنْتَ، وَأَنَا أَسْتَقِي لِجِمَالِكَ أَيْضًا، هِيَ الْمَرْأَةُ الَّتِي عَيَّنَهَا الرَّبُّ لِابْنِ سَيِّدِي.', 'تكوين 24:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 45, 'وَإِذْ كُنْتُ أَنَا لَمْ أَفْرَغْ بَعْدُ مِنَ الْكَلَامِ فِي قَلْبِي، إِذَا رِفْقَةُ خَارِجَةٌ وَجَرَّتُهَا عَلَى كَتِفِهَا، فَنَزَلَتْ إِلَى الْعَيْنِ وَاسْتَقَتْ. فَقُلْتُ لَهَا׃ اسْقِينِي.', 'تكوين 24:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 46, 'فَأَسْرَعَتْ وَأَنْزَلَتْ جَرَّتَهَا عَنْهَا وَقَالَتِ׃ اشْرَبْ وَأَنَا أَسْقِي جِمَالَكَ أَيْضًا. فَشَرِبْتُ، وَسَقَتِ الْجِمَالَ أَيْضًا.', 'تكوين 24:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 47, 'فَسَأَلْتُهَا وَقُلتُ׃ بِنْتُ مَنْ أَنْتِ؟ فَقَالَتْ׃ بِنْتُ بَتُوئِيلَ بْنِ نَاحُورَ الَّذِي وَلَدَتْهُ لَهُ مِلْكَةُ. فَوَضَعْتُ الْخِزَامَةَ فِي أَنْفِهَا وَالسِّوَارَيْنِ عَلَى يَدَيْهَا.', 'تكوين 24:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 48, 'وَخَرَرْتُ وَسَجَدْتُ لِلرَّبِّ، وَبَارَكْتُ الرَّبَّ إِلَهَ سَيِّدِي إِبْرَاهِيمَ الَّذِي هَدَانِي فِي طَرِيقٍ أَمِينٍ لِآخُذَ ابْنَةَ أَخِي سَيِّدِي لِابْنِهِ.', 'تكوين 24:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 49, 'وَالْآنَ إِنْ كُنْتُمْ تَصْنَعُونَ مَعْرُوفًا وَأَمَانَةً إِلَى سَيِّدِي فَأَخْبِرُونِي، وَإِلَا فَأَخْبِرُونِي لِأَنْصَرِفَ يَمِينًا أَوْ شِمَالًا».', 'تكوين 24:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 50, 'فَأَجَابَ لَابَانُ وَبَتُوئِيلُ وَقَالَا׃ «مِنْ عِنْدِ الرَّبِّ خَرَجَ الْأَمْرُ. لَا نَقْدِرُ أَنْ نُكَلِّمَكَ بِشَرٍّ أَوْ خَيْرٍ.', 'تكوين 24:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 51, 'هُوَذَا رِفْقَةُ قُدَّامَكَ. خُذْهَا وَاذْهَبْ. فَلْتَكُنْ زَوْجَةً لِابْنِ سَيِّدِكَ، كَمَا تَكَلَّمَ الرَّبُّ».', 'تكوين 24:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 52, 'وَكَانَ عِنْدَمَا سَمِعَ عَبْدُ إِبْرَاهِيمَ كَلَامَهُمْ أَنَّهُ سَجَدَ لِلرَّبِّ إِلَى الْأَرْضِ.', 'تكوين 24:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 53, 'وَأَخْرَجَ الْعَبْدُ آنِيَةَ فِضَّةٍ وَآنِيَةَ ذَهَبٍ وَثِيَابًا وَأَعْطَاهَا لِرِفْقَةَ، وَأَعْطَى تُحَفًا لِأَخِيهَا وَلِأُمِّهَا.', 'تكوين 24:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 54, 'فَأَكَلَ وَشَرِبَ هُوَ وَالرِّجَالُ الَّذِينَ مَعَهُ وَبَاتُوا. ثُمَّ قَامُوا صَبَاحًا فَقَالَ׃ «اصْرِفُونِي إِلَى سَيِّدِي».', 'تكوين 24:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 55, 'فَقَالَ أَخُوهَا وَأُمُّهَا׃ «لِتَمْكُثِ الْفَتَاةُ عِنْدَنَا أَيَّامًا أَوْ عَشْرَةً، بَعْدَ ذَلِكَ تَمْضِي».', 'تكوين 24:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 56, 'فَقَالَ لَهُمْ׃ «لَا تُعَوِّقُونِي وَالرَّبُّ قَدْ أَنْجَحَ طَرِيقِي. اِصْرِفُونِي لِأَذْهَبَ إِلَى سَيِّدِي».', 'تكوين 24:56');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 57, 'فَقَالُوا׃ «نَدْعُو الْفَتَاةَ وَنَسْأَلُهَا شِفَاهًا».', 'تكوين 24:57');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 58, 'فَدَعَوْا رِفْقَةَ وَقَالُوا لَهَا׃ «هَلْ تَذْهَبِينَ مَعَ هَذَا الرَّجُلِ؟» فَقَالَتْ׃ «أَذْهَبُ».', 'تكوين 24:58');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 59, 'فَصَرَفُوا رِفْقَةَ أُخْتَهُمْ وَمُرْضِعَتَهَا وَعَبْدَ إِبْرَاهِيمَ وَرِجَالَهُ.', 'تكوين 24:59');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 60, 'وَبَارَكُوا رِفْقَةَ وَقَالُوا لَهَا׃ «أَنْتِ أُخْتُنَا. صِيرِي أُلُوفَ رِبْوَاتٍ، وَلْيَرِثْ نَسْلُكِ بَابَ مُبْغِضِيهِ».', 'تكوين 24:60');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 61, 'فَقَامَتْ رِفْقَةُ وَفَتَيَاتُهَا وَرَكِبْنَ عَلَى الْجِمَالِ وَتَبِعْنَ الرَّجُلَ. فَأَخَذَ الْعَبْدُ رِفْقَةَ وَمَضَى.', 'تكوين 24:61');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 62, 'وَكَانَ إِسْحَاقُ قَدْ أَتَى مِنْ وُرُودِ بِئْرِ لَحَيْ رُئِي، إِذْ كَانَ سَاكِنًا فِي أَرْضِ الْجَنُوبِ.', 'تكوين 24:62');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 63, 'وَخَرَجَ إِسْحَاقُ لِيَتَأَمَّلَ فِي الْحَقْلِ عِنْدَ إِقْبَالِ الْمَسَاءِ، فَرَفَعَ عَيْنَيْهِ وَنَظَرَ وَإِذَا جِمَالٌ مُقْبِلَةٌ.', 'تكوين 24:63');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 64, 'وَرَفَعَتْ رِفْقَةُ عَيْنَيْهَا فَرَأَتْ إِسْحَاقَ فَنَزَلَتْ عَنِ الْجَمَلِ.', 'تكوين 24:64');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 65, 'وَقَالَتْ لِلْعَبْدِ׃ «مَنْ هَذَا الرَّجُلُ الْمَاشِي فِي الْحَقْلِ لِلِقَائِنَا؟» فَقَالَ الْعَبْدُ׃ «هُوَ سَيِّدِي». فَأَخَذَتِ الْبُرْقُعَ وَتَغَطَّتْ.', 'تكوين 24:65');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 66, 'ثُمَّ حَدَّثَ الْعَبْدُ إِسْحَاقَ بِكُلِّ الْأُمُورِ الَّتِي صَنَعَ،', 'تكوين 24:66');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 24, 67, 'فَأَدْخَلَهَا إِسْحَاقُ إِلَى خِبَاءِ سَارَةَ أُمِّهِ، وَأَخَذَ رِفْقَةَ فَصَارَتْ لَهُ زَوْجَةً وَأَحَبَّهَا. فَتَعَزَّى إِسْحَاقُ بَعْدَ مَوْتِ أُمِّهِ.', 'تكوين 24:67');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 1, 'وَعَادَ إِبْرَاهِيمُ فَأَخَذَ زَوْجَةً اسْمُهَا قَطُورَةُ،', 'تكوين 25:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 2, 'فَوَلَدَتْ لَهُ׃ زِمْرَانَ وَيَقْشَانَ وَمَدَانَ وَمِدْيَانَ وَيِشْبَاقَ وَشُوحًا.', 'تكوين 25:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 3, 'وَوَلَدَ يَقْشَانُ׃ شَبَا وَدَدَانَ. وَكَانَ بَنُو دَدَانَ׃ أَشُّورِيمَ وَلَطُوشِيمَ وَلَأُمِّيمَ.', 'تكوين 25:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 4, 'وَبَنُو مِدْيَانَ׃ عَيْفَةُ وَعِفْرُ وَحَنُوكُ وَأَبِيدَاعُ وَأَلْدَعَةُ. جَمِيعُ هَؤُلَاءِ بَنُو قَطُورَةَ.', 'تكوين 25:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 5, 'وَأَعْطَى إِبْرَاهِيمُ إِسْحَاقَ كُلَّ مَا كَانَ لَهُ.', 'تكوين 25:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 6, 'وَأَمَّا بَنُو السَّرَارِيِّ اللَّوَاتِي كَانَتْ لِإِبْرَاهِيمَ فَأَعْطَاهُمْ إِبْرَاهِيمُ عَطَايَا، وَصَرَفَهُمْ عَنْ إِسْحَاقَ ابْنِهِ شَرْقًا إِلَى أَرْضِ الْمَشْرِقِ، وَهُوَ بَعْدُ حَيٌّ.', 'تكوين 25:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 7, 'وَهَذِهِ أَيَّامُ سِنِي حَيَاةِ إِبْرَاهِيمَ الَّتِي عَاشَهَا׃ مِئَةٌ وَخَمْسٌ وَسَبْعُونَ سَنَةً.', 'تكوين 25:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 8, 'وَأَسْلَمَ إِبْرَاهِيمُ رُوحَهُ وَمَاتَ بِشَيْبَةٍ صَالِحَةٍ، شَيْخًا وَشَبْعَانَ أَيَّامًا، وَانْضَمَّ إِلَى قَوْمِهِ.', 'تكوين 25:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 9, 'وَدَفَنَهُ إِسْحَاقُ وَإِسْمَاعِيلُ ابْنَاهُ فِي مَغَارَةِ الْمَكْفِيلَةِ فِي حَقْلِ عِفْرُونَ بْنِ صُوحَرَ الْحِثِّيِّ الَّذِي أَمَامَ مَمْرَا،', 'تكوين 25:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 10, 'الْحَقْلِ الَّذِي اشْتَرَاهُ إِبْرَاهِيمُ مِنْ بَنِي حِثٍّ. هُنَاكَ دُفِنَ إِبْرَاهِيمُ وَسَارَةُ امْرَأَتُهُ.', 'تكوين 25:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 11, 'وَكَانَ بَعْدَ مَوْتِ إِبْرَاهِيمَ أَنَّ اللهَ بَارَكَ إِسْحَاقَ ابْنَهُ. وَسَكَنَ إِسْحَاقُ عِنْدَ بِئْرِ لَحَيْ رُئِي.', 'تكوين 25:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 12, 'وَهَذِهِ مَوَالِيدُ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ، الَّذِي وَلَدَتْهُ هَاجَرُ الْمِصْرِيَّةُ جَارِيَةُ سَارَةَ لِإِبْرَاهِيمَ.', 'تكوين 25:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 13, 'وَهَذِهِ أَسْمَاءُ بَنِي إِسْمَاعِيلَ بِأَسْمَائِهِمْ حَسَبَ مَوَالِيدِهِمْ׃ نَبَايُوتُ بِكْرُ إِسْمَاعِيلَ، وَقِيدَارُ، وَأَدَبْئِيلُ وَمِبْسَامُ', 'تكوين 25:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 14, 'وَمِشْمَاعُ وَدُومَةُ وَمَسَّا', 'تكوين 25:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 15, 'وَحَدَارُ وَتَيْمَا وَيَطُورُ وَنَافِيشُ وَقِدْمَةُ.', 'تكوين 25:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 16, 'هَؤُلَاءِ هُمْ بَنُو إِسْمَاعِيلَ، وَهَذِهِ أَسْمَاؤُهُمْ بِدِيَارِهِمْ وَحُصُونِهِمْ. اثْنَا عَشَرَ رَئِيسًا حَسَبَ قَبَائِلِهِمْ.', 'تكوين 25:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 17, 'وَهَذِهِ سِنُو حَيَاةِ إِسْمَاعِيلَ׃ مِئَةٌ وَسَبْعٌ وَثَلَاثُونَ سَنَةً، وَأَسْلَمَ رُوحَهُ وَمَاتَ وَانْضَمَّ إِلَى قَوْمِهِ.', 'تكوين 25:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 18, 'وَسَكَنُوا مِنْ حَوِيلَةَ إِلَى شُورَ الَّتِي أَمَامَ مِصْرَ حِينَمَا تَجِيءُ نَحْوَ أَشُّورَ. أَمَامَ جَمِيعِ إِخْوَتِهِ نَزَلَ.', 'تكوين 25:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 19, 'وَهَذِهِ مَوَالِيدُ إِسْحَاقَ بْنِ إِبْرَاهِيمَ׃ وَلَدَ إِبْرَاهِيمُ إِسْحَاقَ.', 'تكوين 25:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 20, 'وَكَانَ إِسْحَاقُ ابْنَ أَرْبَعِينَ سَنَةً لَمَّا اتَّخَذَ لِنَفْسِهِ زَوْجَةً، رِفْقَةَ بِنْتَ بَتُوئِيلَ الْأَرَامِيِّ، أُخْتَ لَابَانَ الْأَرَامِيِّ مِنْ فَدَّانِ أَرَامَ.', 'تكوين 25:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 21, 'وَصَلَّى إِسْحَاقُ إِلَى الرَّبِّ لِأَجْلِ امْرَأَتِهِ لِأَنَّهَا كَانَتْ عَاقِرًا، فَاسْتَجَابَ لَهُ الرَّبُّ، فَحَبِلَتْ رِفْقَةُ امْرَأَتُهُ.', 'تكوين 25:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 22, 'وَتَزَاحَمَ الْوَلَدَانِ فِي بَطْنِهَا، فَقَالَتْ׃ «إِنْ كَانَ هَكَذَا فَلِمَاذَا أَنَا؟» فَمَضَتْ لِتَسْأَلَ الرَّبَّ.', 'تكوين 25:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 23, 'فَقَالَ لَهَا الرَّبُّ׃ «فِي بَطْنِكِ أُمَّتَانِ، وَمِنْ أَحْشَائِكِ يَفْتَرِقُ شَعْبَانِ׃ شَعْبٌ يَقْوَى عَلَى شَعْبٍ، وَكَبِيرٌ يُسْتَعْبَدُ لِصَغِيرٍ».', 'تكوين 25:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 24, 'فَلَمَّا كَمُلَتْ أَيَّامُهَا لِتَلِدَ إِذَا فِي بَطْنِهَا تَوْأَمَانِ.', 'تكوين 25:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 25, 'فَخَرَجَ الْأوَّلُ أَحْمَرَ، كُلُّهُ كَفَرْوَةِ شَعْرٍ، فَدَعَوْا اسْمَهُ «عِيسُوَ».', 'تكوين 25:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 26, 'وَبَعْدَ ذَلِكَ خَرَجَ أَخُوهُ وَيَدُهُ قَابِضَةٌ بِعَقِبِ عِيسُو، فَدُعِيَ اسْمُهُ «يَعْقُوبَ». وَكَانَ إِسْحَاقُ ابْنَ سِتِّينَ سَنَةً لَمَّا وَلَدَتْهُمَا.', 'تكوين 25:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 27, 'فَكَبِرَ الْغُلَامَانِ، وَكَانَ عِيسُو إِنْسَانًا يَعْرِفُ الصَّيْدَ، إِنْسَانَ الْبَرِّيَّةِ، وَيَعْقُوبُ إِنْسَانًا كَامِلًا يَسْكُنُ الْخِيَامَ.', 'تكوين 25:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 28, 'فَأَحَبَّ إِسْحَاقُ عِيسُوَ لِأَنَّ فِي فَمِهِ صَيْدًا، وَأَمَّا رِفْقَةُ فَكَانَتْ تُحِبُّ يَعْقُوبَ.', 'تكوين 25:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 29, 'وَطَبَخَ يَعْقُوبُ طَبِيخًا، فَأَتَى عِيسُو مِنَ الْحَقْلِ وَهُوَ قَدْ أَعْيَا.', 'تكوين 25:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 30, 'فَقَالَ عِيسُو لِيَعْقُوبَ׃ «أَطْعِمْنِي مِنْ هَذَا الْأَحْمَرِ لِأَنِّي قَدْ أَعْيَيْتُ». لِذَلِكَ دُعِيَ اسْمُهُ «أَدُومَ».', 'تكوين 25:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 31, 'فَقَالَ يَعْقُوبُ׃ «بِعْنِي الْيَوْمَ بَكُورِيَّتَكَ».', 'تكوين 25:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 32, 'فَقَالَ عِيسُو׃ «هَا أَنَا مَاضٍ إِلَى الْمَوْتِ، فَلِمَاذَا لِي بَكُورِيَّةٌ؟»', 'تكوين 25:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 33, 'فَقَالَ يَعْقُوبُ׃ «احْلِفْ لِيَ الْيَوْمَ». فَحَلَفَ لَهُ، فَبَاعَ بَكُورِيَّتَهُ لِيَعْقُوبَ.', 'تكوين 25:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 25, 34, 'فَأَعْطَى يَعْقُوبُ عِيسُوَ خُبْزًا وَطَبِيخَ عَدَسٍ، فَأَكَلَ وَشَرِبَ وَقَامَ وَمَضَى. فَاحْتَقَرَ عِيسُو الْبَكُورِيَّةَ.', 'تكوين 25:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 1, 'وَكَانَ فِي الْأَرْضِ جُوعٌ غَيْرُ الْجُوعِ الْأَوَّلِ الَّذِي كَانَ فِي أَيَّامِ إِبْرَاهِيمَ، فَذَهَبَ إِسْحَاقُ إِلَى أَبِيمَالِكَ مَلِكِ الْفِلِسْطِينِيِّينَ، إِلَى جَرَارَ.', 'تكوين 26:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 2, 'وَظَهَرَ لَهُ الرَّبُّ وَقَالَ׃ «لَا تَنْزِلْ إِلَى مِصْرَ. اسْكُنْ فِي الْأَرْضِ الَّتِي أَقُولُ لَكَ.', 'تكوين 26:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 3, 'تَغَرَّبْ فِي هَذِهِ الْأَرْضِ فَأَكُونَ مَعَكَ وَأُبَارِكَكَ، لِأَنِّي لَكَ وَلِنَسْلِكَ أُعْطِي جَمِيعَ هَذِهِ الْبِلَادِ، وَأَفِي بِالْقَسَمِ الَّذِي أَقْسَمْتُ لِإِبْرَاهِيمَ أَبِيكَ.', 'تكوين 26:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 4, 'وَأُكَثِّرُ نَسْلَكَ كَنُجُومِ السَّمَاءِ، وَأُعْطِي نَسْلَكَ جَمِيعَ هَذِهِ الْبِلَادِ، وَتَتَبَارَكُ فِي نَسْلِكَ جَمِيعُ أُمَمِ الْأَرْضِ،', 'تكوين 26:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 5, 'مِنْ أَجْلِ أَنَّ إِبْرَاهِيمَ سَمِعَ لِقَوْلِي وَحَفِظَ مَا يُحْفَظُ لِي׃ أَوَامِرِي وَفَرَائِضِي وَشَرَائِعِي».', 'تكوين 26:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 6, 'فَأَقَامَ إِسْحَاقُ فِي جَرَارَ.', 'تكوين 26:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 7, 'وَسَأَلَهُ أَهْلُ الْمَكَانِ عَنِ امْرَأَتِهِ، فَقَالَ׃ «هِيَ أُخْتِي». لِأَنَّهُ خَافَ أَنْ يَقُولَ׃ «امْرَأَتِي» لَعَلَّ أَهْلَ الْمَكَانِ׃ «يَقْتُلُونَنِي مِنْ أَجْلِ رِفْقَةَ» لِأَنَّهَا كَانَتْ حَسَنَةَ الْمَنْظَرِ.', 'تكوين 26:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 8, 'وَحَدَثَ إِذْ طَالَتْ لَهُ الْأَيَّامُ هُنَاكَ أَنَّ أَبِيمَالِكَ مَلِكَ الْفِلِسْطِينِيِّينَ أَشْرَفَ مِنَ الْكُوَّةِ وَنَظَرَ، وَإِذَا إِسْحَاقُ يُلَاعِبُ رِفْقَةَ امْرَأَتَهُ.', 'تكوين 26:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 9, 'فَدَعَا أَبِيمَالِكُ إِسْحَاقَ وَقَالَ׃ «إِنَّمَا هِيَ امْرَأَتُكَ! فَكَيْفَ قُلْتَ׃ هِيَ أُخْتِي؟» فَقَالَ لَهُ إِسْحَاقُ׃ «لِأَنِّي قُلْتُ׃ لَعَلِّي أَمُوتُ بِسَبَبِهَا».', 'تكوين 26:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 10, 'فَقَالَ أَبِيمَالِكُ׃ «مَا هَذَا الَّذِي صَنَعْتَ بِنَا؟ لَوْلَا قَلِيلٌ لَاضْطَجَعَ أَحَدُ الشَّعْبِ مَعَ امْرَأَتِكَ فَجَلَبْتَ عَلَيْنَا ذَنْبًا».', 'تكوين 26:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 11, 'فَأَوْصَى أَبِيمَالِكُ جَمِيعَ الشَّعْبِ قَائِلًا׃ «الَّذِي يَمَسُّ هَذَا الرَّجُلَ أَوِ امْرَأَتَهُ مَوْتًا يَمُوتُ».', 'تكوين 26:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 12, 'وَزَرَعَ إِسْحَاقُ فِي تِلْكَ الْأَرْضِ فَأَصَابَ فِي تِلْكَ السَّنَةِ مِئَةَ ضِعْفٍ، وَبَارَكَهُ الرَّبُّ.', 'تكوين 26:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 13, 'فَتَعَاظَمَ الرَّجُلُ وَكَانَ يَتَزَايَدُ فِي التَّعَاظُمِ حَتَّى صَارَ عَظِيمًا جِدًّا.', 'تكوين 26:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 14, 'فَكَانَ لَهُ مَوَاشٍ مِنَ الْغَنَمِ وَمَوَاشٍ مِنَ الْبَقَرِ وَعَبِيدٌ كَثِيرُونَ. فَحَسَدَهُ الْفِلِسْطِينِيُّونَ.', 'تكوين 26:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 15, 'وَجَمِيعُ الْآبَارِ، الَّتِي حَفَرَهَا عَبِيدُ أَبِيهِ فِي أَيَّامِ إِبْرَاهِيمَ أَبِيهِ، طَمَّهَا الْفِلِسْطِينِيُّونَ وَمَلَأُوهَا تُرَابًا.', 'تكوين 26:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 16, 'وَقَالَ أَبِيمَالِكُ لِإِسْحَاقَ׃ «اذْهَبْ مِنْ عِنْدِنَا لِأَنَّكَ صِرْتَ أَقْوَى مِنَّا جِدًّا».', 'تكوين 26:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 17, 'فَمَضَى إِسْحَاقُ مِنْ هُنَاكَ، وَنَزَلَ فِي وَادِي جَرَارَ وَأَقَامَ هُنَاكَ.', 'تكوين 26:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 18, 'فَعَادَ إِسْحَاقُ وَنَبَشَ آبَارَ الْمَاءِ الَّتِي حَفَرُوهَا فِي أَيَّامِ إِبْرَاهِيمَ أَبِيهِ، وَطَمَّهَا الْفِلِسْطِينِيُّونَ بَعْدَ مَوْتِ أَبِيهِ، وَدَعَاهَا بِأَسْمَاءٍ كَالْأَسْمَاءِ الَّتِي دَعَاهَا بِهَا أَبُوهُ.', 'تكوين 26:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 19, 'وَحَفَرَ عَبِيدُ إِسْحَاقَ فِي الْوَادِي فَوَجَدُوا هُنَاكَ بِئْرَ مَاءٍ حَيٍّ.', 'تكوين 26:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 20, 'فَخَاصَمَ رُعَاةُ جَرَارَ رُعَاةَ إِسْحَاقَ قَائِلِينَ׃ «لَنَا الْمَاءُ». فَدَعَا اسْمَ الْبِئْرِ «عِسِقَ» لِأَنَّهُمْ نَازَعُوهُ.', 'تكوين 26:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 21, 'ثُمَّ حَفَرُوا بِئْرًا أُخْرَى وَتَخَاصَمُوا عَلَيْهَا أَيْضًا، فَدَعَا اسْمَهَا «سِطْنَةَ».', 'تكوين 26:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 22, 'ثُمَّ نَقَلَ مِنْ هُنَاكَ وَحَفَرَ بِئْرًا أُخْرَى وَلَمْ يَتَخَاصَمُوا عَلَيْهَا، فَدَعَا اسْمَهَا «رَحُوبُوتَ»، وَقَالَ׃ «إِنَّهُ الْآنَ قَدْ أَرْحَبَ لَنَا الرَّبُّ وَأَثْمَرْنَا فِي الْأَرْضِ».', 'تكوين 26:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 23, 'ثُمَّ صَعِدَ مِنْ هُنَاكَ إِلَى بِئْرِ سَبْعٍ.', 'تكوين 26:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 24, 'فَظَهَرَ لَهُ الرَّبُّ فِي تِلْكَ اللَّيْلَةِ وَقَالَ׃ «أَنَا إِلَهُ إِبْرَاهِيمَ أَبِيكَ. لَا تَخَفْ لِأَنِّي مَعَكَ، وَأُبَارِكُكَ وَأُكَثِّرُ نَسْلَكَ مِنْ أَجْلِ إِبْرَاهِيمَ عَبْدِي».', 'تكوين 26:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 25, 'فَبَنَى هُنَاكَ مَذْبَحًا وَدَعَا بِاسْمِ الرَّبِّ. وَنَصَبَ هُنَاكَ خَيْمَتَهُ، وَحَفَرَ هُنَاكَ عَبِيدُ إِسْحَاقَ بِئْرًا.', 'تكوين 26:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 26, 'وَذَهَبَ إِلَيْهِ مِنْ جَرَارَ أَبِيمَالِكُ وَأَحُزَّاتُ مِنْ أَصْحَابِهِ وَفِيكُولُ رَئِيسُ جَيْشِهِ.', 'تكوين 26:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 27, 'فَقَالَ لَهُمْ إِسْحَاقُ׃ «مَا بَالُكُمْ أَتَيْتُمْ إِلَيَّ وَأَنْتُمْ قَدْ أَبْغَضْتُمُونِي وَصَرَفْتُمُونِي مِنْ عِنْدِكُمْ؟»', 'تكوين 26:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 28, 'فَقَالُوا׃ «إِنَّنَا قَدْ رَأَيْنَا أَنَّ الرَّبَّ كَانَ مَعَكَ، فَقُلْنَا׃ لِيَكُنْ بَيْنَنَا حَلْفٌ، بَيْنَنَا وَبَيْنَكَ، وَنَقْطَعُ مَعَكَ عَهْدًا׃', 'تكوين 26:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 29, 'أَنْ لَا تَصْنَعَ بِنَا شَرًّا، كَمَا لَمْ نَمَسَّكَ وَكَمَا لَمْ نَصْنَعْ بِكَ إِلَا خَيْرًا وَصَرَفْنَاكَ بِسَلَامٍ. أَنْتَ الْآنَ مُبَارَكُ الرَّبِّ».', 'تكوين 26:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 30, 'فَصَنَعَ لَهُمْ ضِيَافَةً، فَأَكَلُوا وَشَرِبُوا.', 'تكوين 26:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 31, 'ثُمَّ بَكَّرُوا فِي الْغَدِ وَحَلَفُوا بَعْضُهُمْ لِبَعْضٍ، وَصَرَفَهُمْ إِسْحَاقُ. فَمَضَوْا مِنْ عِنْدِهِ بِسَلَامٍ.', 'تكوين 26:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 32, 'وَحَدَثَ فِي ذَلِكَ الْيَوْمِ أَنَّ عَبِيدَ إِسْحَاقَ جَاءُوا وَأَخْبَرُوهُ عَنِ الْبِئْرِ الَّتِي حَفَرُوا، وَقَالُوا لَهُ׃ «قَدْ وَجَدْنَا مَاءً».', 'تكوين 26:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 33, 'فَدَعَاهَا «شِبْعَةَ»، لِذَلِكَ اسْمُ الْمَدِينَةِ بِئْرُ سَبْعٍ إِلَى هَذَا الْيَوْمِ.', 'تكوين 26:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 34, 'وَلَمَّا كَانَ عِيسُو ابْنَ أَرْبَعِينَ سَنَةً اتَّخَذَ زَوْجَةً׃ يَهُودِيتَ ابْنَةَ بِيرِي الْحِثِّيِّ، وَبَسْمَةَ ابْنَةَ إِيلُونَ الْحِثِّيِّ.', 'تكوين 26:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 26, 35, 'فَكَانَتَا مَرَارَةَ نَفْسٍ لِإِسْحَاقَ وَرِفْقَةَ.', 'تكوين 26:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 1, 'وَحَدَثَ لَمَّا شَاخَ إِسْحَاقُ وَكَلَّتْ عَيْنَاهُ عَنِ النَّظَرِ، أَنَّهُ دَعَا عِيسُوَ ابْنَهُ الْأَكْبَرَ وَقَالَ لَهُ׃ «يَا ابْنِي». فَقَالَ لَهُ׃ «هَأَنَذَا».', 'تكوين 27:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 2, 'فَقَالَ׃ «إِنَّنِي قَدْ شِخْتُ وَلَسْتُ أَعْرِفُ يَوْمَ وَفَاتِي.', 'تكوين 27:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 3, 'فَالْآنَ خُذْ عُدَّتَكَ׃ جُعْبَتَكَ وَقَوْسَكَ، وَاخْرُجْ إِلَى الْبَرِّيَّةِ وَتَصَيَّدْ لِي صَيْدًا،', 'تكوين 27:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 4, 'وَاصْنَعْ لِي أَطْعِمَةً كَمَا أُحِبُّ، وَأْتِنِي بِهَا لِآكُلَ حَتَّى تُبَارِكَكَ نَفْسِي قَبْلَ أَنْ أَمُوتَ».', 'تكوين 27:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 5, 'وَكَانَتْ رِفْقَةُ سَامِعَةً إِذْ تَكَلَّمَ إِسْحَاقُ مَعَ عِيسُو ابْنِهِ. فَذَهَبَ عِيسُو إِلَى الْبَرِّيَّةِ كَيْ يَصْطَادَ صَيْدًا لِيَأْتِيَ بِهِ.', 'تكوين 27:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 6, 'وَأَمَّا رِفْقَةُ فَكَلمتْ يَعْقُوبَ ابْنِهَا قَائِلةً׃ «إِنِّي قَدْ سَمِعْتُ أَبَاكَ يُكَلِّمُ عِيسُوَ أَخَاكَ قَائِلًا׃', 'تكوين 27:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 7, 'ائْتِنِي بِصَيْدٍ وَاصْنَعْ لِي أَطْعِمَةً لِآكُلَ وَأُبَارِكَكَ أَمَامَ الرَّبِّ قَبْلَ وَفَاتِي.', 'تكوين 27:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 8, 'فَالْآنَ يَا ابْنِي اسْمَعْ لِقَوْلِي فِي مَا أَنَا آمُرُكَ بِهِ׃', 'تكوين 27:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 9, 'اِذْهَبْ إِلَى الْغَنَمِ وَخُذْ لِي مِنْ هُنَاكَ جَدْيَيْنِ جَيِّدَيْنِ مِنَ الْمِعْزَى، فَأَصْنَعَهُمَا أَطْعِمَةً لِأَبِيكَ كَمَا يُحِبُّ،', 'تكوين 27:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 10, 'فَتُحْضِرَهَا إِلَى أَبِيكَ لِيَأْكُلَ حَتَّى يُبَارِكَكَ قَبْلَ وَفَاتِهِ».', 'تكوين 27:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 11, 'فَقَالَ يَعْقُوبُ لِرِفْقَةَ أُمِّهِ׃ «هُوَذَا عِيسُو أَخِي رَجُلٌ أَشْعَرُ وَأَنَا رَجُلٌ أَمْلَسُ.', 'تكوين 27:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 12, 'رُبَّمَا يَجُسُّنِي أَبِي فَأَكُونُ فِي عَيْنَيْهِ كَمُتَهَاوِنٍ، وَأَجْلِبُ عَلَى نَفْسِي لَعْنَةً لَا بَرَكَةً».', 'تكوين 27:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 13, 'فَقَالَتْ لَهُ أُمُّهُ׃ «لَعْنَتُكَ عَلَيَّ يَا ابْنِي. اِسْمَعْ لِقَوْلِي فَقَطْ وَاذْهَبْ خُذْ لِي».', 'تكوين 27:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 14, 'فَذَهَبَ وَأَخَذَ وَأَحْضَرَ لِأُمِّهِ، فَصَنَعَتْ أُمُّهُ أَطْعِمَةً كَمَا كَانَ أَبُوهُ يُحِبُّ.', 'تكوين 27:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 15, 'وَأَخَذَتْ رِفْقَةُ ثِيَابَ عِيسُو ابْنِهَا الْأَكْبَرِ الْفَاخِرَةَ الَّتِي كَانَتْ عِنْدَهَا فِي الْبَيْتِ وَأَلْبَسَتْ يَعْقُوبَ ابْنَهَا الْأَصْغَرَ،', 'تكوين 27:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 16, 'وَأَلْبَسَتْ يَدَيْهِ وَمَلَاسَةَ عُنُقِهِ جُلُودَ جَدْيَيِ الْمِعْزَى.', 'تكوين 27:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 17, 'وَأَعْطَتِ الْأَطْعِمَةَ وَالْخُبْزَ الَّتِي صَنَعَتْ فِي يَدِ يَعْقُوبَ ابْنِهَا.', 'تكوين 27:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 18, 'فَدَخَلَ إِلَى أَبِيهِ وَقَالَ׃ «يَا أَبِي». فَقَالَ׃ «هَأَنَذَا. مَنْ أَنْتَ يَا ابْنِي؟».', 'تكوين 27:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 19, 'فَقَالَ يَعْقُوبُ لِأَبِيهِ׃ «أَنَا عِيسُو بِكْرُكَ. قَدْ فَعَلْتُ كَمَا كَلَّمْتَنِي. قُمِ اجْلِسْ وَكُلْ مِنْ صَيْدِي لِكَيْ تُبَارِكَنِي نَفْسُكَ».', 'تكوين 27:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 20, 'فَقَالَ إِسْحَاقُ لِابْنِهِ׃ «مَا هَذَا الَّذِي أَسْرَعْتَ لِتَجِدَ يَا ابْنِي؟». فَقَالَ׃ «إِنَّ الرَّبَّ إِلَهَكَ قَدْ يَسَّرَ لِي».', 'تكوين 27:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 21, 'فَقَالَ إِسْحَاقُ لِيَعْقُوبَ׃ «تَقَدَّمْ لِأَجُسَّكَ يَا ابْنِي. أَأَنْتَ هُوَ ابْنِي عِيسُو أَمْ لَا؟».', 'تكوين 27:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 22, 'فَتَقَدَّمَ يَعْقُوبُ إِلَى إِسْحَاقَ أَبِيهِ، فَجَسَّهُ وَقَالَ׃ «الصَّوْتُ صَوْتُ يَعْقُوبَ، وَلَكِنَّ الْيَدَيْنِ يَدَا عِيسُو».', 'تكوين 27:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 23, 'وَلَمْ يَعْرِفْهُ لِأَنَّ يَدَيْهِ كَانَتَا مُشْعِرَتَيْنِ كَيَدَيْ عِيسُو أَخِيهِ، فَبَارَكَهُ.', 'تكوين 27:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 24, 'وَقَالَ׃ «هَلْ أَنْتَ هُوَ ابْنِي عِيسُو؟». فَقَالَ׃ «أَنَا هُوَ».', 'تكوين 27:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 25, 'فَقَالَ׃ «قَدِّمْ لِي لِآكُلَ مِنْ صَيْدِ ابْنِي حَتَّى تُبَارِكَكَ نَفْسِي». فَقَدَّمَ لَهُ فَأَكَلَ، وَأَحْضَرَ لَهُ خَمْرًا فَشَرِبَ.', 'تكوين 27:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 26, 'فَقَالَ لَهُ إِسْحَاقُ أَبُوهُ׃ «تَقَدَّمْ وَقَبِّلْنِي يَا ابْنِي».', 'تكوين 27:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 27, 'فَتَقَدَّمَ وَقَبَّلَهُ، فَشَمَّ رَائِحَةَ ثِيَابِهِ وَبَارَكَهُ، وَقَالَ׃ «انْظُرْ! رَائِحَةُ ابْنِي كَرَائِحَةِ حَقْلٍ قَدْ بَارَكَهُ الرَّبُّ.', 'تكوين 27:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 28, 'فَلْيُعْطِكَ اللهُ مِنْ نَدَى السَّمَاءِ وَمِنْ دَسَمِ الْأَرْضِ. وَكَثْرَةَ حِنْطَةٍ وَخَمْرٍ.', 'تكوين 27:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 29, 'لِيُسْتَعْبَدْ لَكَ شُعُوبٌ، وَتَسْجُدْ لَكَ قَبَائِلُ. كُنْ سَيِّدًا لِإِخْوَتِكَ، وَلْيَسْجُدْ لَكَ بَنُو أُمِّكَ. لِيَكُنْ لَاعِنُوكَ مَلْعُونِينَ، وَمُبَارِكُوكَ مُبَارَكِينَ».', 'تكوين 27:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 30, 'وَحَدَثَ عِنْدَمَا فَرَغَ إِسْحَاقُ مِنْ بَرَكَةِ يَعْقُوبَ، وَيَعْقُوبُ قَدْ خَرَجَ مِنْ لَدُنْ إِسْحَاقَ أَبِيهِ، أَنَّ عِيسُوَ أَخَاهُ أَتَى مِنْ صَيْدِهِ،', 'تكوين 27:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 31, 'فَصَنَعَ هُوَ أَيْضًا أَطْعِمَةً وَدَخَلَ بِهَا إِلَى أَبِيهِ وَقَالَ لِأَبِيهِ׃ «لِيَقُمْ أَبِي وَيَأْكُلْ مِنْ صَيْدِ ابْنِهِ حَتَّى تُبَارِكَنِي نَفْسُكَ».', 'تكوين 27:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 32, 'فَقَالَ لَهُ إِسْحَاقُ أَبُوهُ׃ «مَنْ أَنْتَ؟» فَقَالَ׃ «أَنَا ابْنُكَ بِكْرُكَ عِيسُو».', 'تكوين 27:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 33, 'فَارْتَعَدَ إِسْحَاقُ ارْتِعَادًا عَظِيمًا جِدًّا وَقَالَ׃ «فَمَنْ هُوَ الَّذِي اصْطَادَ صَيْدًا وَأَتَى بِهِ إِلَيَّ فَأَكَلْتُ مِنَ الْكُلِّ قَبْلَ أَنْ تَجِيءَ، وَبَارَكْتُهُ؟ نَعَمْ، وَيَكُونُ مُبَارَكًا».', 'تكوين 27:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 34, 'فَعِنْدَمَا سَمِعَ عِيسُو كَلَامَ أَبِيهِ صَرَخَ صَرْخَةً عَظِيمَةً وَمُرَّةً جِدًّا، وَقَالَ لِأَبِيهِ׃ «بَارِكْنِي أَنَا أَيْضًا يَا أَبِي».', 'تكوين 27:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 35, 'فَقَالَ׃ «قَدْ جَاءَ أَخُوكَ بِمَكْرٍ وَأَخَذَ بَرَكَتَكَ».', 'تكوين 27:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 36, 'فَقَالَ׃ «أَلَا إِنَّ اسْمَهُ دُعِيَ يَعْقُوبَ، فَقَدْ تَعَقَّبَنِي الْآنَ مَرَّتَيْنِ! أَخَذَ بَكُورِيَّتِي، وَهُوَذَا الْآنَ قَدْ أَخَذَ بَرَكَتِي». ثُمَّ قَالَ׃ «أَمَا أَبْقَيْتَ لِي بَرَكَةً؟».', 'تكوين 27:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 37, 'فَأَجَابَ إِسْحَاقُ وَقَالَ لِعِيسُو׃ «إِنِّي قَدْ جَعَلْتُهُ سَيِّدًا لَكَ، وَدَفَعْتُ إِلَيْهِ جَمِيعَ إِخْوَتِهِ عَبِيدًا، وَعَضَدْتُهُ بِحِنْطَةٍ وَخَمْرٍ. فَمَاذَا أَصْنَعُ إِلَيْكَ يَا ابْنِي؟»', 'تكوين 27:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 38, 'فَقَالَ عِيسُو لِأَبِيهِ׃ «أَلَكَ بَرَكَةٌ وَاحِدَةٌ فَقَطْ يَا أَبِي؟ بَارِكْنِي أَنَا أَيْضًا يَا أَبِي». وَرَفَعَ عِيسُو صَوْتَهُ وَبَكَى.', 'تكوين 27:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 39, 'فَأَجَابَ إِسْحَاقُ أَبُوهُ وَقَالَ لَهُ׃ «هُوَذَا بِلَا دَسَمِ الْأَرْضِ يَكُونُ مَسْكَنُكَ، وَبِلَا نَدَى السَّمَاءِ مِنْ فَوْقُ.', 'تكوين 27:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 40, 'وَبِسَيْفِكَ تَعِيشُ، وَلِأَخِيكَ تُسْتَعْبَدُ، وَلَكِنْ يَكُونُ حِينَمَا تَجْمَحُ أَنَّكَ تُكَسِّرُ نِيرَهُ عَنْ عُنُقِكَ».', 'تكوين 27:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 41, 'فَحَقَدَ عِيسُو عَلَى يَعْقُوبَ مِنْ أَجْلِ الْبَرَكَةِ الَّتِي بَارَكَهُ بِهَا أَبُوهُ. وَقَالَ عِيسُو فِي قَلْبِهِ׃ «قَرُبَتْ أَيَّامُ مَنَاحَةِ أَبِي، فَأَقْتُلُ يَعْقُوبَ أَخِي».', 'تكوين 27:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 42, 'فَأُخْبِرَتْ رِفْقَةُ بِكَلَامِ عِيسُوَ ابْنِهَا الْأَكْبَرِ، فَأَرْسَلَتْ وَدَعَتْ يَعْقُوبَ ابْنَهَا الْأَصْغَرَ وَقَالَتْ لَهُ׃ «هُوَذَا عِيسُو أَخُوكَ مُتَسَلٍّ مِنْ جِهَتِكَ بِأَنَّهُ يَقْتُلُكَ.', 'تكوين 27:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 43, 'فَالْآنَ يَا ابْنِي اسْمَعْ لِقَوْلِي، وَقُمِ اهْرُبْ إِلَى أَخِي لَابَانَ إِلَى حَارَانَ،', 'تكوين 27:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 44, 'وَأَقِمْ عِنْدَهُ أَيَّامًا قَلِيلَةً حَتَّى يَرْتَدَّ سُخْطُ أَخِيكَ.', 'تكوين 27:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 45, 'حَتَّى يَرْتَدَّ غَضَبُ أَخِيكَ عَنْكَ، وَيَنْسَى مَا صَنَعْتَ بِهِ. ثُمَّ أُرْسِلُ فَآخُذُكَ مِنْ هُنَاكَ. لِمَاذَا أُعْدَمُ اثْنَيْكُمَا فِي يَوْمٍ وَاحِدٍ؟».', 'تكوين 27:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 27, 46, 'وَقَالَتْ رِفْقَةُ لِإِسْحَاقَ׃ «مَلِلْتُ حَيَاتِي مِنْ أَجْلِ بَنَاتِ حِثَّ. إِنْ كَانَ يَعْقُوبُ يَأْخُذُ زَوْجَةً مِنْ بَنَاتِ حِثَّ مِثْلَ هَؤُلَاءِ مِنْ بَنَاتِ الْأَرْضِ، فَلِمَاذَا لِي حَيَاةٌ؟».', 'تكوين 27:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 1, 'فَدَعَا إِسْحَاقُ يَعْقُوبَ وَبَارَكَهُ، وَأَوْصَاهُ وَقَالَ لَهُ׃ «لَا تَأْخُذْ زَوْجَةً مِنْ بَنَاتِ كَنْعَانَ.', 'تكوين 28:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 2, 'قُمِ اذْهَبْ إِلَى فَدَّانِ أَرَامَ، إِلَى بَيْتِ بَتُوئِيلَ أَبِي أُمِّكَ، وَخُذْ لِنَفْسِكَ زَوْجَةً مِنْ هُنَاكَ، مِنْ بَنَاتِ لَابَانَ أَخِي أُمِّكَ.', 'تكوين 28:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 3, 'وَاللهُ الْقَدِيرُ يُبَارِكُكَ، وَيَجْعَلُكَ مُثْمِرًا، وَيُكَثِّرُكَ فَتَكُونُ جُمْهُورًا مِنَ الشُّعُوبِ.', 'تكوين 28:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 4, 'وَيُعْطِيكَ بَرَكَةَ إِبْرَاهِيمَ لَكَ وَلِنَسْلِكَ مَعَكَ، لِتَرِثَ أَرْضَ غُرْبَتِكَ الَّتِي أَعْطَاهَا اللهُ لِإِبْرَاهِيمَ».', 'تكوين 28:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 5, 'فَصَرَفَ إِسْحَاقُ يَعْقُوبَ فَذَهَبَ إِلَى فَدَّانِ أَرَامَ، إِلَى لَابَانَ بْنِ بَتُوئِيلَ الْأَرَامِيِّ، أَخِي رِفْقَةَ أُمِّ يَعْقُوبَ وَعِيسُوَ.', 'تكوين 28:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 6, 'فَلَمَّا رَأَى عِيسُو أَنَّ إِسْحَاقَ بَارَكَ يَعْقُوبَ وَأَرْسَلَهُ إِلَى فَدَّانِ أَرَامَ لِيَأْخُذَ لِنَفْسِهِ مِنْ هُنَاكَ زَوْجَةً، إِذْ بَارَكَهُ وَأَوْصَاهُ قَائِلًا׃ «لَا تَأْخُذْ زَوْجَةً مِنْ بَنَاتِ كَنْعَانَ».', 'تكوين 28:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 7, 'وَأَنَّ يَعْقُوبَ سَمِعَ لِأَبِيهِ وَأُمِّهِ وَذَهَبَ إِلَى فَدَّانِ أَرَامَ،.', 'تكوين 28:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 8, 'رَأَى عِيسُو أَنَّ بَنَاتِ كَنْعَانَ شِرِّيرَاتٌ فِي عَيْنَيْ إِسْحَاقَ أَبِيهِ،', 'تكوين 28:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 9, 'فَذَهَبَ عِيسُو إِلَى إِسْمَاعِيلَ وَأَخَذَ مَحْلَةَ بِنْتَ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ، أُخْتَ نَبَايُوتَ، زَوْجَةً لَهُ عَلَى نِسَائِهِ.', 'تكوين 28:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 10, 'فَخَرَجَ يَعْقُوبُ مِنْ بِئْرِ سَبْعٍ وَذَهَبَ نَحْوَ حَارَانَ.', 'تكوين 28:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 11, 'وَصَادَفَ مَكَانًا وَبَاتَ هُنَاكَ لِأَنَّ الشَّمْسَ كَانَتْ قَدْ غَابَتْ، وَأَخَذَ مِنْ حِجَارَةِ الْمَكَانِ وَوَضَعَهُ تَحْتَ رَأْسِهِ، فَاضْطَجَعَ فِي ذَلِكَ الْمَكَانِ.', 'تكوين 28:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 12, 'وَرَأَى حُلْمًا، وَإِذَا سُلَّمٌ مَنْصُوبَةٌ عَلَى الْأَرْضِ وَرَأْسُهَا يَمَسُّ السَّمَاءَ، وَهُوَذَا مَلَائِكَةُ اللهِ صَاعِدَةٌ وَنَازِلَةٌ عَلَيْهَا.', 'تكوين 28:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 13, 'وَهُوَذَا الرَّبُّ وَاقِفٌ عَلَيْهَا، فَقَالَ׃ «أَنَا الرَّبُّ إِلَهُ إِبْرَاهِيمَ أَبِيكَ وَإِلَهُ إِسْحَاقَ. الْأَرْضُ الَّتِي أَنْتَ مُضْطَجِعٌ عَلَيْهَا أُعْطِيهَا لَكَ وَلِنَسْلِكَ.', 'تكوين 28:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 14, 'وَيَكُونُ نَسْلُكَ كَتُرَابِ الْأَرْضِ، وَتَمْتَدُّ غَرْبًا وَشَرْقًا وَشَمَالًا وَجَنُوبًا، وَيَتَبَارَكُ فِيكَ وَفِي نَسْلِكَ جَمِيعُ قَبَائِلِ الْأَرْضِ.', 'تكوين 28:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 15, 'وَهَا أَنَا مَعَكَ، وَأَحْفَظُكَ حَيْثُمَا تَذْهَبُ، وَأَرُدُّكَ إِلَى هَذِهِ الْأَرْضِ، لِأَنِّي لَا أَتْرُكُكَ حَتَّى أَفْعَلَ مَا كَلَّمْتُكَ بِهِ».', 'تكوين 28:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 16, 'فَاسْتَيْقَظَ يَعْقُوبُ مِنْ نَوْمِهِ وَقَالَ׃ «حَقًّا إِنَّ الرَّبَّ فِي هَذَا الْمَكَانِ وَأَنَا لَمْ أَعْلَمْ!».', 'تكوين 28:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 17, 'وَخَافَ وَقَالَ׃ «مَا أَرْهَبَ هَذَا الْمَكَانَ! مَا هَذَا إِلَا بَيْتُ اللهِ، وَهَذَا بَابُ السَّمَاءِ».', 'تكوين 28:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 18, 'وَبَكَّرَ يَعْقُوبُ فِي الصَّبَاحِ وَأَخَذَ الْحَجَرَ الَّذِي وَضَعَهُ تَحْتَ رَأْسِهِ وَأَقَامَهُ عَمُودًا، وَصَبَّ زَيْتًا عَلَى رَأْسِهِ.', 'تكوين 28:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 19, 'وَدَعَا اسْمَ ذَلِكَ الْمَكَانِ «بَيْتَ إِيلَ»، وَلَكِنِ اسْمُ الْمَدِينَةِ أَوَّلًا كَانَ لُوزَ.', 'تكوين 28:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 20, 'وَنَذَرَ يَعْقُوبُ نَذْرًا قَائِلًا׃ «إِنْ كَانَ اللهُ مَعِي، وَحَفِظَنِي فِي هَذَا الطَّرِيقِ الَّذِي أَنَا سَائِرٌ فِيهِ، وَأَعْطَانِي خُبْزًا لِآكُلَ وَثِيَابًا لِأَلْبَسَ،', 'تكوين 28:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 21, 'وَرَجَعْتُ بِسَلَامٍ إِلَى بَيْتِ أَبِي، يَكُونُ الرَّبُّ لِي إِلَهًا،', 'تكوين 28:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 28, 22, 'وَهَذَا الْحَجَرُ الَّذِي أَقَمْتُهُ عَمُودًا يَكُونُ بَيْتَ اللهِ، وَكُلُّ مَا تُعْطِينِي فَإِنِّي أُعَشِّرُهُ لَكَ».', 'تكوين 28:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 1, 'ثُمَّ رَفَعَ يَعْقُوبُ رِجْلَيْهِ وَذَهَبَ إِلَى أَرْضِ بَنِي الْمَشْرِقِ.', 'تكوين 29:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 2, 'وَنَظَرَ وَإِذَا فِي الْحَقْلِ بِئْرٌ وَهُنَاكَ ثَلَاثَةُ قُطْعَانِ غَنَمٍ رَابِضَةٌ عِنْدَهَا، لِأَنَّهُمْ كَانُوا مِنْ تِلْكَ الْبِئْرِ يَسْقُونَ الْقُطْعَانَ، وَالْحَجَرُ عَلَى فَمِ الْبِئْرِ كَانَ كَبِيرًا.', 'تكوين 29:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 3, 'فَكَانَ يَجْتَمِعُ إِلَى هُنَاكَ جَمِيعُ الْقُطْعَانِ فَيُدَحْرِجُونَ الْحَجَرَ عَنْ فَمِ الْبِئْرِ وَيَسْقُونَ الْغَنَمَ، ثُمَّ يَرُدُّونَ الْحَجَرَ عَلَى فَمِ الْبِئْرِ إِلَى مَكَانِهِ.', 'تكوين 29:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 4, 'فَقَالَ لَهُمْ يَعْقُوبُ׃ «يَا إِخْوَتِي، مِنْ أَيْنَ أَنْتُمْ؟» فَقَالُوا׃ «نَحْنُ مِنْ حَارَانَ».', 'تكوين 29:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 5, 'فَقَالَ لَهُمْ׃ «هَلْ تَعْرِفُونَ لَابَانَ ابْنَ نَاحُورَ؟» فَقَالُوا׃ «نَعْرِفُهُ».', 'تكوين 29:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 6, 'فَقَالَ لَهُمْ׃ «هَلْ لَهُ سَلَامَةٌ؟» فَقَالُوا׃ «لَهُ سَلَامَةٌ. وَهُوَذَا رَاحِيلُ ابْنَتُهُ آتِيَةٌ مَعَ الْغَنَمِ».', 'تكوين 29:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 7, 'فَقَالَ׃ «هُوَذَا النَّهَارُ بَعْدُ طَوِيلٌ. لَيْسَ وَقْتَ اجْتِمَاعِ الْمَوَاشِي. اِسْقُوا الْغَنَمَ وَاذْهَبُوا ارْعَوْا».', 'تكوين 29:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 8, 'فَقَالُوا׃ «لَا نَقْدِرُ حَتَّى تَجْتَمِعَ جَمِيعُ الْقُطْعَانِ وَيُدَحْرِجُوا الْحَجَرَ عَنْ فَمِ الْبِئْرِ، ثُمَّ نَسْقِي الْغَنَمَ».', 'تكوين 29:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 9, 'وَإِذْ هُوَ بَعْدُ يَتَكَلَّمُ مَعَهُمْ أَتَتْ رَاحِيلُ مَعَ غَنَمِ أَبِيهَا، لِأَنَّهَا كَانَتْ تَرْعَى.', 'تكوين 29:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 10, 'فَكَانَ لَمَّا أَبْصَرَ يَعْقُوبُ رَاحِيلَ بِنْتَ لَابَانَ خَالِهِ، وَغَنَمَ لَابَانَ خَالِهِ، أَنَّ يَعْقُوبَ تَقَدَّمَ وَدَحْرَجَ الْحَجَرَ عَنْ فَمِ الْبِئْرِ وَسَقَى غَنَمَ لَابَانَ خَالِهِ.', 'تكوين 29:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 11, 'وَقَبَّلَ يَعْقُوبُ رَاحِيلَ وَرَفَعَ صَوْتَهُ وَبَكَى.', 'تكوين 29:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 12, 'وَأَخْبَرَ يَعْقُوبُ رَاحِيلَ أَنَّهُ أَخُو أَبِيهَا، وَأَنَّهُ ابْنُ رِفْقَةَ، فَرَكَضَتْ وَأَخْبَرَتْ أَبَاهَا.', 'تكوين 29:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 13, 'فَكَانَ حِينَ سَمِعَ لَابَانُ خَبَرَ يَعْقُوبَ ابْنِ أُخْتِهِ أَنَّهُ رَكَضَ لِلِقَائِهِ وَعَانَقَهُ وَقَبَّلَهُ وَأَتَى بِهِ إِلَى بَيْتِهِ. فَحَدَّثَ لَابَانَ بِجَمِيعِ هَذِهِ الْأُمُورِ.', 'تكوين 29:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 14, 'فَقَالَ لَهُ لَابَانُ׃ «إِنَّمَا أَنْتَ عَظْمِي وَلَحْمِي». فَأَقَامَ عِنْدَهُ شَهْرًا مِنَ الزَّمَانِ.', 'تكوين 29:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 15, 'ثُمَّ قَالَ لَابَانُ لِيَعْقُوبَ׃ «أَلِأَنَّكَ أَخِي تَخْدِمُنِي مَجَّانًا؟ أَخْبِرْنِي مَا أُجْرَتُكَ».', 'تكوين 29:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 16, 'وَكَانَ لِلَابَانَ ابْنَتَانِ، اسْمُ الْكُبْرَى لَيْئَةُ وَاسْمُ الصُّغْرَى رَاحِيلُ.', 'تكوين 29:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 17, 'وَكَانَتْ عَيْنَا لَيْئَةَ ضَعِيفَتَيْنِ، وَأَمَّا رَاحِيلُ فَكَانَتْ حَسَنَةَ الصُّورَةِ وَحَسَنَةَ الْمَنْظَرِ.', 'تكوين 29:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 18, 'وَأَحَبَّ يَعْقُوبُ رَاحِيلَ، فَقَالَ׃ «أَخْدِمُكَ سَبْعَ سِنِينٍ بِرَاحِيلَ ابْنَتِكَ الصُّغْرَى».', 'تكوين 29:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 19, 'فَقَالَ لَابَانُ׃ «أَنْ أُعْطِيَكَ إِيَّاهَا أَحْسَنُ مِنْ أَنْ أُعْطِيَهَا لِرَجُلٍ آخَرَ. أَقِمْ عِنْدِي».', 'تكوين 29:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 20, 'فَخَدَمَ يَعْقُوبُ بِرَاحِيلَ سَبْعَ سِنِينٍ، وَكَانَتْ فِي عَيْنَيْهِ كَأَيَّامٍ قَلِيلَةٍ بِسَبَبِ مَحَبَّتِهِ لَهَا.', 'تكوين 29:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 21, 'ثُمَّ قَالَ يَعْقُوبُ لِلَابَانَ׃ «أَعْطِنِي امْرَأَتِي لِأَنَّ أَيَّامِي قَدْ كَمُلَتْ، فَأَدْخُلَ عَلَيْهَا».', 'تكوين 29:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 22, 'فَجَمَعَ لَابَانُ جَمِيعَ أَهْلِ الْمَكَانِ وَصَنَعَ وَلِيمَةً.', 'تكوين 29:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 23, 'وَكَانَ فِي الْمَسَاءِ أَنَّهُ أَخَذَ لَيْئَةَ ابْنَتَهُ وَأَتَى بِهَا إِلَيْهِ، فَدَخَلَ عَلَيْهَا.', 'تكوين 29:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 24, 'وَأَعْطَى لَابَانُ زِلْفَةَ جَارِيَتَهُ لِلَيْئَةَ ابْنَتِهِ جَارِيَةً.', 'تكوين 29:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 25, 'وَفِي الصَّبَاحِ إِذَا هِيَ لَيْئَةُ، فَقَالَ لِلَابَانَ׃ «مَا هَذَا الَّذِي صَنَعْتَ بِي؟ أَلَيْسَ بِرَاحِيلَ خَدَمْتُ عِنْدَكَ؟ فَلِمَاذَا خَدَعْتَنِي؟».', 'تكوين 29:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 26, 'فَقَالَ لَابَانُ׃ «لَا يُفْعَلُ هَكَذَا فِي مَكَانِنَا أَنْ تُعْطَى الصَّغِيرَةُ قَبْلَ الْبِكْرِ.', 'تكوين 29:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 27, 'أَكْمِلْ أُسْبُوعَ هَذِهِ، فَنُعْطِيَكَ تِلْكَ أَيْضًا، بِالْخِدْمَةِ الَّتِي تَخْدِمُنِي أَيْضًا سَبْعَ سِنِينٍ أُخَرَ».', 'تكوين 29:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 28, 'فَفَعَلَ يَعْقُوبُ هَكَذَا. فَأَكْمَلَ أُسْبُوعَ هَذِهِ، فَأَعْطَاهُ رَاحِيلَ ابْنَتَهُ زَوْجَةً لَهُ.', 'تكوين 29:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 29, 'وَأَعْطَى لَابَانُ رَاحِيلَ ابْنَتَهُ بِلْهَةَ جَارِيَتَهُ جَارِيَةً لَهَا.', 'تكوين 29:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 30, 'فَدَخَلَ عَلَى رَاحِيلَ أَيْضًا، وَأَحَبَّ أَيْضًا رَاحِيلَ أَكْثَرَ مِنْ لَيْئَةَ. وَعَادَ فَخَدَمَ عِنْدَهُ سَبْعَ سِنِينٍ أُخَرَ.', 'تكوين 29:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 31, 'وَرَأَى الرَّبُّ أَنَّ لَيْئَةَ مَكْرُوهَةٌ فَفَتَحَ رَحِمَهَا، وَأَمَّا رَاحِيلُ فَكَانَتْ عَاقِرًا.', 'تكوين 29:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 32, 'فَحَبِلَتْ لَيْئَةُ وَوَلَدَتِ ابْنًا وَدَعَتِ اسْمَهُ «رَأُوبَيْنَ»، لِأَنَّهَا قَالَتْ׃ «إِنَّ الرَّبَّ قَدْ نَظَرَ إِلَى مَذَلَّتِي. إِنَّهُ الْآنَ يُحِبُّنِي رَجُلِي».', 'تكوين 29:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 33, 'وَحَبِلَتْ أَيْضًا وَوَلَدَتِ ابْنًا، وَقَالَتْ׃ «إِنَّ الرَّبَّ قَدْ سَمِعَ أَنِّي مَكْرُوهَةٌ فَأَعْطَانِي هَذَا أَيْضًا». فَدَعَتِ اسْمَهُ «شِمْعُونَ».', 'تكوين 29:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 34, 'وَحَبِلَتْ أَيْضًا وَوَلَدَتِ ابْنًا، وَقَالَتِ׃ «الْآنَ هَذِهِ الْمَرَّةَ يَقْتَرِنُ بِي رَجُلِي، لِأَنِّي وَلَدْتُ لَهُ ثَلَاثَةَ بَنِينَ». لِذَلِكَ دُعِيَ اسْمُهُ «لَاوِيَ».', 'تكوين 29:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 29, 35, 'وَحَبِلَتْ أَيْضًا وَوَلَدَتِ ابْنًا وَقَالَتْ׃ «هَذِهِ الْمَرَّةَ أَحْمَدُ الرَّبَّ». لِذَلِكَ دَعَتِ اسْمَهُ «يَهُوذَا». ثُمَّ تَوَقَّفَتْ عَنِ الْوِلَادَةِ.', 'تكوين 29:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 1, 'فَلَمَّا رَأَتْ رَاحِيلُ أَنَّهَا لَمْ تَلِدْ لِيَعْقُوبَ، غَارَتْ رَاحِيلُ مِنْ أُخْتِهَا، وَقَالَتْ لِيَعْقُوبَ׃ «هَبْ لِي بَنِينَ، وَإِلَا فَأَنَا أَمُوتُ!».', 'تكوين 30:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 2, 'فَحَمِيَ غَضَبُ يَعْقُوبَ عَلَى رَاحِيلَ وَقَالَ׃ «أَلَعَلِّي مَكَانَ اللهِ الَّذِي مَنَعَ عَنْكِ ثَمْرَةَ الْبَطْنِ؟».', 'تكوين 30:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 3, 'فَقَالَتْ׃ «هُوَذَا جَارِيَتِي بِلْهَةُ، ادْخُلْ عَلَيْهَا فَتَلِدَ عَلَى رُكْبَتَيَّ، وَأُرْزَقُ أَنَا أَيْضًا مِنْهَا بَنِينَ».', 'تكوين 30:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 4, 'فَأَعْطَتْهُ بِلْهَةَ جَارِيَتَهَا زَوْجَةً، فَدَخَلَ عَلَيْهَا يَعْقُوبُ،', 'تكوين 30:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 5, 'فَحَبِلَتْ بِلْهَةُ وَوَلَدَتْ لِيَعْقُوبَ ابْنًا،', 'تكوين 30:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 6, 'فَقَالَتْ رَاحِيلُ׃ «قَدْ قَضَى لِيَ اللهُ وَسَمِعَ أَيْضًا لِصَوْتِي وَأَعْطَانِيَ ابْنًا». لِذَلِكَ دَعَتِ اسْمَهُ «دَانًا».', 'تكوين 30:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 7, 'وَحَبِلَتْ أَيْضًا بِلْهَةُ جَارِيَةُ رَاحِيلَ وَوَلَدَتِ ابْنًا ثَانِيًا لِيَعْقُوبَ،', 'تكوين 30:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 8, 'فَقَالَتْ رَاحِيلُ׃ «مُصَارَعَاتِ اللهِ قَدْ صَارَعْتُ أُخْتِي وَغَلَبْتُ». فَدَعَتِ اسْمَهُ «نَفْتَالِي».', 'تكوين 30:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 9, 'وَلَمَّا رَأَتْ لَيْئَةُ أَنَّهَا تَوَقَّفَتْ عَنِ الْوِلَادَةِ، أَخَذَتْ زِلْفَةَ جَارِيَتَهَا وَأَعْطَتْهَا لِيَعْقُوبَ زَوْجَةً،', 'تكوين 30:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 10, 'فَوَلَدَتْ زِلْفَةُ جَارِيَةُ لَيْئَةَ لِيَعْقُوبَ ابْنًا.', 'تكوين 30:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 11, 'فَقَالَتْ لَيْئَةُ׃ «بِسَعْدٍ». فَدَعَتِ اسْمَهُ «جَادًا».', 'تكوين 30:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 12, 'وَوَلَدَتْ زِلْفَةُ جَارِيَةُ لَيْئَةَ ابْنًا ثَانِيًا لِيَعْقُوبَ،', 'تكوين 30:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 13, 'فَقَالَتْ لَيْئَةُ׃ «بِغِبْطَتِي، لِأَنَّهُ تُغَبِّطُنِي بَنَاتٌ». فَدَعَتِ اسْمَهُ «أَشِيرَ».', 'تكوين 30:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 14, 'وَمَضَى رَأُوبَيْنُ فِي أَيَّامِ حَصَادِ الْحِنْطَةِ فَوَجَدَ لُفَّاحًا فِي الْحَقْلِ وَجَاءَ بِهِ إِلَى لَيْئَةَ أُمِّهِ. فَقَالَتْ رَاحِيلُ لِلَيْئَةَ׃ «أَعْطِينِي مِنْ لُفَّاحِ ابْنِكِ».', 'تكوين 30:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 15, 'فَقَالَتْ لَهَا׃ «أَقَلِيلٌ أَنَّكِ أَخَذْتِ رَجُلِي فَتَأْخُذِينَ لُفَّاحَ ابْنِي أَيْضًا؟» فَقَالَتْ رَاحِيلُ׃ «إِذًا يَضْطَجِعُ مَعَكِ اللَّيْلَةَ عِوَضًا عَنْ لُفَّاحِ ابْنِكِ».', 'تكوين 30:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 16, 'فَلَمَّا أَتَى يَعْقُوبُ مِنَ الْحَقْلِ فِي الْمَسَاءِ، خَرَجَتْ لَيْئَةُ لِمُلَاقَاتِهِ وَقَالَتْ׃ «إِلَيَّ تَجِيءُ لِأَنِّي قَدِ اسْتَأْجَرْتُكَ بِلُفَّاحِ ابْنِي». فَاضْطَجَعَ مَعَهَا تِلْكَ اللَّيْلَةَ.', 'تكوين 30:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 17, 'وَسَمِعَ اللهُ لِلَيْئَةَ فَحَبِلَتْ وَوَلَدَتْ لِيَعْقُوبَ ابْنًا خَامِسًا.', 'تكوين 30:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 18, 'فَقَالَتْ لَيْئَةُ׃ «قَدْ أَعْطَانِي اللهُ أُجْرَتِي، لِأَنِّي أَعْطَيْتُ جَارِيَتِي لِرَجُلِي». فَدَعَتِ اسْمَهُ «يَسَّاكَرَ».', 'تكوين 30:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 19, 'وَحَبِلَتْ أَيْضًا لَيْئَةُ وَوَلَدَتِ ابْنًا سَادِسًا لِيَعْقُوبَ،', 'تكوين 30:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 20, 'فَقَالَتْ لَيْئَةُ׃ «قَدْ وَهَبَنِي اللهُ هِبَةً حَسَنَةً. الْآنَ يُسَاكِنُنِي رَجُلِي، لِأَنِّي وَلَدْتُ لَهُ سِتَّةَ بَنِينَ». فَدَعَتِ اسْمَهُ «زَبُولُونَ».', 'تكوين 30:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 21, 'ثُمَّ وَلَدَتِ ابْنَةً وَدَعَتِ اسْمَهَا «دِينَةَ».', 'تكوين 30:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 22, 'وَذَكَرَ اللهُ رَاحِيلَ، وَسَمِعَ لَهَا اللهُ وَفَتَحَ رَحِمَهَا،', 'تكوين 30:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 23, 'فَحَبِلَتْ وَوَلَدَتِ ابْنًا فَقَالَتْ׃ «قَدْ نَزَعَ اللهُ عَارِي».', 'تكوين 30:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 24, 'وَدَعَتِ اسْمَهُ «يُوسُفَ» قَائِلَةً׃ «يَزِيدُنِي الرَّبُّ ابْنًا آخَرَ».', 'تكوين 30:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 25, 'وَحَدَثَ لَمَّا وَلَدَتْ رَاحِيلُ يُوسُفَ أَنَّ يَعْقُوبَ قَالَ لِلَابَانَ׃ «اصْرِفْنِي لِأَذْهَبَ إِلَى مَكَانِي وَإِلَى أَرْضِي.', 'تكوين 30:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 26, 'أَعْطِنِي نِسَائِي وَأَوْلَادِي الَّذِينَ خَدَمْتُكَ بِهِمْ فَأَذْهَبَ، لِأَنَّكَ أَنْتَ تَعْلَمُ خِدْمَتِي الَّتِي خَدَمْتُكَ».', 'تكوين 30:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 27, 'فَقَالَ لَهُ لَابَانُ׃ «لَيْتَنِي أَجِدُ نِعْمَةً فِي عَيْنَيْكَ. قَدْ تَفَاءَلْتُ فَبَارَكَنِي الرَّبُّ بِسَبَبِكَ».', 'تكوين 30:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 28, 'وَقَالَ׃ «عَيِّنْ لِي أُجْرَتَكَ فَأُعْطِيَكَ».', 'تكوين 30:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 29, 'فَقَالَ لَهُ׃ «أَنْتَ تَعْلَمُ مَاذَا خَدَمْتُكَ، وَمَاذَا صَارَتْ مَوَاشِيكَ مَعِي،', 'تكوين 30:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 30, 'لِأَنَّ مَا كَانَ لَكَ قَبْلِي قَلِيلٌ فَقَدِ اتَّسَعَ إِلَى كَثِيرٍ، وَبَارَكَكَ الرَّبُّ فِي أَثَرِي. وَالْآنَ مَتَى أَعْمَلُ أَنَا أَيْضًا لِبَيْتِي؟».', 'تكوين 30:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 31, 'فَقَالَ׃ «مَاذَا أُعْطِيكَ؟» فَقَالَ يَعْقُوبُ׃ «لَا تُعْطِينِي شَيْئًا. إِنْ صَنَعْتَ لِي هَذَا الْأَمْرَ أَعُودُ أَرْعَى غَنَمَكَ وَأَحْفَظُهَا׃', 'تكوين 30:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 32, 'أَجْتَازُ بَيْنَ غَنَمِكَ كُلِّهَا الْيَوْمَ، وَاعْزِلْ أَنْتَ مِنْهَا كُلَّ شَاةٍ رَقْطَاءَ وَبَلْقَاءَ، وَكُلَّ شَاةٍ سَوْدَاءَ بَيْنَ الْخِرْفَانِ، وَبَلْقَاءَ وَرَقْطَاءَ بَيْنَ الْمِعْزَى. فَيَكُونَ مِثْلُ ذَلِكَ أُجْرَتِي.', 'تكوين 30:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 33, 'وَيَشْهَدُ فِيَّ بِرِّي يَوْمَ غَدٍ إِذَا جِئْتَ مِنْ أَجْلِ أُجْرَتِي قُدَّامَكَ. كُلُّ مَا لَيْسَ أَرْقَطَ أَوْ أَبْلَقَ بَيْنَ الْمِعْزَى وَأَسْوَدَ بَيْنَ الْخِرْفَانِ فَهُوَ مَسْرُوقٌ عِنْدِي».', 'تكوين 30:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 34, 'فَقَالَ لَابَانُ׃ «هُوَذَا لِيَكُنْ بِحَسَبِ كَلَامِكَ».', 'تكوين 30:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 35, 'فَعَزَلَ فِي ذَلِكَ الْيَوْمِ التُّيُوسَ الْمُخَطَّطَةَ وَالْبَلْقَاءَ، وَكُلَّ الْعِنَازِ الرَّقْطَاءِ وَالْبَلْقَاءِ، كُلَّ مَا فِيهِ بَيَاضٌ وَكُلَّ أَسْوَدَ بَيْنَ الْخِرْفَانِ، وَدَفَعَهَا إِلَى أَيْدِي بَنِيهِ.', 'تكوين 30:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 36, 'وَجَعَلَ مَسِيرَةَ ثَلَاثَةِ أَيَّامٍ بَيْنَهُ وَبَيْنَ يَعْقُوبَ، وَكَانَ يَعْقُوبُ يَرْعَى غَنَمَ لَابَانَ الْبَاقِيَةَ.', 'تكوين 30:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 37, 'فَأَخَذَ يَعْقُوبُ لِنَفْسِهِ قُضْبَانًا خُضْرًا مِنْ لُبْنَى وَلَوْزٍ وَدُلْبٍ، وَقَشَّرَ فِيهَا خُطُوطًا بِيضًا، كَاشِطًا عَنِ الْبَيَاضِ الَّذِي عَلَى الْقُضْبَانِ.', 'تكوين 30:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 38, 'وَأَوْقَفَ الْقُضْبَانَ الَّتِي قَشَّرَهَا فِي الْأَجْرَانِ فِي مَسَاقِي الْمَاءِ حَيْثُ كَانَتِ الْغَنَمُ تَجِيءُ لِتَشْرَبَ، تُجَاهَ الْغَنَمِ، لِتَتَوَحَّمَ عِنْدَ مَجِيئِهَا لِتَشْرَبَ.', 'تكوين 30:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 39, 'فَتَوَحَّمَتِ الْغَنَمُ عِنْدَ الْقُضْبَانِ، وَوَلَدَتِ الْغَنَمُ مُخَطَّطَاتٍ وَرُقْطًا وَبُلْقًا.', 'تكوين 30:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 40, 'وَأَفْرَزَ يَعْقُوبُ الْخِرْفَانَ وَجَعَلَ وُجُوهَ الْغَنَمِ إِلَى الْمُخَطَّطِ وَكُلِّ أَسْوَدَ بَيْنَ غَنَمِ لَابَانَ. وَجَعَلَ لَهُ قُطْعَانًا وَحْدَهُ وَلَمْ يَجْعَلْهَا مَعَ غَنَمِ لَابَانَ.', 'تكوين 30:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 41, 'وَحَدَثَ كُلَّمَا تَوَحَّمَتِ الْغَنَمُ الْقَوِيَّةُ أَنَّ يَعْقُوبَ وَضَعَ الْقُضْبَانَ أَمَامَ عُيُونِ الْغَنَمِ فِي الْأَجْرَانِ لِتَتَوَحَّمَ بَيْنَ الْقُضْبَانِ.', 'تكوين 30:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 42, 'وَحِينَ اسْتَضْعَفَتِ الْغَنَمُ لَمْ يَضَعْهَا، فَصَارَتِ الضَّعِيفَةُ لِلَابَانَ وَالْقَوِيَّةُ لِيَعْقُوبَ.', 'تكوين 30:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 30, 43, 'فَاتَّسَعَ الرَّجُلُ كَثِيرًا جِدًّا، وَكَانَ لَهُ غَنَمٌ كَثِيرٌ وَجَوَارٍ وَعَبِيدٌ وَجِمَالٌ وَحَمِيرٌ.', 'تكوين 30:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 1, 'فَسَمِعَ كَلَامَ بَنِي لَابَانَ قَائِلِينَ׃ «أَخَذَ يَعْقُوبُ كُلَّ مَا كَانَ لِأَبِينَا، وَمِمَّا لِأَبِينَا صَنَعَ كُلَّ هَذَا الْمَجْدِ».', 'تكوين 31:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 2, 'وَنَظَرَ يَعْقُوبُ وَجْهَ لَابَانَ وَإِذَا هُوَ لَيْسَ مَعَهُ كَأَمْسِ وَأَوَّلَ مِنْ أَمْسِ.', 'تكوين 31:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 3, 'وَقَالَ الرَّبُّ لِيَعْقُوبَ׃ «ارْجِعْ إِلَى أَرْضِ آبَائِكَ وَإِلَى عَشِيرَتِكَ، فَأَكُونَ مَعَكَ».', 'تكوين 31:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 4, 'فَأَرْسَلَ يَعْقُوبُ وَدَعَا رَاحِيلَ وَلَيْئَةَ إِلَى الْحَقْلِ إِلَى غَنَمِهِ،', 'تكوين 31:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 5, 'وَقَالَ لَهُمَا׃ «أَنَا أَرَى وَجْهَ أَبِيكُمَا أَنَّهُ لَيْسَ نَحْوِي كَأَمْسِ وَأَوَّلَ مِنْ أَمْسِ. وَلَكِنْ إِلَهُ أَبِي كَانَ مَعِي.', 'تكوين 31:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 6, 'وَأَنْتُمَا تَعْلَمَانِ أَنِّي بِكُلِّ قُوَّتِي خَدَمْتُ أَبَاكُمَا،', 'تكوين 31:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 7, 'وَأَمَّا أَبُوكُمَا فَغَدَرَ بِي وَغَيَّرَ أُجْرَتِي عَشَرَ مَرَّاتٍ. لَكِنَّ اللهَ لَمْ يَسْمَحْ لَهُ أَنْ يَصْنَعَ بِي شَرًّا.', 'تكوين 31:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 8, 'إِنْ قَالَ هَكَذَا׃ الرُّقْطُ تَكُونُ أُجْرَتَكَ، وَلَدَتْ كُلُّ الْغَنَمِ رُقْطًا. وَإِنْ قَالَ هَكَذَا׃ الْمُخَطَّطَةُ تَكُونُ أُجْرَتَكَ، وَلَدَتْ كُلُّ الْغَنَمِ مُخَطَّطَةً.', 'تكوين 31:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 9, 'فَقَدْ سَلَبَ اللهُ مَوَاشِيَ أَبِيكُمَا وَأَعْطَانِي.', 'تكوين 31:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 10, 'وَحَدَثَ فِي وَقْتِ تَوَحُّمِ الْغَنَمِ أَنِّي رَفَعْتُ عَيْنَيَّ وَنَظَرْتُ فِي حُلْمٍ، وَإِذَا الْفُحُولُ الصَّاعِدَةُ عَلَى الْغَنَمِ مُخَطَّطَةٌ وَرَقْطَاءُ وَمُنَمَّرَةٌ.', 'تكوين 31:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 11, 'وَقَالَ لِي مَلَاكُ اللهِ فِي الْحُلْمِ׃ يَا يَعْقُوبُ. فَقُلْتُ׃ هَأَنَذَا.', 'تكوين 31:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 12, 'فَقَالَ׃ ارْفَعْ عَيْنَيْكَ وَانْظُرْ. جَمِيعُ الْفُحُولِ الصَّاعِدَةِ عَلَى الْغَنَمِ مُخَطَّطَةٌ وَرَقْطَاءُ وَمُنَمَّرَةٌ، لِأَنِّي قَدْ رَأَيْتُ كُلَّ مَا يَصْنَعُ بِكَ لَابَانُ.', 'تكوين 31:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 13, 'أَنَا إِلَهُ بَيْتِ إِيلَ حَيْثُ مَسَحْتَ عَمُودًا، حَيْثُ نَذَرْتَ لِي نَذْرًا. الْآنَ قُمِ اخْرُجْ مِنْ هَذِهِ الْأَرْضِ وَارْجِعْ إِلَى أَرْضِ مِيلَادِكَ».', 'تكوين 31:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 14, 'فَأَجَابَتْ رَاحِيلُ وَلَيْئَةُ وَقَاَلتَا لَهُ׃ «أَلَنَا أَيْضًا نَصِيبٌ وَمِيرَاثٌ فِي بَيْتِ أَبِينَا؟', 'تكوين 31:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 15, 'أَلَمْ نُحْسَبْ مِنْهُ أَجْنَبِيَّتَيْنِ، لِأَنَّهُ بَاعَنَا وَقَدْ أَكَلَ أَيْضًا ثَمَنَنَا؟', 'تكوين 31:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 16, 'إِنَّ كُلَّ الْغِنَى الَّذِي سَلَبَهُ اللهُ مِنْ أَبِينَا هُوَ لَنَا وَلِأَوْلَادِنَا، فَالْآنَ كُلَّ مَا قَالَ لَكَ اللهُ افْعَلْ».', 'تكوين 31:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 17, 'فَقَامَ يَعْقُوبُ وَحَمَلَ أَوْلَادَهُ وَنِسَاءَهُ عَلَى الْجِمَالِ،', 'تكوين 31:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 18, 'وَسَاقَ كُلَّ مَوَاشِيهِ وَجَمِيعَ مُقْتَنَاهُ الَّذِي كَانَ قَدِ اقْتَنَى׃ مَوَاشِيَ اقْتِنَائِهِ الَّتِي اقْتَنَى فِي فَدَّانِ أَرَامَ، لِيَجِيءَ إِلَى إِسْحَاقَ أَبِيهِ إِلَى أَرْضِ كَنْعَانَ.', 'تكوين 31:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 19, 'وَأَمَّا لَابَانُ فَكَانَ قَدْ مَضَى لِيَجُزَّ غَنَمَهُ، فَسَرَقَتْ رَاحِيلُ أَصْنَامَ أَبِيهَا.', 'تكوين 31:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 20, 'وَخَدَعَ يَعْقُوبُ قَلْبَ لَابَانَ الْأَرَامِيِّ إِذْ لَمْ يُخْبِرْهُ بِأَنَّهُ هَارِبٌ.', 'تكوين 31:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 21, 'فَهَرَبَ هُوَ وَكُلُّ مَا كَانَ لَهُ، وَقَامَ وَعَبَرَ النَّهْرَ وَجَعَلَ وَجْهَهُ نَحْوَ جَبَلِ جِلْعَادَ.', 'تكوين 31:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 22, 'فَأُخْبِرَ لَابَانُ فِي الْيَوْمِ الثَّالِثِ بِأَنَّ يَعْقُوبَ قَدْ هَرَبَ.', 'تكوين 31:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 23, 'فَأَخَذَ إِخْوَتَهُ مَعَهُ وَسَعَى وَرَاءَهُ مَسِيرَةَ سَبْعَةِ أَيَّامٍ، فَأَدْرَكَهُ فِي جَبَلِ جِلْعَادَ.', 'تكوين 31:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 24, 'وَأَتَى اللهُ إِلَى لَابَانَ الْأَرَامِيِّ فِي حُلْمِ اللَّيْلِ وَقَالَ لَهُ׃ «احْتَرِزْ مِنْ أَنْ تُكَلِّمَ يَعْقُوبَ بِخَيْرٍ أَوْ شَرٍّ».', 'تكوين 31:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 25, 'فَلَحِقَ لَابَانُ يَعْقُوبَ، وَيَعْقُوبُ قَدْ ضَرَبَ خَيْمَتَهُ فِي الْجَبَلِ. فَضَرَبَ لَابَانُ مَعَ إِخْوَتِهِ فِي جَبَلِ جِلْعَادَ.', 'تكوين 31:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 26, 'وَقَالَ لَابَانُ لِيَعْقُوبَ׃ «مَاذَا فَعَلْتَ، وَقَدْ خَدَعْتَ قَلْبِي، وَسُقْتَ بَنَاتِي كَسَبَايَا السَّيْفِ؟', 'تكوين 31:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 27, 'لِمَاذَا هَرَبْتَ خُفْيَةً وَخَدَعْتَنِي وَلَمْ تُخْبِرْنِي حَتَّى أُشَيِّعَكَ بِالْفَرَحِ وَالْأَغَانِيِّ، بِالدُّفِّ وَالْعُودِ،', 'تكوين 31:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 28, 'وَلَمْ تَدَعْنِي أُقَبِّلُ بَنِيَّ وَبَنَاتِي؟ الْآنَ بِغَبَاوَةٍ فَعَلْتَ!', 'تكوين 31:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 29, 'فِي قُدْرَةِ يَدِي أَنْ أَصْنَعَ بِكُمْ شَرًّا، وَلَكِنْ إِلَهُ أَبِيكُمْ كَلَّمَنِيَ الْبَارِحَةَ قَائِلًا׃ احْتَرِزْ مِنْ أَنْ تُكَلِّمَ يَعْقُوبَ بِخَيْرٍ أَوْ شَرٍّ.', 'تكوين 31:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 30, 'وَالْآنَ أَنْتَ ذَهَبْتَ لِأَنَّكَ قَدِ اشْتَقْتَ إِلَى بَيْتِ أَبِيكَ، وَلَكِنْ لِمَاذَا سَرَقْتَ آلِهَتِي؟».', 'تكوين 31:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 31, 'فَأَجَابَ يَعْقُوبُ وَقَالَ لِلَابَانَ׃ «إِنِّي خِفْتُ لِأَنِّي قُلْتُ لَعَلَّكَ تَغْتَصِبُ ابْنَتَيْكَ مِنِّي.', 'تكوين 31:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 32, 'اَلَّذِي تَجِدُ آلِهَتَكَ مَعَهُ لَا يَعِيشُ. قُدَّامَ إِخْوَتِنَا انْظُرْ مَاذَا مَعِي وَخُذْهُ لِنَفْسِكَ». وَلَمْ يَكُنْ يَعْقُوبُ يَعْلَمُ أَنَّ رَاحِيلَ سَرَقَتْهَا.', 'تكوين 31:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 33, 'فَدَخَلَ لَابَانُ خِبَاءَ يَعْقُوبَ وَخِبَاءَ لَيْئَةَ وَخِبَاءَ الْجَارِيَتَيْنِ وَلَمْ يَجِدْ. وَخَرَجَ مِنْ خِبَاءِ لَيْئَةَ وَدَخَلَ خِبَاءَ رَاحِيلَ.', 'تكوين 31:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 34, 'وَكَانَتْ رَاحِيلُ قَدْ أَخَذَتِ الْأَصْنَامَ وَوَضَعَتْهَا فِي حِدَاجَةِ الْجَمَلِ وَجَلَسَتْ عَلَيْهَا. فَجَسَّ لَابَانُ كُلَّ الْخِبَاءِ وَلَمْ يَجِدْ.', 'تكوين 31:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 35, 'وَقَالَتْ لِأَبِيهَا׃ «لَا يَغْتَظْ سَيِّدِي أَنِّي لَا أَسْتَطِيعُ أَنْ أَقُومَ أَمَامَكَ لِأَنَّ عَلَيَّ عَادَةَ النِّسَاءِ». فَفَتَّشَ وَلَمْ يَجِدِ الْأَصْنَامَ.', 'تكوين 31:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 36, 'فَاغْتَاظَ يَعْقُوبُ وَخَاصَمَ لَابَانَ. وَأجَابَ يَعْقُوبُ وَقَالَ لِلَابَانَ׃ «مَا جُرْمِي؟ مَا خَطِيَّتِي حَتَّى حَمِيتَ وَرَائِي؟', 'تكوين 31:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 37, 'إِنَّكَ جَسَسْتَ جَمِيعَ أَثَاثِي. مَاذَا وَجَدْتَ مِنْ جَمِيعِ أَثَاثِ بَيْتِكَ؟ ضَعْهُ هَهُنَا قُدَّامَ إِخْوَتِي وَإِخْوَتِكَ، فَلْيُنْصِفُوا بَيْنَنَا الِاثْنَيْنِ.', 'تكوين 31:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 38, 'اَلْآنَ عِشْرِينَ سَنَةً أَنَا مَعَكَ. نِعَاجُكَ وَعِنَازُكَ لَمْ تُسْقِطْ، وَكِبَاشَ غَنَمِكَ لَمْ آكُلْ.', 'تكوين 31:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 39, 'فَرِيسَةً لَمْ أُحْضِرْ إِلَيْكَ. أَنَا كُنْتُ أَخْسَرُهَا. مِنْ يَدِي كُنْتَ تَطْلُبُهَا. مَسْرُوقَةَ النَّهَارِ أَوْ مَسْرُوقَةَ اللَّيْلِ.', 'تكوين 31:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 40, 'كُنْتُ فِي النَّهَارِ يَأْكُلُنِي الْحَرُّ وَفِي اللَّيْلِ الْجَلِيدُ، وَطَارَ نَوْمِي مِنْ عَيْنَيَّ.', 'تكوين 31:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 41, 'اَلْآنَ لِي عِشْرُونَ سَنَةً فِي بَيْتِكَ. خَدَمْتُكَ أَرْبَعَ عَشَرَةَ سَنَةً بَابْنَتَيْكَ، وَسِتَّ سِنِينٍ بِغَنَمِكَ. وَقَدْ غَيَّرْتَ أُجْرَتِي عَشَرَ مَرَّاتٍ.', 'تكوين 31:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 42, 'لَوْلَا أَنَّ إِلَهَ أَبِي إِلَهَ إِبْرَاهِيمَ وَهَيْبَةَ إِسْحَاقَ كَانَ مَعِي، لَكُنْتَ الْآنَ قَدْ صَرَفْتَنِي فَارِغًا. مَشَقَّتِي وَتَعَبَ يَدَيَّ قَدْ نَظَرَ اللهُ، فَوَبَّخَكَ الْبَارِحَةَ».', 'تكوين 31:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 43, 'فَأَجَابَ لَابَانُ وَقَالَ لِيَعقُوبَ׃ «الْبَنَاتُ بَنَاتِي، وَالْبَنُونَ بَنِيَّ، وَالْغَنَمُ غَنَمِي، وَكُلُّ مَا أَنْتَ تَرَى فَهُوَ لِي. فَبَنَاتِي مَاذَا أَصْنَعُ بِهِنَّ الْيَوْمَ أَوْ بِأَوْلَادِهِنَّ الَّذِينَ وَلَدْنَ؟', 'تكوين 31:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 44, 'فَالْآنَ هَلُمَّ نَقْطَعْ عَهْدًا أَنَا وَأَنْتَ، فَيَكُونُ شَاهِدًا بَيْنِي وَبَيْنَكَ».', 'تكوين 31:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 45, 'فَأَخَذَ يَعْقُوبُ حَجَرًا وَأَوْقَفَهُ عَمُودًا،', 'تكوين 31:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 46, 'وَقَالَ يَعْقُوبُ لِإِخْوَتِهِ׃ «الْتَقِطُوا حِجَارَةً». فَأَخَذُوا حِجَارَةً وَعَمِلُوا رُجْمَةً وَأَكَلُوا هُنَاكَ عَلَى الرُّجْمَةِ.', 'تكوين 31:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 47, 'وَدَعَاهَا لَابَانُ «يَجَرْ سَهْدُوثَا» وَأَمَّا يَعْقُوبُ فَدَعَاهَا «جَلْعِيدَ».', 'تكوين 31:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 48, 'وَقَالَ لَابَانُ׃ «هَذِهِ الرُّجْمَةُ هِيَ شَاهِدَةٌ بَيْنِي وَبَيْنَكَ الْيَوْمَ». لِذَلِكَ دُعِيَ اسْمُهَا «جَلْعِيدَ».', 'تكوين 31:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 49, 'وَ«الْمِصْفَاةَ»، لِأَنَّهُ قَالَ׃ «لِيُرَاقِبِ الرَّبُّ بَيْنِي وَبَيْنَكَ حِينَمَا نَتَوَارَى بَعْضُنَا عَنْ بَعْضٍ.', 'تكوين 31:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 50, 'إِنَّكَ لَا تُذِلُّ بَنَاتِي، وَلَا تَأْخُذُ نِسَاءً عَلَى بَنَاتِي. لَيْسَ إِنْسَانٌ مَعَنَا. اُنْظُرْ، اللهُ شَاهِدٌ بَيْنِي وَبَيْنَكَ».', 'تكوين 31:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 51, 'وَقَالَ لَابَانُ لِيَعْقُوبَ׃ «هُوَذَا هَذِهِ الرُّجْمَةُ، وَهُوَذَا الْعَمُودُ الَّذِي وَضَعْتُ بَيْنِي وَبَيْنَكَ.', 'تكوين 31:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 52, 'شَاهِدَةٌ هَذِهِ الرُّجْمَةُ وَشَاهِدٌ الْعَمُودُ أَنِّي لَا أَتَجَاوَزُ هَذِهِ الرُّجْمَةَ إِلَيْكَ، وَأَنَّكَ لَا تَتَجَاوَزُ هَذِهِ الرُّجْمَةَ وَهَذَا الْعَمُودَ إِلَيَّ لِلشَّرِّ.', 'تكوين 31:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 53, 'إِلَهُ إِبْرَاهِيمَ وَآلِهَةُ نَاحُورَ، آلِهَةُ أَبِيهِمَا، يَقْضُونَ بَيْنَنَا». وَحَلَفَ يَعْقُوبُ بِهَيْبَةِ أَبِيهِ إِسْحَاقَ.', 'تكوين 31:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 54, 'وَذَبَحَ يَعْقُوبُ ذَبِيحَةً فِي الْجَبَلِ وَدَعَا إِخْوَتَهُ لِيَأْكُلُوا طَعَامًا، فَأَكَلُوا طَعَامًا وَبَاتُوا فِي الْجَبَلِ.', 'تكوين 31:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 31, 55, 'ثُمَّ بَكَّرَ لَابَانُ صَبَاحًا وَقَبَّلَ بَنِيهِ وَبَنَاتِهِ وَبَارَكَهُمْ وَمَضَى. وَرَجَعَ لَابَانُ إِلَى مَكَانِهِ.', 'تكوين 31:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 1, 'وَأَمَّا يَعْقُوبُ فَمَضَى فِي طَرِيقِهِ وَلَاقَاهُ مَلَائِكَةُ اللهِ.', 'تكوين 32:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 2, 'وَقَالَ يَعْقُوبُ إِذْ رَآهُمْ׃ «هَذَا جَيْشُ اللهِ!». فَدَعَا اسْمَ ذَلِكَ الْمَكَانِ «مَحَنَايِمَ».', 'تكوين 32:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 3, 'وَأَرْسَلَ يَعْقُوبُ رُسُلًا قُدَّامَهُ إِلَى عِيسُوَ أَخِيهِ إِلَى أَرْضِ سَعِيرَ بِلَادِ أَدُومَ،', 'تكوين 32:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 4, 'وَأَمَرَهُمْ قَائِلًا׃ «هَكَذَا تَقُولُونَ لِسَيِّدِي عِيسُوَ׃ هَكَذَا قَالَ عَبْدُكَ يَعْقُوبُ׃ تَغَرَّبْتُ عِنْدَ لَابَانَ وَلَبِثْتُ إِلَى الْآنَ.', 'تكوين 32:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 5, 'وَقَدْ صَارَ لِي بَقَرٌ وَحَمِيرٌ وَغَنَمٌ وَعَبِيدٌ وَإِمَاءٌ. وَأَرْسَلْتُ لِأُخْبِرَ سَيِّدِي لِكَيْ أَجِدَ نِعْمَةً فِي عَيْنَيْكَ».', 'تكوين 32:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 6, 'فَرَجَعَ الرُّسُلُ إِلَى يَعْقُوبَ قَائِلِينَ׃ «أَتَيْنَا إِلَى أَخِيكَ، إِلَى عِيسُو، وَهُوَ أَيْضًا قَادِمٌ لِلِقَائِكَ، وَأَرْبَعُ مِئَةِ رَجُلٍ مَعَهُ».', 'تكوين 32:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 7, 'فَخَافَ يَعْقُوبُ جِدًّا وَضَاقَ بِهِ الْأَمْرُ، فَقَسَمَ الْقَوْمَ الَّذِينَ مَعَهُ وَالْغَنَمَ وَالْبَقَرَ وَالْجِمَالَ إِلَى جَيْشَيْنِ.', 'تكوين 32:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 8, 'وَقَالَ׃ «إِنْ جَاءَ عِيسُو إِلَى الْجَيْشِ الْوَاحِدِ وَضَرَبَهُ، يَكُونُ الْجَيْشُ الْبَاقِي نَاجِيًا».', 'تكوين 32:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 9, 'وَقَالَ يَعْقُوبُ׃ «يَا إِلَهَ أَبِي إِبْرَاهِيمَ وَإِلَهَ أَبِي إِسْحَاقَ، الرَّبَّ الَّذِي قَالَ لِيَ׃ ارْجِعْ إِلَى أَرْضِكَ وَإِلَى عَشِيرَتِكَ فَأُحْسِنَ إِلَيْكَ.', 'تكوين 32:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 10, 'صَغِيرٌ أَنَا عَنْ جَمِيعِ أَلْطَافِكَ وَجَمِيعِ الْأَمَانَةِ الَّتِي صَنَعْتَ إِلَى عَبْدِكَ. فَإِنِّي بِعَصَايَ عَبَرْتُ هَذَا الْأُرْدُنَّ، وَالْآنَ قَدْ صِرْتُ جَيْشَيْنِ.', 'تكوين 32:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 11, 'نَجِّنِي مِنْ يَدِ أَخِي، مِنْ يَدِ عِيسُوَ، لِأَنِّي خَائِفٌ مِنْهُ أَنْ يَأْتِيَ وَيَضْرِبَنِي الْأُمَّ مَعَ الْبَنِينَ.', 'تكوين 32:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 12, 'وَأَنْتَ قَدْ قُلْتَ׃ إِنِّي أُحْسِنُ إِلَيْكَ وَأَجْعَلُ نَسْلَكَ كَرَمْلِ الْبَحْرِ الَّذِي لَا يُعَدُّ لِلْكَثْرَةِ».', 'تكوين 32:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 13, 'وَبَاتَ هُنَاكَ تِلْكَ اللَّيْلَةَ وَأَخَذَ مِمَّا أَتَى بِيَدِهِ هَدِيَّةً لِعِيسُو أَخِيهِ׃', 'تكوين 32:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 14, 'مِئَتَيْ عَنْزٍ وَعِشْرِينَ تَيْسًا، مِئَتَيْ نَعْجَةٍ وَعِشْرِينَ كَبْشًا،', 'تكوين 32:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 15, 'ثَلَاثِينَ نَاقَةً مُرْضِعَةً وَأَوْلَادَهَا، أَرْبَعِينَ بَقَرَةً وَعَشْرَةَ ثِيرَانٍ، عِشْرِينَ أَتَانًا وَعَشْرَةَ حَمِيرٍ،', 'تكوين 32:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 16, 'وَدَفَعَهَا إِلَى يَدِ عَبِيدِهِ قَطِيعًا قَطِيعًا عَلَى حِدَةٍ. وَقَالَ لِعَبِيدِهِ׃ «اجْتَازُوا قُدَّامِي وَاجْعَلُوا فُسْحَةً بَيْنَ قَطِيعٍ وَقَطِيعٍ».', 'تكوين 32:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 17, 'وَأَمَرَ الْأَوَّلَ قَائِلًا׃ «إِذَا صَادَفَكَ عِيسُو أَخِي وَسَأَلَكَ قَائِلًا׃ لِمَنْ أَنْتَ؟ وَإِلَى أَيْنَ تَذْهَبُ؟ وَلِمَنْ هَذَا الَّذِي قُدَّامَكَ؟', 'تكوين 32:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 18, 'تَقُولُ׃ لِعَبْدِكَ يَعْقُوبَ. هُوَ هَدِيَّةٌ مُرْسَلَةٌ لِسَيِّدِي عِيسُوَ، وَهَا هُوَ أَيْضًا وَرَاءَنَا».', 'تكوين 32:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 19, 'وَأَمَرَ أَيْضًا الْثَانِى وَالثَّالِثَ وَجَمِيعَ السَّائِرِينَ وَرَاءَ الْقُطْعَانِ قَائِلًا׃ «بِمِثْلِ هَذَا الْكَلَامِ تُكَلِّمُونَ عِيسُوَ حِينَمَا تَجِدُونَهُ،', 'تكوين 32:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 20, 'وَتَقُولُونَ׃ هُوَذَا عَبْدُكَ يَعْقُوبُ أَيْضًا وَرَاءَنَا». لِأَنَّهُ قَالَ׃ «أَسْتَعْطِفُ وَجْهَهُ بِالْهَدِيَّةِ السَّائِرَةِ أَمَامِي، وَبَعْدَ ذَلِكَ أَنْظُرُ وَجْهَهُ، عَسَى أَنْ يَرْفَعَ وَجْهِي».', 'تكوين 32:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 21, 'فَاجْتَازَتِ الْهَدِيَّةُ قُدَّامَهُ، وَأَمَّا هُوَ فَبَاتَ تِلْكَ اللَّيْلَةَ فِي الْمَحَلَّةِ.', 'تكوين 32:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 22, 'ثُمَّ قَامَ فِي تِلْكَ اللَّيْلَةِ وَأَخَذَ امْرَأَتَيْهِ وَجَارِيَتَيْهِ وَأَوْلَادَهُ الْأَحَدَ عَشَرَ وَعَبَرَ مَخَاضَةَ يَبُّوقَ.', 'تكوين 32:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 23, 'أَخَذَهُمْ وَأَجَازَهُمُ الْوَادِيَ، وَأَجَازَ مَا كَانَ لَهُ.', 'تكوين 32:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 24, 'فَبَقِيَ يَعْقُوبُ وَحْدَهُ، وَصَارَعَهُ إِنْسَانٌ حَتَّى طُلُوعِ الْفَجْرِ.', 'تكوين 32:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 25, 'وَلَمَّا رَأَى أَنَّهُ لَا يَقْدِرُ عَلَيْهِ، ضَرَبَ حُقَّ فَخْذِهِ، فَانْخَلَعَ حُقُّ فَخْذِ يَعْقُوبَ فِي مُصَارَعَتِهِ مَعَهُ.', 'تكوين 32:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 26, 'وَقَالَ׃ «أَطْلِقْنِي، لِأَنَّهُ قَدْ طَلَعَ الْفَجْرُ». فَقَالَ׃ «لَا أُطْلِقُكَ إِنْ لَمْ تُبَارِكْنِي».', 'تكوين 32:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 27, 'فَقَالَ لَهُ׃ «مَا اسْمُكَ؟» فَقَالَ׃ «يَعْقُوبُ».', 'تكوين 32:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 28, 'فَقَالَ׃ «لَا يُدْعَى اسْمُكَ فِي مَا بَعْدُ يَعْقُوبَ بَلْ إِسْرَائِيلَ، لِأَنَّكَ جَاهَدْتَ مَعَ اللهِ وَالنَّاسِ وَقَدَرْتَ».', 'تكوين 32:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 29, 'وَسَأَلَ يَعْقُوبُ وَقَالَ׃ «أَخْبِرْنِي بِاسْمِكَ». فَقَالَ׃ «لِمَاذَا تَسْأَلُ عَنِ اسْمِي؟». وَبَارَكَهُ هُنَاكَ.', 'تكوين 32:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 30, 'فَدَعَا يَعْقُوبُ اسْمَ الْمَكَانِ «فَنِيئِيلَ» قَائِلًا׃ «لِأَنِّي نَظَرْتُ اللهَ وَجْهًا لِوَجْهٍ، وَنُجِّيَتْ نَفْسِي».', 'تكوين 32:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 31, 'وَأَشْرَقَتْ لَهُ الشَّمْسُ إِذْ عَبَرَ فَنُوئِيلَ وَهُوَ يَخْمَعُ عَلَى فَخْذِهِ.', 'تكوين 32:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 32, 32, 'لِذَلِكَ لَا يَأْكُلُ بَنُو إِسْرَائِيلَ عِرْقَ النَّسَا الَّذِي عَلَى حُقِّ الْفَخْذِ إِلَى هَذَا الْيَوْمِ، لِأَنَّهُ ضَرَبَ حُقَّ فَخْذِ يَعْقُوبَ عَلَى عِرْقِ النَّسَا.', 'تكوين 32:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 1, 'وَرَفَعَ يَعْقُوبُ عَيْنَيْهِ وَنَظَرَ وَإِذَا عِيسُو مُقْبِلٌ وَمَعَهُ أَرْبَعُ مِئَةِ رَجُلٍ، فَقَسَمَ الْأَوْلَادَ عَلَى لَيْئَةَ وَعَلَى رَاحِيلَ وَعَلَى الْجَارِيَتَيْنِ.', 'تكوين 33:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 2, 'وَوَضَعَ الْجَارِيَتَيْنِ وَأَوْلَادَهُمَا أَوَّلًا، وَلَيْئَةَ وَأَوْلَادَهَا وَرَاءَهُمْ، وَرَاحِيلَ وَيُوسُفَ أَخِيرًا.', 'تكوين 33:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 3, 'وَأَمَّا هُوَ فَاجْتَازَ قُدَّامَهُمْ وَسَجَدَ إِلَى الْأَرْضِ سَبْعَ مَرَّاتٍ حَتَّى اقْتَرَبَ إِلَى أَخِيهِ.', 'تكوين 33:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 4, 'فَرَكَضَ عِيسُو لِلِقَائِهِ وَعَانَقَهُ وَوَقَعَ عَلَى عُنُقِهِ وَقَبَّلَهُ، وَبَكَيَا.', 'تكوين 33:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 5, 'ثُمَّ رَفَعَ عَيْنَيْهِ وَأَبْصَرَ النِّسَاءَ وَالْأَوْلَادَ وَقَالَ׃ «مَا هَؤُلَاءِ مِنْكَ؟» فَقَالَ׃ «الْأَوْلَادُ الَّذِينَ أَنْعَمَ اللهُ بِهِمْ عَلَى عَبْدِكَ».', 'تكوين 33:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 6, 'فَاقْتَرَبَتِ الْجَارِيَتَانِ هُمَا وَأَوْلَادُهُمَا وَسَجَدَتَا.', 'تكوين 33:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 7, 'ثُمَّ اقْتَرَبَتْ لَيْئَةُ أَيْضًا وَأَوْلَادُهَا وَسَجَدُوا. وَبَعْدَ ذَلِكَ اقْتَرَبَ يُوسُفُ وَرَاحِيلُ وَسَجَدَا.', 'تكوين 33:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 8, 'فَقَالَ׃ «مَاذَا مِنْكَ كُلُّ هَذَا الْجَيْشِ الَّذِي صَادَفْتُهُ؟» فَقَالَ׃ «لِأَجِدَ نِعْمَةً فِي عَيْنَيْ سَيِّدِي».', 'تكوين 33:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 9, 'فَقَالَ عِيسُو׃ «لِي كَثِيرٌ، يَا أَخِي. لِيَكُنْ لَكَ الَّذِي لَكَ».', 'تكوين 33:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 10, 'فَقَالَ يَعْقُوبُ׃ «لَا. إِنْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ تَأْخُذْ هَدِيَّتِي مِنْ يَدِي، لِأَنِّي رَأَيْتُ وَجْهَكَ كَمَا يُرَى وَجْهُ اللهِ، فَرَضِيتَ عَلَيَّ.', 'تكوين 33:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 11, 'خُذْ بَرَكَتِي الَّتِي أُتِيَ بِهَا إِلَيْكَ، لِأَنَّ اللهَ قَدْ أَنْعَمَ عَلَيَّ وَلِي كُلُّ شَيْءٍ». وَأَلَحَّ عَلَيْهِ فَأَخَذَ.', 'تكوين 33:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 12, 'ثُمَّ قَالَ׃ «لِنَرْحَلْ وَنَذْهَبْ، وَأَذْهَبُ أَنَا قُدَّامَكَ».', 'تكوين 33:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 13, 'فَقَالَ لَهُ׃ «سَيِّدِي عَالِمٌ أَنَّ الْأَوْلَادَ رَخْصَةٌ، وَالْغَنَمَ وَالْبَقَرَ الَّتِي عِنْدِي مُرْضِعَةٌ، فَإِنِ اسْتَكَدُّوهَا يَوْمًا وَاحِدًا مَاتَتْ كُلُّ الْغَنَمِ.', 'تكوين 33:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 14, 'لِيَجْتَزْ سَيِّدِي قُدَّامَ عَبْدِهِ، وَأَنَا أَسْتَاقُ عَلَى مَهَلِي فِي إِثْرِ الْأَمْلَاكِ الَّتِي قُدَّامِي، وَفِي إِثْرِ الْأَوْلَادِ، حَتَّى أَجِيءَ إِلَى سَيِّدِي إِلَى سَعِيرَ».', 'تكوين 33:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 15, 'فَقَالَ عِيسُو׃ «أَتْرُكُ عِنْدَكَ مِنَ الْقَوْمِ الَّذِينَ مَعِي». فَقَالَ׃ «لِمَاذَا؟ دَعْنِي أَجِدْ نِعْمَةً فِي عَيْنَيْ سَيِّدِي».', 'تكوين 33:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 16, 'فَرَجَعَ عِيسُو ذَلِكَ الْيَوْمَ فِي طَرِيقِهِ إِلَى سَعِيرَ.', 'تكوين 33:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 17, 'وَأَمَّا يَعْقُوبُ فَارْتَحَلَ إِلَى سُكُّوتَ، وَبَنَى لِنَفْسِهِ بَيْتًا، وَصَنَعَ لِمَوَاشِيهِ مِظَالًا. لِذَلِكَ دَعَا اسْمَ الْمَكَانِ «سُكُّوتَ».', 'تكوين 33:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 18, 'ثُمَّ أَتَى يَعْقُوبُ سَالِمًا إِلَى مَدِينَةِ شَكِيمَ الَّتِي فِي أَرْضِ كَنْعَانَ، حِينَ جَاءَ مِنْ فَدَّانِ أَرَامَ. وَنَزَلَ أَمَامَ الْمَدِينَةِ.', 'تكوين 33:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 19, 'وَابْتَاعَ قِطْعَةَ الْحَقْلِ الَّتِي نَصَبَ فِيهَا خَيْمَتَهُ مِنْ يَدِ بَنِي حَمُورَ أَبِي شَكِيمَ بِمِئَةِ قَسِيطَةٍ.', 'تكوين 33:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 33, 20, 'وَأَقَامَ هُنَاكَ مَذْبَحًا وَدَعَاهُ «إِيلَ إِلَهَ إِسْرَائِيلَ».', 'تكوين 33:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 1, 'وَخَرَجَتْ دِينَةُ ابْنَةُ لَيْئَةَ الَّتِي وَلَدَتْهَا لِيَعْقُوبَ لِتَنْظُرَ بَنَاتِ الْأَرْضِ،', 'تكوين 34:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 2, 'فَرَآهَا شَكِيمُ ابْنُ حَمُورَ الْحِوِّيِّ رَئِيسِ الْأَرْضِ، وَأَخَذَهَا وَاضْطَجَعَ مَعَهَا وَأَذَلَّهَا.', 'تكوين 34:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 3, 'وَتَعَلَّقَتْ نَفْسُهُ بِدِينَةَ ابْنَةِ يَعْقُوبَ، وَأَحَبَّ الْفَتَاةَ وَلَاطَفَ الْفَتاةَ.', 'تكوين 34:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 4, 'فَكَلَّمَ شَكِيمُ حَمُورَ أَبَاهُ قَائِلًا׃ «خُذْ لِي هَذِهِ الصَّبِيَّةَ زَوْجَةً».', 'تكوين 34:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 5, 'وَسَمِعَ يَعْقُوبُ أَنَّهُ نَجَّسَ دِينَةَ ابْنَتَهُ. وَأَمَّا بَنُوهُ فَكَانُوا مَعَ مَوَاشِيهِ فِي الْحَقْلِ، فَسَكَتَ يَعْقُوبُ حَتَّى جَاءُوا.', 'تكوين 34:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 6, 'فَخَرَجَ حَمُورُ أَبُو شَكِيمَ إِلَى يَعْقُوبَ لِيَتَكَلَّمَ مَعَهُ.', 'تكوين 34:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 7, 'وَأَتَى بَنُو يَعْقُوبَ مِنَ الْحَقْلِ حِينَ سَمِعُوا. وَغَضِبَ الرِّجَالُ وَاغْتَاظُوا جِدًّا لِأَنَّهُ صَنَعَ قَبَاحَةً فِي إِسْرَائِيلَ بِمُضَاجَعَةِ ابْنَةِ يَعْقُوبَ، وَهَكَذَا لَا يُصْنَعُ.', 'تكوين 34:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 8, 'وَتَكَلَّمَ حَمُورُ مَعَهُمَ قَائِلًا׃ «شَكِيمُ ابْنِي قَدْ تَعَلَّقَتْ نَفْسُهُ بِابْنَتِكُمْ. أَعْطُوهُ إِيَّاهَا زَوْجَةً', 'تكوين 34:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 9, 'وَصَاهِرُونَا. تُعْطُونَنَا بَنَاتِكُمْ، وَتَأْخُذُونَ لَكُمْ بَنَاتِنَا.', 'تكوين 34:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 10, 'وَتَسْكُنُونَ مَعَنَا، وَتَكُونُ الْأَرْضُ قُدَّامَكُمُ. اسْكُنُوا وَاتَّجِرُوا فِيهَا وَتَمَلَّكُوا بِهَا».', 'تكوين 34:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 11, 'ثُمَّ قَالَ شَكِيمُ لِأَبِيهَا وَلإِخْوَتِهَا׃ «دَعُونِي أَجِدْ نِعْمَةً فِي أَعْيُنِكُمْ. فَالَّذِي تَقُولُونَ لِي أُعْطِي.', 'تكوين 34:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 12, 'كَثِّرُوا عَلَيَّ جِدًّا مَهْرًا وَعَطِيَّةً، فَأُعْطِيَ كَمَا تَقُولُونَ لِي. وَأَعْطُونِي الْفَتَاةَ زَوْجَةً».', 'تكوين 34:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 13, 'فَأَجَابَ بَنُو يَعْقُوبَ شَكِيمَ وَحَمُورَ أَبَاهُ بِمَكْرٍ وَتَكَلَّمُوا. لِأَنَّهُ كَانَ قَدْ نَجَّسَ دِينَةَ أُخْتَهُمْ،', 'تكوين 34:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 14, 'فَقَالُوُا لَهُمَا׃ «لَا نَسْتَطِيعُ أَنْ نَفْعَلَ هَذَا الْأَمْرَ أَنْ نُعْطِيَ أُخْتَنَا لِرَجُلٍ أَغْلَفَ، لِأَنَّهُ عَارٌ لَنَا.', 'تكوين 34:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 15, 'غَيْرَ أَنَّنَا بِهَذَا نُواتِيكُمْ׃ إِنْ صِرْتُمْ مِثْلَنَا بِخَتْنِكُمْ كُلَّ ذَكَرٍ.', 'تكوين 34:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 16, 'نُعْطِيكُمْ بَنَاتِنَا وَنَأْخُذُ لَنَا بَنَاتِكُمْ، وَنَسْكُنُ مَعَكُمْ وَنَصِيرُ شَعْبًا وَاحِدًا.', 'تكوين 34:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 17, 'وَإِنْ لَمْ تَسْمَعُوا لَنَا، أَنْ تَخْتَتِنُوا، نَأْخُذُ ابْنَتَنَا وَنَمْضِي».', 'تكوين 34:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 18, 'فَحَسُنَ كَلَامُهُمْ فِي عَيْنَيْ حَمُورَ وَفِي عَيْنَيْ شَكِيمَ بْنِ حَمُورَ.', 'تكوين 34:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 19, 'وَلَمْ يَتَأَخَّرِ الْغُلَامُ أَنْ يَفْعَلَ الْأَمْرَ، لِأَنَّهُ كَانَ مَسْرُورًا بِابْنَةِ يَعْقُوبَ. وَكَانَ أَكْرَمَ جَمِيعِ بَيْتِ أَبِيهِ.', 'تكوين 34:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 20, 'فَأَتَى حَمُورُ وَشَكِيمُ ابْنُهُ إِلَى بَابِ مَدِينَتِهْمَا، وَكَلَّمَا أَهْلَ مَدِينَتِهْمَا قَائِلَيْنِ׃', 'تكوين 34:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 21, '«هَؤُلَاءِ الْقَوْمُ مُسَالِمُونَ لَنَا. فَلْيَسْكُنُوا فِي الْأَرْضِ وَيَتَّجِرُوا فِيهَا. وَهُوَذَا الْأَرْضُ وَاسِعَةُ الطَّرَفَيْنِ أَمَامَهُمْ. نَأْخُذُ لَنَا بَنَاتِهِمْ زَوْجَاتٍ وَنُعْطِيهِمْ بَنَاتِنَا.', 'تكوين 34:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 22, 'غَيْرَ أَنَّهُ بِهَذَا فَقَطْ يُواتِينَا الْقَوْمُ عَلَى السَّكَنِ مَعَنَا لِنَصِيرَ شَعْبًا وَاحِدًا׃ بِخَتْنِنَا كُلَّ ذَكَرٍ كَمَا هُمْ مَخْتُونُونَ.', 'تكوين 34:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 23, 'أَلَا تَكُونُ مَوَاشِيهِمْ وَمُقْتَنَاهُمْ وَكُلُّ بَهَائِمِهِمْ لَنَا؟ نُواتِيهِمْ فَقَطْ فَيَسْكُنُونَ مَعَنَا».', 'تكوين 34:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 24, 'فَسَمِعَ لِحَمُورَ وَشَكِيمَ ابْنِهِ جَمِيعُ الْخَارِجِينَ مِنْ بَابِ الْمَدِينَةِ، وَاخْتَتَنَ كُلُّ ذَكَرٍ. كُلُّ الْخَارِجِينَ مِنْ بَابِ الْمَدِينَةِ.', 'تكوين 34:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 25, 'فَحَدَثَ فِي الْيَوْمِ الثَّالِثِ إِذْ كَانُوا مُتَوَجِّعِينَ أَنَّ ابْنَيْ يَعْقُوبَ، شِمْعُونَ وَلَاوِيَ أَخَوَيْ دِينَةَ، أَخَذَا كُلُّ وَاحِدٍ سَيْفَهُ وَأَتَيَا عَلَى الْمَدِينَةِ بِأَمْنٍ وَقَتَلَا كُلَّ ذَكَرٍ.', 'تكوين 34:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 26, 'وَقَتَلَا حَمُورَ وَشَكِيمَ ابْنَهُ بِحَدِّ السَّيْفِ، وَأَخَذَا دِينَةَ مِنْ بَيْتِ شَكِيمَ وَخَرَجَا.', 'تكوين 34:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 27, 'ثُمَّ أَتَى بَنُو يَعْقُوبَ عَلَى الْقَتْلَى وَنَهَبُوا الْمَدِينَةَ، لِأَنَّهُمْ نَجَّسُوا أُخْتَهُمْ.', 'تكوين 34:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 28, 'غَنَمَهُمْ وَبَقَرَهُمْ وَحَمِيرَهُمْ وَكُلُّ مَا فِي الْمَدِينَةِ وَمَا فِي الْحَقْلِ أَخَذُوهُ.', 'تكوين 34:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 29, 'وَسَبَوْا وَنَهَبُوا كُلَّ ثَرْوَتِهِمْ وَكُلَّ أَطْفَالِهِمْ، وَنِسَاءَهُمْ وَكُلَّ مَا فِي الْبُيُوتِ.', 'تكوين 34:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 30, 'فَقَالَ يَعْقُوبُ لِشَمْعُونَ وَلَاوِي׃ «كَدَّرْتُمَانِي بِتَكْرِيهِكُمَا إِيَّايَ عِنْدَ سُكَّانِ الْأَرْضِ الْكَنْعَانِيِّينَ وَالْفِرِزِيِّينَ، وَأَنَا نَفَرٌ قَلِيلٌ. فَيَجْتَمِعُونَ عَلَيَّ وَيَضْرِبُونَنِي، فَأَبِيدُ أَنَا وَبَيْتِي».', 'تكوين 34:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 34, 31, 'فَقَالَا׃ «أَنَظِيرَ زَانِيَةٍ يَفْعَلُ بِأُخْتِنَا؟».', 'تكوين 34:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 1, 'ثُمَّ قَالَ اللهُ لِيَعْقُوبَ׃ «قُمِ اصْعَدْ إِلَى بَيْتِ إِيلَ وَأَقِمْ هُنَاكَ، وَاصْنَعْ هُنَاكَ مَذْبَحًا لِلهِ الَّذِي ظَهَرَ لَكَ حِينَ هَرَبْتَ مِنْ وَجْهِ عِيسُو أَخِيكَ».', 'تكوين 35:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 2, 'فَقَالَ يَعْقُوبُ لِبَيْتِهِ وَلِكُلِّ مَنْ كَانَ مَعَهُ׃ «اعْزِلُوا الْآلِهَةَ الْغَرِيبَةَ الَّتِي بَيْنَكُمْ وَتَطَهَّرُوا وَأَبْدِلُوا ثِيَابَكُمْ.', 'تكوين 35:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 3, 'وَلْنَقُمْ وَنَصْعَدْ إِلَى بَيْتِ إِيلَ، فَأَصْنَعَ هُنَاكَ مَذْبَحًا لِلهِ الَّذِي اسْتَجَابَ لِي فِي يَوْمِ ضِيقَتِي، وَكَانَ مَعِي فِي الطَّرِيقِ الَّذِي ذَهَبْتُ فِيهِ».', 'تكوين 35:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 4, 'فَأَعْطَوْا يَعْقُوبَ كُلَّ الْآلِهَةِ الْغَرِيبَةِ الَّتِي فِي أَيْدِيهِمْ وَالْأَقْرَاطِ الَّتِي فِي آذَانِهِمْ، فَطَمَرَهَا يَعْقُوبُ تَحْتَ الْبُطْمَةِ الَّتِي عِنْدَ شَكِيمَ.', 'تكوين 35:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 5, 'ثُمَّ رَحَلُوا، وَكَانَ خَوْفُ اللهِ عَلَى الْمُدُنِ الَّتِي حَوْلَهُمْ، فَلَمْ يَسْعَوْا وَرَاءَ بَنِي يَعْقُوبَ.', 'تكوين 35:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 6, 'فَأَتَى يَعْقُوبُ إِلَى لُوزَ الَّتِي فِي أَرْضِ كَنْعَانَ، وَهِيَ بَيْتُ إِيلَ. هُوَ وَجَمِيعُ الْقَوْمِ الَّذِينَ مَعَهُ.', 'تكوين 35:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 7, 'وَبَنَى هُنَاكَ مَذْبَحًا، وَدَعَا الْمَكَانَ «إِيلَ بَيْتِ إِيلَ» لِأَنَّهُ هُنَاكَ ظَهَرَ لَهُ اللهُ حِينَ هَرَبَ مِنْ وَجْهِ أَخِيهِ.', 'تكوين 35:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 8, 'وَمَاتَتْ دَبُورَةُ مُرْضِعَةُ رِفْقَةَ وَدُفِنَتْ تَحْتَ بَيْتَ إِيلَ تَحْتَ الْبَلُّوطَةِ، فَدَعَا اسْمَهَا «أَلُّونَ بَاكُوتَ».', 'تكوين 35:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 9, 'وَظَهَرَ اللهُ لِيَعْقُوبَ أَيْضًا حِينَ جَاءَ مِنْ فَدَّانِ أَرَامَ وَبَارَكَهُ.', 'تكوين 35:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 10, 'وَقَالَ لَهُ اللهُ׃ «اسْمُكَ يَعْقُوبُ. لَا يُدْعَى اسْمُكَ فِيمَا بَعْدُ يَعْقُوبَ، بَلْ يَكُونُ اسْمُكَ إِسْرَائِيلَ». فَدَعَا اسْمَهُ «إِسْرَائِيلَ».', 'تكوين 35:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 11, 'وَقَالَ لَهُ اللهُ׃ «أَنَا اللهُ الْقَدِيرُ. أَثْمِرْ وَاكْثُرْ. أُمَّةٌ وَجَمَاعَةُ أُمَمٍ تَكُونُ مِنْكَ، وَمُلُوكٌ سَيَخْرُجُونَ مِنْ صُلْبِكَ.', 'تكوين 35:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 12, 'وَالْأَرْضُ الَّتِي أَعْطَيْتُ إِبْرَاهِيمَ وَإِسْحَاقَ، لَكَ أُعْطِيهَا، وَلِنَسْلِكَ مِنْ بَعْدِكَ أُعْطِي الْأَرْضَ».', 'تكوين 35:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 13, 'ثُمَّ صَعِدَ اللهُ عَنْهُ فِي الْمَكَانِ الَّذِي فِيهِ تَكَلَّمَ مَعَهُ.', 'تكوين 35:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 14, 'فَنَصَبَ يَعْقُوبُ عَمُودًا فِي الْمَكَانِ الَّذِي فِيهِ تَكَلَّمَ مَعَهُ، عَمُودًا مِنْ حَجَرٍ، وَسَكَبَ عَلَيْهِ سَكِيبًا، وَصَبَّ عَلَيْهِ زَيْتًا.', 'تكوين 35:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 15, 'وَدَعَا يَعْقُوبُ اسْمَ الْمَكَانِ الَّذِي فِيهِ تَكَلَّمَ اللهُ مَعَهُ «بَيْتَ إِيلَ».', 'تكوين 35:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 16, 'ثُمَّ رَحَلُوا مِنْ بَيْتِ إِيلَ. وَلَمَّا كَانَ مَسَافَةٌ مِنَ الْأَرْضِ بَعْدُ حَتَّى يَأْتُوا إِلَى أَفْرَاتَةَ، وَلَدَتْ رَاحِيلُ وَتَعَسَّرَتْ وِلَادَتُهَا.', 'تكوين 35:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 17, 'وَحَدَثَ حِينَ تَعسَّرَتْ وِلَادَتُهِا أَنَّ الْقَابِلَةَ قَالَتِ لَهَا׃ «لَا تَخَافِي، لِأَنَّ هَذَا أَيْضًا ابْنٌ لَكِ».', 'تكوين 35:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 18, 'وَكَانَ عِنْدَ خُرُوجِ نَفْسِهَا، لِأَنَّهَا مَاتَتْ، أَنَّهَا دَعَتِ اسْمَهُ «بَنْ أُونِي». وَأَمَّا أَبُوهُ فَدَعَاهُ «بَنْيَامِينَ».', 'تكوين 35:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 19, 'فَمَاتَتْ رَاحِيلُ وَدُفِنَتْ فِي طَرِيقِ أَفْرَاتَةَ، الَّتِي هِيَ بَيْتُ لَحْمٍ.', 'تكوين 35:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 20, 'فَنَصَبَ يَعْقُوبُ عَمُودًا عَلَى قَبْرِهَا، وَهُوَ «عَمُودُ قَبْرِ رَاحِيلَ» إِلَى الْيَوْمِ.', 'تكوين 35:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 21, 'ثُمَّ رَحَلَ إِسْرَائِيلُ وَنَصَبَ خَيْمَتَهُ وَرَاءَ مَجْدَلَ عِدْرٍ.', 'تكوين 35:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 22, 'وَحَدَثَ إِذْ كَانَ إِسْرَائِيلُ سَاكِنًا فِي تِلْكَ الْأَرْضِ، أَنَّ رَأُوبَيْنَ ذَهَبَ وَاضْطَجَعَ مَعَ بِلْهَةَ سُرِّيَّةِ أَبِيهِ، وَسَمِعَ إِسْرَائِيلُ. وَكَانَ بَنُو يَعْقُوبَ اثْنَيْ عَشَرَ׃', 'تكوين 35:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 23, 'بَنُو لَيْئَةَ׃ رَأُوبَيْنُ بِكْرُ يَعْقُوبَ، وَشِمْعُونُ وَلَاوِي وَيَهُوذَا وَيَسَّاكَرُ وَزَبُولُونُ.', 'تكوين 35:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 24, 'وَابْنَا رَاحِيلَ׃ يُوسُفُ وَبَنْيَامِينُ.', 'تكوين 35:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 25, 'وَابْنَا بِلْهَةَ جَارِيَةِ رَاحِيلَ׃ دَانُ وَنَفْتَالِي.', 'تكوين 35:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 26, 'وَابْنَا زِلْفَةَ جَارِيَةِ لَيْئَةَ׃ جَادُ وَأَشِيرُ. هَؤُلَاءِ بَنُو يَعْقُوبَ الَّذِينَ وُلِدُوا لَهُ فِي فَدَّانِ أَرَامَ.', 'تكوين 35:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 27, 'وَجَاءَ يَعْقُوبُ إِلَى إِسْحَاقَ أَبِيهِ إِلَى مَمْرَا، قِرْيَةِ أَرْبَعَ، الَّتِي هِيَ حَبْرُونُ، حَيْثُ تَغَرَّبَ إِبْرَاهِيمُ وَإِسْحَاقُ.', 'تكوين 35:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 28, 'وَكَانَتْ أَيَّامُ إِسْحَاقَ مِئَةً وَثَمَانِينَ سَنَةً.', 'تكوين 35:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 35, 29, 'فَأَسْلَمَ إِسْحَاقُ رُوحَهُ وَمَاتَ وَانْضَمَّ إِلَى قَوْمِهِ، شَيْخًا وَشَبْعَانَ أَيَّامًا. وَدَفَنَهُ عِيسُو وَيَعْقُوبُ ابْنَاهُ.', 'تكوين 35:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 1, 'وَهَذِهِ مَوَالِيدُ عِيسُوَ، الَّذِي هُوَ أَدُومُ.', 'تكوين 36:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 2, 'أَخَذَ عِيسُو نِسَاءَهُ مِنْ بَنَاتِ كَنْعَانَ׃ عَدَا بِنْتَ إِيلُونَ الْحِثِّيِّ، وَأُهُولِيبَامَةَ بِنْتَ عَنَى بِنْتِ صِبْعُونَ الْحِوِّيِّ،', 'تكوين 36:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 3, 'وَبَسْمَةَ بِنْتَ إِسْمَاعِيلَ أُخْتَ نَبَايُوتَ.', 'تكوين 36:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 4, 'فَوَلَدَتْ عَدَا لِعِيسُو أَلِيفَازَ، وَوَلَدَتْ بَسْمَةُ رَعُوئِيلَ،', 'تكوين 36:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 5, 'وَوَلَدَتْ أُهُولِيبَامَةُ׃ يَعُوشَ وَيَعْلَامَ وَقُورَحَ. هَؤُلَاءِ بَنُو عِيسُو الَّذِينَ وُلِدُوا لَهُ فِي أَرْضِ كَنْعَانَ.', 'تكوين 36:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 6, 'ثُمَّ أَخَذَ عِيسُو نِسَاءَهُ وَبَنِيهِ وَبَنَاتِهِ وَجَمِيعَ نُفُوسِ بَيْتِهِ وَمَوَاشِيَهُ وَكُلَّ بَهَائِمِهِ وَكُلَّ مُقْتَنَاهُ الَّذِي اقْتَنَى فِي أَرْضِ كَنْعَانَ، وَمَضَى إِلَى أَرْضٍ أُخْرَى مِنْ وَجْهِ يَعْقُوبَ أَخِيهِ،', 'تكوين 36:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 7, 'لِأَنَّ أَمْلَاكَهُمَا كَانَتْ كَثِيرَةً عَلَى السُّكْنَى مَعًا، وَلَمْ تَسْتَطِعْ أَرْضُ غُرْبَتِهِمَا أَنْ تَحْمِلَهُمَا مِنْ أَجْلِ مَوَاشِيهِمَا.', 'تكوين 36:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 8, 'فَسَكَنَ عِيسُو فِي جَبَلِ سَعِيرَ. وَعِيسُو هُوَ أَدُومُ.', 'تكوين 36:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 9, 'وَهَذِهِ مَوَالِيدُ عِيسُو أَبِي أَدُومَ فِي جَبَلِ سَعِيرَ.', 'تكوين 36:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 10, 'هَذِهِ أَسْمَاءُ بَنِي عِيسُو׃ أَلِيفَازُ ابْنُ عَدَا امْرَأَةِ عِيسُو، وَرَعُوئِيلُ ابْنُ بَسْمَةَ امْرَأَةِ عِيسُو.', 'تكوين 36:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 11, 'وَكَانَ بَنُو أَلِيفَازَ׃ تَيْمَانَ وَأَوْمَارَ وَصَفْوًا وَجَعْثَامَ وَقَنَازَ.', 'تكوين 36:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 12, 'وَكَانَتْ تِمْنَاعُ سُرِّيَّةً لِأَلِيفَازَ بْنِ عِيسُو، فَوَلَدَتْ لِأَلِيفَازَ عَمَالِيقَ. هَؤُلَاءِ بَنُو عَدَا امْرَأَةِ عِيسُو.', 'تكوين 36:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 13, 'وَهَؤُلَاءِ بَنُو رَعُوئِيلَ׃ نَحَثُ وَزَارَحُ وَشَمَّةُ وَمِزَّةُ. هَؤُلَاءِ كَانُوا بَنِي بَسْمَةَ امْرَأَةِ عِيسُو.', 'تكوين 36:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 14, 'وَهَؤُلَاءِ كَانُوا بَنِي أُهُولِيبَامَةَ بِنْتِ عَنَى بِنْتِ صِبْعُونَ امْرَأَةِ عِيسُو، وَلَدَتْ لِعِيسُو׃ يَعُوشَ وَيَعْلَامَ وَقُورَحَ.', 'تكوين 36:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 15, 'هَؤُلَاءِ أُمَرَاءُ بَنِي عِيسُو׃ بَنُو أَلِيفَازَ بِكْرِ عِيسُو׃ أَمِيرُ تَيْمَانَ وَأَمِيرُ أُومَارَ وَأَمِيرُ صَفْوٍ وَأَمِيرُ قَنَازَ', 'تكوين 36:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 16, 'وَأَمِيرُ قُورَحَ وَأَمِيرُ جَعْثَامَ وَأَمِيرُ عَمَالِيقَ. هَؤُلَاءِ أُمَرَاءُ أَلِيفَازَ فِي أَرْضِ أَدُومَ. هَؤُلَاءِ بَنُو عَدَا.', 'تكوين 36:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 17, 'وَهَؤُلَاءِ بَنُو رَعُوئِيلَ بْنِ عِيسُو׃ أَمِيرُ نَحَثَ وَأَمِيرُ زَارَحَ وَأَمِيرُ شَمَّةَ وَأَمِيرُ مِزَّةَ. هَؤُلَاءِ أُمَرَاءُ رَعُوئِيلَ فِي أَرْضِ أَدُومَ. هَؤُلَاءِ بَنُو بَسْمَةَ امْرَأَةِ عِيسُو.', 'تكوين 36:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 18, 'وَهَؤُلَاءِ بَنُو أُهُولِيبَامَةَ امْرَأَةِ عِيسُو׃ أَمِيرُ يَعُوشَ وَأَمِيرُ يَعْلَامَ وَأَمِيرُ قُورَحَ. هَؤُلَاءِ أُمَرَاءُ أُهُولِيبَامَةَ بِنْتِ عَنَى امْرَأَةِ عِيسُو.', 'تكوين 36:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 19, 'هَؤُلَاءِ بَنُو عِيسُو الَّذِي هُوَ أَدُومُ، وَهَؤُلَاءِ أُمَرَاؤُهُمْ.', 'تكوين 36:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 20, 'هَؤُلَاءِ بَنُو سَعِيرَ الْحُورِيِّ سُكَّانُ الْأَرْضِ׃ لُوطَانُ وَشُوبَالُ وَصِبْعُونُ وَعَنَى', 'تكوين 36:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 21, 'وَدِيشُونُ وَإِيصَرُ وَدِيشَانُ. هَؤُلَاءِ أُمَرَاءُ الْحُورِيِّينَ بَنُو سَعِيرَ فِي أَرْضِ أَدُومَ.', 'تكوين 36:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 22, 'وَكَانَ ابْنَا لُوطَانَ׃ حُورِيَ وَهَيْمَامَ. وَكَانَتْ تِمْنَاعُ أُخْتَ لُوطَانَ.', 'تكوين 36:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 23, 'وَهَؤُلَاءِ بَنُو شُوبَالَ׃ عَلْوَانُ وَمَنَاحَةُ وَعَيْبَالُ وَشَفْوٌ وَأُونَامُ.', 'تكوين 36:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 24, 'وَهَذَانِ ابْنَا صِبْعُونَ׃ أَيَّةُ وَعَنَى. هَذَا هُوَ عَنَى الَّذِي وَجَدَ الْحَمَائِمَ فِي الْبَرِّيَّةِ إِذْ كَانَ يَرْعَى حَمِيرَ صِبْعُونَ أَبِيهِ.', 'تكوين 36:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 25, 'وَهَذَا ابْنُ عَنَى׃ دِيشُونُ. وَأُهُولِيبَامَةُ هِيَ بِنْتُ عَنَى.', 'تكوين 36:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 26, 'وَهَؤُلَاءِ بَنُو دِيشَانَ׃ حَمْدَانُ وَأَشْبَانُ وَيِثْرَانُ وَكَرَانُ.', 'تكوين 36:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 27, 'هَؤُلَاءِ بَنُو إِيصَرَ׃ بِلْهَانُ وَزَعْوَانُ وَعَقَانُ.', 'تكوين 36:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 28, 'هَذَانِ ابْنَا دِيشَانَ׃ عُوصٌ وَأَرَانُ.', 'تكوين 36:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 29, 'هَؤُلَاءِ أُمَرَاءُ الْحُورِيِّينَ׃ أَمِيرُ لُوطَانَ وَأَمِيرُ شُوبَالَ وَأَمِيرُ صِبْعُونَ وَأَمِيرُ عَنَى', 'تكوين 36:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 30, 'وَأَمِيرُ دِيشُونَ وَأَمِيرُ إِيصَرَ وَأَمِيرُ دِيشَانَ. هَؤُلَاءِ أُمَرَاءُ الْحُورِيِّينَ بِأُمَرَائِهِمْ فِي أَرْضِ سَعِيرَ.', 'تكوين 36:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 31, 'وَهَؤُلَاءِ هُمُ الْمُلُوكُ الَّذِينَ مَلَكُوا فِي أَرْضِ أَدُومَ، قَبْلَمَا مَلَكَ مَلِكٌ لِبَنِي إِسْرَائِيلَ.', 'تكوين 36:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 32, 'مَلَكَ فِي أَدُومَ بَالَعُ بْنُ بَعُورَ، وَكَانَ اسْمُ مَدِينَتِهِ دِنْهَابَةَ.', 'تكوين 36:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 33, 'وَمَاتَ بَالَعُ، فَمَلَكَ مَكَانَهُ يُوبَابُ بْنُ زَارَحَ مِنْ بُصْرَةَ.', 'تكوين 36:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 34, 'وَمَاتَ يُوبَابُ، فَمَلَكَ مَكَانَهُ حُوشَامُ مِنْ أَرْضِ التَّيْمَانِيِّ.', 'تكوين 36:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 35, 'وَمَاتَ حُوشَامُ، فَمَلَكَ مَكَانَهُ هَدَادُ بْنُ بَدَادَ الَّذِي كَسَّرَ مِدْيَانَ فِي بِلَادِ مُوآبَ، وَكَانَ اسْمُ مَدِينَتِهِ عَوِيتَ.', 'تكوين 36:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 36, 'وَمَاتَ هَدَادُ، فَمَلَكَ مَكَانَهُ سَمْلَةُ مِنْ مَسْرِيقَةَ.', 'تكوين 36:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 37, 'وَمَاتَ سَمْلَةُ، فَمَلَكَ مَكَانَهُ شَأُولُ مِنْ رَحُوبُوتِ النَّهْرِ.', 'تكوين 36:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 38, 'وَمَاتَ شَأُولُ، فَمَلَكَ مَكَانَهُ بَعْلُ حَانَانَ بْنُ عَكْبُورَ.', 'تكوين 36:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 39, 'وَمَاتَ بَعْلُ حَانَانَ بْنُ عَكْبُورَ، فَمَلَكَ مَكَانَهُ هَدَارُ وَكَانَ اسْمُ مَدِينَتِهِ فَاعُوَ، وَاسْمُ امْرَأَتِهِ مَهِيطَبْئِيلُ بِنْتُ مَطْرِدَ بِنْتِ مَاءِ ذَهَبٍ.', 'تكوين 36:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 40, 'وَهَذِهِ أَسْمَاءُ أُمَرَاءِ عِيسُو، حَسَبَ قَبَائِلِهِمْ وَأَمَاكِنِهِمْ بِأَسْمَائِهِمْ׃ أَمِيرُ تِمْنَاعَ وَأَمِيرُ عَلْوَةَ وَأَمِيرُ يَتِيتَ', 'تكوين 36:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 41, 'وَأَمِيرُ أُهُولِيبَامَةَ وَأَمِيرُ إِيلَةَ وَأَمِيرُ فِينُونَ', 'تكوين 36:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 42, 'وَأَمِيرُ قَنَازَ وَأَمِيرُ تَيْمَانَ وَأَمِيرُ مِبْصَارَ', 'تكوين 36:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 36, 43, 'وَأَمِيرُ مَجْدِيئِيلَ وَأَمِيرُ عِيرَامَ. هَؤُلَاءِ أُمَرَاءُ أَدُومَ حَسَبَ مَسَاكِنِهِمْ فِي أَرْضِ مُلْكِهِمْ. هَذَا هُوَ عِيسُو أَبُو أَدُومَ.', 'تكوين 36:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 1, 'وَسَكَنَ يَعْقُوبُ فِي أَرْضِ غُرْبَةِ أَبِيهِ، فِي أَرْضِ كَنْعَانَ.', 'تكوين 37:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 2, 'هَذِهِ مَوَالِيدُ يَعْقُوبَ׃ يُوسُفُ إِذْ كَانَ ابْنَ سَبْعَ عَشَرَةَ سَنَةً، كَانَ يَرْعَى مَعَ إِخْوَتِهِ الْغَنَمَ وَهُوَ غُلَامٌ عِنْدَ بَنِي بِلْهَةَ وَبَنِي زِلْفَةَ امْرَأَتَيْ أَبِيهِ، وَأَتَى يُوسُفُ بِنَمِيمَتِهِمِ الرَّدِيئَةِ إِلَى أَبِيهِمْ.', 'تكوين 37:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 3, 'وَأَمَّا إِسْرَائِيلُ فَأَحَبَّ يُوسُفَ أَكْثَرَ مِنْ سَائِرِ بَنِيهِ لِأَنَّهُ ابْنُ شَيْخُوخَتِهِ، فَصَنَعَ لَهُ قَمِيصًا مُلَوَّنًا.', 'تكوين 37:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 4, 'فَلَمَّا رَأَى إِخْوَتُهُ أَنَّ أَبَاهُمْ أَحَبَّهُ أَكْثَرَ مِنْ جَمِيعِ إِخْوَتِهِ أَبْغَضُوهُ، وَلَمْ يَسْتَطِيعُوا أَنْ يُكَلِّمُوهُ بِسَلَامٍ.', 'تكوين 37:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 5, 'وَحَلُمَ يُوسُفُ حُلْمًا وَأَخْبَرَ إِخْوَتَهُ، فَازْدَادُوا أَيْضًا بُغْضًا لَهُ.', 'تكوين 37:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 6, 'فَقَالَ لَهُمُ׃ «اسْمَعُوا هَذَا الْحُلْمَ الَّذِي حَلُمْتُ׃', 'تكوين 37:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 7, 'فَهَا نَحْنُ حَازِمُونَ حُزَمًا فِي الْحَقْلِ، وَإِذَا حُزْمَتِي قَامَتْ وَانْتَصَبَتْ، فَاحْتَاطَتْ حُزَمُكُمْ وَسَجَدَتْ لِحُزْمَتِي».', 'تكوين 37:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 8, 'فَقَالَ لَهُ إِخْوَتُهُ׃ «أَلَعَلَّكَ تَمْلِكُ عَلَيْنَا مُلْكًا أَمْ تَتَسَلَّطُ عَلَيْنَا تَسَلُّطًا؟» وَازْدَادُوا أَيْضًا بُغْضًا لَهُ مِنْ أَجْلِ أَحْلَامِهِ وَمِنْ أَجْلِ كَلَامِهِ.', 'تكوين 37:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 9, 'ثُمَّ حَلُمَ أَيْضًا حُلْمًا آخَرَ وَقَصَّهُ عَلَى إِخْوَتِهِ، فَقَالَ׃ «إِنِّي قَدْ حَلُمْتُ حُلْمًا أَيْضًا، وَإِذَا الشَّمْسُ وَالْقَمَرُ وَأَحَدَ عَشَرَ كَوْكَبًا سَاجِدَةٌ لِي».', 'تكوين 37:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 10, 'وَقَصَّهُ عَلَى أَبِيهِ وَعَلَى إِخْوَتِهِ، فَانْتَهَرَهُ أَبُوهُ وَقَالَ لَهُ׃ «مَا هَذَا الْحُلْمُ الَّذِي حَلُمْتَ؟ هَلْ نَأْتِي أَنَا وَأُمُّكَ وَإِخْوَتُكَ لِنَسْجُدَ لَكَ إِلَى الْأَرْضِ؟»', 'تكوين 37:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 11, 'فَحَسَدَهُ إِخْوَتُهُ، وَأَمَّا أَبُوهُ فَحَفِظَ الْأَمْرَ.', 'تكوين 37:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 12, 'وَمَضَى إِخْوَتُهُ لِيَرْعَوْا غَنَمَ أَبِيهِمْ عِنْدَ شَكِيمَ.', 'تكوين 37:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 13, 'فَقَالَ إِسْرَائِيلُ لِيُوسُفَ׃ «أَلَيْسَ إِخْوَتُكَ يَرْعَوْنَ عِنْدَ شَكِيمَ؟ تَعَالَ فَأُرْسِلَكَ إِلَيْهِمْ». فَقَالَ لَهُ׃ «هَأَنَذَا».', 'تكوين 37:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 14, 'فَقَالَ لَهُ׃ «اذْهَبِ انْظُرْ سَلَامَةَ إِخْوَتِكَ وَسَلَامَةَ الْغَنَمِ وَرُدَّ لِي خَبَرًا». فَأَرْسَلَهُ مِنْ وَطَاءِ حَبْرُونَ فَأَتَى إِلَى شَكِيمَ.', 'تكوين 37:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 15, 'فَوَجَدَهُ رَجُلٌ وَإِذَا هُوَ ضَالٌّ فِي الْحَقْلِ. فَسَأَلَهُ الرَّجُلُ قَائِلًا׃ «مَاذَا تَطْلُبُ؟»', 'تكوين 37:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 16, 'فَقَالَ׃ «أَنَا طَالِبٌ إِخْوَتِي. أَخْبِرْنِي «أَيْنَ يَرْعَوْنَ؟».', 'تكوين 37:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 17, 'فَقَالَ الرَّجُلُ׃ «قَدِ ارْتَحَلُوا مِنْ هُنَا، لِأَنِّي سَمِعْتُهُمْ يَقُولُونَ׃ لِنَذْهَبْ إِلَى دُوثَانَ». فَذَهَبَ يُوسُفُ وَرَاءَ إِخْوَتِهِ فَوَجَدَهُمْ فِي دُوثَانَ.', 'تكوين 37:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 18, 'فَلَمَّا أَبْصَرُوهُ مِنْ بَعِيدٍ، قَبْلَمَا اقْتَرَبَ إِلَيْهِمِ، احْتَالُوا لَهُ لِيُمِيتُوهُ.', 'تكوين 37:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 19, 'فَقَالَ بَعْضُهُمْ لِبَعْضٍ׃ «هُوَذَا هَذَا صَاحِبُ الْأَحْلَامِ قَادِمٌ.', 'تكوين 37:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 20, 'فَالْآنَ هَلُمَّ نَقْتُلْهُ وَنَطْرَحْهُ فِي إِحْدَى الْآبَارِ وَنَقُولُ׃ وَحْشٌ رَدِيءٌ أَكَلَهُ. فَنَرَى مَاذَا تَكُونُ أَحْلَامُهُ».', 'تكوين 37:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 21, 'فَسَمِعَ رَأُوبَيْنُ وَأَنْقَذَهُ مِنْ أَيْدِيهِمْ، وَقَالَ׃ «لَا نَقْتُلُهُ».', 'تكوين 37:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 22, 'وَقَالَ لَهُمْ رَأُوبَيْنُ׃ «لَا تَسْفِكُوا دَمًا. اِطْرَحُوهُ فِي هَذِهِ الْبِئْرِ الَّتِي فِي الْبَرِّيَّةِ وَلَا تَمُدُّوا إِلَيْهِ يَدًا». لِكَيْ يُنْقِذَهُ مِنْ أَيْدِيهِمْ لِيَرُدَّهُ إِلَى أَبِيهِ.', 'تكوين 37:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 23, 'فَكَانَ لَمَّا جَاءَ يُوسُفُ إِلَى إِخْوَتِهِ أَنَّهُمْ خَلَعُوا عَنْ يُوسُفَ قَمِيصَهُ، الْقَمِيصَ الْمُلَوَّنَ الَّذِي عَلَيْهِ،', 'تكوين 37:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 24, 'وَأَخَذُوهُ وَطَرَحُوهُ فِي الْبِئْرِ. وَأَمَّا الْبِئْرُ فَكَانَتْ فَارِغَةً لَيْسَ فِيهَا مَاءٌ.', 'تكوين 37:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 25, 'ثُمَّ جَلَسُوا لِيَأْكُلُوا طَعَامًا. فَرَفَعُوا عُيُونَهُمْ وَنَظَرُوا وَإِذَا قَافِلَةُ إِسْمَاعِيلِيِّينَ مُقْبِلَةٌ مِنْ جِلْعَادَ، وَجِمَالُهُمْ حَامِلَةٌ كَثِيرَاءَ وَبَلَسَانًا وَلَاذَنًا، ذَاهِبِينَ لِيَنْزِلُوا بِهَا إِلَى مِصْرَ.', 'تكوين 37:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 26, 'فَقَالَ يَهُوذَا لِإِخْوَتِهِ׃ «مَا الْفَائِدَةُ أَنْ نَقْتُلَ أَخَانَا وَنُخْفِيَ دَمَهُ؟', 'تكوين 37:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 27, 'تَعَالَوْا فَنَبِيعَهُ لِلْإِسْمَاعِيلِيِّينَ، وَلَا تَكُنْ أَيْدِينَا عَلَيْهِ لِأَنَّهُ أَخُونَا وَلَحْمُنَا». فَسَمِعَ لَهُ إِخْوَتُهُ.', 'تكوين 37:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 28, 'وَاجْتَازَ رِجَالٌ مِدْيَانِيُّونَ تُجَّارٌ، فَسَحَبُوا يُوسُفَ وَأَصْعَدُوهُ مِنَ الْبِئْرِ، وَبَاعُوا يُوسُفَ لِلْإِسْمَاعِيلِيِّينَ بِعِشْرِينَ مِنَ الْفِضَّةِ. فَأَتَوْا بِيُوسُفَ إِلَى مِصْرَ.', 'تكوين 37:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 29, 'وَرَجَعَ رَأُوبَيْنُ إِلَى الْبِئْرِ، وَإِذَا يُوسُفُ لَيْسَ فِي الْبِئْرِ، فَمَزَّقَ ثِيَابَهُ.', 'تكوين 37:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 30, 'ثُمَّ رَجَعَ إِلَى إِخْوَتِهِ وَقَالَ׃ «الْوَلَدُ لَيْسَ مَوْجُودًا، وَأَنَا إِلَى أَيْنَ أَذْهَبُ؟».', 'تكوين 37:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 31, 'فَأَخَذُوا قَمِيصَ يُوسُفَ وَذَبَحُوا تَيْسًا مِنَ الْمِعْزَى وَغَمَسُوا الْقَمِيصَ فِي الدَّمِ.', 'تكوين 37:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 32, 'وَأَرْسَلُوا الْقَمِيصَ الْمُلَوَّنَ وَأَحْضَرُوهُ إِلَى أَبِيهِمْ وَقَالُوا׃ «وَجَدْنَا هَذَا. حَقِّقْ أَقَمِيصُ ابْنِكَ هُوَ أَمْ لَا؟».', 'تكوين 37:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 33, 'فَتَحَقَّقَهُ وَقَالَ׃ «قَمِيصُ ابْنِي! وَحْشٌ رَدِيءٌ أَكَلَهُ، افْتُرِسَ يُوسُفُ افْتِرَاسًا».', 'تكوين 37:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 34, 'فَمَزَّقَ يَعْقُوبُ ثِيَابَهُ، وَوَضَعَ مِسْحًا عَلَى حَقَوَيْهِ، وَنَاحَ عَلَى ابْنِهِ أَيَّامًا كَثِيرَةً.', 'تكوين 37:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 35, 'فَقَامَ جَمِيعُ بَنِيهِ وَجَمِيعُ بَنَاتِهِ لِيُعَزُّوهُ، فَأَبَى أَنْ يَتَعَزَّى وَقَالَ׃ «إِنِّي أَنْزِلُ إِلَى ابْنِي نَائِحًا إِلَى الْهَاوِيَةِ». وَبَكَى عَلَيْهِ أَبُوهُ.', 'تكوين 37:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 37, 36, 'وَأَمَّا الْمِدْيَانِيُّونَ فَبَاعُوهُ فِي مِصْرَ لِفُوطِيفَارَ خَصِيِّ فِرْعَوْنَ، رَئِيسِ الشُّرَطِ.', 'تكوين 37:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 1, 'وَحَدَثَ فِي ذَلِكَ الزَّمَانِ أَنَّ يَهُوذَا نَزَلَ مِنْ عِنْدِ إِخْوَتِهِ، وَمَالَ إِلَى رَجُلٍ عَدُّلَامِيٍّ اسْمُهُ حِيرَةُ.', 'تكوين 38:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 2, 'وَنَظَرَ يَهُوذَا هُنَاكَ ابْنَةَ رَجُلٍ كَنْعَانِيٍّ اسْمُهُ شُوعٌ، فَأَخَذَهَا وَدَخَلَ عَلَيْهَا،', 'تكوين 38:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 3, 'فَحَبِلَتْ وَوَلَدَتِ ابْنًا وَدَعَا اسْمَهُ «عِيرًا».', 'تكوين 38:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 4, 'ثُمَّ حَبِلَتْ أَيْضًا وَوَلَدَتِ ابْنًا وَدَعَتِ اسْمَهُ «أُونَانَ».', 'تكوين 38:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 5, 'ثُمَّ عَادَتْ فَوَلَدَتْ أَيْضًا ابْنًا وَدَعَتِ اسْمَهُ «شِيلَةَ». وَكَانَ فِي كَزِيبَ حِينَ وَلَدَتْهُ.', 'تكوين 38:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 6, 'وَأَخَذَ يَهُوذَا زَوْجَةً لِعِيرٍ بِكْرِهِ اسْمُهَا ثَامَارُ.', 'تكوين 38:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 7, 'وَكَانَ عِيرٌ بِكْرُ يَهُوذَا شِرِّيرًا فِي عَيْنَيِ الرَّبِّ، فَأَمَاتَهُ الرَّبُّ.', 'تكوين 38:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 8, 'فَقَالَ يَهُوذَا لِأُونَانَ׃ «ادْخُلْ عَلَى امْرَأَةِ أَخِيكَ وَتَزَوَّجْ بِهَا، وَأَقِمْ نَسْلًا لِأَخِيكَ».', 'تكوين 38:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 9, 'فَعَلِمَ أُونَانُ أَنَّ النَّسْلَ لَا يَكُونُ لَهُ، فَكَانَ إِذْ دَخَلَ عَلَى امْرَأَةِ أَخِيهِ أَنَّهُ أَفْسَدَ عَلَى الْأَرْضِ، لِكَيْ لَا يُعْطِيَ نَسْلًا لِأَخِيهِ.', 'تكوين 38:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 10, 'فَقَبُحَ فِي عَيْنَيِ الرَّبِّ مَا فَعَلَهُ، فَأَمَاتَهُ أَيْضًا.', 'تكوين 38:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 11, 'فَقَالَ يَهُوذَا لِثَامَارَ كَنَّتِهِ׃ «اقْعُدِي أَرْمَلَةً فِي بَيْتِ أَبِيكِ حَتَّى يَكْبُرَ شِيلَةُ ابْنِي». لِأَنَّهُ قَالَ׃ «لَعَلَّهُ يَمُوتُ هُوَ أَيْضًا كَأَخَوَيْهِ». فَمَضَتْ ثَامَارُ وَقَعَدَتْ فِي بَيْتِ أَبِيهَا.', 'تكوين 38:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 12, 'وَلَمَّا طَالَ الزَّمَانُ مَاتَتِ ابْنَةُ شُوعٍ امْرَأَةُ يَهُوذَا. ثُمَّ تَعَزَّى يَهُوذَا فَصَعِدَ إِلَى جُزَّازِ غَنَمِهِ إِلَى تِمْنَةَ، هُوَ وَحِيرَةُ صَاحِبُهُ الْعَدُّلَامِيُّ.', 'تكوين 38:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 13, 'فَأُخْبِرَتْ ثَامَارُ وَقِيلَ لَهَا׃ «هُوَذَا حَمُوكِ صَاعِدٌ إِلَى تِمْنَةَ لِيَجُزَّ غَنَمَهُ».', 'تكوين 38:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 14, 'فَخَلَعَتْ عَنْهَا ثِيَابَ تَرَمُّلِهَا، وَتَغَطَّتْ بِبُرْقُعٍ وَتَلَفَّفَتْ، وَجَلَسَتْ فِي مَدْخَلِ عَيْنَايِمَ الَّتِي عَلَى طَرِيقِ تِمْنَةَ، لِأَنَّهَا رَأَتْ أَنَّ شِيلَةَ قَدْ كَبُرَ وَهِيَ لَمْ تُعْطَ لَهُ زَوْجَةً.', 'تكوين 38:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 15, 'فَنَظَرَهَا يَهُوذَا وَحَسِبَهَا زَانِيَةً، لِأَنَّهَا كَانَتْ قَدْ غَطَّتْ وَجْهَهَا.', 'تكوين 38:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 16, 'فَمَالَ إِلَيْهَا عَلَى الطَّرِيقِ وَقَالَ׃ «هَاتِي أَدْخُلْ عَلَيْكِ». لِأَنَّهُ لَمْ يَعْلَمْ أَنَّهَا كَنَّتُهُ. فَقَالَتْ׃ «مَاذَا تُعْطِينِي لِكَيْ تَدْخُلَ عَلَيَّ؟»', 'تكوين 38:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 17, 'فَقَالَ׃ «إِنِّي أُرْسِلُ جَدْيَ مِعْزَى مِنَ الْغَنَمِ». فَقَالَتْ׃ «هَلْ تُعْطِينِي رَهْنًا حَتَّى تُرْسِلَهُ؟».', 'تكوين 38:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 18, 'فَقَالَ׃ «مَا الرَّهْنُ الَّذِي أُعْطِيكِ؟» فَقَالَتْ׃ «خَاتِمُكَ وَعِصَابَتُكَ وَعَصَاكَ الَّتِي فِي يَدِكَ». فَأَعْطَاهَا وَدَخَلَ عَلَيْهَا، فَحَبِلَتْ مِنْهُ.', 'تكوين 38:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 19, 'ثُمَّ قَامَتْ وَمَضَتْ وَخَلَعَتْ عَنْهَا بُرْقُعَهَا وَلَبِسَتْ ثِيَابَ تَرَمُّلِهَا.', 'تكوين 38:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 20, 'فَأَرْسَلَ يَهُوذَا جَدْيَ الْمِعْزَى بِيَدِ صَاحِبِهِ الْعَدُّلَامِيِّ لِيَأْخُذَ الرَّهْنَ مِنْ يَدِ الْمَرْأَةِ، فَلَمْ يَجِدْهَا.', 'تكوين 38:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 21, 'فَسَأَلَ أَهْلَ مَكَانِهَا قَائِلًا׃ «أَيْنَ الزَّانِيَةُ الَّتِي كَانَتْ فِي عَيْنَايِمَ عَلَى الطَّرِيقِ؟» فَقَالُوا׃ «لَمْ تَكُنْ هَهُنَا زَانِيَةٌ».', 'تكوين 38:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 22, 'فَرَجَعَ إِلَى يَهُوذَا وَقَالَ׃ «لَمْ أَجِدْهَا. وَأَهْلُ الْمَكَانِ أَيْضًا قَالُوا׃ لَمْ تَكُنْ هَهُنَا زَانِيَةٌ».', 'تكوين 38:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 23, 'فَقَالَ يَهُوذَا׃ «لِتَأْخُذْ لِنَفْسِهَا، لِئَلَّا نَصِيرَ إِهَانَةً. إِنِّي قَدْ أَرْسَلْتُ هَذَا الْجَدْيَ وَأَنْتَ لَمْ تَجِدْهَا».', 'تكوين 38:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 24, 'وَلَمَّا كَانَ نَحْوُ ثَلَاثَةِ أَشْهُرٍ، أُخْبِرَ يَهُوذَا وَقِيلَ لَهُ׃ «قَدْ زَنَتْ ثَامَارُ كَنَّتُكَ، وَهَا هِيَ حُبْلَى أَيْضًا مِنَ الزِّنَا». فَقَالَ يَهُوذَا׃ «أَخْرِجُوهَا فَتُحْرَقَ».', 'تكوين 38:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 25, 'أَمَّا هِيَ فَلَمَّا أُخْرِجَتْ أَرْسَلَتْ إِلَى حَمِيهَا قَائِلَةً׃ «مِنَ الرَّجُلِ الَّذِي هَذِهِ لَهُ أَنَا حُبْلَى!» وَقَالَتْ׃ «حَقِّقْ لِمَنِ الْخَاتِمُ وَالْعِصَابَةُ وَالْعَصَا هَذِهِ».', 'تكوين 38:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 26, 'فَتَحَقَّقَهَا يَهُوذَا وَقَالَ׃ «هِيَ أَبَرُّ مِنِّي، لِأَنِّي لَمْ أُعْطِهَا لِشِيلَةَ ابْنِي». فَلَمْ يَعُدْ يَعْرِفُهَا أَيْضًا.', 'تكوين 38:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 27, 'وَفِي وَقْتِ وِلَادَتِهَا إِذَا فِي بَطْنِهَا تَوْأَمَانِ.', 'تكوين 38:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 28, 'وَكَانَ فِي وِلَادَتِهَا أَنَّ أَحَدَهُمَا أَخْرَجَ يَدًا فَأَخَذَتِ الْقَابِلَةُ وَرَبَطَتْ عَلَى يَدِهِ قِرْمِزًا، قَائِلَةً׃ «هَذَا خَرَجَ أَوَّلًا».', 'تكوين 38:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 29, 'وَلَكِنْ حِينَ رَدَّ يَدَهُ، إِذَا أَخُوهُ قَدْ خَرَجَ. فَقَالَتْ׃ «لِمَاذَا اقْتَحَمْتَ؟ عَلَيْكَ اقْتِحَامٌ!». فَدُعِيَ اسْمُهُ «فَارِصَ».', 'تكوين 38:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 38, 30, 'وَبَعْدَ ذَلِكَ خَرَجَ أَخُوهُ الَّذِي عَلَى يَدِهِ الْقِرْمِزُ. فَدُعِيَ اسْمُهُ «زَارَحَ».', 'تكوين 38:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 1, 'وَأَمَّا يُوسُفُ فَأُنْزِلَ إِلَى مِصْرَ، وَاشْتَرَاهُ فُوطِيفَارُ خَصِيُّ فِرْعَوْنَ رَئِيسُ الشُّرَطِ، رَجُلٌ مِصْرِيٌّ، مِنْ يَدِ الْإِسْمَاعِيلِيِّينَ الَّذِينَ أَنْزَلُوهُ إِلَى هُنَاكَ.', 'تكوين 39:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 2, 'وَكَانَ الرَّبُّ مَعَ يُوسُفَ فَكَانَ رَجُلًا نَاجِحًا، وَكَانَ فِي بَيْتِ سَيِّدِهِ الْمِصْرِيِّ.', 'تكوين 39:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 3, 'وَرَأَى سَيِّدُهُ أَنَّ الرَّبَّ مَعَهُ، وَأَنَّ كُلَّ مَا يَصْنَعُ كَانَ الرَّبُّ يُنْجِحُهُ بِيَدِهِ.', 'تكوين 39:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 4, 'فَوَجَدَ يُوسُفُ نِعْمَةً فِي عَيْنَيْهِ، وَخَدَمَهُ، فَوَكَّلَهُ عَلَى بَيْتِهِ وَدَفَعَ إِلَى يَدِهِ كُلَّ مَا كَانَ لَهُ.', 'تكوين 39:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 5, 'وَكَانَ مِنْ حِينِ وَكَّلَهُ عَلَى بَيْتِهِ، وَعَلَى كُلِّ مَا كَانَ لَهُ، أَنَّ الرَّبَّ بَارَكَ بَيْتَ الْمِصْرِيِّ بِسَبَبِ يُوسُفَ. وَكَانَتْ بَرَكَةُ الرَّبِّ عَلَى كُلِّ مَا كَانَ لَهُ فِي الْبَيْتِ وَفِي الْحَقْلِ،', 'تكوين 39:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 6, 'فَتَرَكَ كُلَّ مَا كَانَ لَهُ فِي يَدِ يُوسُفَ. وَلَمْ يَكُنْ مَعَهُ يَعْرِفُ شَيْئًا إِلَا الْخُبْزَ الَّذِي يَأْكُلُ. وَكَانَ يُوسُفُ حَسَنَ الصُّورَةِ وَحَسَنَ الْمَنْظَرِ.', 'تكوين 39:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 7, 'وَحَدَثَ بَعْدَ هَذِهِ الْأُمُورِ أَنَّ امْرَأَةَ سَيِّدِهِ رَفَعَتْ عَيْنَيْهَا إِلَى يُوسُفَ وَقَالَتِ׃ «اضْطَجِعْ مَعِي».', 'تكوين 39:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 8, 'فَأَبَى وَقَالَ لِامْرَأَةِ سَيِّدِهِ׃ «هُوَذَا سَيِّدِي لَا يَعْرِفُ مَعِي مَا فِي الْبَيْتِ، وَكُلُّ مَا لَهُ قَدْ دَفَعَهُ إِلَى يَدِي.', 'تكوين 39:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 9, 'لَيْسَ هُوَ فِي هَذَا الْبَيْتِ أَعْظَمَ مِنِّي. وَلَمْ يُمْسِكْ عَنِّي شَيْئًا غَيْرَكِ، لِأَنَّكِ امْرَأَتُهُ. فَكَيْفَ أَصْنَعُ هَذَا الشَّرَّ الْعَظِيمَ وَأُخْطِئُ إِلَى اللهِ؟».', 'تكوين 39:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 10, 'وَكَانَ إِذْ كَلَّمَتْ يُوسُفَ يَوْمًا فَيَوْمًا أَنَّهُ لَمْ يَسْمَعْ لَهَا أَنْ يَضْطَجِعَ بِجَانِبِهَا لِيَكُونَ مَعَهَا.', 'تكوين 39:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 11, 'ثُمَّ حَدَثَ نَحْوَ هَذَا الْوَقْتِ أَنَّهُ دَخَلَ الْبَيْتَ لِيَعْمَلَ عَمَلَهُ، وَلَمْ يَكُنْ إِنْسَانٌ مِنْ أَهْلِ الْبَيْتِ هُنَاكَ فِي الْبَيْتِ.', 'تكوين 39:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 12, 'فَأَمْسَكَتْهُ بِثَوْبِهِ قَائِلَةً׃ «اضْطَجِعْ مَعِي!». فَتَرَكَ ثَوْبَهُ فِي يَدِهَا وَهَرَبَ وَخَرَجَ إِلَى خَارِجٍ.', 'تكوين 39:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 13, 'وَكَانَ لَمَّا رَأَتْ أَنَّهُ تَرَكَ ثَوْبَهُ فِي يَدِهَا وَهَرَبَ إِلَى خَارِجٍ،', 'تكوين 39:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 14, 'أَنَّهَا نَادَتْ أَهْلَ بَيْتِهَا، وَكَلَّمَتهُمْ قَائِلةً׃ «انْظُرُوا! قَدْ جَاءَ إِلَيْنَا بِرَجُلٍ عِبْرَانِيٍّ لِيُدَاعِبَنَا! دَخَلَ إِلَيَّ لِيَضْطَجِعَ مَعِي، فَصَرَخْتُ بِصَوْتٍ عَظِيمٍ.', 'تكوين 39:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 15, 'وَكَانَ لَمَّا سَمِعَ أَنِّي رَفَعْتُ صَوْتِي وَصَرَخْتُ، أَنَّهُ تَرَكَ ثَوْبَهُ بِجَانِبِي وَهَرَبَ وَخَرَجَ إِلَى خَارِجٍ».', 'تكوين 39:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 16, 'فَوَضَعَتْ ثَوْبَهُ بِجَانِبِهَا حَتَّى جَاءَ سَيِّدُهُ إِلَى بَيْتِهِ.', 'تكوين 39:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 17, 'فَكَلَّمَتْهُ بِمِثْلِ هَذَا الْكَلَامِ قَائِلَةً׃ «دَخَلَ إِلَيَّ الْعَبْدُ الْعِبْرَانِيُّ الَّذِي جِئْتَ بِهِ إِلَيْنَا لِيُدَاعِبَنِي.', 'تكوين 39:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 18, 'وَكَانَ لَمَّا رَفَعْتُ صَوْتِي وَصَرَخْتُ، أَنَّهُ تَرَكَ ثَوْبَهُ بِجَانِبِي وَهَرَبَ إِلَى خَارِجٍ».', 'تكوين 39:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 19, 'فَكَانَ لَمَّا سَمِعَ سَيِّدُهُ كَلَامَ امْرَأَتِهِ الَّذِي كَلَّمَتْهُ بِهِ قَائِلَةً׃ «بِحَسَبِ هَذَا الْكَلَامِ صَنَعَ بِي عَبْدُكَ»، أَنَّ غَضَبَهُ حَمِيَ.', 'تكوين 39:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 20, 'فَأَخَذَ يُوسُفَ سَيِّدُهُ وَوَضَعَهُ فِي بَيْتِ السِّجْنِ، الْمَكَانِ الَّذِي كَانَ أَسْرَى الْمَلِكِ مَحْبُوسِينَ فِيهِ. وَكَانَ هُنَاكَ فِي بَيْتِ السِّجْنِ.', 'تكوين 39:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 21, 'وَلَكِنَّ الرَّبَّ كَانَ مَعَ يُوسُفَ، وَبَسَطَ إِلَيْهِ لُطْفًا، وَجَعَلَ نِعْمَةً لَهُ فِي عَيْنَيْ رَئِيسِ بَيْتِ السِّجْنِ.', 'تكوين 39:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 22, 'فَدَفَعَ رَئِيسُ بَيْتِ السِّجْنِ إِلَى يَدِ يُوسُفَ جَمِيعَ الْأَسْرَى الَّذِينَ فِي بَيْتِ السِّجْنِ. وَكُلُّ مَا كَانُوا يَعْمَلُونَ هُنَاكَ كَانَ هُوَ الْعَامِلَ.', 'تكوين 39:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 39, 23, 'وَلَمْ يَكُنْ رَئِيسُ بَيْتِ السِّجْنِ يَنْظُرُ شَيْئًا الْبَتَّةَ مِمَّا فِي يَدِهِ، لِأَنَّ الرَّبَّ كَانَ مَعَهُ، وَمَهْمَا صَنَعَ كَانَ الرَّبُّ يُنْجِحُهُ.', 'تكوين 39:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 1, 'وَحَدَثَ بَعْدَ هَذِهِ الْأُمُورِ أَنَّ سَاقِيَ مَلِكِ مِصْرَ وَالْخَبَّازَ أَذْنَبَا إِلَى سَيِّدِهِمَا مَلِكِ مِصْرَ.', 'تكوين 40:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 2, 'فَسَخَطَ فِرْعَوْنُ عَلَى خَصِيَّيْهِ׃ رَئِيسِ السُّقَاةِ وَرَئِيسِ الْخَبَّازِينَ،', 'تكوين 40:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 3, 'فَوَضَعَهُمَا فِي حَبْسِ بَيْتِ رَئِيسِ الشُّرَطِ، فِي بَيْتِ السِّجْنِ، الْمَكَانِ الَّذِي كَانَ يُوسُفُ مَحْبُوسًا فِيهِ.', 'تكوين 40:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 4, 'فَأَقَامَ رَئِيسُ الشُّرَطِ يُوسُفَ عِنْدَهُمَا فَخَدَمَهُمَا. وَكَانَا أَيَّامًا فِي الْحَبْسِ.', 'تكوين 40:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 5, 'وَحَلُمَا كِلَاهُمَا حُلْمًا فِي لَيْلَةٍ وَاحِدَةٍ، كُلُّ وَاحِدٍ حُلْمَهُ، كُلُّ وَاحِدٍ بِحَسَبِ تَعْبِيرِ حُلْمِهِ، سَاقِي مَلِكِ مِصْرَ وَخَبَّازُهُ، الْمَحْبُوسَانِ فِي بَيْتِ السِّجْنِ.', 'تكوين 40:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 6, 'فَدَخَلَ يُوسُفُ إِلَيْهِمَا فِي الصَّبَاحِ وَنَظَرَهُمَا، وَإِذَا هُمَا مُغْتَمَّانِ.', 'تكوين 40:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 7, 'فَسَأَلَ خَصِيَّيْ فِرْعَوْنَ اللَّذَيْنِ مَعَهُ فِي حَبْسِ بَيْتِ سَيِّدِهِ قَائِلًا׃ «لِمَاذَا وَجْهَاكُمَا مُكْمَدَّانِ الْيَوْمَ؟»', 'تكوين 40:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 8, 'فَقَالَا لَهُ׃ «حَلُمْنَا حُلْمًا وَلَيْسَ مَنْ يُعَبِّرُهُ». فَقَالَ لَهُمَا يُوسُفُ׃ «أَلَيْسَتْ لِلهِ التَّعَابِيرُ؟ قُصَّا عَلَيَّ».', 'تكوين 40:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 9, 'فَقَصَّ رَئِيسُ السُّقَاةِ حُلْمَهُ عَلَى يُوسُفَ وَقَالَ لَهُ׃ «كُنْتُ فِي حُلْمِي وَإِذَا كَرْمَةٌ أَمَامِي.', 'تكوين 40:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 10, 'وَفِي الْكَرْمَةِ ثَلَاثَةُ قُضْبَانٍ، وَهِيَ إِذْ أَفْرَخَتْ طَلَعَ زَهْرُهَا، وَأَنْضَجَتْ عَنَاقِيدُهَا عِنَبًا.', 'تكوين 40:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 11, 'وَكَانَتْ كَأْسُ فِرْعَوْنَ فِي يَدِي، فَأَخَذْتُ الْعِنَبَ وَعَصَرْتُهُ فِي كَأْسِ فِرْعَوْنَ، وَأَعْطَيْتُ الْكَأْسَ فِي يَدِ فِرْعَوْنَ».', 'تكوين 40:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 12, 'فَقَالَ لَهُ يُوسُفُ׃ «هَذَا تَعْبِيرُهُ׃ الثَّلَاثَةُ الْقُضْبَانِ هِيَ ثَلَاثَةُ أَيَّامٍ.', 'تكوين 40:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 13, 'فِي ثَلَاثَةِ أَيَّامٍ أَيْضًا يَرْفَعُ فِرْعَوْنُ رَأْسَكَ وَيَرُدُّكَ إِلَى مَقَامِكَ، فَتُعْطِي كَأْسَ فِرْعَوْنَ فِي يَدِهِ كَالْعَادَةِ الْأُولَى حِينَ كُنْتَ سَاقِيَهُ.', 'تكوين 40:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 14, 'وَإِنَّمَا إِذَا ذَكَرْتَنِي عِنْدَكَ حِينَمَا يَصِيرُ لَكَ خَيْرٌ، تَصْنَعُ إِلَيَّ إِحْسَانًا وَتَذْكُرُنِي لِفِرْعَوْنَ، وَتُخْرِجُنِي مِنْ هَذَا الْبَيْتِ.', 'تكوين 40:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 15, 'لِأَنِّي قَدْ سُرِقْتُ مِنْ أَرْضِ الْعِبْرَانِيِّينَ، وَهُنَا أَيْضًا لَمْ أَفْعَلْ شَيْئًا حَتَّى وَضَعُونِي فِي السِّجْنِ».', 'تكوين 40:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 16, 'فَلَمَّا رَأَى رَئِيسُ الْخَبَّازِينَ أَنَّهُ عَبَّرَ جَيِّدًا، قَالَ لِيُوسُفَ׃ «كُنْتُ أَنَا أَيْضًا فِي حُلْمِي وَإِذَا ثَلَاثَةُ سِلَالِ حُوَّارَى عَلَى رَأْسِي.', 'تكوين 40:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 17, 'وَفِي السَّلِّ الْأَعْلَى مِنْ جَمِيعِ طَعَامِ فِرْعَوْنَ مِنْ صَنْعَةِ الْخَبَّازِ. وَالطُّيُورُ تَأْكُلُهُ مِنَ السَّلِّ عَنْ رَأْسِي».', 'تكوين 40:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 18, 'فَأَجَابَ يُوسُفُ وَقَالَ׃ «هَذَا تَعْبِيرُهُ׃ الثَّلَاثَةُ السِّلَالِ هِيَ ثَلَاثَةُ أَيَّامٍ.', 'تكوين 40:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 19, 'فِي ثَلَاثَةِ أَيَّامٍ أَيْضًا يَرْفَعُ فِرْعَوْنُ رَأْسَكَ عَنْكَ، وَيُعَلِّقُكَ عَلَى خَشَبَةٍ، وَتَأْكُلُ الطُّيُورُ لَحْمَكَ عَنْكَ».', 'تكوين 40:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 20, 'فَحَدَثَ فِي الْيَوْمِ الثَّالِثِ، يَوْمِ مِيلَادِ فِرْعَوْنَ، أَنَّهُ صَنَعَ وَلِيمَةً لِجَمِيعِ عَبِيدِهِ، وَرَفَعَ رَأْسَ رَئِيسِ السُّقَاةِ وَرَأْسَ رَئِيسِ الْخَبَّازِينَ بَيْنَ عَبِيدِهِ.', 'تكوين 40:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 21, 'وَرَدَّ رَئِيسَ السُّقَاةِ إِلَى سَقْيِهِ، فَأَعْطَى الْكَأْسَ فِي يَدِ فِرْعَوْنَ.', 'تكوين 40:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 22, 'وَأَمَّا رَئِيسُ الْخَبَّازِينَ فَعَلَّقَهُ، كَمَا عَبَّرَ لَهُمَا يُوسُفُ.', 'تكوين 40:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 40, 23, 'وَلَكِنْ لَمْ يَذْكُرْ رَئِيسُ السُّقَاةِ يُوسُفَ بَلْ نَسِيَهُ.', 'تكوين 40:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 1, 'وَحَدَثَ مِنْ بَعْدِ سَنَتَيْنِ مِنَ الزَّمَانِ أَنَّ فِرْعَوْنَ رَأَى حُلْمًا׃ وَإِذَا هُوَ وَاقِفٌ عِنْدَ النَّهْرِ،', 'تكوين 41:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 2, 'وَهُوَذَا سَبْعُ بَقَرَاتٍ طَالِعَةٍ مِنَ النَّهْرِ حَسَنَةِ الْمَنْظَرِ وَسَمِينَةِ اللَّحْمِ، فَارْتَعَتْ فِي رَوْضَةٍ.', 'تكوين 41:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 3, 'ثُمَّ هُوَذَا سَبْعُ بَقَرَاتٍ أُخْرَى طَالِعَةٍ وَرَاءَهَا مِنَ النَّهْرِ قَبِيحَةِ الْمَنْظَرِ وَرَقِيقَةِ اللَّحْمِ، فَوَقَفَتْ بِجَانِبِ الْبَقَرَاتِ الْأُولَى عَلَى شَاطِئِ النَّهْرِ،', 'تكوين 41:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 4, 'فَأَكَلَتِ الْبَقَرَاتُ الْقَبِيحَةُ الْمَنْظَرِ وَالرَّقِيقَةُ اللَّحْمِ الْبَقَرَاتِ السَّبْعَ الْحَسَنَةَ الْمَنْظَرِ وَالسَّمِينَةَ. وَاسْتَيْقَظَ فِرْعَوْنُ.', 'تكوين 41:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 5, 'ثُمَّ نَامَ فَحَلُمَ ثَانِيَةً׃ وَهُوَذَا سَبْعُ سَنَابِلَ طَالِعَةٍ فِي سَاقٍ وَاحِدٍ سَمِينَةٍ وَحَسَنَةٍ.', 'تكوين 41:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 6, 'ثُمَّ هُوَذَا سَبْعُ سَنَابِلَ رَقِيقَةٍ وَمَلْفُوحَةٍ بِالرِّيحِ الشَّرْقِيَّةِ نَابِتَةٍ وَرَاءَهَا.', 'تكوين 41:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 7, 'فَابْتَلَعَتِ السَّنَابِلُ الرَّقِيقَةُ السَّنَابِلَ السَّبْعَ السَّمِينَةَ الْمُمْتَلِئَةَ. وَاسْتَيْقَظَ فِرْعَوْنُ، وَإِذَا هُوَ حُلْمٌ.', 'تكوين 41:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 8, 'وَكَانَ فِي الصَّبَاحِ أَنَّ نَفْسَهُ انْزَعَجَتْ، فَأَرْسَلَ وَدَعَا جَمِيعَ سَحَرَةِ مِصْرَ وَجَمِيعَ حُكَمَائِهَا. وَقَصَّ عَلَيْهِمْ فِرْعَوْنُ حُلْمَهُ، فَلَمْ يَكُنْ مَنْ يُعَبِّرُهُ لِفِرْعَوْنَ.', 'تكوين 41:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 9, 'ثُمَّ كَلَّمَ رَئِيسُ السُّقَاةِ فِرْعَوْنَ قَائِلًا׃ «أَنَا أَتَذَكَّرُ الْيَوْمَ خَطَايَايَ.', 'تكوين 41:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 10, 'فِرْعَوْنُ سَخَطَ عَلَى عَبْدَيْهِ، فَجَعَلَنِي فِي حَبْسِ بَيْتِ رَئِيسِ الشُّرَطِ أَنَا وَرَئِيسَ الْخَبَّازِينَ.', 'تكوين 41:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 11, 'فَحَلُمْنَا حُلْمًا فِي لَيْلَةٍ وَاحِدَةٍ أَنَا وَهُوَ. حَلُمْنَا كُلُّ وَاحِدٍ بِحَسَبِ تَعْبِيرِ حُلْمِهِ.', 'تكوين 41:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 12, 'وَكَانَ هُنَاكَ مَعَنَا غُلَامٌ عِبْرَانِيٌّ عَبْدٌ لِرَئِيسِ الشُّرَطِ، فَقَصَصْنَا عَلَيْهِ، فَعَبَّرَ لَنَا حُلْمَيْنَا. عَبَّرَ لِكُلِّ وَاحِدٍ بِحَسَبِ حُلْمِهِ.', 'تكوين 41:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 13, 'وَكَمَا عَبَّرَ لَنَا هَكَذَا حَدَثَ. رَدَّنِي أَنَا إِلَى مَقَامِي، وَأَمَّا هُوَ فَعَلَّقَهُ».', 'تكوين 41:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 14, 'فَأَرْسَلَ فِرْعَوْنُ وَدَعَا يُوسُفَ، فَأَسْرَعُوا بِهِ مِنَ السِّجْنِ. فَحَلَقَ وَأَبْدَلَ ثِيَابَهُ وَدَخَلَ عَلَى فِرْعَوْنَ.', 'تكوين 41:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 15, 'فَقَالَ فِرْعَوْنُ لِيُوسُفَ׃ «حَلُمْتُ حُلْمًا وَلَيْسَ مَنْ يُعَبِّرُهُ. وَأَنَا سَمِعْتُ عَنْكَ قَوْلًا، إِنَّكَ تَسْمَعُ أَحْلَامًا لِتُعَبِّرَهَا».', 'تكوين 41:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 16, 'فَأَجَابَ يُوسُفُ فِرْعَوْنَ قَائِلًا׃ «لَيْسَ لِي. اللهُ يُجِيبُ بِسَلَامَةٍ فِرْعَوْنَ».', 'تكوين 41:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 17, 'فَقَالَ فِرْعَوْنُ لِيُوسُفَ׃ «إِنِّي كُنْتُ فيِ حُلْمِي وَاقِفًا عَلَى شَاطِئِ النَّهْرِ،', 'تكوين 41:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 18, 'وَهُوَذَا سَبْعُ بَقَرَاتٍ طَالِعَةٍ مِنَ النَّهْرِ سَمِينَةِ اللَّحْمِ وَحَسَنَةَ الصُّورَةِ، فَارْتَعَتْ فِي رَوْضَةٍ.', 'تكوين 41:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 19, 'ثُمَّ هُوَذَا سَبْعُ بَقَرَاتٍ أُخْرَى طَالِعَةٍ وَرَاءَهَا مَهْزُولَةً وَقَبِيحَةَ الصُّورَةِ جِدًّا وَرَقِيقَةَ اللَّحْمِ. لَمْ أَنْظُرْ فِي كُلِّ أَرْضِ مِصْرَ مِثْلَهَا فِي الْقَبَاحَةِ.', 'تكوين 41:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 20, 'فَأَكَلَتِ الْبَقَرَاتُ الرَّقِيقَةُ وَالْقَبِيحَةُ الْبَقَرَاتِ السَّبْعَ الْأُولَى السَّمِينَةَ.', 'تكوين 41:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 21, 'فَدَخَلَتْ أَجْوَافَهَا، وَلَمْ يَعْلَمْ أَنَّهَا دَخَلَتْ فِي أَجْوَافِهَا، فَكَانَ مَنْظَرُهَا قَبِيحًا كَمَا فِي الْأَوَّلِ. وَاسْتَيْقَظْتُ.', 'تكوين 41:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 22, 'ثُمَّ رَأَيْتُ فِي حُلْمِي وَهُوَذَا سَبْعُ سَنَابِلَ طَالِعَةٌ فِي سَاقٍ وَاحِدٍ مُمْتَلِئَةً وَحَسَنَةً.', 'تكوين 41:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 23, 'ثُمَّ هُوَذَا سَبْعُ سَنَابِلَ يَابِسَةً رَقِيقَةً مَلْفُوحَةً بِالرِّيحِ الشَّرْقِيَّةِ نَابِتَةٌ وَرَاءَهَا.', 'تكوين 41:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 24, 'فَابْتَلَعَتِ السَّنَابِلُ الرَّقِيقَةُ السَّنَابِلَ السَّبْعَ الْحَسَنَةَ. فَقُلْتُ لِلسَّحَرَةِ، وَلَمْ يَكُنْ مَنْ يُخْبِرُنِي».', 'تكوين 41:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 25, 'فَقَالَ يُوسُفُ لِفِرْعَوْنَ׃ «حُلْمُ فِرْعَوْنَ وَاحِدٌ. قَدْ أَخْبَرَ اللهُ فِرْعَوْنَ بِمَا هُوَ صَانِعٌ.', 'تكوين 41:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 26, 'اَلْبَقَرَاتُ السَّبْعُ الْحَسَنَةُ هِيَ سَبْعُ سِنِينَ، وَالسَّنَابِلُ السَّبْعُ الْحَسَنَةُ هِيَ سَبْعُ سِنِينَ. هُوَ حُلْمٌ وَاحِدٌ.', 'تكوين 41:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 27, 'وَالْبَقَرَاتُ السَّبْعُ الرَّقِيقَةُ الْقَبِيحَةُ الَّتِي طَلَعَتْ وَرَاءَهَا هِيَ سَبْعُ سِنِينَ، وَالسَّنَابِلُ السَّبْعُ الْفَارِغَةُ الْمَلْفُوحَةُ بِالرِّيحِ الشَّرْقِيَّةِ تَكُونُ سَبْعَ سِنِينَ جُوعًا.', 'تكوين 41:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 28, 'هُوَ الْأَمْرُ الَّذِي كَلَّمْتُ بِهِ فِرْعَوْنَ. قَدْ أَظْهَرَ اللهُ لِفِرْعَوْنَ مَا هُوَ صَانِعٌ.', 'تكوين 41:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 29, 'هُوَذَا سَبْعُ سِنِينَ قَادِمَةٌ شِبَعًا عَظِيمًا فِي كُلِّ أَرْضِ مِصْرَ.', 'تكوين 41:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 30, 'ثُمَّ تَقُومُ بَعْدَهَا سَبْعُ سِنِينَ جُوعًا، فَيُنْسَى كُلُّ الشِّبَعِ فِي أَرْضِ مِصْرَ وَيُتْلِفُ الْجُوعُ الْأَرْضَ.', 'تكوين 41:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 31, 'وَلَا يُعْرَفُ الشِّبَعُ فِي الْأَرْضِ مِنْ أَجْلِ ذَلِكَ الْجُوعِ بَعْدَهُ، لِأَنَّهُ يَكُونُ شَدِيدًا جِدًّا.', 'تكوين 41:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 32, 'وَأَمَّا عَنْ تَكْرَارِ الْحُلْمِ عَلَى فِرْعَوْنَ مَرَّتَيْنِ، فَلِأَنَّ الْأَمْرَ مُقَرَّرٌ مِنْ قِبَلِ اللهِ، وَاللهُ مُسْرِعٌ لِيَصْنَعَهُ.', 'تكوين 41:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 33, '«فَالْآنَ لِيَنْظُرْ فِرْعَوْنُ رَجُلًا بَصِيرًا وَحَكِيمًا وَيَجْعَلْهُ عَلَى أَرْضِ مِصْرَ.', 'تكوين 41:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 34, 'يَفْعَلْ فِرْعَوْنُ فَيُوَكِّلْ نُظَّارًا عَلَى الْأَرْضِ، وَيَأْخُذْ خُمْسَ غَلَّةِ أَرْضِ مِصْرَ فِي سَبْعِ سِنِي الشِّبَعِ،', 'تكوين 41:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 35, 'فَيَجْمَعُونَ جَمِيعَ طَعَامِ هَذِهِ السِّنِينَ الْجَيِّدَةِ الْقَادِمَةِ، وَيَخْزِنُونَ قَمْحًا تَحْتَ يَدِ فِرْعَوْنَ طَعَامًا فِي الْمُدُنِ وَيَحْفَظُونَهُ.', 'تكوين 41:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 36, 'فَيَكُونُ الطَّعَامُ ذَخِيرَةً لِلْأَرْضِ لِسَبْعِ سِنِي الْجُوعِ الَّتِي تَكُونُ فِي أَرْضِ مِصْرَ، فَلَا تَنْقَرِضُ الْأَرْضُ بِالْجُوعِ».', 'تكوين 41:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 37, 'فَحَسُنَ الْكَلَامُ فِي عَيْنَيْ فِرْعَوْنَ وَفِي عُيُونِ جَمِيعِ عَبِيدِهِ.', 'تكوين 41:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 38, 'فَقَالَ فِرْعَوْنُ لِعَبِيدِهِ׃ «هَلْ نَجِدُ مِثْلَ هَذَا رَجُلًا فِيهِ رُوحُ اللهِ؟»', 'تكوين 41:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 39, 'ثُمَّ قَالَ فِرْعَوْنُ لِيُوسُفَ׃ «بَعْدَ مَا أَعْلَمَكَ اللهُ كُلَّ هَذَا، لَيْسَ بَصِيرٌ وَحَكِيمٌ مِثْلَكَ.', 'تكوين 41:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 40, 'أَنْتَ تَكُونُ عَلَى بَيْتِي، وَعَلَى فَمِكَ يُقَبِّلُ جَمِيعُ شَعْبِي إِلَا إِنَّ الْكُرْسِيَّ أَكُونُ فِيهِ أَعْظَمَ مِنْكَ».', 'تكوين 41:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 41, 'ثُمَّ قَالَ فِرْعَوْنُ لِيُوسُفَ׃ «انْظُرْ، قَدْ جَعَلْتُكَ عَلَى كُلِّ أَرْضِ مِصْرَ».', 'تكوين 41:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 42, 'وَخَلَعَ فِرْعَوْنُ خَاتِمَهُ مِنْ يَدِهِ وَجَعَلَهُ فِي يَدِ يُوسُفَ، وَأَلْبَسَهُ ثِيَابَ بُوصٍ، وَوَضَعَ طَوْقَ ذَهَبٍ فِي عُنُقِهِ،', 'تكوين 41:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 43, 'وَأَرْكَبَهُ فِي مَرْكَبَتِهِ الْثَّانِيَةِ، وَنَادَوْا أَمَامَهُ «ارْكَعُوا». وَجَعَلَهُ عَلَى كُلِّ أَرْضِ مِصْرَ.', 'تكوين 41:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 44, 'وَقَالَ فِرْعَوْنُ لِيُوسُفَ׃ «أَنَا فِرْعَوْنُ. فَبِدُونِكَ لَا يَرْفَعُ إِنْسَانٌ يَدَهُ وَلَا رِجْلَهُ فِي كُلِّ أَرْضِ مِصْرَ».', 'تكوين 41:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 45, 'وَدَعَا فِرْعَوْنُ اسْمَ يُوسُفَ «صَفْنَاتَ فَعْنِيحَ»، وَأَعْطَاهُ أَسْنَاتَ بِنْتَ فُوطِي فَارَعَ كَاهِنِ أُونَ زَوْجَةً. فَخَرَجَ يُوسُفُ عَلَى أَرْضِ مِصْرَ.', 'تكوين 41:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 46, 'وَكَانَ يُوسُفُ ابْنَ ثَلَاثِينَ سَنَةً لَمَّا وَقَفَ قُدَّامَ فِرْعَوْنَ مَلِكِ مِصْرَ. فَخَرَجَ يُوسُفُ مِنْ لَدُنْ فِرْعَوْنَ وَاجْتَازَ فِي كُلِّ أَرْضِ مِصْرَ.', 'تكوين 41:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 47, 'وَأَثْمَرَتِ الْأَرْضُ فِي سَبْعِ سِنِي الشِّبَعِ بِحُزَمٍ.', 'تكوين 41:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 48, 'فَجَمَعَ كُلَّ طَعَامِ السَّبْعِ سِنِينَ الَّتِي كَانَتْ فِي أَرْضِ مِصْرَ، وَجَعَلَ طَعَامًا فِي الْمُدُنِ. طَعَامَ حَقْلِ الْمَدِينَةِ الَّذِي حَوَالَيْهَا جَعَلَهُ فِيهَا.', 'تكوين 41:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 49, 'وَخَزَنَ يُوسُفُ قَمْحًا كَرَمْلِ الْبَحْرِ، كَثِيرًا جِدًّا حَتَّى تَرَكَ الْعَدَدَ، إِذْ لَمْ يَكُنْ لَهُ عَدَدٌ.', 'تكوين 41:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 50, 'وَوُلِدَ لِيُوسُفَ ابْنَانِ قَبْلَ أَنْ تَأْتِيَ سَنَةُ الْجُوعِ، وَلَدَتْهُمَا لَهُ أَسْنَاتُ بِنْتُ فُوطِي فَارَعَ كَاهِنِ أُونَ.', 'تكوين 41:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 51, 'وَدَعَا يُوسُفُ اسْمَ الْبِكْرِ «مَنَسَّى» قَائِلًا׃ «لِأَنَّ اللهَ أَنْسَانِي كُلَّ تَعَبِي وَكُلَّ بَيْتِ أَبِي».', 'تكوين 41:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 52, 'وَدَعَا اسْمَ الثَّانِى «أَفْرَايِمَ» قَائِلًا׃ «لِأَنَّ اللهَ جَعَلَنِي مُثْمِرًا فِي أَرْضِ مَذَلَّتِي».', 'تكوين 41:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 53, 'ثُمَّ كَمِلَتْ سَبْعُ سِنِي الشِّبَعِ الَّذِي كَانَ فِي أَرْضِ مِصْرَ.', 'تكوين 41:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 54, 'وَابْتَدَأَتْ سَبْعُ سِنِي الْجُوعِ تَأْتِي كَمَا قَالَ يُوسُفُ، فَكَانَ جُوعٌ فِي جَمِيعِ الْبُلْدَانِ. وَأَمَّا جَمِيعُ أَرْضِ مِصْرَ فَكَانَ فِيهَا خُبْزٌ.', 'تكوين 41:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 55, 'وَلَمَّا جَاعَتْ جَمِيعُ أَرْضِ مِصْرَ وَصَرَخَ الشَّعْبُ إِلَى فِرْعَوْنَ لِأَجْلِ الْخُبْزِ، قَالَ فِرْعَوْنُ لِكُلِّ الْمِصْرِيِّينَ׃ «اذْهَبُوا إِلَى يُوسُفَ، وَالَّذِي يَقُولُ لَكُمُ افْعَلُوا».', 'تكوين 41:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 56, 'وَكَانَ الْجُوعُ عَلَى كُلِّ وَجْهِ الْأَرْضِ، وَفَتَحَ يُوسُفُ جَمِيعَ مَا فِيهِ طَعَامٌ وَبَاعَ لِلْمِصْرِيِّينَ. وَاشْتَدَّ الْجُوعُ فِي أَرْضِ مِصْرَ.', 'تكوين 41:56');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 41, 57, 'وَجَاءَتْ كُلُّ الْأَرْضِ إِلَى مِصْرَ إِلَى يُوسُفَ لِتَشْتَرِيَ قَمْحًا، لِأَنَّ الْجُوعَ كَانَ شَدِيدًا فِي كُلِّ الْأَرْضِ.', 'تكوين 41:57');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 1, 'فَلَمَّا رَأَى يَعْقُوبُ أَنَّهُ يُوجَدُ قَمْحٌ فِي مِصْرَ، قَالَ يَعْقُوبُ لِبَنِيهِ׃ «لِمَاذَا تَنْظُرُونَ بَعْضُكُمْ إِلَى بَعْضٍ؟»', 'تكوين 42:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 2, 'وَقَالَ «إِنِّي قَدْ سَمِعْتُ أَنَّهُ يُوجَدُ قَمْحٌ فِي مِصْرَ. انْزِلُوا إِلَى هُنَاكَ وَاشْتَرُوا لَنَا مِنْ هُنَاكَ لِنَحْيَا وَلَا نَمُوتَ».', 'تكوين 42:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 3, 'فَنَزَلَ عَشْرَةٌ مِنْ إِخْوَةِ يُوسُفَ لِيَشْتَرُوا قَمْحًا مِنْ مِصْرَ.', 'تكوين 42:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 4, 'وَأَمَّا بَنْيَامِينُ أَخُو يُوسُفَ فَلَمْ يُرْسِلْهُ يَعْقُوبُ مَعَ إِخْوَتِهِ، لِأَنَّهُ قَالَ׃ «لَعَلَّهُ تُصِيبُهُ أَذِيَّةٌ».', 'تكوين 42:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 5, 'فَأَتَى بَنُو إِسْرَائِيلَ لِيَشْتَرُوا بَيْنَ الَّذِينَ أَتَوْا، لِأَنَّ الْجُوعَ كَانَ فِي أَرْضِ كَنْعَانَ.', 'تكوين 42:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 6, 'وَكَانَ يُوسُفُ هُوَ الْمُسَلَّطَ عَلَى الْأَرْضِ، وَهُوَ الْبَائِعَ لِكُلِّ شَعْبِ الْأَرْضِ. فَأَتَى إِخْوَةُ يُوسُفَ وَسَجَدُوا لَهُ بِوُجُوهِهِمْ إِلَى الْأَرْضِ.', 'تكوين 42:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 7, 'وَلَمَّا نَظَرَ يُوسُفُ إِخْوَتَهُ عَرَفَهُمْ، فَتَنَكَّرَ لَهُمْ وَتَكَلَّمَ مَعَهُمْ بِجَفَاءٍ، وَقَالَ لَهُمْ׃ «مِنْ أَيْنَ جِئْتُمْ؟» فَقَالُوا׃ «مِنْ أَرْضِ كَنْعَانَ لِنَشْتَرِيَ طَعَامًا».', 'تكوين 42:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 8, 'وَعَرَفَ يُوسُفُ إِخْوَتَهُ، وَأَمَّا هُمْ فَلَمْ يَعْرِفُوهُ.', 'تكوين 42:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 9, 'فَتَذَكَّرَ يُوسُفُ الْأَحْلَامَ الَّتِي حَلُمَ عَنْهُمْ، وَقَالَ لَهُمْ׃ «جَوَاسِيسُ أَنْتُمْ! لِتَرَوْا عَوْرَةَ الْأَرْضِ جِئْتُمْ»', 'تكوين 42:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 10, 'فَقَالُوا لَهُ׃ «لَا يَا سَيِّدِي، بَلْ عَبِيدُكَ جَاءُوا لِيَشْتَرُوا طَعَامًا.', 'تكوين 42:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 11, 'نَحْنُ جَمِيعُنَا بَنُو رَجُلٍ وَاحِدٍ. نَحْنُ أُمَنَاءُ، لَيْسَ عَبِيدُكَ جَوَاسِيسَ».', 'تكوين 42:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 12, 'فَقَالَ لَهُمْ׃ «كَلَّا! بَلْ لِتَرَوْا عَوْرَةَ الْأَرْضِ جِئْتُمْ».', 'تكوين 42:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 13, 'فَقَالُوا׃ «عَبِيدُكَ اثْنَا عَشَرَ أَخًا. نَحْنُ بَنُو رَجُلٍ وَاحِدٍ فِي أَرْضِ كَنْعَانَ. وَهُوَذَا الصَّغِيرُ عِنْدَ أَبِينَا الْيَوْمَ، وَالْوَاحِدُ مَفْقُودٌ».', 'تكوين 42:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 14, 'فَقَالَ لَهُمْ يُوسُفُ׃ «ذَلِكَ مَا كَلَّمْتُكُمْ بِهِ قَائِلًا׃ جَوَاسِيسُ أَنْتُمْ!', 'تكوين 42:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 15, 'بِهَذَا تُمْتَحَنُونَ. وَحَيَاةِ فِرْعَوْنَ لَا تَخْرُجُونَ مِنْ هُنَا إِلَا بِمَجِيءِ أَخِيكُمُ الصَّغِيرِ إِلَى هُنَا.', 'تكوين 42:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 16, 'أَرْسِلُوا مِنْكُمْ وَاحِدًا لِيَجِيءَ بِأَخِيكُمْ، وَأَنْتُمْ تُحْبَسُونَ، فَيُمْتَحَنَ كَلَامُكُمْ هَلْ عِنْدَكُمْ صِدْقٌ. وَإِلَا فَوَحَيَاةِ فِرْعَوْنَ إِنَّكُمْ لَجَوَاسِيسُ!».', 'تكوين 42:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 17, 'فَجَمَعَهُمْ إِلَى حَبْسٍ ثَلَاثَةَ أَيَّامٍ.', 'تكوين 42:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 18, 'ثُمَّ قَالَ لَهُمْ يُوسُفُ فِي الْيَوْمِ الثَّالِثِ׃ «افْعَلُوا هَذَا وَاحْيَوْا. أَنَا خَائِفُ اللهِ.', 'تكوين 42:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 19, 'إِنْ كُنْتُمْ أُمَنَاءَ فَلْيُحْبَسْ أَخٌ وَاحِدٌ مِنْكُمْ فِي بَيْتِ حَبْسِكُمْ، وَانْطَلِقُوا أَنْتُمْ وَخُذُوا قَمْحًا لِمَجَاعَةِ بُيُوتِكُمْ.', 'تكوين 42:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 20, 'وَأَحْضِرُوا أَخَاكُمُ الصَّغِيرَ إِلَيَّ، فَيَتَحَقَّقَ كَلَامُكُمْ وَلَا تَمُوتُوا». فَفَعَلُوا هَكَذَا.', 'تكوين 42:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 21, 'وَقَالُوا بَعْضُهُمْ لِبَعْضٍ׃ «حَقًّا إِنَّنَا مُذْنِبُونَ إِلَى أَخِينَا الَّذِي رَأَيْنَا ضِيقَةَ نَفْسِهِ لَمَّا اسْتَرْحَمَنَا وَلَمْ نَسْمَعْ. لِذَلِكَ جَاءَتْ عَلَيْنَا هَذِهِ الضِّيقَةُ».', 'تكوين 42:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 22, 'فَأَجَابَهُمْ رَأُوبَيْنُ قَائِلًا׃ «أَلَمْ أُكَلِّمْكُمْ قَائِلًا׃ لَا تَأْثَمُوا بِالْوَلَدِ، وَأَنْتُمْ لَمْ تَسْمَعُوا؟ فَهُوَذَا دَمُهُ يُطْلَبُ».', 'تكوين 42:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 23, 'وَهُمْ لَمْ يَعْلَمُوا أَنَّ يُوسُفَ فَاهِمٌ، لِأَنَّ التُّرْجُمَانَ كَانَ بَيْنَهُمْ.', 'تكوين 42:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 24, 'فَتَحَوَّلَ عَنْهُمْ وَبَكَى، ثُمَّ رَجَعَ إِلَيْهِمْ وَكَلَّمَهُمْ، وَأَخَذَ مِنْهُمْ شِمْعُونَ وَقَيَّدَهُ أَمَامَ عُيُونِهِمْ.', 'تكوين 42:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 25, 'ثُمَّ أَمَرَ يُوسُفُ أَنْ تُمْلَأَ أَوْعِيَتُهُمْ قَمْحًا، وَتُرَدَّ فِضَّةُ كُلِّ وَاحِدٍ إِلَى عِدْلِهِ، وَأَنْ يُعْطَوْا زَادًا لِلطَّرِيقِ. فَفُعِلَ لَهُمْ هَكَذَا.', 'تكوين 42:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 26, 'فَحَمَلُوا قَمْحَهُمْ عَلَى حَمِيرِهِمْ وَمَضَوْا مِنْ هُنَاكَ.', 'تكوين 42:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 27, 'فَلَمَّا فَتَحَ أَحَدُهُمْ عِدْلَهُ لِيُعْطِيَ عَلِيقًا لِحِمَارِهِ فِي الْمَنْزِلِ، رَأَى فِضَّتَهُ وَإِذَا هِيَ فِي فَمِ عِدْلِهِ.', 'تكوين 42:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 28, 'فَقَالَ لِإِخْوَتِهِ׃ «رُدَّتْ فِضَّتِي وَهَا هِيَ فِي عِدْلِي». فَطَارَتْ قُلُوبُهُمْ وَارْتَعَدُوا بَعْضُهُمْ فِي بَعْضٍ قَائِلِينَ׃ «مَا هَذَا الَّذِي صَنَعَهُ اللهُ بِنَا؟».', 'تكوين 42:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 29, 'فَجَاءُوا إِلَى يَعْقُوبَ أَبِيهِمْ إِلَى أَرْضِ كَنْعَانَ، وَأَخْبَرُوهُ بِكُلِّ مَا أَصَابَهُمْ قَائِلِينَ׃', 'تكوين 42:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 30, '«تَكَلَّمَ مَعَنَا الرَّجُلُ سَيِّدُ الْأَرْضِ بِجَفَاءٍ، وَحَسِبَنَا جَوَاسِيسَ الْأَرْضِ.', 'تكوين 42:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 31, 'فَقُلْنَا لَهُ׃ نَحْنُ أُمَنَاءُ، لَسْنَا جَوَاسِيسَ.', 'تكوين 42:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 32, 'نَحْنُ اثْنَا عَشَرَ أَخًا بَنُو أَبِينَا. الْوَاحِدُ مَفْقُودٌ وَالصَّغِيرُ الْيَوْمَ عِنْدَ أَبِينَا فِي أَرْضِ كَنْعَانَ.', 'تكوين 42:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 33, 'فَقَالَ لَنَا الرَّجُلُ سَيِّدُ الْأَرْضِ׃ بِهَذَا أَعْرِفُ أَنَّكُمْ أُمَنَاءُ. دَعُوا أَخًا وَاحِدًا مِنْكُمْ عِنْدِي، وَخُذُوا لِمَجَاعَةِ بُيُوتِكُمْ وَانْطَلِقُوا.', 'تكوين 42:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 34, 'وَأَحْضِرُوا أَخَاكُمُ الصَّغِيرَ إِلَيَّ فَأَعْرِفَ أَنَّكُمْ لَسْتُمْ جَوَاسِيسَ، بَلْ أَنَّكُمْ أُمَنَاءُ، فَأُعْطِيَكُمْ أَخَاكُمْ وَتَتَّجِرُونَ فِي الْأَرْضِ».', 'تكوين 42:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 35, 'وَإِذْ كَانُوا يُفَرِّغُونَ عِدَالَهُمْ إِذَا صُرَّةُ فِضَّةِ كُلِّ وَاحِدٍ فِي عِدْلِهِ. فَلَمَّا رَأَوْا صُرَرَ فِضَّتِهِمْ هُمْ وَأَبُوهُمْ خَافُوا.', 'تكوين 42:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 36, 'فَقَالَ لَهُمْ يَعْقُوبُ׃ «أَعْدَمْتُمُونِي الْأَوْلَادَ. يُوسُفُ مَفْقُودٌ، وَشِمْعُونُ مَفْقُودٌ، وَبَنْيَامِينُ تَأْخُذُونَهُ. صَارَ كُلُّ هَذَا عَلَيَّ».', 'تكوين 42:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 37, 'وَكَلَّمَ رَأُوبَيْنُ أَبَاهُ قَائِلًا׃ «اقْتُلِ ابْنَيَّ إِنْ لَمْ أَجِئْ بِهِ إِلَيْكَ. سَلِّمْهُ بِيَدِي وَأَنَا أَرُدُّهُ إِلَيْكَ».', 'تكوين 42:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 42, 38, 'فَقَالَ׃ «لَا يَنْزِلُ ابْنِي مَعَكُمْ، لِأَنَّ أَخَاهُ قَدْ مَاتَ، وَهُوَ وَحْدَهُ بَاقٍ. فَإِنْ أَصَابَتْهُ أَذِيَّةٌ فِي الطَّرِيقِ الَّتِي تَذْهَبُونَ فِيهَا تُنْزِلُونَ شَيْبَتِي بِحُزْنٍ إِلَى الْهَاوِيَةِ».', 'تكوين 42:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 1, 'وَكَانَ الْجُوعُ شَدِيدًا فِي الْأَرْضِ.', 'تكوين 43:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 2, 'وَحَدَثَ لَمَّا فَرَغُوا مِنْ أَكْلِ الْقَمْحِ الَّذِي جَاءُوا بِهِ مِنْ مِصْرَ، أَنَّ أَبَاهُمْ قَالَ لَهُمُ׃ «ارْجِعُوا اشْتَرُوا لَنَا قَلِيلًا مِنَ الطَّعَامِ».', 'تكوين 43:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 3, 'فَكَلَّمَهُ يَهُوذَا قَائِلًا׃ «إِنَّ الرَّجُلَ قَدْ أَشْهَدَ عَلَيْنَا قَائِلًا׃ لَا تَرَوْنَ وَجْهِي بِدُونِ أَنْ يَكُونَ أَخُوكُمْ مَعَكُمْ.', 'تكوين 43:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 4, 'إِنْ كُنْتَ تُرْسِلُ أَخَانَا مَعَنَا، نَنْزِلُ وَنَشْتَرِي لَكَ طَعَامًا،', 'تكوين 43:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 5, 'وَلَكِنْ إِنْ كُنْتَ لَا تُرْسِلُهُ لَا نَنْزِلُ. لِأَنَّ الرَّجُلَ قَالَ لَنَا׃ لَا تَرَوْنَ وَجْهِي بِدُونِ أَنْ يَكُونَ أَخُوكُمْ مَعَكُمْ».', 'تكوين 43:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 6, 'فَقَالَ إِسْرَائِيلُ׃ «لِمَاذَا أَسَأْتُمْ إِلَيَّ حَتَّى أَخْبَرْتُمُ الرَّجُلَ أَنَّ لَكُمْ أَخًا أَيْضًا؟»', 'تكوين 43:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 7, 'فَقَالُوا׃ «إِنَّ الرَّجُلَ قَدْ سَأَلَ عَنَّا وَعَنْ عَشِيرَتِنَا، قَائِلًا׃ هَلْ أَبُوكُمْ حَيٌّ بَعْدُ؟ هَلْ لَكُمْ أَخٌ؟ فَأَخْبَرْنَاهُ بِحَسَبِ هَذَا الْكَلَامِ. هَلْ كُنَّا نَعْلَمُ أَنَّهُ يَقُولُ׃ انْزِلُوا بِأَخِيكُمْ؟».', 'تكوين 43:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 8, 'وَقَالَ يَهُوذَا لِإِسْرَائِيلَ أَبِيهِ׃ «أَرْسِلِ الْغُلَامَ مَعِي لِنَقُومَ وَنَذْهَبَ وَنَحْيَا وَلَا نَمُوتَ، نَحْنُ وَأَنْتَ وَأَوْلَادُنَا جَمِيعًا.', 'تكوين 43:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 9, 'أَنَا أَضْمَنُهُ. مِنْ يَدِي تَطْلُبُهُ. إِنْ لَمْ أَجِئْ بِهِ إِلَيْكَ وَأُوقِفْهُ قُدَّامَكَ، أَصِرْ مُذْنِبًا إِلَيْكَ كُلَّ الْأَيَّامِ.', 'تكوين 43:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 10, 'لِأَنَّنَا لَوْ لَمْ نَتَوَانَ لَكُنَّا قَدْ رَجَعْنَا الْآنَ مَرَّتَيْنِ».', 'تكوين 43:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 11, 'فَقَالَ لَهُمْ إِسْرَائِيلُ أَبُوهُمْ׃ «إِنْ كَانَ هَكَذَا فَافْعَلُوا هَذَا׃ خُذُوا مِنْ أَفْخَرِ جَنَى الْأَرْضِ فِي أَوْعِيَتِكُمْ، وَأَنْزِلُوا لِلرَّجُلِ هَدِيَّةً. قَلِيلًا مِنَ الْبَلَسَانِ، وَقَلِيلًا مِنَ الْعَسَلِ، وَكَثِيرَاءَ وَلَاذَنًا وَفُسْتُقًا وَلَوْزًا.', 'تكوين 43:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 12, 'وَخُذُوا فِضَّةً أُخْرَى فِي أَيَادِيكُمْ. وَالْفِضَّةَ الْمَرْدُودَةَ فِي أَفْوَاهِ عِدَالِكُمْ رُدُّوهَا فِي أَيَادِيكُمْ، لَعَلَّهُ كَانَ سَهْوًا.', 'تكوين 43:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 13, 'وَخُذُوا أَخَاكُمْ وَقُومُوا ارْجِعُوا إِلَى الرَّجُلِ.', 'تكوين 43:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 14, 'وَاللهُ الْقَدِيرُ يُعْطِيكُمْ رَحْمَةً أَمَامَ الرَّجُلِ حَتَّى يُطْلِقَ لَكُمْ أَخَاكُمُ الْآخَرَ وَبَنْيَامِينَ. وَأَنَا إِذَا عَدِمْتُ الْأَوْلَادَ عَدِمْتُهُمْ».', 'تكوين 43:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 15, 'فَأَخَذَ الرِّجَالُ هَذِهِ الْهَدِيَّةَ، وَأَخَذُوا ضِعْفَ الْفِضَّةِ فِي أَيَادِيهِمْ، وَبَنْيَامِينَ، وَقَامُوا وَنَزَلُوا إِلَى مِصْرَ وَوَقَفُوا أَمَامَ يُوسُفَ.', 'تكوين 43:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 16, 'فَلَمَّا رَأَى يُوسُفُ بَنْيَامِينَ مَعَهُمْ، قَالَ لِلَّذِي عَلَى بَيْتِهِ׃ «أَدْخِلِ الرِّجَالَ إِلَى الْبَيْتِ وَاذْبَحْ ذَبِيحَةً وَهَيِّئْ، لِأَنَّ الرِّجَالَ يَأْكُلُونَ مَعِي عِنْدَ الظُّهْرِ».', 'تكوين 43:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 17, 'فَفَعَلَ الرَّجُلُ كَمَا قَالَ يُوسُفُ. وَأَدْخَلَ الرَّجُلُ الرِّجَالَ إِلَى بَيْتِ يُوسُفَ.', 'تكوين 43:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 18, 'فَخَافَ الرِّجَالُ إِذْ أُدْخِلُوا إِلَى بَيْتِ يُوسُفَ، وَقَالُوا׃ «لِسَبَبِ الْفِضَّةِ الَّتِي رَجَعَتْ أَوَّلًا فِي عِدَالِنَا نَحْنُ قَدْ أُدْخِلْنَا لِيَهْجِمَ عَلَيْنَا وَيَقَعَ بِنَا وَيَأْخُذَنَا عَبِيدًا وَحَمِيرَنَا».', 'تكوين 43:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 19, 'فَتَقَدَّمُوا إِلَى الرَّجُلِ الَّذِي عَلَى بَيْتِ يُوسُفَ، وَكَلَّمُوهُ فِي بَابِ الْبَيْتِ', 'تكوين 43:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 20, 'وَقَالُوا׃ «اسْتَمِعْ يَا سَيِّدِي، إِنَّنَا قَدْ نَزَلْنَا أَوَّلًا لِنَشْتَرِيَ طَعَامًا.', 'تكوين 43:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 21, 'وَكَانَ لَمَّا أَتَيْنَا إِلَى الْمَنْزِلِ أَنَّنَا فَتَحْنَا عِدَالَنَا، وَإِذَا فِضَّةُ كُلِّ وَاحِدٍ فِي فَمِ عِدْلِهِ. فِضَّتُنَا بِوَزْنِهَا. فَقَدْ رَدَدْنَاهَا فِي أَيَادِينَا.', 'تكوين 43:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 22, 'وَأَنْزَلْنَا فِضَّةً أُخْرَى فِي أَيَادِينَا لِنَشْتَرِيَ طَعَامًا. لَا نَعْلَمُ مَنْ وَضَعَ فِضَّتَنَا فِي عِدَالِنَا».', 'تكوين 43:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 23, 'فَقَالَ׃ «سَلَامٌ لَكُمْ، لَا تَخَافُوا. إِلَهُكُمْ وَإِلَهُ أَبِيكُمْ أَعْطَاكُمْ كَنْزًا فِي عِدَالِكُمْ. فِضَّتُكُمْ وَصَلَتْ إِلَيَّ». ثُمَّ أَخْرَجَ إِلَيْهِمْ شِمْعُونَ.', 'تكوين 43:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 24, 'وَأَدْخَلَ الرَّجُلُ الرِّجَالَ إِلَى بَيْتِ يُوسُفَ وَأَعْطَاهُمْ مَاءً لِيَغْسِلُوا أَرْجُلَهُمْ، وَأَعْطَى عَلِيقًا لِحَمِيرِهِمْ.', 'تكوين 43:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 25, 'وَهَيَّأُوا الْهَدِيَّةَ إِلَى أَنْ يَجِيءَ يُوسُفُ عِنْدَ الظُّهْرِ، لِأَنَّهُمْ سَمِعُوا أَنَّهُمْ هُنَاكَ يَأْكُلُونَ طَعَامًا.', 'تكوين 43:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 26, 'فَلَمَّا جَاءَ يُوسُفُ إِلَى الْبَيْتِ أَحْضَرُوا إِلَيْهِ الْهَدِيَّةَ الَّتِي فِي أَيَادِيهِمْ إِلَى الْبَيْتِ، وَسَجَدُوا لَهُ إِلَى الْأَرْضِ.', 'تكوين 43:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 27, 'فَسَأَلَ عَنْ سَلَامَتِهِمْ، وَقَالَ׃ «أَسَالِمٌ أَبُوكُمُ الشَّيْخُ الَّذِي قُلْتُمْ عَنْهُ؟ أَحَيٌّ هُوَ بَعْدُ؟»', 'تكوين 43:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 28, 'فَقَالُوا׃ «عَبْدُكَ أَبُونَا سَالِمٌ. هُوَ حَيٌّ بَعْدُ». وَخَرُّوا وَسَجَدُوا.', 'تكوين 43:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 29, 'فَرَفَعَ عَيْنَيْهِ وَنَظَرَ بَنْيَامِينَ أَخَاهُ ابْنَ أُمِّهِ، وَقَالَ׃ «أَهَذَا أَخُوكُمُ الصَّغِيرُ الَّذِي قُلْتُمْ لِي عَنْهُ؟» ثُمَّ قَالَ׃ «اللهُ يُنْعِمُ عَلَيْكَ يَا ابْنِي».', 'تكوين 43:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 30, 'وَاسْتَعْجَلَ يُوسُفُ لِأَنَّ أَحْشَاءَهُ حَنَّتْ إِلَى أَخِيهِ وَطَلَبَ مَكَانًا لِيَبْكِيَ، فَدَخَلَ الْمَخْدَعَ وَبَكَى هُنَاكَ.', 'تكوين 43:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 31, 'ثُمَّ غَسَلَ وَجْهَهُ وَخَرَجَ وَتَجَلَّدَ، وَقَالَ׃ «قَدِّمُوا طَعَامًا».', 'تكوين 43:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 32, 'فَقَدَّمُوا لَهُ وَحْدَهُ، وَلَهُمْ وَحْدَهُمْ، وَلِلْمِصْرِيِّينَ الْآكِلِينَ عِنْدَهُ وَحْدَهُمْ، لِأَنَّ الْمِصْرِيِّينَ لَا يَقْدِرُونَ أَنْ يَأْكُلُوا طَعَامًا مَعَ الْعِبْرَانِيِّينَ، لِأَنَّهُ رِجْسٌ عِنْدَ الْمِصْرِيِّينَ.', 'تكوين 43:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 33, 'فَجَلَسُوا قُدَّامَهُ׃ الْبِكْرُ بِحَسَبِ بَكُورِيَّتِهِ، وَالصَّغِيرُ بِحَسَبِ صِغَرِهِ، فَبُهِتَ الرِّجَالُ بَعْضُهُمْ إِلَى بَعْضٍ.', 'تكوين 43:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 43, 34, 'وَرَفَعَ حِصَصًا مِنْ قُدَّامِهِ إِلَيْهِمْ، فَكَانَتْ حِصَّةُ بَنْيَامِينَ أَكْثَرَ مِنْ حِصَصِ جَمِيعِهِمْ خَمْسَةَ أَضْعَافٍ. وَشَرِبُوا وَرَوُوا مَعَهُ.', 'تكوين 43:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 1, 'ثُمَّ أَمَرَ الَّذِي عَلَى بَيْتِهِ قَائِلًا׃ «امْلَأْ عِدَالَ الرِّجَالِ طَعَامًا حَسَبَ مَا يُطِيقُونَ حِمْلَهُ، وَضَعْ فِضَّةَ كُلِّ وَاحِدٍ فِي فَمِ عِدْلِهِ.', 'تكوين 44:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 2, 'وَطَاسِي، طَاسَ الْفِضَّةِ، تَضَعُ فِي فَمِ عِدْلِ الصَّغِيرِ، وَثَمَنَ قَمْحِهِ». فَفَعَلَ بِحَسَبِ كَلَامِ يُوسُفَ الَّذِي تَكَلَّمَ بِهِ.', 'تكوين 44:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 3, 'فَلَمَّا أَضَاءَ الصُّبْحُ انْصَرَفَ الرِّجَالُ هُمْ وَحَمِيرُهُمْ.', 'تكوين 44:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 4, 'وَلَمَّا كَانُوا قَدْ خَرَجُوا مِنَ الْمَدِينَةِ وَلَمْ يَبْتَعِدُوا، قَالَ يُوسُفُ لِلَّذِي عَلَى بَيْتِهِ׃ «قُمِ اسْعَ وَرَاءَ الرِّجَالِ، وَمَتَى أَدْرَكْتَهُمْ فَقُلْ لَهُمْ׃ لِمَاذَا جَازَيْتُمْ شَرًّا عِوَضًا عَنْ خَيْرٍ؟', 'تكوين 44:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 5, 'أَلَيْسَ هَذَا هُوَ الَّذِي يَشْرَبُ سَيِّدِي فِيهِ؟ وَهُوَ يَتَفَاءَلُ بِهِ. أَسَأْتُمْ فِي مَا صَنَعْتُمْ».', 'تكوين 44:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 6, 'فَأَدْرَكَهُمْ وَقَالَ لَهُمْ هَذَا الْكَلَامَ.', 'تكوين 44:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 7, 'فَقَالُوا لَهُ׃ «لِمَاذَا يَتَكَلَّمُ سَيِّدِي مِثْلَ هَذَا الْكَلَامِ؟ حَاشَا لِعَبِيدِكَ أَنْ يَفْعَلُوا مِثْلَ هَذَا الْأَمْرِ!', 'تكوين 44:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 8, 'هُوَذَا الْفِضَّةُ الَّتِي وَجَدْنَا فِي أَفْوَاهِ عِدَالِنَا رَدَدْنَاهَا إِلَيْكَ مِنْ أَرْضِ كَنْعَانَ. فَكَيْفَ نَسْرِقُ مِنْ بَيْتِ سَيِّدِكَ فِضَّةً أَوْ ذَهَبًا؟', 'تكوين 44:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 9, 'الَّذِي يُوجَدُ مَعَهُ مِنْ عَبِيدِكَ يَمُوتُ، وَنَحْنُ أَيْضًا نَكُونُ عَبِيدًا لِسَيِّدِي».', 'تكوين 44:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 10, 'فَقَالَ׃ «نَعَمِ، الْآنَ بِحَسَبِ كَلَامِكُمْ هَكَذَا يَكُونُ. الَّذِي يُوجَدُ مَعَهُ يَكُونُ لِي عَبْدًا، وَأَمَّا أَنْتُمْ فَتَكُونُونَ أَبْرِيَاءَ».', 'تكوين 44:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 11, 'فَاسْتَعْجَلُوا وَأَنْزَلُوا كُلُّ وَاحِدٍ عِدْلَهُ إِلَى الْأَرْضِ، وَفَتَحُوا كُلُّ وَاحِدٍ عِدْلَهُ.', 'تكوين 44:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 12, 'فَفَتَّشَ مُبْتَدِئًا مِنَ الْكَبِيرِ حَتَّى انْتَهَى إِلَى الصَّغِيرِ، فَوُجِدَ الطَّاسُ فِي عِدْلِ بَنْيَامِينَ.', 'تكوين 44:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 13, 'فَمَزَّقُوا ثِيَابَهُمْ وَحَمَّلَ كُلُّ وَاحِدٍ عَلَى حِمَارِهِ وَرَجَعُوا إِلَى الْمَدِينَةِ.', 'تكوين 44:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 14, 'فَدَخَلَ يَهُوذَا وَإِخْوَتُهُ إِلَى بَيْتِ يُوسُفَ وَهُوَ بَعْدُ هُنَاكَ، وَوَقَعُوا أَمَامَهُ عَلَى الْأَرْضِ.', 'تكوين 44:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 15, 'فَقَالَ لَهُمْ يُوسُفُ׃ «مَا هَذَا الْفِعْلُ الَّذِي فَعَلْتُمْ؟ أَلَمْ تَعْلَمُوا أَنَّ رَجُلًا مِثْلِي يَتَفَاءَلُ؟»', 'تكوين 44:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 16, 'فَقَالَ يَهُوذَا׃ «مَاذَا نَقُولُ لِسَيِّدِي؟ مَاذَا نَتَكَلَّمُ؟ وَبِمَاذَا نَتَبَرَّرُ؟ اللهُ قَدْ وَجَدَ إِثْمَ عَبِيدِكَ. هَا نَحْنُ عَبِيدٌ لِسَيِّدِي، نَحْنُ وَالَّذِي وُجِدَ الطَّاسُ فِي يَدِهِ جَمِيعًا».', 'تكوين 44:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 17, 'فَقَالَ׃ «حَاشَا لِي أَنْ أَفْعَلَ هَذَا! الرَّجُلُ الَّذِي وُجِدَ الطَّاسُ فِي يَدِهِ هُوَ يَكُونُ لِي عَبْدًا، وَأَمَّا أَنْتُمْ فَاصْعَدُوا بِسَلَامٍ إِلَى أَبِيكُمْ».', 'تكوين 44:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 18, 'ثُمَّ تَقَدَّمَ إِلَيْهِ يَهُوذَا وَقَالَ׃ «اسْتَمِعْ يَا سَيِّدِي. لِيَتَكَلَّمْ عَبْدُكَ كَلِمَةً فِي أُذُنَيْ سَيِّدِي وَلَا يَحْمَ غَضَبُكَ عَلَى عَبْدِكَ، لِأَنَّكَ مِثْلُ فِرْعَوْنَ.', 'تكوين 44:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 19, 'سَيِّدِي سَأَلَ عَبِيدَهُ قَائِلًا׃ هَلْ لَكُمْ أَبٌ أَوْ أَخٌ؟', 'تكوين 44:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 20, 'فَقُلْنَا لِسَيِّدِي׃ لَنَا أَبٌ شَيْخٌ، وَابْنُ شَيْخُوخَةٍ صَغِيرٌ، مَاتَ أَخُوهُ وَبَقِيَ هُوَ وَحْدَهُ لِأُمِّهِ، وَأَبُوهُ يُحِبُّهُ.', 'تكوين 44:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 21, 'فَقُلْتَ لِعَبِيدِكَ׃ انْزِلُوا بِهِ إِلَيَّ فَأَجْعَلَ نَظَرِي عَلَيْهِ.', 'تكوين 44:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 22, 'فَقُلْنَا لِسَيِّدِي׃ لَا يَقْدِرُ الْغُلَامُ أَنْ يَتْرُكَ أَبَاهُ، وَإِنْ تَرَكَ أَبَاهُ يَمُوتُ.', 'تكوين 44:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 23, 'فَقُلْتَ لِعَبِيدِكَ׃ إِنْ لَمْ يَنْزِلْ أَخُوكُمُ الصَّغِيرُ مَعَكُمْ لَا تَعُودُوا تَنْظُرُونَ وَجْهِي.', 'تكوين 44:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 24, 'فَكَانَ لَمَّا صَعِدْنَا إِلَى عَبْدِكَ أَبِي أَنَّنَا أَخْبَرْنَاهُ بِكَلَامِ سَيِّدِي.', 'تكوين 44:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 25, 'ثُمَّ قَالَ أَبُونَا׃ ارْجِعُوا اشْتَرُوا لَنَا قَلِيلًا مِنَ الطَّعَامِ.', 'تكوين 44:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 26, 'فَقُلْنَا׃ لَا نَقْدِرُ أَنْ نَنْزِلَ، وَإِنَّمَا إِذَا كَانَ أَخُونَا الصَّغِيرُ مَعَنَا نَنْزِلُ، لِأَنَّنَا لَا نَقْدِرُ أَنْ نَنْظُرَ وَجْهَ الرَّجُلِ وَأَخُونَا الصَّغِيرُ لَيْسَ مَعَنَا.', 'تكوين 44:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 27, 'فَقَالَ لَنَا عَبْدُكَ أَبِي׃ أَنْتُمْ تَعْلَمُونَ أَنَّ امْرَأَتِي وَلَدَتْ لِي اثْنَيْنِ،', 'تكوين 44:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 28, 'فَخَرَجَ الْوَاحِدُ مِنْ عِنْدِي، وَقُلْتُ׃ إِنَّمَا هُوَ قَدِ افْتُرِسَ افْتِرَاسًا، وَلَمْ أَنْظُرْهُ إِلَى الْآنَ.', 'تكوين 44:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 29, 'فَإِذَا أَخَذْتُمْ هَذَا أَيْضًا مِنْ أَمَامِ وَجْهِي وَأَصَابَتْهُ أَذِيَّةٌ، تُنْزِلُونَ شَيْبَتِي بِشَرٍّ إِلَى الْهَاوِيَةِ.', 'تكوين 44:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 30, 'فَالْآنَ مَتَى جِئْتُ إِلَى عَبْدِكَ أَبِي، وَالْغُلَامُ لَيْسَ مَعَنَا، وَنَفْسُهُ مُرْتَبِطَةٌ بِنَفْسِهِ،', 'تكوين 44:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 31, 'يَكُونُ مَتَى رَأَى أَنَّ الْغُلَامَ مَفْقُودٌ، أَنَّهُ يَمُوتُ، فَيُنْزِلُ عَبِيدُكَ شَيْبَةَ عَبْدِكَ أَبِينَا بِحُزْنٍ إِلَى الْهَاوِيَةِ،', 'تكوين 44:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 32, 'لِأَنَّ عَبْدَكَ ضَمِنَ الْغُلَامَ لِأَبِي قَائِلًا׃ إِنْ لَمْ أَجِئْ بِهِ إِلَيْكَ أَصِرْ مُذْنِبًا إِلَى أَبِي كُلَّ الْأَيَّامِ.', 'تكوين 44:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 33, 'فَالْآنَ لِيَمْكُثْ عَبْدُكَ عِوَضًا عَنِ الْغُلَامِ، عَبْدًا لِسَيِّدِي، وَيَصْعَدِ الْغُلَامُ مَعَ إِخْوَتِهِ.', 'تكوين 44:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 44, 34, 'لِأَنِّي كَيْفَ أَصْعَدُ إِلَى أَبِي وَالْغُلَامُ لَيْسَ مَعِي؟ لِئَلَّا أَنْظُرَ الشَّرَّ الَّذِي يُصِيبُ أَبِي».', 'تكوين 44:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 1, 'فَلَمْ يَسْتَطِعْ يُوسُفُ أَنْ يَضْبِطَ نَفْسَهُ لَدَى جَمِيعِ الْوَاقِفِينَ عِنْدَهُ فَصَرَخَ׃ «أَخْرِجُوا كُلَّ إِنْسَانٍ عَنِّي». فَلَمْ يَقِفْ أَحَدٌ عِنْدَهُ حِينَ عَرَّفَ يُوسُفُ إِخْوَتَهُ بِنَفْسِهِ.', 'تكوين 45:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 2, 'فَأَطْلَقَ صَوْتَهُ بِالْبُكَاءِ، فَسَمِعَ الْمِصْرِيُّونَ وَسَمِعَ بَيْتُ فِرْعَوْنَ.', 'تكوين 45:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 3, 'وَقَالَ يُوسُفُ لِإِخْوَتِهِ׃ «أَنَا يُوسُفُ. أَحَيٌّ أَبِي بَعْدُ؟» فَلَمْ يَسْتَطِعْ إِخْوَتُهُ أَنْ يُجِيبُوهُ، لِأَنَّهُمُ ارْتَاعُوا مِنْهُ.', 'تكوين 45:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 4, 'فَقَالَ يُوسُفُ لِإِخْوَتِهِ׃ «تَقَدَّمُوا إِلَيَّ». فَتَقَدَّمُوا. فَقَالَ׃ «أَنَا يُوسُفُ أَخُوكُمُ الَّذِي بِعْتُمُوهُ إِلَى مِصْرَ.', 'تكوين 45:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 5, 'وَالْآنَ لَا تَتَأَسَّفُوا وَلَا تَغْتَاظُوا لِأَنَّكُمْ بِعْتُمُونِي إِلَى هُنَا، لِأَنَّهُ لِاسْتِبْقَاءِ حَيَاةٍ أَرْسَلَنِيَ اللهُ قُدَّامَكُمْ.', 'تكوين 45:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 6, 'لِأَنَّ لِلْجُوعِ فِي الْأَرْضِ الْآنَ سَنَتَيْنِ. وَخَمْسُ سِنِينَ أَيْضًا لَا تَكُونُ فِيهَا فَلَاحَةٌ وَلَا حَصَادٌ.', 'تكوين 45:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 7, 'فَقَدْ أَرْسَلَنِي اللهُ قُدَّامَكُمْ لِيَجْعَلَ لَكُمْ بَقِيَّةً فِي الْأَرْضِ وَلِيَسْتَبْقِيَ لَكُمْ نَجَاةً عَظِيمَةً.', 'تكوين 45:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 8, 'فَالْآنَ لَيْسَ أَنْتُمْ أَرْسَلْتُمُونِي إِلَى هُنَا بَلِ اللهُ. وَهُوَ قَدْ جَعَلَنِي أَبًا لِفِرْعَوْنَ وَسَيِّدًا لِكُلِّ بَيْتِهِ وَمُتَسَلِّطًا عَلَى كُلِّ أَرْضِ مِصْرَ.', 'تكوين 45:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 9, 'أَسْرِعُوا وَاصْعَدُوا إِلَى أَبِي وَقُولُوا لَهُ׃ هَكَذَا يَقُولُ ابْنُكَ يُوسُفُ׃ قَدْ جَعَلَنِيَ اللهُ سَيِّدًا لِكُلِّ مِصْرَ. اِنْزِلْ إِلَيَّ. لَا تَقِفْ.', 'تكوين 45:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 10, 'فَتَسْكُنَ فِي أَرْضِ جَاسَانَ وَتَكُونَ قَرِيبًا مِنِّي، أَنْتَ وَبَنُوكَ وَبَنُو بَنِيكَ وَغَنَمُكَ وَبَقَرُكَ وَكُلُّ مَا لَكَ.', 'تكوين 45:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 11, 'وَأَعُولُكَ هُنَاكَ، لِأَنَّهُ يَكُونُ أَيْضًا خَمْسُ سِنِينَ جُوعًا. لِئَلَّا تَفْتَقِرَ أَنْتَ وَبَيْتُكَ وَكُلُّ مَا لَكَ.', 'تكوين 45:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 12, 'وَهُوَذَا عْيُونُكُمْ تَرَى، وَعَيْنَا أَخِي بَنْيَامِينَ، أَنَّ فَمِي هُوَ الَّذِي يُكَلِّمُكُمْ.', 'تكوين 45:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 13, 'وَتُخْبِرُونَ أَبِي بِكُلِّ مَجْدِي فِي مِصْرَ وَبِكُلِّ مَا رَأَيْتُمْ، وَتَسْتَعْجِلُونَ وَتَنْزِلُونَ بِأَبِي إِلَى هُنَا».', 'تكوين 45:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 14, 'ثُمَّ وَقَعَ عَلَى عُنُقِ بَنْيَامِينَ أَخِيهِ وَبَكَى، وَبَكَى بَنْيَامِينُ عَلَى عُنُقِهِ.', 'تكوين 45:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 15, 'وَقَبَّلَ جَمِيعَ إِخْوَتِهِ وَبَكَى عَلَيْهِمْ. وَبَعْدَ ذَلِكَ تَكَلَّمَ إِخْوَتُهُ مَعَهُ.', 'تكوين 45:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 16, 'وَسُمِعَ الْخَبَرُ فِي بَيْتِ فِرْعَوْنَ، وَقِيلَ׃ «جَاءَ إِخْوَةُ يُوسُفَ». فَحَسُنَ فِي عَيْنَيْ فِرْعَوْنَ وَفِي عُيُونِ عَبِيدِهِ.', 'تكوين 45:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 17, 'فَقَالَ فِرْعَوْنُ لِيُوسُفَ׃ «قُلْ لِإِخْوَتِكَ׃ افْعَلُوا هَذَا׃ حَمِّلُوا دَوَابَّكُمْ وَانْطَلِقُوا، اذْهَبُوا إِلَى أَرْضِ كَنْعَانَ.', 'تكوين 45:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 18, 'وَخُذُوا أَبَاكُمْ وَبُيُوتَكُمْ وَتَعَالَوْا إِلَيَّ، فَأُعْطِيَكُمْ خَيْرَاتِ أَرْضِ مِصْرَ وَتَأْكُلُوا دَسَمَ الْأَرْضِ.', 'تكوين 45:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 19, 'فَأَنْتَ قَدْ أُمِرْتَ، افْعَلُوا هَذَا׃ خُذُوا لَكُمْ مِنْ أَرْضِ مِصْرَ عَجَلَاتٍ لِأَوْلَادِكُمْ وَنِسَائِكُمْ، وَاحْمِلُوا أَبَاكُمْ وَتَعَالَوْا.', 'تكوين 45:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 20, 'وَلَا تَحْزَنْ عُيُونُكُمْ عَلَى أَثَاثِكُمْ، لِأَنَّ خَيْرَاتِ جَمِيعِ أَرْضِ مِصْرَ لَكُمْ».', 'تكوين 45:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 21, 'فَفَعَلَ بَنُو إِسْرَائِيلَ هَكَذَا. وَأَعْطَاهُمْ يُوسُفُ عَجَلَاتٍ بِحَسَبِ أَمْرِ فِرْعَوْنَ، وَأَعْطَاهُمْ زَادًا لِلطَّرِيقِ.', 'تكوين 45:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 22, 'وَأَعْطَى كُلَّ وَاحِدٍ مِنْهُمْ حُلَلَ ثِيَابٍ، وَأَمَّا بَنْيَامِينُ فَأَعْطَاهُ ثَلَاثَ مِئَةٍ مِنَ الْفِضَّةِ وَخَمْسَ حُلَلِ ثِيَابٍ.', 'تكوين 45:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 23, 'وَأَرْسَلَ لِأَبِيهِ هَكَذَا׃ عَشْرَةَ حَمِيرٍ حَامِلَةً مِنْ خَيْرَاتِ مِصْرَ، وَعَشَرَ أُتُنٍ حَامِلَةً حِنْطَةً، وَخُبْزًا وَطَعَامًا لِأَبِيهِ لِأَجْلِ الطَّرِيقِ.', 'تكوين 45:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 24, 'ثُمَّ صَرَفَ إِخْوَتَهُ فَانْطَلَقُوا، وَقَالَ لَهُمْ׃ «لَا تَتَغَاضَبُوا فِي الطَّرِيقِ».', 'تكوين 45:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 25, 'فَصَعِدُوا مِنْ مِصْرَ وَجَاءُوا إِلَى أَرْضِ كَنْعَانَ، إِلَى يَعْقُوبَ أَبِيهِمْ.', 'تكوين 45:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 26, 'وَأَخْبَرُوهُ قَائِلِينَ׃ «يُوسُفُ حَيٌّ بَعْدُ، وَهُوَ مُتَسَلِّطٌ عَلَى كُلِّ أَرْضِ مِصْرَ». فَجَمَدَ قَلْبُهُ لِأَنَّهُ لَمْ يُصَدِّقْهُمْ.', 'تكوين 45:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 27, 'ثُمَّ كَلَّمُوهُ بِكُلِّ كَلَامِ يُوسُفَ الَّذِي كَلَّمَهُمْ بِهِ، وَأَبْصَرَ الْعَجَلَاتِ الَّتِي أَرْسَلَهَا يُوسُفُ لِتَحْمِلَهُ. فَعَاشَتْ رُوحُ يَعْقُوبَ أَبِيهِمْ.', 'تكوين 45:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 45, 28, 'فَقَالَ إِسْرَائِيلُ׃ «كَفَى! يُوسُفُ ابْنِي حَيٌّ بَعْدُ. أَذْهَبُ وَأَرَاهُ قَبْلَ أَنْ أَمُوتَ».', 'تكوين 45:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 1, 'فَارْتَحَلَ إِسْرَائِيلُ وَكُلُّ مَا كَانَ لَهُ وَأَتَى إِلَى بِئْرِ سَبْعٍ، وَذَبَحَ ذَبَائِحَ لإِلَهِ أَبِيهِ إِسْحَاقَ.', 'تكوين 46:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 2, 'فَكَلَّمَ اللهُ إِسْرَائِيلَ فِي رُؤَى اللَّيْلِ وَقَالَ׃ «يَعْقُوبُ، يَعْقُوبُ!». فَقَالَ׃ «هَأَنَذَا».', 'تكوين 46:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 3, 'فَقَالَ׃ «أَنَا اللهُ، إِلَهُ أَبِيكَ. لَا تَخَفْ مِنَ النُّزُولِ إِلَى مِصْرَ، لِأَنِّي أَجْعَلُكَ أُمَّةً عَظِيمَةً هُنَاكَ.', 'تكوين 46:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 4, 'أَنَا أَنْزِلُ مَعَكَ إِلَى مِصْرَ، وَأَنَا أُصْعِدُكَ أَيْضًا. وَيَضَعُ يُوسُفُ يَدَهُ عَلَى عَيْنَيْكَ».', 'تكوين 46:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 5, 'فَقَامَ يَعْقُوبُ مِنْ بِئْرِ سَبْعٍ، وَحَمَلَ بَنُو إِسْرَائِيلَ يَعْقُوبَ أَبَاهُمْ وَأَوْلَادَهُمْ وَنِسَاءَهُمْ فِي الْعَجَلَاتِ الَّتِي أَرْسَلَ فِرْعَوْنُ لِحَمْلِهِ.', 'تكوين 46:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 6, 'وَأَخَذُوا مَوَاشِيَهُمْ وَمُقْتَنَاهُمُ الَّذِي اقْتَنَوْا فِي أَرْضِ كَنْعَانَ، وَجَاءُوا إِلَى مِصْرَ. يَعْقُوبُ وَكُلُّ نَسْلِهِ مَعَهُ.', 'تكوين 46:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 7, 'بَنُوهُ وَبَنُو بَنِيهِ مَعَهُ، وَبَنَاتُهُ وَبَنَاتُ بَنِيهِ وَكُلُّ نَسْلِهِ، جَاءَ بِهِمْ مَعَهُ إِلَى مِصْرَ.', 'تكوين 46:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 8, 'وَهَذِهِ أَسْمَاءُ بَنِي إِسْرَائِيلَ الَّذِينَ جَاءُوا إِلَى مِصْرَ׃ يَعْقُوبُ وَبَنُوهُ. بِكْرُ يَعْقُوبَ رَأُوبَيْنُ.', 'تكوين 46:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 9, 'وَبَنُو رَأُوبَيْنَ׃ حَنُوكُ وَفَلُّو وَحَصْرُونُ وَكَرْمِي.', 'تكوين 46:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 10, 'وَبَنُو شِمْعُونَ׃ يَمُوئِيلُ وَيَامِينُ وَأُوهَدُ وَيَاكِينُ وَصُوحَرُ وَشَأُولُ ابْنُ الْكَنْعَانِيَّةِ.', 'تكوين 46:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 11, 'وَبَنُو لَاوِي׃ جِرْشُونُ وَقَهَاتُ وَمَرَارِي.', 'تكوين 46:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 12, 'وَبَنُو يَهُوذَا׃ عِيرٌ وَأُونَانُ وَشِيلَةُ وَفَارَصُ وَزَارَحُ. وَأَمَّا عِيرٌ وَأُونَانُ فَمَاتَا فِي أَرْضِ كَنْعَانَ. وَكَانَ ابْنَا فَارَصَ׃ حَصْرُونَ وَحَامُولَ.', 'تكوين 46:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 13, 'وَبَنُو يَسَّاكَرَ׃ تُولَاعُ وَفَوَّةُ وَيُوبُ وَشِمْرُونُ.', 'تكوين 46:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 14, 'وَبَنُو زَبُولُونَ׃ سَارَدُ وَإِيلُونُ وَيَاحَلْئِيلُ.', 'تكوين 46:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 15, 'هَؤُلَاءِ بَنُو لَيْئَةَ الَّذِينَ وَلَدَتْهُمْ لِيَعْقُوبَ فِي فَدَّانَ أَرَامَ مَعَ دِينَةَ ابْنَتِهِ. جَمِيعُ نُفُوسِ بَنِيهِ وَبَنَاتِهِ ثَلَاثٌ وَثَلَاثُونَ.', 'تكوين 46:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 16, 'وَبَنُو جَادَ׃ صِفْيُونُ وَحَجِّي وَشُونِي وَأَصْبُونُ وَعِيرِي وَأَرُودِي وَأَرْئِيلِي.', 'تكوين 46:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 17, 'وَبَنُو أَشِيرَ׃ يِمْنَةُ وَيِشْوَةُ وَيِشْوِي وَبَرِيعَةُ، وَسَارَحُ هِيَ أُخْتُهُمْ. وَابْنَا بَرِيعَةَ׃ حَابِرُ وَمَلْكِيئِيلُ.', 'تكوين 46:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 18, 'هَؤُلَاءِ بَنُو زِلْفَةَ الَّتِي أَعْطَاهَا لَابَانُ لِلَيْئَةَ ابْنَتِهِ، فَوَلَدَتْ هَؤُلَاءِ لِيَعْقُوبَ، سِتَّ عَشَرَةَ نَفْسًا.', 'تكوين 46:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 19, 'اِبْنَا رَاحِيلَ امْرَأَةِ يَعْقُوبَ׃ يُوسُفُ وَبَنْيَامِينُ.', 'تكوين 46:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 20, 'وَوُلِدَ لِيُوسُفَ فِي أَرْضِ مِصْرَ׃ مَنَسَّى وَأَفْرَايِمُ، اللَّذَانِ وَلَدَتْهُمَا لَهُ أَسْنَاتُ بِنْتُ فُوطِي فَارَعَ كَاهِنِ أُونٍ.', 'تكوين 46:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 21, 'وَبَنُو بَنْيَامِينَ׃ بَالَعُ وَبَاكَرُ وَأَشْبِيلُ وَجِيرَا وَنَعْمَانُ وَإِيحِي وَرُوشُ وَمُفِّيمُ وَحُفِّيمُ وَأَرْدُ.', 'تكوين 46:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 22, 'هَؤُلَاءِ بَنُو رَاحِيلَ الَّذِينَ وُلِدُوا لِيَعْقُوبَ. جَمِيعُ النُّفُوسِ أَرْبَعَ عَشَرَةَ.', 'تكوين 46:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 23, 'وَابْنُ دَانَ׃ حُوشِيمُ.', 'تكوين 46:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 24, 'وَبَنُو نَفْتَالِي׃ يَاحَصْئِيلُ وَجُونِي وَيِصْرُ وَشِلِّيمُ.', 'تكوين 46:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 25, 'هَؤُلَاءِ بَنُو بِلْهَةَ الَّتِي أَعْطَاهَا لَابَانُ لِرَاحِيلَ ابْنَتِهِ. فَوَلَدَتْ هَؤُلَاءِ لِيَعْقُوبَ. جَمِيعُ الْأَنْفُسِ سَبْعٌ.', 'تكوين 46:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 26, 'جَمِيعُ النُّفُوسِ لِيَعْقُوبَ الَّتِي أَتَتْ إِلَى مِصْرَ، الْخَارِجَةِ مِنْ صُلْبِهِ، مَا عَدَا نِسَاءَ بَنِي يَعْقُوبَ، جَمِيعُ النُّفُوسِ سِتٌّ وَسِتُّونَ نَفْسًا.', 'تكوين 46:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 27, 'وَابْنَا يُوسُفَ اللَّذَانِ وُلِدَا لَهُ فِي مِصْرَ نَفْسَانِ. جَمِيعُ نُفُوسِ بَيْتِ يَعْقُوبَ الَّتِي جَاءَتْ إِلَى مِصْرَ سَبْعُونَ.', 'تكوين 46:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 28, 'فَأَرْسَلَ يَهُوذَا أَمَامَهُ إِلَى يُوسُفَ لِيُرِيَ الطَّرِيقَ أَمَامَهُ إِلَى جَاسَانَ، ثُمَّ جَاءُوا إِلَى أَرْضِ جَاسَانَ.', 'تكوين 46:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 29, 'فَشَدَّ يُوسُفُ مَرْكَبَتَهُ وَصَعِدَ لِاسْتِقْبَالِ إِسْرَائِيلَ أَبِيهِ إِلَى جَاسَانَ. وَلَمَّا ظَهَرَ لَهُ وَقَعَ عَلَى عُنُقِهِ وَبَكَى عَلَى عُنُقِهِ زَمَانًا.', 'تكوين 46:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 30, 'فَقَالَ إِسْرَائِيلُ لِيُوسُفَ׃ «أَمُوتُ الْآنَ بَعْدَ مَا رَأَيْتُ وَجْهَكَ أَنَّكَ حَيٌّ بَعْدُ».', 'تكوين 46:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 31, 'ثُمَّ قَالَ يُوسُفُ لِإِخْوَتِهِ وَلِبَيْتِ أَبِيهِ׃ «أَصْعَدُ وَأُخْبِرُ فِرْعَوْنَ وَأَقُولُ لَهُ׃ إِخْوَتِي وَبَيْتُ أَبِي الَّذِينَ فِي أَرْضِ كَنْعَانَ جَاءُوا إِلَيَّ.', 'تكوين 46:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 32, 'وَالرِّجَالُ رُعَاةُ غَنَمٍ، فَإِنَّهُمْ كَانُوا أَهْلَ مَوَاشٍ، وَقَدْ جَاءُوا بِغَنَمِهِمْ وَبَقَرِهِمْ وَكُلِّ مَا لَهُمْ.', 'تكوين 46:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 33, 'فَيَكُونُ إِذَا دَعَاكُمْ فِرْعَوْنُ وَقَالَ׃ مَا صِنَاعَتُكُمْ؟', 'تكوين 46:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 46, 34, 'أَنْ تَقُولُوا׃ عَبِيدُكَ أَهْلُ مَوَاشٍ مُنْذُ صِبَانَا إِلَى الْآنَ، نَحْنُ وَآبَاؤُنَا جَمِيعًا. لِكَيْ تَسْكُنُوا فِي أَرْضِ جَاسَانَ. لِأَنَّ كُلَّ رَاعِي غَنَمٍ رِجْسٌ لِلْمِصْرِيِّينَ».', 'تكوين 46:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 1, 'فَأَتَى يُوسُفُ وَأَخبَرَ فِرْعَوْنَ وَقَالَ׃ «أَبِي وَإِخْوَتِي وَغَنَمُهُمْ وَبَقَرُهُمْ وَكُلُّ مَا لَهُمْ جَاءُوا مِنْ أَرْضِ كَنْعَانَ، وَهُوَذَا هُمْ فِي أَرْضِ جَاسَانَ».', 'تكوين 47:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 2, 'وَأَخَذَ مِنْ جُمْلَةِ إِخْوَتِهِ خَمْسَةَ رِجَالٍ وَأَوْقَفَهُمْ أَمَامَ فِرْعَوْنَ.', 'تكوين 47:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 3, 'فَقَالَ فِرْعَوْنُ لِإِخْوَتِهِ׃ «مَا صِنَاعَتُكُمْ؟» فَقَالُوا لِفِرْعَوْنَ׃ «عَبِيدُكَ رُعَاةُ غَنَمٍ نَحْنُ وَآبَاؤُنَا جَمِيعًا».', 'تكوين 47:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 4, 'وَقَالُوا لِفِرْعَوْنَ׃ «جِئْنَا لِنَتَغَرَّبَ فِي الْأَرْضِ، إِذْ لَيْسَ لِغَنَمِ عَبِيدِكَ مَرْعًى، لِأَنَّ الْجُوعَ شَدِيدٌ فِي أَرْضِ كَنْعَانَ. فَالْآنَ لِيَسْكُنْ عَبِيدُكَ فِي أَرْضِ جَاسَانَ».', 'تكوين 47:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 5, 'فَكَلَّمَ فِرْعَوْنُ يُوسُفَ قَائِلًا׃ «أَبُوكَ وَإِخْوَتُكَ جَاءُوا إِلَيْكَ.', 'تكوين 47:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 6, 'أَرْضُ مِصْرَ قُدَّامَكَ. فِي أَفْضَلِ الْأَرْضِ أَسْكِنْ أَبَاكَ وَإِخْوَتَكَ، لِيَسْكُنُوا فِي أَرْضِ جَاسَانَ. وَإِنْ عَلِمْتَ أَنَّهُ يُوجَدُ بَيْنَهُمْ ذَوُو قُدْرَةٍ، فَاجْعَلْهُمْ رُؤَسَاءَ مَوَاشٍ عَلَى الَّتِي لِي».', 'تكوين 47:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 7, 'ثُمَّ أَدْخَلَ يُوسُفُ يَعْقُوبَ أَبَاهُ وَأَوْقَفَهُ أَمَامَ فِرْعَوْنَ. وَبَارَكَ يَعْقُوبُ فِرْعَوْنَ.', 'تكوين 47:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 8, 'فَقَالَ فِرْعَوْنُ لِيَعْقُوبَ׃ «كَمْ هِيَ أَيَّامُ سِنِي حَيَاتِكَ؟»', 'تكوين 47:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 9, 'فَقَالَ يَعْقُوبُ لِفِرْعَوْنَ׃ «أَيَّامُ سِنِي غُرْبَتِي مِئَةٌ وَثَلَاثُونَ سَنَةً. قَلِيلَةً وَ رَدِيَّةً كَانَتْ أَيَّامُ سِنِي حَيَاتِي، وَلَمْ تَبْلُغْ إِلَى أَيَّامِ سِنِي حَيَاةِ آبَائِي فِي أَيَّامِ غُرْبَتِهِمْ».', 'تكوين 47:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 10, 'وَبَارَكَ يَعْقُوبُ فِرْعَوْنَ وَخَرَجَ مِنْ لَدُنْ فِرْعَوْنَ.', 'تكوين 47:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 11, 'فَأَسْكَنَ يُوسُفُ أَبَاهُ وَإِخْوَتَهُ وَأَعْطَاهُمْ مُلْكًا فِي أَرْضِ مِصْرَ، فِي أَفْضَلِ الْأَرْضِ، فِي أَرْضِ رَعَمْسِيسَ كَمَا أَمَرَ فِرْعَوْنُ.', 'تكوين 47:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 12, 'وَعَالَ يُوسُفُ أَبَاهُ وَإِخْوَتَهُ وَكُلَّ بَيْتِ أَبِيهِ بِطَعَامٍ عَلَى حَسَبِ الْأَوْلَادِ.', 'تكوين 47:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 13, 'وَلَمْ يَكُنْ خُبْزٌ فِي كُلِّ الْأَرْضِ، لِأَنَّ الْجُوعَ كَانَ شَدِيدًا جِدًّا. فَخَوَّرَتْ أَرْضُ مِصْرَ وَأَرْضُ كَنْعَانَ مِنْ أَجْلِ الْجُوعِ.', 'تكوين 47:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 14, 'فَجَمَعَ يُوسُفُ كُلَّ الْفِضَّةِ الْمَوْجُودَةِ فِي أَرْضِ مِصْرَ وَفِي أَرْضِ كَنْعَانَ بِالْقَمْحِ الَّذِي اشْتَرُوا، وَجَاءَ يُوسُفُ بِالْفِضَّةِ إِلَى بَيْتِ فِرْعَوْنَ.', 'تكوين 47:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 15, 'فَلَمَّا فَرَغَتِ الْفِضَّةُ مِنْ أَرْضِ مِصْرَ وَمِنْ أَرْضِ كَنْعَانَ أَتَى جَمِيعُ الْمِصْرِيِّينَ إِلَى يُوسُفَ قَائِلِينَ׃ «أَعْطِنَا خُبْزًا، فَلِمَاذَا نَمُوتُ قُدَّامَكَ؟ لِأَنْ لَيْسَ فِضَّةٌ أَيْضًا».', 'تكوين 47:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 16, 'فَقَالَ يُوسُفُ׃ «هَاتُوا مَوَاشِيَكُمْ فَأُعْطِيَكُمْ بِمَوَاشِيكُمْ، إِنْ لَمْ يَكُنْ فِضَّةٌ أَيْضًا».', 'تكوين 47:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 17, 'فَجَاءُوا بِمَوَاشِيهِمْ إِلَى يُوسُفَ، فَأَعْطَاهُمْ يُوسُفُ خُبْزًا بِالْخَيْلِ وَبِمَوَاشِي الْغَنَمِ وَالْبَقَرِ وَبِالْحَمِيرِ. فَقَاتَهُمْ بِالْخُبْزِ تِلْكَ السَّنَةَ بَدَلَ جَمِيعِ مَوَاشِيهِمْ.', 'تكوين 47:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 18, 'وَلَمَّا تَمَّتْ تِلْكَ السَّنَةُ أَتَوْا إِلَيْهِ فِي السَّنَةِ الْثَّانِيَةِ وَقَالُوا لَهُ׃ «لَا نُخْفِي عَنْ سَيِّدِي أَنَّهُ إِذْ قَدْ فَرَغَتِ الْفِضَّةُ، وَمَوَاشِي الْبَهَائِمِ عِنْدَ سَيِّدِي، لَمْ يَبْقَ قُدَّامَ سَيِّدِي إِلَا أَجْسَادُنَا وَأَرْضُنَا.', 'تكوين 47:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 19, 'لِمَاذَا نَمُوتُ أَمَامَ عَيْنَيْكَ نَحْنُ وَأَرْضُنَا جَمِيعًا؟ اِشْتَرِنَا وَأَرْضَنَا بِالْخُبْزِ، فَنَصِيرَ نَحْنُ وَأَرْضُنَا عَبِيدًا لِفِرْعَوْنَ، وَأَعْطِ بِذَارًا لِنَحْيَا وَلَا نَمُوتَ وَلَا تَصِيرَ أَرْضُنَا قَفْرًا».', 'تكوين 47:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 20, 'فَاشْتَرَى يُوسُفُ كُلَّ أَرْضِ مِصْرَ لِفِرْعَوْنَ، إِذْ بَاعَ الْمِصْرِيُّونَ كُلُّ وَاحِدٍ حَقْلَهُ، لِأَنَّ الْجُوعَ اشْتَدَّ عَلَيْهِمْ. فَصَارَتِ الْأَرْضُ لِفِرْعَوْنَ.', 'تكوين 47:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 21, 'وَأَمَّا الشَّعْبُ فَنَقَلَهُمْ إِلَى الْمُدُنِ مِنْ أَقْصَى حَدِّ مِصْرَ إِلَى أَقْصَاهُ.', 'تكوين 47:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 22, 'إِلَا إِنَّ أَرْضَ الْكَهَنَةِ لَمْ يَشْتَرِهَا، إِذْ كَانَتْ لِلْكَهَنَةِ فَرِيضَةٌ مِنْ قِبَلِ فِرْعَوْنَ، فَأَكَلُوا فَرِيضَتَهُمُ الَّتِي أَعْطَاهُمْ فِرْعَوْنُ، لِذَلِكَ لَمْ يَبِيعُوا أَرْضَهُمْ.', 'تكوين 47:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 23, 'فَقَالَ يُوسُفُ لِلشَّعْبِ׃ «إِنِّي قَدِ اشْتَرَيْتُكُمُ الْيَوْمَ وَأَرْضَكُمْ لِفِرْعَوْنَ. هُوَذَا لَكُمْ بِذَارٌ فَتَزْرَعُونَ الْأَرْضَ.', 'تكوين 47:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 24, 'وَيَكُونُ عِنْدَ الْغَلَّةِ أَنَّكُمْ تُعْطُونَ خُمْسًا لِفِرْعَوْنَ، وَالْأَرْبَعَةُ الْأَجْزَاءُ تَكُونُ لَكُمْ بِذَارًا لِلْحَقْلِ، وَطَعَامًا لَكُمْ وَلِمَنْ فِي بْيُوتِكُمْ، وَطَعَامًا لِأَوْلَادِكُمْ».', 'تكوين 47:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 25, 'فَقَالُوا׃ «أَحْيَيْتَنَا. لَيْتَنَا نَجِدُ نِعْمَةً فِي عَيْنَيْ سَيِّدِي فَنَكُونَ عَبِيدًا لِفِرْعَوْنَ».', 'تكوين 47:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 26, 'فَجَعَلَهَا يُوسُفُ فَرْضًا عَلَى أَرْضِ مِصْرَ إِلَى هَذَا الْيَوْمِ׃ لِفِرْعَوْنَ الْخُمْسُ. إِلَا إِنَّ أَرْضَ الْكَهَنَةِ وَحْدَهُمْ لَمْ تَصِرْ لِفِرْعَوْنَ.', 'تكوين 47:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 27, 'وَسَكَنَ إِسْرَائِيلُ فِي أَرْضِ مِصْرَ، فِي أَرْضِ جَاسَانَ، وَتَمَلَّكُوا فِيهَا وَأَثْمَرُوا وَكَثُرُوا جِدًّا.', 'تكوين 47:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 28, 'وَعَاشَ يَعْقُوبُ فِي أَرْضِ مِصْرَ سَبْعَ عَشَرَةَ سَنَةً. فَكَانَتْ أَيَّامُ يَعْقُوبَ، سِنُو حَيَاتِهِ مِئَةً وَسَبْعًا وَأَرْبَعِينَ سَنَةً.', 'تكوين 47:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 29, 'وَلَمَّا قَرُبَتْ أَيَّامُ إِسْرَائِيلَ أَنْ يَمُوتَ دَعَا ابْنَهُ يُوسُفَ وَقَالَ لَهُ׃ «إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ فَضَعْ يَدَكَ تَحْتَ فَخْذِي وَاصْنَعْ مَعِي مَعْرُوفًا وَأَمَانَةً׃ لَا تَدْفِنِّي فِي مِصْرَ،', 'تكوين 47:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 30, 'بَلْ أَضْطَجِعُ مَعَ آبَائِي، فَتَحْمِلُنِي مِنْ مِصْرَ وَتَدْفِنُنِي فِي مَقْبَرَتِهِمْ». فَقَالَ׃ «أَنَا أَفْعَلُ بِحَسَبِ قَوْلِكَ».', 'تكوين 47:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 47, 31, 'فَقَالَ׃ «احْلِفْ لِي». فَحَلَفَ لَهُ. فَسَجَدَ إِسْرَائِيلُ عَلَى رَأْسِ السَّرِيرِ.', 'تكوين 47:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 1, 'وَحَدَثَ بَعْدَ هَذِهِ الْأُمُورِ أَنَّهُ قِيلَ لِيُوسُفَ׃ «هُوَذَا أَبُوكَ مَرِيضٌ». فَأَخَذَ مَعَهُ ابْنَيْهِ مَنَسَّى وَأَفْرَايِمَ.', 'تكوين 48:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 2, 'فَأُخْبِرَ يَعْقُوبُ وَقِيلَ لَهُ׃ «هُوَذَا ابْنُكَ يُوسُفُ قَادِمٌ إِلَيْكَ». فَتَشَدَّدَ إِسْرَائِيلُ وَجَلَسَ عَلَى السَّرِيرِ.', 'تكوين 48:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 3, 'وَقَالَ يَعْقُوبُ لِيُوسُفَ׃ «اللهُ الْقَادِرُ عَلَى كُلِّ شَيْءٍ ظَهَرَ لِي فِي لُوزَ، فِي أَرْضِ كَنْعَانَ، وَبَارَكَنِي.', 'تكوين 48:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 4, 'وَقَالَ لِي׃ هَا أَنَا أَجْعَلُكَ مُثْمِرًا وَأُكَثِّرُكَ، وَأَجْعَلُكَ جُمْهُورًا مِنَ الْأُمَمِ، وَأُعْطِي نَسْلَكَ هَذِهِ الْأَرْضَ مِنْ بَعْدِكَ مُلْكًا أَبَدِيًّا.', 'تكوين 48:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 5, 'وَالْآنَ ابْنَاكَ الْمَوْلُودَانِ لَكَ فِي أَرْضِ مِصْرَ، قَبْلَمَا أَتَيْتُ إِلَيْكَ إِلَى مِصْرَ هُمَا لِي. أَفْرَايِمُ وَمَنَسَّى كَرَأُوبَيْنَ وَشِمْعُونَ يَكُونَانِ لِي.', 'تكوين 48:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 6, 'وَأَمَّا أَوْلَادُكَ الَّذِينَ تَلِدُ بَعْدَهُمَا فَيَكُونُونَ لَكَ. عَلَى اسْمِ أَخَوَيْهِمْ يُسَمَّوْنَ فِي نَصِيبِهِمْ.', 'تكوين 48:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 7, 'وَأَنَا حِينَ جِئْتُ مِنْ فَدَّانَ مَاتَتْ عِنْدِي رَاحِيلُ فِي أَرْضِ كَنْعَانَ فِي الطَّرِيقِ، إِذْ بَقِيَتْ مَسَافَةٌ مِنَ الْأَرْضِ حَتَّى آتِيَ إِلَى أَفْرَاتَةَ، فَدَفَنْتُهَا هُنَاكَ فِي طَرِيقِ أَفْرَاتَةَ، الَّتِي هِيَ بَيْتُ لَحْمٍ».', 'تكوين 48:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 8, 'وَرَأَى إِسْرَائِيلُ ابْنَيْ يُوسُفَ فَقَالَ׃ «مَنْ هَذَانِ؟».', 'تكوين 48:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 9, 'فَقَالَ يُوسُفُ لِأَبِيهِ׃ «هُمَا ابْنَايَ اللَّذَانِ أَعْطَانِيَ اللهُ هَهُنَا». فَقَالَ׃ «قَدِّمْهُمَا إِلَيَّ لِأُبَارِكَهُمَا».', 'تكوين 48:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 10, 'وَأَمَّا عَيْنَا إِسْرَائِيلَ فَكَانَتَا قَدْ ثَقُلَتَا مِنَ الشَّيْخُوخَةِ، لَا يَقْدِرُ أَنْ يُبْصِرَ، فَقَرَّبَهُمَا إِلَيْهِ فَقَبَّلَهُمَا وَاحْتَضَنَهُمَا.', 'تكوين 48:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 11, 'وَقَالَ إِسْرَائِيلُ لِيُوسُفَ׃ «لَمْ أَكُنْ أَظُنُّ أَنِّي أَرَى وَجْهَكَ، وَهُوَذَا اللهُ قَدْ أَرَانِي نَسْلَكَ أَيْضًا».', 'تكوين 48:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 12, 'ثُمَّ أَخْرَجَهُمَا يُوسُفُ مِنْ بَيْنَ رُكْبَتَيْهِ وَسَجَدَ أَمَامَ وَجْهِهِ إِلَى الْأَرْضِ.', 'تكوين 48:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 13, 'وَأَخَذَ يُوسُفُ الِاثْنَيْنِ أَفْرَايِمَ بِيَمِينِهِ عَنْ يَسَارِ إِسْرَائِيلَ، وَمَنَسَّى بِيَسَارِهِ عَنْ يَمِينِ إِسْرَائِيلَ وَقَرَّبَهُمَا إِلَيْهِ.', 'تكوين 48:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 14, 'فَمَدَّ إِسْرَائِيلُ يَمِينَهُ وَوَضَعَهَا عَلَى رَأْسِ أَفْرَايِمَ وَهُوَ الصَّغِيرُ، وَيَسَارَهُ عَلَى رَأْسِ مَنَسَّى. وَضَعَ يَدَيْهِ بِفِطْنَةٍ فَإِنَّ مَنَسَّى كَانَ الْبِكْرَ.', 'تكوين 48:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 15, 'وَبَارَكَ يُوسُفَ وَقَالَ׃ «اللهُ الَّذِي سَارَ أَمَامَهُ أَبَوَايَ إِبْرَاهِيمُ وَإِسْحَاقُ، اللهُ الَّذِي رَعَانِي مُنْذُ وُجُودِي إِلَى هَذَا الْيَوْمِ،', 'تكوين 48:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 16, 'الْمَلَاكُ الَّذِي خَلَّصَنِي مِنْ كُلِّ شَرٍّ، يُبَارِكُ الْغُلَامَيْنِ. وَلْيُدْعَ عَلَيْهِمَا اسْمِي وَاسْمُ أَبَوَيَّ إِبْرَاهِيمَ وَإِسْحَاقَ، وَلْيَكْثُرَا كَثِيرًا فِي الْأَرْضِ».', 'تكوين 48:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 17, 'فَلَمَّا رَأَى يُوسُفُ أَنَّ أَبَاهُ وَضَعَ يَدَهُ الْيُمْنَى عَلَى رَأْسِ أَفْرَايِمَ، سَاءَ ذَلِكَ فِي عَيْنَيْهِ، فَأَمْسَكَ بِيَدِ أَبِيهِ لِيَنْقُلَهَا عَنْ رَأْسِ أَفْرَايِمَ إِلَى رَأْسِ مَنَسَّى.', 'تكوين 48:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 18, 'وَقَالَ يُوسُفُ لِأَبِيهِ׃ «لَيْسَ هَكَذَا يَا أَبِي، لِأَنَّ هَذَا هُوَ الْبِكْرُ. ضَعْ يَمِينَكَ عَلَى رَأْسِهِ».', 'تكوين 48:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 19, 'فَأَبَى أَبُوهُ وَقَالَ׃ «عَلِمْتُ يَا ابْنِي، عَلِمْتُ. هُوَ أَيْضًا يَكُونُ شَعْبًا، وَهُوَ أَيْضًا يَصِيرُ كَبِيرًا. وَلَكِنَّ أَخَاهُ الصَّغِيرَ يَكُونُ أَكْبَرَ مِنْهُ، وَنَسْلُهُ يَكُونُ جُمْهُورًا مِنَ الْأُمَمِ».', 'تكوين 48:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 20, 'وَبَارَكَهُمَا فِي ذَلِكَ الْيَوْمِ قَائِلًا׃ «بِكَ يُبَارِكُ إِسْرَائِيلُ قَائِلًا׃ يَجْعَلُكَ اللهُ كَأَفْرَايِمَ وَكَمَنَسَّى». فَقَدَّمَ أَفْرَايِمَ عَلَى مَنَسَّى.', 'تكوين 48:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 21, 'وَقَالَ إِسْرَائِيلُ لِيُوسُفَ׃ «هَا أَنَا أَمُوتُ، وَلَكِنَّ اللهَ سَيَكُونُ مَعَكُمْ وَيَرُدُّكُمْ إِلَى أَرْضِ آبَائِكُمْ.', 'تكوين 48:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 48, 22, 'وَأَنَا قَدْ وَهَبْتُ لَكَ سَهْمًا وَاحِدًا فَوْقَ إِخْوَتِكَ، أَخَذْتُهُ مِنْ يَدِ الْأَمُورِيِّينَ بِسَيْفِي وَقَوْسِي».', 'تكوين 48:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 1, 'وَدَعَا يَعْقُوبُ بَنِيهِ وَقَالَ׃ «اجْتَمِعُوا لِأُنْبِئَكُمْ بِمَا يُصِيبُكُمْ فِي آخِرِ الْأَيَّامِ.', 'تكوين 49:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 2, 'اجْتَمِعُوا وَاسْمَعُوا يَا بَنِي يَعْقُوبَ، وَاصْغَوْا إِلَى إِسْرَائِيلَ أَبِيكُمْ׃', 'تكوين 49:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 3, 'رَأُوبَيْنُ، أَنْتَ بِكْرِي، قُوَّتِي وَأَوَّلُ قُدْرَتِي، فَضْلُ الرِّفْعَةِ وَفَضْلُ الْعِزِّ.', 'تكوين 49:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 4, 'فَائِرًا كَالْمَاءِ لَا تَتَفَضَّلُ، لِأَنَّكَ صَعِدْتَ عَلَى مَضْجَعِ أَبِيكَ. حِينَئِذٍ دَنَّسْتَهُ. عَلَى فِرَاشِي صَعِدَ.', 'تكوين 49:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 5, 'شِمْعُونُ وَلَاوِي أَخَوَانِ، آلَاتُ ظُلْمٍ سُيُوفُهُمَا.', 'تكوين 49:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 6, 'فِي مَجْلِسِهِمَا لَا تَدْخُلُ نَفْسِي. بِمَجْمَعِهِمَا لَا تَتَّحِدُ كَرَامَتِي. لِأَنَّهُمَا فِي غَضَبِهِمَا قَتَلَا إِنْسَانًا، وَفِي رِضَاهُمَا عَرْقَبَا ثَوْرًا.', 'تكوين 49:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 7, 'مَلْعُونٌ غَضَبُهُمَا فَإِنَّهُ شَدِيدٌ، وَسَخَطُهُمَا فَإِنَّهُ قَاسٍ. أُقَسِّمُهُمَا فِي يَعْقُوبَ، وَأُفَرِّقُهُمَا فِي إِسْرَائِيلَ.', 'تكوين 49:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 8, 'يَهُوذَا، إِيَّاكَ يَحْمَدُ إِخْوَتُكَ، يَدُكَ عَلَى قَفَا أَعْدَائِكَ، يَسْجُدُ لَكَ بَنُو أَبِيكَ.', 'تكوين 49:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 9, 'يَهُوذَا جَرْوُ أَسَدٍ، مِنْ فَرِيسَةٍ صَعِدْتَ يَا ابْنِي، جَثَا وَرَبَضَ كَأَسَدٍ وَكَلَبْوَةٍ. مَنْ يُنْهِضُهُ؟', 'تكوين 49:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 10, 'لَا يَزُولُ قَضِيبٌ مِنْ يَهُوذَا وَمُشْتَرِعٌ مِنْ بَيْنِ رِجْلَيْهِ حَتَّى يَأْتِيَ شِيلُونُ وَلَهُ يَكُونُ خُضُوعُ شُعُوبٍ.', 'تكوين 49:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 11, 'رَابِطًا بِالْكَرْمَةِ جَحْشَهُ، وَبِالْجَفْنَةِ ابْنَ أَتَانِهِ، غَسَلَ بِالْخَمْرِ لِبَاسَهُ، وَبِدَمِ الْعِنَبِ ثَوْبَهُ.', 'تكوين 49:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 12, 'مُسْوَدُّ الْعَيْنَيْنِ مِنَ الْخَمْرِ، وَمُبْيَضُّ الْأَسْنَانِ مِنَ اللَّبَنِ.', 'تكوين 49:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 13, 'زَبُولُونُ، عِنْدَ سَاحِلِ الْبَحْرِ يَسْكُنُ، وَهُوَ عِنْدَ سَاحِلِ السُّفُنِ، وَجَانِبُهُ عِنْدَ صَيْدُونَ.', 'تكوين 49:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 14, 'يَسَّاكَرُ، حِمَارٌ جَسِيمٌ رَابِضٌ بَيْنَ الْحَظَائِرِ.', 'تكوين 49:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 15, 'فَرَأَى الْمَحَلَّ أَنَّهُ حَسَنٌ، وَالْأَرْضَ أَنَّهَا نَزِهَةٌ، فَأَحْنَى كَتِفَهُ لِلْحِمْلِ وَصَارَ لِلْجِزْيَةِ عَبْدًا.', 'تكوين 49:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 16, 'دَانُ، يَدِينُ شَعْبَهُ كَأَحَدِ أَسْبَاطِ إِسْرَائِيلَ.', 'تكوين 49:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 17, 'يَكُونُ دَانُ حَيَّةً عَلَى الطَّرِيقِ، أُفْعُوانًا عَلَى السَّبِيلِ، يَلْسَعُ عَقِبَيِ الْفَرَسِ فَيَسْقُطُ رَاكِبُهُ إِلَى الْوَرَاءِ.', 'تكوين 49:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 18, 'لِخَلَاصِكَ انْتَظَرْتُ يَا رَبُّ.', 'تكوين 49:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 19, 'جَادُ، يَزْحَمُهُ جَيْشٌ، وَلَكِنَّهُ يَزْحَمُ مُؤَخَّرَهُ.', 'تكوين 49:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 20, 'أَشِيرُ، خُبْزُهُ سَمِينٌ وَهُوَ يُعْطِي لَذَّاتِ مُلُوكٍ.', 'تكوين 49:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 21, 'نَفْتَالِي، أَيِّلَةٌ مُسَيَّبَةٌ يُعْطِي أَقْوَالًا حَسَنَةً.', 'تكوين 49:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 22, 'يُوسُفُ، غُصْنُ شَجَرَةٍ مُثْمِرَةٍ، غُصْنُ شَجَرَةٍ مُثْمِرَةٍ عَلَى عَيْنٍ. أَغْصَانٌ قَدِ ارْتَفَعَتْ فَوْقَ حَائِطٍ.', 'تكوين 49:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 23, 'فَمَرَّرَتْهُ وَرَمَتْهُ وَاضْطَهَدَتْهُ أَرْبَابُ السِّهَامِ.', 'تكوين 49:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 24, 'وَلَكِنْ ثَبَتَتْ بِمَتَانَةٍ قَوْسُهُ، وَتَشَدَّدَتْ سَوَاعِدُ يَدَيْهِ. مِنْ يَدَيْ عَزِيزِ يَعْقُوبَ، مِنْ هُنَاكَ، مِنَ الرَّاعِي صَخْرِ إِسْرَائِيلَ،', 'تكوين 49:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 25, 'مِنْ إِلَهِ أَبِيكَ الَّذِي يُعِينُكَ، وَمِنَ الْقَادِرِ عَلَى كُلِّ شَيْءٍ الَّذِي يُبَارِكُكَ، تَأْتِي بَرَكَاتُ السَّمَاءِ مِنْ فَوْقُ، وَبَرَكَاتُ الْغَمْرِ الرَّابِضِ تَحْتُ. بَرَكَاتُ الثَّدْيَيْنِ وَالرَّحِمِ.', 'تكوين 49:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 26, 'بَرَكَاتُ أَبِيكَ فَاقَتْ عَلَى بَرَكَاتِ أَبَوَيَّ. إِلَى مُنْيَةِ الْآكَامِ الدَّهْرِيَّةِ تَكُونُ عَلَى رَأْسِ يُوسُفَ، وَعَلَى قِمَّةِ نَذِيرِ إِخْوَتِهِ.', 'تكوين 49:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 27, 'بَنْيَامِينُ ذِئْبٌ يَفْتَرِسُ. فِي الصَّبَاحِ يَأْكُلُ غَنِيمَةً، وَعِنْدَ الْمَسَاءِ يُقَسِّمُ نَهْبًا».', 'تكوين 49:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 28, 'جَمِيعُ هَؤُلَاءِ هُمْ أَسْبَاطُ إِسْرَائِيلَ الِاثْنَا عَشَرَ. وَهَذَا مَا كَلَّمَهُمْ بِهِ أَبُوهُمْ وَبَارَكَهُمْ. كُلُّ وَاحِدٍ بِحَسَبِ بَرَكَتِهِ بَارَكَهُمْ.', 'تكوين 49:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 29, 'وَأَوْصَاهُمْ وَقَالَ لَهُمْ׃ «أَنَا أَنْضَمُّ إِلَى قَوْمِي. اِدْفِنُونِي عِنْدَ آبَائِي فِي الْمَغَارَةِ الَّتِي فِي حَقْلِ عِفْرُونَ الْحِثِّيِّ.', 'تكوين 49:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 30, 'فِي الْمَغَارَةِ الَّتِي فِي حَقْلِ الْمَكْفِيلَةِ، الَّتِي أَمَامَ مَمْرَا فِي أَرْضِ كَنْعَانَ، الَّتِي اشْتَرَاهَا إِبْرَاهِيمُ مَعَ الْحَقْلِ مِنْ عِفْرُونَ الْحِثِّيِّ مُلْكَ قَبْرٍ.', 'تكوين 49:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 31, 'هُنَاكَ دَفَنُوا إِبْرَاهِيمَ وَسَارَةَ امْرَأَتَهُ. هُنَاكَ دَفَنُوا إِسْحَاقَ وَرِفْقَةَ امْرَأَتَهُ، وَهُنَاكَ دَفَنْتُ لَيْئَةَ.', 'تكوين 49:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 32, 'شِرَاءُ الْحَقْلِ وَالْمَغَارَةِ الَّتِي فِيهِ كَانَ مِنْ بَنِي حِثَّ».', 'تكوين 49:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 49, 33, 'وَلَمَّا فَرَغَ يَعْقُوبُ مِنْ تَوْصِيَةِ بَنِيهِ ضَمَّ رِجْلَيْهِ إِلَى السَّرِيرِ، وَأَسْلَمَ الرُّوحَ وَانْضَمَّ إِلَى قَوْمِهِ.', 'تكوين 49:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 1, 'فَوَقَعَ يُوسُفُ عَلَى وَجْهِ أَبِيهِ وَبَكَى عَلَيْهِ وَقَبَّلَهُ.', 'تكوين 50:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 2, 'وَأَمَرَ يُوسُفُ عَبِيدَهُ الْأَطِبَّاءَ أَنْ يُحَنِّطُوا أَبَاهُ. فَحَنَّطَ الْأَطِبَّاءُ إِسْرَائِيلَ.', 'تكوين 50:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 3, 'وَكَمُلَ لَهُ أَرْبَعُونَ يَوْمًا، لِأَنَّهُ هَكَذَا تَكْمُلُ أَيَّامُ الْمُحَنَّطِينَ. وَبَكَى عَلَيْهِ الْمِصْرِيُّونَ سَبْعِينَ يَوْمًا.', 'تكوين 50:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 4, 'وَبَعْدَ مَا مَضَتْ أَيَّامُ بُكَائِهِ كَلَّمَ يُوسُفُ بَيْتَ فِرْعَوْنَ قَائِلًا׃ «إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عُيُونِكُمْ، فَتَكَلَّمُوا فِي مَسَامِعِ فِرْعَوْنَ قَائِلِينَ׃', 'تكوين 50:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 5, 'أَبِي اسْتَحْلَفَنِي قَائِلًا׃ هَا أَنَا أَمُوتُ. فِي قَبْرِيَ الَّذِي حَفَرْتُ لِنَفْسِي فِي أَرْضِ كَنْعَانَ هُنَاكَ تَدْفِنُنِي، فَالْآنَ أَصْعَدُ لِأَدْفِنَ أَبِي وَأَرْجِعُ».', 'تكوين 50:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 6, 'فَقَالَ فِرْعَوْنُ׃ «اصْعَدْ وَادْفِنْ أَبَاكَ كَمَا اسْتَحْلَفَكَ».', 'تكوين 50:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 7, 'فَصَعِدَ يُوسُفُ لِيَدْفِنَ أَبَاهُ، وَصَعِدَ مَعَهُ جَمِيعُ عَبِيدِ فِرْعَوْنَ، شُيُوخُ بَيْتِهِ وَجَمِيعُ شُيُوخِ أَرْضِ مِصْرَ،', 'تكوين 50:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 8, 'وَكُلُّ بَيْتِ يُوسُفَ وَإِخْوَتُهُ وَبَيْتُ أَبِيهِ، غَيْرَ أَنَّهُمْ تَرَكُوا أَوْلَادَهُمْ وَغَنَمَهُمْ وَبَقَرَهُمْ فِي أَرْضِ جَاسَانَ.', 'تكوين 50:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 9, 'وَصَعِدَ مَعَهُ مَرْكَبَاتٌ وَفُرْسَانٌ، فَكَانَ الْجَيْشُ كَثِيرًا جِدًّا.', 'تكوين 50:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 10, 'فَأَتَوْا إِلَى بَيْدَرِ أَطَادَ الَّذِي فِي عَبْرِ الْأُرْدُنِّ وَنَاحُوا هُنَاكَ نَوْحًا عَظِيمًا وَشَدِيدًا جِدًّا، وَصَنَعَ لِأَبِيهِ مَنَاحَةً سَبْعَةَ أَيَّامٍ.', 'تكوين 50:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 11, 'فَلَمَّا رَأَى أَهْلُ الْبِلَادِ الْكَنْعَانِيُّونَ الْمَنَاحَةَ فِي بَيْدَرِ أَطَادَ قَالُوا׃ «هَذِهِ مَنَاحَةٌ ثَقِيلَةٌ لِلْمِصْرِيِّينَ». لِذَلِكَ دُعِيَ اسْمُهُ «آبَلَ مِصْرَايِمَ». الَّذِي فِي عَبْرِ الْأُرْدُنِّ.', 'تكوين 50:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 12, 'وَفَعَلَ لَهُ بَنُوهُ هَكَذَا كَمَا أَوْصَاهُمْ׃', 'تكوين 50:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 13, 'حَمَلَهُ بَنُوهُ إِلَى أَرْضِ كَنْعَانَ وَدَفَنُوهُ فِي مَغَارَةِ حَقْلِ الْمَكْفِيلَةِ، الَّتِي اشْتَرَاهَا إِبْرَاهِيمُ مَعَ الْحَقْلِ مُلْكَ قَبْرٍ مِنْ عِفْرُونَ الْحِثِّيِ أَمَامَ مَمْرَا.', 'تكوين 50:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 14, 'ثُمَّ رَجَعَ يُوسُفُ إِلَى مِصْرَ هُوَ وَإِخْوَتُهُ وَجَمِيعُ الَّذِينَ صَعِدُوا مَعَهُ لِدَفْنِ أَبِيهِ بَعْدَ مَا دَفَنَ أَبَاهُ.', 'تكوين 50:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 15, 'وَلَمَّا رَأَى إِخْوَةُ يُوسُفَ أَنَّ أَبَاهُمْ قَدْ مَاتَ، قَالُوا׃ «لَعَلَّ يُوسُفَ يَضْطَهِدُنَا وَيَرُدُّ عَلَيْنَا جَمِيعَ الشَّرِّ الَّذِي صَنَعْنَا بِهِ».', 'تكوين 50:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 16, 'فَأَوَصَوْا إِلَى يُوسُفَ قَائِلِينَ׃ «أَبُوكَ أَوْصَى قَبْلَ مَوْتِهِ قَائِلًا׃', 'تكوين 50:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 17, 'هَكَذَا تَقُولُونَ لِيُوسُفَ׃ آهِ! اصْفَحْ عَنْ ذَنْبِ إِخْوَتِكَ وَخَطِيَّتِهِمْ، فَإِنَّهُمْ صَنَعُوا بِكَ شَرًّا. فَالْآنَ اصْفَحْ عَنْ ذَنْبِ عَبِيدِ إِلَهِ أَبِيكَ». فَبَكَى يُوسُفُ حِينَ كَلَّمُوهُ.', 'تكوين 50:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 18, 'وَأَتَى إِخْوَتُهُ أَيْضًا وَوَقَعُوا أَمَامَهُ وَقَالُوا׃ «هَا نَحْنُ عَبِيدُكَ».', 'تكوين 50:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 19, 'فَقَالَ لَهُمْ يُوسُفُ׃ «لَا تَخَافُوا. لِأَنَّهُ هَلْ أَنَا مَكَانَ اللهِ؟', 'تكوين 50:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 20, 'أَنْتُمْ قَصَدْتُمْ لِي شَرًّا، أَمَّا اللهُ فَقَصَدَ بِهِ خَيْرًا، لِكَيْ يَفْعَلَ كَمَا الْيَوْمَ، لِيُحْيِيَ شَعْبًا كَثِيرًا.', 'تكوين 50:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 21, 'فَالْآنَ لَا تَخَافُوا. أَنَا أَعُولُكُمْ وَأَوْلَادَكُمْ». فَعَزَّاهُمْ وَطَيَّبَ قُلُوبَهُمْ.', 'تكوين 50:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 22, 'وَسَكَنَ يُوسُفُ فِي مِصْرَ هُوَ وَبَيْتُ أَبِيهِ، وَعَاشَ يُوسُفُ مِئَةً وَعَشَرَ سِنِينَ.', 'تكوين 50:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 23, 'وَرَأَى يُوسُفُ لِأَفْرَايِمَ أَوْلَادَ الْجِيلِ الثَّالِثِ. وَأَوْلَادُ مَاكِيرَ بْنِ مَنَسَّى أَيْضًا وُلِدُوا عَلَى رُكْبَتَيْ يُوسُفَ.', 'تكوين 50:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 24, 'وَقَالَ يُوسُفُ لِإِخْوَتِهِ׃ «أَنَا أَمُوتُ، وَلَكِنَّ اللهَ سَيَفْتَقِدُكُمْ وَيُصْعِدُكُمْ مِنْ هَذِهِ الْأَرْضِ إِلَى الْأَرْضِ الَّتِي حَلَفَ لِإِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ».', 'تكوين 50:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 25, 'وَاسْتَحْلَفَ يُوسُفُ بَنِي إِسْرَائِيلَ قَائِلًا׃ «اللهُ سَيَفْتَقِدُكُمْ فَتُصْعِدُونَ عِظَامِي مِنْ هُنَا».', 'تكوين 50:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'تكوين', 50, 26, 'ثُمَّ مَاتَ يُوسُفُ وَهُوَ ابْنُ مِئَةٍ وَعَشَرِ سِنِينَ، فَحَنَّطُوهُ وَوُضِعَ فِي تَابُوتٍ فِي مِصْرَ.', 'تكوين 50:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 1, 'وَهَذِهِ أَسْمَاءُ بَنِي إِسْرَائِيلَ الَّذِينَ جَاءُوا إِلَى مِصْرَ. مَعَ يَعْقُوبَ جَاءَ كُلُّ إِنْسَانٍ وَبَيْتُهُ׃', 'خروج 1:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 2, 'رَأُوبَيْنُ وَشِمْعُونُ وَلَاوِي وَيَهُوذَا', 'خروج 1:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 3, 'وَيَسَّاكَرُ وَزَبُولُونُ وَبَنْيَامِينُ', 'خروج 1:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 4, 'وَدَانُ وَنَفْتَالِي وَجَادُ وَأَشِيرُ.', 'خروج 1:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 5, 'وَكَانَتْ جَمِيعُ نُفُوسِ الْخَارِجِينَ مِنْ صُلْبِ يَعْقُوبَ سَبْعِينَ نَفْسًا. وَلَكِنْ يُوسُفُ كَانَ فِي مِصْرَ.', 'خروج 1:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 6, 'وَمَاتَ يُوسُفُ وَكُلُّ إِخْوَتِهِ وَجَمِيعُ ذَلِكَ الْجِيلِ.', 'خروج 1:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 7, 'وَأَمَّا بَنُو إِسْرَائِيلَ فَأَثْمَرُوا وَتَوَالَدُوا وَنَمَوْا وَكَثُرُوا كَثِيرًا جِدًّا، وَامْتَلَأَتِ الْأَرْضُ مِنْهُمْ.', 'خروج 1:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 8, 'ثُمَّ قَامَ مَلِكٌ جَدِيدٌ عَلَى مِصْرَ لَمْ يَكُنْ يَعْرِفُ يُوسُفَ.', 'خروج 1:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 9, 'فَقَالَ لِشَعْبِهِ׃ «هُوَذَا بَنُو إِسْرَائِيلَ شَعْبٌ أَكْثَرُ وَأَعْظَمُ مِنَّا.', 'خروج 1:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 10, 'هَلُمَّ نَحْتَالُ لَهُمْ لِئَلَّا يَنْمُوا، فَيَكُونَ إِذَا حَدَثَتْ حَرْبٌ أَنَّهُمْ يَنْضَمُّونَ إِلَى أَعْدَائِنَا وَيُحَارِبُونَنَا وَيَصْعَدُونَ مِنَ الْأَرْضِ».', 'خروج 1:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 11, 'فَجَعَلُوا عَلَيْهِمْ رُؤَسَاءَ تَسْخِيرٍ لِكَيْ يُذِلُّوهُمْ بِأَثْقَالِهِمْ، فَبَنَوْا لِفِرْعَوْنَ مَدِينَتَيْ مَخَازِنَ׃ فِيثُومَ، وَرَعَمْسِيسَ.', 'خروج 1:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 12, 'وَلَكِنْ بِحَسْبِمَا أَذَلُّوهُمْ هَكَذَا نَمَوْا وَامْتَدُّوا. فَاخْتَشَوْا مِنْ بَنِي إِسْرَائِيلَ.', 'خروج 1:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 13, 'فَاسْتَعْبَدَ الْمِصْرِيُّونَ بَنِي إِسْرَائِيلَ بِعُنْفٍ،', 'خروج 1:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 14, 'وَمَرَّرُوا حَيَاتَهُمْ بِعُبُودِيَّةٍ قَاسِيَةٍ فِي الطِّينِ وَاللِّبْنِ وَفِي كُلِّ عَمَلٍ فِي الْحَقْلِ. كُلِّ عَمَلِهِمِ الَّذِي عَمِلُوهُ بِوَاسِطَتِهِمْ عُنْفًا.', 'خروج 1:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 15, 'وَكَلَّمَ مَلِكُ مِصْرَ قَابِلَتَيِ الْعِبْرَانِيَّاتِ اللَّتَيْنِ اسْمُ إِحْدَاهُمَا شِفْرَةُ وَاسْمُ الْأُخْرَى فُوعَةُ،', 'خروج 1:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 16, 'وَقَالَ׃ «حِينَمَا تُوَلِّدَانِ الْعِبْرَانِيَّاتِ وَتَنْظُرَانِهِنَّ عَلَى الْكَرَاسِيِّ، إِنْ كَانَ ابْنًا فَاقْتُلَاهُ، وَإِنْ كَانَ بِنْتًا فَتَحْيَا».', 'خروج 1:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 17, 'وَلَكِنَّ الْقَابِلَتَيْنِ خَافَتَا اللهَ وَلَمْ تَفْعَلَا كَمَا كَلَّمَهُمَا مَلِكُ مِصْرَ، بَلِ اسْتَحْيَتَا الْأَوْلَادَ.', 'خروج 1:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 18, 'فَدَعَا مَلِكُ مِصْرَ الْقَابِلَتَيْنِ وَقَالَ لَهُمَا׃ «لِمَاذَا فَعَلْتُمَا هَذَا الْأَمْرَ وَاسْتَحْيَيْتُمَا الْأَوْلَادَ؟»', 'خروج 1:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 19, 'فَقَالَتِ الْقَابِلَتَانِ لِفِرْعَوْنَ׃ «إِنَّ النِّسَاءَ الْعِبْرَانِيَّاتِ لَسْنَ كَالْمِصْرِيَّاتِ، فَإِنَّهُنَّ قَوِيَّاتٌ يَلِدْنَ قَبْلَ أَنْ تَأْتِيَهُنَّ الْقَابِلَةُ».', 'خروج 1:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 20, 'فَأَحْسَنَ اللهُ إِلَى الْقَابِلَتَيْنِ، وَنَمَا الشَّعْبُ وَكَثُرَ جِدًّا.', 'خروج 1:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 21, 'وَكَانَ إِذْ خَافَتِ الْقَابِلَتَانِ اللهَ أَنَّهُ صَنَعَ لَهُمَا بُيُوتًا.', 'خروج 1:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 1, 22, 'ثُمَّ أَمَرَ فِرْعَوْنُ جَمِيعَ شَعْبِهِ قَائِلًا׃ «كُلُّ ابْنٍ يُولَدُ تَطْرَحُونَهُ فِي النَّهْرِ، لَكِنَّ كُلَّ بِنْتٍ تَسْتَحْيُونَهَا».', 'خروج 1:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 1, 'وَذَهَبَ رَجُلٌ مِنْ بَيْتِ لَاوِي وَأَخَذَ بِنْتَ لَاوِي،', 'خروج 2:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 2, 'فَحَبِلَتِ الْمَرْأَةُ وَوَلَدَتِ ابْنًا. وَلَمَّا رَأَتْهُ أَنَّهُ حَسَنٌ، خَبَّأَتْهُ ثَلَاثَةَ أَشْهُرٍ.', 'خروج 2:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 3, 'وَلَمَّا لَمْ يُمْكِنْهَا أَنْ تُخَبِّئَهُ بَعْدُ، أَخَذَتْ لَهُ سَفَطًا مِنَ الْبَرْدِيِّ وَطَلَتْهُ بِالْحُمَرِ وَالزِّفْتِ، وَوَضَعَتِ الْوَلَدَ فِيهِ، وَوَضَعَتْهُ بَيْنَ الْحَلْفَاءِ عَلَى حَافَةِ النَّهْرِ.', 'خروج 2:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 4, 'وَوَقَفَتْ أُخْتُهُ مِنْ بَعِيدٍ لِتَعْرِفَ مَاذَا يُفْعَلُ بِهِ.', 'خروج 2:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 5, 'فَنَزَلَتِ ابْنَةُ فِرْعَوْنَ إِلَى النَّهْرِ لِتَغْتَسِلَ، وَكَانَتْ جَوَارِيهَا مَاشِيَاتٍ عَلَى جَانِبِ النَّهْرِ. فَرَأَتِ السَّفَطَ بَيْنَ الْحَلْفَاءِ، فَأَرْسَلَتْ أَمَتَهَا وَأَخَذَتْهُ.', 'خروج 2:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 6, 'وَلَمَّا فَتَحَتْهُ رَأَتِ الْوَلَدَ، وَإِذَا هُوَ صَبِيٌّ يَبْكِي. فَرَقَّتْ لَهُ وَقَالَتْ׃ «هَذَا مِنْ أَوْلَادِ الْعِبْرَانِيِّينَ».', 'خروج 2:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 7, 'فَقَالَتْ أُخْتُهُ لِابْنَةِ فِرْعَوْنَ׃ «هَلْ أَذْهَبُ وَأَدْعُو لَكِ امْرَأَةً مُرْضِعَةً مِنَ الْعِبْرَانِيَّاتِ لِتُرْضِعَ لَكِ الْوَلَدَ؟»', 'خروج 2:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 8, 'فَقَالَتْ لَهَا ابْنَةُ فِرْعَوْنَ׃ «اذْهَبِي». فَذَهَبَتِ الْفَتَاةُ وَدَعَتْ أُمَّ الْوَلَدِ.', 'خروج 2:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 9, 'فَقَالَتْ لَهَا ابْنَةُ فِرْعَوْنَ׃ «اذْهَبِي بِهَذَا الْوَلَدِ وَأَرْضِعِيهِ لِي وَأَنَا أُعْطِي أُجْرَتَكِ». فَأَخَذَتِ الْمَرْأَةُ الْوَلَدَ وَأَرْضَعَتْهُ.', 'خروج 2:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 10, 'وَلَمَّا كَبِرَ الْوَلَدُ جَاءَتْ بِهِ إِلَى ابْنَةِ فِرْعَوْنَ فَصَارَ لَهَا ابْنًا، وَدَعَتِ اسْمَهُ «مُوسَى» وَقَالَتْ׃ «إِنِّي انْتَشَلْتُهُ مِنَ الْمَاءِ».', 'خروج 2:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 11, 'وَحَدَثَ فِي تِلْكَ الْأَيَّامِ لَمَّا كَبِرَ مُوسَى أَنَّهُ خَرَجَ إِلَى إِخْوَتِهِ لِيَنْظُرَ فِي أَثْقَالِهِمْ، فَرَأَى رَجُلًا مِصْرِيًّا يَضْرِبُ رَجُلًا عِبْرَانِيًّا مِنْ إِخْوَتِهِ،', 'خروج 2:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 12, 'فَالْتَفَتَ إِلَى هُنَا وَهُنَاكَ وَرَأَى أَنْ لَيْسَ أَحَدٌ، فَقَتَلَ الْمِصْرِيَّ وَطَمَرَهُ فِي الرَّمْلِ.', 'خروج 2:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 13, 'ثُمَّ خَرَجَ فِي الْيَوْمِ الثَّانِي وَإِذَا رَجُلَانِ عِبْرَانِيَّانِ يَتَخَاصَمَانِ، فَقَالَ لِلْمُذْنِبِ׃ «لِمَاذَا تَضْرِبُ صَاحِبَكَ؟»', 'خروج 2:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 14, 'فَقَالَ׃ «مَنْ جَعَلَكَ رَئِيسًا وَقَاضِيًا عَلَيْنَا؟ أَمُفْتَكِرٌ أَنْتَ بِقَتْلِي كَمَا قَتَلْتَ الْمِصْرِيَّ؟». فَخَافَ مُوسَى وَقَالَ׃ «حَقًّا قَدْ عُرِفَ الْأَمْرُ».', 'خروج 2:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 15, 'فَسَمِعَ فِرْعَوْنُ هَذَا الْأَمْرَ، فَطَلَبَ أَنْ يَقْتُلَ مُوسَى. فَهَرَبَ مُوسَى مِنْ وَجْهِ فِرْعَوْنَ وَسَكَنَ فِي أَرْضِ مِدْيَانَ، وَجَلَسَ عِنْدَ الْبِئْرِ.', 'خروج 2:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 16, 'وَكَانَ لِكَاهِنِ مِدْيَانَ سَبْعُ بَنَاتٍ، فَأَتَيْنَ وَاسْتَقَيْنَ وَمَلَأْنَ الْأَجْرَانَ لِيَسْقِينَ غَنَمَ أَبِيهِنَّ.', 'خروج 2:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 17, 'فَأَتَى الرُّعَاةُ وَطَرَدُوهُنَّ. فَنَهَضَ مُوسَى وَأَنْجَدَهُنَّ وَسَقَى غَنَمَهُنَّ.', 'خروج 2:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 18, 'فَلَمَّا أَتَيْنَ إِلَى رَعُوئِيلَ أَبِيهِنَّ قَالَ׃ «مَا بَالُكُنَّ أَسْرَعْتُنَّ فِي الْمَجِيءِ الْيَوْمَ؟»', 'خروج 2:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 19, 'فَقُلْنَ׃ «رَجُلٌ مِصْرِيٌّ أَنْقَذَنَا مِنْ أَيْدِي الرُّعَاةِ، وَإِنَّهُ اسْتَقَى لَنَا أَيْضًا وَسَقَى الْغَنَمَ».', 'خروج 2:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 20, 'فَقَالَ لِبَنَاتِهِ׃ «وَأَيْنَ هُوَ؟ لِمَاذَا تَرَكْتُنَّ الرَّجُلَ؟ ادْعُونَهُ لِيَأْكُلَ طَعَامًا».', 'خروج 2:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 21, 'فَارْتَضَى مُوسَى أَنْ يَسْكُنَ مَعَ الرَّجُلِ، فَأَعْطَى مُوسَى صَفُّورَةَ ابْنَتَهُ.', 'خروج 2:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 22, 'فَوَلَدَتِ ابْنًا فَدَعَا اسْمَهُ «جَرْشُومَ»، لِأَنَّهُ قَالَ׃ «كُنْتُ نَزِيلًا فِي أَرْضٍ غَرِيبَةٍ».', 'خروج 2:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 23, 'وَحَدَثَ فِي تِلْكَ الْأَيَّامِ الْكَثِيرَةِ أَنَّ مَلِكَ مِصْرَ مَاتَ. وَتَنَهَّدَ بَنُو إِسْرَائِيلَ مِنَ الْعُبُودِيَّةِ وَصَرَخُوا، فَصَعِدَ صُرَاخُهُمْ إِلَى اللهِ مِنْ أَجْلِ الْعُبُودِيَّةِ.', 'خروج 2:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 24, 'فَسَمِعَ اللهُ أَنِينَهُمْ، فَتَذَكَّرَ اللهُ مِيثَاقَهُ مَعَ إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ.', 'خروج 2:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 2, 25, 'وَنَظَرَ اللهُ بَنِي إِسْرَائِيلَ وَعَلِمَ اللهُ.', 'خروج 2:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 1, 'وَأَمَّا مُوسَى فَكَانَ يَرْعَى غَنَمَ يَثْرُونَ حَمِيهِ كَاهِنِ مِدْيَانَ، فَسَاقَ الْغَنَمَ إِلَى وَرَاءِ الْبَرِّيَّةِ وَجَاءَ إِلَى جَبَلِ اللهِ حُورِيبَ.', 'خروج 3:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 2, 'وَظَهَرَ لَهُ مَلَاكُ الرَّبِّ بِلَهِيبِ نَارٍ مِنْ وَسَطِ عُلَّيْقَةٍ. فَنَظَرَ وَإِذَا الْعُلَّيْقَةُ تَتَوَقَّدُ بِالنَّارِ، وَالْعُلَّيْقَةُ لَمْ تَكُنْ تَحْتَرِقُ.', 'خروج 3:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 3, 'فَقَالَ مُوسَى׃ «أَمِيلُ الْآنَ لِأَنْظُرَ هَذَا الْمَنْظَرَ الْعَظِيمَ. لِمَاذَا لَا تَحْتَرِقُ الْعُلَّيْقَةُ؟».', 'خروج 3:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 4, 'فَلَمَّا رَأَى الرَّبُّ أَنَّهُ مَالَ لِيَنْظُرَ، نَادَاهُ اللهُ مِنْ وَسَطِ الْعُلَّيْقَةِ وَقَالَ׃ «مُوسَى، مُوسَى!». فَقَالَ׃ «هَأَنَذَا».', 'خروج 3:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 5, 'فَقَالَ׃ «لَا تَقْتَرِبْ إِلَى هَهُنَا. اخْلَعْ حِذَاءَكَ مِنْ رِجْلَيْكَ، لِأَنَّ الْمَوْضِعَ الَّذِي أَنْتَ وَاقِفٌ عَلَيْهِ أَرْضٌ مُقَدَّسَةٌ».', 'خروج 3:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 6, 'ثُمَّ قَالَ׃ «أَنَا إِلَهُ أَبِيكَ، إِلَهُ إِبْرَاهِيمَ وَإِلَهُ إِسْحَاقَ وَإِلَهُ يَعْقُوبَ». فَغَطَّى مُوسَى وَجْهَهُ لِأَنَّهُ خَافَ أَنْ يَنْظُرَ إِلَى اللهِ.', 'خروج 3:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 7, 'فَقَالَ الرَّبُّ׃ «إِنِّي قَدْ رَأَيْتُ مَذَلَّةَ شَعْبِي الَّذِي فِي مِصْرَ وَسَمِعْتُ صُرَاخَهُمْ مِنْ أَجْلِ مُسَخِّرِيهِمْ. إِنِّي عَلِمْتُ أَوْجَاعَهُمْ،', 'خروج 3:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 8, 'فَنَزَلْتُ لِأُنْقِذَهُمْ مِنْ أَيْدِي الْمِصْرِيِّينَ، وَأُصْعِدَهُمْ مِنْ تِلْكَ الْأَرْضِ إِلَى أَرْضٍ جَيِّدَةٍ وَوَاسِعَةٍ، إِلَى أَرْضٍ تَفِيضُ لَبَنًا وَعَسَلًا، إِلَى مَكَانِ الْكَنْعَانِيِّينَ وَالْحِثِّيِّينَ وَالْأَمُورِيِّينَ وَالْفِرِزَّيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ.', 'خروج 3:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 9, 'وَالْآنَ هُوَذَا صُرَاخُ بَنِي إِسْرَائِيلَ قَدْ أَتَى إِلَيَّ، وَرَأَيْتُ أَيْضًا الضِّيقَةَ الَّتِي يُضَايِقُهُمْ بِهَا الْمِصْرِيُّونَ،', 'خروج 3:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 10, 'فَالْآنَ هَلُمَّ فَأُرْسِلُكَ إِلَى فِرْعَوْنَ، وَتُخْرِجُ شَعْبِي بَنِي إِسْرَائِيلَ مِنْ مِصْرَ».', 'خروج 3:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 11, 'فَقَالَ مُوسَى لِلهِ׃ «مَنْ أَنَا حَتَّى أَذْهَبَ إِلَى فِرْعَوْنَ، وَحَتَّى أُخْرِجَ بَنِي إِسْرَائِيلَ مِنْ مِصْرَ؟»', 'خروج 3:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 12, 'فَقَالَ׃ «إِنِّي أَكُونُ مَعَكَ، وَهَذِهِ تَكُونُ لَكَ الْعَلَامَةُ أَنِّي أَرْسَلْتُكَ׃ حِينَمَا تُخْرِجُ الشَّعْبَ مِنْ مِصْرَ، تَعْبُدُونَ اللهَ عَلَى هَذَا الْجَبَلِ».', 'خروج 3:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 13, 'فَقَالَ مُوسَى لِلهِ׃ «هَا أَنَا آتِي إِلَى بَنِي إِسْرَائِيلَ وَأَقُولُ لَهُمْ׃ إِلَهُ آبَائِكُمْ أَرْسَلَنِي إِلَيْكُمْ. فَإِذَا قَالُوا لِي׃ مَا اسْمُهُ؟ فَمَاذَا أَقُولُ لَهُمْ؟»', 'خروج 3:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 14, 'فَقَالَ اللهُ لِمُوسَى׃ «أَهْيَهِ الَّذِي أَهْيَهْ». وَقَالَ׃ «هَكَذَا تَقُولُ لِبَنِي إِسْرَائِيلَ׃ أَهْيَهْ أَرْسَلَنِي إِلَيْكُمْ».', 'خروج 3:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 15, 'وَقَالَ اللهُ أَيْضًا لِمُوسَى׃ «هَكَذَا تَقُولُ لِبَنِي إِسْرَائِيلَ׃ يَهْوَهْ إِلَهُ آبَائِكُمْ، إِلَهُ إِبْرَاهِيمَ وَإِلَهُ إِسْحَاقَ وَإِلَهُ يَعْقُوبَ أَرْسَلَنِي إِلَيْكُمْ. هَذَا اسْمِي إِلَى الْأَبَدِ وَهَذَا ذِكْرِي إِلَى دَوْرٍ فَدَوْرٍ.', 'خروج 3:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 16, 'اِذْهَبْ وَاجْمَعْ شُيُوخَ إِسْرَائِيلَ وَقُلْ لَهُمُ׃ الرَّبُّ إِلَهُ آبَائِكُمْ، إِلَهُ إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ ظَهَرَ لِي قَائِلًا׃ إِنِّي قَدِ افْتَقَدْتُكُمْ وَمَا صُنِعَ بِكُمْ فِي مِصْرَ.', 'خروج 3:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 17, 'فَقُلْتُ أُصْعِدُكُمْ مِنْ مَذَلَّةِ مِصْرَ إِلَى أَرْضِ الْكَنْعَانِيِّينَ وَالْحِثِّيِّينَ وَالْأَمُورِيِّينَ وَالْفِرِزِّيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ، إِلَى أَرْضٍ تَفِيضُ لَبَنًا وَعَسَلًا.', 'خروج 3:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 18, '«فَإِذَا سَمِعُوا لِقَوْلِكَ، تَدْخُلُ أَنْتَ وَشُيُوخُ بَنِي إِسْرَائِيلَ إِلَى مَلِكِ مِصْرَ وَتَقُولُونَ لَهُ׃ الرَّبُّ إِلَهُ الْعِبْرَانِيِّينَ الْتَقَانَا، فَالْآنَ نَمْضِي سَفَرَ ثَلَاثَةِ أَيَّامٍ فِي الْبَرِّيَّةِ وَنَذْبَحُ لِلرَّبِّ إِلَهِنَا.', 'خروج 3:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 19, 'وَلَكِنِّي أَعْلَمُ أَنَّ مَلِكَ مِصْرَ لَا يَدَعُكُمْ تَمْضُونَ وَلَا بِيَدٍ قَوِيَّةٍ،', 'خروج 3:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 20, 'فَأَمُدُّ يَدِي وَأَضْرِبُ مِصْرَ بِكُلِّ عَجَائِبِي الَّتِي أَصْنَعُ فِيهَا. وَبَعْدَ ذَلِكَ يُطْلِقُكُمْ.', 'خروج 3:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 21, 'وَأُعْطِي نِعْمَةً لِهَذَا الشَّعْبِ فِي عُيُونِ الْمِصْرِيِّينَ. فَيَكُونُ حِينَمَا تَمْضُونَ أَنَّكُمْ لَا تَمْضُونَ فَارِغِينَ.', 'خروج 3:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 3, 22, 'بَلْ تَطْلُبُ كُلُّ امْرَأَةٍ مِنْ جَارَتِهَا وَمِنْ نَزِيلَةِ بَيْتِهَا أَمْتِعَةَ فِضَّةٍ وَأَمْتِعَةَ ذَهَبٍ وَثِيَابًا، وَتَضَعُونَهَا عَلَى بَنِيكُمْ وَبَنَاتِكُمْ. فَتَسْلُبُونَ الْمِصْرِيِّينَ».', 'خروج 3:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 1, 'فَأَجَابَ مُوسَى وَقَالَ׃ «وَلَكِنْ هَا هُمْ لَا يُصَدِّقُونَنِي وَلَا يَسْمَعُونَ لِقَوْلِي، بَلْ يَقُولُونَ׃ لَمْ يَظْهَرْ لَكَ الرَّبُّ».', 'خروج 4:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 2, 'فَقَالَ لَهُ الرَّبُّ׃ «مَا هَذِهِ فِي يَدِكَ؟» فَقَالَ׃ «عَصًا».', 'خروج 4:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 3, 'فَقَالَ׃ «اطْرَحْهَا إِلَى الْأَرْضِ». فَطَرَحَهَا إِلَى الْأَرْضِ فَصَارَتْ حَيَّةً، فَهَرَبَ مُوسَى مِنْهَا.', 'خروج 4:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 4, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «مُدَّ يَدَكَ وَأَمْسِكْ بِذَنَبِهَا». فَمَدَّ يَدَهُ وَأَمْسَكَ بِهِ، فَصَارَتْ عَصًا فِي يَدِهِ.', 'خروج 4:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 5, '«لِكَيْ يُصَدِّقُوا أَنَّهُ قَدْ ظَهَرَ لَكَ الرَّبُّ إِلَهُ آبَائِهِمْ، إِلَهُ إِبْرَاهِيمَ وَإِلَهُ إِسْحَاقَ وَإِلَهُ يَعْقُوبَ».', 'خروج 4:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 6, 'ثُمَّ قَالَ لَهُ الرَّبُّ أَيْضًا׃ «أَدْخِلْ يَدَكَ فِي عُبِّكَ». فَأَدْخَلَ يَدَهُ فِي عُبِّهِ ثُمَّ أَخْرَجَهَا، وَإِذَا يَدُهُ بَرْصَاءُ مِثْلَ الثَّلْجِ.', 'خروج 4:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 7, 'ثُمَّ قَالَ لَهُ׃ «رُدَّ يَدَكَ إِلَى عُبِّكَ». فَرَدَّ يَدَهُ إِلَى عُبِّهِ ثُمَّ أَخْرَجَهَا مِنْ عُبِّهِ، وَإِذَا هِيَ قَدْ عَادَتْ مِثْلَ جَسَدِهِ.', 'خروج 4:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 8, '«فَيَكُونُ إِذَا لَمْ يُصَدِّقُوكَ وَلَمْ يَسْمَعُوا لِصَوْتِ الْآيَةِ الْأُولَى، أَنَّهُمْ يُصَدِّقُونَ صَوْتَ الْآيَةِ الْأَخِيرَةِ.', 'خروج 4:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 9, 'وَيَكُونُ إِذَا لَمْ يُصَدِّقُوا هَاتَيْنِ الْآيَتَيْنِ، وَلَمْ يَسْمَعُوا لِقَوْلِكَ، أَنَّكَ تَأْخُذُ مِنْ مَاءِ النَّهْرِ وَتَسْكُبُ عَلَى الْيَابِسَةِ، فَيَصِيرُ الْمَاءُ الَّذِي تَأْخُذُهُ مِنَ النَّهْرِ دَمًا عَلَى الْيَابِسَةِ».', 'خروج 4:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 10, 'فَقَالَ مُوسَى لِلرَّبِّ׃ «اسْتَمِعْ أَيُّهَا السَّيِّدُ، لَسْتُ أَنَا صَاحِبَ كَلَامٍ مُنْذُ أَمْسِ وَلَا أَوَّلِ مِنْ أَمْسِ، وَلَا مِنْ حِينِ كَلَّمْتَ عَبْدَكَ، بَلْ أَنَا ثَقِيلُ الْفَمِ وَاللِّسَانِ».', 'خروج 4:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 11, 'فَقَالَ لَهُ الرَّبُّ׃ «مَنْ صَنَعَ لِلْإِنْسَانِ فَمًا؟ أَوْ مَنْ يَصْنَعُ أَخْرَسَ أَوْ أَصَمَّ أَوْ بَصِيرًا أَوْ أَعْمَى؟ أَمَا هُوَ أَنَا الرَّبُّ؟', 'خروج 4:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 12, 'فَالْآنَ اذْهَبْ وَأَنَا أَكُونُ مَعَ فَمِكَ وَأُعَلِّمُكَ مَا تَتَكَلَّمُ بِهِ».', 'خروج 4:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 13, 'فَقَالَ׃ «اسْتَمِعْ أَيُّهَا السَّيِّدُ، أَرْسِلْ بِيَدِ مَنْ تُرْسِلُ».', 'خروج 4:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 14, 'فَحَمِيَ غَضَبُ الرَّبِّ عَلَى مُوسَى وَقَالَ׃ «أَلَيْسَ هَارُونُ اللَّاوِيُّ أَخَاكَ؟ أَنَا أَعْلَمُ أَنَّهُ هُوَ يَتَكَلَّمُ، وَأَيْضًا هَا هُوَ خَارِجٌ لِاسْتِقْبَالِكَ. فَحِينَمَا يَرَاكَ يَفْرَحُ بِقَلْبِهِ،', 'خروج 4:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 15, 'فَتُكَلِّمُهُ وَتَضَعُ الْكَلِمَاتِ فِي فَمِهِ، وَأَنَا أَكُونُ مَعَ فَمِكَ وَمَعَ فَمِهِ، وَأُعْلِمُكُمَا مَاذَا تَصْنَعَانِ.', 'خروج 4:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 16, 'وَهُوَ يُكَلِّمُ الشَّعْبَ عَنْكَ. وَهُوَ يَكُونُ لَكَ فَمًا، وَأَنْتَ تَكُونُ لَهُ إِلَهًا.', 'خروج 4:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 17, 'وَتَأْخُذُ فِي يَدِكَ هَذِهِ الْعَصَا الَّتِي تَصْنَعُ بِهَا الْآيَاتِ».', 'خروج 4:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 18, 'فَمَضَى مُوسَى وَرَجَعَ إِلَى يَثْرُونَ حَمِيهِ وَقَالَ لَهُ׃ «أَنَا أَذْهَبُ وَأَرْجِعُ إِلَى إِخْوَتِي الَّذِينَ فِي مِصْرَ لِأَرَى هَلْ هُمْ بَعْدُ أَحْيَاءٌ». فَقَالَ يَثْرُونُ لِمُوسَى׃ «اذْهَبْ بِسَلَامٍ».', 'خروج 4:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 19, 'وَقَالَ الرَّبُّ لِمُوسَى فِي مِدْيَانَ׃ «اذْهَبْ ارْجِعْ إِلَى مِصْرَ، لِأَنَّهُ قَدْ مَاتَ جَمِيعُ الْقَوْمِ الَّذِينَ كَانُوا يَطْلُبُونَ نَفْسَكَ».', 'خروج 4:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 20, 'فَأَخَذَ مُوسَى امْرَأَتَهُ وَبَنِيهِ وَأَرْكَبَهُمْ عَلَى الْحَمِيرِ وَرَجَعَ إِلَى أَرْضِ مِصْرَ. وَأَخَذَ مُوسَى عَصَا اللهِ فِي يَدِهِ.', 'خروج 4:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 21, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «عِنْدَمَا تَذْهَبُ لِتَرْجِعَ إِلَى مِصْرَ، انْظُرْ جَمِيعَ الْعَجَائِبِ الَّتِي جَعَلْتُهَا فِي يَدِكَ وَاصْنَعْهَا قُدَّامَ فِرْعَوْنَ. وَلَكِنِّي أُشَدِّدُ قَلْبَهُ حَتَّى لَا يُطْلِقَ الشَّعْبَ.', 'خروج 4:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 22, 'فَتَقُولُ لِفِرْعَوْنَ׃ هَكَذَا يَقُولُ الرَّبُّ׃ إِسْرَائِيلُ ابْنِي الْبِكْرُ.', 'خروج 4:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 23, 'فَقُلْتُ لَكَ׃ أَطْلِقِ ابْنِي لِيَعْبُدَنِي، فَأَبَيْتَ أَنْ تُطْلِقَهُ. هَا أَنَا أَقْتُلُ ابْنَكَ الْبِكْرَ».', 'خروج 4:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 24, 'وَحَدَثَ فِي الطَّرِيقِ فِي الْمَنْزِلِ أَنَّ الرَّبَّ الْتَقَاهُ وَطَلَبَ أَنْ يَقْتُلَهُ.', 'خروج 4:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 25, 'فَأَخَذَتْ صَفُّورَةُ صَوَّانَةً وَقَطَعَتْ غُرْلَةَ ابْنِهَا وَمَسَّتْ رِجْلَيْهِ. فَقَالَتْ׃ «إِنَّكَ عَرِيسُ دَمٍ لِي».', 'خروج 4:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 26, 'فَانْفَكَّ عَنْهُ. حِينَئِذٍ قَالَتْ׃ «عَرِيسُ دَمٍ مِنْ أَجْلِ الْخِتَانِ».', 'خروج 4:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 27, 'وَقَالَ الرَّبُّ لِهَارُونَ׃ «اذْهَبْ إِلَى الْبَرِّيَّةِ لِاسْتِقْبَالِ مُوسَى». فَذَهَبَ وَالْتَقَاهُ فِي جَبَلِ اللهِ وَقَبَّلَهُ.', 'خروج 4:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 28, 'فَأَخْبَرَ مُوسَى هَارُونَ بِجَمِيعِ كَلَامِ الرَّبِّ الَّذِي أَرْسَلَهُ، وَبِكُلِّ الْآيَاتِ الَّتِي أَوْصَاهُ بِهَا.', 'خروج 4:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 29, 'ثُمَّ مَضَى مُوسَى وَهَارُونُ وَجَمَعَا جَمِيعَ شُيُوخِ بَنِي إِسْرَائِيلَ.', 'خروج 4:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 30, 'فَتَكَلَّمَ هَارُونُ بِجَمِيعِ الْكَلَامِ الَّذِي كَلَّمَ الرَّبُّ مُوسَى بِهِ، وَصَنَعَ الْآيَاتِ أَمَامَ عُيُونِ الشَّعْبِ.', 'خروج 4:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 4, 31, 'فَآمَنَ الشَّعْبُ. وَلَمَّا سَمِعُوا أَنَّ الرَّبَّ افْتَقَدَ بَنِي إِسْرَائِيلَ وَأَنَّهُ نَظَرَ مَذَلَّتَهُمْ، خَرُّوا وَسَجَدُوا.', 'خروج 4:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 1, 'وَبَعْدَ ذَلِكَ دَخَلَ مُوسَى وَهَارُونُ وَقَالَا لِفِرْعَوْنَ׃ «هَكَذَا يَقُولُ الرَّبُّ إِلَهُ إِسْرَائِيلَ׃ أَطْلِقْ شَعْبِي لِيُعَيِّدُوا لِي فِي الْبَرِّيَّةِ».', 'خروج 5:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 2, 'فَقَالَ فِرْعَوْنُ׃ «مَنْ هُوَ الرَّبُّ حَتَّى أَسْمَعَ لِقَوْلِهِ فَأُطْلِقَ إِسْرَائِيلَ؟ لَا أَعْرِفُ الرَّبَّ، وَإِسْرَائِيلَ لَا أُطْلِقُهُ».', 'خروج 5:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 3, 'فَقَالَا׃ «إِلَهُ الْعِبْرَانِيِّينَ قَدِ الْتَقَانَا، فَنَذْهَبُ سَفَرَ ثَلَاثَةِ أَيَّامٍ فِي الْبَرِّيَّةِ وَنَذْبَحُ لِلرَّبِّ إِلَهِنَا، لِئَلَّا يُصِيبَنَا بِالْوَبَإِ أَوْ بِالسَّيْفِ».', 'خروج 5:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 4, 'فَقَالَ لَهُمَا مَلِكُ مِصْرَ׃ «لِمَاذَا يَا مُوسَى وَهَارُونُ تُبَطِّلَانِ الشَّعْبَ مِنْ أَعْمَالِهِ؟ اِذْهَبَا إِلَى أَثْقَالِكُمَا».', 'خروج 5:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 5, 'وَقَالَ فِرْعَوْنُ׃ «هُوَذَا الْآنَ شَعْبُ الْأَرْضِ كَثِيرٌ وَأَنْتُمَا تُرِيحَانِهِمْ مِنْ أَثْقَالِهِمْ».', 'خروج 5:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 6, 'فَأَمَرَ فِرْعَوْنُ فِي ذَلِكَ الْيَوْمِ مُسَخِّرِي الشَّعْبِ وَمُدَبِّرِيهِ قَائِلًا׃', 'خروج 5:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 7, '«لَا تَعُودُوا تُعْطُونَ الشَّعْبَ تِبْنًا لِصُنْعِ اللِّبْنِ كَأَمْسِ وَأَوَّلَ مِنْ أَمْسِ. لِيَذْهَبُوا هُمْ وَيَجْمَعُوا تِبْنًا لِأَنْفُسِهِمْ.', 'خروج 5:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 8, 'وَمِقْدَارَ اللِّبْنِ الَّذِي كَانُوا يَصْنَعُونَهُ أَمْسِ، وَأَوَّلَ مِنْ أَمْسِ تَجْعَلُونَ عَلَيْهِمْ. لَا تَنْقُصُوا مِنْهُ، فَإِنَّهُمْ مُتَكَاسِلُونَ، لِذَلِكَ يَصْرُخُونَ قَائِلِينَ׃ نَذْهَبُ وَنَذْبَحُ لِإِلَهِنَا.', 'خروج 5:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 9, 'لِيُثَقَّلِ الْعَمَلُ عَلَى الْقَوْمِ حَتَّى يَشْتَغِلُوا بِهِ وَلَا يَلْتَفِتُوا إِلَى كَلَامِ الْكَذِبِ».', 'خروج 5:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 10, 'فَخَرَجَ مُسَخِّرُو الشَّعْبِ وَمُدَبِّرُوهُ وَكَلَّمُوا الشَّعْبَ، قَائِلِينَ׃ «هَكَذَا يَقُولُ فِرْعَوْنُ׃ لَسْتُ أُعْطِيكُمْ تِبْنًا.', 'خروج 5:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 11, 'اذْهَبُوا أَنْتُمْ وَخُذُوا لِأَنْفُسِكُمْ تِبْنًا مِنْ حَيْثُ تَجِدُونَ. إِنَّهُ لَا يُنْقَصُ مِنْ عَمَلِكُمْ شَيْءٌ».', 'خروج 5:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 12, 'فَتَفَرَّقَ الشَّعْبُ فِي كُلِّ أَرْضِ مِصْرَ لِيَجْمَعُوا قَشًّا عِوَضًا عَنِ التِّبْنِ.', 'خروج 5:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 13, 'وَكَانَ الْمُسَخِّرُونَ يُعَجِّلُونَهُمْ قَائِلِينَ׃ «كَمِّلُوا أَعْمَالَكُمْ، أَمْرَ كُلِّ يَوْمٍ بِيَوْمِهِ، كَمَا كَانَ حِينَمَا كَانَ التِّبْنُ».', 'خروج 5:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 14, 'فَضُرِبَ مُدَبِّرُو بَنِي إِسْرَائِيلَ الَّذِينَ أَقَامَهُمْ عَلَيْهِمْ مُسَخِّرُو فِرْعَوْنَ، وَقِيلَ لَهُمْ׃ «لِمَاذَا لَمْ تُكَمِّلُوا فَرِيضَتَكُمْ مِنْ صُنْعِ اللِّبْنِ أَمْسِ وَالْيَوْمَ كَالْأَمْسِ وَأَوَّلَ مِنْ أَمْسِ؟».', 'خروج 5:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 15, 'فَأَتَى مُدَبِّرُو بَنِي إِسْرَائِيلَ وَصَرَخُوا إِلَى فِرْعَوْنَ قَائِلِينَ׃ «لِمَاذَا تَفْعَلُ هَكَذَا بِعَبِيدِكَ؟', 'خروج 5:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 16, 'اَلتِّبْنُ لَيْسَ يُعْطَى لِعَبِيدِكَ، وَاللِّبْنُ يَقُولُونَ لَنَا׃ اصْنَعُوهُ! وَهُوَذَا عَبِيدُكَ مَضْرُوبُونَ، وَقَدْ أَخْطَأَ شَعْبُكَ».', 'خروج 5:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 17, 'فَقَالَ׃ «مُتَكَاسِلُونَ أَنْتُمْ، مُتَكَاسِلُونَ! لِذَلِكَ تَقُولُونَ׃ نَذْهَبُ وَنَذْبَحُ لِلرَّبِّ.', 'خروج 5:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 18, 'فَالْآنَ اذْهَبُوا اعْمَلُوا. وَتِبْنٌ لَا يُعْطَى لَكُمْ وَمِقْدَارَ اللِّبْنِ تُقَدِّمُونَهُ».', 'خروج 5:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 19, 'فَرَأَى مُدَبِّرُو بَنِي إِسْرَائِيلَ أَنْفُسَهُمْ فِي بَلِيَّةٍ إِذْ قِيلَ لَهُمْ لَا تُنَقِّصُوا مِنْ لِبْنِكُمْ أَمْرَ كُلِّ يَوْمٍ بِيَوْمِهِ.', 'خروج 5:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 20, 'وَصَادَفُوا مُوسَى وَهَارُونَ وَاقِفَيْنِ لِلِقَائِهِمْ حِينَ خَرَجُوا مِنْ لَدُنْ فِرْعَوْنَ.', 'خروج 5:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 21, 'فَقَالُوا لَهُمَا׃ «يَنْظُرُ الرَّبُّ إِلَيْكُمَا وَيَقْضِي، لِأَنَّكُمَا أَنْتَنْتُمَا رَائِحَتَنَا فِي عَيْنَيْ فِرْعَوْنَ وَفِي عُيُونِ عَبِيدِهِ حَتَّى تُعْطِيَا سَيْفًا فِي أَيْدِيهِمْ لِيَقْتُلُونَا».', 'خروج 5:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 22, 'فَرَجَعَ مُوسَى إِلَى الرَّبِّ وَقَالَ׃ «يَا سَيِّدُ، لِمَاذَا أَسَأْتَ إِلَى هَذَا الشَّعْبِ؟ لِمَاذَا أَرْسَلْتَنِي؟', 'خروج 5:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 5, 23, 'فَإِنَّهُ مُنْذُ دَخَلْتُ إِلَى فِرْعَوْنَ لِأَتَكَلَّمَ بِاسْمِكَ، أَسَاءَ إِلَى هَذَا الشَّعْبِ. وَأَنْتَ لَمْ تُخَلِّصْ شَعْبَكَ».', 'خروج 5:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 1, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «الْآنَ تَنْظُرُ مَا أَنَا أَفْعَلُ بِفِرْعَوْنَ. فَإِنَّهُ بِيَدٍ قَوِيَّةٍ يُطْلِقُهُمْ، وَبِيَدٍ قَوِيَّةٍ يَطْرُدُهُمْ مِنْ أَرْضِهِ».', 'خروج 6:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 2, 'ثُمَّ كَلَّمَ اللهُ مُوسَى وَقَالَ لَهُ׃ «أَنَا الرَّبُّ.', 'خروج 6:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 3, 'وَأَنَا ظَهَرْتُ لِإِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ بِأَنِّي الْإِلَهُ الْقَادِرُ عَلَى كُلِّ شَيْءٍ. وَأَمَّا بِاسْمِي «يَهْوَهْ» فَلَمْ أُعْرَفْ عِنْدَهُمْ.', 'خروج 6:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 4, 'وَأَيْضًا أَقَمْتُ مَعَهُمْ عَهْدِي׃ أَنْ أُعْطِيَهُمْ أَرْضَ كَنْعَانَ أَرْضَ غُرْبَتِهِمِ الَّتِي تَغَرَّبُوا فِيهَا.', 'خروج 6:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 5, 'وَأَنَا أَيْضًا قَدْ سَمِعْتُ أَنِينَ بَنِي إِسْرَائِيلَ الَّذِينَ يَسْتَعْبِدُهُمُ الْمِصْرِيُّونَ، وَتَذَكَّرْتُ عَهْدِي.', 'خروج 6:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 6, 'لِذَلِكَ قُلْ لِبَنِي إِسْرَائِيلَ׃ أَنَا الرَّبُّ. وَأَنَا أُخْرِجُكُمْ مِنْ تَحْتِ أَثْقَالِ الْمِصْرِيِّينَ وَأُنْقِذُكُمْ مِنْ عُبُودِيَّتِهِمْ وَأُخَلِّصُكُمْ بِذِرَاعٍ مَمْدُودَةٍ وَبِأَحْكَامٍ عَظِيمَةٍ،', 'خروج 6:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 7, 'وَأَتَّخِذُكُمْ لِي شَعْبًا، وَأَكُونُ لَكُمْ إِلَهًا. فَتَعْلَمُونَ أَنِّي أَنَا الرَّبُّ إِلَهُكُمُ الَّذِي يُخْرِجُكُمْ مِنْ تَحْتِ أَثْقَالِ الْمِصْرِيِّينَ.', 'خروج 6:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 8, 'وَأُدْخِلُكُمْ إِلَى الْأَرْضِ الَّتِي رَفَعْتُ يَدِي أَنْ أُعْطِيَهَا لِإِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ. وَأُعْطِيَكُمْ إِيَّاهَا مِيرَاثًا. أَنَا الرَّبُّ».', 'خروج 6:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 9, 'فَكَلَّمَ مُوسَى هَكَذَا بَنِي إِسْرَائِيلَ، وَلَكِنْ لَمْ يَسْمَعُوا لِمُوسَى مِنْ صِغَرِ النَّفْسِ، وَمِنَ الْعُبُودِيَّةِ الْقَاسِيَةِ.', 'خروج 6:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 10, 'ثُمَّ كَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 6:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 11, '«اُدْخُلْ قُلْ لِفِرْعَوْنَ مَلِكِ مِصْرَ أَنْ يُطْلِقَ بَنِي إِسْرَائِيلَ مِنْ أَرْضِهِ».', 'خروج 6:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 12, 'فَتَكَلَّمَ مُوسَى أَمَامَ الرَّبِّ قَائِلًا׃ «هُوَذَا بَنُو إِسْرَائِيلَ لَمْ يَسْمَعُوا لِي، فَكَيْفَ يَسْمَعُنِي فِرْعَوْنُ وَأَنَا أَغْلَفُ الشَّفَتَيْنِ؟»', 'خروج 6:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 13, 'فَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ، وَأَوْصَى مَعَهُمَا إِلَى بَنِي إِسْرَائِيلَ وَإِلَى فِرْعَوْنَ مَلِكِ مِصْرَ فِي إِخْرَاجِ بَنِي إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ.', 'خروج 6:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 14, 'هَؤُلَاءِ رُؤَسَاءُ بُيُوتِ آبَائِهِمْ׃ بَنُو رَأُوبَيْنَ بِكْرِ إِسْرَائِيلَ׃ حَنُوكُ وَفَلُّو وَحَصْرُونُ وَكَرْمِي. هَذِهِ عَشَائِرُ رَأُوبَيْنَ.', 'خروج 6:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 15, 'وَبَنُو شِمْعُونَ׃ يَمُوئِيلُ وَيَامِينُ وَأُوهَدُ وَيَاكِينُ وَصُوحَرُ وَشَأُولُ ابْنُ الْكَنْعَانِيَّةِ. هَذِهِ عَشَائِرُ شِمْعُونَ.', 'خروج 6:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 16, 'وَهَذِهِ أَسْمَاءُ بَنِي لَاوِي بِحَسَبِ مَوَالِيدِهِمْ׃ جِرْشُونُ وَقَهَاتُ وَمَرَارِي. وَكَانَتْ سِنُو حَيَاةِ لَاوِي مِئَةً وَسَبْعًا وَثَلَاثِينَ سَنَةً.', 'خروج 6:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 17, 'اِبْنَا جِرْشُونَ׃ لِبْنِي وَشِمْعِي بِحَسَبِ عَشَائِرِهِمَا.', 'خروج 6:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 18, 'وَبَنُو قَهَاتَ׃ عَمْرَامُ وَيِصْهَارُ وَحَبْرُونُ وَعُزِّيئِيلُ. وَكَانَتْ سِنُو حَيَاةِ قَهَاتَ مِئَةً وَثَلَاثًا وَثَلَاثِينَ سَنَةً.', 'خروج 6:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 19, 'وَابْنَا مَرَارِي׃ مَحْلِي وَمُوشِي. هَذِهِ عَشَائِرُ اللَّاوِيِّينَ بِحَسَبِ مَوَالِيدِهِمْ.', 'خروج 6:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 20, 'وَأَخَذَ عَمْرَامُ يُوكَابَدَ عَمَّتَهُ زَوْجَةً لَهُ. فَوَلَدَتْ لَهُ هَارُونَ وَمُوسَى. وَكَانَتْ سِنُو حَيَاةِ عَمْرَامَ مِئَةً وَسَبْعًا وَثَلَاثِينَ سَنَةً.', 'خروج 6:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 21, 'وَبَنُو يِصْهَارَ׃ قُورَحُ وَنَافَجُ وَذِكْرِي.', 'خروج 6:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 22, 'وَبَنُو عُزِّيئِيلَ׃ مِيشَائِيلُ وَأَلْصَافَانُ وَسِتْرِي.', 'خروج 6:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 23, 'وَأَخَذَ هَارُونُ أَلِيشَابَعَ بِنْتَ عَمِّينَادَابَ أُخْتَ نَحْشُونَ زَوْجَةً لَهُ، فَوَلَدَتْ لَهُ نَادَابَ وَأَبِيهُوَ وَأَلِعَازَارَ وَإِيثَامَارَ.', 'خروج 6:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 24, 'وَبَنُو قُورَحَ׃ أَسِّيرُ وَأَلْقَانَةُ وَأَبِيَأَسَافُ. هَذِهِ عَشَائِرُ الْقُورَحِيِّينَ.', 'خروج 6:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 25, 'وَأَلِعَازَارُ بْنُ هَارُونَ أَخَذَ لِنَفْسِهِ مِنْ بَنَاتِ فُوطِيئِيلَ زَوْجَةً، فَوَلَدَتْ لَهُ فِينَحَاسَ. هَؤُلَاءِ هُمْ رُؤَسَاءُ آبَاءِ اللَّاوِيِّينَ بِحَسَبِ عَشَائِرِهِمْ.', 'خروج 6:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 26, 'هَذَانِ هُمَا هَارُونُ وَمُوسَى اللَّذَانِ قَالَ الرَّبُّ لَهُمَا׃ «أَخْرِجَا بَنِي إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ» بِحَسَبِ أَجْنَادِهِمْ.', 'خروج 6:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 27, 'هُمَا اللَّذَانِ كَلَّمَا فِرْعَوْنَ مَلِكَ مِصْرَ فِي إِخْرَاجِ بَنِي إِسْرَائِيلَ مِنْ مِصْرَ. هَذَانِ هُمَا مُوسَى وَهَارُونُ.', 'خروج 6:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 28, 'وَكَانَ يَوْمَ كَلَّمَ الرَّبُّ مُوسَى فِي أَرْضِ مِصْرَ', 'خروج 6:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 29, 'أَنَّ الرَّبَّ كَلَّمَهُ قَائِلًا׃ «أَنَا الرَّبُّ. كَلِّمْ فِرْعَوْنَ مَلِكَ مِصْرَ بِكُلِّ مَا أَنَا أُكَلِّمُكَ بِهِ».', 'خروج 6:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 6, 30, 'فَقَالَ مُوسَى أَمَامَ الرَّبِّ׃ «هَا أَنَا أَغْلَفُ الشَّفَتَيْنِ. فَكَيْفَ يَسْمَعُ لِي فِرْعَوْنُ؟».', 'خروج 6:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 1, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «انْظُرْ! أَنَا جَعَلْتُكَ إِلَهًا لِفِرْعَوْنَ. وَهَارُونُ أَخُوكَ يَكُونُ نَبِيَّكَ.', 'خروج 7:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 2, 'أَنْتَ تَتَكَلَّمُ بِكُلِّ مَا آمُرُكَ، وَهَارُونُ أَخُوكَ يُكَلِّمُ فِرْعَوْنَ لِيُطْلِقَ بَنِي إِسْرَائِيلَ مِنْ أَرْضِهِ.', 'خروج 7:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 3, 'وَلَكِنِّي أُقَسِّي قَلْبَ فِرْعَوْنَ وَأُكَثِّرُ آيَاتِي وَعَجَائِبِي فِي أَرْضِ مِصْرَ.', 'خروج 7:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 4, 'وَلَا يَسْمَعُ لَكُمَا فِرْعَوْنُ حَتَّى أَجْعَلَ يَدِي عَلَى مِصْرَ، فَأُخْرِجَ أَجْنَادِي، شَعْبِي بَنِي إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ بِأَحْكَامٍ عَظِيمَةٍ.', 'خروج 7:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 5, 'فَيَعْرِفُ الْمِصْرِيُّونَ أَنِّي أَنَا الرَّبُّ حِينَمَا أَمُدُّ يَدِي عَلَى مِصْرَ وَأُخْرِجُ بَنِي إِسْرَائِيلَ مِنْ بَيْنِهِمْ».', 'خروج 7:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 6, 'فَفَعَلَ مُوسَى وَهَارُونُ كَمَا أَمَرَهُمَا الرَّبُّ. هَكَذَا فَعَلَا.', 'خروج 7:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 7, 'وَكَانَ مُوسَى ابْنَ ثَمَانِينَ سَنَةً، وَهَارُونُ ابْنَ ثَلَاثٍ وَثَمَانِينَ سَنَةً حِينَ كَلَّمَا فِرْعَوْنَ.', 'خروج 7:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 8, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'خروج 7:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 9, '«إِذَا كَلَّمَكُمَا فِرْعَوْنُ قَائِلًا׃ هَاتِيَا عَجِيبَةً، تَقُولُ لِهَارُونَ׃ خُذْ عَصَاكَ وَاطْرَحْهَا أَمَامَ فِرْعَوْنَ فَتَصِيرَ ثُعْبَانًا».', 'خروج 7:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 10, 'فَدَخَلَ مُوسَى وَهَارُونُ إِلَى فِرْعَوْنَ وَفَعَلَا هَكَذَا كَمَا أَمَرَ الرَّبُّ. طَرَحَ هَارُونُ عَصَاهُ أَمَامَ فِرْعَوْنَ وَأَمَامَ عَبِيدِهِ فَصَارَتْ ثُعْبَانًا.', 'خروج 7:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 11, 'فَدَعَا فِرْعَوْنُ أَيْضًا الْحُكَمَاءَ وَالسَّحَرَةَ، فَفَعَلَ عَرَّافُو مِصْرَ أَيْضًا بِسِحْرِهِمْ كَذَلِكَ.', 'خروج 7:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 12, 'طَرَحُوا كُلُّ وَاحِدٍ عَصَاهُ فَصَارَتِ الْعِصِيُّ ثَعَابِينَ. وَلَكِنْ عَصَا هَارُونَ ابْتَلَعَتْ عِصِيَّهُمْ.', 'خروج 7:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 13, 'فَاشْتَدَّ قَلْبُ فِرْعَوْنَ فَلَمْ يَسْمَعْ لَهُمَا، كَمَا تَكَلَّمَ الرَّبُّ.', 'خروج 7:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 14, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «قَلْبُ فِرْعَوْنَ غَلِيظٌ. قَدْ أَبَى أَنْ يُطْلِقَ الشَّعْبَ.', 'خروج 7:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 15, 'اِذْهَبْ إِلَى فِرْعَوْنَ فِي الصَّبَاحِ. إِنَّهُ يَخْرُجُ إِلَى الْمَاءِ، وَقِفْ لِلِقَائِهِ عَلَى حَافَةِ النَّهْرِ. وَالْعَصَا الَّتِي تَحَوَّلَتْ حَيَّةً تَأْخُذُهَا فِي يَدِكَ.', 'خروج 7:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 16, 'وَتَقُولُ لَهُ׃ الرَّبُّ إِلَهُ الْعِبْرَانِيِّينَ أَرْسَلَنِي إِلَيْكَ قَائِلًا׃ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي فِي الْبَرِّيَّةِ. وَهُوَذَا حَتَّى الْآنَ لَمْ تَسْمَعْ.', 'خروج 7:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 17, 'هَكَذَا يَقُولُ الرَّبُّ׃ بِهَذَا تَعْرِفُ أَنِّي أَنَا الرَّبُّ׃ هَا أَنَا أَضْرِبُ بِالْعَصَا الَّتِي فِي يَدِي عَلَى الْمَاءِ الَّذِي فِي النَّهْرِ فَيَتَحَوَّلُ دَمًا.', 'خروج 7:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 18, 'وَيَمُوتُ السَّمَكُ الَّذِي فِي النَّهْرِ وَيَنْتِنُ النَّهْرُ. فَيَعَافُ الْمِصْرِيُّونَ أَنْ يَشْرَبُوا مَاءً مِنَ النَّهْرِ».', 'خروج 7:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 19, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «قُلْ لِهَارُونَ׃ خُذْ عَصَاكَ وَمُدَّ يَدَكَ عَلَى مِيَاهِ الْمِصْرِيِّينَ، عَلَى أَنْهَارِهِمْ وَعَلَى سَوَاقِيهِمْ، وَعَلَى آجَامِهِمْ، وَعَلَى كُلِّ مُجْتَمَعَاتِ مِيَاهِهِمْ لِتَصِيرَ دَمًا. فَيَكُونَ دَمٌ فِي كُلِّ أَرْضِ مِصْرَ فِي الْأَخْشَابِ وَفِي الْأَحْجَارِ».', 'خروج 7:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 20, 'فَفَعَلَ هَكَذَا مُوسَى وَهَارُونُ كَمَا أَمَرَ الرَّبُّ. رَفَعَ الْعَصَا وَضَرَبَ الْمَاءَ الَّذِي فِي النَّهْرِ أَمَامَ عَيْنَيْ فِرْعَوْنَ وَأَمَامَ عُيُونِ عَبِيدِهِ، فَتَحَوَّلَ كُلُّ الْمَاءِ الَّذِي فِي النَّهْرِ دَمًا.', 'خروج 7:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 21, 'وَمَاتَ السَّمَكُ الَّذِي فِي النَّهْرِ وَأَنْتَنَ النَّهْرُ، فَلَمْ يَقْدِرِ الْمِصْرِيُّونَ أَنْ يَشْرَبُوا مَاءً مِنَ النَّهْرِ. وَكَانَ الدَّمُ فِي كُلِّ أَرْضِ مِصْرَ.', 'خروج 7:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 22, 'وَفَعَلَ عَرَّافُو مِصْرَ كَذَلِكَ بِسِحْرِهِمْ. فَاشْتَدَّ قَلْبُ فِرْعَوْنَ فَلَمْ يَسْمَعْ لَهُمَا، كَمَا تَكَلَّمَ الرَّبُّ.', 'خروج 7:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 23, 'ثُمَّ انْصَرَفَ فِرْعَوْنُ وَدَخَلَ بَيْتَهُ وَلَمْ يُوَجِّهْ قَلْبَهُ إِلَى هَذَا أَيْضًا.', 'خروج 7:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 24, 'وَحَفَرَ جَمِيعُ الْمِصْرِيِّينَ حَوَالَيِ النَّهْرِ لِأَجْلِ مَاءٍ لِيَشْرَبُوا، لِأَنَّهُمْ لَمْ يَقْدِرُوا أَنْ يَشْرَبُوا مِنْ مَاءِ النَّهْرِ.', 'خروج 7:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 7, 25, 'وَكَمُلَتْ سَبْعَةُ أَيَّامٍ بَعْدَ مَا ضَرَبَ الرَّبُّ النَّهْرَ.', 'خروج 7:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 1, 'قَالَ الرَّبُّ لِمُوسَى׃ «ادْخُلْ إِلَى فِرْعَوْنَ وَقُلْ لَهُ׃ هَكَذَا يَقُولُ الرَّبُّ׃ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي.', 'خروج 8:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 2, 'وَإِنْ كُنْتَ تَأْبَى أَنْ تُطْلِقَهُمْ فَهَا أَنَا أَضْرِبُ جَمِيعَ تُخُومِكَ بِالضَّفَادِعِ.', 'خروج 8:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 3, 'فَيَفِيضُ النَّهْرُ ضَفَادِعَ. فَتَصْعَدُ وَتَدْخُلُ إِلَى بَيْتِكَ وَإِلَى مِخْدَعِ فِرَاشِكَ وَعَلَى سَرِيرِكَ وَإِلَى بُيُوتِ عَبِيدِكَ وَعَلَى شَعْبِكَ وَإِلَى تَنَانِيرِكَ وَإِلَى مَعَاجِنِكَ.', 'خروج 8:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 4, 'عَلَيْكَ وَعَلَى شَعْبِكَ وَعَبِيدِكَ تَصْعَدُ الضَّفَادِعُ».', 'خروج 8:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 5, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «قُلْ لِهَارُونَ׃ مُدَّ يَدَكَ بِعَصَاكَ عَلَى الْأَنْهَارِ وَالسَّوَاقِي وَالْآجَامِ، وَأَصْعِدِ الضَّفَادِعَ عَلَى أَرْضِ مِصْرَ».', 'خروج 8:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 6, 'فَمَدَّ هَارُونُ يَدَهُ عَلَى مِيَاهِ مِصْرَ، فَصَعِدَتِ الضَّفَادِعُ وَغَطَّتْ أَرْضَ مِصْرَ.', 'خروج 8:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 7, 'وَفَعَلَ كَذَلِكَ الْعَرَّافُونَ بِسِحْرِهِمْ وَأَصْعَدُوا الضَّفَادِعَ عَلَى أَرْضِ مِصْرَ.', 'خروج 8:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 8, 'فَدَعَا فِرْعَوْنُ مُوسَى وَهَارُونَ وَقَالَ׃ «صَلِّيَا إِلَى الرَّبِّ لِيَرْفَعَ الضَّفَادِعَ عَنِّي وَعَنْ شَعْبِي فَأُطْلِقَ الشَّعْبَ لِيَذْبَحُوا لِلرَّبِّ».', 'خروج 8:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 9, 'فَقَالَ مُوسَى لِفِرْعَوْنَ׃ «عَيِّنْ لِي مَتَى أُصَلِّي لِأَجْلِكَ وَلِأَجْلِ عَبِيدِكَ وَشَعْبِكَ لِقَطْعِ الضَّفَادِعِ عَنْكَ وَعَنْ بُيُوتِكَ. وَلَكِنَّهَا تَبْقَى فِي النَّهْرِ».', 'خروج 8:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 10, 'فَقَالَ׃ «غَدًا». فَقَالَ׃ «كَقَوْلِكَ. لِكَيْ تَعْرِفَ أَنْ لَيْسَ مِثْلُ الرَّبِّ إِلَهِنَا.', 'خروج 8:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 11, 'فَتَرْتَفِعُ الضَّفَادِعُ عَنْكَ وَعَنْ بُيُوتِكَ وَعَبِيدِكَ وَشَعْبِكَ، وَلَكِنَّهَا تَبْقَى فِي النَّهْرِ».', 'خروج 8:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 12, 'ثُمَّ خَرَجَ مُوسَى وَهَارُونُ مِنْ لَدُنْ فِرْعَوْنَ، وَصَرَخَ مُوسَى إِلَى الرَّبِّ مِنْ أَجْلِ الضَّفَادِعِ الَّتِي جَعَلَهَا عَلَى فِرْعَوْنَ،', 'خروج 8:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 13, 'فَفَعَلَ الرَّبُّ كَقَوْلِ مُوسَى. فَمَاتَتِ الضَّفَادِعُ مِنَ الْبُيُوتِ وَالدُّورِ وَالْحُقُولِ.', 'خروج 8:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 14, 'وَجَمَعُوهَا كُوَمًا كَثِيرَةً حَتَّى أَنْتَنَتِ الْأَرْضُ.', 'خروج 8:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 15, 'فَلَمَّا رَأَى فِرْعَوْنُ أَنَّهُ قَدْ حَصَلَ الْفَرَجُ أَغْلَظَ قَلْبَهُ وَلَمْ يَسْمَعْ لَهُمَا، كَمَا تَكَلَّمَ الرَّبُّ.', 'خروج 8:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 16, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «قُلْ لِهَارُونَ׃ مُدَّ عَصَاكَ وَاضْرِبْ تُرَابَ الْأَرْضِ لِيَصِيرَ بَعُوضًا فِي جَمِيعِ أَرْضِ مِصْرَ».', 'خروج 8:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 17, 'فَفَعَلَا كَذَلِكَ. مَدَّ هَارُونُ يَدَهُ بِعَصَاهُ وَضَرَبَ تُرَابَ الْأَرْضِ، فَصَارَ الْبَعُوضُ عَلَى النَّاسِ وَعَلَى الْبَهَائِمِ. كُلُّ تُرَابِ الْأَرْضِ صَارَ بَعُوضًا فِي جَمِيعِ أَرْضِ مِصْرَ.', 'خروج 8:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 18, 'وَفَعَلَ كَذَلِكَ الْعَرَّافُونَ بِسِحْرِهِمْ لِيُخْرِجُوا الْبَعُوضَ فَلَمْ يَسْتَطِيعُوا. وَكَانَ الْبَعُوضُ عَلَى النَّاسِ وَعَلَى الْبَهَائِمِ.', 'خروج 8:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 19, 'فَقَالَ الْعَرَّافُونَ لِفِرْعَوْنَ׃ «هَذَا إِصْبَعُ اللهِ». وَلَكِنِ اشْتَدَّ قَلْبُ فِرْعَوْنَ فَلَمْ يَسْمَعْ لَهُمَا، كَمَا تَكَلَّمَ الرَّبُّ.', 'خروج 8:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 20, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «بَكِّرْ فِي الصَّبَاحِ وَقِفْ أَمَامَ فِرْعَوْنَ. إِنَّهُ يَخْرُجُ إِلَى الْمَاءِ. وَقُلْ لَهُ׃ هَكَذَا يَقُولُ الرَّبُّ׃ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي.', 'خروج 8:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 21, 'فَإِنَّهُ إِنْ كُنْتَ لَا تُطْلِقُ شَعْبِي، هَا أَنَا أُرْسِلُ عَلَيْكَ وَعَلَى عَبِيدِكَ وَعَلَى شَعْبِكَ وَعَلَى بُيُوتِكَ الذُّبَّانَ، فَتَمْتَلِئُ بُيُوتُ الْمِصْرِيِّينَ ذُبَّانًا. وَأَيْضًا الْأَرْضُ الَّتِي هُمْ عَلَيْهَا.', 'خروج 8:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 22, 'وَلَكِنْ أُمَيِّزُ فِي ذَلِكَ الْيَوْمِ أَرْضَ جَاسَانَ حَيْثُ شَعْبِي مُقِيمٌ حَتَّى لَا يَكُونُ هُنَاكَ ذُبَّانٌ. لِكَيْ تَعْلَمَ أَنِّي أَنَا الرَّبُّ فِي الْأَرْضِ.', 'خروج 8:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 23, 'وَأَجْعَلُ فَرْقًا بَيْنَ شَعْبِي وَشَعْبِكَ. غَدًا تَكُونُ هَذِهِ الْآيَةُ».', 'خروج 8:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 24, 'فَفَعَلَ الرَّبُّ هَكَذَا، فَدَخَلَتْ ذُبَّانٌ كَثِيرَةٌ إِلَى بَيْتِ فِرْعَوْنَ وَبُيُوتِ عَبِيدِهِ. وَفِي كُلِّ أَرْضِ مِصْرَ خَرِبَتِ الْأَرْضُ مِنَ الذُّبَّانِ.', 'خروج 8:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 25, 'فَدَعَا فِرْعَوْنُ مُوسَى وَهَارُونَ وَقَالَ׃ «اذْهَبُوا اذْبَحُوا لِإِلَهِكُمْ فِي هَذِهِ الْأَرْضِ».', 'خروج 8:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 26, 'فَقَالَ مُوسَى׃ «لَا يَصْلَحُ أَنْ نَفْعَلَ هَكَذَا، لِأَنَّنَا إِنَّمَا نَذْبَحُ رِجْسَ الْمِصْرِيِّينَ لِلرَّبِّ إِلَهِنَا. إِنْ ذَبَحْنَا رِجْسَ الْمِصْرِيِّينَ أَمَامَ عُيُونِهِمْ أَفَلَا يَرْجُمُونَنَا؟', 'خروج 8:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 27, 'نَذْهَبُ سَفَرَ ثَلَاثَةِ أَيَّامٍ فِي الْبَرِّيَّةِ وَنَذْبَحُ لِلرَّبِّ إِلَهِنَا كَمَا يَقُولُ لَنَا».', 'خروج 8:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 28, 'فَقَالَ فِرْعَوْنُ׃ «أَنَا أُطْلِقُكُمْ لِتَذْبَحُوا لِلرَّبِّ إِلَهِكُمْ فِي الْبَرِّيَّةِ، وَلَكِنْ لَا تَذْهَبُوا بَعِيدًا. صَلِّيَا لِأَجْلِي».', 'خروج 8:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 29, 'فَقَالَ مُوسَى׃ «هَا أَنَا أَخْرُجُ مِنْ لَدُنْكَ وَأُصَلِّي إِلَى الرَّبِّ، فَتَرْتَفِعُ الذُّبَّانُ عَنْ فِرْعَوْنَ وَعَبِيدِهِ وَشَعْبِهِ غَدًا. وَلَكِنْ لَا يَعُدْ فِرْعَوْنُ يُخَاتِلُ حَتَّى لَا يُطْلِقَ الشَّعْبَ لِيَذْبَحَ لِلرَّبِّ».', 'خروج 8:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 30, 'فَخَرَجَ مُوسَى مِنْ لَدُنْ فِرْعَوْنَ وَصَلَّى إِلَى الرَّبِّ.', 'خروج 8:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 31, 'فَفَعَلَ الرَّبُّ كَقَوْلِ مُوسَى، فَارْتَفَعَ الذُّبَّانُ عَنْ فِرْعَوْنَ وَعَبِيدِهِ وَشَعْبِهِ. لَمْ تَبْقَ وَاحِدَةٌ.', 'خروج 8:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 8, 32, 'وَلَكِنْ أَغْلَظَ فِرْعَوْنُ قَلْبَهُ هَذِهِ الْمَرَّةَ أَيْضًا فَلَمْ يُطْلِقِ الشَّعْبَ.', 'خروج 8:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 1, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «ادْخُلْ إِلَى فِرْعَوْنَ وَقُلْ لَهُ׃ هَكَذَا يَقُولُ الرَّبُّ إِلَهُ الْعِبْرَانِيِّينَ׃ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي.', 'خروج 9:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 2, 'فَإِنَّهُ إِنْ كُنْتَ تَأْبَى أَنْ تُطْلِقَهُمْ وَكُنْتَ تُمْسِكُهُمْ بَعْدُ،', 'خروج 9:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 3, 'فَهَا يَدُ الرَّبِّ تَكُونُ عَلَى مَوَاشِيكَ الَّتِي فِي الْحَقْلِ، عَلَى الْخَيْلِ وَالْحَمِيرِ وَالْجِمَالِ وَالْبَقَرِ وَالْغَنَمِ، وَبَأً ثَقِيلًا جِدًّا.', 'خروج 9:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 4, 'وَيُمَيِّزُ الرَّبُّ بَيْنَ مَوَاشِي إِسْرَائِيلَ وَمَوَاشِي الْمِصْرِيِّينَ. فَلَا يَمُوتُ مِنْ كُلِّ مَا لِبَنِي إِسْرَائِيلَ شَيْءٌ».', 'خروج 9:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 5, 'وَعَيَّنَ الرَّبُّ وَقْتًا قَائِلًا׃ «غَدًا يَفْعَلُ الرَّبُّ هَذَا الْأَمْرَ فِي الْأَرْضِ».', 'خروج 9:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 6, 'فَفَعَلَ الرَّبُّ هَذَا الْأَمْرَ فِي الْغَدِ. فَمَاتَتْ جَمِيعُ مَوَاشِي الْمِصْرِيِّينَ. وَأَمَّا مَوَاشِي بَنِي إِسْرَائِيلَ فَلَمْ يَمُتْ مِنْهَا وَاحِدٌ.', 'خروج 9:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 7, 'وَأَرْسَلَ فِرْعَوْنُ وَإِذَا مَوَاشِي إِسْرَائِيلَ لَمْ يَمُتْ مِنْهَا وَلَا وَاحِدٌ. وَلَكِنْ غَلُظَ قَلْبُ فِرْعَوْنَ فَلَمْ يُطْلِقِ الشَّعْبَ.', 'خروج 9:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 8, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى وَهَارُونَ׃ «خُذَا مِلْءَ أَيْدِيكُمَا مِنْ رَمَادِ الأَتُونِ، وَلْيُذَرِّهِ مُوسَى نَحْوَ السَّمَاءِ أَمَامَ عَيْنَيْ فِرْعَوْنَ،', 'خروج 9:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 9, 'لِيَصِيرَ غُبَارًا عَلَى كُلِّ أَرْضِ مِصْرَ. فَيَصِيرَ عَلَى النَّاسِ وَعَلَى الْبَهَائِمِ دَمَامِلَ طَالِعَةً بِبُثُورٍ فِي كُلِّ أَرْضِ مِصْرَ».', 'خروج 9:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 10, 'فَأَخَذَا رَمَادَ الْأَتُونِ وَوَقَفَا أَمَامَ فِرْعَوْنَ، وَذَرَّاهُ مُوسَى نَحْوَ السَّمَاءِ، فَصَارَ دَمَامِلَ بُثُورٍ طَالِعَةً فِي النَّاسِ وَفِي الْبَهَائِمِ.', 'خروج 9:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 11, 'وَلَمْ يَسْتَطِعِ الْعَرَّافُونَ أَنْ يَقِفُوا أَمَامَ مُوسَى مِنْ أَجْلِ الدَّمَامِلِ، لِأَنَّ الدَّمَامِلَ كَانَتْ فِي الْعَرَّافِينَ وَفِي كُلِّ الْمِصْرِيِّينَ.', 'خروج 9:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 12, 'وَلَكِنْ شَدَّدَ الرَّبُّ قَلْبَ فِرْعَوْنَ فَلَمْ يَسْمَعْ لَهُمَا، كَمَا كَلَّمَ الرَّبُّ مُوسَى.', 'خروج 9:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 13, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «بَكِّرْ فِي الصَّبَاحِ وَقِفْ أَمَامَ فِرْعَوْنَ وَقُلْ لَهُ׃ هَكَذَا يَقُولُ الرَّبُّ إِلَهُ الْعِبْرَانِيِّينَ׃ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي.', 'خروج 9:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 14, 'لِأَنِّي هَذِهِ الْمَرَّةَ أُرْسِلُ جَمِيعَ ضَرَبَاتِي إِلَى قَلْبِكَ وَعَلَى عَبِيدِكَ وَشَعْبِكَ، لِكَيْ تَعْرِفَ أَنْ لَيْسَ مِثْلِي فِي كُلِّ الْأَرْضِ.', 'خروج 9:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 15, 'فَإِنَّهُ الْآنَ لَوْ كُنْتُ أَمُدُّ يَدِي وَأَضْرِبُكَ وَشَعْبَكَ بِالْوَبَإِ، لَكُنْتَ تُبَادُ مِنَ الْأَرْضِ.', 'خروج 9:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 16, 'وَلَكِنْ لِأَجْلِ هَذَا أَقَمْتُكَ، لِكَيْ أُرِيَكَ قُوَّتِي، وَلِكَيْ يُخْبَرَ بِاسْمِي فِي كُلِّ الْأَرْضِ.', 'خروج 9:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 17, 'أَنْتَ مُعَانِدٌ بَعْدُ لِشَعْبِي حَتَّى لَا تُطْلِقَهُ.', 'خروج 9:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 18, 'هَا أَنَا غَدًا مِثْلَ الْآنَ أُمْطِرُ بَرَدًا عَظِيمًا جِدًّا لَمْ يَكُنْ مِثْلُهُ فِي مِصْرَ مُنْذُ يَوْمِ تَأْسِيسِهَا إِلَى الْآنَ.', 'خروج 9:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 19, 'فَالْآنَ أَرْسِلِ احْمِ مَوَاشِيَكَ وَكُلَّ مَا لَكَ فِي الْحَقْلِ. جَمِيعُ النَّاسِ وَالْبَهَائِمِ الَّذِينَ يُوجَدُونَ فِي الْحَقْلِ وَلَا يُجْمَعُونَ إِلَى الْبُيُوتِ، يَنْزِلُ عَلَيْهِمِ الْبَرَدُ فَيَمُوتُونَ».', 'خروج 9:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 20, 'فَالَّذِي خَافَ كَلِمَةَ الرَّبِّ مِنْ عَبِيدِ فِرْعَوْنَ هَرَبَ بِعَبِيدِهِ وَمَوَاشِيهِ إِلَى الْبُيُوتِ.', 'خروج 9:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 21, 'وَأَمَّا الَّذِي لَمْ يُوَجِّهْ قَلْبَهُ إِلَى كَلِمَةِ الرَّبِّ فَتَرَكَ عَبِيدَهُ وَمَوَاشِيَهُ فِي الْحَقْلِ.', 'خروج 9:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 22, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «مُدَّ يَدَكَ نَحْوَ السَّمَاءِ لِيَكُونَ بَرَدٌ فِي كُلِّ أَرْضِ مِصْرَ׃ عَلَى النَّاسِ وَعَلَى الْبَهَائِمِ وَعَلَى كُلِّ عُشْبِ الْحَقْلِ فِي أَرْضِ مِصْرَ».', 'خروج 9:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 23, 'فَمَدَّ مُوسَى عَصَاهُ نَحْوَ السَّمَاءِ، فَأَعْطَى الرَّبُّ رُعُودًا وَبَرَدًا، وَجَرَتْ نَارٌ عَلَى الْأَرْضِ، وَأَمْطَرَ الرَّبُّ بَرَدًا عَلَى أَرْضِ مِصْرَ.', 'خروج 9:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 24, 'فَكَانَ بَرَدٌ، وَنَارٌ مُتَوَاصِلَةٌ فِي وَسَطِ الْبَرَدِ. شَيْءٌ عَظِيمٌ جِدًّا لَمْ يَكُنْ مِثْلُهُ فِي كُلِّ أَرْضِ مِصْرَ مُنْذُ صَارَتْ أُمَّةً.', 'خروج 9:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 25, 'فَضَرَبَ الْبَرَدُ فِي كُلِّ أَرْضِ مِصْرَ جَمِيعَ مَا فِي الْحَقْلِ مِنَ النَّاسِ وَالْبَهَائِمِ. وَضَرَبَ الْبَرَدُ جَمِيعَ عُشْبِ الْحَقْلِ وَكَسَّرَ جَمِيعَ شَجَرِ الْحَقْلِ.', 'خروج 9:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 26, 'إِلَّا أَرْضَ جَاسَانَ حَيْثُ كَانَ بَنُو إِسْرَائِيلَ، فَلَمْ يَكُنْ فِيهَا بَرَدٌ.', 'خروج 9:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 27, 'فَأَرْسَلَ فِرْعَوْنُ وَدَعَا مُوسَى وَهَارُونَ وَقَالَ لَهُمَا׃ «أَخْطَأْتُ هَذِهِ الْمَرَّةَ. الرَّبُّ هُوَ الْبَارُّ وَأَنَا وَشَعْبِي الْأَشْرَارُ.', 'خروج 9:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 28, 'صَلِّيَا إِلَى الرَّبِّ، وَكَفَى حُدُوثُ رُعُودِ اللهِ وَالْبَرَدُ، فَأُطْلِقَكُمْ وَلَا تَعُودُوا تَلْبَثُونَ».', 'خروج 9:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 29, 'فَقَالَ لَهُ مُوسَى׃ «عِنْدَ خُرُوجِي مِنَ الْمَدِينَةِ أَبْسِطُ يَدَيَّ إِلَى الرَّبِّ، فَتَنْقَطِعُ الرُّعُودُ وَلَا يَكُونُ الْبَرَدُ أَيْضًا، لِكَيْ تَعْرِفَ أَنَّ لِلرَّبِّ الْأَرْضَ.', 'خروج 9:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 30, 'وَأَمَّا أَنْتَ وَعَبِيدُكَ فَأَنَا أَعْلَمُ أَنَّكُمْ لَمْ تَخْشَوْا بَعْدُ مِنَ الرَّبِّ الْإِلَهِ».', 'خروج 9:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 31, 'فَالْكَتَّانُ وَالشَّعِيرُ ضُرِبَا. لِأَنَّ الشَّعِيرَ كَانَ مُسْبِلًا وَالْكَتَّانُ مُبْزِرًا.', 'خروج 9:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 32, 'وَأَمَّا الْحِنْطَةُ وَالْقَطَانِيُّ فَلَمْ تُضْرَبْ لِأَنَّهَا كَانَتْ مُتَأَخِّرَةً.', 'خروج 9:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 33, 'فَخَرَجَ مُوسَى مِنَ الْمَدِينَةِ مِنْ لَدُنْ فِرْعَوْنَ وَبَسَطَ يَدَيْهِ إِلَى الرَّبِّ، فَانْقَطَعَتِ الرُّعُودُ وَالْبَرَدُ وَلَمْ يَنْصَبَّ الْمَطَرُ عَلَى الْأَرْضِ.', 'خروج 9:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 34, 'وَلَكِنْ فِرْعَوْنُ لَمَّا رَأَى أَنَّ الْمَطَرَ وَالْبَرَدَ وَالرُّعُودَ انْقَطَعَتْ، عَادَ يُخْطِئُ وَأَغْلَظَ قَلْبَهُ هُوَ وَعَبِيدُهُ.', 'خروج 9:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 9, 35, 'فَاشْتَدَّ قَلْبُ فِرْعَوْنَ فَلَمْ يُطْلِقْ بَنِي إِسْرَائِيلَ، كَمَا تَكَلَّمَ الرَّبُّ عَنْ يَدِ مُوسَى.', 'خروج 9:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 1, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «ادْخُلْ إِلَى فِرْعَوْنَ، فَإِنِّي أَغْلَظْتُ قَلْبَهُ وَقُلُوبَ عَبِيدِهِ لِكَيْ أَصْنَعَ آيَاتِي هَذِهِ بَيْنَهُمْ.', 'خروج 10:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 2, 'وَلِكَيْ تُخْبِرَ فِي مَسَامِعِ ابْنِكَ وَابْنِ ابْنِكَ بِمَا فَعَلْتُهُ فِي مِصْرَ، وَبِآيَاتِي الَّتِي صَنَعْتُهَا بَيْنَهُمْ، فَتَعْلَمُونَ أَنِّي أَنَا الرَّبُّ».', 'خروج 10:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 3, 'فَدَخَلَ مُوسَى وَهَارُونُ إِلَى فِرْعَوْنَ وَقَالَا لَهُ׃ «هَكَذَا يَقُولُ الرَّبُّ إِلَهُ الْعِبْرَانِيِّينَ׃ إِلَى مَتَى تَأْبَى أَنْ تَخْضَعَ لِي؟ أَطْلِقْ شَعْبِي لِيَعْبُدُونِي.', 'خروج 10:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 4, 'فَإِنَّهُ إِنْ كُنْتَ تَأْبَى أَنْ تُطْلِقَ شَعْبِي هَا أَنَا أَجِيءُ غَدًا بِجَرَادٍ عَلَى تُخُومِكَ،', 'خروج 10:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 5, 'فَيُغَطِّي وَجْهَ الْأَرْضِ حَتَّى لَا يُسْتَطَاعَ نَظَرُ الْأَرْضِ. وَيَأْكُلُ الْفَضْلَةَ السَّالِمَةَ الْبَاقِيَةَ لَكُمْ مِنَ الْبَرَدِ. وَيَأْكُلُ جَمِيعَ الشَّجَرِ النَّابِتِ لَكُمْ مِنَ الْحَقْلِ.', 'خروج 10:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 6, 'وَيَمْلَأُ بُيُوتَكَ وَبُيُوتَ جَمِيعِ عَبِيدِكَ وَبُيُوتَ جَمِيعِ الْمِصْرِيِّينَ، الْأَمْرُ الَّذِي لَمْ يَرَهُ آبَاؤُكَ وَلَا آبَاءُ آبَائِكَ مُنْذُ يَوْمَ وُجِدُوا عَلَى الْأَرْضِ إِلَى هَذَا الْيَوْمِ». ثُمَّ تَحَوَّلَ وَخَرَجَ مِنْ لَدُنْ فِرْعَوْنَ.', 'خروج 10:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 7, 'فَقَالَ عَبِيدُ فِرْعَوْنَ لَهُ׃ «إِلَى مَتَى يَكُونُ هَذَا لَنَا فَخًّا؟ أَطْلِقِ الرِّجَالَ لِيَعْبُدُوا الرَّبَّ إِلَهَهُمْ. أَلَمْ تَعْلَمْ بَعْدُ أَنَّ مِصْرَ قَدْ خَرِبَتْ؟».', 'خروج 10:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 8, 'فَرُدَّ مُوسَى وَهَارُونُ إِلَى فِرْعَوْنَ، فَقَالَ لَهُمَا׃ «اذْهَبُوا اعْبُدُوا الرَّبَّ إِلَهَكُمْ. وَلَكِنْ مَنْ وَمَنْ هُمُ الَّذِينَ يَذْهَبُونَ؟»', 'خروج 10:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 9, 'فَقَالَ مُوسَى׃ «نَذْهَبُ بِفِتْيَانِنَا وَشُيُوخِنَا. نَذْهَبُ بِبَنِينَا وَبَنَاتِنَا، بِغَنَمِنَا وَبَقَرِنَا، لِأَنَّ لَنَا عِيدًا لِلرَّبِّ».', 'خروج 10:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 10, 'فَقَالَ لَهُمَا׃ «يَكُونُ الرَّبُّ مَعَكُمْ هَكَذَا كَمَا أُطْلِقُكُمْ وَأَوْلَادَكُمُ. انْظُرُوا، إِنَّ قُدَّامَ وُجُوهِكُمْ شَرًّا.', 'خروج 10:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 11, 'لَيْسَ هَكَذَا. اِذْهَبُوا أَنْتُمُ الرِّجَالَ وَاعْبُدُوا الرَّبَّ. لِأَنَّكُمْ لِهَذَا طَالِبُونَ». فَطُرِدَا مِنْ لَدُنْ فِرْعَوْنَ.', 'خروج 10:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 12, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «مُدَّ يَدَكَ عَلَى أَرْضِ مِصْرَ لِأَجْلِ الْجَرَادِ، لِيَصْعَدَ عَلَى أَرْضِ مِصْرَ وَيَأْكُلَ كُلَّ عُشْبِ الْأَرْضِ، كُلَّ مَا تَرَكَهُ الْبَرَدُ».', 'خروج 10:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 13, 'فَمَدَّ مُوسَى عَصَاهُ عَلَى أَرْضِ مِصْرَ، فَجَلَبَ الرَّبُّ عَلَى الْأَرْضِ رِيحًا شَرْقِيَّةً كُلَّ ذَلِكَ النَّهَارِ وَكُلَّ اللَّيْلِ. وَلَمَّا كَانَ الصَّبَاحُ، حَمَلَتِ الرِّيحُ الشَّرْقِيَّةُ الْجَرَادَ،', 'خروج 10:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 14, 'فَصَعِدَ الْجَرَادُ عَلَى كُلِّ أَرْضِ مِصْرَ، وَحَلَّ فِي جَمِيعِ تُخُومِ مِصْرَ. شَيْءٌ ثَقِيلٌ جِدًّا لَمْ يَكُنْ قَبْلَهُ جَرَادٌ هَكَذَا مِثْلَهُ، وَلَا يَكُونُ بَعْدَهُ كَذَلِكَ،', 'خروج 10:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 15, 'وَغَطَّى وَجْهَ كُلِّ الْأَرْضِ حَتَّى أَظْلَمَتِ الْأَرْضُ. وَأَكَلَ جَمِيعَ عُشْبِ الْأَرْضِ وَجَمِيعَ ثَمَرِ الشَّجَرِ الَّذِي تَرَكَهُ الْبَرَدُ، حَتَّى لَمْ يَبْقَ شَيْءٌ أَخْضَرُ فِي الشَّجَرِ وَلَا فِي عُشْبِ الْحَقْلِ فِي كُلِّ أَرْضِ مِصْرَ».', 'خروج 10:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 16, 'فَدَعَا فِرْعَوْنُ مُوسَى وَهَارُونَ مُسْرِعًا وَقَالَ׃ «أَخْطَأْتُ إِلَى الرَّبِّ إِلَهِكُمَا وَإِلَيْكُمَا.', 'خروج 10:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 17, 'وَالْآنَ اصْفَحَا عَنْ خَطِيَّتِي هَذِهِ الْمَرَّةَ فَقَطْ، وَصَلِّيَا إِلَى الرَّبِّ إِلَهِكُمَا لِيَرْفَعَ عَنِّي هَذَا الْمَوْتَ فَقَطْ».', 'خروج 10:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 18, 'فَخَرَجَ مُوسَى مِنْ لَدُنْ فِرْعَوْنَ وَصَلَّى إِلَى الرَّبِّ.', 'خروج 10:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 19, 'فَرَدَّ الرَّبُّ رِيحًا غَرْبِيَّةً شَدِيدَةً جِدًّا، فَحَمَلَتِ الْجَرَادَ وَطَرَحَتْهُ إِلَى بَحْرِ سُوفَ. لَمْ تَبْقَ جَرَادَةٌ وَاحِدَةٌ فِي كُلِّ تُخُومِ مِصْرَ.', 'خروج 10:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 20, 'وَلَكِنْ شَدَّدَ الرَّبُّ قَلْبَ فِرْعَوْنَ فَلَمْ يُطْلِقْ بَنِي إِسْرَائِيلَ.', 'خروج 10:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 21, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «مُدَّ يَدَكَ نَحْوَ السَّمَاءِ لِيَكُونَ ظَلَامٌ عَلَى أَرْضِ مِصْرَ، حَتَّى يُلْمَسُ الظَّلَامُ».', 'خروج 10:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 22, 'فَمَدَّ مُوسَى يَدَهُ نَحْوَ السَّمَاءِ فَكَانَ ظَلَامٌ دَامِسٌ فِي كُلِّ أَرْضِ مِصْرَ ثَلَاثَةَ أَيَّامٍ.', 'خروج 10:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 23, 'لَمْ يُبْصِرْ أَحَدٌ أَخَاهُ، وَلَا قَامَ أَحَدٌ مِنْ مَكَانِهِ ثَلَاثَةَ أَيَّامٍ. وَلَكِنْ جَمِيعُ بَنِي إِسْرَائِيلَ كَانَ لَهُمْ نُورٌ فِي مَسَاكِنِهِمْ.', 'خروج 10:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 24, 'فَدَعَا فِرْعَوْنُ مُوسَى وَقَالَ׃ «اذْهَبُوا اعْبُدُوا الرَّبَّ. غَيْرَ أَنَّ غَنَمَكُمْ وَبَقَرَكُمْ تَبْقَى. أَوْلَادُكُمْ أَيْضًا تَذْهَبُ مَعَكُمْ».', 'خروج 10:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 25, 'فَقَالَ مُوسَى׃ «أَنْتَ تُعْطِي أَيْضًا فِي أَيْدِينَا ذَبَائِحَ وَمُحْرَقَاتٍ لِنَصْنَعَهَا لِلرَّبِّ إِلَهِنَا،', 'خروج 10:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 26, 'فَتَذْهَبُ مَوَاشِينَا أَيْضًا مَعَنَا. لَا يَبْقَى ظِلْفٌ. لِأَنَّنَا مِنْهَا نَأْخُذُ لِعِبَادَةِ الرَّبِّ إِلَهِنَا. وَنَحْنُ لَا نَعْرِفُ بِمَاذَا نَعْبُدُ الرَّبَّ حَتَّى نَأْتِيَ إِلَى هُنَاكَ».', 'خروج 10:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 27, 'وَلَكِنْ شَدَّدَ الرَّبُّ قَلْبَ فِرْعَوْنَ فَلَمْ يَشَأْ أَنْ يُطْلِقَهُمْ.', 'خروج 10:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 28, 'وَقَالَ لَهُ فِرْعَوْنُ׃ «اذْهَبْ عَنِّي. اِحْتَرِزْ. لَا تَرَ وَجْهِي أَيْضًا. إِنَّكَ يَوْمَ تَرَى وَجْهِي تَمُوتُ».', 'خروج 10:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 10, 29, 'فَقَالَ مُوسَى׃ «نِعِمَّا قُلْتَ. أَنَا لَا أَعُودُ أَرَى وَجْهَكَ أَيْضًا».', 'خروج 10:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 1, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «ضَرْبَةً وَاحِدَةً أَيْضًا أَجْلِبُ عَلَى فِرْعَوْنَ وَعَلَى مِصْرَ. بَعْدَ ذَلِكَ يُطْلِقُكُمْ مِنْ هُنَا. وَعِنْدَمَا يُطْلِقُكُمْ يَطْرُدُكُمْ طَرْدًا مِنْ هُنَا بِالتَّمَامِ.', 'خروج 11:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 2, 'تَكَلَّمْ فِي مَسَامِعِ الشَّعْبِ أَنْ يَطْلُبَ كُلُّ رَجُلٍ مِنْ صَاحِبِهِ، وَكُلُّ امْرَأَةٍ مِنْ صَاحِبَتِهَا أَمْتِعَةَ فِضَّةٍ وَأَمْتِعَةَ ذَهَبٍ».', 'خروج 11:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 3, 'وَأَعْطَى الرَّبُّ نِعْمَةً لِلشَّعْبِ فِي عُيُونِ الْمِصْرِيِّينَ. وَأَيْضًا الرَّجُلُ مُوسَى كَانَ عَظِيمًا جِدًّا فِي أَرْضِ مِصْرَ فِي عُيُونِ عَبِيدِ فِرْعَوْنَ وَعُيُونِ الشَّعْبِ.', 'خروج 11:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 4, 'وَقَالَ مُوسَى׃ «هَكَذَا يَقُولُ الرَّبُّ׃ إِنِّي نَحْوَ نِصْفِ اللَّيْلِ أَخْرُجُ فِي وَسَطِ مِصْرَ،', 'خروج 11:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 5, 'فَيَمُوتُ كُلُّ بِكْرٍ فِي أَرْضِ مِصْرَ، مِنْ بِكْرِ فِرْعَوْنَ الْجَالِسِ عَلَى كُرْسِيِّهِ إِلَى بِكْرِ الْجَارِيَةِ الَّتِي خَلْفَ الرَّحَى، وَكُلُّ بِكْرِ بَهِيمَةٍ.', 'خروج 11:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 6, 'وَيَكُونُ صُرَاخٌ عَظِيمٌ فِي كُلِّ أَرْضِ مِصْرَ لَمْ يَكُنْ مِثْلُهُ وَلَا يَكُونُ مِثْلُهُ أَيْضًا.', 'خروج 11:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 7, 'وَلَكِنْ جَمِيعُ بَنِي إِسْرَائِيلَ لَا يُسَنِّنُ كَلْبٌ لِسَانَهُ إِلَيْهِمْ، لَا إِلَى النَّاسِ وَلَا إِلَى الْبَهَائِمِ. لِكَيْ تَعْلَمُوا أَنَّ الرَّبَّ يُمَيِّزُ بَيْنَ الْمِصْرِيِّينَ وَإِسْرَائِيلَ.', 'خروج 11:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 8, 'فَيَنْزِلُ إِلَيَّ جَمِيعُ عَبِيدِكَ هَؤُلَاءِ، وَيَسْجُدُونَ لِي قَائِلِينَ׃ اخْرُجْ أَنْتَ وَجَمِيعُ الشَّعْبِ الَّذِينَ فِي أَثَرِكَ. وَبَعْدَ ذَلِكَ أَخْرُجُ». ثُمَّ خَرَجَ مِنْ لَدُنْ فِرْعَوْنَ فِي حُمُوِّ الْغَضَبِ.', 'خروج 11:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 9, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «لَا يَسْمَعُ لَكُمَا فِرْعَوْنُ لِكَيْ تَكْثُرَ عَجَائِبِي فِي أَرْضِ مِصْرَ».', 'خروج 11:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 11, 10, 'وَكَانَ مُوسَى وَهَارُونُ يَفْعَلَانِ كُلَّ هَذِهِ الْعَجَائِبِ أَمَامَ فِرْعَوْنَ، وَلَكِنْ شَدَّدَ الرَّبُّ قَلْبَ فِرْعَوْنَ، فَلَمْ يُطْلِقْ بَنِي إِسْرَائِيلَ مِنْ أَرْضِهِ.', 'خروج 11:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ فِي أَرْضِ مِصْرَ قَائِلًا׃', 'خروج 12:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 2, '«هَذَا الشَّهْرُ يَكُونُ لَكُمْ رَأْسَ الشُّهُورِ. هُوَ لَكُمْ أَوَّلُ شُهُورِ السَّنَةِ.', 'خروج 12:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 3, 'كَلِّمَا كُلَّ جَمَاعَةِ إِسْرَائِيلَ قَائِلَيْنِ׃ فِي الْعَاشِرِ مِنْ هَذَا الشَّهْرِ يَأْخُذُونَ لَهُمْ كُلُّ وَاحِدٍ شَاةً بِحَسَبِ بُيُوتِ الْآبَاءِ، شَاةً لِلْبَيْتِ.', 'خروج 12:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 4, 'وَإِنْ كَانَ الْبَيْتُ صَغِيرًا عَنْ أَنْ يَكُونَ كُفْوًا لِشَاةٍ، يَأْخُذُ هُوَ وَجَارُهُ الْقَرِيبُ مِنْ بَيْتِهِ بِحَسَبِ عَدَدِ النُّفُوسِ. كُلُّ وَاحِدٍ عَلَى حَسَبِ أُكْلِهِ تَحْسُبُونَ لِلشَّاةِ.', 'خروج 12:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 5, 'تَكُونُ لَكُمْ شَاةً صَحِيحَةً ذَكَرًا ابْنَ سَنَةٍ، تَأْخُذُونَهُ مِنَ الْخِرْفَانِ أَوْ مِنَ الْمَوَاعِزِ.', 'خروج 12:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 6, 'وَيَكُونُ عِنْدَكُمْ تَحْتَ الْحِفْظِ إِلَى الْيَوْمِ الرَّابِعَ عَشَرَ مِنْ هَذَا الشَّهْرِ. ثُمَّ يَذْبَحُهُ كُلُّ جُمْهُورِ جَمَاعَةِ إِسْرَائِيلَ فِي الْعَشِيَّةِ.', 'خروج 12:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 7, 'وَيَأْخُذُونَ مِنَ الدَّمِ وَيَجْعَلُونَهُ عَلَى الْقَائِمَتَيْنِ وَالْعَتَبَةِ الْعُلْيَا فِي الْبُيُوتِ الَّتِي يَأْكُلُونَهُ فِيهَا.', 'خروج 12:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 8, 'وَيَأْكُلُونَ اللَّحْمَ تِلْكَ اللَّيْلَةَ مَشْوِيًّا بِالنَّارِ مَعَ فَطِيرٍ. عَلَى أَعْشَابٍ مُرَّةٍ يَأْكُلُونَهُ.', 'خروج 12:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 9, 'لَا تَأْكُلُوا مِنْهُ نِيئًا أَوْ طَبِيخًا مَطْبُوخًا بِالْمَاءِ، بَلْ مَشْوِيًّا بِالنَّارِ. رَأْسَهُ مَعَ أَكَارِعِهِ وَجَوْفِهِ.', 'خروج 12:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 10, 'وَلَا تُبْقُوا مِنْهُ إِلَى الصَّبَاحِ. وَالْبَاقِي مِنْهُ إِلَى الصَّبَاحِ، تُحْرِقُونَهُ بِالنَّارِ.', 'خروج 12:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 11, 'وَهَكَذَا تَأْكُلُونَهُ׃ أَحْقَاؤُكُمْ مَشْدُودَةٌ، وَأَحْذِيَتُكُمْ فِي أَرْجُلِكُمْ، وَعِصِيُّكُمْ فِي أَيْدِيكُمْ. وَتَأْكُلُونَهُ بِعَجَلَةٍ. هُوَ فِصْحٌ لِلرَّبِّ.', 'خروج 12:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 12, 'فَإِنِّي أَجْتَازُ فِي أَرْضِ مِصْرَ هَذِهِ اللَّيْلَةَ، وَأَضْرِبُ كُلَّ بِكْرٍ فِي أَرْضِ مِصْرَ مِنَ النَّاسِ وَالْبَهَائِمِ. وَأَصْنَعُ أَحْكَامًا بِكُلِّ آلِهَةِ الْمِصْرِيِّينَ. أَنَا الرَّبُّ.', 'خروج 12:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 13, 'وَيَكُونُ لَكُمُ الدَّمُ عَلَامَةً عَلَى الْبُيُوتِ الَّتِي أَنْتُمْ فِيهَا، فَأَرَى الدَّمَ وَأَعْبُرُ عَنْكُمْ، فَلَا يَكُونُ عَلَيْكُمْ ضَرْبَةٌ لِلْهَلَاكِ حِينَ أَضْرِبُ أَرْضَ مِصْرَ.', 'خروج 12:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 14, 'وَيَكُونُ لَكُمْ هَذَا الْيَوْمُ تَذْكَارًا فَتُعَيِّدُونَهُ عِيدًا لِلرَّبِّ. فِي أَجْيَالِكُمْ تُعَيِّدُونَهُ فَرِيضَةً أَبَدِيَّةً.', 'خروج 12:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 15, '«سَبْعَةَ أَيَّامٍ تَأْكُلُونَ فَطِيرًا. الْيَوْمَ الْأَوَّلَ تَعْزِلُونَ الْخَمِيرَ مِنْ بُيُوتِكُمْ، فَإِنَّ كُلَّ مَنْ أَكَلَ خَمِيرًا مِنَ الْيَوْمِ الْأَوَّلِ إِلَى الْيَوْمِ السَّابِعِ تُقْطَعُ تِلْكَ النَّفْسُ مِنْ إِسْرَائِيلَ.', 'خروج 12:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 16, 'وَيَكُونُ لَكُمْ فِي الْيَوْمِ الْأَوَّلِ مَحْفَلٌ مُقَدَّسٌ، وَفِي الْيَوْمِ السَّابِعِ مَحْفَلٌ مُقَدَّسٌ. لَا يُعْمَلُ فِيهِمَا عَمَلٌ مَا إِلَّا مَا تَأْكُلُهُ كُلُّ نَفْسٍ، فَذَلِكَ وَحْدَهُ يُعْمَلُ مِنْكُمْ.', 'خروج 12:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 17, 'وَتَحْفَظُونَ الْفَطِيرَ لِأَنِّي فِي هَذَا الْيَوْمِ عَيْنِهِ أَخْرَجْتُ أَجْنَادَكُمْ مِنْ أَرْضِ مِصْرَ، فَتَحْفَظُونَ هَذَا الْيَوْمَ فِي أَجْيَالِكُمْ فَرِيضَةً أَبَدِيَّةً.', 'خروج 12:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 18, 'فِي الشَّهْرِ الْأَوَّلِ، فِي الْيَوْمِ الرَّابِعَ عَشَرَ مِنَ الشَّهْرِ، مَسَاءً، تَأْكُلُونَ فَطِيرًا إِلَى الْيَوْمِ الْحَادِي وَالْعِشْرِينَ مِنَ الشَّهْرِ مَسَاءً.', 'خروج 12:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 19, 'سَبْعَةَ أَيَّامٍ لَا يُوجَدْ خَمِيرٌ فِي بُيُوتِكُمْ. فَإِنَّ كُلَّ مَنْ أَكَلَ مُخْتَمِرًا تُقْطَعُ تِلْكَ النَّفْسُ مِنْ جَمَاعَةِ إِسْرَائِيلَ، الْغَرِيبُ مَعَ مَوْلُودِ الْأَرْضِ.', 'خروج 12:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 20, 'لَا تَأْكُلُوا شَيْئًا مُخْتَمِرًا. فِي جَمِيعِ مَسَاكِنِكُمْ تَأْكُلُونَ فَطِيرًا».', 'خروج 12:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 21, 'فَدَعَا مُوسَى جَمِيعَ شُيُوخِ إِسْرَائِيلَ وَقَالَ لَهُمُ׃ «اسْحَبُوا وَخُذُوا لَكُمْ غَنَمًا بِحَسَبِ عَشَائِرِكُمْ وَاذْبَحُوا الْفِصْحَ.', 'خروج 12:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 22, 'وَخُذُوا بَاقَةَ زُوفَا وَاغْمِسُوهَا فِي الدَّمِ الَّذِي فِي الطَّسْتِ وَمُسُّوا الْعَتَبَةَ الْعُلْيَا وَالْقَائِمَتَيْنِ بِالدَّمِ الَّذِي فِي الطَّسْتِ. وَأَنْتُمْ لَا يَخْرُجْ أَحَدٌ مِنْكُمْ مِنْ بَابِ بَيْتِهِ حَتَّى الصَّبَاحِ،', 'خروج 12:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 23, 'فَإِنَّ الرَّبَّ يَجْتَازُ لِيَضْرِبَ الْمِصْرِيِّينَ. فَحِينَ يَرَى الدَّمَ عَلَى الْعَتَبَةِ الْعُلْيَا وَالْقَائِمَتَيْنِ يَعْبُرُ الرَّبُّ عَنِ الْبَابِ وَلَا يَدَعُ الْمُهْلِكَ يَدْخُلُ بُيُوتَكُمْ لِيَضْرِبَ.', 'خروج 12:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 24, 'فَتَحْفَظُونَ هَذَا الْأَمْرَ فَرِيضَةً لَكَ وَلِأَوْلَادِكَ إِلَى الْأَبَدِ.', 'خروج 12:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 25, 'وَيَكُونُ حِينَ تَدْخُلُونَ الْأَرْضَ الَّتِي يُعْطِيكُمُ الرَّبُّ كَمَا تَكَلَّمَ، أَنَّكُمْ تَحْفَظُونَ هَذِهِ الْخِدْمَةَ.', 'خروج 12:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 26, 'وَيَكُونُ حِينَ يَقُولُ لَكُمْ أَوْلَادُكُمْ׃ مَا هَذِهِ الْخِدْمَةُ لَكُمْ؟', 'خروج 12:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 27, 'أَنَّكُمْ تَقُولُونَ׃ هِيَ ذَبِيحَةُ فِصْحٍ لِلرَّبِّ الَّذِي عَبَرَ عَنْ بُيُوتِ بَنِي إِسْرَائِيلَ فِي مِصْرَ لَمَّا ضَرَبَ الْمِصْرِيِّينَ وَخَلَّصَ بُيُوتَنَا». فَخَرَّ الشَّعْبُ وَسَجَدُوا.', 'خروج 12:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 28, 'وَمَضَى بَنُو إِسْرَائِيلَ وَفَعَلُوا كَمَا أَمَرَ الرَّبُّ مُوسَى وَهَارُونَ. هَكَذَا فَعَلُوا.', 'خروج 12:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 29, 'فَحَدَثَ فِي نِصْفِ اللَّيْلِ أَنَّ الرَّبَّ ضَرَبَ كُلَّ بِكْرٍ فِي أَرْضِ مِصْرَ، مِنْ بِكْرِ فِرْعَوْنَ الْجَالِسِ عَلَى كُرْسِيِّهِ إِلَى بِكْرِ الْأَسِيرِ الَّذِي فِي السِّجْنِ، وَكُلَّ بِكْرِ بَهِيمَةٍ.', 'خروج 12:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 30, 'فَقَامَ فِرْعَوْنُ لَيْلًا هُوَ وَكُلُّ عَبِيدِهِ وَجَمِيعُ الْمِصْرِيِّينَ. وَكَانَ صُرَاخٌ عَظِيمٌ فِي مِصْرَ، لِأَنَّهُ لَمْ يَكُنْ بَيْتٌ لَيْسَ فِيهِ مَيْتٌ.', 'خروج 12:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 31, 'فَدَعَا مُوسَى وَهَارُونَ لَيْلًا وَقَالَ׃ «قُومُوا اخْرُجُوا مِنْ بَيْنِ شَعْبِي أَنْتُمَا وَبَنُو إِسْرَائِيلَ جَمِيعًا، وَاذْهَبُوا اعْبُدُوا الرَّبَّ كَمَا تَكَلَّمْتُمْ.', 'خروج 12:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 32, 'خُذُوا غَنَمَكُمْ أَيْضًا وَبَقَرَكُمْ كَمَا تَكَلَّمْتُمْ وَاذْهَبُوا. وَبَارِكُونِي أَيْضًا».', 'خروج 12:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 33, 'وَأَلَحَّ الْمِصْرِيُّونَ عَلَى الشَّعْبِ لِيُطْلِقُوهُمْ عَاجِلًا مِنَ الْأَرْضِ، لِأَنَّهُمْ قَالُوا׃ «جَمِيعُنَا أَمْوَاتٌ».', 'خروج 12:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 34, 'فَحَمَلَ الشَّعْبُ عَجِينَهُمْ قَبْلَ أَنْ يَخْتَمِرَ، وَمَعَاجِنُهُمْ مَصْرُورَةٌ فِي ثِيَابِهِمْ عَلَى أَكْتَافِهِمْ.', 'خروج 12:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 35, 'وَفَعَلَ بَنُو إِسْرَائِيلَ بِحَسَبِ قَوْلِ مُوسَى. طَلَبُوا مِنَ الْمِصْرِيِّينَ أَمْتِعَةَ فِضَّةٍ وَأَمْتِعَةَ ذَهَبٍ وَثِيَابًا.', 'خروج 12:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 36, 'وَأَعْطَى الرَّبُّ نِعْمَةً لِلشَّعْبِ فِي عُيُونِ الْمِصْرِيِّينَ حَتَّى أَعَارُوهُمْ. فَسَلَبُوا الْمِصْرِيِّينَ.', 'خروج 12:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 37, 'فَارْتَحَلَ بَنُو إِسْرَائِيلَ مِنْ رَعَمْسِيسَ إِلَى سُكُّوتَ، نَحْوَ سِتِّ مِئَةِ أَلْفِ مَاشٍ مِنَ الرِّجَالِ عَدَا الْأَوْلَادِ.', 'خروج 12:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 38, 'وَصَعِدَ مَعَهُمْ لَفِيفٌ كَثِيرٌ أَيْضًا مَعَ غَنَمٍ وَبَقَرٍ، مَوَاشٍ وَافِرَةٍ جِدًّا.', 'خروج 12:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 39, 'وَخَبَزُوا الْعَجِينَ الَّذِي أَخْرَجُوهُ مِنْ مِصْرَ خُبْزَ مَلَّةٍ فَطِيرًا، إِذْ كَانَ لَمْ يَخْتَمِرْ. لِأَنَّهُمْ طُرِدُوا مِنْ مِصْرَ وَلَمْ يَقْدِرُوا أَنْ يَتَأَخَّرُوا، فَلَمْ يَصْنَعُوا لِأَنْفُسِهِمْ زَادًا.', 'خروج 12:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 40, 'وَأَمَّا إِقَامَةُ بَنِي إِسْرَائِيلَ الَّتِي أَقَامُوهَا فِي مِصْرَ فَكَانَتْ أَرْبَعَ مِئَةٍ وَثَلَاثِينَ سَنَةً.', 'خروج 12:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 41, 'وَكَانَ عِنْدَ نِهَايَةِ أَرْبَعِ مِئَةٍ وَثَلَاثِينَ سَنَةً، فِي ذَلِكَ الْيَوْمِ عَيْنِهِ، أَنَّ جَمِيعَ أَجْنَادِ الرَّبِّ خَرَجَتْ مِنْ أَرْضِ مِصْرَ.', 'خروج 12:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 42, 'هِيَ لَيْلَةٌ تُحْفَظُ لِلرَّبِّ لِإِخْرَاجِهِ إِيَّاهُمْ مِنْ أَرْضِ مِصْرَ. هَذِهِ اللَّيْلَةُ هِيَ لِلرَّبِّ. تُحْفَظُ مِنْ جَمِيعِ بَنِي إِسْرَائِيلَ فِي أَجْيَالِهِمْ.', 'خروج 12:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 43, 'وَقَالَ الرَّبُّ لِمُوسَى وَهَارُونَ׃ «هَذِهِ فَرِيضَةُ الْفِصْحِ׃ كُلُّ ابْنِ غَرِيبٍ لَا يَأْكُلُ مِنْهُ.', 'خروج 12:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 44, 'وَلَكِنْ كُلُّ عَبْدِ رَجُلٍ مُبْتَاعٍ بِفِضَّةٍ تَخْتِنُهُ ثُمَّ يَأْكُلُ مِنْهُ.', 'خروج 12:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 45, 'النَّزِيلُ وَالْأَجِيرُ لَا يَأْكُلَانِ مِنْهُ.', 'خروج 12:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 46, 'فِي بَيْتٍ وَاحِدٍ يُؤْكَلُ. لَا تُخْرِجْ مِنَ اللَّحْمِ مِنَ الْبَيْتِ إِلَى خَارِجٍ، وَعَظْمًا لَا تَكْسِرُوا مِنْهُ.', 'خروج 12:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 47, 'كُلُّ جَمَاعَةِ إِسْرَائِيلَ يَصْنَعُونَهُ.', 'خروج 12:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 48, 'وَإِذَا نَزَلَ عِنْدَكَ نَزِيلٌ وَصَنَعَ فِصْحًا لِلرَّبِّ، فَلْيُخْتَنْ مِنْهُ كُلُّ ذَكَرٍ، ثُمَّ يَتَقَدَّمُ لِيَصْنَعَهُ، فَيَكُونُ كَمَوْلُودِ الْأَرْضِ. وَأَمَّا كُلُّ أَغْلَفَ فَلَا يَأْكُلُ مِنْهُ.', 'خروج 12:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 49, 'تَكُونُ شَرِيعَةٌ وَاحِدَةٌ لِمَوْلُودِ الْأَرْضِ وَلِلنَّزِيلِ النَّازِلِ بَيْنَكُمْ».', 'خروج 12:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 50, 'فَفَعَلَ جَمِيعُ بَنِي إِسْرَائِيلَ كَمَا أَمَرَ الرَّبُّ مُوسَى وَهَارُونَ. هَكَذَا فَعَلُوا.', 'خروج 12:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 12, 51, 'وَكَانَ فِي ذَلِكَ الْيَوْمِ عَيْنِهِ أَنَّ الرَّبَّ أَخْرَجَ بَنِي إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ بِحَسَبِ أَجْنَادِهِمْ.', 'خروج 12:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 13:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 2, '«قَدِّسْ لِي كُلَّ بِكْرٍ، كُلَّ فَاتِحِ رَحِمٍ مِنْ بَنِي إِسْرَائِيلَ، مِنَ النَّاسِ وَمِنَ الْبَهَائِمِ. إِنَّهُ لِي».', 'خروج 13:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 3, 'وَقَالَ مُوسَى لِلشَّعْبِ׃ «اذْكُرُوا هَذَا الْيَوْمَ الَّذِي فِيهِ خَرَجْتُمْ مِنْ مِصْرَ مِنْ بَيْتِ الْعُبُودِيَّةِ، فَإِنَّهُ بِيَدٍ قَوِيَّةٍ أَخْرَجَكُمُ الرَّبُّ مِنْ هُنَا. وَلَا يُؤْكَلُ خَمِيرٌ.', 'خروج 13:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 4, 'اَلْيَوْمَ أَنْتُمْ خَارِجُونَ فِي شَهْرِ أَبِيبَ.', 'خروج 13:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 5, 'وَيَكُونُ مَتَى أَدْخَلَكَ الرَّبُّ أَرْضَ الْكَنْعَانِيِّينَ وَالْحِثِّيِّينَ وَالْأَمُورِيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ الَّتِي حَلَفَ لِآبَائِكَ أَنْ يُعْطِيَكَ، أَرْضًا تَفِيضُ لَبَنًا وَعَسَلًا، أَنَّكَ تَصْنَعُ هَذِهِ الْخِدْمَةَ فِي هَذَا الشَّهْرِ.', 'خروج 13:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 6, 'سَبْعَةَ أَيَّامٍ تَأْكُلُ فَطِيرًا، وَفِي الْيَوْمِ السَّابِعِ عِيدٌ لِلرَّبِّ.', 'خروج 13:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 7, 'فَطِيرٌ يُؤْكَلُ السَّبْعَةَ الْأَيَّامِ، وَلَا يُرَى عِنْدَكَ مُخْتَمِرٌ، وَلَا يُرَى عِنْدَكَ خَمِيرٌ فِي جَمِيعِ تُخُومِكَ.', 'خروج 13:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 8, '«وَتُخْبِرُ ابْنَكَ فِي ذَلِكَ الْيَوْمِ قَائِلًا׃ مِنْ أَجْلِ مَا صَنَعَ إِلَيَّ الرَّبُّ حِينَ أَخْرَجَنِي مِنْ مِصْرَ.', 'خروج 13:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 9, 'وَيَكُونُ لَكَ عَلَامَةً عَلَى يَدِكَ، وَتَذْكَارًا بَيْنَ عَيْنَيْكَ، لِكَيْ تَكُونَ شَرِيعَةُ الرَّبِّ فِي فَمِكَ. لِأَنَّهُ بِيَدٍ قَوِيَّةٍ أَخْرَجَكَ الرَّبُّ مِنْ مِصْرَ.', 'خروج 13:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 10, 'فَتَحْفَظُ هَذِهِ الْفَرِيضَةَ فِي وَقْتِهَا مِنْ سَنَةٍ إِلَى سَنَةٍ.', 'خروج 13:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 11, '«وَيَكُونُ مَتَى أَدْخَلَكَ الرَّبُّ أَرْضَ الْكَنْعَانِيِّينَ كَمَا حَلَفَ لَكَ وَلِآبَائِكَ، وَأَعْطَاكَ إِيَّاهَا،', 'خروج 13:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 12, 'أَنَّكَ تُقَدِّمُ لِلرَّبِّ كُلَّ فَاتِحِ رَحِمٍ، وَكُلَّ بِكْرٍ مِنْ نِتَاجِ الْبَهَائِمِ الَّتِي تَكُونُ لَكَ. الذُّكُورُ لِلرَّبِّ.', 'خروج 13:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 13, 'وَلَكِنَّ كُلَّ بِكْرِ حِمَارٍ تَفْدِيهِ بِشَاةٍ. وَإِنْ لَمْ تَفْدِهِ فَتَكْسِرُ عُنُقَهُ. وَكُلُّ بِكْرِ إِنْسَانٍ مِنْ أَوْلَادِكَ تَفْدِيهِ.', 'خروج 13:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 14, '«وَيَكُونُ مَتَى سَأَلَكَ ابْنُكَ غَدًا قَائِلًا׃ مَا هَذَا؟ تَقُولُ لَهُ׃ بِيَدٍ قَوِيَّةٍ أَخْرَجَنَا الرَّبُّ مِنْ مِصْرَ مِنْ بَيْتِ الْعُبُودِيَّةِ.', 'خروج 13:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 15, 'وَكَانَ لَمَّا تَقَسَّى فِرْعَوْنُ عَنْ إِطْلَاقِنَا أَنَّ الرَّبَّ قَتَلَ كُلَّ بِكْرٍ فِي أَرْضِ مِصْرَ، مِنْ بِكْرِ النَّاسِ إِلَى بِكْرِ الْبَهَائِمِ. لِذَلِكَ أَنَا أَذْبَحُ لِلرَّبِّ الذُّكُورَ مِنْ كُلِّ فَاتِحِ رَحِمٍ، وَأَفْدِي كُلَّ بِكْرٍ مِنْ أَوْلَادِي.', 'خروج 13:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 16, 'فَيَكُونُ عَلَامَةً عَلَى يَدِكَ، وَعِصَابَةً بَيْنَ عَيْنَيْكَ. لِأَنَّهُ بِيَدٍ قَوِيَّةٍ أَخْرَجَنَا الرَّبُّ مِنْ مِصْرَ».', 'خروج 13:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 17, 'وَكَانَ لَمَّا أَطْلَقَ فِرْعَوْنُ الشَّعْبَ أَنَّ اللهَ لَمْ يَهْدِهِمْ فِي طَرِيقِ أَرْضِ الْفِلِسْطِينِيِّينَ مَعَ أَنَّهَا قَرِيبَةٌ، لِأَنَّ اللهَ قَالَ׃ «لِئَلَّا يَنْدَمَ الشَّعْبُ إِذَا رَأَوْا حَرْبًا وَيَرْجِعُوا إِلَى مِصْرَ».', 'خروج 13:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 18, 'فَأَدَارَ اللهُ الشَّعْبَ فِي طَرِيقِ بَرِّيَّةِ بَحْرِ سُوفٍ. وَصَعِدَ بَنُو إِسْرَائِيلَ مُتَجَهِّزِينَ مِنْ أَرْضِ مِصْرَ.', 'خروج 13:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 19, 'وَأَخَذَ مُوسَى عِظَامَ يُوسُفَ مَعَهُ، لِأَنَّهُ كَانَ قَدِ اسْتَحْلَفَ بَنِي إِسْرَائِيلَ بِحَلْفٍ قَائِلًا׃ «إِنَّ اللهَ سَيَفْتَقِدُكُمْ فَتُصْعِدُونَ عِظَامِي مِنْ هُنَا مَعَكُمْ».', 'خروج 13:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 20, 'وَارْتَحَلُوا مِنْ سُكُّوتَ وَنَزَلُوا فِي إِيثَامَ فِي طَرَفِ الْبَرِّيَّةِ.', 'خروج 13:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 21, 'وَكَانَ الرَّبُّ يَسِيرُ أَمَامَهُمْ نَهَارًا فِي عَمُودِ سَحَابٍ لِيَهْدِيَهُمْ فِي الطَّرِيقِ، وَلَيْلًا فِي عَمُودِ نَارٍ لِيُضِيءَ لَهُمْ. لِكَيْ يَمْشُوا نَهَارًا وَلَيْلًا.', 'خروج 13:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 13, 22, 'لَمْ يَبْرَحْ عَمُودُ السَّحَابِ نَهَارًا وَعَمُودُ النَّارِ لَيْلًا مِنْ أَمَامِ الشَّعْبِ.', 'خروج 13:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 1, 'وَكَلَّمَ الرَّبُ مُوسَى قَائِلًا׃', 'خروج 14:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ أَنْ يَرْجِعُوا وَيَنْزِلُوا أَمَامَ فَمِ الْحِيرُوثِ بَيْنَ مَجْدَلَ وَالْبَحْرِ، أَمَامَ بَعْلَ صَفُونَ. مُقَابِلَهُ تَنْزِلُونَ عِنْدَ الْبَحْرِ.', 'خروج 14:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 3, 'فَيَقُولُ فِرْعَوْنُ عَنْ بَنِي إِسْرَائِيلَ׃ هُمْ مُرْتَبِكُونَ فِي الْأَرْضِ. قَدِ اسْتَغْلَقَ عَلَيْهِمِ الْقَفْرُ.', 'خروج 14:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 4, 'وَأُشَدِّدُ قَلْبَ فِرْعَوْنَ حَتَّى يَسْعَى وَرَاءَهُمْ، فَأَتَمَجَّدُ بِفِرْعَوْنَ وَبِجَمِيعِ جَيْشِهِ، وَيَعْرِفُ الْمِصْرِيُّونَ أَنِّي أَنَا الرَّبُّ». فَفَعَلُوا هَكَذَا.', 'خروج 14:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 5, 'فَلَمَّا أُخْبِرَ مَلِكُ مِصْرَ أَنَّ الشَّعْبَ قَدْ هَرَبَ، تَغَيَّرَ قَلْبُ فِرْعَوْنَ وَعَبِيدِهِ عَلَى الشَّعْبِ. فَقَالُوا׃ «مَاذَا فَعَلْنَا حَتَّى أَطْلَقْنَا إِسْرَائِيلَ مِنْ خِدْمَتِنَا؟»', 'خروج 14:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 6, 'فَشَدَّ مَرْكَبَتَهُ وَأَخَذَ قَوْمَهُ مَعَهُ.', 'خروج 14:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 7, 'وَأَخَذَ سِتَّ مِئَةِ مَرْكَبَةٍ مُنْتَخَبَةٍ وَسَائِرَ مَرْكَبَاتِ مِصْرَ وَجُنُودًا مَرْكَبِيَّةً عَلَى جَمِيعِهَا.', 'خروج 14:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 8, 'وَشَدَّدَ الرَّبُّ قَلْبَ فِرْعَوْنَ مَلِكِ مِصْرَ حَتَّى سَعَى وَرَاءَ بَنِي إِسْرَائِيلَ، وَبَنُو إِسْرَائِيلَ خَارِجُونَ بِيَدٍ رَفِيعَةٍ.', 'خروج 14:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 9, 'فَسَعَى الْمِصْرِيُّونَ وَرَاءَهُمْ وَأَدْرَكُوهُمْ. جَمِيعُ خَيْلِ مَرْكَبَاتِ فِرْعَوْنَ وَفُرْسَانِهِ وَجَيْشِهِ، وَهُمْ نَازِلُونَ عِنْدَ الْبَحْرِ عِنْدَ فَمِ الْحِيرُوثِ، أَمَامَ بَعْلَ صَفُونَ.', 'خروج 14:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 10, 'فَلَمَّا اقْتَرَبَ فِرْعَوْنُ رَفَعَ بَنُو إِسْرَائِيلَ عُيُونَهُمْ، وَإِذَا الْمِصْرِيُّونَ رَاحِلُونَ وَرَاءَهُمْ. فَفَزِعُوِا جِدًّا، وَصَرَخَ بَنُو إِسْرَائِيلَ إِلَى الرَّبِّ.', 'خروج 14:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 11, 'وَقَالُوا لِمُوسَى׃ «هَلْ لِأَنَّهُ لَيْسَتْ قُبُورٌ فِي مِصْرَ أَخَذْتَنَا لِنَمُوتَ فِي الْبَرِّيَّةِ؟ مَاذَا صَنَعْتَ بِنَا حَتَّى أَخْرَجْتَنَا مِنْ مِصْرَ؟', 'خروج 14:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 12, 'أَلَيْسَ هَذَا هُوَ الْكَلَامُ الَّذِي كَلَّمْنَاكَ بِهِ فِي مِصْرَ قَائِلِينَ׃ كُفَّ عَنَّا فَنَخْدِمَ الْمِصْرِيِّينَ؟ لِأَنَّهُ خَيْرٌ لَنَا أَنْ نَخْدِمَ الْمِصْرِيِّينَ مِنْ أَنْ نَمُوتَ فِي الْبَرِّيَّةِ».', 'خروج 14:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 13, 'فَقَالَ مُوسَى لِلشَّعْبِ׃ «لَا تَخَافُوا. قِفُوا وَانْظُرُوا خَلَاصَ الرَّبِّ الَّذِي يَصْنَعُهُ لَكُمُ الْيَوْمَ. فَإِنَّهُ كَمَا رَأَيْتُمُ الْمِصْرِيِّينَ الْيَوْمَ، لَا تَعُودُونَ تَرَوْنَهُمْ أَيْضًا إِلَى الْأَبَدِ.', 'خروج 14:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 14, 'الرَّبُّ يُقَاتِلُ عَنْكُمْ وَأَنْتُمْ تَصْمُتُونَ».', 'خروج 14:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 15, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «مَا لَكَ تَصْرُخُ إِلَيَّ؟ قُلْ لِبَنِي إِسْرَائِيلَ أَنْ يَرْحَلُوا.', 'خروج 14:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 16, 'وَارْفَعْ أَنْتَ عَصَاكَ وَمُدَّ يَدَكَ عَلَى الْبَحْرِ وَشُقَّهُ، فَيَدْخُلَ بَنُو إِسْرَائِيلَ فِي وَسَطِ الْبَحْرِ عَلَى الْيَابِسَةِ.', 'خروج 14:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 17, 'وَهَا أَنَا أُشَدِّدُ قُلُوبَ الْمِصْرِيِّينَ حَتَّى يَدْخُلُوا وَرَاءَهُمْ، فَأَتَمَجَّدُ بِفِرْعَوْنَ وَكُلِّ جَيْشِهِ، بِمَرْكَبَاتِهِ وَفُرْسَانِهِ.', 'خروج 14:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 18, 'فَيَعْرِفُ الْمِصْرِيُّونَ أَنِّي أَنَا الرَّبُّ حِينَ أَتَمَجَّدُ بِفِرْعَوْنَ وَمَرْكَبَاتِهِ وَفُرْسَانِهِ».', 'خروج 14:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 19, 'فَانْتَقَلَ مَلَاكُ اللهِ السَّائِرُ أَمَامَ عَسْكَرِ إِسْرَائِيلَ وَسَارَ وَرَاءَهُمْ، وَانْتَقَلَ عَمُودُ السَّحَابِ مِنْ أَمَامِهِمْ وَوَقَفَ وَرَاءَهُمْ.', 'خروج 14:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 20, 'فَدَخَلَ بَيْنَ عَسْكَرِ الْمِصْرِيِّينَ وَعَسْكَرِ إِسْرَائِيلَ، وَصَارَ السَّحَابُ وَالظَّلَامُ وَأَضَاءَ اللَّيْلَ. فَلَمْ يَقْتَرِبْ هَذَا إِلَى ذَاكَ كُلَّ اللَّيْلِ.', 'خروج 14:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 21, 'وَمَدَّ مُوسَى يَدَهُ عَلَى الْبَحْرِ، فَأَجْرَى الرَّبُّ الْبَحْرَ بِرِيحٍ شَرْقِيَّةٍ شَدِيدَةٍ كُلَّ اللَّيْلِ، وَجَعَلَ الْبَحْرَ يَابِسَةً وَانْشَقَّ الْمَاءُ.', 'خروج 14:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 22, 'فَدَخَلَ بَنُو إِسْرَائِيلَ فِي وَسَطِ الْبَحْرِ عَلَى الْيَابِسَةِ، وَالْمَاءُ سُورٌ لَهُمْ عَنْ يَمِينِهِمْ وَعَنْ يَسَارِهِمْ.', 'خروج 14:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 23, 'وَتَبِعَهُمُ الْمِصْرِيُّونَ وَدَخَلُوا وَرَاءَهُمْ. جَمِيعُ خَيْلِ فِرْعَوْنَ وَمَرْكَبَاتِهِ وَفُرْسَانِهِ إِلَى وَسَطِ الْبَحْرِ.', 'خروج 14:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 24, 'وَكَانَ فِي هَزِيعِ الصُّبْحِ أَنَّ الرَّبَّ أَشْرَفَ عَلَى عَسْكَرِ الْمِصْرِيِّينَ فِي عَمُودِ النَّارِ وَالسَّحَابِ، وَأَزْعَجَ عَسْكَرَ الْمِصْرِيِّينَ،', 'خروج 14:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 25, 'وَخَلَعَ بَكَرَ مَرْكَبَاتِهِمْ حَتَّى سَاقُوهَا بِثَقْلَةٍ. فَقَالَ الْمِصْرِيُّونَ׃ «نَهْرُبُ مِنْ إِسْرَائِيلَ، لِأَنَّ الرَّبَّ يُقَاتِلُ الْمِصْرِيِّينَ عَنْهُمْ».', 'خروج 14:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 26, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «مُدَّ يَدَكَ عَلَى الْبَحْرِ لِيَرْجِعَ الْمَاءُ عَلَى الْمِصْرِيِّينَ، عَلَى مَرْكَبَاتِهِمْ وَفُرْسَانِهِمْ».', 'خروج 14:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 27, 'فَمَدَّ مُوسَى يَدَهُ عَلَى الْبَحْرِ فَرَجَعَ الْبَحْرُ عِنْدَ إِقْبَالِ الصُّبْحِ إِلَى حَالِهِ الدَّائِمَةِ، وَالْمِصْرِيُّونَ هَارِبُونَ إِلَى لِقَائِهِ. فَدَفَعَ الرَّبُّ الْمِصْرِيِّينَ فِي وَسَطِ الْبَحْرِ.', 'خروج 14:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 28, 'فَرَجَعَ الْمَاءُ وَغَطَّى مَرْكَبَاتِ وَفُرْسَانَ جَمِيعِ جَيْشِ فِرْعَوْنَ الَّذِي دَخَلَ وَرَاءَهُمْ فِي الْبَحْرِ. لَمْ يَبْقَ مِنْهُمْ وَلَا وَاحِدٌ.', 'خروج 14:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 29, 'وَأَمَّا بَنُو إِسْرَائِيلَ فَمَشَوْا عَلَى الْيَابِسَةِ فِي وَسَطِ الْبَحْرِ، وَالْمَاءُ سُورٌ لَهُمْ عَنْ يَمِينِهِمْ وَعَنْ يَسَارِهِمْ.', 'خروج 14:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 30, 'فَخَلَّصَ الرَّبُّ فِي ذَلِكَ الْيَوْمِ إِسْرَائِيلَ مِنْ يَدِ الْمِصْرِيِّينَ. وَنَظَرَ إِسْرَائِيلُ الْمِصْرِيِّينَ أَمْوَاتًا عَلَى شَاطِئِ الْبَحْرِ.', 'خروج 14:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 14, 31, 'وَرَأَى إِسْرَائِيلُ الْفِعْلَ الْعَظِيمَ الَّذِي صَنَعَهُ الرَّبُّ بِالْمِصْرِيِّينَ، فَخَافَ الشَّعْبُ الرَّبَّ وَآمَنُوا بِالرَّبِّ وَبِعَبْدِهِ مُوسَى.', 'خروج 14:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 1, 'حِينَئِذٍ رَنَّمَ مُوسَى وَبَنُو إِسْرَائِيلَ هَذِهِ التَّسْبِيحَةَ لِلرَّبِّ وَقَالُوا׃ «أُرَنِّمُ لِلرَّبِّ فَإِنَّهُ قَدْ تَعَظَّمَ. الْفَرَسَ وَرَاكِبَهُ طَرَحَهُمَا فِي الْبَحْرِ.', 'خروج 15:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 2, 'الرَّبُّ قُوَّتِي وَنَشِيدِي، وَقَدْ صَارَ خَلَاصِي. هَذَا إِلَهِي فَأُمَجِّدُهُ، إِلَهُ أَبِي فَأُرَفِّعُهُ.', 'خروج 15:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 3, 'الرَّبُّ رَجُلُ الْحَرْبِ. الرَّبُّ اسْمُهُ.', 'خروج 15:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 4, 'مَرْكَبَاتُ فِرْعَوْنَ وَجَيْشُهُ أَلْقَاهُمَا فِي الْبَحْرِ، فَغَرِقَ أَفْضَلُ جُنُودِهِ الْمَرْكَبِيَّةِ فِي بَحْرِ سُوفَ،', 'خروج 15:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 5, 'تُغَطِّيهِمُ اللُّجَجُ. قَدْ هَبَطُوا فِي الْأَعْمَاقِ كَحَجَرٍ.', 'خروج 15:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 6, 'يَمِينُكَ يَا رَبُّ مُعْتَزَّةٌ بِالْقُدْرَةِ. يَمِينُكَ يَا رَبُّ تُحَطِّمُ الْعَدُوَّ.', 'خروج 15:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 7, 'وَبِكَثْرَةِ عَظَمَتِكَ تَهْدِمُ مُقَاوِمِيكَ. تُرْسِلُ سُخْطَكَ فَيَأْكُلُهُمْ كَالْقَشِّ،', 'خروج 15:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 8, 'وَبِرِيحِ أَنْفِكَ تَرَاكَمَتِ الْمِيَاهُ. انْتَصَبَتِ الْمَجَارِيَ كَرَابِيَةٍ. تَجَمَّدَتِ اللُّجَجُ فِي قَلْبِ الْبَحْرِ.', 'خروج 15:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 9, 'قَالَ الْعَدُوُّ׃ أَتْبَعُ، أُدْرِكُ، أُقَسِّمُ غَنِيمَةً. تَمْتَلِئُ مِنْهُمْ نَفْسِي. أُجَرِّدُ سَيْفِي. تُفْنِيهِمْ يَدِي.', 'خروج 15:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 10, 'نَفَخْتَ بِرِيحِكَ فَغَطَّاهُمُ الْبَحْرُ. غَاصُوا كَالرَّصَاصِ فِي مِيَاهٍ غَامِرَةٍ.', 'خروج 15:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 11, 'مَنْ مِثْلُكَ بَيْنَ الْآلِهَةِ يَا رَبُّ؟ مَنْ مِثْلُكَ مُعْتَزًّا فِي الْقَدَاسَةِ، مَخُوفًا بِالتَّسَابِيحِ، صَانِعًا عَجَائِبَ؟', 'خروج 15:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 12, 'تَمُدُّ يَمِينَكَ فَتَبْتَلِعُهُمُ الْأَرْضُ.', 'خروج 15:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 13, 'تُرْشِدُ بِرَأْفَتِكَ الشَّعْبَ الَّذِي فَدَيْتَهُ. تَهْدِيهِ بِقُوَّتِكَ إِلَى مَسْكَنِ قُدْسِكَ.', 'خروج 15:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 14, 'يَسْمَعُ الشُّعُوبُ فَيَرْتَعِدُونَ. تَأْخُذُ الرَّعْدَةُ سُكَّانَ فِلِسْطِينَ.', 'خروج 15:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 15, 'حِينَئِذٍ يَنْدَهِشُ أُمَرَاءُ أَدُومَ. أَقْوِيَاءُ مُوآبَ تَأْخُذُهُمُ الرَّجْفَةُ. يَذُوبُ جَمِيعُ سُكَّانِ كَنْعَانَ.', 'خروج 15:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 16, 'تَقَعُ عَلَيْهِمِ الْهَيْبَةُ وَالرُّعْبُ. بِعَظَمَةِ ذِرَاعِكَ يَصْمُتُونَ كَالْحَجَرِ حَتَّى يَعْبُرَ شَعْبُكَ يَا رَبُّ. حَتَّى يَعْبُرَ الشَّعْبُ الَّذِي اقْتَنَيْتَهُ.', 'خروج 15:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 17, 'تَجِيءُ بِهِمْ وَتَغْرِسُهُمْ فِي جَبَلِ مِيرَاثِكَ، الْمَكَانِ الَّذِي صَنَعْتَهُ يَا رَبُّ لِسَكَنِكَ الْمَقْدِسِ الَّذِي هَيَّأَتْهُ يَدَاكَ يَا رَبُّ.', 'خروج 15:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 18, 'الرَّبُّ يَمْلِكُ إِلَى الدَّهْرِ وَالْأَبَدِ».', 'خروج 15:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 19, 'فَإِنَّ خَيْلَ فِرْعَوْنَ دَخَلَتْ بِمَرْكَبَاتِهِ وَفُرْسَانِهِ إِلَى الْبَحْرِ، وَرَدَّ الرَّبُّ عَلَيْهِمْ مَاءَ الْبَحْرِ. وَأَمَّا بَنُو إِسْرَائِيلَ فَمَشَوْا عَلَى الْيَابِسَةِ فِي وَسَطِ الْبَحْرِ.', 'خروج 15:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 20, 'فَأَخَذَتْ مَرْيَمُ النَّبِيَّةُ أُخْتُ هَارُونَ الدُّفَّ بِيَدِهَا، وَخَرَجَتْ جَمِيعُ النِّسَاءِ وَرَاءَهَا بِدُفُوفٍ وَرَقْصٍ.', 'خروج 15:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 21, 'وَأَجَابَتْهُمْ مَرْيَمُ׃ «رَنِّمُوا لِلرَّبِّ فَإِنَّهُ قَدْ تَعَظَّمَ. الْفَرَسَ وَرَاكِبَهُ طَرَحَهُمَا فِي الْبَحْرِ».', 'خروج 15:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 22, 'ثُمَّ ارْتَحَلَ مُوسَى بِإِسْرَائِيلَ مِنْ بَحْرِ سُوفَ وَخَرَجُوا إِلَى بَرِّيَّةِ شُورٍ. فَسَارُوا ثَلَاثَةَ أَيَّامٍ فِي الْبَرِّيَّةِ وَلَمْ يَجِدُوا مَاءً.', 'خروج 15:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 23, 'فَجَاءُوا إِلَى مَارَّةَ، وَلَمْ يَقْدِرُوا أَنْ يَشْرَبُوا مَاءً مِنْ مَارَّةَ لِأَنَّهُ مُرٌّ. لِذَلِكَ دُعِيَ اسْمُهَا «مَارَّةَ».', 'خروج 15:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 24, 'فَتَذَمَّرَ الشَّعْبُ عَلَى مُوسَى قَائِلِينَ׃ «مَاذَا نَشْرَبُ؟»', 'خروج 15:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 25, 'فَصَرَخَ إِلَى الرَّبِّ. فَأَرَاهُ الرَّبُّ شَجَرَةً فَطَرَحَهَا فِي الْمَاءِ فَصَارَ الْمَاءُ عَذْبًا. هُنَاكَ وَضَعَ لَهُ فَرِيضَةً وَحُكْمًا، وَهُنَاكَ امْتَحَنَهُ.', 'خروج 15:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 26, 'فَقَالَ׃ «إِنْ كُنْتَ تَسْمَعُ لِصَوْتِ الرَّبِّ إِلَهِكَ، وَتَصْنَعُ الْحَقَّ فِي عَيْنَيْهِ، وَتَصْغَى إِلَى وَصَايَاهُ وَتَحْفَظُ جَمِيعَ فَرَائِضِهِ، فَمَرَضًا مَا مِمَّا وَضَعْتُهُ عَلَى الْمِصْرِيِّينَ لَا أَضَعُ عَلَيْكَ. فَإِنِّي أَنَا الرَّبُّ شَافِيكَ».', 'خروج 15:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 15, 27, 'ثُمَّ جَاءُوا إِلَى إِيلِيمَ وَهُنَاكَ اثْنَتَا عَشْرَةَ عَيْنَ مَاءٍ وَسَبْعُونَ نَخْلَةً. فَنَزَلُوا هُنَاكَ عِنْدَ الْمَاءِ.', 'خروج 15:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 1, 'ثُمَّ ارْتَحَلُوا مِنْ إِيلِيمَ. وَأَتَى كُلُّ جَمَاعَةِ بَنِي إِسْرَائِيلَ إِلَى بَرِّيَّةِ سِينٍ، الَّتِي بَيْنَ إِيلِيمَ وَسِينَاءَ فِي الْيَوْمِ الْخَامِسَ عَشَرَ مِنَ الشَّهْرِ الثَّانِي بَعْدَ خُرُوجِهِمْ مِنْ أَرْضِ مِصْرَ.', 'خروج 16:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 2, 'فَتَذَمَّرَ كُلُّ جَمَاعَةِ بَنِي إِسْرَائِيلَ عَلَى مُوسَى وَهَارُونَ فِي الْبَرِّيَّةِ.', 'خروج 16:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 3, 'وَقَالَ لَهُمَا بَنُو إِسْرَائِيلَ׃ «لَيْتَنَا مُتْنَا بِيَدِ الرَّبِّ فِي أَرْضِ مِصْرَ، إِذْ كُنَّا جَالِسِينَ عِنْدَ قُدُورِ اللَّحْمِ نَأْكُلُ خُبْزًا لِلشَّبَعِ. فَإِنَّكُمَا أَخْرَجْتُمَانَا إِلَى هَذَا الْقَفْرِ لِكَيْ تُمِيتَا كُلَّ هَذَا الْجُمْهُورِ بِالْجُوعِ».', 'خروج 16:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 4, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «هَا أَنَا أُمْطِرُ لَكُمْ خُبْزًا مِنَ السَّمَاءِ. فَيَخْرُجُ الشَّعْبُ وَيَلْتَقِطُونَ حَاجَةَ الْيَوْمِ بِيَوْمِهَا. لِكَيْ أَمْتَحِنَهُمْ، أَيَسْلُكُونَ فِي نَامُوسِي أَمْ لَا.', 'خروج 16:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 5, 'وَيَكُونُ فِي الْيَوْمِ السَّادِسِ أَنَّهُمْ يُهَيِّئُونَ مَا يَجِيئُونَ بِهِ فَيَكُونُ ضِعْفَ مَا يَلْتَقِطُونَهُ يَوْمًا فَيَوْمًا».', 'خروج 16:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 6, 'فَقَالَ مُوسَى وَهَارُونُ لِجَمِيعِ بَنِي إِسْرَائِيلَ׃ «فِي الْمَسَاءِ تَعْلَمُونَ أَنَّ الرَّبَّ أَخْرَجَكُمْ مِنْ أَرْضِ مِصْرَ.', 'خروج 16:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 7, 'وَفِي الصَّبَاحِ تَرَوْنَ مَجْدَ الرَّبِّ لِاسْتِمَاعِهِ تَذَمُّرَكُمْ عَلَى الرَّبِّ. وَأَمَّا نَحْنُ فَمَاذَا حَتَّى تَتَذَمَّرُوا عَلَيْنَا؟».', 'خروج 16:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 8, 'وَقَالَ مُوسَى׃ «ذَلِكَ بِأَنَّ الرَّبَّ يُعْطِيكُمْ فِي الْمَسَاءِ لَحْمًا لِتَأْكُلُوا، وَفِي الصَّبَاحِ خُبْزًا لِتَشْبَعُوا، لِاسْتِمَاعِ الرَّبِّ تَذَمُّرَكُمُ الَّذِي تَتَذَمَّرُونَ عَلَيْهِ. وَأَمَّا نَحْنُ فَمَاذَا؟ لَيْسَ عَلَيْنَا تَذَمُّرُكُمْ بَلْ عَلَى الرَّبِّ».', 'خروج 16:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 9, 'وَقَالَ مُوسَى لِهَارُونَ׃ «قُلْ لِكُلِّ جَمَاعَةِ بَنِي إِسْرَائِيلَ׃ اقْتَرِبُوا إِلَى أَمَامِ الرَّبِّ لِأَنَّهُ قَدْ سَمِعَ تَذَمُّرَكُمْ».', 'خروج 16:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 10, 'فَحَدَثَ إِذْ كَانَ هَارُونُ يُكَلِّمُ كُلَّ جَمَاعَةِ بَنِي إِسْرَائِيلَ أَنَّهُمُ الْتَفَتُوا نَحْوَ الْبَرِّيَّةِ، وَإِذَا مَجْدُ الرَّبِّ قَدْ ظَهَرَ فِي السَّحَابِ.', 'خروج 16:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 11, 'فَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 16:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 12, '«سَمِعْتُ تَذَمُّرَ بَنِي إِسْرَائِيلَ. كَلِّمْهُمْ قَائِلًا׃ فِي الْعَشِيَّةِ تَأْكُلُونَ لَحْمًا، وَفِي الصَّبَاحِ تَشْبَعُونَ خُبْزًا، وَتَعْلَمُونَ أَنِّي أَنَا الرَّبُّ إِلَهُكُمْ».', 'خروج 16:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 13, 'فَكَانَ فِي الْمَسَاءِ أَنَّ السَّلْوَى صَعِدَتْ وَغَطَّتِ الْمَحَلَّةَ. وَفِي الصَّبَاحِ كَانَ سَقِيطُ النَّدَى حَوَالَيِ الْمَحَلَّةِ.', 'خروج 16:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 14, 'وَلَمَّا ارْتَفَعَ سَقِيطُ النَّدَى إِذَا عَلَى وَجْهِ الْبَرِّيَّةِ شَيْءٌ دَقِيقٌ مِثْلُ قُشُورٍ. دَقِيقٌ كَالْجَلِيدِ عَلَى الْأَرْضِ.', 'خروج 16:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 15, 'فَلَمَّا رَأَى بَنُو إِسْرَائِيلَ قَالُوا بَعْضُهُمْ لِبَعْضٍ׃ «مَنْ هُوَ؟» لِأَنَّهُمْ لَمْ يَعْرِفُوا مَا هُوَ. فَقَالَ لَهُمْ مُوسَى׃ «هُوَ الْخُبْزُ الَّذِي أَعْطَاكُمُ الرَّبُّ لِتَأْكُلُوا.', 'خروج 16:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 16, 'هَذَا هُوَ الشَّيْءُ الَّذِي أَمَرَ بِهِ الرَّبُّ. اِلْتَقِطُوا مِنْهُ كُلُّ وَاحِدٍ عَلَى حَسَبِ أُكْلِهِ. عُمِرًا لِلرَّأْسِ عَلَى عَدَدِ نُفُوسِكُمْ تَأْخُذُونَ، كُلُّ وَاحِدٍ لِلَّذِينَ فِي خَيْمَتِهِ».', 'خروج 16:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 17, 'فَفَعَلَ بَنُو إِسْرَائِيلَ هَكَذَا، وَالْتَقَطُوا بَيْنَ مُكَثِّرٍ وَمُقَلِّلٍ.', 'خروج 16:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 18, 'وَلَمَّا كَالُوا بِالْعُمِرِ، لَمْ يُفْضِلِ الْمُكَثِّرُ وَالْمُقَلِّلُ لَمْ يُنْقِصْ. كَانُوا قَدِ الْتَقَطُوا كُلُّ وَاحِدٍ عَلَى حَسَبِ أُكْلِهِ.', 'خروج 16:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 19, 'وَقَالَ لَهُمْ مُوسَى׃ «لَا يُبْقِ أَحَدٌ مِنْهُ إِلَى الصَّبَاحِ».', 'خروج 16:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 20, 'لَكِنَّهُمْ لَمْ يَسْمَعُوا لِمُوسَى، بَلْ أَبْقَى مِنْهُ أُنَاسٌ إِلَى الصَّبَاحِ، فَتَوَلَّدَ فِيهِ دُودٌ وَأَنْتَنَ. فَسَخَطَ عَلَيْهِمْ مُوسَى.', 'خروج 16:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 21, 'وَكَانُوا يَلْتَقِطُونَهُ صَبَاحًا فَصَبَاحًا كُلُّ وَاحِدٍ عَلَى حَسَبِ أُكْلِهِ. وَإِذَا حَمِيَتِ الشَّمْسُ كَانَ يَذُوبُ.', 'خروج 16:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 22, 'ثُمَّ كَانَ فِي الْيَوْمِ السَّادِسِ أَنَّهُمُ الْتَقَطُوا خُبْزًا مُضَاعَفًا، عُمِرَيْنِ لِلْوَاحِدِ. فَجَاءَ كُلُّ رُؤَسَاءِ الْجَمَاعَةِ وَأَخْبَرُوا مُوسَى.', 'خروج 16:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 23, 'فَقَالَ لَهُمْ׃ «هَذَا مَا قَالَ الرَّبُّ׃ غَدًا عُطْلَةٌ، سَبْتٌ مُقَدَّسٌ لِلرَّبِّ. اخْبِزُوا مَا تَخْبِزُونَ وَاطْبُخُوا مَا تَطْبُخُونَ. وَكُلُّ مَا فَضِلَ ضَعُوهُ عِنْدَكُمْ لِيُحْفَظَ إِلَى الْغَدِ».', 'خروج 16:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 24, 'فَوَضَعُوهُ إِلَى الْغَدِ كَمَا أَمَرَ مُوسَى، فَلَمْ يُنْتِنْ وَلَا صَارَ فِيهِ دُودٌ.', 'خروج 16:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 25, 'فَقَالَ مُوسَى׃ «كُلُوهُ الْيَوْمَ، لِأَنَّ لِلرَّبِّ الْيَوْمَ سَبْتًا. الْيَوْمَ لَا تَجِدُونَهُ فِي الْحَقْلِ.', 'خروج 16:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 26, 'سِتَّةَ أَيَّامٍ تَلْتَقِطُونَهُ، وَأَمَّا الْيَوْمُ السَّابِعُ فَفِيهِ سَبْتٌ، لَا يُوجَدُ فِيهِ».', 'خروج 16:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 27, 'وَحَدَثَ فِي الْيَوْمِ السَّابِعِ أَنَّ بَعْضَ الشَّعْبِ خَرَجُوا لِيَلْتَقِطُوا فَلَمْ يَجِدُوا.', 'خروج 16:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 28, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «إِلَى مَتَى تَأْبَوْنَ أَنْ تَحْفَظُوا وَصَايَايَ وَشَرَائِعِي؟', 'خروج 16:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 29, 'اُنْظُرُوا! إِنَّ الرَّبَّ أَعْطَاكُمُ السَّبْتَ. لِذَلِكَ هُوَ يُعْطِيكُمْ فِي الْيَوْمِ السَّادِسِ خُبْزَ يَوْمَيْنِ. اجْلِسُوا كُلُّ وَاحِدٍ فِي مَكَانِهِ. لَا يَخْرُجْ أَحَدٌ مِنْ مَكَانِهِ فِي الْيَوْمِ السَّابِعِ».', 'خروج 16:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 30, 'فَاسْتَرَاحَ الشَّعْبُ فِي الْيَوْمِ السَّابِعِ.', 'خروج 16:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 31, 'وَدَعَا بَيْتُ إِسْرَائِيلَ اسْمَهُ «مَنًّا». وَهُوَ كَبِزْرِ الْكُزْبَرَةِ، أَبْيَضُ، وَطَعْمُهُ كَرِقَاقٍ بِعَسَلٍ.', 'خروج 16:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 32, 'وَقَالَ مُوسَى׃ «هَذَا هُوَ الشَّيْءُ الَّذِي أَمَرَ بِهِ الرَّبُّ. مِلْءُ الْعُمِرِ مِنْهُ يَكُونُ لِلْحِفْظِ فِي أَجْيَالِكُمْ. لِكَيْ يَرَوْا الْخُبْزَ الَّذِي أَطْعَمْتُكُمْ فِي الْبَرِّيَّةِ حِينَ أَخْرَجْتُكُمْ مِنْ أَرْضِ مِصْرَ».', 'خروج 16:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 33, 'وَقَالَ مُوسَى لِهَارُونَ׃ «خُذْ قِسْطًا وَاحِدًا وَاجْعَلْ فِيهِ مِلْءَ الْعُمِرِ مَنًّا، وَضَعْهُ أَمَامَ الرَّبِّ لِلْحِفْظِ فِي أَجْيَالِكُمْ».', 'خروج 16:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 34, 'كَمَا أَمَرَ الرَّبُّ مُوسَى وَضَعَهُ هَارُونُ أَمَامَ الشَّهَادَةِ لِلْحِفْظِ.', 'خروج 16:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 35, 'وَأَكَلَ بَنُو إِسْرَائِيلَ الْمَنَّ أَرْبَعِينَ سَنَةً حَتَّى جَاءُوا إِلَى أَرْضٍ عَامِرَةٍ. أَكَلُوا الْمَنَّ حَتَّى جَاءُوا إِلَى طَرَفِ أَرْضِ كَنْعَانَ.', 'خروج 16:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 16, 36, 'وَأَمَّا الْعُمِرُ فَهُوَ عُشْرُ الْإِيفَةِ.', 'خروج 16:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 1, 'ثُمَّ ارْتَحَلَ كُلُّ جَمَاعَةِ بَنِي إِسْرَائِيلَ مِنْ بَرِّيَّةِ سِينٍ بِحَسَبِ مَرَاحِلِهِمْ عَلَى مُوجِبِ أَمْرِ الرَّبِّ، وَنَزَلُوا فِي رَفِيدِيمَ. وَلَمْ يَكُنْ مَاءٌ لِيَشْرَبَ الشَّعْبُ.', 'خروج 17:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 2, 'فَخَاصَمَ الشَّعْبُ مُوسَى وَقَالُوا׃ «أَعْطُونَا مَاءً لِنَشْرَبَ». فَقَالَ لَهُمْ مُوسَى׃ «لِمَاذَا تُخَاصِمُونَنِي؟ لِمَاذَا تُجَرِّبُونَ الرَّبَّ؟»', 'خروج 17:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 3, 'وَعَطِشَ هُنَاكَ الشَّعْبُ إِلَى الْمَاءِ، وَتَذَمَّرَ الشَّعْبُ عَلَى مُوسَى وَقَالُوا׃ «لِمَاذَا أَصْعَدْتَنَا مِنْ مِصْرَ لِتُمِيتَنَا وَأَوْلَادَنَا وَمَوَاشِيَنَا بِالْعَطَشِ؟»', 'خروج 17:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 4, 'فَصَرَخَ مُوسَى إِلَى الرَّبِّ قَائِلًا׃ «مَاذَا أَفْعَلُ بِهَذَا الشَّعْبِ؟ بَعْدَ قَلِيلٍ يَرْجُمُونَنِي».', 'خروج 17:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 5, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «مُرَّ قُدَّامَ الشَّعْبِ، وَخُذْ مَعَكَ مِنْ شُيُوخِ إِسْرَائِيلَ. وَعَصَاكَ الَّتِي ضَرَبْتَ بِهَا النَّهْرَ خُذْهَا فِي يَدِكَ وَاذْهَبْ.', 'خروج 17:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 6, 'هَا أَنَا أَقِفُ أَمَامَكَ هُنَاكَ عَلَى الصَّخْرَةِ فِي حُورِيبَ، فَتَضْرِبُ الصَّخْرَةَ فَيَخْرُجُ مِنْهَا مَاءٌ لِيَشْرَبَ الشَّعْبُ». فَفَعَلَ مُوسَى هَكَذَا أَمَامَ عُيُونِ شُيُوخِ إِسْرَائِيلَ.', 'خروج 17:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 7, 'وَدَعَا اسْمَ الْمَوْضِعِ «مَسَّةَ وَمَرِيبَةَ» مِنْ أَجْلِ مُخَاصَمَةِ بَنِي إِسْرَائِيلَ، وَمِنْ أَجْلِ تَجْرِبَتِهِمْ لِلرَّبِّ قَائِلِينَ׃ «أَفِي وَسَطِنَا الرَّبُّ أَمْ لَا؟».', 'خروج 17:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 8, 'وَأَتَى عَمَالِيقُ وَحَارَبَ إِسْرَائِيلَ فِي رَفِيدِيمَ.', 'خروج 17:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 9, 'فَقَالَ مُوسَى لِيَشُوعَ׃ «انْتَخِبْ لَنَا رِجَالًا وَاخْرُجْ حَارِبْ عَمَالِيقَ. وَغَدًا أَقِفُ أَنَا عَلَى رَأْسِ التَّلَّةِ وَعَصَا اللهِ فِي يَدِي».', 'خروج 17:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 10, 'فَفَعَلَ يَشُوعُ كَمَا قَالَ لَهُ مُوسَى لِيُحَارِبَ عَمَالِيقَ. وَأَمَّا مُوسَى وَهَارُونُ وَحُورُ فَصَعِدُوا عَلَى رَأْسِ التَّلَّةِ.', 'خروج 17:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 11, 'وَكَانَ إِذَا رَفَعَ مُوسَى يَدَهُ أَنَّ إِسْرَائِيلَ يَغْلِبُ، وَإِذَا خَفَضَ يَدَهُ أَنَّ عَمَالِيقَ يَغْلِبُ.', 'خروج 17:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 12, 'فَلَمَّا صَارَتْ يَدَا مُوسَى ثَقِيلَتَيْنِ، أَخَذَا حَجَرًا وَوَضَعَاهُ تَحْتَهُ فَجَلَسَ عَلَيْهِ. وَدَعَمَ هَارُونُ وَحُورُ يَدَيْهِ، الْوَاحِدُ مِنْ هُنَا وَالْآخَرُ مِنْ هُنَاكَ. فَكَانَتْ يَدَاهُ ثَابِتَتَيْنِ إِلَى غُرُوبِ الشَّمْسِ.', 'خروج 17:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 13, 'فَهَزَمَ يَشُوعُ عَمَالِيقَ وَقَوْمَهُ بِحَدِّ السَّيْفِ.', 'خروج 17:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 14, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «اكْتُبْ هَذَا تَذْكَارًا فِي الْكِتَابِ، وَضَعْهُ فِي مَسَامِعِ يَشُوعَ. فَإِنِّي سَوْفَ أَمْحُو ذِكْرَ عَمَالِيقَ مِنْ تَحْتِ السَّمَاءِ».', 'خروج 17:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 15, 'فَبَنَى مُوسَى مَذْبَحًا وَدَعَا اسْمَهُ «يَهْوَهْ نِسِّي».', 'خروج 17:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 17, 16, 'وَقَالَ׃ «إِنَّ الْيَدَ عَلَى كُرْسِيِّ الرَّبِّ. لِلرَّبِّ حَرْبٌ مَعَ عَمَالِيقَ مِنْ دَوْرٍ إِلَى دَوْرٍ».', 'خروج 17:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 1, 'فَسَمِعَ يَثْرُونُ كَاهِنُ مِدْيَانَ، حَمُو مُوسَى، كُلَّ مَا صَنَعَ اللهُ إِلَى مُوسَى وَإِلَى إِسْرَائِيلَ شَعْبِهِ׃ أَنَّ الرَّبَّ أَخْرَجَ إِسْرَائِيلَ مِنْ مِصْرَ.', 'خروج 18:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 2, 'فَأَخَذَ يَثْرُونُ حَمُو مُوسَى صِفُّورَةَ امْرَأَةَ مُوسَى بَعْدَ صَرْفِهَا', 'خروج 18:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 3, 'وَابْنَيْهَا، اللَّذَيْنِ اسْمُ أَحَدِهِمَا جِرْشُومُ، لِأَنَّهُ قَالَ׃ «كُنْتُ نَزِيلًا فِي أَرْضٍ غَرِيبَةٍ».', 'خروج 18:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 4, 'وَاسْمُ الْآخَرِ أَلِيعَازَرُ، لِأَنَّهُ قَالَ׃ «إِلَهُ أَبِي كَانَ عَوْنِي وَأَنْقَذَنِي مِنْ سَيْفِ فِرْعَوْنَ».', 'خروج 18:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 5, 'وَأَتَى يَثْرُونُ حَمُو مُوسَى وَابْنَاهُ وَامْرَأَتُهُ إِلَى مُوسَى إِلَى الْبَرِّيَّةِ حَيْثُ كَانَ نَازِلًا عِنْدَ جَبَلِ اللهِ.', 'خروج 18:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 6, 'فَقَالَ لِمُوسَى׃ «أَنَا حَمُوكَ يَثْرُونُ، آتٍ إِلَيْكَ وَامْرَأَتُكَ وَابْنَاهَا مَعَهَا».', 'خروج 18:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 7, 'فَخَرَجَ مُوسَى لِاسْتِقْبَالِ حَمِيهِ وَسَجَدَ وَقَبَّلَهُ. وَسَأَلَ كُلُّ وَاحِدٍ صَاحِبَهُ عَنْ سَلَامَتِهِ، ثُمَّ دَخَلَا إِلَى الْخَيْمَةِ.', 'خروج 18:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 8, 'فَقَصَّ مُوسَى عَلَى حَمِيهِ كُلَّ مَا صَنَعَ الرَّبُّ بِفِرْعَوْنَ وَالْمِصْرِيِّينَ مِنْ أَجْلِ إِسْرَائِيلَ، وَكُلَّ الْمَشَقَّةِ الَّتِي أَصَابَتْهُمْ فِي الطَّرِيقِ فَخَلَّصَهُمُ الرَّبُّ.', 'خروج 18:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 9, 'فَفَرِحَ يَثْرُونُ بِجَمِيعِ الْخَيْرِ الَّذِي صَنَعَهُ إِلَى إِسْرَائِيلَ الرَّبُّ، الَّذِي أَنْقَذَهُ مِنْ أَيْدِي الْمِصْرِيِّينَ.', 'خروج 18:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 10, 'وَقَالَ يَثْرُونُ׃ «مُبَارَكٌ الرَّبُّ الَّذِي أَنْقَذَكُمْ مِنْ أَيْدِي الْمِصْرِيِّينَ وَمِنْ يَدِ فِرْعَوْنَ. اَلَّذِي أَنْقَذَ الشَّعْبَ مِنْ تَحْتِ أَيْدِي الْمِصْرِيِّينَ.', 'خروج 18:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 11, 'الْآنَ عَلِمْتُ أَنَّ الرَّبَّ أَعْظَمُ مِنْ جَمِيعِ الْآلِهَةِ، لِأَنَّهُ فِي الشَّيْءِ الَّذِي بَغَوْا بِهِ كَانَ عَلَيْهِمْ».', 'خروج 18:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 12, 'فَأَخَذَ يَثْرُونُ حَمُو مُوسَى مُحْرَقَةً وَذَبَائِحَ لِلهِ. وَجَاءَ هَارُونُ وَجَمِيعُ شُيُوخِ إِسْرَائِيلَ لِيَأْكُلُوا طَعَامًا مَعَ حَمِي مُوسَى أَمَامَ اللهِ.', 'خروج 18:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 13, 'وَحَدَثَ فِي الْغَدِ أَنَّ مُوسَى جَلَسَ لِيَقْضِيَ لِلشَّعْبِ. فَوَقَفَ الشَّعْبُ عِنْدَ مُوسَى مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ.', 'خروج 18:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 14, 'فَلَمَّا رَأَى حَمُو مُوسَى كُلَّ مَا هُوَ صَانِعٌ لِلشَّعْبِ، قَالَ׃ «مَا هَذَا الْأَمْرُ الَّذِي أَنْتَ صَانِعٌ لِلشَّعْبِ؟ مَا بَالُكَ جَالِسًا وَحْدَكَ وَجَمِيعُ الشَّعْبِ وَاقِفٌ عِنْدَكَ مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ؟»', 'خروج 18:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 15, 'فَقَالَ مُوسَى لِحَمِيهِ׃ «إِنَّ الشَّعْبَ يَأْتِي إِلَيَّ لِيَسْأَلَ اللهَ.', 'خروج 18:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 16, 'إِذَا كَانَ لَهُمْ دَعْوَى يَأْتُونَ إِلَيَّ فَأَقْضِي بَيْنَ الرَّجُلِ وَصَاحِبِهِ، وَأُعَرِّفُهُمْ فَرَائِضَ اللهِ وَشَرَائِعَهُ».', 'خروج 18:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 17, 'فَقَالَ حَمُو مُوسَى لَهُ׃ «لَيْسَ جَيِّدًا الْأَمْرُ الَّذِي أَنْتَ صَانِعٌ.', 'خروج 18:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 18, 'إِنَّكَ تَكِلُّ أَنْتَ وَهَذَا الشَّعْبُ الَّذِي مَعَكَ جَمِيعًا، لِأَنَّ الْأَمْرَ أَعْظَمُ مِنْكَ. لَا تَسْتَطِيعُ أَنْ تَصْنَعَهُ وَحْدَكَ.', 'خروج 18:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 19, 'اَلْآنَ اسْمَعْ لِصَوْتِي فَأَنْصَحَكَ. فَلْيَكُنِ اللهُ مَعَكَ. كُنْ أَنْتَ لِلشَّعْبِ أَمَامَ اللهِ، وَقَدِّمْ أَنْتَ الدَّعَاوِيَ إِلَى اللهِ،', 'خروج 18:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 20, 'وَعَلِّمْهُمُ الْفَرَائِضَ وَالشَّرَائِعَ، وَعَرِّفْهُمُ الطَّرِيقَ الَّذِي يَسْلُكُونَهُ، وَالْعَمَلَ الَّذِي يَعْمَلُونَهُ.', 'خروج 18:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 21, 'وَأَنْتَ تَنْظُرُ مِنْ جَمِيعِ الشَّعْبِ ذَوِي قُدْرَةٍ خَائِفِينَ اللهَ، أُمَنَاءَ مُبْغِضِينَ الرَّشْوَةَ، وَتُقِيمُهُمْ عَلَيْهِمْ رُؤَسَاءَ أُلُوفٍ، وَرُؤَسَاءَ مِئَاتٍ، وَرُؤَسَاءَ خَمَاسِينَ، وَرُؤَسَاءَ عَشَرَاتٍ،', 'خروج 18:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 22, 'فَيَقْضُونَ لِلشَّعْبِ كُلَّ حِينٍ. وَيَكُونُ أَنَّ كُلَّ الدَّعَاوِي الْكَبِيرَةِ يَجِيئُونَ بِهَا إِلَيْكَ، وَكُلَّ الدَّعَاوِي الصَّغِيرَةِ يَقْضُونَ هُمْ فِيهَا. وَخَفِّفْ عَنْ نَفْسِكَ، فَهُمْ يَحْمِلُونَ مَعَكَ.', 'خروج 18:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 23, 'إِنْ فَعَلْتَ هَذَا الْأَمْرَ وَأَوْصَاكَ اللهُ تَسْتَطِيعُ الْقِيَامَ. وَكُلُّ هَذَا الشَّعْبِ أَيْضًا يَأْتِي إِلَى مَكَانِهِ بِالسَّلَامِ».', 'خروج 18:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 24, 'فَسَمِعَ مُوسَى لِصَوْتِ حَمِيهِ وَفَعَلَ كُلَّ مَا قَالَ.', 'خروج 18:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 25, 'وَاخْتَارَ مُوسَى ذَوِي قُدْرَةٍ مِنْ جَمِيعِ إِسْرَائِيلَ وَجَعَلَهُمْ رُؤُوسًا عَلَى الشَّعْبِ، رُؤَسَاءَ أُلُوفٍ، وَرُؤَسَاءَ مِئَاتٍ، وَرُؤَسَاءَ خَمَاسِينَ، وَرُؤَسَاءَ عَشَرَاتٍ.', 'خروج 18:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 26, 'فَكَانُوا يَقْضُونَ لِلشَّعْبِ كُلَّ حِينٍ. الدَّعَاوِي الْعَسِرَةُ يَجِيئُونَ بِهَا إِلَى مُوسَى، وَكُلُّ الدَّعَاوِي الصَّغِيرَةِ يَقْضُونَ هُمْ فِيهَا.', 'خروج 18:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 18, 27, 'ثُمَّ صَرَفَ مُوسَى حَمَاهُ فَمَضَى إِلَى أَرْضِهِ.', 'خروج 18:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 1, 'فِي الشَّهْرِ الثَّالِثِ بَعْدَ خُرُوجِ بَنِي إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ، فِي ذَلِكَ الْيَوْمِ جَاءُوا إِلَى بَرِّيَّةِ سِينَاءَ.', 'خروج 19:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 2, 'ارْتَحَلُوا مِنْ رَفِيدِيمَ وَجَاءُوا إِلَى بَرِّيَّةِ سِينَاءَ فَنَزَلُوا فِي الْبَرِّيَّةِ. هُنَاكَ نَزَلَ إِسْرَائِيلُ مُقَابِلَ الْجَبَلِ.', 'خروج 19:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 3, 'وَأَمَّا مُوسَى فَصَعِدَ إِلَى اللهِ. فَنَادَاهُ الرَّبُّ مِنَ الْجَبَلِ قَائِلًا׃ «هَكَذَا تَقُولُ لِبَيْتِ يَعْقُوبَ، وَتُخْبِرُ بَنِي إِسْرَائِيلَ׃', 'خروج 19:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 4, 'أَنْتُمْ رَأَيْتُمْ مَا صَنَعْتُ بِالْمِصْرِيِّينَ. وَأَنَا حَمَلْتُكُمْ عَلَى أَجْنِحَةِ النُّسُورِ وَجِئْتُ بِكُمْ إِلَيَّ.', 'خروج 19:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 5, 'فَالْآنَ إِنْ سَمِعْتُمْ لِصَوْتِي، وَحَفِظْتُمْ عَهْدِي تَكُونُونَ لِي خَاصَّةً مِنْ بَيْنِ جَمِيعِ الشُّعُوبِ. فَإِنَّ لِي كُلَّ الْأَرْضِ.', 'خروج 19:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 6, 'وَأَنْتُمْ تَكُونُونَ لِي مَمْلَكَةَ كَهَنَةٍ وَأُمَّةً مُقَدَّسَةً. هَذِهِ هِيَ الْكَلِمَاتُ الَّتِي تُكَلِّمُ بِهَا بَنِي إِسْرَائِيلَ».', 'خروج 19:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 7, 'فَجَاءَ مُوسَى وَدَعَا شُيُوخَ الشَّعْبِ وَوَضَعَ قُدَّامَهُمْ كُلَّ هَذِهِ الْكَلِمَاتِ الَّتِي أَوْصَاهُ بِهَا الرَّبُّ.', 'خروج 19:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 8, 'فَأَجَابَ جَمِيعُ الشَّعْبِ مَعًا وَقَالُوا׃ «كُلُّ مَا تَكَلَّمَ بِهِ الرَّبُّ نَفْعَلُ». فَرَدَّ مُوسَى كَلَامَ الشَّعْبِ إِلَى الرَّبِّ.', 'خروج 19:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 9, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «هَا أَنَا آتٍ إِلَيْكَ فِي ظَلَامِ السَّحَابِ لِكَيْ يَسْمَعَ الشَّعْبُ حِينَمَا أَتَكَلَّمُ مَعَكَ، فَيُؤْمِنُوا بِكَ أَيْضًا إِلَى الْأَبَدِ». وَأَخْبَرَ مُوسَى الرَّبَّ بِكَلَامِ الشَّعْبِ.', 'خروج 19:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 10, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «اذْهَبْ إِلَى الشَّعْبِ وَقَدِّسْهُمُ الْيَوْمَ وَغَدًا، وَلْيَغْسِلُوا ثِيَابَهُمْ،', 'خروج 19:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 11, 'وَيَكُونُوا مُسْتَعِدِّينَ لِلْيَوْمِ الثَّالِثِ. لِأَنَّهُ فِي الْيَوْمِ الثَّالِثِ يَنْزِلُ الرَّبُّ أَمَامَ عْيُونِ جَمِيعِ الشَّعْبِ عَلَى جَبَلِ سِينَاءَ.', 'خروج 19:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 12, 'وَتُقِيمُ لِلشَّعْبِ حُدُودًا مِنْ كُلِّ نَاحِيَةٍ، قَائِلًا׃ احْتَرِزُوا مِنْ أَنْ تَصْعَدُوا إِلَى الْجَبَلِ أَوْ تَمَسُّوا طَرَفَهُ. كُلُّ مَنْ يَمَسُّ الْجَبَلَ يُقْتَلُ قَتْلًا.', 'خروج 19:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 13, 'لَا تَمَسُّهُ يَدٌ بَلْ يُرْجَمُ رَجْمًا أَوْ يُرْمَى رَمْيًا. بَهِيمَةً كَانَ أَمْ إِنْسَانًا لَا يَعِيشُ. أَمَّا عِنْدَ صَوْتِ الْبُوقِ فَهُمْ يَصْعَدُونَ إِلَى الْجَبَلِ».', 'خروج 19:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 14, 'فَانْحَدَرَ مُوسَى مِنَ الْجَبَلِ إِلَى الشَّعْبِ، وَقَدَّسَ الشَّعْبَ وَغَسَلُوا ثِيَابَهُمْ.', 'خروج 19:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 15, 'وَقَالَ لِلشَّعْبِ׃ «كُونُوا مُسْتَعِدِّينَ لِلْيَوْمِ الثَّالِثِ. لَا تَقْرُبُوا امْرَأَةً».', 'خروج 19:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 16, 'وَحَدَثَ فِي الْيَوْمِ الثَّالِثِ لَمَّا كَانَ الصَّبَاحُ أَنَّهُ صَارَتْ رُعُودٌ وَبُرُوقٌ وَسَحَابٌ ثَقِيلٌ عَلَى الْجَبَلِ، وَصَوْتُ بُوقٍ شَدِيدٌ جِدًّا. فَارْتَعَدَ كُلُّ الشَّعْبِ الَّذِي فِي الْمَحَلَّةِ.', 'خروج 19:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 17, 'وَأَخْرَجَ مُوسَى الشَّعْبَ مِنَ الْمَحَلَّةِ لِمُلَاقَاةِ اللهِ، فَوَقَفُوا فِي أَسْفَلِ الْجَبَلِ.', 'خروج 19:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 18, 'وَكَانَ جَبَلُ سِينَاءَ كُلُّهُ يُدَخِّنُ مِنْ أَجْلِ أَنَّ الرَّبَّ نَزَلَ عَلَيْهِ بِالنَّارِ، وَصَعِدَ دُخَانُهُ كَدُخَانِ الْأَتُونِ، وَارْتَجَفَ كُلُّ الْجَبَلِ جِدًّا.', 'خروج 19:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 19, 'فَكَانَ صَوْتُ الْبُوقِ يَزْدَادُ اشْتِدَادًا جِدًّا، وَمُوسَى يَتَكَلَّمُ وَاللهُ يُجِيبُهُ بِصَوْتٍ.', 'خروج 19:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 20, 'وَنَزَلَ الرَّبُّ عَلَى جَبَلِ سِينَاءَ، إِلَى رَأْسِ الْجَبَلِ، وَدَعَا اللهُ مُوسَى إِلَى رَأْسِ الْجَبَلِ. فَصَعِدَ مُوسَى.', 'خروج 19:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 21, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «انْحَدِرْ حَذِّرِ الشَّعْبَ لِئَلَّا يَقْتَحِمُوا إِلَى الرَّبِّ لِيَنْظُرُوا، فَيَسْقُطَ مِنْهُمْ كَثِيرُونَ.', 'خروج 19:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 22, 'وَلْيَتَقَدَّسْ أَيْضًا الْكَهَنَةُ الَّذِينَ يَقْتَرِبُونَ إِلَى الرَّبِّ لِئَلَّا يَبْطِشَ بِهِمِ الرَّبُّ».', 'خروج 19:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 23, 'فَقَالَ مُوسَى لِلرَّبِّ׃ «لَا يَقْدِرُ الشَّعْبُ أَنْ يَصْعَدَ إِلَى جَبَلِ سِينَاءَ، لِأَنَّكَ أَنْتَ حَذَّرْتَنَا قَائِلًا׃ أَقِمْ حُدُودًا لِلْجَبَلِ وَقَدِّسْهُ».', 'خروج 19:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 24, 'فَقَالَ لَهُ الرَّبُّ׃ «اذْهَبِ انْحَدِرْ ثُمَّ اصْعَدْ أَنْتَ وَهَارُونُ مَعَكَ. وَأَمَّا الْكَهَنَةُ وَالشَّعْبُ فَلَا يَقْتَحِمُوا لِيَصْعَدُوا إِلَى الرَّبِّ لِئَلَّا يَبْطِشَ بِهِمْ».', 'خروج 19:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 19, 25, 'فَانْحَدَرَ مُوسَى إِلَى الشَّعْبِ وَقَالَ لَهُمْ.', 'خروج 19:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 1, 'ثُمَّ تَكَلَّمَ اللهُ بِجَمِيعِ هَذِهِ الْكَلِمَاتِ قَائِلًا׃', 'خروج 20:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 2, '«أَنَا الرَّبُّ إِلَهُكَ الَّذِي أَخْرَجَكَ مِنْ أَرْضِ مِصْرَ مِنْ بَيْتِ الْعُبُودِيَّةِ.', 'خروج 20:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 3, 'لَا يَكُنْ لَكَ آلِهَةٌ أُخْرَى أَمَامِي.', 'خروج 20:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 4, 'لَا تَصْنَعْ لَكَ تِمْثَالًا مَنْحُوتًا، وَلَا صُورَةً مَا مِمَّا فِي السَّمَاءِ مِنْ فَوْقُ، وَمَا فِي الْأَرْضِ مِنْ تَحْتُ، وَمَا فِي الْمَاءِ مِنْ تَحْتِ الْأَرْضِ.', 'خروج 20:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 5, 'لَا تَسْجُدْ لَهُنَّ وَلَا تَعْبُدْهُنَّ، لِأَنِّي أَنَا الرَّبَّ إِلَهَكَ إِلَهٌ غَيُورٌ، أَفْتَقِدُ ذُنُوبَ الْآبَاءِ فِي الْأَبْنَاءِ فِي الْجِيلِ الثَّالِثِ وَالرَّابِعِ مِنْ مُبْغِضِيَّ،', 'خروج 20:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 6, 'وَأَصْنَعُ إِحْسَانًا إِلَى أُلُوفٍ مِنْ مُحِبِّيَّ وَحَافِظِي وَصَايَايَ.', 'خروج 20:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 7, 'لَا تَنْطِقْ بِاسْمِ الرَّبِّ إِلَهِكَ بَاطِلًا، لِأَنَّ الرَّبَّ لَا يُبْرِئُ مَنْ نَطَقَ بِاسْمِهِ بَاطِلًا.', 'خروج 20:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 8, 'اُذْكُرْ يَوْمَ السَّبْتِ لِتُقَدِّسَهُ.', 'خروج 20:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 9, 'سِتَّةَ أَيَّامٍ تَعْمَلُ وَتَصْنَعُ جَمِيعَ عَمَلِكَ،', 'خروج 20:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 10, 'وَأَمَّا الْيَوْمُ السَّابِعُ فَفِيهِ سَبْتٌ لِلرَّبِّ إِلَهِكَ. لَا تَصْنَعْ عَمَلًا مَّا أَنْتَ وَابْنُكَ وَابْنَتُكَ وَعَبْدُكَ وَأَمَتُكَ وَبَهِيمَتُكَ وَنَزِيلُكَ الَّذِي دَاخِلَ أَبْوَابِكَ.', 'خروج 20:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 11, 'لِأَنْ فِي سِتَّةِ أَيَّامٍ صَنَعَ الرَّبُّ السَّمَاءَ وَالْأَرْضَ وَالْبَحْرَ وَكُلَّ مَا فِيهَا، وَاسْتَرَاحَ فِي الْيَوْمِ السَّابِعِ. لِذَلِكَ بَارَكَ الرَّبُّ يَوْمَ السَّبْتِ وَقَدَّسَهُ.', 'خروج 20:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 12, 'أَكْرِمْ أَبَاكَ وَأُمَّكَ لِكَيْ تَطُولَ أَيَّامُكَ عَلَى الْأَرْضِ الَّتِي يُعْطِيكَ الرَّبُّ إِلَهُكَ.', 'خروج 20:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 13, 'لَا تَقْتُلْ.', 'خروج 20:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 14, 'لَا تَزْنِ.', 'خروج 20:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 15, 'لَا تَسْرِقْ.', 'خروج 20:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 16, 'لَا تَشْهَدْ عَلَى قَرِيبِكَ شَهَادَةَ زُورٍ.', 'خروج 20:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 17, 'لَا تَشْتَهِ بَيْتَ قَرِيبِكَ. لَا تَشْتَهِ امْرَأَةَ قَرِيبِكَ، وَلَا عَبْدَهُ، وَلَا أَمَتَهُ، وَلَا ثَوْرَهُ، وَلَا حِمَارَهُ، وَلَا شَيْئًا مِمَّا لِقَرِيبِكَ».', 'خروج 20:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 18, 'وَكَانَ جَمِيعُ الشَّعْبِ يَرَوْنَ الرُّعُودَ وَالْبُرُوقَ وَصَوْتَ الْبُوقِ، وَالْجَبَلَ يُدَخِّنُ. وَلَمَّا رَأَى الشَّعْبُ ارْتَعَدُوا وَوَقَفُوا مِنْ بَعِيدٍ،', 'خروج 20:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 19, 'وَقَالُوا لِمُوسَى׃ «تَكَلَّمْ أَنْتَ مَعَنَا فَنَسْمَعَ. وَلَا يَتَكَلَّمْ مَعَنَا اللهُ لِئَلَّا نَمُوتَ».', 'خروج 20:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 20, 'فَقَالَ مُوسَى لِلشَّعْبِ׃ «لَا تَخَافُوا. لِأَنَّ اللهَ إِنَّمَا جَاءَ لِكَيْ يَمْتَحِنَكُمْ، وَلِكَيْ تَكُونَ مَخَافَتُهُ أَمَامَ وُجُوهِكُمْ حَتَّى لَا تُخْطِئُوا».', 'خروج 20:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 21, 'فَوَقَفَ الشَّعْبُ مِنْ بَعِيدٍ، وَأَمَّا مُوسَى فَاقْتَرَبَ إِلَى الضَّبَابِ حَيْثُ كَانَ اللهُ.', 'خروج 20:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 22, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «هَكَذَا تَقُولُ لِبَنِي إِسْرَائِيلَ׃ أَنْتُمْ رَأَيْتُمْ أَنَّنِي مِنَ السَّمَاءِ تَكَلَّمْتُ مَعَكُمْ.', 'خروج 20:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 23, 'لَا تَصْنَعُوا مَعِي آلِهَةَ فِضَّةٍ، وَلَا تَصْنَعُوا لَكُمْ آلِهَةَ ذَهَبٍ.', 'خروج 20:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 24, 'مَذْبَحًا مِنْ تُرَابٍ تَصْنَعُ لِي وَتَذْبَحُ عَلَيْهِ مُحْرَقَاتِكَ وَذَبَائِحَ سَلَامَتِكَ، غَنَمَكَ وَبَقَرَكَ. فِي كُلِّ الْأَمَاكِنِ الَّتِي فِيهَا أَصْنَعُ لِاسْمِي ذِكْرًا آتِي إِلَيْكَ وَأُبَارِكُكَ.', 'خروج 20:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 25, 'وَإِنْ صَنَعْتَ لِي مَذْبَحًا مِنْ حِجَارَةٍ فَلَا تَبْنِهِ مِنْهَا مَنْحُوتَةً. إِذَا رَفَعْتَ عَلَيْهَا إِزْمِيلَكَ تُدَنِّسُهَا.', 'خروج 20:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 20, 26, 'وَلَا تَصْعَدْ بِدَرَجٍ إِلَى مَذْبَحِي كَيْلَا تَنْكَشِفَ عَوْرَتُكَ عَلَيْهِ.', 'خروج 20:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 1, '«وَهَذِهِ هِيَ الْأَحْكَامُ الَّتِي تَضَعُ أَمَامَهُمْ׃', 'خروج 21:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 2, 'إِذَا اشْتَرَيْتَ عَبْدًا عِبْرَانِيًّا، فَسِتَّ سِنِينَ يَخْدِمُ، وَفِي السَّابِعَةِ يَخْرُجُ حُرًّا مَجَّانًا.', 'خروج 21:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 3, 'إِنْ دَخَلَ وَحْدَهُ فَوَحْدَهُ يَخْرُجُ. إِنْ كَانَ بَعْلَ امْرَأَةٍ، تَخْرُجُ امْرَأَتُهُ مَعَهُ.', 'خروج 21:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 4, 'إِنْ أَعْطَاهُ سَيِّدُهُ امْرَأَةً وَوَلَدَتْ لَهُ بَنِينَ أَوْ بَنَاتٍ، فَالْمَرْأَةُ وَأَوْلَادُهَا يَكُونُونَ لِسَيِّدِهِ، وَهُوَ يَخْرُجُ وَحْدَهُ.', 'خروج 21:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 5, 'وَلَكِنْ إِنْ قَالَ الْعَبْدُ׃ أُحِبُّ سَيِّدِي وَامْرَأَتِي وَأَوْلَادِي، لَا أَخْرُجُ حُرًّا،', 'خروج 21:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 6, 'يُقَدِّمُهُ سَيِّدُهُ إِلَى اللهِ، وَيُقَرِّبُهُ إِلَى الْبَابِ أَوْ إِلَى الْقَائِمَةِ، وَيَثْقُبُ سَيِّدُهُ أُذْنَهُ بِالْمِثْقَبِ، فَيَخْدِمُهُ إِلَى الْأَبَدِ.', 'خروج 21:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 7, 'وَإِذَا بَاعَ رَجُلٌ ابْنَتَهُ أَمَةً، لَا تَخْرُجُ كَمَا يَخْرُجُ الْعَبِيدُ.', 'خروج 21:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 8, 'إِنْ قَبُحَتْ فِي عَيْنَيْ سَيِّدِهَا الَّذِي خَطَبَهَا لِنَفْسِهِ، يَدَعُهَا تُفَكُّ. وَلَيْسَ لَهُ سُلْطَانٌ أَنْ يَبِيعَهَا لِقَوْمٍ أَجَانِبَ لِغَدْرِهِ بِهَا.', 'خروج 21:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 9, 'وَإِنْ خَطَبَهَا لِابْنِهِ فَبِحَسَبِ حَقِّ الْبَنَاتِ يَفْعَلُ لَهَا.', 'خروج 21:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 10, 'إِنِ اتَّخَذَ لِنَفْسِهِ أُخْرَى، لَا يُنَقِّصُ طَعَامَهَا وَكِسْوَتَهَا وَمُعَاشَرَتَهَا.', 'خروج 21:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 11, 'وَإِنْ لَمْ يَفْعَلْ لَهَا هَذِهِ الثَّلَاثَ تَخْرُجُ مَجَّانًا بِلَا ثَمَنٍ.', 'خروج 21:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 12, '«مَنْ ضَرَبَ إِنْسَانًا فَمَاتَ يُقْتَلُ قَتْلًا.', 'خروج 21:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 13, 'وَلَكِنَّ الَّذِي لَمْ يَتَعَمَّدْ، بَلْ أَوْقَعَ اللهُ فِي يَدِهِ، فَأَنَا أَجْعَلُ لَكَ مَكَانًا يَهْرُبُ إِلَيْهِ.', 'خروج 21:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 14, 'وَإِذَا بَغَى إِنْسَانٌ عَلَى صَاحِبِهِ لِيَقْتُلَهُ بِغَدْرٍ فَمِنْ عِنْدِ مَذْبَحِي تَأْخُذُهُ لِلْمَوْتِ.', 'خروج 21:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 15, 'وَمَنْ ضَرَبَ أَبَاهُ أَوْ أُمَّهُ يُقْتَلُ قَتْلًا.', 'خروج 21:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 16, 'وَمَنْ سَرَقَ إِنْسَانًا وَبَاعَهُ، أَوْ وُجِدَ فِي يَدِهِ، يُقْتَلُ قَتْلًا.', 'خروج 21:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 17, 'وَمَنْ شَتَمَ أَبَاهُ أَوْ أُمَّهُ يُقْتَلُ قَتْلًا.', 'خروج 21:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 18, 'وَإِذَا تَخَاصَمَ رَجُلَانِ فَضَرَبَ أَحَدُهُمَا الْآخَرَ بِحَجَرٍ أَوْ بِلَكْمَةٍ وَلَمْ يُقْتَلْ بَلْ سَقَطَ فِي الْفِرَاشِ،', 'خروج 21:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 19, 'فَإِنْ قَامَ وَتَمَشَّى خَارِجًا عَلَى عُكَّازِهِ يَكُونُ الضَّارِبُ بَرِيئًا. إِلَّا أَنَّهُ يُعَوِّضُ عُطْلَتَهُ، وَيُنْفِقُ عَلَى شِفَائِهِ.', 'خروج 21:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 20, 'وَإِذَا ضَرَبَ إِنْسَانٌ عَبْدَهُ أَوْ أَمَتَهُ بِالْعَصَا فَمَاتَ تَحْتَ يَدِهِ يُنْتَقَمُ مِنْهُ.', 'خروج 21:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 21, 'لَكِنْ إِنْ بَقِيَ يَوْمًا أَوْ يَوْمَيْنِ لَا يُنْتَقَمُ مِنْهُ لِأَنَّهُ مَالُهُ.', 'خروج 21:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 22, 'وَإِذَا تَخَاصَمَ رِجَالٌ وَصَدَمُوا امْرَأَةً حُبْلَى فَسَقَطَ وَلَدُهَا وَلَمْ تَحْصُلْ أَذِيَّةٌ، يُغَرَّمُ كَمَا يَضَعُ عَلَيْهِ زَوْجُ الْمَرْأَةِ، وَيَدْفَعُ عَنْ يَدِ الْقُضَاةِ.', 'خروج 21:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 23, 'وَإِنْ حَصَلَتْ أَذِيَّةٌ تُعْطِي نَفْسًا بِنَفْسٍ،', 'خروج 21:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 24, 'وَعَيْنًا بِعَيْنٍ، وَسِنًّا بِسِنٍّ، وَيَدًا بِيَدٍ، وَرِجْلًا بِرِجْلٍ،', 'خروج 21:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 25, 'وَكَيًّا بِكَيٍّ، وَجُرْحًا بِجُرْحٍ، وَرَضًّا بِرَضٍّ.', 'خروج 21:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 26, 'وَإِذَا ضَرَبَ إِنْسَانٌ عَيْنَ عَبْدِهِ، أَوْ عَيْنَ أَمَتِهِ فَأَتْلَفَهَا، يُطْلِقُهُ حُرًّا عِوَضًا عَنْ عَيْنِهِ.', 'خروج 21:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 27, 'وَإِنْ أَسْقَطَ سِنَّ عَبْدِهِ أَوْ سِنَّ أَمَتِهِ يُطْلِقُهُ حُرًّا عِوَضًا عَنْ سِنِّهِ.', 'خروج 21:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 28, '«وَإِذَا نَطَحَ ثَوْرٌ رَجُلًا أَوِ امْرَأَةً فَمَاتَ، يُرْجَمُ الثَّوْرُ وَلَا يُؤْكَلُ لَحْمُهُ. وَأَمَّا صَاحِبُ الثَّوْرِ فَيَكُونُ بَرِيئًا.', 'خروج 21:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 29, 'وَلَكِنْ إِنْ كَانَ ثَوْرًا نَطَّاحًا مِنْ قَبْلُ، وَقَدْ أُشْهِدَ عَلَى صَاحِبِهِ وَلَمْ يَضْبِطْهُ، فَقَتَلَ رَجُلًا أَوِ امْرَأَةً، فَالثَّوْرُ يُرْجَمُ وَصَاحِبُهُ أَيْضًا يُقْتَلُ.', 'خروج 21:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 30, 'إِنْ وُضِعَتْ عَلَيْهِ فِدْيَةٌ، يَدْفَعُ فِدَاءَ نَفْسِهِ كُلُّ مَا يُوضَعُ عَلَيْهِ.', 'خروج 21:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 31, 'أَوْ إِذَا نَطَحَ ابْنًا أَوْ نَطَحَ ابْنَةً فَبِحَسَبِ هَذَا الْحُكْمِ يُفْعَلُ بِهِ.', 'خروج 21:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 32, 'إِنْ نَطَحَ الثَّوْرُ عَبْدًا أَوْ أَمَةً، يُعْطِي سَيِّدَهُ ثَلَاثِينَ شَاقِلَ فِضَّةٍ، وَالثَّوْرُ يُرْجَمُ.', 'خروج 21:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 33, 'وَإِذَا فَتَحَ إِنْسَانٌ بِئْرًا، أَوْحَفَرَ إِنْسَانٌ بِئْرًا وَلَمْ يُغَطِّهِ، فَوَقَعَ فِيهِ ثَوْرٌ أَوْ حِمَارٌ،', 'خروج 21:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 34, 'فَصَاحِبُ الْبِئْرِ يُعَوِّضُ وَيَرُدُّ فِضَّةً لِصَاحِبِهِ، وَالْمَيْتُ يَكُونُ لَهُ.', 'خروج 21:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 35, 'وَإِذَا نَطَحَ ثَوْرُ إِنْسَانٍ ثَوْرَ صَاحِبِهِ فَمَاتَ، يَبِيعَانِ الثَّوْرَ الْحَيَّ وَيَقْتَسِمَانِ ثَمَنَهُ. وَالْمَيْتُ أَيْضًا يَقْتَسِمَانِهِ.', 'خروج 21:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 21, 36, 'لَكِنْ إِذَا عُلِمَ أَنَّهُ ثَوْرٌ نَطَّاحٌ مِنْ قَبْلُ وَلَمْ يَضْبِطْهُ صَاحِبُهُ، يُعَوِّضُ عَنِ الثَّوْرِ بِثَوْرٍ، وَالْمَيْتُ يَكُونُ لَهُ.', 'خروج 21:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 1, '«إِذَا سَرَقَ إِنْسَانٌ ثَوْرًا أَوْ شَاةً فَذَبَحَهُ أَوْ بَاعَهُ، يُعَوِّضُ عَنِ الثَّوْرِ بِخَمْسَةِ ثِيرَانٍ، وَعَنِ الشَّاةِ بِأَرْبَعَةٍ مِنَ الْغَنَمِ.', 'خروج 22:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 2, 'إِنْ وُجِدَ السَّارِقُ وَهُوَ يَنْقُبُ، فَضُرِبَ وَمَاتَ، فَلَيْسَ لَهُ دَمٌ.', 'خروج 22:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 3, 'وَلَكِنْ إِنْ أَشْرَقَتْ عَلَيْهِ الشَّمْسُ، فَلَهُ دَمٌ. إِنَّهُ يُعَوِّضُ. إِنْ لَمْ يَكُنْ لَهُ يُبَعْ بِسَرِقَتِهِ.', 'خروج 22:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 4, 'إِنْ وُجِدَتِ السَّرِقَةُ فِي يَدِهِ حَيَّةً، ثَوْرًا كَانَتْ أَمْ حِمَارًا أَمْ شَاةً، يُعَوِّضُ بِاثْنَيْنِ.', 'خروج 22:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 5, '«إِذَا رَعَى إِنْسَانٌ حَقْلًا أَوْ كَرْمًا وَسَرَّحَ مَوَاشِيَهُ فَرَعَتْ فِي حَقْلِ غَيْرِهِ، فَمِنْ أَجْوَدِ حَقْلِهِ، وَأَجْوَدِ كَرْمِهِ يُعَوِّضُ.', 'خروج 22:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 6, 'إِذَا خَرَجَتْ نَارٌ وَأَصَابَتْ شَوْكًا فَاحْتَرَقَتْ أَكْدَاسٌ أَوْ زَرْعٌ أَوْ حَقْلٌ، فَالَّذِي أَوْقَدَ الْوَقِيدَ يُعَوِّضُ.', 'خروج 22:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 7, 'إِذَا أَعْطَى إِنْسَانٌ صَاحِبَهُ فِضَّةً أَوْ أَمْتِعَةً لِلْحِفْظِ، فَسُرِقَتْ مِنْ بَيْتِ الْإِنْسَانِ، فَإِنْ وُجِدَ السَّارِقُ، يُعَوِّضُ بِاثْنَيْنِ.', 'خروج 22:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 8, 'وَإِنْ لَمْ يُوجَدِ السَّارِقُ يُقَدَّمُ صَاحِبُ الْبَيْتِ إِلَى اللهِ لِيَحْكُمَ هَلْ لَمْ يَمُدَّ يَدَهُ إِلَى مُلْكِ صَاحِبِهِ.', 'خروج 22:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 9, 'فِي كُلِّ دَعْوَى جِنَايَةٍ، مِنْ جِهَةِ ثَوْرٍ أَوْ حِمَارٍ أَوْ شَاةٍ أَوْ ثَوْبٍ أَوْ مَفْقُودٍ مَا، يُقَالُ׃ إِنَّ هَذَا هُوَ، تُقَدَّمُ إِلَى اللهِ دَعْوَاهُمَا. فَالَّذِي يَحْكُمُ اللهُ بِذَنْبِهِ، يُعَوِّضُ صَاحِبَهُ بِاثْنَيْنِ.', 'خروج 22:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 10, 'إِذَا أَعْطَى إِنْسَانٌ صَاحِبَهُ حِمَارًا أَوْ ثَوْرًا أَوْ شَاةً أَوْ بَهِيمَةً مَّا لِلْحِفْظِ، فَمَاتَ أَوِ انْكَسَرَ أَوْ نُهِبَ وَلَيْسَ نَاظِرٌ،', 'خروج 22:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 11, 'فَيَمِينُ الرَّبِّ تَكُونُ بَيْنَهُمَا، هَلْ لَمْ يَمُدَّ يَدَهُ إِلَى مُلْكِ صَاحِبِهِ. فَيَقْبَلُ صَاحِبُهُ. فَلَا يُعَوِّضُ.', 'خروج 22:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 12, 'وَإِنْ سُرِقَ مِنْ عِنْدِهِ يُعَوِّضُ صَاحِبَهُ.', 'خروج 22:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 13, 'إِنِ افْتُرِسَ يُحْضِرُهُ شَهَادَةً. لَا يُعَوِّضُ عَنِ الْمُفْتَرَسِ.', 'خروج 22:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 14, 'وَإِذَا اسْتَعَارَ إِنْسَانٌ مِنْ صَاحِبِهِ شَيْئًا فَانْكَسَرَ أَوْ مَاتَ، وَصَاحِبُهُ لَيْسَ مَعَهُ، يُعَوِّضُ.', 'خروج 22:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 15, 'وَإِنْ كَانَ صَاحِبُهُ مَعَهُ لَا يُعَوِّضُ. إِنْ كَانَ مُسْتَأْجَرًا أَتَى بِأُجْرَتِهِ.', 'خروج 22:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 16, '«وَإِذَا رَاوَدَ رَجُلٌ عَذْرَاءَ لَمْ تُخْطَبْ، فَاضْطَجَعَ مَعَهَا يَمْهُرُهَا لِنَفْسِهِ زَوْجَةً.', 'خروج 22:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 17, 'إِنْ أَبَى أَبُوهَا أَنْ يُعْطِيَهُ إِيَّاهَا، يَزِنُ لَهُ فِضَّةً كَمَهْرِ الْعَذَارَى.', 'خروج 22:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 18, 'لَا تَدَعْ سَاحِرَةً تَعِيشُ.', 'خروج 22:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 19, 'كُلُّ مَنِ اضْطَجَعَ مَعَ بَهِيمَةٍ يُقْتَلُ قَتْلًا.', 'خروج 22:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 20, 'مَنْ ذَبَحَ لِآلِهَةٍ غَيْرِ الرَّبِّ وَحْدَهُ، يُهْلَكُ.', 'خروج 22:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 21, '«وَلَا تَضْطَهِدِ الْغَرِيبَ وَلَا تُضَايِقْهُ، لِأَنَّكُمْ كُنْتُمْ غُرَبَاءَ فِي أَرْضِ مِصْرَ.', 'خروج 22:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 22, 'لَا تُسِيءْ إِلَى أَرْمَلَةٍ مَّا وَلَا يَتِيمٍ.', 'خروج 22:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 23, 'إِنْ أَسَأْتَ إِلَيْهِ فَإِنِّي إِنْ صَرَخَ إِلَيَّ أَسْمَعُ صُرَاخَهُ،', 'خروج 22:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 24, 'فَيَحْمَى غَضَبِي وَأَقْتُلُكُمْ بِالسَّيْفِ، فَتَصِيرُ نِسَاؤُكُمْ أَرَامِلَ، وَأَوْلَادُكُمْ يَتَامَى.', 'خروج 22:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 25, 'إِنْ أَقْرَضْتَ فِضَّةً لِشَعْبِي الْفَقِيرِ الَّذِي عِنْدَكَ فَلَا تَكُنْ لَهُ كَالْمُرَابِي. لَا تَضَعُوا عَلَيْهِ رِبًا.', 'خروج 22:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 26, 'إِنِ ارْتَهَنْتَ ثَوْبَ صَاحِبِكَ فَإِلَى غُرُوبِ الشَّمْسِ تَرُدُّهُ لَهُ،', 'خروج 22:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 27, 'لِأَنَّهُ وَحْدَهُ غِطَاؤُهُ، هُوَ ثَوْبُهُ لِجِلْدِهِ، فِي مَاذَا يَنَامُ؟ فَيَكُونُ إِذَا صَرَخَ إِلَيَّ أَنِّي أَسْمَعُ، لِأَنِّي رَؤُوفٌ.', 'خروج 22:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 28, '«لَا تَسُبَّ اللهَ، وَلَا تَلْعَنْ رَئِيسًا فِي شَعْبِكَ.', 'خروج 22:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 29, 'لَا تُؤَخِّرْ مِلْءَ بَيْدَرِكَ، وَقَطْرَ مِعْصَرَتِكَ، وَأَبْكَارَ بَنِيكَ تُعْطِينِي.', 'خروج 22:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 30, 'كَذَلِكَ تَفْعَلُ بِبَقَرِكَ وَغَنَمِكَ. سَبْعَةَ أَيَّامٍ يَكُونُ مَعَ أُمِّهِ، وَفِي الْيَوْمِ الثَّامِنِ تُعْطِينِي إِيَّاهُ.', 'خروج 22:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 22, 31, 'وَتَكُونُونَ لِي أُنَاسًا مُقَدَّسِينَ. وَلَحْمَ فَرِيسَةٍ فِي الصَّحْرَاءِ لَا تَأْكُلُوا. لِلْكِلَابِ تَطْرَحُونَهُ.', 'خروج 22:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 1, '«لَا تَقْبَلْ خَبَرًا كَاذِبًا، وَلَا تَضَعْ يَدَكَ مَعَ الْمُنَافِقِ لِتَكُونَ شَاهِدَ ظُلْمٍ.', 'خروج 23:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 2, 'لَا تَتْبَعِ الْكَثِيرِينَ إِلَى فِعْلِ الشَّرِّ، وَلَا تُجِبْ فِي دَعْوَى مَائِلًا وَرَاءَ الْكَثِيرِينَ لِلتَّحْرِيفِ.', 'خروج 23:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 3, 'وَلَا تُحَابِ مَعَ الْمِسْكِينِ فِي دَعْوَاهُ.', 'خروج 23:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 4, 'إِذَا صَادَفْتَ ثَوْرَ عَدُوِّكَ أَوْ حِمَارَهُ شَارِدًا، تَرُدُّهُ إِلَيْهِ.', 'خروج 23:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 5, 'إِذَا رَأَيْتَ حِمَارَ مُبْغِضِكَ وَاقِعًا تَحْتَ حِمْلِهِ وَعَدَلْتَ عَنْ حَلِّهِ، فَلَا بُدَّ أَنْ تَحُلَّ مَعَهُ.', 'خروج 23:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 6, 'لَا تُحَرِّفْ حَقَّ فَقِيرِكَ فِي دَعْوَاهُ.', 'خروج 23:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 7, 'اِبْتَعِدْ عَنْ كَلَامِ الْكَذِبِ، وَلَا تَقْتُلِ الْبَرِيءَ وَالْبَارَّ، لِأَنِّي لَا أُبَرِّرُ الْمُذْنِبَ.', 'خروج 23:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 8, 'وَلَا تَأْخُذْ رَشْوَةً، لِأَنَّ الرَّشْوَةَ تُعْمِي الْمُبْصِرِينَ، وَتُعَوِّجُ كَلَامَ الْأَبْرَارِ.', 'خروج 23:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 9, 'وَلَا تُضَايِقِ الْغَرِيبَ فَإِنَّكُمْ عَارِفُونَ نَفْسَ الْغَرِيبِ، لِأَنَّكُمْ كُنْتُمْ غُرَبَاءَ فِي أَرْضِ مِصْرَ.', 'خروج 23:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 10, '«وَسِتَّ سِنِينَ تَزْرَعُ أَرْضَكَ وَتَجْمَعُ غَلَّتَهَا،', 'خروج 23:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 11, 'وَأَمَّا فِي السَّابِعَةِ فَتُرِيحُهَا وَتَتْرُكُهَا لِيَأْكُلَ فُقَرَاءُ شَعْبِكَ. وَفَضْلَتُهُمْ تَأْكُلُهَا وُحُوشُ الْبَرِّيَّةِ. كَذَلِكَ تَفْعَلُ بِكَرْمِكَ وَزَيْتُونِكَ.', 'خروج 23:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 12, 'سِتَّةَ أَيَّامٍ تَعْمَلُ عَمَلَكَ. وَأَمَّا الْيَوْمُ السَّابِعُ فَفِيهِ تَسْتَرِيحُ، لِكَيْ يَسْتَرِيحَ ثَوْرُكَ وَحِمَارُكَ، وَيَتَنَفَّسَ ابْنُ أَمَتِكَ وَالْغَرِيبُ.', 'خروج 23:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 13, 'وَكُلُّ مَا قُلْتُ لَكُمُ احْتَفِظُوا بِهِ، وَلَا تَذْكُرُوا اسْمَ آلِهَةٍ أُخْرَى، وَلَا يُسْمَعْ مِنْ فَمِكَ.', 'خروج 23:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 14, '«ثَلَاثَ مَرَّاتٍ تُعَيِّدُ لِي فِي السَّنَةِ.', 'خروج 23:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 15, 'تَحْفَظُ عِيدَ الْفَطِيرِ. تَأْكُلُ فَطِيرًا سَبْعَةَ أَيَّامٍ كَمَا أَمَرْتُكَ فِي وَقْتِ شَهْرِ أَبِيبَ، لِأَنَّهُ فِيهِ خَرَجْتَ مِنْ مِصْرَ. وَلَا يَظْهَرُوا أَمَامِي فَارِغِينَ.', 'خروج 23:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 16, 'وَعِيدَ الْحَصَادِ أَبْكَارِ غَلَّاتِكَ الَّتِي تَزْرَعُ فِي الْحَقْلِ. وَعِيدَ الْجَمْعِ فِي نِهَايَةِ السَّنَةِ عِنْدَمَا تَجْمَعُ غَلَّاتِكَ مِنَ الْحَقْلِ.', 'خروج 23:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 17, 'ثَلَاثَ مَرَّاتٍ فِي السَّنَةِ يَظْهَرُ جَمِيعُ ذُكُورِكَ أَمَامَ السَّيِّدِ الرَّبِّ.', 'خروج 23:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 18, 'لَا تَذْبَحْ عَلَى خَمِيرٍ دَمَ ذَبِيحَتِي، وَلَا يَبِتْ شَحْمُ عِيدِي إِلَى الْغَدِ.', 'خروج 23:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 19, 'أَوَّلَ أَبْكَارِ أَرْضِكَ تُحْضِرُهُ إِلَى بَيْتِ الرَّبِّ إِلَهِكَ. لَا تَطْبُخْ جَدْيًا بِلَبَنِ أُمِّهِ.', 'خروج 23:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 20, '«هَا أَنَا مُرْسِلٌ مَلَاكًا أَمَامَ وَجْهِكَ لِيَحْفَظَكَ فِي الطَّرِيقِ، وَلِيَجِيءَ بِكَ إِلَى الْمَكَانِ الَّذِي أَعْدَدْتُهُ.', 'خروج 23:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 21, 'اِحْتَرِزْ مِنْهُ وَاسْمَعْ لِصَوْتِهِ وَلَا تَتَمَرَّدْ عَلَيْهِ، لِأَنَّهُ لَا يَصْفَحُ عَنْ ذُنُوبِكُمْ، لِأَنَّ اسْمِي فِيهِ.', 'خروج 23:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 22, 'وَلَكِنْ إِنْ سَمِعْتَ لِصَوْتِهِ وَفَعَلْتَ كُلَّ مَا أَتَكَلَّمُ بِهِ، أُعَادِي أَعْدَاءَكَ، وَأُضَايِقُ مُضَايِقِيكَ.', 'خروج 23:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 23, 'فَإِنَّ مَلَاكِي يَسِيرُ أَمَامَكَ وَيَجِيءُ بِكَ إِلَى الْأَمُورِيِّينَ وَالْحِثِّيِّينَ وَالْفِرِزِّيِّينَ وَالْكَنْعَانِيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ، فَأُبِيدُهُمْ.', 'خروج 23:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 24, 'لَا تَسْجُدْ لِآلِهَتِهِمْ، وَلَا تَعْبُدْهَا، وَلَا تَعْمَلْ كَأَعْمَالِهِمْ، بَلْ تُبِيدُهُمْ وَتَكْسِرُ أَنْصَابَهُمْ.', 'خروج 23:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 25, 'وَتَعْبُدُونَ الرَّبَّ إِلَهَكُمْ، فَيُبَارِكُ خُبْزَكَ وَمَاءَكَ، وَأُزِيلُ الْمَرَضَ مِنْ بَيْنِكُمْ.', 'خروج 23:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 26, 'لَا تَكُونُ مُسْقِطَةٌ وَلَا عَاقِرٌ فِي أَرْضِكَ، وَأُكَمِّلُ عَدَدَ أَيَّامِكَ.', 'خروج 23:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 27, 'أُرْسِلُ هَيْبَتِي أَمَامَكَ، وَأُزْعِجُ جَمِيعَ الشُّعُوبِ الَّذِينَ تَأْتِي عَلَيْهِمْ، وَأُعْطِيكَ جَمِيعَ أَعْدَائِكَ مُدْبِرِينَ.', 'خروج 23:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 28, 'وَأُرْسِلُ أَمَامَكَ الزَّنَابِيرَ. فَتَطْرُدُ الْحِوِّيِّينَ وَالْكَنْعَانِيِّينَ وَالْحِثِّيِّينَ مِنْ أَمَامِكَ.', 'خروج 23:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 29, 'لَا أَطْرُدُهُمْ مِنْ أَمَامِكَ فِي سَنَةٍ وَاحِدَةٍ، لِئَلَّا تَصِيرَ الْأَرْضُ خَرِبَةً، فَتَكْثُرَ عَلَيْكَ وُحُوشُ الْبَرِّيَّةِ.', 'خروج 23:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 30, 'قَلِيلًا قَلِيلًا أَطْرُدُهُمْ مِنْ أَمَامِكَ إِلَى أَنْ تُثْمِرَ وَتَمْلِكَ الْأَرْضَ.', 'خروج 23:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 31, 'وَأَجْعَلُ تُخُومَكَ مِنْ بَحْرِ سُوفٍ إِلَى بَحْرِ فِلِسْطِينَ، وَمِنَ الْبَرِّيَّةِ إِلَى النَّهْرِ. فَإِنِّي أَدْفَعُ إِلَى أَيْدِيكُمْ سُكَّانَ الْأَرْضِ، فَتَطْرُدُهُمْ مِنْ أَمَامِكَ.', 'خروج 23:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 32, 'لَا تَقْطَعْ مَعَهُمْ وَلَا مَعَ آلِهَتِهِمْ عَهْدًا.', 'خروج 23:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 23, 33, 'لَا يَسْكُنُوا فِي أَرْضِكَ لِئَلَّا يَجْعَلُوكَ تُخْطِئُ إِلَيَّ. إِذَا عَبَدْتَ آلِهَتَهُمْ فَإِنَّهُ يَكُونُ لَكَ فَخًّا».', 'خروج 23:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 1, 'وَقَالَ لِمُوسَى׃ «اصْعَدْ إِلَى الرَّبِّ أَنْتَ وَهَارُونُ وَنَادَابُ وَأَبِيهُو، وَسَبْعُونَ مِنْ شُيُوخِ إِسْرَائِيلَ، وَاسْجُدُوا مِنْ بَعِيدٍ.', 'خروج 24:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 2, 'وَيَقْتَرِبُ مُوسَى وَحْدَهُ إِلَى الرَّبِّ، وَهُمْ لَا يَقْتَرِبُونَ. وَأَمَّا الشَّعْبُ فَلَا يَصْعَدْ مَعَهُ».', 'خروج 24:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 3, 'فَجَاءَ مُوسَى وَحَدَّثَ الشَّعْبَ بِجَمِيعِ أَقْوَالِ الرَّبِّ وَجَمِيعِ الْأَحْكَامِ، فَأَجَابَ جَمِيعُ الشَّعْبِ بِصَوْتٍ وَاحِدٍ وَقَالُوا׃ «كُلُّ الْأَقْوَالِ الَّتِي تَكَلَّمَ بِهَا الرَّبُّ نَفْعَلُ».', 'خروج 24:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 4, 'فَكَتَبَ مُوسَى جَمِيعَ أَقْوَالِ الرَّبِّ. وَبَكَّرَ فِي الصَّبَاحِ وَبَنَى مَذْبَحًا فِي أَسْفَلِ الْجَبَلِ، وَاثْنَيْ عَشَرَ عَمُودًا لِأَسْبَاطِ إِسْرَائِيلَ الِاثْنَيْ عَشَرَ.', 'خروج 24:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 5, 'وَأَرْسَلَ فِتْيَانَ بَنِي إِسْرَائِيلَ، فَأَصْعَدُوا مُحْرَقَاتٍ، وَذَبَحُوا ذَبَائِحَ سَلَامَةٍ لِلرَّبِّ مِنَ الثِّيرَانِ.', 'خروج 24:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 6, 'فَأَخَذَ مُوسَى نِصْفَ الدَّمِ وَوَضَعَهُ فِي الطُّسُوسِ. وَنِصْفَ الدَّمِ رَشَّهُ عَلَى الْمَذْبَحِ.', 'خروج 24:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 7, 'وَأَخَذَ كِتَابَ الْعَهْدِ وَقَرَأَ فِي مَسَامِعِ الشَّعْبِ، فَقَالُوا׃ «كُلُّ مَا تَكَلَّمَ بِهِ الرَّبُّ نَفْعَلُ وَنَسْمَعُ لَهُ».', 'خروج 24:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 8, 'وَأَخَذَ مُوسَى الدَّمَ وَرَشَّ عَلَى الشَّعْبِ وَقَالَ׃ «هُوَذَا دَمُ الْعَهْدِ الَّذِي قَطَعَهُ الرَّبُّ مَعَكُمْ عَلَى جَمِيعِ هَذِهِ الْأَقْوَالِ».', 'خروج 24:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 9, 'ثُمَّ صَعِدَ مُوسَى وَهَارُونُ وَنَادَابُ وَأَبِيهُو وَسَبْعُونَ مِنْ شُيُوخِ إِسْرَائِيلَ،', 'خروج 24:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 10, 'وَرَأَوْا إِلَهَ إِسْرَائِيلَ، وَتَحْتَ رِجْلَيْهِ شِبْهُ صَنْعَةٍ مِنَ الْعَقِيقِ الْأَزْرَقِ الشَّفَّافِ، وَكَذَاتِ السَّمَاءِ فِي النَّقَاوَةِ.', 'خروج 24:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 11, 'وَلَكِنَّهُ لَمْ يَمُدَّ يَدَهُ إِلَى أَشْرَافِ بَنِي إِسْرَائِيلَ. فَرَأَوْا اللهَ وَأَكَلُوا وَشَرِبُوا.', 'خروج 24:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 12, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «اصْعَدْ إِلَيَّ إِلَى الْجَبَلِ، وَكُنْ هُنَاكَ، فَأُعْطِيَكَ لَوْحَيِ الْحِجَارَةِ وَالشَّرِيعَةِ وَالْوَصِيَّةِ الَّتِي كَتَبْتُهَا لِتَعْلِيمِهِمْ».', 'خروج 24:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 13, 'فَقَامَ مُوسَى وَيَشُوعُ خَادِمُهُ. وَصَعِدَ مُوسَى إِلَى جَبَلِ اللهِ.', 'خروج 24:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 14, 'وَأَمَّا الشُّيُوخُ فَقَالَ لَهُمُ׃ «اجْلِسُوا لَنَا هَهُنَا حَتَّى نَرْجِعَ إِلَيْكُمْ. وَهُوَذَا هَارُونُ وَحُورُ مَعَكُمْ. فَمَنْ كَانَ صَاحِبَ دَعْوَى فَلْيَتَقَدَّمْ إِلَيْهِمَا».', 'خروج 24:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 15, 'فَصَعِدَ مُوسَى إِلَى الْجَبَلِ، فَغَطَّى السَّحَابُ الْجَبَلَ،', 'خروج 24:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 16, 'وَحَلَّ مَجْدُ الرَّبِّ عَلَى جَبَلِ سِينَاءَ، وَغَطَّاهُ السَّحَابُ سِتَّةَ أَيَّامٍ. وَفِي الْيَوْمِ السَّابِعِ دُعِيَ مُوسَى مِنْ وَسَطِ السَّحَابِ.', 'خروج 24:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 17, 'وَكَانَ مَنْظَرُ مَجْدِ الرَّبِّ كَنَارٍ آكِلَةٍ عَلَى رَأْسِ الْجَبَلِ أَمَامَ عُيُونِ بَنِي إِسْرَائِيلَ.', 'خروج 24:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 24, 18, 'وَدَخَلَ مُوسَى فِي وَسَطِ السَّحَابِ وَصَعِدَ إِلَى الْجَبَلِ. وَكَانَ مُوسَى فِي الْجَبَلِ أَرْبَعِينَ نَهَارًا وَأَرْبَعِينَ لَيْلَةً.', 'خروج 24:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 25:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ أَنْ يَأْخُذُوا لِي تَقْدِمَةً. مِنْ كُلِّ مَنْ يَحِثُّهُ قَلْبُهُ تَأْخُذُونَ تَقْدِمَتِي.', 'خروج 25:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 3, 'وَهَذِهِ هِيَ التَّقْدِمَةُ الَّتِي تَأْخُذُونَهَا مِنْهُمْ׃ ذَهَبٌ وَفِضَّةٌ وَنُحَاسٌ،', 'خروج 25:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 4, 'وَأَسْمَانْجُونِيٌّ وَأُرْجُوَانٌ وَقِرْمِزٌ وَبُوصٌ وَشَعْرُ مِعْزَى،', 'خروج 25:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 5, 'وَجُلُودُ كِبَاشٍ مُحَمَّرَةٌ وَجُلُودُ تُخَسٍ وَخَشَبُ سَنْطٍ،', 'خروج 25:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 6, 'وَزَيْتٌ لِلْمَنَارَةِ وَأَطْيَابٌ لِدُهْنِ الْمَسْحَةِ وَلِلْبَخُورِ الْعَطِرِ،', 'خروج 25:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 7, 'وَحِجَارَةُ جَزْعٍ وَحِجَارَةُ تَرْصِيعٍ لِلرِّدَاءِ وَالصُّدْرَةِ.', 'خروج 25:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 8, 'فَيَصْنَعُونَ لِي مَقْدِسًا لِأَسْكُنَ فِي وَسَطِهِمْ.', 'خروج 25:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 9, 'بِحَسَبِ جَمِيعِ مَا أَنَا أُرِيكَ مِنْ مِثَالِ الْمَسْكَنِ، وَمِثَالِ جَمِيعِ آنِيَتِهِ هَكَذَا تَصْنَعُونَ.', 'خروج 25:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 10, '«فَيَصْنَعُونَ تَابُوتًا مِنْ خَشَبِ السَّنْطِ، طُولُهُ ذِرَاعَانِ وَنِصْفٌ، وَعَرْضُهُ ذِرَاعٌ وَنِصْفٌ، وَارْتِفَاعُهُ ذِرَاعٌ وَنِصْفٌ.', 'خروج 25:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 11, 'وَتُغَشِّيهِ بِذَهَبٍ نَقِيٍّ. مِنْ دَاخِلٍ وَمِنْ خَارِجٍ تُغَشِّيهِ، وَتَصْنَعُ عَلَيْهِ إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهِ.', 'خروج 25:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 12, 'وَتَسْبِكُ لَهُ أَرْبَعَ حَلَقَاتٍ مِنْ ذَهَبٍ، وَتَجْعَلُهَا عَلَى قَوَائِمِهِ الْأَرْبَعِ. عَلَى جَانِبِهِ الْوَاحِدِ حَلْقَتَانِ، وَعَلَى جَانِبِهِ الثَّانِي حَلْقَتَانِ.', 'خروج 25:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 13, 'وَتَصْنَعُ عَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَتُغَشِّيهِمَا بِذَهَبٍ.', 'خروج 25:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 14, 'وَتُدْخِلُ الْعَصَوَيْنِ فِي الْحَلَقَاتِ عَلَى جَانِبَيِ التَّابُوتِ لِيُحْمَلَ التَّابُوتُ بِهِمَا.', 'خروج 25:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 15, 'تَبْقَى الْعَصَوَانِ فِي حَلَقَاتِ التَّابُوتِ. لَا تُنْزَعَانِ مِنْهَا.', 'خروج 25:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 16, 'وَتَضَعُ فِي التَّابُوتِ الشَّهَادَةَ الَّتِي أُعْطِيكَ.', 'خروج 25:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 17, '«وَتَصْنَعُ غِطَاءً مِنْ ذَهَبٍ نَقِيٍّ طُولُهُ ذِرَاعَانِ وَنِصْفٌ، وَعَرْضُهُ ذِرَاعٌ وَنِصْفٌ،', 'خروج 25:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 18, 'وَتَصْنَعُ كَرُوبَيْنِ مِنْ ذَهَبٍ. صَنْعَةَ خِرَاطَةٍ تَصْنَعُهُمَا عَلَى طَرَفَيِ الْغِطَاءِ.', 'خروج 25:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 19, 'فَاصْنَعْ كَرُوبًا وَاحِدًا عَلَى الطَّرَفِ مِنْ هُنَا، وَكَرُوبًا آخَرَ عَلَى الطَّرَفِ مِنْ هُنَاكَ. مِنَ الْغِطَاءِ تَصْنَعُونَ الْكَرُوبَيْنِ عَلَى طَرَفَيْهِ.', 'خروج 25:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 20, 'وَيَكُونُ الْكَرُوبَانِ بَاسِطَيْنِ أَجْنِحَتَهُمَا إِلَى فَوْقُ، مُظَلِّلَيْنِ بِأَجْنِحَتِهِمَا عَلَى الْغِطَاءِ، وَوَجْهَاهُمَا كُلُّ وَاحِدٍ إِلَى الْآخَرِ. نَحْوَ الْغِطَاءِ يَكُونُ وَجْهَا الْكَرُوبَيْنِ.', 'خروج 25:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 21, 'وَتَجْعَلُ الْغِطَاءَ عَلَى التَّابُوتِ مِنْ فَوْقُ، وَفِي التَّابُوتِ تَضَعُ الشَّهَادَةَ الَّتِي أُعْطِيكَ.', 'خروج 25:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 22, 'وَأَنَا أَجْتَمِعُ بِكَ هُنَاكَ وَأَتَكَلَّمُ مَعَكَ، مِنْ عَلَى الْغِطَاءِ مِنْ بَيْنِ الْكَرُوبَيْنِ اللَّذَيْنِ عَلَى تَابُوتِ الشَّهَادَةِ، بِكُلِّ مَا أُوصِيكَ بِهِ إِلَى بَنِي إِسْرَائِيلَ.', 'خروج 25:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 23, '«وَتَصْنَعُ مَائِدَةً مِنْ خَشَبِ السَّنْطِ طُولُهَا ذِرَاعَانِ، وَعَرْضُهَا ذِرَاعٌ، وَارْتِفَاعُهَا ذِرَاعٌ وَنِصْفٌ.', 'خروج 25:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 24, 'وَتُغَشِّيهَا بِذَهَبٍ نَقِيٍّ، وَتَصْنَعُ لَهَا إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهَا.', 'خروج 25:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 25, 'وَتَصْنَعُ لَهَا حَاجِبًا عَلَى شِبْرٍ حَوَالَيْهَا، وَتَصْنَعُ لِحَاجِبِهَا إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهَا.', 'خروج 25:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 26, 'وَتَصْنَعُ لَهَا أَرْبَعَ حَلَقَاتٍ مِنْ ذَهَبٍ، وَتَجْعَلُ الْحَلَقَاتِ عَلَى الزَّوَايَا الْأَرْبَعِ الَّتِي لِقَوَائِمِهَا الْأَرْبَعِ.', 'خروج 25:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 27, 'عِنْدَ الْحَاجِبِ تَكُونُ الْحَلَقَاتُ بُيُوتًا لِعَصَوَيْنِ لِحَمْلِ الْمَائِدَةِ.', 'خروج 25:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 28, 'وَتَصْنَعُ الْعَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَتُغَشِّيهِمَا بِذَهَبٍ، فَتُحْمَلُ بِهِمَا الْمَائِدَةُ.', 'خروج 25:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 29, 'وَتَصْنَعُ صِحَافَهَا وَصُحُونَهَا وَكَأْسَاتِهَا وَجَامَاتِهَا الَّتِي يُسْكَبُ بِهَا. مِنْ ذَهَبٍ نَقِيٍّ تَصْنَعُهَا.', 'خروج 25:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 30, 'وَتَجْعَلُ عَلَى الْمَائِدَةِ خُبْزَ الْوُجُوهِ أَمَامِي دَائِمًا.', 'خروج 25:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 31, '«وَتَصْنَعُ مَنَارَةً مِنْ ذَهَبٍ نَقِيٍّ. عَمَلَ الْخِرَاطَةِ تُصْنَعُ الْمَنَارَةُ، قَاعِدَتُهَا وَسَاقُهَا. تَكُونُ كَأْسَاتُهَا وَعُجَرُهَا وَأَزْهَارُهَا مِنْهَا.', 'خروج 25:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 32, 'وَسِتُّ شُعَبٍ خَارِجَةٌ مِنْ جَانِبَيْهَا. مِنْ جَانِبِهَا الْوَاحِدِ ثَلَاثُ شُعَبِ مَنَارَةٍ، وَمِنْ جَانِبِهَا الثَّانِي ثَلَاثُ شُعَبِ مَنَارَةٍ.', 'خروج 25:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 33, 'فِي الشُّعْبَةِ الْوَاحِدَةِ ثَلَاثُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجْرَةٍ وَزَهْرٍ، وَفِي الشُّعْبَةِ الثَّانِيَةِ ثَلَاثُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجْرَةٍ وَزَهْرٍ، وَهَكَذَا إِلَى السِّتِّ الشُّعَبِ الْخَارِجَةِ مِنَ الْمَنَارَةِ.', 'خروج 25:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 34, 'وَفِي الْمَنَارَةِ أَرْبَعُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجَرِهَا وَأَزْهَارِهَا.', 'خروج 25:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 35, 'وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ، وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ، وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ إِلَى السِّتِّ الشُّعَبِ الْخَارِجَةِ مِنَ الْمَنَارَةِ.', 'خروج 25:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 36, 'تَكُونُ عُجَرُهَا وَشُعَبُهَا مِنْهَا. جَمِيعُهَا خِرَاطَةٌ وَاحِدَةٌ مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 25:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 37, 'وَتَصْنَعُ سُرُجَهَا سَبْعَةً، فَتُصْعَدُ سُرُجُهَا لِتُضِيءَ إِلَى مُقَابِلِهَا.', 'خروج 25:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 38, 'وَمَلَاقِطُهَا وَمَنَافِضُهَا مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 25:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 39, 'مِنْ وَزْنَةِ ذَهَبٍ نَقِيٍّ تُصْنَعُ مَعَ جَمِيعِ هَذِهِ الْأَوَانِي.', 'خروج 25:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 25, 40, 'وَانْظُرْ فَاصْنَعْهَا عَلَى مِثَالِهَا الَّذِي أُظْهِرَ لَكَ فِي الْجَبَلِ.', 'خروج 25:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 1, '«وَأَمَّا الْمَسْكَنُ فَتَصْنَعُهُ مِنْ عَشَرِ شُقَقِ بُوصٍ مَبْرُومٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ. بِكَرُوبِيمَ صَنْعَةَ حَائِكٍ حَاذِقٍ تَصْنَعُهَا.', 'خروج 26:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 2, 'طُولُ الشُّقَّةِ الْوَاحِدَةِ ثَمَانٍ وَعِشْرُونَ ذِرَاعًا، وَعَرْضُ الشُّقَّةِ الْوَاحِدَةِ أَرْبَعُ أَذْرُعٍ. قِيَاسًا وَاحِدًا لِجَمِيعِ الشُّقَقِ.', 'خروج 26:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 3, 'تَكُونُ خَمْسٌ مِنَ الشُّقَقِ بَعْضُهَا مَوْصُولٌ بِبَعْضٍ، وَخَمْسُ شُقَقٍ بَعْضُهَا مَوْصُولٌ بِبَعْضٍ.', 'خروج 26:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 4, 'وَتَصْنَعُ عُرًى مِنْ أَسْمَانْجُونِيٍّ عَلَى حَاشِيَةِ الشُّقَّةِ الْوَاحِدَةِ فِي الطَّرَفِ مِنَ الْمُوَصَّلِ الْوَاحِدِ. وَكَذَلِكَ تَصْنَعُ فِي حَاشِيَةِ الشُّقَّةِ الطَّرَفِيَّةِ مِنَ الْمُوَصَّلِ الثَّانِي.', 'خروج 26:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 5, 'خَمْسِينَ عُرْوَةً تَصْنَعُ فِي الشُّقَّةِ الْوَاحِدَةِ، وَخَمْسِينَ عُرْوَةً تَصْنَعُ فِي طَرَفِ الشُّقَّةِ الَّذِي فِي الْمُوَصَّلِ الثَّانِي. تَكُونُ الْعُرَى بَعْضُهَا مُقَابِلٌ لِبَعْضٍ.', 'خروج 26:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 6, 'وَتَصْنَعُ خَمْسِينَ شِظَاظًا مِنْ ذَهَبٍ، وَتَصِلُ الشُّقَّتَيْنِ بَعْضَهُمَا بِبَعْضٍ بِالْأَشِظَّةِ. فَيَصِيرُ الْمَسْكَنُ وَاحِدًا.', 'خروج 26:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 7, '«وَتَصْنَعُ شُقَقًا مِنْ شَعْرِ مِعْزَى خَيْمَةً عَلَى الْمَسْكَنِ. إِحْدَى عَشْرَةَ شُقَّةً تَصْنَعُهَا.', 'خروج 26:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 8, 'طُولُ الشُّقَّةِ الْوَاحِدَةِ ثَلَاثُونَ ذِرَاعًا، وَعَرْضُ الشُّقَّةِ الْوَاحِدَةِ أَرْبَعُ أَذْرُعٍ. قِيَاسًا وَاحِدًا لِلْإِحْدَى عَشْرَةَ شُقَّةً.', 'خروج 26:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 9, 'وَتَصِلُ خَمْسًا مِنَ الشُّقَقِ وَحْدَهَا، وَسِتًّا مِنَ الشُّقَقِ وَحْدَهَا. وَتَثْنِي الشُّقَّةَ السَّادِسَةَ فِي وَجْهِ الْخَيْمَةِ.', 'خروج 26:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 10, 'وَتَصْنَعُ خَمْسِينَ عُرْوَةً عَلَى حَاشِيَةِ الشُّقَّةِ الْوَاحِدَةِ الطَّرَفِيَّةِ مِنَ الْمُوَصَّلِ الْوَاحِدِ، وَخَمْسِينَ عُرْوَةً عَلَى حَاشِيَةِ الشُّقَّةِ مِنَ الْمُوَصَّلِ الثَّانِي.', 'خروج 26:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 11, 'وَتَصْنَعُ خَمْسِينَ شِظَاظًا مِنْ نُحَاسٍ، وَتُدْخِلُ الْأَشِظَّةَ فِي الْعُرَى، وَتَصِلُ الْخَيْمَةَ فَتَصِيرُ وَاحِدَةً.', 'خروج 26:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 12, 'وَأَمَّا الْمُدَلَّى الْفَاضِلُ مِنْ شُقَقِ الْخَيْمَةِ، نِصْفُ الشُّقَّةِ الْمُوَصَّلَةِ الْفَاضِلُ، فَيُدَلَّى عَلَى مُؤَخَّرِ الْمَسْكَنِ.', 'خروج 26:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 13, 'وَالذِّرَاعُ مِنْ هُنَا وَالذِّرَاعُ مِنْ هُنَاكَ، مِنَ الْفَاضِلِ فِي طُولِ شُقَقِ الْخَيْمَةِ، تَكُونَانِ مُدَلَّاتَيْنِ عَلَى جَانِبَيِ الْمَسْكَنِ مِنْ هُنَا وَمِنْ هُنَاكَ لِتَغْطِيَتِهِ.', 'خروج 26:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 14, 'وَتَصْنَعُ غِطَاءً لِلْخَيْمَةِ مِنْ جُلُودِ كِبَاشٍ مُحَمَّرَةٍ، وَغِطَاءً مِنْ جُلُودِ تُخَسٍ مِنْ فَوْقُ.', 'خروج 26:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 15, '«وَتَصْنَعُ الْأَلْوَاحَ لِلْمَسْكَنِ مِنْ خَشَبِ السَّنْطِ قَائِمَةً.', 'خروج 26:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 16, 'طُولُ اللَّوْحِ عَشَرُ أَذْرُعٍ، وَعَرْضُ اللَّوْحِ الْوَاحِدِ ذِرَاعٌ وَنِصْفٌ.', 'خروج 26:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 17, 'وَلِلَّوْحِ الْوَاحِدِ رِجْلَانِ مَقْرُونَةٌ إِحْدَاهُمَا بِالْأُخْرَى. هَكَذَا تَصْنَعُ لِجَمِيعِ أَلْوَاحِ الْمَسْكَنِ.', 'خروج 26:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 18, 'وَتَصْنَعُ الْأَلْوَاحَ لِلْمَسْكَنِ عِشْرِينَ لَوْحًا إِلَى جِهَةِ الْجَنُوبِ نَحْوَ التَّيْمَنِ.', 'خروج 26:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 19, 'وَتَصْنَعُ أَرْبَعِينَ قَاعِدَةً مِنْ فِضَّةٍ تَحْتَ الْعِشْرِينَ لَوْحًا. تَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ لِرِجْلَيْهِ، وَتَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ لِرِجْلَيْهِ.', 'خروج 26:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 20, 'وَلِجَانِبِ الْمَسْكَنِ الثَّانِي إِلَى جِهَةِ الشِّمَالِ عِشْرِينَ لَوْحًا.', 'خروج 26:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 21, 'وَأَرْبَعِينَ قَاعِدَةً لَهَا مِنْ فِضَّةٍ. تَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ، وَتَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ.', 'خروج 26:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 22, 'وَلِمُؤَخَّرِ الْمَسْكَنِ نَحْوَ الْغَرْبِ تَصْنَعُ سِتَّةَ أَلْوَاحٍ.', 'خروج 26:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 23, 'وَتَصْنَعُ لَوْحَيْنِ لِزَاوِيَتَيِ الْمَسْكَنِ فِي الْمُؤَخَّرِ،', 'خروج 26:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 24, 'وَيَكُونَانِ مُزْدَوِجَيْنِ مِنْ أَسْفَلُ. وَعَلَى سَوَاءٍ يَكُونَانِ مُزْدَوِجَيْنِ إِلَى رَأْسِهِ إِلَى الْحَلْقَةِ الْوَاحِدَةِ. هَكَذَا يَكُونُ لِكِلَيْهِمَا. يَكُونَانِ لِلزَّاوِيَتَيْنِ.', 'خروج 26:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 25, 'فَتَكُونُ ثَمَانِيَةَ أَلْوَاحٍ، وَقَوَاعِدُهَا مِنْ فِضَّةٍ سِتَّ عَشْرَةَ قَاعِدَةً. تَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ، وَتَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ.', 'خروج 26:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 26, '«وَتَصْنَعُ عَوَارِضَ مِنْ خَشَبِ السَّنْطِ، خَمْسًا لِأَلْوَاحِ جَانِبِ الْمَسْكَنِ الْوَاحِدِ،', 'خروج 26:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 27, 'وَخَمْسَ عَوَارِضَ لِأَلْوَاحِ جَانِبِ الْمَسْكَنِ الثَّانِي، وَخَمْسَ عَوَارِضَ لِأَلْوَاحِ جَانِبِ الْمَسْكَنِ فِي الْمُؤَخَّرِ نَحْوَ الْغَرْبِ.', 'خروج 26:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 28, 'وَالْعَارِضَةُ الْوُسْطَى فِي وَسَطِ الْأَلْوَاحِ تَنْفُذُ مِنَ الطَّرَفِ إِلَى الطَّرَفِ.', 'خروج 26:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 29, 'وَتُغَشِّي الْأَلْوَاحَ بِذَهَبٍ، وَتَصْنَعُ حَلَقَاتِهَا مِنْ ذَهَبٍ بُيُوتًا لِلْعَوَارِضِ، وَتُغَشِّي الْعَوَارِضَ بِذَهَبٍ.', 'خروج 26:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 30, 'وَتُقِيمُ الْمَسْكَنَ كَرَسْمِهِ الَّذِي أُظْهِرَ لَكَ فِي الْجَبَلِ.', 'خروج 26:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 31, '«وَتَصْنَعُ حِجَابًا مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ. صَنْعَةَ حَائِكٍ حَاذِقٍ يَصْنَعُهُ بِكَرُوبِيمَ.', 'خروج 26:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 32, 'وَتَجْعَلُهُ عَلَى أَرْبَعَةِ أَعْمِدَةٍ مِنْ سَنْطٍ مُغَشَّاةٍ بِذَهَبٍ. رُزَزُهَا مِنْ ذَهَبٍ. عَلَى أَرْبَعِ قَوَاعِدَ مِنْ فِضَّةٍ.', 'خروج 26:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 33, 'وَتَجْعَلُ الْحِجَابَ تَحْتَ الْأَشِظَّةِ. وَتُدْخِلُ إِلَى هُنَاكَ دَاخِلَ الْحِجَابِ تَابُوتَ الشَّهَادَةِ، فَيَفْصِلُ لَكُمُ الْحِجَابُ بَيْنَ الْقُدْسِ وَقُدْسِ الْأَقْدَاسِ.', 'خروج 26:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 34, 'وَتَجْعَلُ الْغِطَاءَ عَلَى تَابُوتِ الشَّهَادَةِ فِي قُدْسِ الْأَقْدَاسِ.', 'خروج 26:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 35, 'وَتَضَعُ الْمَائِدَةَ خَارِجَ الْحِجَابِ، وَالْمَنَارَةَ مُقَابِلَ الْمَائِدَةِ عَلَى جَانِبِ الْمَسْكَنِ نَحْوَ التَّيْمَنِ، وَتَجْعَلُ الْمَائِدَةَ عَلَى جَانِبِ الشِّمَالِ.', 'خروج 26:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 36, '«وَتَصْنَعُ سَجْفًا لِمَدْخَلِ الْخَيْمَةِ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ صَنْعَةَ الطَّرَّازِ.', 'خروج 26:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 26, 37, 'وَتَصْنَعُ لِلسَّجْفِ خَمْسَةَ أَعْمِدَةٍ مِنْ سَنْطٍ وَتُغَشِّيهَا بِذَهَبٍ. رُزَزُهَا مِنْ ذَهَبٍ، وَتَسْبِكُ لَهَا خَمْسَ قَوَاعِدَ مِنْ نُحَاسٍ.', 'خروج 26:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 1, '«وَتَصْنَعُ الْمَذْبَحَ مِنْ خَشَبِ السَّنْطِ، طُولُهُ خَمْسُ أَذْرُعٍ، وَعَرْضُهُ خَمْسُ أَذْرُعٍ. مُرَبَّعًا يَكُونُ الْمَذْبَحُ. وَارْتِفَاعُهُ ثَلَاثُ أَذْرُعٍ.', 'خروج 27:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 2, 'وَتَصْنَعُ قُرُونَهُ عَلَى زَوَايَاهُ الْأَرْبَعِ. مِنْهُ تَكُونُ قُرُونُهُ، وَتُغَشِّيهِ بِنُحَاسٍ.', 'خروج 27:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 3, 'وَتَصْنَعُ قُدُورَهُ لِرَفْعِ رَمَادِهِ، وَرُفُوشَهُ وَمَرَاكِنَهُ وَمَنَاشِلَهُ وَمَجَامِرَهُ. جَمِيعَ آنِيَتِهِ تَصْنَعُهَا مِنْ نُحَاسٍ.', 'خروج 27:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 4, 'وَتَصْنَعُ لَهُ شُبَّاكَةً صَنْعَةَ الشَّبَكَةِ مِنْ نُحَاسٍ، وَتَصْنَعُ عَلَى الشَّبَكَةِ أَرْبَعَ حَلَقَاتٍ مِنْ نُحَاسٍ عَلَى أَرْبَعَةِ أَطْرَافِهِ.', 'خروج 27:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 5, 'وَتَجْعَلُهَا تَحْتَ حَاجِبِ الْمَذْبَحِ مِنْ أَسْفَلُ، وَتَكُونُ الشَّبَكَةُ إِلَى نِصْفِ الْمَذْبَحِ.', 'خروج 27:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 6, 'وَتَصْنَعُ عَصَوَيْنِ لِلْمَذْبَحِ، عَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَتُغَشِّيهِمَا بِنُحَاسٍ.', 'خروج 27:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 7, 'وَتُدْخَلُ عَصَوَاهُ فِي الْحَلَقَاتِ، فَتَكُونُ الْعَصَوَانِ عَلَى جَانِبَيِ الْمَذْبَحِ حِينَمَا يُحْمَلُ.', 'خروج 27:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 8, 'مُجَوَّفًا تَصْنَعُهُ مِنْ أَلْوَاحٍ، كَمَا أُظْهِرَ لَكَ فِي الْجَبَلِ هَكَذَا يَصْنَعُونَهُ.', 'خروج 27:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 9, '«وَتَصْنَعُ دَارَ الْمَسْكَنِ. إِلَى جِهَةِ الْجَنُوبِ نَحْوَ التَّيْمَنِ لِلدَّارِ أَسْتَارٌ مِنْ بُوصٍ مَبْرُومٍ مِئَةُ ذِرَاعٍ طُولًا إِلَى الْجِهَةِ الْوَاحِدَةِ.', 'خروج 27:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 10, 'وَأَعْمِدَتُهَا عِشْرُونَ، وَقَوَاعِدُهَا عِشْرُونَ مِنْ نُحَاسٍ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ.', 'خروج 27:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 11, 'وَكَذَلِكَ إِلَى جِهَةِ الشِّمَالِ فِي الطُّولِ أَسْتَارٌ مِئَةُ ذِرَاعٍ طُولًا. وَأَعْمِدَتُهَا عِشْرُونَ، وَقَوَاعِدُهَا عِشْرُونَ مِنْ نُحَاسٍ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ.', 'خروج 27:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 12, 'وَفِي عَرْضِ الدَّارِ إِلَى جِهَةِ الْغَرْبِ أَسْتَارٌ خَمْسُونَ ذِرَاعًا. أَعْمِدَتُهَا عَشْرَةٌ، وَقَوَاعِدُهَا عَشْرٌ.', 'خروج 27:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 13, 'وَعَرْضُ الدَّارِ إِلَى جِهَةِ الشَّرْقِ نَحْوَ الشُّرُوقِ خَمْسُونَ ذِرَاعًا.', 'خروج 27:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 14, 'وَخَمْسَ عَشْرَةَ ذِرَاعًا مِنَ الْأَسْتَارِ لِلْجَانِبِ الْوَاحِدِ. أَعْمِدَتُهَا ثَلَاثَةٌ وَقَوَاعِدُهَا ثَلَاثٌ.', 'خروج 27:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 15, 'وَلِلْجَانِبِ الثَّانِي خَمْسَ عَشْرَةَ ذِرَاعًا مِنَ الْأَسْتَارِ. أَعْمِدَتُهَا ثَلَاثَةٌ وَقَوَاعِدُهَا ثَلَاثٌ.', 'خروج 27:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 16, 'وَلِبَابِ الدَّارِ سَجْفٌ عِشْرُونَ ذِرَاعًا مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ صَنْعَةَ الطَّرَّازِ. أَعْمِدَتُهُ أَرْبَعَةٌ، وَقَوَاعِدُهَا أَرْبَعٌ.', 'خروج 27:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 17, 'لِكُلِّ أَعْمِدَةِ الدَّارِ حَوَالَيْهَا قُضْبَانٌ مِنْ فِضَّةٍ. رُزَزُهَا مِنْ فِضَّةٍ، وَقَوَاعِدُهَا مِنْ نُحَاسٍ.', 'خروج 27:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 18, 'طُولُ الدَّارِ مِئَةُ ذِرَاعٍ، وَعَرْضُهَا خَمْسُونَ فَخَمْسُونَ، وَارْتِفَاعُهَا خَمْسُ أَذْرُعٍ مِنْ بُوصٍ مَبْرُومٍ، وَقَوَاعِدُهَا مِنْ نُحَاسٍ.', 'خروج 27:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 19, 'جَمِيعُ أَوَانِي الْمَسْكَنِ فِي كُلِّ خِدْمَتِهِ وَجَمِيعُ أَوْتَادِهِ وَجَمِيعُ أَوْتَادِ الدَّارِ مِنْ نُحَاسٍ.', 'خروج 27:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 20, '«وَأَنْتَ تَأْمُرُ بَنِي إِسْرَائِيلَ أَنْ يُقَدِّمُوا إِلَيْكَ زَيْتَ زَيْتُونٍ مَرْضُوضٍ نَقِيًّا لِلضَّوْءِ لِإِصْعَادِ السُّرُجِ دَائِمًا.', 'خروج 27:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 27, 21, 'فِي خَيْمَةِ الِاجْتِمَاعِ، خَارِجَ الْحِجَابِ الَّذِي أَمَامَ الشَّهَادَةِ، يُرَتِّبُهَا هَارُونُ وَبَنُوهُ مِنَ الْمَسَاءِ إِلَى الصَّبَاحِ أَمَامَ الرَّبِّ. فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِهِمْ مِنْ بَنِي إِسْرَائِيلَ.', 'خروج 27:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 1, '«وَقَرِّبْ إِلَيْكَ هَارُونَ أَخَاكَ وَبَنِيهِ مَعَهُ مِنْ بَيْنِ بَنِي إِسْرَائِيلَ لِيَكْهَنَ لِي. هَارُونَ نَادَابَ وَأَبِيهُوَ أَلِعَازَارَ وَإِيثَامَارَ بَنِي هَارُونَ.', 'خروج 28:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 2, 'وَاصْنَعْ ثِيَابًا مُقَدَّسَةً لِهَارُونَ أَخِيكَ لِلْمَجْدِ وَالْبَهَاءِ.', 'خروج 28:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 3, 'وَتُكَلِّمُ جَمِيعَ حُكَمَاءِ الْقُلُوبِ الَّذِينَ مَلَأْتُهُمْ رُوحَ حِكْمَةٍ، أَنْ يَصْنَعُوا ثِيَابَ هَارُونَ لِتَقْدِيسِهِ لِيَكْهَنَ لِي.', 'خروج 28:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 4, 'وَهَذِهِ هِيَ الثِّيَابُ الَّتِي يَصْنَعُونَهَا׃ صُدْرَةٌ وَرِدَاءٌ وَجُبَّةٌ وَقَمِيصٌ مُخَرَّمٌ وَعِمَامَةٌ وَمِنْطَقَةٌ. فَيَصْنَعُونَ ثِيَابًا مُقَدَّسَةً لِهَارُونَ أَخِيكَ وَلِبَنِيهِ لِيَكْهَنَ لِي.', 'خروج 28:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 5, 'وَهُمْ يَأْخُذُونَ الذَّهَبَ وَالْأَسْمَانْجُونِيَّ وَالْأُرْجُوَانَ وَالْقِرْمِزَ وَالْبُوصَ.', 'خروج 28:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 6, '«فَيَصْنَعُونَ الرِّدَاءَ مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ صَنْعَةَ حَائِكٍ حَاذِقٍ.', 'خروج 28:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 7, 'يَكُونُ لَهُ كَتِفَانِ مَوْصُولَانِ فِي طَرَفَيْهِ لِيَتَّصِلَ.', 'خروج 28:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 8, 'وَزُنَّارُ شَدِّهِ الَّذِي عَلَيْهِ يَكُونُ مِنْهُ كَصَنْعَتِهِ. مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ.', 'خروج 28:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 9, 'وَتَأْخُذُ حَجَرَيْ جَزْعٍ وَتُنَقِّشُ عَلَيْهِمَا أَسْمَاءَ بَنِي إِسْرَائِيلَ.', 'خروج 28:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 10, 'سِتَّةً مِنْ أَسْمَائِهِمْ عَلَى الْحَجَرِ الْوَاحِدِ، وَأَسْمَاءَ السِّتَّةِ الْبَاقِينَ عَلَى الْحَجَرِ الثَّانِي حَسَبَ مَوَالِيدِهِمْ.', 'خروج 28:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 11, 'صَنْعَةَ نَقَّاشِ الْحِجَارَةِ نَقْشَ الْخَاتِمِ تُنَقِّشُ الْحَجَرَيْنِ عَلَى حَسَبِ أَسْمَاءِ بَنِي إِسْرَائِيلَ. مُحَاطَيْنِ بِطَوْقَيْنِ مِنْ ذَهَبٍ تَصْنَعُهُمَا.', 'خروج 28:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 12, 'وَتَضَعُ الْحَجَرَيْنِ عَلَى كَتِفَيِ الرِّدَاءِ حَجَرَيْ تَذْكَارٍ لِبَنِي إِسْرَائِيلَ. فَيَحْمِلُ هَارُونُ أَسْمَاءَهُمْ أَمَامَ الرَّبِّ عَلَى كَتِفَيْهِ لِلتَّذْكَارِ.', 'خروج 28:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 13, 'وَتَصْنَعُ طَوْقَيْنِ مِنْ ذَهَبٍ،', 'خروج 28:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 14, 'وَسِلْسِلَتَيْنِ مِنْ ذَهَبٍ نَقِيٍّ. مَجْدُولَتَيْنِ تَصْنَعُهُمَا صَنْعَةَ الضَّفْرِ، وَتَجْعَلُ سِلْسِلَتَيِ الضَّفَائِرِ فِي الطَّوْقَيْنِ.', 'خروج 28:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 15, '«وَتَصْنَعُ صُدْرَةَ قَضَاءٍ. صَنْعَةَ حَائِكٍ حَاذِقٍ كَصَنْعَةِ الرِّدَاءِ تَصْنَعُهَا. مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ تَصْنَعُهَا.', 'خروج 28:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 16, 'تَكُونُ مُرَبَّعَةً مَثْنِيَّةً، طُولُهَا شِبْرٌ وَعَرْضُهَا شِبْرٌ.', 'خروج 28:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 17, 'وَتُرَصِّعُ فِيهَا تَرْصِيعَ حَجَرٍ أَرْبَعَةَ صُفُوفِ حِجَارَةٍ. صَفُّ׃ عَقِيقٍ أَحْمَرَ وَيَاقُوتٍ أَصْفَرَ وَزُمُرُّدٍ، الصَّفُّ الْأَوَّلُ.', 'خروج 28:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 18, 'وَالصَّفُّ الثَّانِي׃ بَهْرَمَانٌ وَيَاقُوتٌ أَزْرَقُ وَعَقِيقٌ أَبْيَضُ.', 'خروج 28:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 19, 'وَالصَّفُّ الثَّالِثُ׃ عَيْنُ الْهِرِّ وَيَشْمٌ وَجَمَشْتٌ.', 'خروج 28:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 20, 'وَالصَّفُّ الرَّابِعُ׃ زَبَرْجَدٌ وَجَزْعٌ وَيَشْبٌ. تَكُونُ مُطَوَّقَةً بِذَهَبٍ فِي تَرْصِيعِهَا.', 'خروج 28:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 21, 'وَتَكُونُ الْحِجَارَةُ عَلَى أَسْمَاءِ بَنِي إِسْرَائِيلَ، اثْنَيْ عَشَرَ عَلَى أَسْمَائِهِمْ. كَنَقْشِ الْخَاتِمِ كُلُّ وَاحِدٍ عَلَى اسْمِهِ تَكُونُ لِلِاثْنَيْ عَشَرَ سِبْطًا.', 'خروج 28:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 22, '«وَتَصْنَعُ عَلَى الصُّدْرَةِ سَلَاسِلَ مَجْدُولَةً صَنْعَةَ الضَّفْرِ مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 28:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 23, 'وَتَصْنَعُ عَلَى الصُّدْرَةِ حَلْقَتَيْنِ مِنْ ذَهَبٍ، وَتَجْعَلُ الْحَلْقَتَيْنِ عَلَى طَرَفَيِ الصُّدْرَةِ.', 'خروج 28:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 24, 'وَتَجْعَلُ ضَفِيرَتَيِ الذَّهَبِ فِي الْحَلْقَتَيْنِ عَلَى طَرَفَيِ الصُّدْرَةِ.', 'خروج 28:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 25, 'وَتَجْعَلُ طَرَفَيِ الضَّفِيرَتَيْنِ الْآخَرَيْنِ فِي الطَّوْقَيْنِ، وَتَجْعَلُهُمَا عَلَى كَتِفَيِ الرِّدَاءِ إِلَى قُدَّامِهِ.', 'خروج 28:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 26, 'وَتَصْنَعُ حَلْقَتَيْنِ مِنْ ذَهَبٍ وَتَضَعُهُمَا عَلَى طَرَفَيِ الصُّدْرَةِ عَلَى حَاشِيَتِهَا الَّتِي إِلَى جِهَةِ الرِّدَاءِ مِنْ دَاخِلٍ.', 'خروج 28:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 27, 'وَتَصْنَعُ حَلْقَتَيْنِ مِنْ ذَهَبٍ، وَتَجْعَلُهُمَا عَلَى كَتِفَيِ الرِّدَاءِ مِنْ أَسْفَلُ مِنْ قُدَّامِهِ عِنْدَ وَصْلِهِ مِنْ فَوْقِ زُنَّارِ الرِّدَاءِ.', 'خروج 28:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 28, 'وَيَرْبُطُونَ الصُّدْرَةَ بِحَلْقَتَيْهَا إِلَى حَلْقَتَيِ الرِّدَاءِ بِخَيْطٍ مِنْ أَسْمَانْجُونِيٍّ لِتَكُونَ عَلَى زُنَّارِ الرِّدَاءِ، وَلَا تُنْزَعُ الصُّدْرَةُ عَنِ الرِّدَاءِ.', 'خروج 28:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 29, 'فَيَحْمِلُ هَارُونُ أَسْمَاءَ بَنِي إِسْرَائِيلَ فِي صُدْرَةِ الْقَضَاءِ عَلَى قَلْبِهِ عِنْدَ دُخُولِهِ إِلَى الْقُدْسِ لِلتَّذْكَارِ أَمَامَ الرَّبِّ دَائِمًا.', 'خروج 28:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 30, 'وَتَجْعَلُ فِي صُدْرَةِ الْقَضَاءِ الْأُورِيمَ وَالتُّمِّيمَ لِتَكُونَ عَلَى قَلْبِ هَارُونَ عِنْدَ دُخُولِهِ أَمَامَ الرَّبِّ. فَيَحْمِلُ هَارُونُ قَضَاءَ بَنِي إِسْرَائِيلَ عَلَى قَلْبِهِ أَمَامَ الرَّبِّ دَائِمًا.', 'خروج 28:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 31, '«وَتَصْنَعُ جُبَّةَ الرِّدَاءِ كُلَّهَا مِنْ أَسْمَانْجُونِيٍّ،', 'خروج 28:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 32, 'وَتَكُونُ فَتْحَةُ رَأْسِهَا فِي وَسَطِهَا، وَيَكُونُ لِفَتْحَتِهَا حَاشِيَةٌ حَوَالَيْهَا صَنْعَةَ الْحَائِكِ. كَفَتْحَةِ الدِّرْعِ يَكُونُ لَهَا. لَا تُشَقُّ.', 'خروج 28:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 33, 'وَتَصْنَعُ عَلَى أَذْيَالِهَا رُمَّانَاتٍ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوانٍ وَقِرْمِزٍ، عَلَى أَذْيَالِهَا حَوَالَيْهَا، وَجَلَاجِلَ مِنْ ذَهَبٍ بَيْنَهَا حَوَالَيْهَا.', 'خروج 28:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 34, 'جُلْجُلَ ذَهَبٍ وَرُمَّانَةً، جُلْجُلَ ذَهَبٍ وَرُمَّانَةً، عَلَى أَذْيَالِ الْجُبَّةِ حَوَالَيْهَا.', 'خروج 28:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 35, 'فَتَكُونُ عَلَى هَارُونَ لِلْخِدْمَةِ لِيُسْمَعَ صَوْتُهَا عِنْدَ دُخُولِهِ إِلَى الْقُدْسِ أَمَامَ الرَّبِّ، وَعِنْدَ خُرُوجِهِ، لِئَلَّا يَمُوتَ.', 'خروج 28:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 36, '«وَتَصْنَعُ صَفِيحَةً مِنْ ذَهَبٍ نَقِيٍّ، وَتُنَقِّشُ عَلَيْهَا نَقْشَ خَاتِمٍ׃ «قُدْسٌ لِلرَّبِّ».', 'خروج 28:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 37, 'وَتَضَعُهَا عَلَى خَيْطٍ أَسْمَانْجُونِيٍّ لِتَكُونَ عَلَى الْعِمَامَةِ. إِلَى قُدَّامِ الْعِمَامَةِ تَكُونُ.', 'خروج 28:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 38, 'فَتَكُونُ عَلَى جِبْهَةِ هَارُونَ، فَيَحْمِلُ هَارُونُ إِثْمَ الْأَقْدَاسِ الَّتِي يُقَدِّسُهَا بَنُو إِسْرَائِيلَ، جَمِيعِ عَطَايَا أَقْدَاسِهِمْ. وَتَكُونُ عَلَى جِبْهَتِهِ دَائِمًا لِلرِّضَا عَنْهُمْ أَمَامَ الرَّبِّ.', 'خروج 28:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 39, 'وَتُخَرِّمُ الْقَمِيصَ مِنْ بُوصٍ، وَتَصْنَعُ الْعِمَامَةَ مِنْ بُوصٍ، وَالْمِنْطَقَةُ تَصْنَعُهَا صَنْعَةَ الطَّرَّازِ.', 'خروج 28:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 40, '«وَلِبَنِي هَارُونَ تَصْنَعُ أَقْمِصَةً، وَتَصْنَعُ لَهُمْ مَنَاطِقَ، وَتَصْنَعُ لَهُمْ قَلَانِسَ لِلْمَجْدِ وَالْبَهَاءِ.', 'خروج 28:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 41, 'وَتُلْبِسُ هَارُونَ أَخَاكَ إِيَّاهَا وَبَنِيهِ مَعَهُ، وَتَمْسَحُهُمْ، وَتَمْلَأُ أَيَادِيهِمْ، وَتُقَدِّسُهُمْ لِيَكْهَنُوا لِي.', 'خروج 28:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 42, 'وَتَصْنَعُ لَهُمْ سَرَاوِيلَ مِنْ كَتَّانٍ لِسَتْرِ الْعَوْرَةِ. مِنَ الْحَقَوَيْنِ إِلَى الْفَخْذَيْنِ تَكُونُ.', 'خروج 28:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 28, 43, 'فَتَكُونُ عَلَى هَارُونَ وَبَنِيهِ عِنْدَ دُخُولِهِمْ إِلَى خَيْمَةِ الِاجْتِمَاعِ، أَوْ عِنْدَ اقْتِرَابِهِمْ إِلَى الْمَذْبَحِ لِلْخِدْمَةِ فِي الْقُدْسِ، لِئَلَّا يَحْمِلُوا إِثْمًا وَيَمُوتُوا. فَرِيضَةً أَبَدِيَّةً لَهُ وَلِنَسْلِهِ مِنْ بَعْدِهِ.', 'خروج 28:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 1, '«وَهَذَا مَا تَصْنَعُهُ لَهُمْ لِتَقْدِيسِهِمْ لِيَكْهَنُوا لِي׃ خُذْ ثَوْرًا وَاحِدًا ابْنَ بَقَرٍ، وَكَبْشَيْنِ صَحِيحَيْنِ،', 'خروج 29:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 2, 'وَخُبْزَ فَطِيرٍ، وَأَقْرَاصَ فَطِيرٍ مَلْتُوتَةً بِزَيْتٍ، وَرُقَاقَ فَطِيرٍ مَدْهُونَةً بِزَيْتٍ. مِنْ دَقِيقِ حِنْطَةٍ تَصْنَعُهَا.', 'خروج 29:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 3, 'وَتَجْعَلُهَا فِي سَلَّةٍ وَاحِدَةٍ، وَتُقَدِّمُهَا فِي السَّلَّةِ مَعَ الثَّوْرِ وَالْكَبْشَيْنِ.', 'خروج 29:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 4, '«وَتُقَدِّمُ هَارُونَ وَبَنِيهِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ وَتَغْسِلُهُمْ بِمَاءٍ.', 'خروج 29:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 5, 'وَتَأْخُذُ الثِّيَابَ وَتُلْبِسُ هَارُونَ الْقَمِيصَ وَجُبَّةَ الرِّدَاءِ وَالرِّدَاءَ وَالصُّدْرَةَ، وَتَشُدُّهُ بِزُنَّارِ الرِّدَاءِ،', 'خروج 29:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 6, 'وَتَضَعُ الْعِمَامَةَ عَلَى رَأْسِهِ، وَتَجْعَلُ الْإِكْلِيلَ الْمُقَدَّسَ عَلَى الْعِمَامَةِ،', 'خروج 29:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 7, 'وَتَأْخُذُ دُهْنَ الْمَسْحَةِ وَتَسْكُبُهُ عَلَى رَأْسِهِ وَتَمْسَحُهُ.', 'خروج 29:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 8, 'وَتُقَدِّمُ بَنِيهِ وَتُلْبِسُهُمْ أَقْمِصَةً.', 'خروج 29:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 9, 'وَتُنَطِّقُهُمْ بِمَنَاطِقَ، هَارُونَ وَبَنِيهِ، وَتَشُدُّ لَهُمْ قَلَانِسَ. فَيَكُونُ لَهُمْ كَهَنُوتٌ فَرِيضَةً أَبَدِيَّةً. وَتَمْلَأُ يَدَ هَارُونَ وَأَيْدِيَ بَنِيهِ.', 'خروج 29:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 10, '«وَتُقَدِّمُ الثَّوْرَ إِلَى قُدَّامِ خَيْمَةِ الِاجْتِمَاعِ، فَيَضَعُ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ الثَّوْرِ.', 'خروج 29:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 11, 'فَتَذْبَحُ الثَّوْرَ أَمَامَ الرَّبِّ عِنْدَ بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'خروج 29:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 12, 'وَتَأْخُذُ مِنْ دَمِ الثَّوْرِ وَتَجْعَلُهُ عَلَى قُرُونِ الْمَذْبَحِ بِإِصْبِعِكَ، وَسَائِرَ الدَّمِ تَصُبُّهُ إِلَى أَسْفَلِ الْمَذْبَحِ.', 'خروج 29:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 13, 'وَتَأْخُذُ كُلَّ الشَّحْمِ الَّذِي يُغَشِّي الْجَوْفَ، وَزِيَادَةَ الْكَبِدِ وَالْكُلْيَتَيْنِ وَالشَّحْمَ الَّذِي عَلَيْهِمَا، وَتُوقِدُهَا عَلَى الْمَذْبَحِ.', 'خروج 29:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 14, 'وَأَمَّا لَحْمُ الثَّوْرِ وَجِلْدُهُ وَفَرْثُهُ فَتَحْرِقُهَا بِنَارٍ خَارِجَ الْمَحَلَّةِ. هُوَ ذَبِيحَةُ خَطِيَّةٍ.', 'خروج 29:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 15, '«وَتَأْخُذُ الْكَبْشَ الْوَاحِدَ، فَيَضَعُ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ الْكَبْشِ.', 'خروج 29:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 16, 'فَتَذْبَحُ الْكَبْشَ وَتَأْخُذُ دَمَهُ وَتَرُشُّهُ عَلَى الْمَذْبَحِ مِنْ كُلِّ نَاحِيَةٍ.', 'خروج 29:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 17, 'وَتَقْطَعُ الْكَبْشَ إِلَى قِطَعِهِ، وَتَغْسِلُ جَوْفَهُ وَأَكَارِعَهُ وَتَجْعَلُهَا عَلَى قِطَعِهِ وَعَلَى رَأْسِهِ،', 'خروج 29:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 18, 'وَتُوقِدُ كُلَّ الْكَبْشِ عَلَى الْمَذْبَحِ. هُوَ مُحْرَقَةٌ لِلرَّبِّ. رَائِحَةُ سَرُورٍ، وَقُودٌ هُوَ لِلرَّبِّ.', 'خروج 29:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 19, '«وَتَأْخُذُ الْكَبْشَ الثَّانِي، فَيَضَعُ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ الْكَبْشِ.', 'خروج 29:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 20, 'فَتَذْبَحُ الْكَبْشَ وَتَأْخُذُ مِنْ دَمِهِ وَتَجْعَلُ عَلَى شَحْمَةِ أُذُنِ هَارُونَ، وَعَلَى شَحْمِ آذَانِ بَنِيهِ الْيُمْنَى، وَعَلَى أَبَاهِمِ أَيْدِيهِمِ الْيُمْنَى، وَعَلَى أَبَاهِمِ أَرْجُلِهِمِ الْيُمْنَى. وَتَرُشُّ الدَّمَ عَلَى الْمَذْبَحِ مِنْ كُلِّ نَاحِيَةٍ.', 'خروج 29:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 21, 'وَتَأْخُذُ مِنَ الدَّمِ الَّذِي عَلَى الْمَذْبَحِ وَمِنْ دُهْنِ الْمَسْحَةِ، وَتَنْضِحُ عَلَى هَارُونَ وَثِيَابِهِ، وَعَلَى بَنِيهِ وَثِيَابِ بَنِيهِ مَعَهُ، فَيَتَقَدَّسُ هُوَ وَثِيَابُهُ وَبَنُوهُ وَثِيَابُ بَنِيهِ مَعَهُ.', 'خروج 29:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 22, 'ثُمَّ تَأْخُذُ مِنَ الْكَبْشِ׃ الشَّحْمَ وَالْإِلْيَةَ وَالشَّحْمَ الَّذِي يُغَشِّي الْجَوْفَ، وَزِيَادَةَ الْكَبِدِ وَالْكُلْيَتَيْنِ، وَالشَّحْمَ الَّذِي عَلَيْهِمَا، وَالسَّاقَ الْيُمْنَى. فَإِنَّهُ كَبْشُ مِلْءٍ.', 'خروج 29:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 23, 'وَرَغِيفًا وَاحِدًا مِنَ الْخُبْزِ، وَقُرْصًا وَاحِدًا مِنَ الْخُبْزِ بِزَيْتٍ، وَرُقَاقَةً وَاحِدَةً مِنْ سَلَّةِ الْفَطِيرِ الَّتِي أَمَامَ الرَّبِّ.', 'خروج 29:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 24, 'وَتَضَعُ الْجَمِيعَ فِي يَدَيْ هَارُونَ وَفِي أَيْدِي بَنِيهِ، وَتُرَدِّدُهَا تَرْدِيدًا أَمَامَ الرَّبِّ.', 'خروج 29:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 25, 'ثُمَّ تَأْخُذُهَا مِنْ أَيْدِيهِمْ وَتُوقِدُهَا عَلَى الْمَذْبَحِ فَوْقَ الْمُحْرَقَةِ رَائِحَةَ سَرُورٍ أَمَامَ الرَّبِّ. وَقُودٌ هُوَ لِلرَّبِّ.', 'خروج 29:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 26, '«ثُمَّ تَأْخُذُ الْقَصَّ مِنْ كَبْشِ الْمِلْءِ الَّذِي لِهَارُونَ، وَتُرَدِّدُهُ تَرْدِيدًا أَمَامَ الرَّبِّ، فَيَكُونُ لَكَ نَصِيبًا.', 'خروج 29:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 27, 'وَتُقَدِّسُ قَصَّ التَّرْدِيدِ وَسَاقَ الرَّفِيعَةِ الَّذِي رُدِّدَ وَالَّذِي رُفِعَ مِنْ كَبْشِ الْمِلْءِ مِمَّا لِهَارُونَ وَلِبَنِيهِ،', 'خروج 29:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 28, 'فَيَكُونَانِ لِهَارُونَ وَبَنِيهِ فَرِيضَةً أَبَدِيَّةً مِنْ بَنِي إِسْرَائِيلَ لِأَنَّهُمَا رَفِيعَةٌ. وَيَكُونَانِ رَفِيعَةً مِنْ بَنِي إِسْرَائِيلَ مِنْ ذَبَائِحِ سَلَامَتِهِمْ، رَفِيعَتَهُمْ لِلرَّبِّ.', 'خروج 29:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 29, '«وَالثِّيَابُ الْمُقَدَّسَةُ الَّتِي لِهَارُونَ تَكُونُ لِبَنِيهِ بَعْدَهُ، لِيُمْسَحُوا فِيهَا، وَلِتُمْلَأَ فِيهَا أَيْدِيهِمْ.', 'خروج 29:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 30, 'سَبْعَةَ أَيَّامٍ يَلْبَسُهَا الْكَاهِنُ الَّذِي هُوَ عِوَضٌ عَنْهُ مِنْ بَنِيهِ، الَّذِي يَدْخُلُ خَيْمَةَ الِاجْتِمَاعِ لِيَخْدِمَ فِي الْقُدْسِ.', 'خروج 29:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 31, '«وَأَمَّا كَبْشُ الْمِلْءِ فَتَأْخُذُهُ وَتَطْبُخُ لَحْمَهُ فِي مَكَانٍ مُقَدَّسٍ.', 'خروج 29:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 32, 'فَيَأْكُلُ هَارُونُ وَبَنُوهُ لَحْمَ الْكَبْشِ وَالْخُبْزَ الَّذِي فِي السَّلَّةِ عِنْدَ بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'خروج 29:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 33, 'يَأْكُلُهَا الَّذِينَ كُفِّرَ بِهَا عَنْهُمْ لِمِلْءِ أَيْدِيهِمْ لِتَقْدِيسِهِمْ. وَأَمَّا الْأَجْنَبِيُّ فَلَا يَأْكُلُ لِأَنَّهَا مُقَدَّسَةٌ.', 'خروج 29:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 34, 'وَإِنْ بَقِيَ شَيْءٌ مِنْ لَحْمِ الْمِلْءِ أَوْ مِنَ الْخُبْزِ إِلَى الصَّبَاحِ، تُحْرِقُ الْبَاقِيَ بِالنَّارِ. لَا يُؤْكَلُ لِأَنَّهُ مُقَدَّسٌ.', 'خروج 29:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 35, 'وَتَصْنَعُ لِهَارُونَ وَبَنِيهِ هَكَذَا بِحَسَبِ كُلِّ مَا أَمَرْتُكَ. سَبْعَةَ أَيَّامٍ تَمْلَأُ أَيْدِيَهُمْ.', 'خروج 29:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 36, 'وَتُقَدِّمُ ثَوْرَ خَطِيَّةٍ كُلَّ يَوْمٍ لِأَجْلِ الْكَفَّارَةِ. وَتُطَهِّرُ الْمَذْبَحَ بِتَكْفِيرِكَ عَلَيْهِ، وَتَمْسَحُهُ لِتَقْدِيسِهِ.', 'خروج 29:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 37, 'سَبْعَةَ أَيَّامٍ تُكَفِّرُ عَلَى الْمَذْبَحِ وَتُقَدِّسُهُ، فَيَكُونُ الْمَذْبَحُ قُدْسَ أَقْدَاسٍ. كُلُّ مَا مَسَّ الْمَذْبَحَ يَكُونُ مُقَدَّسًا.', 'خروج 29:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 38, '«وَهَذَا مَا تُقَدِّمُهُ عَلَى الْمَذْبَحِ׃ خَرُوفَانِ حَوْلِيَّانِ كُلَّ يَوْمٍ دَائِمًا.', 'خروج 29:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 39, 'الْخَرُوفُ الْوَاحِدُ تُقَدِّمُهُ صَبَاحًا، وَالْخَرُوفُ الثَّانِي تُقَدِّمُهُ فِي الْعَشِيَّةِ.', 'خروج 29:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 40, 'وَعُشْرٌ مِنْ دَقِيقٍ مَلْتُوتٍ بِرُبْعِ الْهِينِ مِنْ زَيْتِ الرَّضِّ، وَسَكِيبٌ رُبْعُ الْهِينِ مِنَ الْخَمْرِ لِلْخَرُوفِ الْوَاحِدِ.', 'خروج 29:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 41, 'وَالْخَرُوفُ الثَّانِي تُقَدِّمُهُ فِي الْعَشِيَّةِ. مِثْلَ تَقْدِمَةِ الصَّبَاحِ وَسَكِيبِهِ تَصْنَعُ لَهُ. رَائِحَةُ سَرُورٍ، وَقُودٌ لِلرَّبِّ.', 'خروج 29:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 42, 'مُحْرَقَةٌ دَائِمَةٌ فِي أَجْيَالِكُمْ عِنْدَ بَابِ خَيْمَةِ الِاجْتِمَاعِ أَمَامَ الرَّبِّ، حَيْثُ أَجْتَمِعُ بِكُمْ لِأُكَلِّمَكَ هُنَاكَ.', 'خروج 29:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 43, 'وَأَجْتَمِعُ هُنَاكَ بِبَنِي إِسْرَائِيلَ فَيُقَدَّسُ بِمَجْدِي.', 'خروج 29:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 44, 'وَأُقَدِّسُ خَيْمَةَ الِاجْتِمَاعِ وَالْمَذْبَحَ، وَهَارُونُ وَبَنُوهُ أُقَدِّسُهُمْ لِكَيْ يَكْهَنُوا لِي.', 'خروج 29:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 45, 'وَأَسْكُنُ فِي وَسَطِ بَنِي إِسْرَائِيلَ وَأَكُونُ لَهُمْ إِلَهًا،', 'خروج 29:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 29, 46, 'فَيَعْلَمُونَ أَنِّي أَنَا الرَّبُّ إِلَهُهُمُ الَّذِي أَخْرَجَهُمْ مِنْ أَرْضِ مِصْرَ لِأَسْكُنَ فِي وَسْطِهِمْ. أَنَا الرَّبُّ إِلَهُهُمْ.', 'خروج 29:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 1, '«وَتَصْنَعُ مَذْبَحًا لِإِيقَادِ الْبَخُورِ. مِنْ خَشَبِ السَّنْطِ تَصْنَعُهُ.', 'خروج 30:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 2, 'طُولُهُ ذِرَاعٌ وَعَرْضُهُ ذِرَاعٌ. مُرَبَّعًا يَكُونُ. وَارْتِفَاعُهُ ذِرَاعَانِ. مِنْهُ تَكُونُ قُرُونُهُ.', 'خروج 30:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 3, 'وَتُغَشِّيهِ بِذَهَبٍ نَقِيٍّ׃ سَطْحَهُ وَحِيطَانَهُ حَوَالَيْهِ وَقُرُونَهُ. وَتَصْنَعُ لَهُ إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهِ.', 'خروج 30:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 4, 'وَتَصْنَعُ لَهُ حَلْقَتَيْنِ مِنْ ذَهَبٍ تَحْتَ إِكْلِيلِهِ عَلَى جَانِبَيْهِ. عَلَى الْجَانِبَيْنِ تَصْنَعُهُمَا، لِتَكُونَا بَيْتَيْنِ لِعَصَوَيْنِ لِحَمْلِهِ بِهِمَا.', 'خروج 30:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 5, 'وَتَصْنَعُ الْعَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَتُغَشِّيهِمَا بِذَهَبٍ.', 'خروج 30:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 6, 'وَتَجْعَلُهُ قُدَّامَ الْحِجَابِ الَّذِي أَمَامَ تَابُوتِ الشَّهَادَةِ. قُدَّامَ الْغِطَاءِ الَّذِي عَلَى الشَّهَادَةِ حَيْثُ أَجْتَمِعُ بِكَ.', 'خروج 30:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 7, 'فَيُوقِدُ عَلَيْهِ هَارُونُ بَخُورًا عَطِرًا كُلَّ صَبَاحٍ، حِينَ يُصْلِحُ السُّرُجَ يُوقِدُهُ.', 'خروج 30:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 8, 'وَحِينَ يُصْعِدُ هَارُونُ السُّرُجَ فِي الْعَشِيَّةِ يُوقِدُهُ. بَخُورًا دَائِمًا أَمَامَ الرَّبِّ فِي أَجْيَالِكُمْ.', 'خروج 30:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 9, 'لَا تُصْعِدُوا عَلَيْهِ بَخُورًا غَرِيبًا وَلَا مُحْرَقَةً أَوْ تَقْدِمَةً، وَلَا تَسْكُبُوا عَلَيْهِ سَكِيبًا.', 'خروج 30:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 10, 'وَيَصْنَعُ هَارُونُ كَفَّارَةً عَلَى قُرُونِهِ مَرَّةً فِي السَّنَةِ. مِنْ دَمِ ذَبِيحَةِ الْخَطِيَّةِ الَّتِي لِلْكَفَّارَةِ مَرَّةً فِي السَّنَةِ يَصْنَعُ كَفَّارَةً عَلَيْهِ فِي أَجْيَالِكُمْ. قُدْسُ أَقْدَاسٍ هُوَ لِلرَّبِّ».', 'خروج 30:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 11, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 30:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 12, '«إِذَا أَخَذْتَ كَمِّيَّةَ بَنِي إِسْرَائِيلَ بِحَسَبِ الْمَعْدُودِينَ مِنْهُمْ، يُعْطُونَ كُلُّ وَاحِدٍ فِدْيَةَ نَفْسِهِ لِلرَّبِّ عِنْدَمَا تَعُدُّهُمْ، لِئَلَّا يَصِيرَ فِيهِمْ وَبَأٌ عِنْدَمَا تَعُدُّهُمْ.', 'خروج 30:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 13, 'هَذَا مَا يُعْطِيهِ كُلُّ مَنِ اجْتَازَ إِلَى الْمَعْدُودِينَ׃ نِصْفُ الشَّاقِلِ بِشَاقِلِ الْقُدْسِ. الشَّاقِلُ هُوَ عِشْرُونَ جِيرَةً. نِصْفُ الشَّاقِلِ تَقْدِمَةً لِلرَّبِّ.', 'خروج 30:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 14, 'كُلُّ مَنِ اجْتَازَ إِلَى الْمَعْدُودِينَ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا يُعْطِي تَقْدِمَةً لِلرَّبِّ.', 'خروج 30:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 15, 'اَلْغَنِيُّ لَا يُكَثِّرُ وَالْفَقِيرُ لَا يُقَلِّلُ عَنْ نِصْفِ الشَّاقِلِ حِينَ تُعْطُونَ تَقْدِمَةَ الرَّبِّ لِلتَّكْفِيرِ عَنْ نُفُوسِكُمْ.', 'خروج 30:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 16, 'وَتَأْخُذُ فِضَّةَ الْكَفَّارَةِ مِنْ بَنِي إِسْرَائِيلَ، وَتَجْعَلُهَا لِخِدْمَةِ خَيْمَةِ الِاجْتِمَاعِ. فَتَكُونُ لِبَنِي إِسْرَائِيلَ تَذْكَارًا أَمَامَ الرَّبِّ لِلتَّكْفِيرِ عَنْ نُفُوسِكُمْ».', 'خروج 30:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 17, 'وَكَلَّمْ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 30:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 18, '«وَتَصْنَعُ مِرْحَضَةً مِنْ نُحَاسٍ، وَقَاعِدَتَهَا مِنْ نُحَاسٍ، لِلِاغْتِسَالِ. وَتَجْعَلُهَا بَيْنَ خَيْمَةِ الِاجْتِمَاعِ وَالْمَذْبَحِ، وَتَجْعَلُ فِيهَا مَاءً.', 'خروج 30:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 19, 'فَيَغْسِلُ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ وَأَرْجُلَهُمْ مِنْهَا.', 'خروج 30:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 20, 'عِنْدَ دُخُولِهِمْ إِلَى خَيْمَةِ الِاجْتِمَاعِ يَغْسِلُونَ بِمَاءٍ لِئَلَّا يَمُوتُوا، أَوْ عِنْدَ اقْتِرَابِهِمْ إِلَى الْمَذْبَحِ لِلْخِدْمَةِ لِيُوقِدُوا وَقُودًا لِلرَّبِّ.', 'خروج 30:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 21, 'يَغْسِلُونَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ لِئَلَّا يَمُوتُوا. وَيَكُونُ لَهُمْ فَرِيضَةً أَبَدِيَّةً لَهُ وَلِنَسْلِهِ فِي أَجْيَالِهِمْ».', 'خروج 30:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 22, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 30:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 23, '«وَأَنْتَ تَأْخُذُ لَكَ أَفْخَرَ الْأَطْيَابِ׃ مُرًّا قَاطِرًا خَمْسَ مِئَةِ شَاقِلٍ، وَقِرْفَةً عَطِرَةً نِصْفَ ذَلِكَ׃ مِئَتَيْنِ وَخَمْسِينَ، وَقَصَبَ الذَّرِيرَةِ مِئَتَيْنِ وَخَمْسِينَ،', 'خروج 30:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 24, 'وَسَلِيخَةً خَمْسَ مِئَةٍ بِشَاقِلِ الْقُدْسِ، وَمِنْ زَيْتِ الزَّيْتُونِ هِينًا.', 'خروج 30:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 25, 'وَتَصْنَعُهُ دُهْنًا مُقَدَّسًا لِلْمَسْحَةِ. عِطْرَ عِطَارَةٍ صَنْعَةَ الْعَطَّارِ. دُهْنًا مُقَدَّسًا لِلْمَسْحَةِ يَكُونُ.', 'خروج 30:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 26, 'وَتَمْسَحُ بِهِ خَيْمَةَ الِاجْتِمَاعِ، وَتَابُوتَ الشَّهَادَةِ،', 'خروج 30:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 27, 'وَالْمَائِدَةَ وَكُلَّ آنِيَتِهَا، وَالْمَنَارَةَ وَآنِيَتَهَا، وَمَذْبَحَ الْبَخُورِ،', 'خروج 30:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 28, 'وَمَذْبَحَ الْمُحْرَقَةِ وَكُلَّ آنِيَتِهِ، وَالْمِرْحَضَةَ وَقَاعِدَتَهَا.', 'خروج 30:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 29, 'وَتُقَدِّسُهَا فَتَكُونُ قُدْسَ أَقْدَاسٍ. كُلُّ مَا مَسَّهَا يَكُونُ مُقَدَّسًا.', 'خروج 30:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 30, 'وَتَمْسَحُ هَارُونَ وَبَنِيهِ وَتُقَدِّسُهُمْ لِيَكْهَنُوا لِي.', 'خروج 30:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 31, 'وَتُكَلِّمُ بَنِي إِسْرَائِيلَ قَائِلًا׃ يَكُونُ هَذَا لِي دُهْنًا مُقَدَّسًا لِلْمَسْحَةِ فِي أَجْيَالِكُمْ.', 'خروج 30:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 32, 'عَلَى جَسَدِ إِنْسَانٍ لَا يُسْكَبُ، وَعَلَى مَقَادِيرِهِ لَا تَصْنَعُوا مِثْلَهُ. مُقَدَّسٌ هُوَ، وَيَكُونُ مُقَدَّسًا عِنْدَكُمْ.', 'خروج 30:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 33, 'كُلُّ مَنْ رَكَّبَ مِثْلَهُ وَمَنْ جَعَلَ مِنْهُ عَلَى أَجْنَبِيٍّ يُقْطَعُ مِنْ شَعْبِهِ».', 'خروج 30:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 34, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «خُذْ لَكَ أَعْطَارًا׃ مَيْعَةً وَأَظْفَارًا وَقِنَّةً عَطِرَةً وَلُبَانًا نَقِيًّا. تَكُونُ أَجْزَاءً مُتَسَاوِيَةً،', 'خروج 30:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 35, 'فَتَصْنَعُهَا بَخُورًا عَطِرًا صَنْعَةَ الْعَطَّارِ، مُمَلَّحًا نَقِيًّا مُقَدَّسًا.', 'خروج 30:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 36, 'وَتَسْحَقُ مِنْهُ نَاعِمًا، وَتَجْعَلُ مِنْهُ قُدَّامَ الشَّهَادَةِ فِي خَيْمَةِ الِاجْتِمَاعِ حَيْثُ أَجْتَمِعُ بِكَ. قُدْسَ أَقْدَاسٍ يَكُونُ عِنْدَكُمْ.', 'خروج 30:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 37, 'وَالْبَخُورُ الَّذِي تَصْنَعُهُ عَلَى مَقَادِيرِهِ لَا تَصْنَعُوا لِأَنْفُسِكُمْ. يَكُونُ عِنْدَكَ مُقَدَّسًا لِلرَّبِّ.', 'خروج 30:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 30, 38, 'كُلُّ مَنْ صَنَعَ مِثْلَهُ لِيَشُمَّهُ يُقْطَعُ مِنْ شَعْبِهِ».', 'خروج 30:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 31:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 2, '«اُنْظُرْ. قَدْ دَعَوْتُ بَصَلْئِيلَ بْنَ أُورِي بْنَ حُورَ مِنْ سِبْطِ يَهُوذَا بِاسْمِهِ،', 'خروج 31:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 3, 'وَمَلَأْتُهُ مِنْ رُوحِ اللهِ بِالْحِكْمَةِ وَالْفَهْمِ وَالْمَعْرِفَةِ وَكُلِّ صَنْعَةٍ،', 'خروج 31:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 4, 'لِاخْتِرَاعِ مُخْتَرَعَاتٍ لِيَعْمَلَ فِي الذَّهَبِ وَالْفِضَّةِ وَالنُّحَاسِ،', 'خروج 31:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 5, 'وَنَقْشِ حِجَارَةٍ لِلتَّرْصِيعِ، وَنِجَارَةِ الْخَشَبِ، لِيَعْمَلَ فِي كُلِّ صَنْعَةٍ.', 'خروج 31:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 6, 'وَهَا أَنَا قَدْ جَعَلْتُ مَعَهُ أُهُولِيآبَ بْنَ أَخِيسَامَاكَ مِنْ سِبْطِ دَانَ. وَفِي قَلْبِ كُلِّ حَكِيمِ الْقَلْبِ جَعَلْتُ حِكْمَةً، لِيَصْنَعُوا كُلَّ مَا أَمَرْتُكَ׃', 'خروج 31:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 7, 'خَيْمَةَ الِاجْتِمَاعِ، وَتَابُوتَ الشَّهَادَةِ، وَالْغِطَاءَ الَّذِي عَلَيْهِ، وَكُلَّ آنِيَةِ الْخَيْمَةِ،', 'خروج 31:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 8, 'وَالْمَائِدَةَ وَآنِيَتَهَا، وَالْمَنَارَةَ الطَّاهِرَةَ وَكُلَّ آنِيَتِهَا، وَمَذْبَحَ الْبَخُورِ،', 'خروج 31:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 9, 'وَمَذْبَحَ الْمُحْرَقَةِ وَكُلَّ آنِيَتِهِ، وَالْمِرْحَضَةَ وَقَاعِدَتَهَا،', 'خروج 31:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 10, 'وَالثِّيَابَ الْمَنْسُوجَةَ، وَالثِّيَابَ الْمُقَدَّسَةَ لِهَارُونَ الْكَاهِنِ وَثِيَابَ بَنِيهِ لِلْكَهَانَةِ،', 'خروج 31:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 11, 'وَدُهْنَ الْمَسْحَةِ وَالْبَخُورَ الْعَطِرَ لِلْقُدْسِ. حَسَبَ كُلِّ مَا أَمَرْتُكَ بِهِ يَصْنَعُونَ».', 'خروج 31:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 12, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 31:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 13, '«وَأَنْتَ تُكَلِّمُ بَنِي إِسْرَائِيلَ قَائِلًا׃ سُبُوتِي تَحْفَظُونَهَا، لِأَنَّهُ عَلَامَةٌ بَيْنِي وَبَيْنَكُمْ فِي أَجْيَالِكُمْ لِتَعْلَمُوا أَنِّي أَنَا الرَّبُّ الَّذِي يُقَدِّسُكُمْ،', 'خروج 31:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 14, 'فَتَحْفَظُونَ السَّبْتَ لِأَنَّهُ مُقَدَّسٌ لَكُمْ. مَنْ دَنَّسَهُ يُقْتَلُ قَتْلًا. إِنَّ كُلَّ مَنْ صَنَعَ فِيهِ عَمَلًا تُقْطَعُ تِلْكَ النَّفْسُ مِنْ بَيْنِ شَعْبِهَا.', 'خروج 31:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 15, 'سِتَّةَ أَيَّامٍ يُصْنَعُ عَمَلٌ، وَأَمَّا الْيَوْمُ الْسَّابِعُ فَفِيهِ سَبْتُ عُطْلَةٍ مُقَدَّسٌ لِلرَّبِّ. كُلُّ مَنْ صَنَعَ عَمَلًا فِي يَوْمِ السَّبْتِ يُقْتَلُ قَتْلًا.', 'خروج 31:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 16, 'فَيَحْفَظُ بَنُو إِسْرَائِيلَ السَّبْتَ لِيَصْنَعُوا السَّبْتَ فِي أَجْيَالِهِمْ عَهْدًا أَبَدِيًّا.', 'خروج 31:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 17, 'هُوَ بَيْنِي وَبَيْنَ بَنِي إِسْرَائِيلَ عَلَامَةٌ إِلَى الْأَبَدِ. لِأَنَّهُ فِي سِتَّةِ أَيَّامٍ صَنَعَ الرَّبُّ السَّمَاءَ وَالْأَرْضَ، وَفِي الْيَوْمِ السَّابِعِ اسْتَرَاحَ وَتَنَفَّسَ».', 'خروج 31:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 31, 18, 'ثُمَّ أَعْطَى مُوسَى عِنْدَ فَرَاغِهِ مِنَ الْكَلَامِ مَعَهُ فِي جَبَلِ سِينَاءَ لَوْحَيِ الشَّهَادَةِ׃ لَوْحَيْ حَجَرٍ مَكْتُوبَيْنِ بِإِصْبِعِ اللهِ.', 'خروج 31:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 1, 'وَلَمَّا رَأَى الشَّعْبُ أَنَّ مُوسَى أَبْطَأَ فِي النُّزُولِ مِنَ الْجَبَلِ، اجْتَمَعَ الشَّعْبُ عَلَى هَارُونَ وَقَالُوا لَهُ׃ «قُمِ اصْنَعْ لَنَا آلِهَةً تَسِيرُ أَمَامَنَا، لِأَنَّ هَذَا مُوسَى الرَّجُلَ الَّذِي أَصْعَدَنَا مِنْ أَرْضِ مِصْرَ، لَا نَعْلَمُ مَاذَا أَصَابَهُ».', 'خروج 32:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 2, 'فَقَالَ لَهُمْ هَارُونُ׃ «انْزِعُوا أَقْرَاطَ الذَّهَبِ الَّتِي فِي آذَانِ نِسَائِكُمْ وَبَنِيكُمْ وَبَنَاتِكُمْ وَآتُونِي بِهَا».', 'خروج 32:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 3, 'فَنَزَعَ كُلُّ الشَّعْبِ أَقْرَاطَ الذَّهَبِ الَّتِي فِي آذَانِهِمْ وَأَتَوْا بِهَا إِلَى هَارُونَ.', 'خروج 32:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 4, 'فَأَخَذَ ذَلِكَ مِنْ أَيْدِيهِمْ وَصَوَّرَهُ بِالْإِزْمِيلِ، وَصَنَعَهُ عِجْلًا مَسْبُوكًا. فَقَالُوا׃ «هَذِهِ آلِهَتُكَ يَا إِسْرَائِيلُ الَّتِي أَصْعَدَتْكَ مِنْ أَرْضِ مِصْرَ».', 'خروج 32:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 5, 'فَلَمَّا نَظَرَ هَارُونُ بَنَى مَذْبَحًا أَمَامَهُ، وَنَادَى هَارُونُ وَقَالَ׃ «غَدًا عِيدٌ لِلرَّبِّ».', 'خروج 32:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 6, 'فَبَكَّرُوا فِي الْغَدِ وَأَصْعَدُوا مُحْرَقَاتٍ وَقَدَّمُوا ذَبَائِحَ سَلَامَةٍ. وَجَلَسَ الشَّعْبُ لِلْأَكْلِ وَالشُّرْبِ ثُمَّ قَامُوا لِلَّعِبِ.', 'خروج 32:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 7, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «اذْهَبِ انْزِلْ. لِأَنَّهُ قَدْ فَسَدَ شَعْبُكَ الَّذِي أَصْعَدْتَهُ مِنْ أَرْضِ مِصْرَ.', 'خروج 32:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 8, 'زَاغُوا سَرِيعًا عَنِ الطَّرِيقِ الَّذِي أَوْصَيْتُهُمْ بِهِ. صَنَعُوا لَهُمْ عِجْلًا مَسْبُوكًا، وَسَجَدُوا لَهُ وَذَبَحُوا لَهُ وَقَالُوا׃ هَذِهِ آلِهَتُكَ يَا إِسْرَائِيلُ الَّتِي أَصْعَدَتْكَ مِنْ أَرْضِ مِصْرَ».', 'خروج 32:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 9, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «رَأَيْتُ هَذَا الشَّعْبَ وَإِذَا هُوَ شَعْبٌ صُلْبُ الرَّقَبَةِ.', 'خروج 32:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 10, 'فَالْآنَ اتْرُكْنِي لِيَحْمَى غَضَبِي عَلَيْهِمْ وَأُفْنِيَهُمْ، فَأُصَيِّرَكَ شَعْبًا عَظِيمًا».', 'خروج 32:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 11, 'فَتَضَرَّعَ مُوسَى أَمَامَ الرَّبِّ إِلَهِهِ، وَقَالَ׃ «لِمَاذَا يَا رَبُّ يَحْمَى غَضَبُكَ عَلَى شَعْبِكَ الَّذِي أَخْرَجْتَهُ مِنْ أَرْضِ مِصْرَ بِقُوَّةٍ عَظِيمَةٍ وَيَدٍ شَدِيدَةٍ؟', 'خروج 32:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 12, 'لِمَاذَا يَتَكَلَّمُ الْمِصْرِيُّونَ قَائِلِينَ׃ أَخْرَجَهُمْ بِخُبْثٍ لِيَقْتُلَهُمْ فِي الْجِبَالِ، وَيُفْنِيَهُمْ عَنْ وَجْهِ الْأَرْضِ؟ اِرْجِعْ عَنْ حُمُوِّ غَضَبِكَ، وَانْدَمْ عَلَى الشَّرِّ بِشَعْبِكَ.', 'خروج 32:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 13, 'اُذْكُرْ إِبْرَاهِيمَ وَإِسْحَاقَ وَإِسْرَائِيلَ عَبِيدَكَ الَّذِينَ حَلَفْتَ لَهُمْ بِنَفْسِكَ وَقُلْتَ لَهُمْ׃ أُكَثِّرُ نَسْلَكُمْ كَنُجُومِ السَّمَاءِ، وَأُعْطِي نَسْلَكُمْ كُلَّ هَذِهِ الْأَرْضِ الَّتِي تَكَلَّمْتُ عَنْهَا فَيَمْلِكُونَهَا إِلَى الْأَبَدِ».', 'خروج 32:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 14, 'فَنَدِمَ الرَّبُّ عَلَى الشَّرِّ الَّذِي قَالَ إِنَّهُ يَفْعَلُهُ بِشَعْبِهِ.', 'خروج 32:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 15, 'فَانْصَرَفَ مُوسَى وَنَزَلَ مِنَ الْجَبَلِ وَلَوْحَا الشَّهَادَةِ فِي يَدِهِ׃ لَوْحَانِ مَكْتُوبَانِ عَلَى جَانِبَيْهِمَا. مِنْ هُنَا وَمِنْ هُنَا كَانَا مَكْتُوبَيْنِ.', 'خروج 32:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 16, 'وَاللَّوْحَانِ هُمَا صَنْعَةُ اللهِ، وَالْكِتَابَةُ كِتَابَةُ اللهِ مَنْقُوشَةٌ عَلَى اللَّوْحَيْنِ.', 'خروج 32:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 17, 'وَسَمِعَ يَشُوعُ صَوْتَ الشَّعْبِ فِي هُتَافِهِ فَقَالَ لِمُوسَى׃ «صَوْتُ قِتَالٍ فِي الْمَحَلَّةِ».', 'خروج 32:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 18, 'فَقَالَ׃ «لَيْسَ صَوْتَ صِيَاحِ النُّصْرَةِ وَلَا صَوْتَ صِيَاحِ الْكَسْرَةِ، بَلْ صَوْتَ غِنَاءٍ أَنَا سَامِعٌ».', 'خروج 32:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 19, 'وَكَانَ عِنْدَمَا اقْتَرَبَ إِلَى الْمَحَلَّةِ أَنَّهُ أَبْصَرَ الْعِجْلَ وَالرَّقْصَ، فَحَمِيَ غَضَبُ مُوسَى، وَطَرَحَ اللَّوْحَيْنِ مِنْ يَدَيْهِ وَكَسَّرَهُمَا فِي أَسْفَلِ الْجَبَلِ.', 'خروج 32:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 20, 'ثُمَّ أَخَذَ الْعِجْلَ الَّذِي صَنَعُوا وَأَحْرَقَهُ بِالنَّارِ، وَطَحَنَهُ حَتَّى صَارَ نَاعِمًا، وَذَرَّاهُ عَلَى وَجْهِ الْمَاءِ، وَسَقَى بَنِي إِسْرَائِيلَ.', 'خروج 32:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 21, 'وَقَالَ مُوسَى لِهَارُونَ׃ «مَاذَا صَنَعَ بِكَ هَذَا الشَّعْبُ حَتَّى جَلَبْتَ عَلَيْهِ خَطِيَّةً عَظِيمَةً؟»', 'خروج 32:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 22, 'فَقَالَ هَارُونُ׃ «لَا يَحْمَ غَضَبُ سَيِّدِي. أَنْتَ تَعْرِفُ الشَّعْبَ أَنَّهُ فِي شَرٍّ.', 'خروج 32:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 23, 'فَقَالُوا لِيَ׃ اصْنَعْ لَنَا آلِهَةً تَسِيرُ أَمَامَنَا، لِأَنَّ هَذَا مُوسَى الرَّجُلَ الَّذِي أَصْعَدَنَا مِنْ أَرْضِ مِصْرَ، لَا نَعْلَمُ مَاذَا أَصَابَهُ.', 'خروج 32:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 24, 'فَقُلْتُ لَهُمْ׃ مَنْ لَهُ ذَهَبٌ فَلْيَنْزِعْهُ وَيُعْطِنِي. فَطَرَحْتُهُ فِي النَّارِ فَخَرَجَ هَذَا الْعِجْلُ».', 'خروج 32:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 25, 'وَلَمَّا رَأَى مُوسَى الشَّعْبَ أَنَّهُ مُعَرًّى لِأَنَّ هَارُونَ كَانَ قَدْ عَرَّاهُ لِلْهُزْءِ بَيْنَ مُقَاوِمِيهِ،', 'خروج 32:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 26, 'وَقَفَ مُوسَى فِي بَابِ الْمَحَلَّةِ، وَقَالَ׃ «مَنْ لِلرَّبِّ فَإِلَيَّ». فَاجْتَمَعَ إِلَيْهِ جَمِيعُ بَنِي لَاوِي.', 'خروج 32:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 27, 'فَقَالَ لَهُمْ׃ «هَكَذَا قَالَ الرَّبُّ إِلَهُ إِسْرَائِيلَ׃ ضَعُوا كُلُّ وَاحِدٍ سَيْفَهُ عَلَى فَخْذِهِ وَمُرُّوا وَارْجِعُوا مِنْ بَابٍ إِلَى بَابٍ فِي الْمَحَلَّةِ، وَاقْتُلُوا كُلُّ وَاحِدٍ أَخَاهُ وَكُلُّ وَاحِدٍ صَاحِبَهُ وَكُلُّ وَاحِدٍ قَرِيبَهُ».', 'خروج 32:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 28, 'فَفَعَلَ بَنُو لَاوِي بِحَسَبِ قَوْلِ مُوسَى. وَوَقَعَ مِنَ الشَّعْبِ فِي ذَلِكَ الْيَوْمِ نَحْوُ ثَلَاثَةِ آلَافِ رَجُلٍ.', 'خروج 32:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 29, 'وَقَالَ مُوسَى׃ «امْلَأُوا أَيْدِيَكُمُ الْيَوْمَ لِلرَّبِّ، حَتَّى كُلُّ وَاحِدٍ بِابْنِهِ وَبِأَخِيهِ، فَيُعْطِيَكُمُ الْيَوْمَ بَرَكَةً».', 'خروج 32:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 30, 'وَكَانَ فِي الْغَدِ أَنَّ مُوسَى قَالَ لِلشَّعْبِ׃ «أَنْتُمْ قَدْ أَخْطَأْتُمْ خَطِيَّةً عَظِيمَةً، فَأَصْعَدُ الْآنَ إِلَى الرَّبِّ لَعَلِّي أُكَفِّرُ خَطِيَّتَكُمْ».', 'خروج 32:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 31, 'فَرَجَعَ مُوسَى إِلَى الرَّبِّ، وَقَالَ׃ «آهِ، قَدْ أَخْطَأَ هَذَا الشَّعْبُ خَطِيَّةً عَظِيمَةً وَصَنَعُوا لِأَنْفُسِهِمْ آلِهَةً مِنْ ذَهَبٍ.', 'خروج 32:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 32, 'وَالْآنَ إِنْ غَفَرْتَ خَطِيَّتَهُمْ، وَإِلَّا فَامْحُنِي مِنْ كِتَابِكَ الَّذِي كَتَبْتَ».', 'خروج 32:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 33, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «مَنْ أَخْطَأَ إِلَيَّ أَمْحُوهُ مِنْ كِتَابِي.', 'خروج 32:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 34, 'وَالْآنَ اذْهَبِ اهْدِ الشَّعْبَ إِلَى حَيْثُ كَلَّمْتُكَ. هُوَذَا مَلَاكِي يَسِيرُ أَمَامَكَ. وَلَكِنْ فِي يَوْمِ افْتِقَادِي أَفْتَقِدُ فِيهِمْ خَطِيَّتَهُمْ».', 'خروج 32:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 32, 35, 'فَضَرَبَ الرَّبُّ الشَّعْبَ، لِأَنَّهُمْ صَنَعُوا الْعِجْلَ الَّذِي صَنَعَهُ هَارُونُ.', 'خروج 32:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 1, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «اذْهَبِ اصْعَدْ مِنْ هُنَا أَنْتَ وَالشَّعْبُ الَّذِي أَصْعَدْتَهُ مِنْ أَرْضِ مِصْرَ إِلَى الْأَرْضِ الَّتِي حَلَفْتُ لِإِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ قَائِلًا׃ لِنَسْلِكَ أُعْطِيهَا.', 'خروج 33:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 2, 'وَأَنَا أُرْسِلُ أَمَامَكَ مَلَاكًا، وَأَطْرُدُ الْكَنْعَانِيِّينَ وَالْأَمُورِيِّينَ وَالْحِثِّيِّينَ وَالْفِرِزِّيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ.', 'خروج 33:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 3, 'إِلَى أَرْضٍ تَفِيضُ لَبَنًا وَعَسَلًا. فَإِنِّي لَا أَصْعَدُ فِي وَسَطِكَ لِأَنَّكَ شَعْبٌ صُلْبُ الرَّقَبَةِ، لِئَلَّا أُفْنِيَكَ فِي الطَّرِيقِ».', 'خروج 33:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 4, 'فَلَمَّا سَمِعَ الشَّعْبُ هَذَا الْكَلَامَ السُّوءَ نَاحُوا وَلَمْ يَضَعْ أَحَدٌ زِينَتَهُ عَلَيْهِ.', 'خروج 33:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 5, 'وَكَانَ الرَّبُّ قَدْ قَالَ لِمُوسَى׃ «قُلْ لِبَنِي إِسْرَائِيلَ׃ أَنْتُمْ شَعْبٌ صُلْبُ الرَّقَبَةِ. إِنْ صَعِدْتُ لَحْظَةً وَاحِدَةً فِي وَسَطِكُمْ أَفْنَيْتُكُمْ. وَلَكِنِ الْآنَ اخْلَعْ زِينَتَكَ عَنْكَ فَأَعْلَمَ مَاذَا أَصْنَعُ بِكَ».', 'خروج 33:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 6, 'فَنَزَعَ بَنُو إِسْرَائِيلَ زِينَتَهُمْ مِنْ جَبَلِ حُورِيبَ.', 'خروج 33:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 7, 'وَأَخَذَ مُوسَى الْخَيْمَةَ وَنَصَبَهَا لَهُ خَارِجَ الْمَحَلَّةِ، بَعِيدًا عَنِ الْمَحَلَّةِ، وَدَعَاهَا «خَيْمَةَ الِاجْتِمَاعِ». فَكَانَ كُلُّ مَنْ يَطْلُبُ الرَّبَّ يَخْرُجُ إِلَى خَيْمَةِ الِاجْتِمَاعِ الَّتِي خَارِجَ الْمَحَلَّةِ.', 'خروج 33:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 8, 'وَكَانَ جَمِيعُ الشَّعْبِ إِذَا خَرَجَ مُوسَى إِلَى الْخَيْمَةِ يَقُومُونَ وَيَقِفُونَ كُلُّ وَاحِدٍ فِي بَابِ خَيْمَتِهِ وَيَنْظُرُونَ وَرَاءَ مُوسَى حَتَّى يَدْخُلَ الْخَيْمَةَ.', 'خروج 33:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 9, 'وَكَانَ عَمُودُ السَّحَابِ إِذَا دَخَلَ مُوسَى الْخَيْمَةَ، يَنْزِلُ وَيَقِفُ عِنْدَ بَابِ الْخَيْمَةِ. وَيَتَكَلَّمُ الرَّبُّ مَعَ مُوسَى.', 'خروج 33:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 10, 'فَيَرَى جَمِيعُ الشَّعْبِ عَمُودَ السَّحَابِ، وَاقِفًا عِنْدَ بَابِ الْخَيْمَةِ، وَيَقُومُ كُلُّ الشَّعْبِ وَيَسْجُدُونَ كُلُّ وَاحِدٍ فِي بَابِ خَيْمَتِهِ.', 'خروج 33:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 11, 'وَيُكَلِّمُ الرَّبُّ مُوسَى وَجْهًا لِوَجْهٍ، كَمَا يُكَلِّمُ الرَّجُلُ صَاحِبَهُ. وَإِذَا رَجَعَ مُوسَى إِلَى الْمَحَلَّةِ كَانَ خَادِمُهُ يَشُوعُ بْنُ نُونَ الْغُلَامُ، لَا يَبْرَحُ مِنْ دَاخِلِ الْخَيْمَةِ.', 'خروج 33:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 12, 'وَقَالَ مُوسَى لِلرَّبِّ׃ «انْظُرْ. أَنْتَ قَائِلٌ لِي׃ أَصْعِدْ هَذَا الشَّعْبَ، وَأَنْتَ لَمْ تُعَرِّفْنِي مَنْ تُرْسِلُ مَعِي. وَأَنْتَ قَدْ قُلْتَ׃ عَرَفْتُكَ بِاسْمِكَ، وَوَجَدْتَ أَيْضًا نِعْمَةً فِي عَيْنَيَّ.', 'خروج 33:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 13, 'فَالْآنَ إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ فَعَلِّمْنِي طَرِيقَكَ حَتَّى أَعْرِفَكَ لِكَيْ أَجِدَ نِعْمَةً فِي عَيْنَيْكَ. وَانْظُرْ أَنَّ هَذِهِ الْأُمَّةَ شَعْبُكَ».', 'خروج 33:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 14, 'فَقَالَ׃ «وَجْهِي يَسِيرُ فَأُرِيحُكَ».', 'خروج 33:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 15, 'فَقَالَ لَهُ׃ «إِنْ لَمْ يَسِرْ وَجْهُكَ فَلَا تُصْعِدْنَا مِنْ هَهُنَا،', 'خروج 33:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 16, 'فَإِنَّهُ بِمَاذَا يُعْلَمُ أَنِّي وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ أَنَا وَشَعْبُكَ؟ أَلَيْسَ بِمَسِيرِكَ مَعَنَا؟ فَنَمْتَازَ أَنَا وَشَعْبُكَ عَنْ جَمِيعِ الشُّعُوبِ الَّذِينَ عَلَى وَجْهِ الْأَرْضِ».', 'خروج 33:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 17, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «هَذَا الْأَمْرُ أَيْضًا الَّذِي تَكَلَّمْتَ عَنْهُ أَفْعَلُهُ، لِأَنَّكَ وَجَدْتَ نِعْمَةً فِي عَيْنَيَّ، وَعَرَفْتُكَ بِاسْمِكَ».', 'خروج 33:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 18, 'فَقَالَ׃ «أَرِنِي مَجْدَكَ».', 'خروج 33:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 19, 'فَقَالَ׃ «أُجِيزُ كُلَّ جُودَتِي قُدَّامَكَ. وَأُنَادِي بِاسْمِ الرَّبِّ قُدَّامَكَ. وَأَتَرَاءَفُ عَلَى مَنْ أَتَرَاءَفُ، وَأَرْحَمُ مَنْ أَرْحَمُ».', 'خروج 33:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 20, 'وَقَالَ׃ «لَا تَقْدِرُ أَنْ تَرَى وَجْهِي، لِأَنَّ الْإِنْسَانَ لَا يَرَانِي وَيَعِيشُ».', 'خروج 33:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 21, 'وَقَالَ الرَّبُّ׃ «هُوَذَا عِنْدِي مَكَانٌ، فَتَقِفُ عَلَى الصَّخْرَةِ.', 'خروج 33:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 22, 'وَيَكُونُ مَتَى اجْتَازَ مَجْدِي، أَنِّي أَضَعُكَ فِي نُقْرَةٍ مِنَ الصَّخْرَةِ، وَأَسْتُرُكَ بِيَدِي حَتَّى أَجْتَازَ.', 'خروج 33:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 33, 23, 'ثُمَّ أَرْفَعُ يَدِي فَتَنْظُرُ وَرَائِي، وَأَمَّا وَجْهِي فَلَا يُرَى».', 'خروج 33:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 1, 'ثُمَّ قَالَ الرَّبُّ لِمُوسَى׃ «انْحَتْ لَكَ لَوْحَيْنِ مِنْ حَجَرٍ مِثْلَ الْأَوَّلَيْنِ، فَأَكْتُبَ أَنَا عَلَى اللَّوْحَيْنِ الْكَلِمَاتِ الَّتِي كَانَتْ عَلَى اللَّوْحَيْنِ الْأَوَّلَيْنِ اللَّذَيْنِ كَسَرْتَهُمَا.', 'خروج 34:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 2, 'وَكُنْ مُسْتَعِدًّا لِلصَّبَاحِ. وَاصْعَدْ فِي الصَّبَاحِ إِلَى جَبَلِ سِينَاءَ، وَقِفْ عِنْدِي هُنَاكَ عَلَى رَأْسِ الْجَبَلِ.', 'خروج 34:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 3, 'وَلَا يَصْعَدْ أَحَدٌ مَعَكَ، وَأَيْضًا لَا يُرَ أَحَدٌ فِي كُلِّ الْجَبَلِ. الْغَنَمُ أَيْضًا وَالْبَقَرُ لَا تَرْعَ إِلَى جِهَةِ ذَلِكَ الْجَبَلِ».', 'خروج 34:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 4, 'فَنَحَتَ لَوْحَيْنِ مِنْ حَجَرٍ كَالْأَوَّلَيْنِ. وَبَكَّرَ مُوسَى فِي الصَّبَاحِ وَصَعِدَ إِلَى جَبَلِ سِينَاءَ كَمَا أَمَرَهُ الرَّبُّ، وَأَخَذَ فِي يَدِهِ لَوْحَيِ الْحَجَرِ.', 'خروج 34:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 5, 'فَنَزَلَ الرَّبُّ فِي السَّحَابِ، فَوَقَفَ عِنْدَهُ هُنَاكَ وَنَادَى بِاسْمِ الرَّبِّ.', 'خروج 34:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 6, 'فَاجْتَازَ الرَّبُّ قُدَّامَهُ، وَنَادَى الرَّبُّ׃ «الرَّبُّ إِلَهٌ رَحِيمٌ وَرَؤُوفٌ، بَطِيءُ الْغَضَبِ وَكَثِيرُ الْإِحْسَانِ وَالْوَفَاءِ.', 'خروج 34:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 7, 'حَافِظُ الْإِحْسَانِ إِلَى أُلُوفٍ. غَافِرُ الْإِثْمِ وَالْمَعْصِيَةِ وَالْخَطِيَّةِ. وَلَكِنَّهُ لَنْ يُبْرِئَ إِبْرَاءً. مُفْتَقِدٌ إِثْمَ الْآبَاءِ فِي الْأَبْنَاءِ، وَفِي أَبْنَاءِ الْأَبْنَاءِ، فِي الْجِيلِ الثَّالِثِ وَالرَّابِعِ».', 'خروج 34:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 8, 'فَأَسْرَعَ مُوسَى وَخَرَّ إِلَى الْأَرْضِ وَسَجَدَ.', 'خروج 34:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 9, 'وَقَالَ׃ «إِنْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ أَيُّهَا السَّيِّدُ فَلْيَسِرِ السَّيِّدُ فِي وَسَطِنَا، فَإِنَّهُ شَعْبٌ صُلْبُ الرَّقَبَةِ. وَاغْفِرْ إِثْمَنَا وَخَطِيَّتَنَا وَاتَّخِذْنَا مُلْكًا».', 'خروج 34:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 10, 'فَقَالَ׃ «هَا أَنَا قَاطِعٌ عَهْدًا. قُدَّامَ جَمِيعِ شَعْبِكَ أَفْعَلُ عَجَائِبَ لَمْ تُخْلَقْ فِي كُلِّ الْأَرْضِ وَفِي جَمِيعِ الْأُمَمِ، فَيَرَى جَمِيعُ الشَّعْبِ الَّذِي أَنْتَ فِي وَسَطِهِ فِعْلَ الرَّبِّ. إِنَّ الَّذِي أَنَا فَاعِلُهُ مَعَكَ رَهِيبٌ.', 'خروج 34:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 11, '«اِحْفَظْ مَا أَنَا مُوصِيكَ الْيَوْمَ. هَا أَنَا طَارِدٌ مِنْ قُدَّامِكَ الْأَمُورِيِّينَ وَالْكَنْعَانِيِّينَ وَالْحِثِّيِّينَ وَالْفِرِزِّيِّينَ وَالْحِوِّيِّينَ وَالْيَبُوسِيِّينَ.', 'خروج 34:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 12, 'اِحْتَرِزْ مِنْ أَنْ تَقْطَعَ عَهْدًا مَعَ سُكَّانِ الْأَرْضِ الَّتِي أَنْتَ آتٍ إِلَيْهَا لِئَلَّا يَصِيرُوا فَخًّا فِي وَسَطِكَ،', 'خروج 34:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 13, 'بَلْ تَهْدِمُونَ مَذَابِحَهُمْ، وَتُكَسِّرُونَ أَنْصَابَهُمْ، وَتَقْطَعُونَ سَوَارِيَهُمْ.', 'خروج 34:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 14, 'فَإِنَّكَ لَا تَسْجُدُ لِإِلَهٍ آخَرَ، لِأَنَّ الرَّبَّ اسْمُهُ غَيُورٌ. إِلَهٌ غَيُورٌ هُوَ.', 'خروج 34:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 15, 'اِحْتَرِزْ مِنْ أَنْ تَقْطَعَ عَهْدًا مَعَ سُكَّانِ الْأَرْضِ، فَيَزْنُونَ وَرَاءَ آلِهَتِهِمْ وَيَذْبَحُونَ لِآلِهَتِهِمْ، فَتُدْعَى وَتَأْكُلُ مِنْ ذَبِيحَتِهِمْ،', 'خروج 34:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 16, 'وَتَأْخُذُ مِنْ بَنَاتِهِمْ لِبَنِيكَ، فَتَزْنِي بَنَاتُهُمْ وَرَاءَ آلِهَتِهِنَّ، وَيَجْعَلْنَ بَنِيكَ يَزْنُونَ وَرَاءَ آلِهَتِهِنَّ.', 'خروج 34:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 17, '«لَا تَصْنَعْ لِنَفْسِكَ آلِهَةً مَسْبُوكَةً.', 'خروج 34:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 18, 'تَحْفَظُ عِيدَ الْفَطِيرِ. سَبْعَةَ أَيَّامٍ تَأْكُلُ فَطِيرًا كَمَا أَمَرْتُكَ فِي وَقْتِ شَهْرِ أَبِيبَ، لِأَنَّكَ فِي شَهْرِ أَبِيبَ خَرَجْتَ مِنْ مِصْرَ.', 'خروج 34:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 19, 'لِي كُلُّ فَاتِحِ رَحِمٍ، وَكُلُّ مَا يُولَدُ ذَكَرًا مِنْ مَوَاشِيكَ بِكْرًا مِنْ ثَوْرٍ وَشَاةٍ.', 'خروج 34:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 20, 'وَأَمَّا بِكْرُ الْحِمَارِ فَتَفْدِيهِ بِشَاةٍ، وَإِنْ لَمْ تَفْدِهِ تَكْسِرُ عُنُقَهُ. كُلُّ بِكْرٍ مِنْ بَنِيكَ تَفْدِيهِ، وَلَا يَظْهَرُوا أَمَامِي فَارِغِينَ.', 'خروج 34:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 21, 'سِتَّةَ أَيَّامٍ تَعْمَلُ، وَأَمَّا الْيَوْمُ السَّابِعُ فَتَسْتَرِيحُ فِيهِ. فِي الْفَلَاحَةِ وَفِي الْحَصَادِ تَسْتَرِيحُ.', 'خروج 34:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 22, 'وَتَصْنَعُ لِنَفْسِكَ عِيدَ الْأَسَابِيعِ أَبْكَارِ حِصَادِ الْحِنْطَةِ. وَعِيدَ الْجَمْعِ فِي آخِرِ السَّنَةِ.', 'خروج 34:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 23, 'ثَلَاثَ مَرَّاتٍ فِي السَّنَةِ يَظْهَرُ جَمِيعُ ذُكُورِكَ أَمَامَ السَّيِّدِ الرَّبِّ إِلَهِ إِسْرَائِيلَ.', 'خروج 34:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 24, 'فَإِنِّي أَطْرُدُ الْأُمَمَ مِنْ قُدَّامِكَ وَأُوَسِّعُ تُخُومَكَ، وَلَا يَشْتَهِي أَحَدٌ أَرْضَكَ حِينَ تَصْعَدُ لِتَظْهَرَ أَمَامَ الرَّبِّ إِلَهِكَ ثَلَاثَ مَرَّاتٍ فِي السَّنَةِ.', 'خروج 34:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 25, 'لَا تَذْبَحْ عَلَى خَمِيرٍ دَمَ ذَبِيحَتِي، وَلَا تَبِتْ إِلَى الْغَدِ ذَبِيحَةُ عِيدِ الْفِصْحِ.', 'خروج 34:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 26, 'أَوَّلُ أَبْكَارِ أَرْضِكَ تُحْضِرُهُ إِلَى بَيْتِ الرَّبِّ إِلَهِكَ. لَا تَطْبُخْ جَدْيًا بِلَبَنِ أُمِّهِ».', 'خروج 34:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 27, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «اكْتُبْ لِنَفْسِكَ هَذِهِ الْكَلِمَاتِ، لِأَنَّنِي بِحَسَبِ هَذِهِ الْكَلِمَاتِ قَطَعْتُ عَهْدًا مَعَكَ وَمَعَ إِسْرَائِيلَ».', 'خروج 34:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 28, 'وَكَانَ هُنَاكَ عِنْدَ الرَّبِّ أَرْبَعِينَ نَهَارًا وَأَرْبَعِينَ لَيْلَةً، لَمْ يَأْكُلْ خُبْزًا وَلَمْ يَشْرَبْ مَاءً. فَكَتَبَ عَلَى اللَّوْحَيْنِ كَلِمَاتِ الْعَهْدِ، الْكَلِمَاتِ الْعَشَرَ.', 'خروج 34:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 29, 'وَكَانَ لَمَّا نَزَلَ مُوسَى مِنْ جَبَلِ سِينَاءَ وَلَوْحَا الشَّهَادَةِ فِي يَدِ مُوسَى، عِنْدَ نُزُولِهِ مِنَ الْجَبَلِ، أَنَّ مُوسَى لَمْ يَعْلَمْ أَنَّ جِلْدَ وَجْهِهِ صَارَ يَلْمَعُ فِي كَلَامِهِ مَعَهُ.', 'خروج 34:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 30, 'فَنَظَرَ هَارُونُ وَجَمِيعُ بَنِي إِسْرَائِيلَ مُوسَى وَإِذَا جِلْدُ وَجْهِهِ يَلْمَعُ، فَخَافُوا أَنْ يَقْتَرِبُوا إِلَيْهِ.', 'خروج 34:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 31, 'فَدَعَاهُمْ مُوسَى. فَرَجَعَ إِلَيْهِ هَارُونُ وَجَمِيعُ الرُّؤَسَاءِ فِي الْجَمَاعَةِ، فَكَلَّمَهُمْ مُوسَى.', 'خروج 34:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 32, 'وَبَعْدَ ذَلِكَ اقْتَرَبَ جَمِيعُ بَنِي إِسْرَائِيلَ، فَأَوْصَاهُمْ بِكُلِّ مَا تَكَلَّمَ بِهِ الرَّبُّ مَعَهُ فِي جَبَلِ سِينَاءَ.', 'خروج 34:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 33, 'وَلَمَّا فَرَغَ مُوسَى مِنَ الْكَلَامِ مَعَهُمْ، جَعَلَ عَلَى وَجْهِهِ بُرْقُعًا.', 'خروج 34:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 34, 'وَكَانَ مُوسَى عِنْدَ دُخُولِهِ أَمَامَ الرَّبِّ لِيَتَكَلَّمَ مَعَهُ يَنْزِعُ الْبُرْقُعَ حَتَّى يَخْرُجَ، ثُمَّ يَخْرُجُ وَيُكَلِّمُ بَنِي إِسْرَائِيلَ بِمَا يُوصَى.', 'خروج 34:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 34, 35, 'فَإِذَا رَأَى بَنُو إِسْرَائِيلَ وَجْهَ مُوسَى أَنَّ جِلْدَهُ يَلْمَعُ كَانَ مُوسَى يَرُدُّ الْبُرْقُعَ عَلَى وَجْهِهِ حَتَّى يَدْخُلَ لِيَتَكَلَّمَ مَعَهُ.', 'خروج 34:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 1, 'وَجَمَعَ مُوسَى كُلَّ جَمَاعَةِ بَنِي إِسْرَائِيلَ وَقَالَ لَهُمْ׃ «هَذِهِ هِيَ الْكَلِمَاتُ الَّتِي أَمَرَ الرَّبُّ أَنْ تُصْنَعَ׃', 'خروج 35:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 2, 'سِتَّةَ أَيَّامٍ يُعْمَلُ عَمَلٌ، وَأَمَّا الْيَوْمُ الْسَّابِعُ فَفِيهِ يَكُونُ لَكُمْ سَبْتُ عُطْلَةٍ مُقَدَّسٌ لِلرَّبِّ. كُلُّ مَنْ يَعْمَلُ فِيهِ عَمَلًا يُقْتَلُ.', 'خروج 35:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 3, 'لَا تُشْعِلُوا نَارًا فِي جَمِيعِ مَسَاكِنِكُمْ يَوْمَ السَّبْتِ».', 'خروج 35:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 4, 'وَكَلَّمَ مُوسَى كُلَّ جَمَاعَةِ بَنِي إِسْرَائِيلَ قَائِلًا׃ «هَذَا هُوَ الشَّيْءُ الَّذِي أَمَرَ بِهِ الرَّبُّ قَائِلًا׃', 'خروج 35:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 5, 'خُذُوا مِنْ عِنْدِكُمْ تَقْدِمَةً لِلرَّبِّ. كُلُّ مَنْ قَلْبُهُ سَمُوحٌ فَلْيَأْتِ بِتَقْدِمَةِ الرَّبِّ׃ ذَهَبًا وَفِضَّةً وَنُحَاسًا،', 'خروج 35:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 6, 'وَأَسْمَانْجُونِيًّا وَأُرْجُوَانًا وَقِرْمِزًا وَبُوصًا وَشَعْرَ مِعْزًى،', 'خروج 35:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 7, 'وَجُلُودَ كِبَاشٍ مُحَمَّرَةً وَجُلُودَ تُخَسٍ وَخَشَبَ سَنْطٍ،', 'خروج 35:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 8, 'وَزَيْتًا لِلضَّوْءِ وَأَطْيَابًا لِدُهْنِ الْمَسْحَةِ وَلِلْبَخُورِ الْعَطِرِ،', 'خروج 35:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 9, 'وَحِجَارَةَ جَزْعٍ وَحِجَارَةَ تَرْصِيعٍ لِلرِّدَاءِ وَالصُّدْرَةِ.', 'خروج 35:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 10, 'وَكُلُّ حَكِيمِ الْقَلْبِ بَيْنَكُمْ فَلْيَأْتِ وَيَصْنَعْ كُلَّ مَا أَمَرَ بِهِ الرَّبُّ׃', 'خروج 35:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 11, 'الْمَسْكَنَ وَخَيْمَتَهُ وَغِطَاءَهُ وَأَشِظَّتَهُ وَأَلْوَاحَهُ وَعَوَارِضَهُ وَأَعْمِدَتَهُ وَقَوَاعِدَهُ،', 'خروج 35:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 12, 'وَالتَّابُوتَ وَعَصَوَيْهِ، وَالْغِطَاءَ وَحِجَابَ السَّجْفِ،', 'خروج 35:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 13, 'وَالْمَائِدَةَ وَعَصَوَيْهَا وَكُلَّ آنِيَتِهَا، وَخُبْزَ الْوُجُوهِ،', 'خروج 35:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 14, 'وَمَنَارَةَ الضَّوْءِ وَآنِيَتَهَا وَسُرُجَهَا وَزَيْتَ الضَّوْءِ،', 'خروج 35:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 15, 'وَمَذْبَحَ الْبَخُورِ وَعَصَوَيْهِ، وَدُهْنَ الْمَسْحَةِ وَالْبَخُورَ الْعَطِرَ، وَسَجْفَ الْبَابِ لِمَدْخَلِ الْمَسْكَنِ،', 'خروج 35:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 16, 'وَمَذْبَحَ الْمُحْرَقَةِ وَشُبَّاكَةَ النُّحَاسِ الَّتِي لَهُ وَعَصَوَيْهِ وَكُلَّ آنِيَتِهِ، وَالْمِرْحَضَةَ وَقَاعِدَتَهَا،', 'خروج 35:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 17, 'وَأَسْتَارَ الدَّارِ وَأَعْمِدَتَهَا وَقَوَاعِدَهَا، وَسَجْفَ بَابِ الدَّارِ،', 'خروج 35:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 18, 'وَأَوْتَادَ الْمَسْكَنِ، وَأَوْتَادَ الدَّارِ وَأَطْنَابَهَا،', 'خروج 35:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 19, 'وَالثِّيَابَ الْمَنْسُوجَةَ لِلْخِدْمَةِ فِي الْمَقْدِسِ، وَالثِّيَابَ الْمُقَدَّسَةَ لِهَارُونَ الْكَاهِنِ، وَثِيَابَ بَنِيهِ لِلْكَهَانَةِ».', 'خروج 35:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 20, 'فَخَرَجَ كُلُّ جَمَاعَةِ بَنِي إِسْرَائِيلَ مِنْ قُدَّامِ مُوسَى،', 'خروج 35:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 21, 'ثُمَّ جَاءَ كُلُّ مَنْ أَنْهَضَهُ قَلْبُهُ، وَكُلُّ مَنْ سَمَّحَتْهُ رُوحُهُ. جَاءُوا بِتَقْدِمَةِ الرَّبِّ لِعَمَلِ خَيْمَةِ الِاجْتِمَاعِ وَلِكُلِّ خِدْمَتِهَا وَلِلثِّيَابِ الْمُقَدَّسَةِ.', 'خروج 35:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 22, 'وَجَاءَ الرِّجَالُ مَعَ النِّسَاءِ، كُلُّ سَمُوحِ الْقَلْبِ، جَاءَ بِخَزَائِمَ وَأَقْرَاطٍ وَخَوَاتِمَ وَقَلَائِدَ، كُلِّ مَتَاعٍ مِنَ الذَّهَبِ. وَكُلُّ مَنْ قَدَّمَ تَقْدِمَةَ ذَهَبٍ لِلرَّبِّ.', 'خروج 35:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 23, 'وَكُلُّ مَنْ وُجِدَ عِنْدَهُ أَسْمَانْجُونِيٌّ وَأُرْجُوانٌ وَقِرْمِزٌ وَبُوصٌ وَشَعْرُ مِعْزًى وَجُلُودُ كِبَاشٍ مُحَمَّرَةٌ وَجُلُودُ تُخَسٍ، جَاءَ بِهَا.', 'خروج 35:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 24, 'كُلُّ مَنْ قَدَّمَ تَقْدِمَةَ فِضَّةٍ وَنُحَاسٍ جَاءَ بِتَقْدِمَةِ الرَّبِّ. وَكُلُّ مَنْ وُجِدَ عِنْدَهُ خَشَبُ سَنْطٍ لِصَنْعَةٍ مَا مِنَ الْعَمَلِ جَاءَ بِهِ.', 'خروج 35:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 25, 'وَكُلُّ النِّسَاءِ الْحَكِيمَاتِ الْقَلْبِ غَزَلْنَ بِأَيْدِيهِنَّ وَجِئْنَ مِنَ الْغَزْلِ بِالْأَسْمَانْجُونِيِّ وَالْأُرْجُوَانِ وَالْقِرْمِزِ وَالْبُوصِ.', 'خروج 35:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 26, 'وَكُلُّ النِّسَاءِ اللَّوَاتِي أَنْهَضَتْهُنَّ قُلُوبُهُنَّ بِالْحِكْمَةِ غَزَلْنَ شَعْرَ الْمِعْزَى.', 'خروج 35:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 27, 'وَالرُّؤَسَاءُ جَاءُوا بِحِجَارَةِ الْجَزْعِ وَحِجَارَةِ التَّرْصِيعِ لِلرِّدَاءِ وَالصُّدْرَةِ،', 'خروج 35:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 28, 'وَبِالطِّيبِ وَالزَّيْتِ لِلضَّوْءِ وَلِدُهْنِ الْمَسْحَةِ وَلِلْبَخُورِ الْعَطِرِ.', 'خروج 35:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 29, 'بَنُو إِسْرَائِيلَ، جَمِيعُ الرِّجَالِ وَالنِّسَاءِ الَّذِينَ سَمَّحَتْهُمْ قُلُوبُهُمْ أَنْ يَأْتُوا بِشَيْءٍ لِكُلِّ الْعَمَلِ الَّذِي أَمَرَ الرَّبُّ أَنْ يُصْنَعَ عَلَى يَدِ مُوسَى، جَاءُوا بِهِ تَبَرُّعًا إِلَى الرَّبِّ.', 'خروج 35:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 30, 'وَقَالَ مُوسَى لِبَنِي إِسْرَائِيلَ׃ «انْظُرُوا. قَدْ دَعَا الرَّبُّ بَصَلْئِيلَ بْنَ أُورِي بْنَ حُورَ مِنْ سِبْطِ يَهُوذَا بِاسْمِهِ،', 'خروج 35:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 31, 'وَمَلَأَهُ مِنْ رُوحِ اللهِ بِالْحِكْمَةِ وَالْفَهْمِ وَالْمَعْرِفَةِ وَكُلِّ صَنْعَةٍ،', 'خروج 35:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 32, 'وَلِاخْتِرَاعِ مُخْتَرَعَاتٍ، لِيَعْمَلَ فِي الذَّهَبِ وَالْفِضَّةِ وَالنُّحَاسِ،', 'خروج 35:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 33, 'وَنَقْشِ حِجَارَةٍ لِلتَّرْصِيعِ، وَنِجَارَةِ الْخَشَبِ، لِيَعْمَلَ فِي كُلِّ صَنْعَةٍ مِنَ الْمُخْتَرَعَاتِ.', 'خروج 35:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 34, 'وَجَعَلَ فِي قَلْبِهِ أَنْ يُعَلِّمَ هُوَ وَأُهُولِيآبُ بْنَ أَخِيسَامَاكَ مِنْ سِبْطِ دَانَ.', 'خروج 35:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 35, 35, 'قَدْ مَلَأَهُمَا حِكْمَةَ قَلْبٍ لِيَصْنَعَا كُلَّ عَمَلِ النَّقَّاشِ وَالْحَائِكِ الْحَاذِقِ وَالطَّرَّازِ فِي الْأَسْمَانْجُونِيِّ وَالْأُرْجُوَانِ وَالْقِرْمِزِ وَالْبُوصِ وَكُلَّ عَمَلِ النَّسَّاجِ. صَانِعِي كُلِّ صَنْعَةٍ وَمُخْتَرِعِي الْمُخْتَرَعَاتِ.', 'خروج 35:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 1, '«فَيَعْمَلُ بَصَلْئِيلُ وَأُهُولِيآبُ وَكُلُّ إِنْسَانٍ حَكِيمِ الْقَلْبِ، قَدْ جَعَلَ فِيهِ الرَّبُّ حِكْمَةً وَفَهْمًا لِيَعْرِفَ أَنْ يَصْنَعَ صَنْعَةً مَّا مِنْ عَمَلِ الْمَقْدِسِ، بِحَسَبِ كُلِّ مَا أَمَرَ الرَّبُّ».', 'خروج 36:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 2, 'فَدَعَا مُوسَى بَصَلْئِيلَ وَأُهُولِيآبَ وَكُلَّ رَجُلٍ حَكِيمِ الْقَلْبِ، قَدْ جَعَلَ الرَّبُّ حِكْمَةً فِي قَلْبِهِ، كُلَّ مَنْ أَنْهَضَهُ قَلْبُهُ أَنْ يَتَقَدَّمَ إِلَى الْعَمَلِ لِيَصْنَعَهُ.', 'خروج 36:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 3, 'فَأَخَذُوا مِنْ قُدَّامِ مُوسَى كُلَّ التَّقْدِمَةِ الَّتِي جَاءَ بِهَا بَنُو إِسْرَائِيلَ لِصَنْعَةِ عَمَلِ الْمَقْدِسِ لِكَيْ يَصْنَعُوهُ. وَهُمْ جَاءُوا إِلَيْهِ أَيْضًا بِشَيْءٍ تَبَرُّعًا كُلَّ صَبَاحٍ.', 'خروج 36:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 4, 'فَجَاءَ كُلُّ الْحُكَمَاءِ الصَّانِعِينَ كُلَّ عَمَلِ الْمَقْدِسِ، كُلُّ وَاحِدٍ مِنْ عَمَلِهِ الَّذِي هُمْ يَصْنَعُونَهُ.', 'خروج 36:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 5, 'وَكَلَّمُوا مُوسَى قَائِلِينَ׃ «يَجِيءُ الشَّعْبُ بِكَثِيرٍ فَوْقَ حَاجَةِ الْعَمَلِ لِلصَّنْعَةِ الَّتِي أَمَرَ الرَّبُّ بِصُنْعِهَا».', 'خروج 36:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 6, 'فَأَمَرَ مُوسَى أَنْ يُنْفِذُوا صَوْتًا فِي الْمَحَلَّةِ قَائِلِينَ׃ «لَا يَصْنَعْ رَجُلٌ أَوِ امْرَأَةٌ عَمَلًا أَيْضًا لِتَقْدِمَةِ الْمَقْدِسِ». فَامْتَنَعَ الشَّعْبُ عَنِ الْجَلَبِ.', 'خروج 36:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 7, 'وَالْمَوَادُّ كَانَتْ كِفَايَتَهُمْ لِكُلِّ الْعَمَلِ لِيَصْنَعُوهُ وَأَكْثَرَ.', 'خروج 36:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 8, 'فَصَنَعُوا كُلُّ حَكِيمِ قَلْبٍ مِنْ صَانِعِي الْعَمَلِ الْمَسْكَنَ عَشَرَ شُقَقٍ مِنْ بُوصٍ مَبْرُومٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوانٍ وَقِرْمِزٍ بِكَرُوبِيمَ، صَنْعَةَ حَائِكٍ حَاذِقٍ صَنَعَهَا.', 'خروج 36:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 9, 'طُولُ الشُّقَّةِ الْوَاحِدَةِ ثَمَانٍ وَعِشْرُونَ ذِرَاعًا، وَعَرْضُ الشُّقَّةِ الْوَاحِدَةِ أَرْبَعُ أَذْرُعٍ. قِيَاسًا وَاحِدًا لِجَمِيعِ الشُّقَقِ.', 'خروج 36:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 10, 'وَوَصَلَ خَمْسًا مِنَ الشُّقَقِ بَعْضَهَا بِبَعْضٍ. وَوَصَلَ خَمْسًا مِنَ الشُّقَقِ بَعْضَهَا بِبَعْضٍ.', 'خروج 36:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 11, 'وَصَنَعَ عُرًى مِنْ أَسْمَانْجُونِيٍّ عَلَى حَاشِيَةِ الشُّقَّةِ الْوَاحِدَةِ فِي الطَّرَفِ مِنَ الْمُوَصَّلِ الْوَاحِدِ. كَذَلِكَ صَنَعَ فِي حَاشِيَةِ الشُّقَّةِ الطَّرَفِيَّةِ مِنَ الْمُوَصَّلِ الثَّانِي.', 'خروج 36:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 12, 'خَمْسِينَ عُرْوَةً صَنَعَ فِي الشُّقَّةِ الْوَاحِدَةِ، وَخَمْسِينَ عُرْوَةً صَنَعَ فِي طَرَفِ الشُّقَّةِ الَّذِي فِي الْمُوَصَّلِ الثَّانِي. مُقَابِلَةً كَانَتِ الْعُرَى بَعْضُهَا لِبَعْضٍ.', 'خروج 36:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 13, 'وَصَنَعَ خَمْسِينَ شِظَاظًا مِنْ ذَهَبٍ، وَوَصَلَ الشُّقَّتَيْنِ بَعْضَهُمَا بِبَعْضٍ بِالْأَشِظَّةِ، فَصَارَ الْمَسْكَنُ وَاحِدًا.', 'خروج 36:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 14, 'وَصَنَعَ شُقَقًا مِنْ شَعْرِ مِعْزًى خَيْمَةً فَوْقَ الْمَسْكَنِ. إِحْدَى عَشْرَةَ شُقَّةً صَنَعَهَا.', 'خروج 36:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 15, 'طُولُ الشُّقَّةِ الْوَاحِدَةِ ثَلَاثُونَ ذِرَاعًا، وَعَرْضُ الشُّقَّةِ الْوَاحِدَةِ أَرْبَعُ أَذْرُعٍ. قِيَاسًا وَاحِدًا لِلْإِحْدَى عَشْرَةَ شُقَّةً.', 'خروج 36:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 16, 'وَوَصَلَ خَمْسًا مِنَ الشُّقَقِ وَحْدَهَا، وَسِتًّا مِنَ الشُّقَقِ وَحْدَهَا.', 'خروج 36:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 17, 'وَصَنَعَ خَمْسِينَ عُرْوَةً عَلَى حَاشِيَةِ الشُّقَّةِ الطَّرَفِيَّةِ مِنَ الْمُوَصَّلِ الْوَاحِدِ. وَصَنَعَ خَمْسِينَ عُرْوَةً عَلَى حَاشِيَةِ الشُّقَّةِ الْمُوَصَّلَةِ الثَّانِيَةِ.', 'خروج 36:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 18, 'وَصَنَعَ خَمْسِينَ شِظَاظًا مِنْ نُحَاسٍ لِيَصِلَ الْخَيْمَةَ لِتَصِيرَ وَاحِدَةً.', 'خروج 36:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 19, 'وَصَنَعَ غِطَاءً لِلْخَيْمَةِ مِنْ جُلُودِ كِبَاشٍ مُحَمَّرَةً، وَغِطَاءً مِنْ جُلُودِ تُخَسٍ مِنْ فَوْقُ.', 'خروج 36:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 20, 'وَصَنَعَ الْأَلْوَاحَ لِلْمَسْكَنِ مِنْ خَشَبِ السَّنْطِ قَائِمَةً.', 'خروج 36:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 21, 'طُولُ اللَّوْحِ عَشْرُ أَذْرُعٍ، وَعَرْضُ اللَّوْحِ الْوَاحِدِ ذِرَاعٌ وَنِصْفٌ.', 'خروج 36:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 22, 'وَلِلَّوْحِ الْوَاحِدِ رِجْلَانِ، مَقْرُونَةٌ إِحْدَاهُمَا بِالْأُخْرَى. هَكَذَا صَنَعَ لِجَمِيعِ أَلْوَاحِ الْمَسْكَنِ.', 'خروج 36:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 23, 'وَصَنَعَ الْأَلْوَاحَ لِلْمَسْكَنِ عِشْرِينَ لَوْحًا إِلَى جِهَةِ الْجَنُوبِ نَحْوَ التَّيْمَنِ.', 'خروج 36:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 24, 'وَصَنَعَ أَرْبَعِينَ قَاعِدَةً مِنْ فِضَّةٍ تَحْتَ الْعِشْرِينَ لَوْحًا، تَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ لِرِجْلَيْهِ، وَتَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ لِرِجْلَيْهِ.', 'خروج 36:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 25, 'وَلِجَانِبِ الْمَسْكَنِ الثَّانِي إِلَى جِهَةِ الشِّمَالِ صَنَعَ عِشْرِينَ لَوْحًا،', 'خروج 36:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 26, 'وَأَرْبَعِينَ قَاعِدَةً لَهَا مِنْ فِضَّةٍ. تَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ، وَتَحْتَ اللَّوْحِ الْوَاحِدِ قَاعِدَتَانِ.', 'خروج 36:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 27, 'وَلِمُؤَخَّرِ الْمَسْكَنِ نَحْوَ الْغَرْبِ صَنَعَ سِتَّةَ أَلْوَاحٍ.', 'خروج 36:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 28, 'وَصَنَعَ لَوْحَيْنِ لِزَاوِيَتَيِ الْمَسْكَنِ فِي الْمُؤَخَّرِ.', 'خروج 36:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 29, 'وَكَانَا مُزْدَوِجَيْنِ مِنْ أَسْفَلُ، وَعَلَى سَوَاءٍ كَانَا مُزْدَوِجَيْنِ إِلَى رَأْسِهِ إِلَى الْحَلْقَةِ الْوَاحِدَةِ. هَكَذَا صَنَعَ لِكِلْتَيْهِمَا، لِكِلْتَا الزَّاوِيَتَيْنِ.', 'خروج 36:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 30, 'فَكَانَتْ ثَمَانِيَةَ أَلْوَاحٍ وَقَوَاعِدُهَا مِنْ فِضَّةٍ سِتَّ عَشْرَةَ قَاعِدَةً. قَاعِدَتَيْنِ قَاعِدَتَيْنِ تَحْتَ اللَّوْحِ الْوَاحِدِ.', 'خروج 36:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 31, 'وَصَنَعَ عَوَارِضَ مِنْ خَشَبِ السَّنْطِ، خَمْسًا لِأَلْوَاحِ جَانِبِ الْمَسْكَنِ الْوَاحِدِ،', 'خروج 36:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 32, 'وَخَمْسَ عَوَارِضَ لِأَلْوَاحِ جَانِبِ الْمَسْكَنِ الثَّانِي، وَخَمْسَ عَوَارِضَ لِأَلْوَاحِ الْمَسْكَنِ فِي الْمُؤَخَّرِ نَحْوَ الْغَرْبِ.', 'خروج 36:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 33, 'وَصَنَعَ الْعَارِضَةَ الْوُسْطَى لِتَنْفُذَ فِي وَسَطِ الْأَلْوَاحِ مِنَ الطَّرَفِ إِلَى الطَّرَفِ.', 'خروج 36:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 34, 'وَغَشَّى الْأَلْوَاحَ بِذَهَبٍ. وَصَنَعَ حَلَقَاتِهَا مِنْ ذَهَبٍ بُيُوتًا لِلْعَوَارِضِ، وَغَشَّى الْعَوَارِضَ بِذَهَبٍ.', 'خروج 36:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 35, 'وَصَنَعَ الْحِجَابَ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ. صَنْعَةَ حَائِكٍ حَاذِقٍ صَنَعَهُ بِكَرُوبِيمَ.', 'خروج 36:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 36, 'وَصَنَعَ لَهُ أَرْبَعَةَ أَعْمِدَةٍ مِنْ سَنْطٍ، وَغَشَّاهَا بِذَهَبٍ. رُزَزُهَا مِنْ ذَهَبٍ. وَسَبَكَ لَهَا أَرْبَعَ قَوَاعِدَ مِنْ فِضَّةٍ.', 'خروج 36:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 37, 'وَصَنَعَ سَجْفًا لِمَدْخَلِ الْخَيْمَةِ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ صَنْعَةَ الطَّرَّازِ.', 'خروج 36:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 36, 38, 'وَأَعْمِدَتَهُ خَمْسَةً وَرُزَزَهَا. وَغَشَّى رُؤُوسَهَا وَقُضْبَانَهَا بِذَهَبٍ، وَقَوَاعِدَهَا خَمْسًا مِنْ نُحَاسٍ.', 'خروج 36:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 1, 'وَصَنَعَ بَصَلْئِيلُ التَّابُوتَ مِنْ خَشَبِ السَّنْطِ، طُولُهُ ذِرَاعَانِ وَنِصْفٌ، وَعَرْضُهُ ذِرَاعٌ وَنِصْفٌ، وَارْتِفَاعُهُ ذِرَاعٌ وَنِصْفٌ.', 'خروج 37:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 2, 'وَغَشَّاهُ بِذَهَبٍ نَقِيٍّ مِنْ دَاخِلٍ وَمِنْ خَارِجٍ. وَصَنَعَ لَهُ إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهِ.', 'خروج 37:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 3, 'وَسَبَكَ لَهُ أَرْبَعَ حَلَقَاتٍ مِنْ ذَهَبٍ عَلَى أَرْبَعِ قَوَائِمِهِ. عَلَى جَانِبِهِ الْوَاحِدِ حَلْقَتَانِ، وَعَلَى جَانِبِهِ الثَّانِي حَلْقَتَانِ.', 'خروج 37:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 4, 'وَصَنَعَ عَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَغَشَّاهُمَا بِذَهَبٍ.', 'خروج 37:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 5, 'وَأَدْخَلَ الْعَصَوَيْنِ فِي الْحَلَقَاتِ عَلَى جَانِبَيِ التَّابُوتِ، لِحَمْلِ التَّابُوتِ.', 'خروج 37:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 6, 'وَصَنَعَ غِطَاءً مِنْ ذَهَبٍ نَقِيٍّ، طُولُهُ ذِرَاعَانِ وَنِصْفٌ، وَعَرْضُهُ ذِرَاعٌ وَنِصْفٌ.', 'خروج 37:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 7, 'وَصَنَعَ كَرُوبَيْنِ مِنْ ذَهَبٍ صَنْعَةَ الْخِرَاطَةِ، صَنَعَهُمَا عَلَى طَرَفَيِ الْغِطَاءِ.', 'خروج 37:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 8, 'كَرُوبًا وَاحِدًا عَلَى الطَّرَفِ مِنْ هُنَا، وَكَرُوبًا وَاحِدًا عَلَى الطَّرَفِ مِنْ هُنَاكَ. مِنَ الْغِطَاءِ صَنَعَ الْكَرُوبَيْنِ عَلَى طَرَفَيْهِ.', 'خروج 37:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 9, 'وَكَانَ الْكَرُوبَانِ بَاسِطَيْنِ أَجْنِحَتَهُمَا إِلَى فَوْقُ، مُظَلِّلَيْنِ بِأَجْنِحَتِهِمَا فَوْقَ الْغِطَاءِ، وَوَجْهَاهُمَا كُلُّ الْوَاحِدِ إِلَى الْآخَرِ. نَحْوَ الْغِطَاءِ كَانَ وَجْهَا الْكَرُوبَيْنِ.', 'خروج 37:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 10, 'وَصَنَعَ الْمَائِدَةَ مِنْ خَشَبِ السَّنْطِ، طُولُهَا ذِرَاعَانِ، وَعَرْضُهَا ذِرَاعٌ، وَارْتِفَاعُهَا ذِرَاعٌ وَنِصْفٌ.', 'خروج 37:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 11, 'وَغَشَّاهَا بِذَهَبٍ نَقِيٍّ، وَصَنَعَ لَهَا إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهَا.', 'خروج 37:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 12, 'وَصَنَعَ لَهَا حَاجِبًا عَلَى شِبْرٍ حَوَالَيْهَا، وَصَنَعَ لِحَاجِبِهَا إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهَا.', 'خروج 37:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 13, 'وَسَبَكَ لَهَا أَرْبَعَ حَلَقَاتٍ مِنْ ذَهَبٍ، وَجَعَلَ الْحَلَقَاتِ عَلَى الزَّوَايَا الْأَرْبَعِ الَّتِي لِقَوَائِمِهَا الْأَرْبَعِ.', 'خروج 37:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 14, 'عِنْدَ الْحَاجِبِ كَانَتِ الْحَلَقَاتُ بُيُوتًا لِلْعَصَوَيْنِ لِحَمْلِ الْمَائِدَةِ.', 'خروج 37:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 15, 'وَصَنَعَ الْعَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ، وَغَشَّاهُمَا بِذَهَبٍ لِحَمْلِ الْمَائِدَةِ.', 'خروج 37:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 16, 'وَصَنَعَ الْأَوَانِيَ الَّتِي عَلَى الْمَائِدَةِ، صِحَافَهَا وَصُحُونَهَا وَجَامَاتِهَا وَكَأْسَاتِهَا الَّتِي يُسْكَبُ بِهَا مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 37:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 17, 'وَصَنَعَ الْمَنَارَةَ مِنْ ذَهَبٍ نَقِيٍّ. صَنْعَةَ الْخِرَاطَةِ صَنَعَ الْمَنَارَةَ، قَاعِدَتَهَا وَسَاقَهَا. كَانَتْ كَأْسَاتُهَا وَعُجَرُهَا وَأَزْهَارُهَا مِنْهَا.', 'خروج 37:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 18, 'وَسِتُّ شُعَبٍ خَارِجَةٌ مِنْ جَانِبَيْهَا. مِنْ جَانِبِهَا الْوَاحِدِ ثَلَاثُ شُعَبِ مَنَارَةٍ، وَمِنْ جَانِبِهَا الثَّانِي ثَلَاثُ شُعَبِ مَنَارَةٍ.', 'خروج 37:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 19, 'فِي الشُّعْبَةِ الْوَاحِدَةِ ثَلَاثُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجْرَةٍ وَزَهْرٍ، وَفِي الشُّعْبَةِ الثَّانِيَةِ ثَلَاثُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجْرَةٍ وَزَهْرٍ، وَهَكَذَا إِلَى السِّتِّ الشُّعَبِ الْخَارِجَةِ مِنَ الْمَنَارَةِ.', 'خروج 37:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 20, 'وَفِي الْمَنَارَةِ أَرْبَعُ كَأْسَاتٍ لَوْزِيَّةٍ بِعُجَرِهَا وَأَزْهَارِهَا.', 'خروج 37:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 21, 'وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ، وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ، وَتَحْتَ الشُّعْبَتَيْنِ مِنْهَا عُجْرَةٌ. إِلَى السِّتِّ الشُّعَبِ الْخَارِجَةِ مِنْهَا.', 'خروج 37:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 22, 'كَانَتْ عُجَرُهَا وَشُعَبُهَا مِنْهَا، جَمِيعُهَا خِرَاطَةٌ وَاحِدَةٌ مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 37:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 23, 'وَصَنَعَ سُرُجَهَا سَبْعَةً، وَمَلَاقِطَهَا وَمَنَافِضَهَا مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 37:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 24, 'مِنْ وَزْنَةِ ذَهَبٍ نَقِيٍّ صَنَعَهَا وَجَمِيعَ أَوَانِيهَا.', 'خروج 37:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 25, 'وَصَنَعَ مَذْبَحَ الْبَخُورِ مِنْ خَشَبِ السَّنْطِ، طُولُهُ ذِرَاعٌ، وَعَرْضُهُ ذِرَاعٌ، مُرَبَّعًا. وَارْتِفَاعُهُ ذِرَاعَانِ. مِنْهُ كَانَتْ قُرُونُهُ.', 'خروج 37:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 26, 'وَغَشَّاهُ بِذَهَبٍ نَقِيٍّ׃ سَطْحَهُ وَحِيطَانَهُ حَوَالَيْهِ وَقُرُونَهُ. وَصَنَعَ لَهُ إِكْلِيلًا مِنْ ذَهَبٍ حَوَالَيْهِ.', 'خروج 37:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 27, 'وَصَنَعَ لَهُ حَلْقَتَيْنِ مِنْ ذَهَبٍ تَحْتَ إِكْلِيلِهِ عَلَى جَانِبَيْهِ، عَلَى الْجَانِبَيْنِ بَيْتَيْنِ لِعَصَوَيْنِ لِحَمْلِهِ بِهِمَا.', 'خروج 37:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 28, 'وَصَنَعَ الْعَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَغَشَّاهُمَا بِذَهَبٍ.', 'خروج 37:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 37, 29, 'وَصَنَعَ دُهْنَ الْمَسْحَةِ مُقَدَّسًا، وَالْبَخُورَ الْعَطِرَ نَقِيًّا صَنْعَةَ الْعَطَّارِ.', 'خروج 37:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 1, 'وَصَنَعَ مَذْبَحَ الْمُحْرَقَةِ مِنْ خَشَبِ السَّنْطِ، طُولُهُ خَمْسُ أَذْرُعٍ، وَعَرْضُهُ خَمْسُ أَذْرُعٍ، مُرَبَّعًا. وَارْتِفَاعُهُ ثَلَاثُ أَذْرُعٍ.', 'خروج 38:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 2, 'وَصَنَعَ قُرُونَهُ عَلَى زَوَايَاهُ الْأَرْبَعِ. مِنْهُ كَانَتْ قُرُونُهُ. وَغَشَّاهُ بِنُحَاسٍ.', 'خروج 38:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 3, 'وَصَنَعَ جَمِيعَ آنِيَةِ الْمَذْبَحِ׃ الْقُدُورَ وَالرُّفُوشَ وَالْمَرَاكِنَ وَالْمَنَاشِلَ وَالْمَجَامِرَ، جَمِيعَ آنِيَتِهِ صَنَعَهَا مِنْ نُحَاسٍ.', 'خروج 38:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 4, 'وَصَنَعَ لِلْمَذْبَحِ شُبَّاكَةً صَنْعَةَ الشَّبَكَةِ مِنْ نُحَاسٍ، تَحْتَ حَاجِبِهِ مِنْ أَسْفَلُ إِلَى نِصْفِهِ.', 'خروج 38:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 5, 'وَسَبَكَ أَرْبَعَ حَلَقَاتٍ فِي الْأَرْبَعَةِ الْأَطْرَافِ لِشُبَّاكَةِ النُّحَاسِ بُيُوتًا لِلْعَصَوَيْنِ.', 'خروج 38:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 6, 'وَصَنَعَ الْعَصَوَيْنِ مِنْ خَشَبِ السَّنْطِ وَغَشَّاهُمَا بِنُحَاسٍ.', 'خروج 38:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 7, 'وَأَدْخَلَ الْعَصَوَيْنِ فِي الْحَلَقَاتِ عَلَى جَانِبَيِ الْمَذْبَحِ لِحَمْلِهِ بِهِمَا. مُجَوَّفًا صَنَعَهُ مِنْ أَلْوَاحٍ.', 'خروج 38:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 8, 'وَصَنَعَ الْمِرْحَضَةَ مِنْ نُحَاسٍ وَقَاعِدَتَهَا مِنْ نُحَاسٍ. مِنْ مَرَائِي الْمُتَجَنِّدَاتِ اللَّوَاتِي تَجَنَّدْنَ عِنْدَ بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'خروج 38:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 9, 'وَصَنَعَ الدَّارَ׃ إِلَى جِهَةِ الْجَنُوبِ نَحْوَ التَّيْمَنِ، أَسْتَارُ الدَّارِ مِنْ بُوصٍ مَبْرُومٍ مِئَةُ ذِرَاعٍ،', 'خروج 38:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 10, 'أَعْمِدَتُهَا عِشْرُونَ، وَقَوَاعِدُهَا عِشْرُونَ مِنْ نُحَاسٍ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ.', 'خروج 38:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 11, 'وَإِلَى جِهَةِ الشِّمَالِ، مِئَةُ ذِرَاعٍ، أَعْمِدَتُهَا عِشْرُونَ وَقَوَاعِدُهَا عِشْرُونَ مِنْ نُحَاسٍ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ.', 'خروج 38:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 12, 'وَإِلَى جِهَةِ الْغَرْبِ أَسْتَارٌ، خَمْسُونَ ذِرَاعًا، أَعْمِدَتُهَا عَشَرَةٌ وَقَوَاعِدُهَا عَشْرٌ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ.', 'خروج 38:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 13, 'وَإِلَى جِهَةِ الشَّرْقِ نَحْوَ الشُّرُوقِ، خَمْسُونَ ذِرَاعًا.', 'خروج 38:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 14, 'لِلْجَانِبِ الْوَاحِدِ أَسْتَارٌ خَمْسَ عَشْرَةَ ذِرَاعًا، أَعْمِدَتُهَا ثَلَاثَةٌ وَقَوَاعِدُهَا ثَلَاثٌ.', 'خروج 38:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 15, 'وَلِلْجَانِبِ الثَّانِي مِنْ بَابِ الدَّارِ إِلَى هُنَا وَإِلَى هُنَا أَسْتَارٌ خَمْسَ عَشَرَةَ ذِرَاعًا، أَعْمِدَتُهَا ثَلَاثَةٌ وَقَوَاعِدُهَا ثَلَاثٌ.', 'خروج 38:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 16, 'جَمِيعُ أَسْتَارِ الدَّارِ حَوَالَيْهَا مِنْ بُوصٍ مَبْرُومٍ،', 'خروج 38:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 17, 'وَقَوَاعِدُ الْأَعْمِدَةِ مِنْ نُحَاسٍ. رُزَزُ الْأَعْمِدَةِ وَقُضْبَانُهَا مِنْ فِضَّةٍ وَتَغْشِيَةُ رُؤُوسِهَا مِنْ فِضَّةٍ وَجَمِيعُ أَعْمِدَةِ الدَّارِ مَوْصُولَةٌ بِقُضْبَانٍ مِنْ فِضَّةٍ.', 'خروج 38:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 18, 'وَسَجْفُ بَابِ الدَّارِ صَنْعَةَ الطَّرَّازِ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ، وَطُولُهُ عِشْرُونَ ذِرَاعًا، وَارْتِفَاعُهُ بِالْعَرْضِ خَمْسُ أَذْرُعٍ بِسَوِيَّةِ أَسْتَارِ الدَّارِ،', 'خروج 38:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 19, 'وَأَعْمِدَتُهَا أَرْبَعَةٌ، وَقَوَاعِدُهَا أَرْبَعٌ مِنْ نُحَاسٍ. رُزَزُهَا مِنْ فِضَّةٍ، وَتَغْشِيَةُ رُؤُوسِهَا وَقُضْبَانِهَا مِنْ فِضَّةٍ.', 'خروج 38:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 20, 'وَجَمِيعُ أَوْتَادِ الْمَسْكَنِ وَالدَّارِ حَوَالَيْهَا مِنْ نُحَاسٍ.', 'خروج 38:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 21, 'هَذَا هُوَ الْمَحْسُوبُ لِلْمَسْكَنِ، مَسْكَنِ الشَّهَادَةِ الَّذِي حُسِبَ بِمُوجَبِ أَمْرِ مُوسَى بِخِدْمَةِ اللَّاوِيِّينَ عَلَى يَدِ إِيثَامَارَ بْنِ هَارُونَ الْكَاهِنِ.', 'خروج 38:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 22, 'وَبَصَلْئِيلُ بْنُ أُورِي بْنِ حُورَ مِنْ سِبْطِ يَهُوذَا صَنَعَ كُلَّ مَا أَمَرَ بِهِ الرَّبُّ مُوسَى.', 'خروج 38:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 23, 'وَمَعَهُ أُهُولِيآبُ بْنُ أَخِيسَامَاكَ مِنْ سِبْطِ دَانَ، نَقَّاشٌ وَمُوَشٍّ وَطَرَّازٌ بِالْأَسْمَانْجُونِيِّ وَالْأُرْجُوَانِ وَالْقِرْمِزِ وَالْبُوصِ.', 'خروج 38:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 24, 'كُلُّ الذَّهَبِ الْمَصْنُوعِ لِلْعَمَلِ فِي جَمِيعِ عَمَلِ الْمَقْدِسِ، وَهُوَ ذَهَبُ التَّقْدِمَةِ׃ تِسْعٌ وَعِشْرُونَ وَزْنَةً وَسَبْعُ مِئَةِ شَاقِلٍ وَثَلَاثُونَ شَاقِلًا بِشَاقِلِ الْمَقْدِسِ.', 'خروج 38:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 25, 'وَفِضَّةُ الْمَعْدُودِينَ مِنَ الْجَمَاعَةِ مِئَةُ وَزْنَةٍ وَأَلْفٌ وَسَبْعُ مِئَةِ شَاقِلٍ وَخَمْسَةٌ وَسَبْعُونَ شَاقِلًا بِشَاقِلِ الْمَقْدِسِ.', 'خروج 38:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 26, 'لِلرَّأْسِ نِصْفٌ، نِصْفُ الشَّاقِلِ بِشَاقِلِ الْمَقْدِسِ. لِكُلِّ مَنِ اجْتَازَ إِلَى الْمَعْدُودِينَ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، لِسِتِّ مِئَةِ أَلْفٍ وَثَلَاثَةِ آلَافٍ وَخَمْسِ مِئَةٍ وَخَمْسِينَ.', 'خروج 38:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 27, 'وَكَانَتْ مِئَةُ وَزْنَةٍ مِنَ الْفِضَّةِ لِسَبْكِ قَوَاعِدِ الْمَقْدِسِ وَقَوَاعِدِ الْحِجَابِ. مِئَةُ قَاعِدَةٍ لِلْمِئَةِ وَزْنَةٍ. وَزْنَةٌ لِلْقَاعِدَةِ.', 'خروج 38:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 28, 'وَالْأَلْفُ وَالسَّبْعُ مِئَةِ شَاقِلٍ وَالْخَمْسَةُ وَالسَّبْعُونَ شَاقِلًا صَنَعَ مِنْهَا رُزَزًا لِلْأَعْمِدَةِ وَغَشَّى رُؤُوسَهَا وَوَصَلَهَا بِقُضْبَانٍ.', 'خروج 38:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 29, 'وَنُحَاسُ التَّقْدِمَةِ سَبْعُونَ وَزْنَةً وَأَلْفَانِ وَأَرْبَعُ مِئَةِ شَاقِلٍ.', 'خروج 38:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 30, 'وَمِنْهُ صَنَعَ قَوَاعِدَ بَابِ خَيْمَةِ الِاجْتِمَاعِ وَمَذْبَحَ النُّحَاسِ وَشُبَّاكَةَ النُّحَاسِ الَّتِي لَهُ وَجَمِيعَ آنِيَةِ الْمَذْبَحِ', 'خروج 38:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 38, 31, 'وَقَوَاعِدَ الدَّارِ حَوَالَيْهَا وَقَوَاعِدَ بَابِ الدَّارِ وَجَمِيعَ أَوْتَادِ الْمَسْكَنِ وَجَمِيعَ أَوْتَادِ الدَّارِ حَوَالَيْهَا.', 'خروج 38:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 1, 'وَمِنَ الْأَسْمَانْجُونِيِّ وَالْأُرْجُوَانِ وَالْقِرْمِزِ صَنَعُوا ثِيَابًا مَنْسُوجَةً لِلْخِدْمَةِ فِي الْمَقْدِسِ، وَصَنَعُوا الثِّيَابَ الْمُقَدَّسَةَ الَّتِي لِهَارُونَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 2, 'فَصَنَعَ الرِّدَاءَ مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ.', 'خروج 39:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 3, 'وَمَدُّوا الذَّهَبَ صَفَائِحَ وَقَدُّوهَا خُيُوطًا لِيَصْنَعُوهَا فِي وَسَطِ الْأَسْمَانْجُونِيِّ وَالْأُرْجُوَانِ وَالْقِرْمِزِ وَالْبُوصِ، صَنْعَةَ الْمُوَشِّي.', 'خروج 39:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 4, 'وَصَنَعُوا لَهُ كَتِفَيْنِ مَوْصُولَيْنِ. عَلَى طَرَفَيْهِ اتَّصَلَ.', 'خروج 39:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 5, 'وَزُنَّارُ شَدِّهِ الَّذِي عَلَيْهِ كَانَ مِنْهُ كَصَنْعَتِهِ مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 6, 'وَصَنَعُوا حَجَرَيِ الْجَزْعِ مُحَاطَيْنِ بِطَوْقَيْنِ مِنْ ذَهَبٍ مَنْقُوشَيْنِ نَقْشَ الْخَاتِمِ عَلَى حَسَبِ أَسْمَاءِ بَنِي إِسْرَائِيلَ.', 'خروج 39:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 7, 'وَوَضَعَهُمَا عَلَى كَتِفَيِ الرِّدَاءِ حَجَرَيْ تَذْكَارٍ لِبَنِي إِسْرَائِيلَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 8, 'وَصَنَعَ الصُّدْرَةَ صَنْعَةَ الْمُوَشِّي كَصَنْعَةِ الرِّدَاءِ مِنْ ذَهَبٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ وَبُوصٍ مَبْرُومٍ.', 'خروج 39:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 9, 'كَانَتْ مُرَبَّعَةً. مَثْنِيَّةً صَنَعُوا الصُّدْرَةَ. طُولُهَا شِبْرٌ وَعَرْضُهَا شِبْرٌ مَثْنِيَّةً.', 'خروج 39:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 10, 'وَرَصَّعُوا فِيهَا أَرْبَعَةَ صُفُوفِ حِجَارَةٍ. صَفُّ׃ عَقِيقٌ أَحْمَرُ وَيَاقُوتٌ أَصْفَرُ وَزُمُرُّدٌ، الصَّفُّ الْأَوَّلُ.', 'خروج 39:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 11, 'وَالصَّفُّ الثَّانِي׃ بَهْرَمَانُ وَيَاقُوتٌ أَزْرَقُ وَعَقِيقٌ أَبْيَضُ.', 'خروج 39:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 12, 'وَالصَّفُّ الثَّالِثُ׃ عَيْنُ الْهِرِّ وَيَشْمٌ وَجَمَسْتُ.', 'خروج 39:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 13, 'وَالصَّفُّ الرَّابِعُ׃ زَبَرْجَدٌ وَجَزْعٌ وَيَشْبٌ. مُحَاطَةٌ بِأَطْوَاقٍ مِنْ ذَهَبٍ فِي تَرْصِيعِهَا.', 'خروج 39:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 14, 'وَالْحِجَارَةُ كَانَتْ عَلَى أَسْمَاءِ بَنِي إِسْرَائِيلَ، اثْنَيْ عَشَرَ عَلَى أَسْمَائِهِمْ كَنَقْشِ الْخَاتِمِ. كُلُّ وَاحِدٍ عَلَى اسْمِهِ لِلِاثْنَيْ عَشَرَ سِبْطًا.', 'خروج 39:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 15, 'وَصَنَعُوا عَلَى الصُّدْرَةِ سَلَاسِلَ مَجْدُولَةً صَنْعَةَ الضَّفْرِ مِنْ ذَهَبٍ نَقِيٍّ.', 'خروج 39:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 16, 'وَصَنَعُوا طَوْقَيْنِ مِنْ ذَهَبٍ وَحَلْقَتَيْنِ مِنْ ذَهَبٍ، وَجَعَلُوا الْحَلْقَتَيْنِ عَلَى طَرَفَيِ الصُّدْرَةِ.', 'خروج 39:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 17, 'وَجَعَلُوا ضَفِيرَتَيِ الذَّهَبِ فِي الْحَلْقَتَيْنِ عَلَى طَرَفَيِ الصُّدْرَةِ.', 'خروج 39:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 18, 'وَطَرَفَا الضَّفِيرَتَيْنِ جَعَلُوهُمَا فِي الطَّوْقَيْنِ، وَجَعَلُوهُمَا عَلَى كَتِفَيِ الرِّدَاءِ إِلَى قُدَّامِهِ.', 'خروج 39:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 19, 'وَصَنَعُوا حَلْقَتَيْنِ مِنْ ذَهَبٍ وَوَضَعُوهُمَا عَلَى طَرَفَيِ الصُّدْرَةِ. عَلَى حَاشِيَتِهَا الَّتِي إِلَى جِهَةِ الرِّدَاءِ مِنْ دَاخِلٍ.', 'خروج 39:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 20, 'وَصَنَعُوا حَلْقَتَيْنِ مِنْ ذَهَبٍ وَجَعَلُوهُمَا عَلَى كَتِفَيِ الرِّدَاءِ مِنْ أَسْفَلُ مِنْ قُدَّامِهِ عِنْدَ وَصْلِهِ فَوْقَ زُنَّارِ الرِّدَاءِ.', 'خروج 39:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 21, 'وَرَبَطُوا الصُّدْرَةَ بِحَلْقَتَيْهَا إِلَى حَلْقَتَيِ الرِّدَاءِ بِخَيْطٍ مِنْ أَسْمَانْجُونِيٍّ لِيَكُونَ عَلَى زُنَّارِ الرِّدَاءِ، وَلَا تُنْزَعُ الصُّدْرَةُ عَنِ الرِّدَاءِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 22, 'وَصَنَعَ جُبَّةَ الرِّدَاءِ صَنْعَةَ النَّسَّاجِ، كُلَّهَا مِنْ أَسْمَانْجُونِيٍّ.', 'خروج 39:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 23, 'وَفَتْحَةُ الْجُبَّةِ فِي وَسَطِهَا كَفَتْحَةِ الدِّرْعِ، وَلِفَتْحَتِهَا حَاشِيَةٌ حَوَالَيْهَا. لَا تَنْشَقُّ.', 'خروج 39:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 24, 'وَصَنَعُوا عَلَى أَذْيَالِ الْجُبَّةِ رُمَّانَاتٍ مِنْ أَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ مَبْرُومٍ.', 'خروج 39:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 25, 'وَصَنَعُوا جَلَاجِلَ مِنْ ذَهَبٍ نَقِيٍّ، وَجَعَلُوا الْجَلَاجِلَ فِي وَسَطِ الرُّمَّانَاتِ عَلَى أَذْيَالِ الْجُبَّةِ حَوَالَيْهَا فِي وَسَطِ الرُّمَّانَاتِ.', 'خروج 39:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 26, 'جُلْجُلٌ وَرُمَّانَةٌ. جُلْجُلٌ وَرُمَّانَةٌ. عَلَى أَذْيَالِ الْجُبَّةِ حَوَالَيْهَا لِلْخِدْمَةِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 27, 'وَصَنَعُوا الْأَقْمِصَةَ مِنْ بُوصٍ صَنْعَةَ النَّسَّاجِ لِهَارُونَ وَبَنِيهِ.', 'خروج 39:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 28, 'وَالْعِمَامَةَ مِنْ بُوصٍ، وَعَصَائِبَ الْقَلَانِسِ مِنْ بُوصٍ، وَسَرَاوِيلَ الْكَتَّانِ مِنْ بُوصٍ مَبْرُومٍ.', 'خروج 39:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 29, 'وَالْمِنْطَقَةَ مِنْ بُوصٍ مَبْرُومٍ وَأَسْمَانْجُونِيٍّ وَأُرْجُوَانٍ وَقِرْمِزٍ صَنْعَةَ الطَّرَّازِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 30, 'وَصَنَعُوا صَفِيحَةَ الْإِكْلِيلِ الْمُقَدَّسِ مِنْ ذَهَبٍ نَقِيٍّ، وَكَتَبُوا عَلَيْهَا كِتَابَةَ نَقْشِ الْخَاتِمِ׃ «قُدْسٌ لِلرَّبِّ».', 'خروج 39:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 31, 'وَجَعَلُوا عَلَيْهَا خَيْطَ أَسْمَانْجُونِيٍّ لِتُجْعَلَ عَلَى الْعِمَامَةِ مِنْ فَوْقُ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 39:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 32, 'فَكَمُلَ كُلُّ عَمَلِ مَسْكَنِ خَيْمَةِ الِاجْتِمَاعِ. وَصَنَعَ بَنُو إِسْرَائِيلَ بِحَسَبِ كُلِّ مَا أَمَرَ الرَّبُّ مُوسَى. هَكَذَا صَنَعُوا.', 'خروج 39:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 33, 'وَجَاءُوا إِلَى مُوسَى بِالْمَسْكَنِ׃ الْخَيْمَةِ وَجَمِيعِ أَوَانِيهَا، أَشِظَّتِهَا وَأَلْوَاحِهَا وَعَوَارِضِهَا وَأَعْمِدَتِهَا وَقَوَاعِدِهَا،', 'خروج 39:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 34, 'وَالْغِطَاءِ مِنْ جُلُودِ الْكِبَاشِ الْمُحَمَّرَةِ، وَالْغِطَاءِ مِنْ جُلُودِ التُّخَسِ، وَحِجَابِ السَّجْفِ،', 'خروج 39:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 35, 'وَتَابُوتِ الشَّهَادَةِ وَعَصَوَيْهِ، وَالْغِطَاءِ،', 'خروج 39:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 36, 'وَالْمَائِدَةِ وَكُلِّ آنِيَتِهَا، وَخُبْزِ الْوُجُوهِ،', 'خروج 39:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 37, 'وَالْمَنَارَةِ الطَّاهِرَةِ وَسُرُجِهَا׃ السُّرُجِ لِلتَّرْتِيبِ، وَكُلِّ آنِيَتِهَا وَالزَّيْتِ لِلضَّوْءِ،', 'خروج 39:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 38, 'وَمَذْبَحِ الذَّهَبِ، وَدُهْنِ الْمَسْحَةِ، وَالْبَخُورِ الْعَطِرِ، وَالسَّجْفِ لِمَدْخَلِ الْخَيْمَةِ،', 'خروج 39:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 39, 'وَمَذْبَحِ النُّحَاسِ، وَشُبَّاكَةِ النُّحَاسِ الَّتِي لَهُ وَعَصَوَيْهِ وَكُلِّ آنِيَتِهِ، وَالْمِرْحَضَةِ وَقَاعِدَتِهَا،', 'خروج 39:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 40, 'وَأَسْتَارِ الدَّارِ وَأَعْمِدَتِهَا وَقَوَاعِدِهَا، وَالسَّجْفِ لِبَابِ الدَّارِ وَأَطْنَابِهَا وَأَوْتَادِهَا، وَجَمِيعِ أَوَانِي خِدْمَةِ الْمَسْكَنِ لِخَيْمَةِ الِاجْتِمَاعِ،', 'خروج 39:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 41, 'وَالثِّيَابِ الْمَنْسُوجَةِ لِلْخِدْمَةِ فِي الْمَقْدِسِ، وَالثِّيَابِ الْمُقَدَّسَةِ لِهَارُونَ الْكَاهِنِ وَثِيَابِ بَنِيهِ لِلْكَهَانَةِ.', 'خروج 39:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 42, 'بِحَسَبِ كُلِّ مَا أَمَرَ الرَّبُّ مُوسَى هَكَذَا صَنَعَ بَنُو إِسْرَائِيلَ كُلَّ الْعَمَلِ.', 'خروج 39:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 39, 43, 'فَنَظَرَ مُوسَى جَمِيعَ الْعَمَلِ، وَإِذَا هُمْ قَدْ صَنَعُوهُ كَمَا أَمَرَ الرَّبُّ. هَكَذَا صَنَعُوا. فَبَارَكَهُمْ مُوسَى.', 'خروج 39:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'خروج 40:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 2, '«فِي الشَّهْرِ الْأَوَّلِ، فِي الْيَوْمِ الْأَوَّلِ مِنَ الشَّهْرِ، تُقِيمُ مَسْكَنَ خَيْمَةِ الِاجْتِمَاعِ،', 'خروج 40:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 3, 'وَتَضَعُ فِيهِ تَابُوتَ الشَّهَادَةِ. وَتَسْتُرُ التَّابُوتَ بِالْحِجَابِ.', 'خروج 40:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 4, 'وَتُدْخِلُ الْمَائِدَةَ وَتُرَتِّبُ تَرْتِيبَهَا. وَتُدْخِلُ الْمَنَارَةَ وَتُصْعِدُ سُرُجَهَا.', 'خروج 40:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 5, 'وَتَجْعَلُ مَذْبَحَ الذَّهَبِ لِلْبَخُورِ أَمَامَ تَابُوتِ الشَّهَادَةِ. وَتَضَعُ سَجْفَ الْبَابِ لِلْمَسْكَنِ.', 'خروج 40:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 6, 'وَتَجْعَلُ مَذْبَحَ الْمُحْرَقَةِ قُدَّامَ بَابِ مَسْكَنِ خَيْمَةِ الِاجْتِمَاعِ.', 'خروج 40:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 7, 'وَتَجْعَلُ الْمِرْحَضَةَ بَيْنَ خَيْمَةِ الِاجْتِمَاعِ وَالْمَذْبَحِ، وَتَجْعَلُ فِيهَا مَاءً.', 'خروج 40:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 8, 'وَتَضَعُ الدَّارَ حَوْلَهُنَّ، وَتَجْعَلُ السَّجْفَ لِبَابِ الدَّارِ.', 'خروج 40:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 9, 'وَتَأْخُذُ دُهْنَ الْمَسْحَةِ وَتَمْسَحُ الْمَسْكَنَ وَكُلَّ مَا فِيهِ، وَتُقَدِّسُهُ وَكُلَّ آنِيَتِهِ لِيَكُونَ مُقَدَّسًا.', 'خروج 40:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 10, 'وَتَمْسَحُ مَذْبَحَ الْمُحْرَقَةِ وَكُلَّ آنِيَتِهِ، وَتُقَدِّسُ الْمَذْبَحَ لِيَكُونَ الْمَذْبَحُ قُدْسَ أَقْدَاسٍ.', 'خروج 40:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 11, 'وَتَمْسَحُ الْمِرْحَضَةَ وَقَاعِدَتَهَا وَتُقَدِّسُهَا.', 'خروج 40:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 12, 'وَتُقَدِّمُ هَارُونَ وَبَنِيهِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ وَتَغْسِلُهُمْ بِمَاءٍ.', 'خروج 40:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 13, 'وَتُلْبِسُ هَارُونَ الثِّيَابَ الْمُقَدَّسَةَ وَتَمْسَحُهُ وَتُقَدِّسُهُ لِيَكْهَنَ لِي.', 'خروج 40:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 14, 'وَتُقَدِّمُ بَنِيهِ وَتُلْبِسُهُمْ أَقْمِصَةً.', 'خروج 40:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 15, 'وَتَمْسَحُهُمْ كَمَا مَسَحْتَ أَبَاهُمْ لِيَكْهَنُوا لِي. وَيَكُونُ ذَلِكَ لِتَصِيرَ لَهُمْ مَسْحَتُهُمْ كَهَنُوتًا أَبَدِيًّا فِي أَجْيَالِهِمْ.', 'خروج 40:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 16, 'فَفَعَلَ مُوسَى بِحَسَبِ كُلِّ مَا أَمَرَهُ الرَّبُّ. هَكَذَا فَعَلَ.', 'خروج 40:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 17, 'وَكَانَ فِي الشَّهْرِ الْأَوَّلِ مِنَ السَّنَةِ الثَّانِيَةِ فِي أَوَّلِ الشَّهْرِ أَنَّ الْمَسْكَنَ أُقِيمَ.', 'خروج 40:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 18, 'أَقَامَ مُوسَى الْمَسْكَنَ، وَجَعَلَ قَوَاعِدَهُ وَوَضَعَ أَلْوَاحَهُ وَجَعَلَ عَوَارِضَهُ وَأَقَامَ أَعْمِدَتَهُ.', 'خروج 40:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 19, 'وَبَسَطَ الْخَيْمَةَ فَوْقَ الْمَسْكَنِ، وَوَضَعَ غِطَاءَ الْخَيْمَةِ عَلَيْهَا مِنْ فَوْقُ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 20, 'وَأَخَذَ الشَّهَادَةَ وَجَعَلَهَا فِي التَّابُوتِ، وَوَضَعَ الْعَصَوَيْنِ عَلَى التَّابُوتِ مِنْ فَوْقُ.', 'خروج 40:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 21, 'وَأَدْخَلَ التَّابُوتَ إِلَى الْمَسْكَنِ، وَوَضَعَ حِجَابَ السَّجْفِ وَسَتَرَ تَابُوتَ الشَّهَادَةِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 22, 'وَجَعَلَ الْمَائِدَةَ فِي خَيْمَةِ الِاجْتِمَاعِ فِي جَانِبِ الْمَسْكَنِ نَحْوَ الشِّمَالِ خَارِجَ الْحِجَابِ.', 'خروج 40:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 23, 'وَرَتَّبَ عَلَيْهَا تَرْتِيبَ الْخُبْزِ أَمَامَ الرَّبِّ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 24, 'وَوَضَعَ الْمَنَارَةَ فِي خَيْمَةِ الِاجْتِمَاعِ مُقَابِلَ الْمَائِدَةِ فِي جَانِبِ الْمَسْكَنِ نَحْوَ الْجَنُوبِ.', 'خروج 40:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 25, 'وَأَصْعَدَ السُّرُجَ أَمَامَ الرَّبِّ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 26, 'وَوَضَعَ مَذْبَحَ الذَّهَبِ فِي خَيْمَةِ الِاجْتِمَاعِ قُدَّامَ الْحِجَابِ،', 'خروج 40:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 27, 'وَبَخَّرَ عَلَيْهِ بِبَخُورٍ عَطِرٍ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 28, 'وَوَضَعَ سَجْفَ الْبَابِ لِلْمَسْكَنِ.', 'خروج 40:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 29, 'وَوَضَعَ مَذْبَحَ الْمُحْرَقَةِ عِنْدَ بَابِ مَسْكَنِ خَيْمَةِ الِاجْتِمَاعِ، وَأَصْعَدَ عَلَيْهِ الْمُحْرَقَةَ وَالتَّقْدِمَةَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 30, 'وَوَضَعَ الْمِرْحَضَةَ بَيْنَ خَيْمَةِ الِاجْتِمَاعِ وَالْمَذْبَحِ وَجَعَلَ فِيهَا مَاءً لِلِاغْتِسَالِ،', 'خروج 40:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 31, 'لِيَغْسِلَ مِنْهَا مُوسَى وَهَارُونُ وَبَنُوهُ أَيْدِيَهُمْ وَأَرْجُلَهُمْ.', 'خروج 40:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 32, 'عِنْدَ دُخُولِهِمْ إِلَى خَيْمَةِ الِاجْتِمَاعِ وَعِنْدَ اقْتِرَابِهِمْ إِلَى الْمَذْبَحِ يَغْسِلُونَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'خروج 40:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 33, 'وَأَقَامَ الدَّارَ حَوْلَ الْمَسْكَنِ وَالْمَذْبَحِ وَوَضَعَ سَجْفَ بَابِ الدَّارِ. وَأَكْمَلَ مُوسَى الْعَمَلَ.', 'خروج 40:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 34, 'ثُمَّ غَطَّتِ السَّحَابَةُ خَيْمَةَ الِاجْتِمَاعِ وَمَلَأَ بَهَاءُ الرَّبِّ الْمَسْكَنَ.', 'خروج 40:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 35, 'فَلَمْ يَقْدِرْ مُوسَى أَنْ يَدْخُلَ خَيْمَةَ الِاجْتِمَاعِ، لِأَنَّ السَّحَابَةَ حَلَّتْ عَلَيْهَا وَبَهَاءُ الرَّبِّ مَلَأَ الْمَسْكَنَ.', 'خروج 40:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 36, 'وَعِنْدَ ارْتِفَاعِ السَّحَابَةِ عَنِ الْمَسْكَنِ كَانَ بَنُو إِسْرَائِيلَ يَرْتَحِلُونَ فِي جَمِيعِ رِحْلَاتِهِمْ.', 'خروج 40:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 37, 'وَإِنْ لَمْ تَرْتَفِعِ السَّحَابَةُ لَا يَرْتَحِلُونَ إِلَى يَوْمِ ارْتِفَاعِهَا،', 'خروج 40:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'خروج', 40, 38, 'لِأَنَّ سَحَابَةَ الرَّبِّ كَانَتْ عَلَى الْمَسْكَنِ نَهَارًا. وَكَانَتْ فِيهَا نَارٌ لَيْلًا أَمَامَ عُيُونِ كُلِّ بَيْتِ إِسْرَائِيلَ فِي جَمِيعِ رِحْلَاتِهِمْ.', 'خروج 40:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 1, 'وَدَعَا الرَّبُّ مُوسَى وَكَلَّمَهُ مِنْ خَيْمَةِ الِاجْتِمَاعِ قَائِلًا׃', 'لاويين 1:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ إِذَا قَرَّبَ إِنْسَانٌ مِنْكُمْ قُرْبَانًا لِلرَّبِّ مِنَ الْبَهَائِمِ، فَمِنَ الْبَقَرِ وَالْغَنَمِ تُقَرِّبُونَ قَرَابِينَكُمْ.', 'لاويين 1:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 3, 'إِنْ كَانَ قُرْبَانُهُ مُحْرَقَةً مِنَ الْبَقَرِ، فَذَكَرًا صَحِيحًا يُقَرِّبُهُ. إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ يُقَدِّمُهُ لِلرِّضَا عَنْهُ أَمَامَ الرَّبِّ.', 'لاويين 1:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 4, 'وَيَضَعُ يَدَهُ عَلَى رَأْسِ الْمُحْرَقَةِ، فَيُرْضَى عَلَيْهِ لِلتَّكْفِيرِ عَنْهُ.', 'لاويين 1:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 5, 'وَيَذْبَحُ الْعِجْلَ أَمَامَ الرَّبِّ، وَيُقَرِّبُ بَنوُ هَارُونَ الْكَهَنَةُ الدَّمَ، وَيَرُشُّونَ الدَّمَ مُسْتَدِيرًا عَلَى الْمَذْبَحِ الَّذِي لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 1:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 6, 'وَيَسْلُخُ الْمُحْرَقَةَ وَيُقَطِّعُهَا إِلَى قِطَعِهَا.', 'لاويين 1:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 7, 'وَيَجْعَلُ بَنُو هَارُونَ الْكَاهِنِ نَارًا عَلَى الْمَذْبَحِ، وَيُرَتِّبُونَ حَطَبًا عَلَى النَّارِ.', 'لاويين 1:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 8, 'وَيُرَتِّبُ بَنُو هَارُونَ الْكَهَنَةُ الْقِطَعَ مَعَ الرَّأْسِ وَالشَّحْمِ فَوْقَ الْحَطَبِ الَّذِي عَلَى النَّارِ الَّتِي عَلَى الْمَذْبَحِ.', 'لاويين 1:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 9, 'وَأَمَّا أَحْشَاؤُهُ وَأَكَارِعُهُ فَيَغْسِلُهَا بِمَاءٍ، وَيُوقِدُ الْكَاهِنُ الْجَمِيعَ عَلَى الْمَذْبَحِ مُحْرَقَةً، وَقُودَ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 1:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 10, '«وَإِنْ كَانَ قُرْبَانُهُ مِنَ الْغَنَمِ الضَّأْنِ أَوِ الْمَعْزِ مُحْرَقَةً، فَذَكَرًا صَحِيحًا يُقَرِّبُهُ.', 'لاويين 1:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 11, 'وَيَذْبَحُهُ عَلَى جَانِبِ الْمَذْبَحِ إِلَى الشِّمَالِ أَمَامَ الرَّبِّ، وَيَرُشُّ بَنُو هَارُونَ الْكَهَنَةُ دَمَهُ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 1:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 12, 'وَيُقَطِّعُهُ إِلَى قِطَعِهِ، مَعَ رَأْسِهِ وَشَحْمِهِ. وَيُرَتِّبُهُنَّ الْكَاهِنُ فَوْقَ الْحَطَبِ الَّذِي عَلَى النَّارِ الَّتِي عَلَى الْمَذْبَحِ.', 'لاويين 1:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 13, 'وَأَمَّا الْأَحْشَاءُ وَالْأَكَارِعُ فَيَغْسِلُهَا بِمَاءٍ، وَيُقَرِّبُ الْكَاهِنُ الْجَمِيعَ، وَيُوقِدُ عَلَى الْمَذْبَحِ. إِنَّهُ مُحْرَقَةٌ، وَقُودُ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 1:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 14, '«وَإِنْ كَانَ قُرْبَانُهُ لِلرَّبِّ مِنَ الطَّيْرِ مُحْرَقَةً، يُقَرِّبُ قُرْبَانَهُ مِنَ الْيَمَامِ أَوْ مِنْ أَفْرَاخِ الْحَمَامِ.', 'لاويين 1:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 15, 'يُقَدِّمُهُ الْكَاهِنُ إِلَى الْمَذْبَحِ، وَيَحُزُّ رَأْسَهُ، وَيُوقِدُ عَلَى الْمَذْبَحِ، وَيُعْصَرُ دَمُهُ عَلَى حَائِطِ الْمَذْبَحِ.', 'لاويين 1:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 16, 'وَيَنْزِعُ حَوْصَلَتَهُ بِفَرْثِهَا وَيَطْرَحُهَا إِلَى جَانِبِ الْمَذْبَحِ شَرْقًا إِلَى مَكَانِ الرَّمَادِ.', 'لاويين 1:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 1, 17, 'وَيَشُقُّهُ بَيْنَ جَنَاحَيْهِ. لَا يَفْصِلُهُ. وَيُوقِدُهُ الْكَاهِنُ عَلَى الْمَذْبَحِ فَوْقَ الْحَطَبِ الَّذِي عَلَى النَّارِ. إِنَّهُ مُحْرَقَةٌ، وَقُودُ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 1:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 1, '«وَإِذَا قَرَّبَ أَحَدٌ قُرْبَانَ تَقْدِمَةٍ لِلرَّبِّ، يَكُونُ قُرْبَانُهُ مِنْ دَقِيقٍ. وَيَسْكُبُ عَلَيْهَا زَيْتًا، وَيَجْعَلُ عَلَيْهَا لُبَانًا.', 'لاويين 2:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 2, 'وَيَأْتِي بِهَا إِلَى بَنِي هَارُونَ الْكَهَنَةِ، وَيَقْبِضُ مِنْهَا مِلْءَ قَبْضَتِهِ مِنْ دَقِيقِهَا وَزَيْتِهَا مَعَ كُلِّ لُبَانِهَا، وَيُوقِدُ الْكَاهِنُ تَذْكَارَهَا عَلَى الْمَذْبَحِ، وَقُودَ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 2:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 3, 'وَالْبَاقِي مِنَ التَّقْدِمَةِ هُوَ لِهَارُونَ وَبَنِيهِ، قُدْسُ أَقْدَاسٍ مِنْ وَقَائِدِ الرَّبِّ.', 'لاويين 2:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 4, '«وَإِذَا قَرَّبْتَ قُرْبَانَ تَقْدِمَةٍ مَخْبُوزَةٍ فِي تَنُّورٍ، تَكُونُ أَقْرَاصًا مِنْ دَقِيقٍ، فَطِيرًا مَلْتُوتَةً بِزَيْتٍ، وَرِقَاقًا فَطِيرًا مَدْهُونَةً بِزَيْتٍ.', 'لاويين 2:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 5, 'وَإِنْ كَانَ قُرْبَانُكَ تَقْدِمَةً عَلَى الصَّاجِ، تَكُونُ مِنْ دَقِيقٍ مَلْتُوتَةً بِزَيْتٍ، فَطِيرًا.', 'لاويين 2:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 6, 'تَفُتُّهَا فُتَاتًا وَتَسْكُبُ عَلَيْهَا زَيْتًا. إِنَّهَا تَقْدِمَةٌ.', 'لاويين 2:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 7, '«وَإِنْ كَانَ قُرْبَانُكَ تَقْدِمَةً مِنْ طَاجِنٍ، فَمِنْ دَقِيقٍ بِزَيْتٍ تَعْمَلُهُ.', 'لاويين 2:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 8, 'فَتَأْتِي بِالتَّقْدِمَةِ الَّتِي تُصْطَنَعُ مِنْ هَذِهِ إِلَى الرَّبِّ وَتُقَدِّمُهَا إِلَى الْكَاهِنِ، فَيَدْنُو بِهَا إِلَى الْمَذْبَحِ.', 'لاويين 2:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 9, 'وَيَأْخُذُ الْكَاهِنُ مِنَ التَّقْدِمَةِ تَذْكَارَهَا وَيُوقِدُ عَلَى الْمَذْبَحِ وَقُودَ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 2:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 10, 'وَالْبَاقِي مِنَ التَّقْدِمَةِ هُوَ لِهَارُونَ وَبَنِيهِ، قُدْسُ أَقْدَاسٍ مِنْ وَقَائِدِ الرَّبِّ.', 'لاويين 2:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 11, '«كُلُّ التَّقْدِمَاتِ الَّتِي تُقَرِّبُونَهَا لِلرَّبِّ لَا تُصْطَنَعُ خَمِيرًا، لِأَنَّ كُلَّ خَمِيرٍ، وَكُلَّ عَسَلٍ لَا تُوقِدُوا مِنْهُمَا وَقُودًا لِلرَّبِّ.', 'لاويين 2:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 12, 'قُرْبَانَ أَوَائِلَ تُقَرِّبُونَهُمَا لِلرَّبِّ. لَكِنْ عَلَى الْمَذْبَحِ لَا يَصْعَدَانِ لِرَائِحَةِ سَرُورٍ.', 'لاويين 2:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 13, 'وَكُلُّ قُرْبَانٍ مِنْ تَقْدِمَاتِكَ بِالْمِلْحِ تُمَلِّحُهُ، وَلَا تُخْلِ تَقْدِمَتَكَ مِنْ مِلْحِ عَهْدِ إِلَهِكَ. عَلَى جَمِيعِ قَرَابِينِكَ تُقَرِّبُ مِلْحًا.', 'لاويين 2:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 14, '«وَإِنْ قَرَّبْتَ تَقْدِمَةَ بَاكُورَاتٍ لِلرَّبِّ، فَفَرِيكًا مَشْوِيًّا بِالنَّارِ. جَرِيشًا سَوِيقًا تُقَرِّبُ تَقْدِمَةَ بَاكُورَاتِكَ.', 'لاويين 2:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 15, 'وَتَجْعَلُ عَلَيْهَا زَيْتًا وَتَضَعُ عَلَيْهَا لُبَانًا. إِنَّهَا تَقْدِمَةٌ.', 'لاويين 2:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 2, 16, 'فَيُوقِدُ الْكَاهِنُ تَذْكَارَهَا مِنْ جَرِيشِهَا وَزَيْتِهَا مَعَ جَمِيعِ لُبَانِهَا وَقُودًا لِلرَّبِّ.', 'لاويين 2:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 1, '«وَإِنْ كَانَ قُرْبَانُهُ ذَبِيحَةَ سَلَامَةٍ، فَإِنْ قَرَّبَ مِنَ الْبَقَرِ ذَكَرًا أَوْ أُنْثَى، فَصَحِيحًا يُقَرِّبُهُ أَمَامَ الرَّبِّ.', 'لاويين 3:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 2, 'يَضَعُ يَدَهُ عَلَى رَأْسِ قُرْبَانِهِ وَيَذْبَحُهُ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ، وَيَرُشُّ بَنُو هَارُونَ الْكَهَنَةُ الدَّمَ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 3:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 3, 'وَيُقَرِّبُ مِنْ ذَبِيحَةِ السَّلَامَةِ وَقُودًا لِلرَّبِّ׃ الشَّحْمَ الَّذِي يُغَشِّي الْأَحْشَاءَ، وَسَائِرَ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ،', 'لاويين 3:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 4, 'وَالْكُلْيَتَيْنِ، وَالشَّحْمَ الَّذِي عَلَيْهِمَا الَّذِي عَلَى الْخَاصِرَتَيْنِ، وَزِيَادَةَ الْكَبِدِ مَعَ الْكُلْيَتَيْنِ يَنْزِعُهَا.', 'لاويين 3:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 5, 'وَيُوقِدُهَا بَنُو هَارُونَ عَلَى الْمَذْبَحِ عَلَى الْمُحْرَقَةِ الَّتِي فَوْقَ الْحَطَبِ الَّذِي عَلَى النَّارِ، وَقُودَ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 3:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 6, '«وَإِنْ كَانَ قُرْبَانُهُ مِنَ الْغَنَمِ ذَبِيحَةَ سَلَامَةٍ لِلرَّبِّ ذَكَرًا أَوْ أُنْثَى، فَصَحِيحًا يُقَرِّبُهُ.', 'لاويين 3:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 7, 'إِنْ قَرَّبَ قُرْبَانَهُ مِنَ الضَّأْنِ يُقَدِّمُهُ أَمَامَ الرَّبِّ.', 'لاويين 3:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 8, 'يَضَعُ يَدَهُ عَلَى رَأْسِ قُرْبَانِهِ وَيَذْبَحُهُ قُدَّامَ خَيْمَةِ الِاجْتِمَاعِ. وَيَرُشُّ بَنُو هَارُونَ دَمَهُ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 3:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 9, 'وَيُقَرِّبُ مِنْ ذَبِيحَةِ السَّلَامَةِ شَحْمَهَا وَقُودًا لِلرَّبِّ׃ الْأَلْيَةَ صَحِيحَةً مِنْ عِنْدِ الْعُصْعُصِ يَنْزِعُهَا، وَالشَّحْمَ الَّذِي يُغَشِّي الْأَحْشَاءَ، وَسَائِرَ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ،', 'لاويين 3:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 10, 'وَالْكُلْيَتَيْنِ، وَالشَّحْمَ الَّذِي عَلَيْهِمَا الَّذِي عَلَى الْخَاصِرَتَيْنِ، وَزِيَادَةَ الْكَبِدِ مَعَ الْكُلْيَتَيْنِ يَنْزِعُهَا.', 'لاويين 3:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 11, 'وَيُوقِدُهَا الْكَاهِنُ عَلَى الْمَذْبَحِ طَعَامَ وَقُودٍ لِلرَّبِّ.', 'لاويين 3:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 12, '«وَإِنْ كَانَ قُرْبَانُهُ مِنَ الْمَعْزِ يُقَدِّمُهُ أَمَامَ الرَّبِّ.', 'لاويين 3:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 13, 'يَضَعُ يَدَهُ عَلَى رَأْسِهِ وَيَذْبَحُهُ قُدَّامَ خَيْمَةِ الِاجْتِمَاعِ، وَيَرُشُّ بَنُو هَارُونَ دَمَهُ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 3:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 14, 'وَيُقَرِّبُ مِنْهُ قُرْبَانَهُ وَقُودًا لِلرَّبِّ׃ الشَّحْمَ الَّذِي يُغَشِّي الْأَحْشَاءَ، وَسَائِرَ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ،', 'لاويين 3:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 15, 'وَالْكُلْيَتَيْنِ وَالشَّحْمَ الَّذِي عَلَيْهِمَا الَّذِي عَلَى الْخَاصِرَتَيْنِ، وَزِيَادَةَ الْكَبِدِ مَعَ الْكُلْيَتَيْنِ يَنْزِعُهَا.', 'لاويين 3:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 16, 'وَيُوقِدُهُنَّ الْكَاهِنُ عَلَى الْمَذْبَحِ طَعَامَ وَقُودٍ لِرَائِحَةِ سَرُورٍ. كُلُّ الشَّحْمِ لِلرَّبِّ.', 'لاويين 3:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 3, 17, 'فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ فِي جَمِيعِ مَسَاكِنِكُمْ׃ لَا تَأْكُلُوا شَيْئًا مِنَ الشَّحْمِ وَلَا مِنَ الدَّمِ».', 'لاويين 3:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 4:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ إِذَا أَخْطَأَتْ نَفْسٌ سَهْوًا فِي شَيْءٍ مِنْ جَمِيعِ مَنَاهِي الرَّبِّ الَّتِي لَا يَنْبَغِي عَمَلُهَا، وَعَمِلَتْ وَاحِدَةً مِنْهَا׃', 'لاويين 4:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 3, 'إِنْ كَانَ الْكَاهِنُ الْمَمْسُوحُ يُخْطِئُ لِإِثْمِ الشَّعْبِ، يُقَرِّبُ عَنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ ثَوْرًا ابْنَ بَقَرٍ صَحِيحًا لِلرَّبِّ، ذَبِيحَةَ خَطِيَّةٍ.', 'لاويين 4:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 4, 'يُقَدِّمُ الثَّوْرَ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ أَمَامَ الرَّبِّ، وَيَضَعُ يَدَهُ عَلَى رَأْسِ الثَّوْرِ، وَيَذْبَحُ الثَّوْرَ أَمَامَ الرَّبِّ.', 'لاويين 4:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 5, 'وَيَأْخُذُ الْكَاهِنُ الْمَمْسُوحُ مِنْ دَمِ الثَّوْرِ وَيَدْخُلُ بِهِ إِلَى خَيْمَةِ الِاجْتِمَاعِ،', 'لاويين 4:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 6, 'وَيَغْمِسُ الْكَاهِنُ إِصْبَعَهُ فِي الدَّمِ وَيَنْضِحُ مِنَ الدَّمِ سَبْعَ مَرَّاتٍ أَمَامَ الرَّبِّ لَدَى حِجَابِ الْقُدْسِ.', 'لاويين 4:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 7, 'وَيَجْعَلُ الْكَاهِنُ مِنَ الدَّمِ عَلَى قُرُونِ مَذْبَحِ الْبَخُورِ الْعَطِرِ الَّذِي فِي خَيْمَةِ الِاجْتِمَاعِ أَمَامَ الرَّبِّ، وَسَائِرُ دَمِ الثَّوْرِ يَصُبُّهُ إِلَى أَسْفَلِ مَذْبَحِ الْمُحْرَقَةِ الَّذِي لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 4:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 8, 'وَجَمِيعُ شَحْمِ ثَوْرِ الْخَطِيَّةِ يَنْزِعُهُ عَنْهُ. الشَّحْمَ الَّذِي يُغَشِّي الْأَحْشَاءَ، وَسَائِرَ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ،', 'لاويين 4:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 9, 'وَالْكُلْيَتَيْنِ وَالشَّحْمَ الَّذِي عَلَيْهِمَا الَّذِي عَلَى الْخَاصِرَتَيْنِ، وَزِيَادَةَ الْكَبِدِ مَعَ الْكُلْيَتَيْنِ يَنْزِعُهَا،', 'لاويين 4:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 10, 'كَمَا تُنْزَعُ مِنْ ثَوْرِ ذَبِيحَةِ السَّلَامَةِ. وَيُوقِدُهُنَّ الْكَاهِنُ عَلَى مَذْبَحِ الْمُحْرَقَةِ.', 'لاويين 4:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 11, 'وَأَمَّا جِلْدُ الثَّوْرِ وَكُلُّ لَحْمِهِ مَعَ رَأْسِهِ وَأَكَارِعِهِ وَأَحْشَائِهِ وَفَرْثِهِ', 'لاويين 4:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 12, 'فَيُخْرِجُ سَائِرَ الثَّوْرِ إِلَى خَارِجِ الْمَحَلَّةِ إِلَى مَكَانٍ طَاهِرٍ، إِلَى مَرْمَى الرَّمَادِ، وَيُحْرِقُهَا عَلَى حَطَبٍ بِالنَّارِ. عَلَى مَرْمَى الرَّمَادِ تُحْرَقُ.', 'لاويين 4:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 13, '«وَإِنْ سَهَا كُلُّ جَمَاعَةِ إِسْرَائِيلَ، وَأُخْفِيَ أَمْرٌ عَنْ أَعْيُنِ الْمَجْمَعِ، وَعَمِلُوا وَاحِدَةً مِنْ جَمِيعِ مَنَاهِي الرَّبِّ الَّتِي لَا يَنْبَغِي عَمَلُهَا، وَأَثِمُوا،', 'لاويين 4:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 14, 'ثُمَّ عُرِفَتِ الْخَطِيَّةُ الَّتِي أَخْطَأُوا بِهَا، يُقَرِّبُ الْمَجْمَعُ ثَوْرًا ابْنَ بَقَرٍ ذَبِيحَةَ خَطِيَّةٍ. يَأْتُونَ بِهِ إِلَى قُدَّامِ خَيْمَةِ الِاجْتِمَاعِ،', 'لاويين 4:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 15, 'وَيَضَعُ شُيُوخُ الْجَمَاعَةِ أَيْدِيَهُمْ عَلَى رَأْسِ الثَّوْرِ أَمَامَ الرَّبِّ، وَيَذْبَحُ الثَّوْرَ أَمَامَ الرَّبِّ.', 'لاويين 4:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 16, 'وَيُدْخِلُ الْكَاهِنُ الْمَمْسُوحُ مِنْ دَمِ الثَّوْرِ إِلَى خَيْمَةِ الِاجْتِمَاعِ،', 'لاويين 4:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 17, 'وَيَغْمِسُ الْكَاهِنُ إِصْبَعَهُ فِي الدَّمِ، وَيَنْضِحُ سَبْعَ مَرَّاتٍ أَمَامَ الرَّبِّ لَدَى الْحِجَابِ.', 'لاويين 4:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 18, 'وَيَجْعَلُ مِنَ الدَّمِ عَلَى قُرُونِ الْمَذْبَحِ الَّذِي أَمَامَ الرَّبِّ فِي خَيْمَةِ الِاجْتِمَاعِ، وَسَائِرَ الدَّمِ يَصُبُّهُ إِلَى أَسْفَلِ مَذْبَحِ الْمُحْرَقَةِ الَّذِي لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 4:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 19, 'وَجَمِيعَ شَحْمِهِ يَنْزِعُهُ عَنْهُ وَيُوقِدُهُ عَلَى الْمَذْبَحِ.', 'لاويين 4:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 20, 'وَيَفْعَلُ بِالثَّوْرِ كَمَا فَعَلَ بِثَوْرِ الْخَطِيَّةِ. كَذَلِكَ يَفْعَلُ بِهِ. وَيُكَفِّرُ عَنْهُمُ الْكَاهِنُ، فَيُصْفَحُ عَنْهُمْ.', 'لاويين 4:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 21, 'ثُمَّ يُخْرِجُ الثَّوْرَ إِلَى خَارِجِ الْمَحَلَّةِ وَيُحْرِقُهُ كَمَا أَحْرَقَ الثَّوْرَ الْأَوَّلَ. إِنَّهُ ذَبِيحَةُ خَطِيَّةِ الْمَجْمَعِ.', 'لاويين 4:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 22, '«إِذَا أَخْطَأَ رَئِيسٌ وَعَمِلَ بِسَهْوٍ وَاحِدَةً مِنْ جَمِيعِ مَنَاهِي الرَّبِّ إِلَهِهِ الَّتِي لَا يَنْبَغِي عَمَلُهَا، وَأَثِمَ،', 'لاويين 4:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 23, 'ثُمَّ أُعْلِمَ بِخَطِيَّتِهِ الَّتِي أَخْطَأَ بِهَا، يَأْتِي بِقُرْبَانِهِ تَيْسًا مِنَ الْمَعْزِ ذَكَرًا صَحِيحًا.', 'لاويين 4:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 24, 'وَيَضَعُ يَدَهُ عَلَى رَأْسِ التَّيْسِ وَيَذْبَحُهُ فِي الْمَوْضِعِ الَّذِي يَذْبَحُ فِيهِ الْمُحْرَقَةَ أَمَامَ الرَّبِّ. إِنَّهُ ذَبِيحَةُ خَطِيَّةٍ.', 'لاويين 4:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 25, 'وَيَأْخُذُ الْكَاهِنُ مِنْ دَمِ ذَبِيحَةِ الْخَطِيَّةِ بِإِصْبَعِهِ وَيَجْعَلُ عَلَى قُرُونِ مَذْبَحِ الْمُحْرَقَةِ، ثُمَّ يَصُبُّ دَمَهُ إِلَى أَسْفَلِ مَذْبَحِ الْمُحْرَقَةِ.', 'لاويين 4:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 26, 'وَجَمِيعَ شَحْمِهِ يُوقِدُهُ عَلَى الْمَذْبَحِ كَشَحْمِ ذَبِيحَةِ السَّلَامَةِ، وَيُكَفِّرُ الْكَاهِنُ عَنْهُ مِنْ خَطِيَّتِهِ فَيُصْفَحُ عَنْهُ.', 'لاويين 4:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 27, '«وَإِنْ أَخْطَأَ أَحَدٌ مِنْ عَامَّةِ الْأَرْضِ سَهْوًا، بِعَمَلِهِ وَاحِدَةً مِنْ مَنَاهِي الرَّبِّ الَّتِي لَا يَنْبَغِي عَمَلُهَا، وَأَثِمَ،', 'لاويين 4:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 28, 'ثُمَّ أُعْلِمَ بِخَطِيَّتِهِ الَّتِي أَخْطَأَ بِهَا، يَأْتِي بِقُرْبَانِهِ عَنْزًا مِنَ الْمَعْزِ أُنْثَى صَحِيحَةً عَنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ.', 'لاويين 4:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 29, 'وَيَضَعُ يَدَهُ عَلَى رَأْسِ ذَبِيحَةِ الْخَطِيَّةِ، وَيَذْبَحُ ذَبِيحَةَ الْخَطِيَّةِ فِي مَوْضِعِ الْمُحْرَقَةِ.', 'لاويين 4:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 30, 'وَيَأْخُذُ الْكَاهِنُ مِنْ دَمِهَا بِإِصْبَعِهِ وَيَجْعَلُ عَلَى قُرُونِ مَذْبَحِ الْمُحْرَقَةِ، وَيَصُبُّ سَائِرَ دَمِهَا إِلَى أَسْفَلِ الْمَذْبَحِ.', 'لاويين 4:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 31, 'وَجَمِيعَ شَحْمِهَا يَنْزِعُهُ كَمَا نُزِعَ الشَّحْمُ عَنْ ذَبِيحَةِ السَّلَامَةِ، وَيُوقِدُ الْكَاهِنُ عَلَى الْمَذْبَحِ رَائِحَةَ سَرُورٍ لِلرَّبِّ وَيُكَفِّرُ عَنْهُ الْكَاهِنُ فَيُصْفَحُ عَنْهُ.', 'لاويين 4:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 32, '«وَإِنْ أَتَى بِقُرْبَانِهِ مِنَ الضَّأْنِ ذَبِيحَةَ خَطِيَّةٍ، يَأْتِي بِهَا أُنْثَى صَحِيحَةً.', 'لاويين 4:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 33, 'وَيَضَعُ يَدَهُ عَلَى رَأْسِ ذَبِيحَةِ الْخَطِيَّةِ، وَيَذْبَحُهَا ذَبِيحَةَ خَطِيَّةٍ فِي الْمَوْضِعِ الَّذِي يَذْبَحُ فِيهِ الْمُحْرَقَةَ.', 'لاويين 4:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 34, 'وَيَأْخُذُ الْكَاهِنُ مِنْ دَمِ ذَبِيحَةِ الْخَطِيَّةِ بِإِصْبَعِهِ وَيَجْعَلُ عَلَى قُرُونِ مَذْبَحِ الْمُحْرَقَةِ، وَيَصُبُّ سَائِرَ الدَّمِ إِلَى أَسْفَلِ الْمَذْبَحِ.', 'لاويين 4:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 4, 35, 'وَجَمِيعَ شَحْمِهِ يَنْزِعُهُ كَمَا يُنْزَعُ شَحْمُ الضَّأْنِ عَنْ ذَبِيحَةِ السَّلَامَةِ، وَيُوقِدُهُ الْكَاهِنُ عَلَى الْمَذْبَحِ عَلَى وَقَائِدِ الرَّبِّ. وَيُكَفِّرُ عَنْهُ الْكَاهِنُ مِنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ فَيُصْفَحُ عَنْهُ.', 'لاويين 4:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 1, '«وَإِذَا أَخْطَأَ أَحَدٌ وَسَمِعَ صَوْتَ حَلْفٍ وَهُوَ شَاهِدٌ يُبْصِرُ أَوْ يَعْرِفُ، فَإِنْ لَمْ يُخْبِرْ بِهِ حَمَلَ ذَنْبَهُ.', 'لاويين 5:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 2, 'أَوْ إِذَا مَسَّ أَحَدٌ شَيْئًا نَجِسًا׃ جُثَّةَ وَحْشٍ نَجِسٍ، أَوْ جُثَّةَ بَهِيمَةٍ نَجِسَةٍ، أَوْ جُثَّةَ دَبِيبٍ نَجِسٍ، وَأُخْفِيَ عَنْهُ، فَهُوَ نَجِسٌ وَمُذْنِبٌ.', 'لاويين 5:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 3, 'أَوْ إِذَا مَسَّ نَجَاسَةَ إِنْسَانٍ مِنْ جَمِيعِ نَجَاسَاتِهِ الَّتِي يَتَنَجَّسُ بِهَا، وَأُخْفِيَ عَنْهُ ثُمَّ عُلِمَ، فَهُوَ مُذْنِبٌ.', 'لاويين 5:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 4, 'أَوْ إِذَا حَلَفَ أَحَدٌ مُفْتَرِطًا بِشَفَتَيْهِ لِلْإِسَاءَةِ أَوْ لِلْإِحْسَانِ مِنْ جَمِيعِ مَا يَفْتَرِطُ بِهِ الْإِنْسَانُ فِي الْيَمِينِ، وَأُخْفِيَ عَنْهُ، ثُمَّ عُلِمَ، فَهُوَ مُذْنِبٌ فِي شَيْءٍ مِنْ ذَلِكَ.', 'لاويين 5:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 5, 'فَإِنْ كَانَ يُذْنِبُ فِي شَيْءٍ مِنْ هَذِهِ، يُقِرُّ بِمَا قَدْ أَخْطَأَ بِهِ.', 'لاويين 5:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 6, 'وَيَأْتِي إِلَى الرَّبِّ بِذَبِيحَةٍ لِإِثْمِهِ عَنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ بِهَا׃ أُنْثَى مِنَ الْأَغْنَامِ نَعْجَةً أَوْ عَنْزًا مِنَ الْمَعْزِ، ذَبِيحَةَ خَطِيَّةٍ، فَيُكَفِّرُ عَنْهُ الْكَاهِنُ مِنْ خَطِيَّتِهِ.', 'لاويين 5:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 7, 'وَإِنْ لَمْ تَنَلْ يَدُهُ كِفَايَةً لِشَاةٍ، فَيَأْتِي بِذَبِيحَةٍ لِإِثْمِهِ الَّذِي أَخْطَأَ بِهِ׃ يَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ إِلَى الرَّبِّ، أَحَدُهُمَا ذَبِيحَةُ خَطِيَّةٍ وَالْآخَرُ مُحْرَقَةٌ.', 'لاويين 5:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 8, 'يَأْتِي بِهِمَا إِلَى الْكَاهِنِ، فَيُقَرِّبُ الَّذِي لِلْخَطِيَّةِ أَوَّلًا. يَحُزُّ رَأْسَهُ مِنْ قَفَاهُ وَلَا يَفْصِلُهُ.', 'لاويين 5:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 9, 'وَيَنْضِحُ مِنْ دَمِ ذَبِيحَةِ الْخَطِيَّةِ عَلَى حَائِطِ الْمَذْبَحِ، وَالْبَاقِي مِنَ الدَّمِ يُعْصَرُ إِلَى أَسْفَلِ الْمَذْبَحِ. إِنَّهُ ذَبِيحَةُ خَطِيَّةٍ.', 'لاويين 5:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 10, 'وَأَمَّا الثَّانِي فَيَعْمَلُهُ مُحْرَقَةً كَالْعَادَةِ، فَيُكَفِّرُ عَنْهُ الْكَاهِنُ مِنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ، فَيُصْفَحُ عَنْهُ.', 'لاويين 5:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 11, 'وَإِنْ لَمْ تَنَلْ يَدُهُ يَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ فَيَأْتِي بِقُرْبَانِهِ عَمَّا أَخْطَأَ بِهِ عُشْرَ الْإِيفَةِ مِنْ دَقِيقٍ، قُرْبَانَ خَطِيَّةٍ. لَا يَضَعُ عَلَيْهِ زَيْتًا، وَلَا يَجْعَلُ عَلَيْهِ لُبَانًا لِأَنَّهُ قُرْبَانُ خَطِيَّةٍ.', 'لاويين 5:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 12, 'يَأْتِي بِهِ إِلَى الْكَاهِنِ فَيَقْبِضُ الْكَاهِنُ مِنْهُ مِلْءَ قَبْضَتِهِ تَذْكَارَهُ، وَيُوقِدُهُ عَلَى الْمَذْبَحِ عَلَى وَقَائِدِ الرَّبِّ. إِنَّهُ قُرْبَانُ خَطِيَّةٍ.', 'لاويين 5:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 13, 'فَيُكَفِّرُ عَنْهُ الْكَاهِنُ مِنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ بِهَا فِي وَاحِدَةٍ مِنْ ذَلِكَ، فَيُصْفَحُ عَنْهُ. وَيَكُونُ لِلْكَاهِنِ كَالتَّقْدِمَةِ».', 'لاويين 5:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 14, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 5:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 15, '«إِذَا خَانَ أَحَدٌ خِيَانَةً وَأَخْطَأَ سَهْوًا فِي أَقْدَاسِ الرَّبِّ، يَأْتِي إِلَى الرَّبِّ بِذَبِيحَةٍ لِإِثْمِهِ׃ كَبْشًا صَحِيحًا مِنَ الْغَنَمِ بِتَقْوِيمِكَ مِنْ شَوَاقِلِ فِضَّةٍ عَلَى شَاقِلِ الْقُدْسِ، ذَبِيحَةَ إِثْمٍ.', 'لاويين 5:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 16, 'وَيُعَوِّضُ عَمَّا أَخْطَأَ بِهِ مِنَ الْقُدْسِ، وَيَزِيدُ عَلَيْهِ خُمْسَهُ، وَيَدْفَعُهُ إِلَى الْكَاهِنِ، فَيُكَفِّرُ الْكَاهِنُ عَنْهُ بِكَبْشِ الْإِثْمِ، فَيُصْفَحُ عَنْهُ.', 'لاويين 5:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 17, '«وَإِذَا أَخْطَأَ أَحَدٌ وَعَمِلَ وَاحِدَةً مِنْ جَمِيعِ مَنَاهِي الرَّبِّ الَّتِي لَا يَنْبَغِي عَمَلُهَا، وَلَمْ يَعْلَمْ، كَانَ مُذْنِبًا وَحَمَلَ ذَنْبَهُ.', 'لاويين 5:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 18, 'فَيَأْتِي بِكَبْشٍ صَحِيحٍ مِنَ الْغَنَمِ بِتَقْوِيمِكَ، ذَبِيحَةَ إِثْمٍ، إِلَى الْكَاهِنِ، فَيُكَفِّرُ عَنْهُ الْكَاهِنُ مِنْ سَهْوِهِ الَّذِي سَهَا وَهُوَ لَا يَعْلَمُ، فَيُصْفَحُ عَنْهُ.', 'لاويين 5:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 5, 19, 'إِنَّهُ ذَبِيحَةُ إِثْمٍ. قَدْ أَثِمَ إِثْمًا إِلَى الرَّبِّ».', 'لاويين 5:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 6:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 2, '«إِذَا أَخْطَأَ أَحَدٌ وَخَانَ خِيَانَةً بِالرَّبِّ، وَجَحَدَ صَاحِبَهُ وَدِيعَةً أَوْ أَمَانَةً أَوْ مَسْلُوبًا، أَوِ اغْتَصَبَ مِنْ صَاحِبِهِ،', 'لاويين 6:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 3, 'أَوْ وَجَدَ لُقَطَةً وَجَحَدَهَا، وَحَلَفَ كَاذِبًا عَلَى شَيْءٍ مِنْ كُلِّ مَا يَفْعَلُهُ الْإِنْسَانُ مُخْطِئًا بِهِ،', 'لاويين 6:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 4, 'فَإِذَا أَخْطَأَ وَأَذْنَبَ، يَرُدُّ الْمَسْلُوبَ الَّذِي سَلَبَهُ، أَوِ الْمُغْتَصَبَ الَّذِي اغْتَصَبَهُ، أَوِ الْوَدِيعَةَ الَّتِي أُودِعَتْ عِنْدَهُ، أَوِ اللُّقَطَةَ الَّتِي وَجَدَهَا،', 'لاويين 6:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 5, 'أَوْ كُلَّ مَا حَلَفَ عَلَيْهِ كَاذِبًا. يُعَوِّضُهُ بِرَأْسِهِ، وَيَزِيدُ عَلَيْهِ خُمْسَهُ. إِلَى الَّذِي هُوَ لَهُ يَدْفَعُهُ يَوْمَ ذَبِيحَةِ إِثْمِهِ.', 'لاويين 6:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 6, 'وَيَأْتِي إِلَى الرَّبِّ بِذَبِيحَةٍ لِإِثْمِهِ׃ كَبْشًا صَحِيحًا مِنَ الْغَنَمِ بِتَقْوِيمِكَ، ذَبِيحَةَ إِثْمٍ إِلَى الْكَاهِنِ.', 'لاويين 6:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 7, 'فَيُكَفِّرُ عَنْهُ الْكَاهِنُ أَمَامَ الرَّبِّ، فَيُصْفَحُ عَنْهُ فِي الشَّيْءِ مِنْ كُلِّ مَا فَعَلَهُ مُذْنِبًا بِهِ».', 'لاويين 6:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 8, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 6:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 9, '«أَوْصِ هَارُونَ وَبَنِيهِ قَائِلًا׃ هَذِهِ شَرِيعَةُ الْمُحْرَقَةِ׃ هِيَ الْمُحْرَقَةُ تَكُونُ عَلَى الْمَوْقِدَةِ فَوْقَ الْمَذْبَحِ كُلَّ اللَّيْلِ حَتَّى الصَّبَاحِ، وَنَارُ الْمَذْبَحِ تَتَّقِدُ عَلَيْهِ.', 'لاويين 6:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 10, 'ثُمَّ يَلْبَسُ الْكَاهِنُ ثَوْبَهُ مِنْ كَتَّانٍ، وَيَلْبَسُ سَرَاوِيلَ مِنْ كَتَّانٍ عَلَى جَسَدِهِ، وَيَرْفَعُ الرَّمَادَ الَّذِي صَيَّرَتِ النَّارُ الْمُحْرَقَةَ إِيَّاهُ عَلَى الْمَذْبَحِ، وَيَضَعُهُ بِجَانِبِ الْمَذْبَحِ.', 'لاويين 6:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 11, 'ثُمَّ يَخْلَعُ ثِيَابَهُ وَيَلْبَسُ ثِيَابًا أُخْرَى، وَيُخْرِجُ الرَّمَادَ إِلَى خَارِجِ الْمَحَلَّةِ، إِلَى مَكَانٍ طَاهِرٍ.', 'لاويين 6:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 12, 'وَالنَّارُ عَلَى الْمَذْبَحِ تَتَّقِدُ عَلَيْهِ. لَا تَطْفَأُ. وَيُشْعِلُ عَلَيْهَا الْكَاهِنُ حَطَبًا كُلَّ صَبَاحٍ، وَيُرَتِّبُ عَلَيْهَا الْمُحْرَقَةَ، وَيُوقِدُ عَلَيْهَا شَحْمَ ذَبَائِحِ السَّلَامَةِ.', 'لاويين 6:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 13, 'نَارٌ دَائِمَةٌ تَتَّقِدُ عَلَى الْمَذْبَحِ. لَا تَطْفَأُ.', 'لاويين 6:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 14, '«وَهَذِهِ شَرِيعَةُ التَّقْدِمَةِ׃ يُقَدِّمُهَا بَنُو هَارُونَ أَمَامَ الرَّبِّ إِلَى قُدَّامِ الْمَذْبَحِ،', 'لاويين 6:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 15, 'وَيَأْخُذُ مِنْهَا بِقَبْضَتِهِ بَعْضَ دَقِيقِ التَّقْدِمَةِ وَزَيْتِهَا وَكُلَّ اللُّبَانِ الَّذِي عَلَى التَّقْدِمَةِ، وَيُوقِدُ عَلَى الْمَذْبَحِ رَائِحَةَ سَرُورٍ تَذْكَارَهَا لِلرَّبِّ.', 'لاويين 6:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 16, 'وَالْبَاقِي مِنْهَا يَأْكُلُهُ هَارُونُ وَبَنُوهُ. فَطِيرًا يُؤْكَلُ فِي مَكَانٍ مُقَدَّسٍ. فِي دَارِ خَيْمَةِ الِاجْتِمَاعِ يَأْكُلُونَهُ.', 'لاويين 6:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 17, 'لَا يُخْبَزُ خَمِيرًا. قَدْ جَعَلْتُهُ نَصِيبَهُمْ مِنْ وَقَائِدِي. إِنَّهَا قُدْسُ أَقْدَاسٍ كَذَبِيحَةِ الْخَطِيَّةِ وَذَبِيحَةِ الْإِثْمِ.', 'لاويين 6:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 18, 'كُلُّ ذَكَرٍ مِنْ بَنِي هَارُونَ يَأْكُلُ مِنْهَا. فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ مِنْ وَقَائِدِ الرَّبِّ. كُلُّ مَنْ مَسَّهَا يَتَقَدَّسُ».', 'لاويين 6:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 19, 'وكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 6:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 20, '«هَذَا قُرْبَانُ هَارُونَ وَبَنِيهِ الَّذِي يُقَرِّبُونَهُ لِلرَّبِّ يَوْمَ مَسْحَتِهِ׃ عُشْرُ الْإِيفَةِ مِنْ دَقِيقٍ تَقْدِمَةً دَائِمَةً، نِصْفُهَا صَبَاحًا، وَنِصْفُهَا مَسَاءً.', 'لاويين 6:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 21, 'عَلَى صَاجٍ تُعْمَلُ بِزَيْتٍ، مَرْبُوكَةً تَأْتِي بِهَا. ثَرَائِدَ تَقْدِمَةٍ، فُتَاتًا تُقَرِّبُهَا رَائِحَةَ سَرُورٍ لِلرَّبِّ.', 'لاويين 6:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 22, 'وَالْكَاهِنُ الْمَمْسُوحُ عِوَضًا عَنْهُ مِنْ بَنِيهِ يَعْمَلُهَا فَرِيضَةً دَهْرِيَّةً لِلرَّبِّ. تُوقَدُ بِكَمَالِهَا.', 'لاويين 6:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 23, 'وَكُلُّ تَقْدِمَةِ كَاهِنٍ تُحْرَقُ بِكَمَالِهَا. لَا تُؤْكَلُ».', 'لاويين 6:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 24, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 6:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 25, '«كَلِّمْ هَارُونَ وَبَنِيهِ قَائِلًا׃ هَذِهِ شَرِيعَةُ ذَبِيحَةِ الْخَطِيَّةِ׃ فِي الْمَكَانِ الَّذِي تُذْبَحُ فِيهِ الْمُحْرَقَةُ، تُذْبَحُ ذَبِيحَةُ الْخَطِيَّةِ أَمَامَ الرَّبِّ. إِنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 6:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 26, 'الْكَاهِنُ الَّذِي يَعْمَلُهَا لِلْخَطِيَّةِ يَأْكُلُهَا. فِي مَكَانٍ مُقَدَّسٍ تُؤْكَلُ فِي دَارِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 6:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 27, 'كُلُّ مَنْ مَسَّ لَحْمَهَا يَتَقَدَّسُ. وَإِذَا انْتَثَرَ مِنْ دَمِهَا عَلَى ثَوْبٍ تَغْسِلُ مَا انْتَثَرَ عَلَيْهِ فِي مَكَانٍ مُقَدَّسٍ.', 'لاويين 6:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 28, 'وَأَمَّا إِنَاءُ الْخَزَفِ الَّذِي تُطْبَخُ فِيهِ فَيُكْسَرُ. وَإِنْ طُبِخَتْ فِي إِنَاءِ نُحَاسٍ، يُجْلَى وَيُشْطَفُ بِمَاءٍ.', 'لاويين 6:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 29, 'كُلُّ ذَكَرٍ مِنَ الْكَهَنَةِ يَأْكُلُ مِنْهَا. إِنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 6:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 6, 30, 'وَكُلُّ ذَبِيحَةِ خَطِيَّةٍ يُدْخَلُ مِنْ دَمِهَا إِلَى خَيْمَةِ الِاجْتِمَاعِ لِلتَّكْفِيرِ فِي الْقُدْسِ، لَا تُؤْكَلُ. تُحْرَقُ بِنَارٍ.', 'لاويين 6:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 1, '«وَهَذِهِ شَرِيعَةُ ذَبِيحَةِ الْإِثْمِ׃ إِنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 7:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 2, 'فِي الْمَكَانِ الَّذِي يَذْبَحُونَ فِيهِ الْمُحْرَقَةَ، يَذْبَحُونَ ذَبِيحَةَ الْإِثْمِ، وَيَرُشُّ دَمَهَا عَلَى الْمَذْبَحِ مُسْتَدِيرًا،', 'لاويين 7:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 3, 'وَيُقَرِّبُ مِنْهَا كُلَّ شَحْمِهَا׃ الْأَلْيَةَ، وَالشَّحْمَ الَّذِي يُغَشِّي الْأَحْشَاءَ،', 'لاويين 7:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 4, 'وَالْكُلْيَتَيْنِ وَالشَّحْمَ الَّذِي عَلَيْهِمَا، الَّذِي عَلَى الْخَاصِرَتَيْنِ، وَزِيَادَةَ الْكَبِدِ مَعَ الْكُلْيَتَيْنِ يَنْزِعُهَا.', 'لاويين 7:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 5, 'وَيُوقِدُهُنَّ الْكَاهِنُ عَلَى الْمَذْبَحِ وَقُودًا لِلرَّبِّ. إِنَّهَا ذَبِيحَةُ إِثْمٍ.', 'لاويين 7:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 6, 'كُلُّ ذَكَرٍ مِنَ الْكَهَنَةِ يَأْكُلُ مِنْهَا. فِي مَكَانٍ مُقَدَّسٍ تُؤْكَلُ. إِنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 7:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 7, 'ذَبِيحَةُ الْإِثْمِ كَذَبِيحَةِ الْخَطِيَّةِ، لَهُمَا شَرِيعَةٌ وَاحِدَةٌ. الْكَاهِنُ الَّذِي يُكَفِّرُ بِهَا تَكُونُ لَهُ.', 'لاويين 7:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 8, 'وَالْكَاهِنُ الَّذِي يُقَرِّبُ مُحْرَقَةَ إِنْسَانٍ فَجِلْدُ الْمُحْرَقَةِ الَّتِي يُقَرِّبُهَا يَكُونُ لَهُ.', 'لاويين 7:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 9, 'وَكُلُّ تَقْدِمَةٍ خُبِزَتْ فِي التَّنُّورِ، وَكُلُّ مَا عُمِلَ فِي طَاجِنٍ أَوْ عَلَى صَاجٍ يَكُونُ لِلْكَاهِنِ الَّذِي يُقَرِّبُهُ.', 'لاويين 7:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 10, 'وَكُلُّ تَقْدِمَةٍ مَلْتُوتَةٍ بِزَيْتٍ أَوْ نَاشِفَةٍ تَكُونُ لِجَمِيعِ بَنِي هَارُونَ، كُلِّ إِنْسَانٍ كَأَخِيهِ.', 'لاويين 7:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 11, '«وَهَذِهِ شَرِيعَةُ ذَبِيحَةِ السَّلَامَةِ. الَّذِي يُقَرِّبُهَا لِلرَّبِّ׃', 'لاويين 7:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 12, 'إِنْ قَرَّبَهَا لِأَجْلِ الشُّكْرِ، يُقَرِّبُ عَلَى ذَبِيحَةِ الشُّكْرِ أَقْرَاصَ فَطِيرٍ مَلْتُوتَةً بِزَيْتٍ، وَرِقَاقَ فَطِيرٍ مَدْهُونَةً بِزَيْتٍ، وَدَقِيقًا مَرْبُوكًا أَقْرَاصًا مَلْتُوتَةً بِزَيْتٍ،', 'لاويين 7:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 13, 'مَعَ أَقْرَاصِ خُبْزٍ خَمِيرٍ يُقَرِّبُ قُرْبَانَهُ عَلَى ذَبِيحَةِ شُكْرِ سَلَامَتِهِ.', 'لاويين 7:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 14, 'وَيُقَرِّبُ مِنْهُ وَاحِدًا مِنْ كُلِّ قُرْبَانٍ رَفِيعَةً لِلرَّبِّ، يَكُونُ لِلْكَاهِنِ الَّذِي يَرُشُّ دَمَ ذَبِيحَةِ السَّلَامَةِ.', 'لاويين 7:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 15, 'وَلَحْمُ ذَبِيحَةِ شُكْرِ سَلَامَتِهِ يُؤْكَلُ يَوْمَ قُرْبَانِهِ. لَا يُبْقِي مِنْهُ شَيْئًا إِلَى الصَّبَاحِ.', 'لاويين 7:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 16, 'وَإِنْ كَانَتْ ذَبِيحَةُ قُرْبَانِهِ نَذْرًا أَوْ نَافِلَةً، فَفِي يَوْمِ تَقْرِيبِهِ ذَبِيحَتَهُ تُؤْكَلُ. وَفِي الْغَدِ يُؤْكَلُ مَا فَضَلَ مِنْهَا.', 'لاويين 7:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 17, 'وَأَمَّا الْفَاضِلُ مِنْ لَحْمِ الذَّبِيحَةِ فِي الْيَوْمِ الثَّالِثِ فَيُحْرَقُ بِالنَّارِ.', 'لاويين 7:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 18, 'وَإِنْ أُكِلَ مِنْ لَحْمِ ذَبِيحَةِ سَلَامَتِهِ فِي الْيَوْمِ الثَّالِثِ لَا تُقْبَلُ. الَّذِي يُقَرِّبُهَا لَا تُحْسَبُ لَهُ، تَكُونُ نَجَاسَةً، وَالنَّفْسُ الَّتِي تَأْكُلُ مِنْهَا تَحْمِلُ ذَنْبَهَا.', 'لاويين 7:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 19, 'وَاللَّحْمُ الَّذِي مَسَّ شَيْئًا مَا نَجِسًا لَا يُؤْكَلُ. يُحْرَقُ بِالنَّارِ. وَاللَّحْمُ يَأْكُلُ كُلُّ طَاهِرٍ مِنْهُ.', 'لاويين 7:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 20, 'وَأَمَّا النَّفْسُ الَّتِي تَأْكُلُ لَحْمًا مِنْ ذَبِيحَةِ السَّلَامَةِ الَّتِي لِلرَّبِّ وَنَجَاسَتُهَا عَلَيْهَا فَتُقْطَعُ تِلْكَ النَّفْسُ مِنْ شَعْبِهَا.', 'لاويين 7:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 21, 'وَالنَّفْسُ الَّتِي تَمَسُّ شَيْئًا مَّا نَجِسًا نَجَاسَةَ إِنْسَانٍ أَوْ بَهِيمَةً نَجِسَةً أَوْ مَكْرُوهًا مَّا نَجِسًا، ثُمَّ تَأْكُلُ مِنْ لَحْمِ ذَبِيحَةِ السَّلَامَةِ الَّتِي لِلرَّبِّ، تُقْطَعُ تِلْكَ النَّفْسُ مِنْ شَعْبِهَا».', 'لاويين 7:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 22, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 7:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 23, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ كُلَّ شَحْمِ ثَوْرٍ أَوْ كَبْشٍ أَوْ مَاعِزٍ لَا تَأْكُلُوا.', 'لاويين 7:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 24, 'وَأَمَّا شَحْمُ الْمَيْتَةِ وَشَحْمُ الْمُفْتَرَسَةِ فَيُسْتَعْمَلُ لِكُلِّ عَمَلٍ، لَكِنْ أَكْلًا لَا تَأْكُلُوهُ.', 'لاويين 7:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 25, 'إِنَّ كُلَّ مَنْ أَكَلَ شَحْمًا مِنَ الْبَهَائِمِ الَّتِي يُقَرِّبُ مِنْهَا وَقُودًا لِلرَّبِّ تُقْطَعُ مِنْ شَعْبِهَا، النَّفْسُ الَّتِي تَأْكُلُ.', 'لاويين 7:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 26, 'وَكُلَّ دَمٍ لَا تَأْكُلُوا فِي جَمِيعِ مَسَاكِنِكُمْ مِنَ الطَّيْرِ وَمِنَ الْبَهَائِمِ.', 'لاويين 7:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 27, 'كُلُّ نَفْسٍ تَأْكُلُ شَيْئًا مِنَ الدَّمِ تُقْطَعُ تِلْكَ النَّفْسُ مِنْ شَعْبِهَا».', 'لاويين 7:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 28, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 7:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 29, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ الَّذِي يُقَرِّبُ ذَبِيحَةَ سَلَامَتِهِ لِلرَّبِّ، يَأْتِي بِقُرْبَانِهِ إِلَى الرَّبِّ مِنْ ذَبِيحَةِ سَلَامَتِهِ.', 'لاويين 7:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 30, 'يَدَاهُ تَأْتِيَانِ بِوَقَائِدِ الرَّبِّ. الشَّحْمُ يَأْتِي بِهِ مَعَ الصَّدْرِ. أَمَّا الصَّدْرُ فَلِكَيْ يُرَدِّدَهُ تَرْدِيدًا أَمَامَ الرَّبِّ.', 'لاويين 7:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 31, 'فَيُوقِدُ الْكَاهِنُ الشَّحْمَ عَلَى الْمَذْبَحِ، وَيَكُونُ الصَّدْرُ لِهَارُونَ وَبَنِيهِ.', 'لاويين 7:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 32, 'وَالسَّاقُ الْيُمْنَى تُعْطُونَهَا رَفِيعَةً لِلْكَاهِنِ مِنْ ذَبَائِحِ سَلَامَتِكُمْ.', 'لاويين 7:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 33, 'اَلَّذِي يُقَرِّبُ دَمَ ذَبِيحَةِ السَّلَامَةِ وَالشَّحْمَ مِنْ بَنِي هَارُونَ، تَكُونُ لَهُ السَّاقُ الْيُمْنَى نَصِيبًا،', 'لاويين 7:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 34, 'لِأَنَّ صَدْرَ التَّرْدِيدِ وَسَاقَ الرَّفِيعَةِ قَدْ أَخَذْتُهُمَا مِنْ بَنِي إِسْرَائِيلَ مِنْ ذَبَائِحِ سَلَامَتِهِمْ وَأَعْطَيْتُهُمَا لِهَارُونَ الْكَاهِنِ وَلِبَنِيهِ فَرِيضَةً دَهْرِيَّةً مِنْ بَنِي إِسْرَائِيلَ».', 'لاويين 7:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 35, 'تِلْكَ مَسْحَةُ هَارُونَ وَمَسْحَةُ بَنِيهِ مِنْ وَقَائِدِ الرَّبِّ يَوْمَ تَقْدِيمِهِمْ لِيَكْهَنُوا لِلرَّبِّ،', 'لاويين 7:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 36, 'الَّتِي أَمَرَ الرَّبُّ أَنْ تُعْطَى لَهُمْ يَوْمَ مَسْحِهِ إِيَّاهُمْ مِنْ بَنِي إِسْرَائِيلَ، فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِهِمْ.', 'لاويين 7:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 37, 'تِلْكَ شَرِيعَةُ الْمُحْرَقَةِ، وَالتَّقْدِمَةِ، وَذَبِيحَةِ الْخَطِيَّةِ، وَذَبِيحَةِ الْإِثْمِ، وَذَبِيحَةِ الْمِلْءِ، وَذَبِيحَةِ السَّلَامَةِ،', 'لاويين 7:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 7, 38, 'الَّتِي أَمَرَ الرَّبُّ بِهَا مُوسَى فِي جَبَلِ سِينَاءَ، يَوْمَ أَمْرِهِ بَنِي إِسْرَائِيلَ بِتَقْرِيبِ قَرَابِينِهِمْ لِلرَّبِّ فِي بَرِّيَّةِ سِينَاءَ.', 'لاويين 7:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 8:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 2, '«خُذْ هَارُونَ وَبَنِيهِ مَعَهُ، وَالثِّيَابَ وَدُهْنَ الْمَسْحَةِ وَثَوْرَ الْخَطِيَّةِ وَالْكَبْشَيْنِ وَسَلَّ الْفَطِيرِ،', 'لاويين 8:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 3, 'وَاجْمَعْ كُلَّ الْجَمَاعَةِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ».', 'لاويين 8:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 4, 'فَفَعَلَ مُوسَى كَمَا أَمَرَهُ الرَّبُّ. فَاجْتَمَعَتِ الْجَمَاعَةُ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 8:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 5, 'ثُمَّ قَالَ مُوسَى لِلْجَمَاعَةِ׃ «هَذَا مَا أَمَرَ الرَّبُّ أَنْ يُفْعَلَ».', 'لاويين 8:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 6, 'فَقَدَّمَ مُوسَى هَارُونَ وَبَنِيهِ وَغَسَّلَهُمْ بِمَاءٍ.', 'لاويين 8:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 7, 'وَجَعَلَ عَلَيْهِ الْقَمِيصَ وَنَطَّقَهُ بِالْمِنْطَقَةِ وَأَلْبَسَهُ الْجُبَّةَ وَجَعَلَ عَلَيْهِ الرِّدَاءَ، وَنَطَّقَهُ بِزُنَّارِ الرِّدَاءِ وَشَدَّهُ بِهِ.', 'لاويين 8:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 8, 'وَوَضَعَ عَلَيْهِ الصُّدْرَةَ وَجَعَلَ فِي الصُّدْرَةِ الْأُورِيمَ وَالتُّمِّيمَ.', 'لاويين 8:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 9, 'وَوَضَعَ الْعِمَامَةَ عَلَى رَأْسِهِ، وَوَضَعَ عَلَى الْعِمَامَةِ إِلَى جِهَةِ وَجْهِهِ صَفِيحَةَ الذَّهَبِ، الْإِكْلِيلَ الْمُقَدَّسَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 8:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 10, 'ثُمَّ أَخَذَ مُوسَى دُهْنَ الْمَسْحَةِ وَمَسَحَ الْمَسْكَنَ وَكُلَّ مَا فِيهِ وَقَدَّسَهُ،', 'لاويين 8:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 11, 'وَنَضَحَ مِنْهُ عَلَى الْمَذْبَحِ سَبْعَ مَرَّاتٍ، وَمَسَحَ الْمَذْبَحَ وَجَمِيعَ آنِيَتِهِ، وَالْمِرْحَضَةَ وَقَاعِدَتَهَا لِتَقْدِيسِهَا.', 'لاويين 8:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 12, 'وَصَبَّ مِنْ دُهْنِ الْمَسْحَةِ عَلَى رَأْسِ هَارُونَ وَمَسَحَهُ لِتَقْدِيسِهِ.', 'لاويين 8:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 13, 'ثُمَّ قَدَّمَ مُوسَى بَنِي هَارُونَ وَأَلْبَسَهُمْ أَقْمِصَةً وَنَطَّقَهُمْ بِمَنَاطِقَ وَشَدَّ لَهُمْ قَلَانِسَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 8:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 14, 'ثُمَّ قَدَّمَ ثَوْرَ الْخَطِيَّةِ، وَوَضَعَ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ ثَوْرِ الْخَطِيَّةِ.', 'لاويين 8:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 15, 'فَذَبَحَهُ، وَأَخَذَ مُوسَى الدَّمَ وَجَعَلَهُ عَلَى قُرُونِ الْمَذْبَحِ مُسْتَدِيرًا بِإِصْبَعِهِ، وَطَهَّرَ الْمَذْبَحَ. ثُمَّ صَبَّ الدَّمَ إِلَى أَسْفَلِ الْمَذْبَحِ وَقَدَّسَهُ تَكْفِيرًا عَنْهُ.', 'لاويين 8:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 16, 'وَأَخَذَ كُلَّ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ وَزِيَادَةَ الْكَبِدِ وَالْكُلْيَتَيْنِ وَشَحْمَهُمَا، وَأَوْقَدَهُ مُوسَى عَلَى الْمَذْبَحِ.', 'لاويين 8:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 17, 'وَأَمَّا الثَّوْرُ׃ جِلْدُهُ وَلَحْمُهُ وَفَرْثُهُ، فَأَحْرَقَهُ بِنَارٍ خَارِجَ الْمَحَلَّةِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 8:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 18, 'ثُمَّ قَدَّمَ كَبْشَ الْمُحْرَقَةِ، فَوَضَعَ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ الْكَبْشِ.', 'لاويين 8:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 19, 'فَذَبَحَهُ، وَرَشَّ مُوسَى الدَّمَ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 8:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 20, 'وَقَطَّعَ الْكَبْشَ إِلَى قِطَعِهِ. وَأَوْقَدَ مُوسَى الرَّأْسَ وَالْقِطَعَ وَالشَّحْمَ.', 'لاويين 8:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 21, 'وَأَمَّا الْأَحْشَاءُ وَالْأَكَارِعُ فَغَسَلَهَا بِمَاءٍ، وَأَوْقَدَ مُوسَى كُلَّ الْكَبْشِ عَلَى الْمَذْبَحِ. إِنَّهُ مُحْرَقَةٌ لِرَائِحَةِ سَرُورٍ. وَقُودٌ هُوَ لِلرَّبِّ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 8:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 22, 'ثُمَّ قَدَّمَ الْكَبْشَ الثَّانِي، كَبْشَ الْمَلْءِ، فَوَضَعَ هَارُونُ وَبَنُوهُ أَيْدِيَهُمْ عَلَى رَأْسِ الْكَبْشِ.', 'لاويين 8:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 23, 'فَذَبَحَهُ، وَأَخَذَ مُوسَى مِنْ دَمِهِ وَجَعَلَ عَلَى شَحْمَةِ أُذُنِ هَارُونَ الْيُمْنَى، وَعَلَى إِبْهَامِ يَدِهِ الْيُمْنَى، وَعَلَى إِبْهَامِ رِجْلِهِ الْيُمْنَى.', 'لاويين 8:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 24, 'ثُمَّ قَدَّمَ مُوسَى بَنِي هَارُونَ وَجَعَلَ مِنَ الدَّمِ عَلَى شَحْمِ آذَانِهِمِ الْيُمْنَى، وَعَلَى أَبَاهِمِ أَيْدِيهِمِ الْيُمْنَى، وَعَلَى أَبَاهِمِ أَرْجُلِهِمِ الْيُمْنَى، ثُمَّ رَشَّ مُوسَى الدَّمَ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 8:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 25, 'ثُمَّ أَخَذَ الشَّحْمَ׃ الْأَلْيَةَ وَكُلَّ الشَّحْمِ الَّذِي عَلَى الْأَحْشَاءِ، وَزِيَادَةَ الْكَبِدِ وَالْكُلْيَتَيْنِ وَشَحْمَهُمَا، وَالسَّاقَ الْيُمْنَى،', 'لاويين 8:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 26, 'وَمِنْ سَلِّ الْفَطِيرِ الَّذِي أَمَامَ الرَّبِّ، أَخَذَ قُرْصًا وَاحِدًا فَطِيرًا، وَقُرْصًا وَاحِدًا مِنَ الْخُبْزِ بِزَيْتٍ، وَرُقَاقَةً وَاحِدَةً، وَوَضَعَهَا عَلَى الشَّحْمِ وَعَلَى السَّاقِ الْيُمْنَى،', 'لاويين 8:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 27, 'وَجَعَلَ الْجَمِيعَ عَلَى كَفَّيْ هَارُونَ وَكُفُوفِ بَنِيهِ، وَرَدَّدَهَا تَرْدِيدًا أَمَامَ الرَّبِّ.', 'لاويين 8:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 28, 'ثُمَّ أَخَذَهَا مُوسَى عَنْ كُفُوفِهِمْ، وَأَوْقَدَهَا عَلَى الْمَذْبَحِ فَوْقَ الْمُحْرَقَةِ. إِنَّهَا قُرْبَانُ مَلْءٍ لِرَائِحَةِ سَرُورٍ. وَقُودٌ هِيَ لِلرَّبِّ.', 'لاويين 8:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 29, 'ثُمَّ أَخَذَ مُوسَى الصَّدْرَ وَرَدَّدَهُ تَرْدِيدًا أَمَامَ الرَّبِّ مِنْ كَبْشِ الْمَلْءِ. لِمُوسَى كَانَ نَصِيبًا، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 8:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 30, 'ثُمَّ أَخَذَ مُوسَى مِنْ دُهْنِ الْمَسْحَةِ وَمِنَ الدَّمِ الَّذِي عَلَى الْمَذْبَحِ، وَنَضَحَ عَلَى هَارُونَ وَعَلَى ثِيَابِهِ، وَعَلَى بَنِيهِ وَعَلَى ثِيَابِ بَنِيهِ مَعَهُ. وَقَدَّسَ هَارُونَ وَثِيَابَهُ وَبَنِيهِ وَثِيَابَ بَنِيهِ مَعَهُ.', 'لاويين 8:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 31, 'ثُمَّ قَالَ مُوسَى لِهَارُونَ وَبَنِيهِ׃ «اطْبُخُوا اللَّحْمَ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ، وَهُنَاكَ تَأْكُلُونَهُ وَالْخُبْزَ الَّذِي فِي سَلِّ قُرْبَانِ الْمَلْءِ، كَمَا أَمَرْتُ قَائِلًا׃ هَارُونُ وَبَنُوهُ يَأْكُلُونَهُ.', 'لاويين 8:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 32, 'وَالْبَاقِي مِنَ اللَّحْمِ وَالْخُبْزِ تُحْرِقُونَهُ بِالنَّارِ.', 'لاويين 8:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 33, 'وَمِنْ لَدُنْ بَابِ خَيْمَةِ الِاجْتِمَاعِ، لَا تَخْرُجُونَ سَبْعَةَ أَيَّامٍ إِلَى يَوْمِ كَمَالِ أَيَّامِ مَلْئِكُمْ، لِأَنَّهُ سَبْعَةَ أَيَّامٍ يَمْلَأُ أَيْدِيَكُمْ.', 'لاويين 8:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 34, 'كَمَا فَعَلَ فِي هَذَا الْيَوْمِ، قَدْ أَمَرَ الرَّبُّ أَنْ يُفْعَلَ لِلتَّكْفِيرِ عَنْكُمْ.', 'لاويين 8:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 35, 'وَلَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ تُقِيمُونَ نَهَارًا وَلَيْلًا سَبْعَةَ أَيَّامٍ، وَتَحْفَظُونَ شَعَائِرَ الرَّبِّ فَلَا تَمُوتُونَ، لِأَنِّي هَكَذَا أُمِرْتُ».', 'لاويين 8:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 8, 36, 'فَعَمِلَ هَارُونُ وَبَنُوهُ كُلَّ مَا أَمَرَ بِهِ الرَّبُّ عَلَى يَدِ مُوسَى.', 'لاويين 8:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 1, 'وَفِي الْيَوْمِ الثَّامِنِ دَعَا مُوسَى هَارُونَ وَبَنِيهِ وَشُيُوخَ إِسْرَائِيلَ.', 'لاويين 9:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 2, 'وَقَالَ لِهَارُونَ׃ «خُذْ لَكَ عِجْلًا ابْنَ بَقَرٍ لِذَبِيحَةِ خَطِيَّةٍ، وَكَبْشًا لِمُحْرَقَةٍ صَحِيحَيْنِ، وَقَدِّمْهُمَا أَمَامَ الرَّبِّ.', 'لاويين 9:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 3, 'وَكَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ خُذُوا تَيْسًا مِنَ الْمَعْزِ لِذَبِيحَةِ خَطِيَّةٍ، وَعِجْلًا وَخَرُوفًا حَوْلِيَّيْنِ صَحِيحَيْنِ لِمُحْرَقَةٍ،', 'لاويين 9:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 4, 'وَثَوْرًا وَكَبْشًا لِذَبِيحَةِ سَلَامَةٍ لِلذَّبْحِ أَمَامَ الرَّبِّ، وَتَقْدِمَةً مَلْتُوتَةً بِزَيْتٍ. لِأَنَّ الرَّبَّ الْيَوْمَ يَتَرَاءَى لَكُمْ».', 'لاويين 9:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 5, 'فَأَخَذُوا مَا أَمَرَ بِهِ مُوسَى إِلَى قُدَّامِ خَيْمَةِ الِاجْتِمَاعِ. وَتَقَدَّمَ كُلُّ الْجَمَاعَةِ وَوَقَفُوا أَمَامَ الرَّبِّ.', 'لاويين 9:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 6, 'فَقَالَ مُوسَى׃ «هَذَا مَا أَمَرَ بِهِ الرَّبُّ. تَعْمَلُونَهُ فَيَتَرَاءَى لَكُمْ مَجْدُ الرَّبِّ».', 'لاويين 9:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 7, 'ثُمَّ قَالَ مُوسَى لِهَارُونَ׃ «تَقَدَّمْ إِلَى الْمَذْبَحِ وَاعْمَلْ ذَبِيحَةَ خَطِيَّتِكَ وَمُحْرَقَتَكَ، وَكَفِّرْ عَنْ نَفْسِكَ وَعَنِ الشَّعْبِ. وَاعْمَلْ قُرْبَانَ الشَّعْبِ وَكَفِّرْ عَنْهُمْ كَمَا أَمَرَ الرَّبُّ».', 'لاويين 9:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 8, 'فَتَقَدَّمَ هَارُونُ إِلَى الْمَذْبَحِ وَذَبَحَ عِجْلَ الْخَطِيَّةِ الَّذِي لَهُ.', 'لاويين 9:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 9, 'وَقَدَّمَ بَنُو هَارُونَ إِلَيْهِ الدَّمَ، فَغَمَسَ إِصْبَعَهُ فِي الدَّمِ وَجَعَلَ عَلَى قُرُونِ الْمَذْبَحِ، ثُمَّ صَبَّ الدَّمَ إِلَى أَسْفَلِ الْمَذْبَحِ.', 'لاويين 9:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 10, 'وَالشَّحْمَ وَالْكُلْيَتَيْنِ وَزِيَادَةَ الْكَبِدِ مِنْ ذَبِيحَةِ الْخَطِيَّةِ أَوْقَدَهَا عَلَى الْمَذْبَحِ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 9:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 11, 'وَأَمَّا اللَّحْمُ وَالْجِلْدُ فَأَحْرَقَهُمَا بِنَارٍ خَارِجَ الْمَحَلَّةِ.', 'لاويين 9:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 12, 'ثُمَّ ذَبَحَ الْمُحْرَقَةَ، فَنَاوَلَهُ بَنُو هَارُونَ الدَّمَ، فَرَشَّهُ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 9:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 13, 'ثُمَّ نَاوَلُوهُ الْمُحْرَقَةَ بِقِطَعِهَا وَالرَّأْسَ، فَأَوْقَدَهَا عَلَى الْمَذْبَحِ.', 'لاويين 9:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 14, 'وَغَسَّلَ الْأَحْشَاءَ وَالْأَكَارِعَ وَأَوْقَدَهَا فَوْقَ الْمُحْرَقَةِ عَلَى الْمَذْبَحِ.', 'لاويين 9:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 15, 'ثُمَّ قَدَّمَ قُرْبَانَ الشَّعْبِ، وَأَخَذَ تَيْسَ الْخَطِيَّةِ الَّذِي لِلشَّعْبِ وَذَبَحَهُ وَعَمِلَهُ لِلْخَطِيَّةِ كَالْأَوَّلِ.', 'لاويين 9:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 16, 'ثُمَّ قَدَّمَ الْمُحْرَقَةَ وَعَمِلَهَا كَالْعَادَةِ.', 'لاويين 9:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 17, 'ثُمَّ قَدَّمَ التَّقْدِمَةَ وَمَلَأَ كَفَّهُ مِنْهَا، وَأَوْقَدَهَا عَلَى الْمَذْبَحِ، عَدَا مُحْرَقَةِ الصَّبَاحِ.', 'لاويين 9:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 18, 'ثُمَّ ذَبَحَ الثَّوْرَ وَالْكَبْشَ ذَبِيحَةَ السَّلَامَةِ الَّتِي لِلشَّعْبِ. وَنَاوَلَهُ بَنُو هَارُونَ الدَّمَ فَرَشَّهُ عَلَى الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 9:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 19, 'وَالشَّحْمَ مِنَ الثَّوْرِ وَمِنَ الْكَبْشِ׃ الْأَلْيَةَ وَمَا يُغَشِّي، وَالْكُلْيَتَيْنِ وَزِيَادَةَ الْكَبِدِ.', 'لاويين 9:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 20, 'وَوَضَعُوا الشَّحْمَ عَلَى الصَّدْرَيْنِ، فَأَوْقَدَ الشَّحْمَ عَلَى الْمَذْبَحِ.', 'لاويين 9:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 21, 'وَأَمَّا الصَّدْرَانِ وَالسَّاقُ الْيُمْنَى فَرَدَّدَهَا هَارُونُ تَرْدِيدًا أَمَامَ الرَّبِّ، كَمَا أَمَرَ مُوسَى.', 'لاويين 9:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 22, 'ثُمَّ رَفَعَ هَارُونُ يَدَهُ نَحْوَ الشَّعْبِ وَبَارَكَهُمْ، وَانْحَدَرَ مِنْ عَمَلِ ذَبِيحَةِ الْخَطِيَّةِ وَالْمُحْرَقَةِ وَذَبِيحَةِ السَّلَامَةِ.', 'لاويين 9:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 23, 'وَدَخَلَ مُوسَى وَهَارُونُ إِلَى خَيْمَةِ الِاجْتِمَاعِ، ثُمَّ خَرَجَا وَبَارَكَا الشَّعْبَ، فَتَرَاءَى مَجْدُ الرَّبِّ لِكُلِّ الشَّعْبِ', 'لاويين 9:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 9, 24, 'وَخَرَجَتْ نَارٌ مِنْ عِنْدِ الرَّبِّ وَأَحْرَقَتْ عَلَى الْمَذْبَحِ الْمُحْرَقَةَ وَالشَّحْمَ. فَرَأَى جَمِيعُ الشَّعْبِ وَهَتَفُوا وَسَقَطُوا عَلَى وُجُوهِهِمْ.', 'لاويين 9:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 1, 'وَأَخَذَ ابْنَا هَارُونَ׃ نَادَابُ وَأَبِيهُو، كُلٌّ مِنْهُمَا مِجْمَرَتَهُ وَجَعَلَا فِيهِمَا نَارًا وَوَضَعَا عَلَيْهَا بَخُورًا، وَقَرَّبَا أَمَامَ الرَّبِّ نَارًا غَرِيبَةً لَمْ يَأْمُرْهُمَا بِهَا.', 'لاويين 10:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 2, 'فَخَرَجَتْ نَارٌ مِنْ عِنْدِ الرَّبِّ وَأَكَلَتْهُمَا، فَمَاتَا أَمَامَ الرَّبِّ.', 'لاويين 10:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 3, 'فَقَالَ مُوسَى لِهَارُونَ׃ «هَذَا مَا تَكَلَّمَ بِهِ الرَّبُّ قَائِلًا׃ فِي الْقَرِيبِينَ مِنِّي أَتَقَدَّسُ، وَأَمَامَ جَمِيعِ الشَّعْبِ أَتَمَجَّدُ». فَصَمَتَ هَارُونُ.', 'لاويين 10:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 4, 'فَدَعَا مُوسَى مِيشَائِيلَ وَأَلْصَافَانَ ابْنَيْ عُزِّيئِيلَ عَمِّ هَارُونَ، وَقَالَ لَهُمَا׃ «تَقَدَّمَا ارْفَعَا أَخَوَيْكُمَا مِنْ قُدَّامِ الْقُدْسِ إِلَى خَارِجِ الْمَحَلَّةِ».', 'لاويين 10:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 5, 'فَتَقَدَّمَا وَرَفَعَاهُمَا فِي قَمِيصَيْهِمَا إِلَى خَارِجِ الْمَحَلَّةِ، كَمَا قَالَ مُوسَى.', 'لاويين 10:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 6, 'وَقَالَ مُوسَى لِهَارُونَ وَأَلِعَازَارَ وَإِيثَامَارَ ابْنَيْهِ׃ «لَا تَكْشِفُوا رُؤُوسَكُمْ وَلَا تَشُقُّوا ثِيَابَكُمْ لِئَلَّا تَمُوتُوا، وَيُسْخَطَ عَلَى كُلِّ الْجَمَاعَةِ. وَأَمَّا إِخْوَتُكُمْ كُلُّ بَيْتِ إِسْرَائِيلَ فَيَبْكُونَ عَلَى الْحَرِيقِ الَّذِي أَحْرَقَهُ الرَّبُّ.', 'لاويين 10:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 7, 'وَمِنْ بَابِ خَيْمَةِ الِاجْتِمَاعِ لَا تَخْرُجُوا لِئَلَّا تَمُوتُوا، لِأَنَّ دُهْنَ مَسْحَةِ الرَّبِّ عَلَيْكُمْ». فَفَعَلُوا حَسَبَ كَلَامِ مُوسَى.', 'لاويين 10:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 8, 'وَكَلَّمَ الرَّبُّ هَارُونَ قَائِلًا׃', 'لاويين 10:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 9, '«خَمْرًا وَمُسْكِرًا لَا تَشْرَبْ أَنْتَ وَبَنُوكَ مَعَكَ عِنْدَ دُخُولِكُمْ إِلَى خَيْمَةِ الِاجْتِمَاعِ لِكَيْ لَا تَمُوتُوا. فَرْضًا دَهْرِيًّا فِي أَجْيَالِكُمْ', 'لاويين 10:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 10, 'وَلِلتَّمْيِيزِ بَيْنَ الْمُقَدَّسِ وَالْمُحَلَّلِ وَبَيْنَ النَّجِسِ وَالطَّاهِرِ،', 'لاويين 10:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 11, 'وَلِتَعْلِيمِ بَنِي إِسْرَائِيلَ جَمِيعَ الْفَرَائِضِ الَّتِي كَلَّمَهُمُ الرَّبُّ بِهَا بِيَدِ مُوسَى».', 'لاويين 10:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 12, 'وَقَالَ مُوسَى لِهَارُونَ وَأَلِعَازَارَ وَإِيثَامَارَ ابْنَيْهِ الْبَاقِيَيْنِ׃ «خُذُوا التَّقْدِمَةَ الْبَاقِيَةَ مِنْ وَقَائِدِ الرَّبِّ وَكُلُوهَا فَطِيرًا بِجَانِبِ الْمَذْبَحِ لِأَنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 10:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 13, 'كُلُوهَا فِي مَكَانٍ مُقَدَّسٍ لِأَنَّهَا فَرِيضَتُكَ وَفَرِيضَةُ بَنِيكَ مِنْ وَقَائِدِ الرَّبِّ، فَإِنَّنِي هَكَذَا أُمِرْتُ.', 'لاويين 10:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 14, 'وَأَمَّا صَدْرُ التَّرْدِيدِ وَسَاقُ الرَّفِيعَةِ فَتَأْكُلُونَهُمَا فِي مَكَانٍ طَاهِرٍ أَنْتَ وَبَنُوكَ وَبَنَاتُكَ مَعَكَ، لِأَنَّهُمَا جُعِلَا فَرِيضَتَكَ وَفَرِيضَةَ بَنِيكَ مِنْ ذَبَائِحِ سَلَامَةِ بَنِي إِسْرَائِيلَ.', 'لاويين 10:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 15, 'سَاقُ الرَّفِيعَةِ وَصَدْرُ التَّرْدِيدِ يَأْتُونَ بِهِمَا مَعَ وَقَائِدِ الشَّحْمِ لِيُرَدَّدَا تَرْدِيدًا أَمَامَ الرَّبِّ، فَيَكُونَانِ لَكَ وَلِبَنِيكَ مَعَكَ فَرِيضَةً دَهْرِيَّةً، كَمَا أَمَرَ الرَّبُّ».', 'لاويين 10:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 16, 'وَأَمَّا تَيْسُ الْخَطِيَّةِ فَإِنَّ مُوسَى طَلَبَهُ فَإِذَا هُوَ قَدِ احْتَرَقَ. فَسَخِطَ عَلَى أَلِعَازَارَ وَإِيثَامَارَ، ابْنَيْ هَارُونَ الْبَاقِيَيْنِ، وَقَالَ׃', 'لاويين 10:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 17, '«مَا لَكُمَا لَمْ تَأْكُلَا ذَبِيحَةَ الْخَطِيَّةِ فِي الْمَكَانِ الْمُقَدَّسِ؟ لِأَنَّهَا قُدْسُ أَقْدَاسٍ، وَقَدْ أَعْطَاكُمَا إِيَّاهَا لِتَحْمِلَا إِثْمَ الْجَمَاعَةِ تَكْفِيرًا عَنْهُمْ أَمَامَ الرَّبِّ.', 'لاويين 10:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 18, 'إِنَّهُ لَمْ يُؤْتَ بِدَمِهَا إِلَى الْقُدْسِ دَاخِلًا. أَكْلًا تَأْكُلَانِهَا فِي الْقُدْسِ كَمَا أَمَرْتُ».', 'لاويين 10:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 19, 'فَقَالَ هَارُونُ لِمُوسَى׃ «إِنَّهُمَا الْيَوْمَ قَدْ قَرَّبَا ذَبِيحَةَ خَطِيَّتِهِمَا وَمُحْرَقَتَهُمَا أَمَامَ الرَّبِّ، وَقَدْ أَصَابَنِي مِثْلُ هَذِهِ. فَلَوْ أَكَلْتُ ذَبِيحَةَ الْخَطِيَّةِ الْيَوْمَ، هَلْ كَانَ يَحْسُنُ فِي عَيْنَيِ الرَّبِّ؟».', 'لاويين 10:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 10, 20, 'فَلَمَّا سَمِعَ مُوسَى حَسُنَ فِي عَيْنَيْهِ.', 'لاويين 10:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا لَهُمَا׃', 'لاويين 11:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 2, '«كَلِّمَا بَنِي إِسْرَائِيلَ قَائِلَيْنِ׃ هَذِهِ هِيَ الْحَيَوَانَاتُ الَّتِي تَأْكُلُونَهَا مِنْ جَمِيعِ الْبَهَائِمِ الَّتِي عَلَى الْأَرْضِ׃', 'لاويين 11:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 3, 'كُلُّ مَا شَقَّ ظِلْفًا وَقَسَمَهُ ظِلْفَيْنِ، وَيَجْتَرُّ مِنَ الْبَهَائِمِ، فَإِيَّاهُ تَأْكُلُونَ.', 'لاويين 11:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 4, 'إِلَّا هَذِهِ فَلَا تَأْكُلُوهَا مِمَّا يَجْتَرُّ وَمِمَّا يَشُقُّ الظِّلْفَ׃ الْجَمَلَ، لِأَنَّهُ يَجْتَرُّ لَكِنَّهُ لَا يَشُقُّ ظِلْفًا، فَهُوَ نَجِسٌ لَكُمْ.', 'لاويين 11:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 5, 'وَالْوَبْرَ، لِأَنَّهُ يَجْتَرُّ لَكِنَّهُ لَا يَشُقُّ ظِلْفًا، فَهُوَ نَجِسٌ لَكُمْ.', 'لاويين 11:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 6, 'وَالْأَرْنَبَ، لِأَنَّهُ يَجْتَرُّ لَكِنَّهُ لَا يَشُقُّ ظِلْفًا، فَهُوَ نَجِسٌ لَكُمْ.', 'لاويين 11:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 7, 'وَالْخِنْزِيرَ، لِأَنَّهُ يَشُقُّ ظِلْفًا وَيَقْسِمُهُ ظِلْفَيْنِ، لَكِنَّهُ لَا يَجْتَرُّ، فَهُوَ نَجِسٌ لَكُمْ.', 'لاويين 11:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 8, 'مِنْ لَحْمِهَا لَا تَأْكُلُوا وَجُثَثَهَا لَا تَلْمِسُوا. إِنَّهَا نَجِسَةٌ لَكُمْ.', 'لاويين 11:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 9, '«وَهَذَا تَأْكُلُونَهُ مِنْ جَمِيعِ مَا فِي الْمِيَاهِ׃ كُلُّ مَا لَهُ زَعَانِفُ وَحَرْشَفٌ فِي الْمِيَاهِ، فِي الْبِحَارِ وَفِي الْأَنْهَارِ، فَإِيَّاهُ تَأْكُلُونَ.', 'لاويين 11:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 10, 'لَكِنْ كُلُّ مَا لَيْسَ لَهُ زَعَانِفُ وَحَرْشَفٌ فِي الْبِحَارِ وَفِي الْأَنْهَارِ، مِنْ كُلِّ دَبِيبٍ فِي الْمِيَاهِ وَمِنْ كُلِّ نَفْسٍ حَيَّةٍ فِي الْمِيَاهِ، فَهُوَ مَكْرُوهٌ لَكُمْ،', 'لاويين 11:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 11, 'وَمَكْرُوهًا يَكُونُ لَكُمْ. مِنْ لَحْمِهِ لَا تَأْكُلُوا، وَجُثَّتَهُ تَكْرَهُونَ.', 'لاويين 11:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 12, 'كُلُّ مَا لَيْسَ لَهُ زَعَانِفُ وَحَرْشَفٌ فِي الْمِيَاهِ فَهُوَ مَكْرُوهٌ لَكُمْ.', 'لاويين 11:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 13, '«وَهَذِهِ تَكْرَهُونَهَا مِنَ الطُّيُورِ. لَا تُؤْكَلْ. إِنَّهَا مَكْرُوهَةٌ׃ اَلنَّسْرُ وَالْأَنُوقُ وَالْعُقَابُ', 'لاويين 11:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 14, 'وَالْحِدَأَةُ وَالْبَاشِقُ عَلَى أَجْنَاسِهِ،', 'لاويين 11:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 15, 'وَكُلُّ غُرَابٍ عَلَى أَجْنَاسِهِ،', 'لاويين 11:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 16, 'وَالنَّعَامَةُ وَالظَّلِيمُ وَالسَّأَفُ وَالْبَازُ عَلَى أَجْنَاسِهِ،', 'لاويين 11:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 17, 'وَالْبُومُ وَالْغَوَّاصُ وَالْكُرْكِيُّ', 'لاويين 11:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 18, 'وَالْبَجَعُ وَالْقُوقُ وَالرَّخَمُ', 'لاويين 11:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 19, 'وَاللَّقْلَقُ وَالْبَبْغَا عَلَى أَجْنَاسِهِ، وَالْهُدْهُدُ وَالْخُفَّاشُ.', 'لاويين 11:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 20, 'وَكُلُّ دَبِيبِ الطَّيْرِ الْمَاشِي عَلَى أَرْبَعٍ. فَهُوَ مَكْرُوهٌ لَكُمْ.', 'لاويين 11:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 21, 'إِلَّا هَذَا تَأْكُلُونَهُ مِنْ جَمِيعِ دَبِيبِ الطَّيْرِ الْمَاشِي عَلَى أَرْبَعٍ׃ مَا لَهُ كُرَاعَانِ فَوْقَ رِجْلَيْهِ يَثِبُ بِهِمَا عَلَى الْأَرْضِ.', 'لاويين 11:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 22, 'هَذَا مِنْهُ تَأْكُلُونَ׃ الْجَرَادُ عَلَى أَجْنَاسِهِ، وَالدَّبَا عَلَى أَجْنَاسِهِ، وَالْحَرْجُوانُ عَلَى أَجْنَاسِهِ، وَالْجُنْدُبُ عَلَى أَجْنَاسِهِ.', 'لاويين 11:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 23, 'لَكِنْ سَائِرُ دَبِيبِ الطَّيْرِ الَّذِي لَهُ أَرْبَعُ أَرْجُلٍ فَهُوَ مَكْرُوهٌ لَكُمْ.', 'لاويين 11:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 24, 'مِنْ هَذِهِ تَتَنَجَّسُونَ. كُلُّ مَنْ مَسَّ جُثَثَهَا يَكُونُ نَجِسًا إِلَى الْمَسَاءِ،', 'لاويين 11:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 25, 'وَكُلُّ مَنْ حَمَلَ مِنْ جُثَثِهَا يَغْسِلُ ثِيَابَهُ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 11:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 26, 'وَجَمِيعُ الْبَهَائِمِ الَّتِي لَهَا ظِلْفٌ وَلَكِنْ لَا تَشُقُّهُ شَقًّا أَوْ لَا تَجْتَرُّ، فَهِيَ نَجِسَةٌ لَكُمْ. كُلُّ مَنْ مَسَّهَا يَكُونُ نَجِسًا.', 'لاويين 11:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 27, 'وَكُلُّ مَا يَمْشِي عَلَى كُفُوفِهِ مِنْ جَمِيعِ الْحَيَوَانَاتِ الْمَاشِيَةِ عَلَى أَرْبَعٍ، فَهُوَ نَجِسٌ لَكُمْ. كُلُّ مَنْ مَسَّ جُثَثَهَا يَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 11:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 28, 'وَمَنْ حَمَلَ جُثَثَهَا يَغْسِلُ ثِيَابَهُ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ. إِنَّهَا نَجِسَةٌ لَكُمْ.', 'لاويين 11:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 29, '«وَهَذَا هُوَ النَّجِسُ لَكُمْ مِنَ الدَّبِيبِ الَّذِي يَدِبُّ عَلَى الْأَرْضِ׃ اِبْنُ عِرْسٍ وَالْفَأْرُ وَالضَّبُّ عَلَى أَجْنَاسِهِ،', 'لاويين 11:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 30, 'وَالْحِرْذَوْنُ وَالْوَرَلُ وَالْوَزَغَةُ وَالْعِظَايَةُ وَالْحِرْبَاءُ.', 'لاويين 11:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 31, 'هَذِهِ هِيَ النَّجِسَةُ لَكُمْ مِنْ كُلِّ الدَّبِيبِ. كُلُّ مَنْ مَسَّهَا بَعْدَ مَوْتِهَا يَكُونُ نَجِسًا إِلَى الْمَسَاءِ،', 'لاويين 11:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 32, 'وَكُلُّ مَا وَقَعَ عَلَيْهِ وَاحِدٌ مِنْهَا بَعْدَ مَوْتِهَا يَكُونُ نَجِسًا. مِنْ كُلِّ مَتَاعِ خَشَبٍ أَوْ ثَوْبٍ أَوْ جِلْدٍ أَوْ بَلَاسٍ. كُلُّ مَتَاعٍ يُعْمَلُ بِهِ عَمَلٌ يُلْقَى فِي الْمَاءِ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ ثُمَّ يَطْهُرُ.', 'لاويين 11:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 33, 'وَكُلُّ مَتَاعِ خَزَفٍ وَقَعَ فِيهِ مِنْهَا، فَكُلُّ مَا فِيهِ يَتَنَجَّسُ، وَأَمَّا هُوَ فَتَكْسِرُونَهُ.', 'لاويين 11:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 34, 'مَا يَأْتِي عَلَيْهِ مَاءٌ مِنْ كُلِّ طَعَامٍ يُؤْكَلُ يَكُونُ نَجِسًا. وَكُلُّ شَرَابٍ يُشْرَبُ فِي كُلِّ مَتَاعٍ يَكُونُ نَجِسًا.', 'لاويين 11:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 35, 'وَكُلُّ مَا وَقَعَ عَلَيْهِ وَاحِدَةٌ مِنْ جُثَثِهَا يَكُونُ نَجِسًا. اَلتَّنُّورُ وَالْمَوْقِدَةُ يُهْدَمَانِ. إِنَّهَا نَجِسَةٌ وَتَكُونُ نَجِسَةً لَكُمْ.', 'لاويين 11:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 36, 'إِلَّا الْعَيْنَ وَالْبِئْرَ، مُجْتَمَعَيِ الْمَاءِ، تَكُونَانِ طَاهِرَتَيْنِ. لَكِنْ مَا مَسَّ جُثَثَهَا يَكُونُ نَجِسًا.', 'لاويين 11:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 37, 'وَإِذَا وَقَعَتْ وَاحِدَةٌ مِنْ جُثَثِهَا عَلَى شَيْءٍ مِنْ بِزْرِ زَرْعٍ يُزْرَعُ فَهُوَ طَاهِرٌ.', 'لاويين 11:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 38, 'لَكِنْ إِذَا جُعِلَ مَاءٌ عَلَى بِزْرٍ فَوَقَعَ عَلَيْهِ وَاحِدَةٌ مِنْ جُثَثِهَا، فَإِنَّهُ نَجِسٌ لَكُمْ.', 'لاويين 11:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 39, 'وَإِذَا مَاتَ وَاحِدٌ مِنَ الْبَهَائِمِ الَّتِي هِيَ طَعَامٌ لَكُمْ، فَمَنْ مَسَّ جُثَّتَهُ يَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 11:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 40, 'وَمَنْ أَكَلَ مِنْ جُثَّتِهِ يَغْسِلُ ثِيَابَهُ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ. وَمَنْ حَمَلَ جُثَّتَهُ يَغْسِلُ ثِيَابَهُ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 11:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 41, '«وَكُلُّ دَبِيبٍ يَدِبُّ عَلَى الْأَرْضِ فَهُوَ مَكْرُوهٌ لَا يُؤْكَلُ.', 'لاويين 11:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 42, 'كُلُّ مَا يَمْشِي عَلَى بَطْنِهِ، وَكُلُّ مَا يَمْشِي عَلَى أَرْبَعٍ مَعَ كُلِّ مَا كَثُرَتْ أَرْجُلُهُ مِنْ كُلِّ دَبِيبٍ يَدِبُّ عَلَى الْأَرْضِ، لَا تَأْكُلُوهُ لِأَنَّهُ مَكْرُوهٌ.', 'لاويين 11:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 43, 'لَا تُدَنِّسُوا أَنْفُسَكُمْ بِدَبِيبٍ يَدِبُّ، وَلَا تَتَنَجَّسُوا بِهِ، وَلَا تَكُونُوا بِهِ نَجِسِينَ.', 'لاويين 11:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 44, 'إِنِّي أَنَا الرَّبُّ إِلَهُكُمْ فَتَتَقَدَّسُونَ وَتَكُونُونَ قِدِّيسِينَ، لِأَنِّي أَنَا قُدُّوسٌ. وَلَا تُنَجِّسُوا أَنْفُسَكُمْ بِدَبِيبٍ يَدِبُّ عَلَى الْأَرْضِ.', 'لاويين 11:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 45, 'إِنِّي أَنَا الرَّبُّ الَّذِي أَصْعَدَكُمْ مِنْ أَرْضِ مِصْرَ لِيَكُونَ لَكُمْ إِلَهًا. فَتَكُونُونَ قِدِّيسِينَ لِأَنِّي أَنَا قُدُّوسٌ.', 'لاويين 11:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 46, 'هَذِهِ شَرِيعَةُ الْبَهَائِمِ وَالطُّيُورِ وَكُلِّ نَفْسٍ حَيَّةٍ تَسْعَى فِي الْمَاءِ وَكُلِّ نَفْسٍ تَدِبُّ عَلَى الْأَرْضِ،', 'لاويين 11:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 11, 47, 'لِلتَّمْيِيزِ بَيْنَ النَّجِسِ وَالطَّاهِرِ، وَبَيْنَ الْحَيَوَانَاتِ الَّتِي تُؤْكَلُ، وَالْحَيَوَانَاتِ الَّتِي لَا تُؤْكَلُ».', 'لاويين 11:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 12:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ إِذَا حَبِلَتِ امْرَأَةٌ وَوَلَدَتْ ذَكَرًا، تَكُونُ نَجِسَةً سَبْعَةَ أَيَّامٍ. كَمَا فِي أَيَّامِ طَمْثِ عِلَّتِهَا تَكُونُ نَجِسَةً.', 'لاويين 12:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 3, 'وَفِي الْيَوْمِ الثَّامِنِ يُخْتَنُ لَحْمُ غُرْلَتِهِ.', 'لاويين 12:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 4, 'ثُمَّ تُقِيمُ ثَلَاثَةً وَثَلَاثِينَ يَوْمًا فِي دَمِ تَطْهِيرِهَا. كُلَّ شَيْءٍ مُقَدَّسٍ لَا تَمَسَّ، وَإِلَى الْمَقْدِسِ لَا تَجِئْ حَتَّى تَكْمُلَ أَيَّامُ تَطْهِيرِهَا.', 'لاويين 12:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 5, 'وَإِنْ وَلَدَتْ أُنْثَى، تَكُونُ نَجِسَةً أُسْبُوعَيْنِ كَمَا فِي طَمْثِهَا. ثُمَّ تُقِيمُ سِتَّةً وَسِتِّينَ يَوْمًا فِي دَمِ تَطْهِيرِهَا.', 'لاويين 12:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 6, 'وَمَتَى كَمُلَتْ أَيَّامُ تَطْهِيرِهَا لِأَجْلِ ابْنٍ أَوِ ابْنَةٍ، تَأْتِي بِخَرُوفٍ حَوْلِيٍّ مُحْرَقَةً، وَفَرْخِ حَمَامَةٍ أَوْ يَمَامَةٍ ذَبِيحَةَ خَطِيَّةٍ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ، إِلَى الْكَاهِنِ،', 'لاويين 12:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 7, 'فَيُقَدِّمُهُمَا أَمَامَ الرَّبِّ وَيُكَفِّرُ عَنْهَا، فَتَطْهُرُ مِنْ يَنْبُوعِ دَمِهَا. هَذِهِ شَرِيعَةُ الَّتِي تَلِدُ ذَكَرًا أَوْ أُنْثَى.', 'لاويين 12:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 12, 8, 'وَإِنْ لَمْ تَنَلْ يَدُهَا كِفَايَةً لِشَاةٍ تَأْخُذُ يَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ، الْوَاحِدَ مُحْرَقَةً، وَالْآخَرَ ذَبِيحَةَ خَطِيَّةٍ، فَيُكَفِّرُ عَنْهَا الْكَاهِنُ فَتَطْهُرُ».', 'لاويين 12:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'لاويين 13:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 2, '«إِذَا كَانَ إِنْسَانٌ فِي جِلْدِ جَسَدِهِ نَاتِئٌ أَوْ قُوبَاءُ أَوْ لُمْعَةٌ تَصِيرُ فِي جِلْدِ جَسَدِهِ ضَرْبَةَ بَرَصٍ، يُؤْتَى بِهِ إِلَى هَارُونَ الْكَاهِنِ أَوْ إِلَى أَحَدِ بَنِيهِ الْكَهَنَةِ.', 'لاويين 13:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 3, 'فَإِنْ رَأَى الْكَاهِنُ الضَّرْبَةَ فِي جِلْدِ الْجَسَدِ، وَفِي الضَّرْبَةِ شَعَرٌ قَدِ ابْيَضَّ، وَمَنْظَرُ الضَّرْبَةِ أَعْمَقُ مِنْ جِلْدِ جَسَدِهِ، فَهِيَ ضَرْبَةُ بَرَصٍ. فَمَتَى رَآهُ الْكَاهِنُ يَحْكُمُ بِنَجَاسَتِهِ.', 'لاويين 13:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 4, 'لَكِنْ إِنْ كَانَتِ الضَّرْبَةُ لُمْعَةً بَيْضَاءَ فِي جِلْدِ جَسَدِهِ، وَلَمْ يَكُنْ مَنْظَرُهَا أَعْمَقَ مِنَ الْجِلْدِ، وَلَمْ يَبْيَضَّ شَعْرُهَا، يَحْجُزُ الْكَاهِنُ الْمَضْرُوبَ سَبْعَةَ أَيَّامٍ.', 'لاويين 13:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 5, 'فَإِنْ رَآهُ الْكَاهِنُ فِي الْيَوْمِ السَّابِعِ وَإِذَا فِي عَيْنِهِ الضَّرْبَةُ قَدْ وَقَفَتْ، وَلَمْ تَمْتَدَّ الضَّرْبَةُ فِي الْجِلْدِ، يَحْجُزُهُ الْكَاهِنُ سَبْعَةَ أَيَّامٍ ثَانِيَةً.', 'لاويين 13:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 6, 'فَإِنْ رَآهُ الْكَاهِنُ فِي الْيَوْمِ السَّابِعِ ثَانِيَةً وَإِذَا الضَّرْبَةُ كَامِدَةُ اللَّوْنِ، وَلَمْ تَمْتَدَّ الضَّرْبَةُ فِي الْجِلْدِ، يَحْكُمُ الْكَاهِنُ بِطَهَارَتِهِ. إِنَّهَا حَزَازٌ. فَيَغْسِلُ ثِيَابَهُ وَيَكُونُ طَاهِرًا.', 'لاويين 13:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 7, 'لَكِنْ إِنْ كَانَتِ الْقُوبَاءُ تَمْتَدُّ فِي الْجِلْدِ بَعْدَ عَرْضِهِ عَلَى الْكَاهِنِ لِتَطْهِيرِهِ، يُعْرَضُ عَلَى الْكَاهِنِ ثَانِيَةً.', 'لاويين 13:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 8, 'فَإِنْ رَأَى الْكَاهِنُ وَإِذَا الْقُوبَاءُ قَدِ امْتَدَّتْ فِي الْجِلْدِ، يَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا بَرَصٌ.', 'لاويين 13:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 9, '«إِنْ كَانَتْ فِي إِنْسَانٍ ضَرْبَةُ بَرَصٍ فَيُؤْتَى بِهِ إِلَى الْكَاهِنِ.', 'لاويين 13:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 10, 'فَإِنْ رَأَى الْكَاهِنُ وَإِذَا فِي الْجِلْدِ نَاتِئٌ أَبْيَضُ، قَدْ صَيَّرَ الشَّعْرَ أَبْيَضَ، وَفِي النَّاتِئِ وَضَحٌ مِنْ لَحْمٍ حَيٍّ،', 'لاويين 13:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 11, 'فَهُوَ بَرَصٌ مُزْمِنٌ فِي جِلْدِ جَسَدِهِ. فَيَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. لَا يَحْجُزُهُ لِأَنَّهُ نَجِسٌ.', 'لاويين 13:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 12, 'لَكِنْ إِنْ كَانَ الْبَرَصُ قَدْ أَفْرَخَ فِي الْجِلْدِ، وَغَطَّى الْبَرَصُ كُلَّ جِلْدِ الْمَضْرُوبِ مِنْ رَأْسِهِ إِلَى قَدَمَيْهِ حَسَبَ كُلِّ مَا تَرَاهُ عَيْنَا الْكَاهِنِ،', 'لاويين 13:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 13, 'وَرَأَى الْكَاهِنُ وَإِذَا الْبَرَصُ قَدْ غَطَّى كُلَّ جِسْمِهِ، يَحْكُمُ بِطَهَارَةِ الْمَضْرُوبِ. كُلُّهُ قَدِ ابْيَضَّ. إِنَّهُ طَاهِرٌ.', 'لاويين 13:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 14, 'لَكِنْ يَوْمَ يُرَى فِيهِ لَحْمٌ حَيٌّ يَكُونُ نَجِسًا.', 'لاويين 13:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 15, 'فَمَتَى رَأَى الْكَاهِنُ اللَّحْمَ الْحَيَّ يَحْكُمُ بِنَجَاسَتِهِ. اللَّحْمُ الْحَيُّ نَجِسٌ. إِنَّهُ بَرَصٌ.', 'لاويين 13:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 16, 'ثُمَّ إِنْ عَادَ اللَّحْمُ الْحَيُّ وَابْيَضَّ يَأْتِي إِلَى الْكَاهِنِ.', 'لاويين 13:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 17, 'فَإِنْ رَآهُ الْكَاهِنُ وَإِذَا الضَّرْبَةُ قَدْ صَارَتْ بَيْضَاءَ، يَحْكُمُ الْكَاهِنُ بِطَهَارَةِ الْمَضْرُوبِ. إِنَّهُ طَاهِرٌ.', 'لاويين 13:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 18, '«وَإِذَا كَانَ الْجِسْمُ فِي جِلْدِهِ دُمَّلَةٌ قَدْ بَرِئَتْ،', 'لاويين 13:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 19, 'وَصَارَ فِي مَوْضِعِ الدُّمَّلَةِ نَاتِئٌ أَبْيَضُ، أَوْ لُمْعَةٌ بَيْضَاءُ ضَارِبَةٌ إِلَى الْحُمْرَةِ، يُعْرَضُ عَلَى الْكَاهِنِ.', 'لاويين 13:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 20, 'فَإِنْ رَأَى الْكَاهِنُ وَإِذَا مَنْظَرُهَا أَعْمَقُ مِنَ الْجِلْدِ وَقَدِ ابْيَضَّ شَعْرُهَا، يَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا ضَرْبَةُ بَرَصٍ أَفْرَخَتْ فِي الدُّمَّلَةِ.', 'لاويين 13:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 21, 'لَكِنْ إِنْ رَآهَا الْكَاهِنُ وَإِذَا لَيْسَ فِيهَا شَعْرٌ أَبْيَضُ، وَلَيْسَتْ أَعْمَقَ مِنَ الْجِلْدِ، وَهِيَ كَامِدَةُ اللَّوْنِ، يَحْجُزُهُ الْكَاهِنُ سَبْعَةَ أَيَّامٍ.', 'لاويين 13:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 22, 'فَإِنْ كَانَتْ قَدِ امْتَدَّتْ فِي الْجِلْدِ يَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا ضَرْبَةٌ.', 'لاويين 13:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 23, 'لَكِنْ إِنْ وَقَفَتِ اللُّمْعَةُ مَكَانَهَا وَلَمْ تَمْتَدَّ، فَهِيَ أَثَرُ الدُّمَّلَةِ. فَيَحْكُمُ الْكَاهِنُ بِطَهَارَتِهِ.', 'لاويين 13:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 24, '«أَوْ إِذَا كَانَ الْجِسْمُ فِي جِلْدِهِ كَيُّ نَارٍ، وَكَانَ حَيُّ الْكَيِّ لُمْعَةً بَيْضَاءَ ضَارِبَةً إِلَى الْحُمْرَةِ أَوْ بَيْضَاءَ،', 'لاويين 13:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 25, 'وَرَآهَا الْكَاهِنُ وَإِذَا الشَّعْرُ فِي اللُّمْعَةِ قَدِ ابْيَضَّ، وَمَنْظَرُهَا أَعْمَقُ مِنَ الْجِلْدِ، فَهِيَ بَرَصٌ قَدْ أَفْرَخَ فِي الْكَيِّ. فَيَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا ضَرْبَةُ بَرَصٍ.', 'لاويين 13:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 26, 'لَكِنْ إِنْ رَآهَا الْكَاهِنُ وَإِذَا لَيْسَ فِي اللُّمْعَةِ شَعْرٌ أَبْيَضُ، وَلَيْسَتْ أَعْمَقَ مِنَ الْجِلْدِ، وَهِيَ كَامِدَةُ اللَّوْنِ، يَحْجُزُهُ الْكَاهِنُ سَبْعَةَ أَيَّامٍ،', 'لاويين 13:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 27, 'ثُمَّ يَرَاهُ الْكَاهِنُ فِي الْيَوْمِ السَّابِعِ. فَإِنْ كَانَتْ قَدِ امْتَدَّتْ فِي الْجِلْدِ، يَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا ضَرْبَةُ بَرَصٍ.', 'لاويين 13:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 28, 'لَكِنْ إِنْ وَقَفَتِ اللُّمْعَةُ مَكَانَهَا، لَمْ تَمْتَدَّ فِي الْجِلْدِ، وَكَانَتْ كَامِدَةَ اللَّوْنِ، فَهِيَ نَاتِئُ الْكَيِّ، فَالْكَاهِنُ يَحْكُمُ بِطَهَارَتِهِ لِأَنَّهَا أَثَرُ الْكَيِّ.', 'لاويين 13:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 29, '«وَإِذَا كَانَ رَجُلٌ أَوِ امْرَأَةٌ فِيهِ ضَرْبَةٌ فِي الرَّأْسِ أَوْ فِي الذَّقَنِ،', 'لاويين 13:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 30, 'وَرَأَى الْكَاهِنُ الضَّرْبَةَ وَإِذَا مَنْظَرُهَا أَعْمَقُ مِنَ الْجِلْدِ، وَفِيهَا شَعْرٌ أَشْقَرُ دَقِيقٌ، يَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّهَا قَرَعٌ. بَرَصُ الرَّأْسِ أَوِ الذَّقَنِ.', 'لاويين 13:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 31, 'لَكِنْ إِذَا رَأَى الْكَاهِنُ ضَرْبَةَ الْقَرَعِ وَإِذَا مَنْظَرُهَا لَيْسَ أَعْمَقَ مِنَ الْجِلْدِ، لَكِنْ لَيْسَ فِيهَا شَعْرٌ أَسْوَدُ، يَحْجُزُ الْكَاهِنُ الْمَضْرُوبَ بِالْقَرَعِ سَبْعَةَ أَيَّامٍ.', 'لاويين 13:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 32, 'فَإِنْ رَأَى الْكَاهِنُ الضَّرْبَةَ فِي الْيَوْمِ السَّابِعِ وَإِذَا الْقَرَعُ لَمْ يَمْتَدَّ، وَلَمْ يَكُنْ فِيهِ شَعْرٌ أَشْقَرُ، وَلَا مَنْظَرُ الْقَرَعِ أَعْمَقُ مِنَ الْجِلْدِ،', 'لاويين 13:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 33, 'فَلْيَحْلِقْ. لَكِنْ لَا يَحْلِقِ الْقَرَعَ. وَيَحْجُزُ الْكَاهِنُ الْأَقْرَعَ سَبْعَةَ أَيَّامٍ ثَانِيَةً.', 'لاويين 13:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 34, 'فَإِنْ رَأَى الْكَاهِنُ الْأَقْرَعَ فِي الْيَوْمِ السَّابِعِ وَإِذَا الْقَرَعُ لَمْ يَمْتَدَّ فِي الْجِلْدِ، وَلَيْسَ مَنْظَرُهُ أَعْمَقَ مِنَ الْجِلْدِ، يَحْكُمُ الْكَاهِنُ بِطَهَارَتِهِ، فَيَغْسِلُ ثِيَابَهُ وَيَكُونُ طَاهِرًا.', 'لاويين 13:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 35, 'لَكِنْ إِنْ كَانَ الْقَرَعُ يَمْتَدُّ فِي الْجِلْدِ بَعْدَ الْحُكْمِ بِطَهَارَتِهِ،', 'لاويين 13:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 36, 'وَرَآهُ الْكَاهِنُ وَإِذَا الْقَرَعُ قَدِ امْتَدَّ فِي الْجِلْدِ، فَلَا يُفَتِّشُ الْكَاهِنُ عَلَى الشَّعْرِ الْأَشْقَرِ. إِنَّهُ نَجِسٌ.', 'لاويين 13:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 37, 'لَكِنْ إِنْ وَقَفَ فِي عَيْنَيْهِ وَنَبَتَ فِيهِ شَعْرٌ أَسْوَدُ، فَقَدْ بَرِئَ الْقَرَعُ. إِنَّهُ طَاهِرٌ فَيَحْكُمُ الْكَاهِنُ بِطَهَارَتِهِ.', 'لاويين 13:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 38, '«وَإِذَا كَانَ رَجُلٌ أَوِ امْرَأَةٌ فِي جِلْدِ جَسَدِهِ لُمَعٌ، لُمَعٌ بِيضٌ،', 'لاويين 13:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 39, 'وَرَأَى الْكَاهِنُ وَإِذَا فِي جِلْدِ جَسَدِهِ لُمَعٌ كَامِدَةُ اللَّوْنِ بَيْضَاءُ، فَذَلِكَ بَهَقٌ قَدْ أَفْرَخَ فِي الْجِلْدِ. إِنَّهُ طَاهِرٌ.', 'لاويين 13:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 40, '«وَإِذَا كَانَ إِنْسَانٌ قَدْ ذَهَبَ شَعْرُ رَأْسِهِ فَهُوَ أَقْرَعُ. إِنَّهُ طَاهِرٌ.', 'لاويين 13:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 41, 'وَإِنْ ذَهَبَ شَعْرُ رَأْسِهِ مِنْ جِهَةِ وَجْهِهِ فَهُوَ أَصْلَعُ. إِنَّهُ طَاهِرٌ.', 'لاويين 13:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 42, 'لَكِنْ إِذَا كَانَ فِي الْقَرَعَةِ أَوْ فِي الصَّلْعَةِ ضَرْبَةٌ بَيْضَاءُ ضَارِبَةٌ إِلَى الْحُمْرَةِ، فَهُوَ بَرَصٌ مُفْرِخٌ فِي قَرَعَتِهِ أَوْ فِي صَلْعَتِهِ.', 'لاويين 13:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 43, 'فَإِنْ رَآهُ الْكَاهِنُ وَإِذَا نَاتِئُ الضَّرْبَةِ أَبْيَضُ ضَارِبٌ إِلَى الْحُمْرَةِ فِي قَرَعَتِهِ أَوْ فِي صَلْعَتِهِ، كَمَنْظَرِ الْبَرَصِ فِي جِلْدِ الْجَسَدِ،', 'لاويين 13:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 44, 'فَهُوَ إِنْسَانٌ أَبْرَصُ. إِنَّهُ نَجِسٌ. فَيَحْكُمُ الْكَاهِنُ بِنَجَاسَتِهِ. إِنَّ ضَرْبَتَهُ فِي رَأْسِهِ.', 'لاويين 13:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 45, 'وَالْأَبْرَصُ الَّذِي فِيهِ الضَّرْبَةُ، تَكُونُ ثِيَابُهُ مَشْقُوقَةً، وَرَأْسُهُ يَكُونُ مَكْشُوفًا، وَيُغَطِّي شَارِبَيْهِ، وَيُنَادِي׃ نَجِسٌ، نَجِسٌ.', 'لاويين 13:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 46, 'كُلَّ الْأَيَّامِ الَّتِي تَكُونُ الضَّرْبَةُ فِيهِ يَكُونُ نَجِسًا. إِنَّهُ نَجِسٌ. يُقِيمُ وَحْدَهُ. خَارِجَ الْمَحَلَّةِ يَكُونُ مُقَامُهُ.', 'لاويين 13:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 47, '«وَأَمَّا الثَّوْبُ فَإِذَا كَانَ فِيهِ ضَرْبَةُ بَرَصٍ، ثَوْبُ صُوفٍ أَوْ ثَوْبُ كَتَّانٍ،', 'لاويين 13:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 48, 'فِي السَّدَى أَوِ اللُّحْمَةِ مِنَ الصُّوفِ أَوِ الْكَتَّانِ، أَوْ فِي جِلْدٍ أَوْ فِي كُلِّ مَصْنُوعٍ مِنْ جِلْدٍ،', 'لاويين 13:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 49, 'وَكَانَتِ الضَّرْبَةُ ضَارِبَةً إِلَى الْخُضْرَةِ أَوْ إِلَى الْحُمْرَةِ فِي الثَّوْبِ أَوْ فِي الْجِلْدِ، فِي السَّدَى أَوِ اللُّحْمَةِ أَوْ فِي مَتَاعٍ مَا مِنْ جِلْدٍ، فَإِنَّهَا ضَرْبَةُ بَرَصٍ، فَتُعْرَضُ عَلَى الْكَاهِنِ.', 'لاويين 13:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 50, 'فَيَرَى الْكَاهِنُ الضَّرْبَةَ وَيَحْجُزُ الْمَضْرُوبَ سَبْعَةَ أَيَّامٍ.', 'لاويين 13:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 51, 'فَمَتَى رَأَى الضَّرْبَةَ فِي الْيَوْمِ السَّابِعِ إِذَا كَانَتِ الضَّرْبَةُ قَدِ امْتَدَّتْ فِي الثَّوْبِ، فِي السَّدَى أَوِ اللُّحْمَةِ أَوْ فِي الْجِلْدِ مِنْ كُلِّ مَا يُصْنَعُ مِنْ جِلْدٍ لِلْعَمَلِ، فَالضَّرْبَةُ بَرَصٌ مُفْسِدٌ. إِنَّهَا نَجِسَةٌ.', 'لاويين 13:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 52, 'فَيُحْرِقُ الثَّوْبَ أَوِ السَّدَى أَوِ اللُّحْمَةَ مِنَ الصُّوفِ أَوِ الْكَتَّانِ أَوْ مَتَاعِ الْجِلْدِ الَّذِي كَانَتْ فِيهِ الضَّرْبَةُ، لِأَنَّهَا بَرَصٌ مُفْسِدٌ. بِالنَّارِ يُحْرَقُ.', 'لاويين 13:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 53, 'لَكِنْ إِنْ رَأَى الْكَاهِنُ وَإِذَا الضَّرْبَةُ لَمْ تَمْتَدَّ فِي الثَّوْبِ فِي السَّدَى أَوِ اللُّحْمَةِ أَوْ فِي مَتَاعِ الْجِلْدِ،', 'لاويين 13:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 54, 'يَأْمُرُ الْكَاهِنُ أَنْ يَغْسِلُوا مَا فِيهِ الضَّرْبَةُ، وَيَحْجُزُهُ سَبْعَةَ أَيَّامٍ ثَانِيَةً.', 'لاويين 13:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 55, 'فَإِنْ رَأَى الْكَاهِنُ بَعْدَ غَسْلِ الْمَضْرُوبِ وَإِذَا الضَّرْبَةُ لَمْ تُغَيِّرْ مَنْظَرَهَا، وَلَا امْتَدَّتِ الضَّرْبَةُ، فَهُوَ نَجِسٌ. بِالنَّارِ تُحْرِقُهُ. إِنَّهَا نُخْرُوبٌ فِي جُرْدَةِ بَاطِنِهِ أَوْ ظَاهِرِهِ.', 'لاويين 13:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 56, 'لَكِنْ إِنْ رَأَى الْكَاهِنُ وَإِذَا الضَّرْبَةُ كَامِدَةُ اللَّوْنِ بَعْدَ غَسْلِهِ، يُمَزِّقُهَا مِنَ الثَّوْبِ أَوِ الْجِلْدِ مِنَ السَّدَى أَوِ اللُّحْمَةِ.', 'لاويين 13:56');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 57, 'ثُمَّ إِنْ ظَهَرَتْ أَيْضًا فِي الثَّوْبِ فِي السَّدَى أَوِ اللُّحْمَةِ أَوْ فِي مَتَاعِ الْجِلْدِ فَهِيَ مُفْرِخَةٌ. بِالنَّارِ تُحْرِقُ مَا فِيهِ الضَّرْبَةُ.', 'لاويين 13:57');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 58, 'وَأَمَّا الثَّوْبُ، السَّدَى أَوِ اللُّحْمَةُ أَوْ مَتَاعُ الْجِلْدِ الَّذِي تَغْسِلُهُ وَتَزُولُ مِنْهُ الضَّرْبَةُ، فَيُغْسَلُ ثَانِيَةً فَيَطْهُرُ.', 'لاويين 13:58');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 13, 59, '«هَذِهِ شَرِيعَةُ ضَرْبَةِ الْبَرَصِ فِي الصُّوفِ أَوِ الْكَتَّانِ، فِي السَّدَى أَوِ اللُّحْمَةِ أَوْ فِي كُلِّ مَتَاعٍ مِنْ جِلْدٍ، لِلْحُكْمِ بِطَهَارَتِهِ أَوْ نَجَاسَتِهِ».', 'لاويين 13:59');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 14:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 2, '«هَذِهِ تَكُونُ شَرِيعَةَ الْأَبْرَصِ׃ يَوْمَ طُهْرِهِ، يُؤْتَى بِهِ إِلَى الْكَاهِنِ.', 'لاويين 14:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 3, 'وَيَخْرُجُ الْكَاهِنُ إِلَى خَارِجِ الْمَحَلَّةِ، فَإِنْ رَأَى الْكَاهِنُ وَإِذَا ضَرْبَةُ الْبَرَصِ قَدْ بَرِئَتْ مِنَ الْأَبْرَصِ،', 'لاويين 14:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 4, 'يَأْمُرُ الْكَاهِنُ أَنْ يُؤْخَذَ لِلْمُتَطَهِّرِ عُصْفُورَانِ حَيَّانِ طَاهِرَانِ، وَخَشَبُ أَرْزٍ وَقِرْمِزٌ وَزُوفَا.', 'لاويين 14:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 5, 'وَيَأْمُرُ الْكَاهِنُ أَنْ يُذْبَحَ الْعُصْفُورُ الْوَاحِدُ فِي إِنَاءِ خَزَفٍ عَلَى مَاءٍ حَيٍّ.', 'لاويين 14:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 6, 'أَمَّا الْعُصْفُورُ الْحَيُّ فَيَأْخُذُهُ مَعَ خَشَبِ الْأَرْزِ وَالْقِرْمِزِ وَالزُّوفَا وَيَغْمِسُهَا مَعَ الْعُصْفُورِ الْحَيِّ فِي دَمِ الْعُصْفُورِ الْمَذْبُوحِ عَلَى الْمَاءِ الْحَيِّ،', 'لاويين 14:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 7, 'وَيَنْضِحُ عَلَى الْمُتَطَهِّرِ مِنَ الْبَرَصِ سَبْعَ مَرَّاتٍ فَيُطَهِّرُهُ، ثُمَّ يُطْلِقُ الْعُصْفُورَ الْحَيَّ عَلَى وَجْهِ الصَّحْرَاءِ.', 'لاويين 14:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 8, 'فَيَغْسِلُ الْمُتَطَهِّرُ ثِيَابَهُ وَيَحْلِقُ كُلَّ شَعْرِهِ وَيَسْتَحِمُّ بِمَاءٍ فَيَطْهُرُ. ثُمَّ يَدْخُلُ الْمَحَلَّةَ، لَكِنْ يُقِيمُ خَارِجَ خَيْمَتِهِ سَبْعَةَ أَيَّامٍ.', 'لاويين 14:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 9, 'وَفِي الْيَوْمِ السَّابِعِ يَحْلِقُ كُلَّ شَعْرِهِ׃ رَأْسَهُ وَلِحْيَتَهُ وَحَوَاجِبَ عَيْنَيْهِ وَجَمِيعَ شَعْرِهِ يَحْلِقُ. وَيَغْسِلُ ثِيَابَهُ وَيَرْحَضُ جَسَدَهُ بِمَاءٍ فَيَطْهُرُ.', 'لاويين 14:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 10, 'ثُمَّ فِي الْيَوْمِ الثَّامِنِ يَأْخُذُ خَرُوفَيْنِ صَحِيحَيْنِ وَنَعْجَةً وَاحِدَةً حَوْلِيَّةً صَحِيحَةً وَثَلَاثَةَ أَعْشَارِ دَقِيقٍ تَقْدِمَةً مَلْتُوتَةً بِزَيْتٍ وَلُجَّ زَيْتٍ.', 'لاويين 14:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 11, 'فَيُوقِفُ الْكَاهِنُ الْمُطَهِّرُ الْإِنْسَانَ الْمُتَطَهِّرَ وَإِيَّاهَا أَمَامَ الرَّبِّ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 14:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 12, 'ثُمَّ يَأْخُذُ الْكَاهِنُ الْخَرُوفَ الْوَاحِدَ وَيُقَرِّبُهُ ذَبِيحَةَ إِثْمٍ مَعَ لُجِّ الزَّيْتِ. يُرَدِّدُهُمَا تَرْدِيدًا أَمَامَ الرَّبِّ.', 'لاويين 14:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 13, 'وَيَذْبَحُ الْخَرُوفَ فِي الْمَوْضِعِ الَّذِي يَذْبَحُ فِيهِ ذَبِيحَةَ الْخَطِيَّةِ وَالْمُحْرَقَةَ فِي الْمَكَانِ الْمُقَدَّسِ، لِأَنَّ ذَبِيحَةَ الْإِثْمِ كَذَبِيحَةِ الْخَطِيَّةِ لِلْكَاهِنِ. إِنَّهَا قُدْسُ أَقْدَاسٍ.', 'لاويين 14:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 14, 'وَيَأْخُذُ الْكَاهِنُ مِنْ دَمِ ذَبِيحَةِ الْإِثْمِ وَيَجْعَلُ الْكَاهِنُ عَلَى شَحْمَةِ أُذُنِ الْمُتَطَهِّرِ الْيُمْنَى، وَعَلَى إِبْهَامِ يَدِهِ الْيُمْنَى، وَعَلَى إِبْهَامِ رِجْلِهِ الْيُمْنَى.', 'لاويين 14:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 15, 'وَيَأْخُذُ الْكَاهِنُ مِنْ لُجِّ الزَّيْتِ وَيَصُبُّ فِي كَفِّ الْكَاهِنِ الْيُسْرَى.', 'لاويين 14:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 16, 'وَيَغْمِسُ الْكَاهِنُ إِصْبَعَهُ الْيُمْنَى فِي الزَّيْتِ الَّذِي عَلَى كَفِّهِ الْيُسْرَى، وَيَنْضِحُ مِنَ الزَّيْتِ بِإِصْبَعِهِ سَبْعَ مَرَّاتٍ أَمَامَ الرَّبِّ.', 'لاويين 14:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 17, 'وَمِمَّا فَضِلَ مِنَ الزَّيْتِ الَّذِي فِي كَفِّهِ يَجْعَلُ الْكَاهِنُ عَلَى شَحْمَةِ أُذُنِ الْمُتَطَهِّرِ الْيُمْنَى، وَعَلَى إِبْهَامِ يَدِهِ الْيُمْنَى، وَعَلَى إِبْهَامِ رِجْلِهِ الْيُمْنَى، عَلَى دَمِ ذَبِيحَةِ الْإِثْمِ.', 'لاويين 14:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 18, 'وَالْفَاضِلُ مِنَ الزَّيْتِ الَّذِي فِي كَفِّ الْكَاهِنِ يَجْعَلُهُ عَلَى رَأْسِ الْمُتَطَهِّرِ، وَيُكَفِّرُ عَنْهُ الْكَاهِنُ أَمَامَ الرَّبِّ.', 'لاويين 14:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 19, 'ثُمَّ يَعْمَلُ الْكَاهِنُ ذَبِيحَةَ الْخَطِيَّةِ وَيُكَفِّرُ عَنِ الْمُتَطَهِّرِ مِنْ نَجَاسَتِهِ. ثُمَّ يَذْبَحُ الْمُحْرَقَةَ.', 'لاويين 14:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 20, 'وَيُصْعِدُ الْكَاهِنُ الْمُحْرَقَةَ وَالتَّقْدِمَةَ عَلَى الْمَذْبَحِ وَيُكَفِّرُ عَنْهُ الْكَاهِنُ فَيَطْهُرُ.', 'لاويين 14:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 21, '«لَكِنْ إِنْ كَانَ فَقِيرًا وَلَا تَنَالُ يَدُهُ، يَأْخُذُ خَرُوفًا وَاحِدًا ذَبِيحَةَ إِثْمٍ لِتَرْدِيدٍ، تَكْفِيرًا عَنْهُ، وَعُشْرًا وَاحِدًا مِنْ دَقِيقٍ مَلْتُوتٍ بِزَيْتٍ لِتَقْدِمَةٍ، وَلُجَّ زَيْتٍ،', 'لاويين 14:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 22, 'وَيَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ كَمَا تَنَالُ يَدُهُ، فَيَكُونُ الْوَاحِدُ ذَبِيحَةَ خَطِيَّةٍ، وَالْآخَرُ مُحْرَقَةً.', 'لاويين 14:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 23, 'وَيَأْتِي بِهَا فِي الْيَوْمِ الثَّامِنِ لِطُهْرِهِ إِلَى الْكَاهِنِ، إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ أَمَامَ الرَّبِّ.', 'لاويين 14:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 24, 'فَيَأْخُذُ الْكَاهِنُ كَبْشَ الْإِثْمِ وَلُجَّ الزَّيْتِ، وَيُرَدِّدُهُمَا الْكَاهِنُ تَرْدِيدًا أَمَامَ الرَّبِّ.', 'لاويين 14:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 25, 'ثُمَّ يَذْبَحُ كَبْشَ الْإِثْمِ، وَيَأْخُذُ الْكَاهِنُ مِنْ دَمِ ذَبِيحَةِ الْإِثْمِ وَيَجْعَلُ عَلَى شَحْمَةِ أُذُنِ الْمُتَطَهِّرِ الْيُمْنَى، وَعَلَى إِبْهَامِ يَدِهِ الْيُمْنَى، وَعَلَى إِبْهَامِ رِجْلِهِ الْيُمْنَى.', 'لاويين 14:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 26, 'وَيَصُبُّ الْكَاهِنُ مِنَ الزَّيْتِ فِي كَفِّ الْكَاهِنِ الْيُسْرَى،', 'لاويين 14:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 27, 'وَيَنْضِحُ الْكَاهِنُ بِإِصْبَعِهِ الْيُمْنَى مِنَ الزَّيْتِ الَّذِي فِي كَفِّهِ الْيُسْرَى سَبْعَ مَرَّاتٍ أَمَامَ الرَّبِّ.', 'لاويين 14:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 28, 'وَيَجْعَلُ الْكَاهِنُ مِنَ الزَّيْتِ الَّذِي فِي كَفِّهِ عَلَى شَحْمَةِ أُذُنِ الْمُتَطَهِّرِ الْيُمْنَى، وَعَلَى إِبْهَامِ يَدِهِ الْيُمْنَى، وَعَلَى إِبْهَامِ رِجْلِهِ الْيُمْنَى، عَلَى مَوْضِعِ دَمِ ذَبِيحَةِ الْإِثْمِ.', 'لاويين 14:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 29, 'وَالْفَاضِلُ مِنَ الزَّيْتِ الَّذِي فِي كَفِّ الْكَاهِنِ يَجْعَلُهُ عَلَى رَأْسِ الْمُتَطَهِّرِ تَكْفِيرًا عَنْهُ أَمَامَ الرَّبِّ.', 'لاويين 14:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 30, 'ثُمَّ يَعْمَلُ وَاحِدَةً مِنَ الْيَمَامَتَيْنِ أَوْ مِنْ فَرْخَيِ الْحَمَامِ، مِمَّا تَنَالُ يَدُهُ.', 'لاويين 14:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 31, 'مَا تَنَالُ يَدُهُ׃ الْوَاحِدَ ذَبِيحَةَ خَطِيَّةٍ، وَالْآخَرَ مُحْرَقَةً مَعَ التَّقْدِمَةِ. وَيُكَفِّرُ الْكَاهِنُ عَنِ الْمُتَطَهِّرِ أَمَامَ الرَّبِّ.', 'لاويين 14:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 32, 'هَذِهِ شَرِيعَةُ الَّذِي فِيهِ ضَرْبَةُ بَرَصٍ الَّذِي لَا تَنَالُ يَدُهُ فِي تَطْهِيرِهِ».', 'لاويين 14:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 33, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'لاويين 14:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 34, '«مَتَى جِئْتُمْ إِلَى أَرْضِ كَنْعَانَ الَّتِي أُعْطِيكُمْ مُلْكًا، وَجَعَلْتُ ضَرْبَةَ بَرَصٍ فِي بَيْتٍ فِي أَرْضِ مُلْكِكُمْ.', 'لاويين 14:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 35, 'يَأْتِي الَّذِي لَهُ الْبَيْتُ، وَيُخبِرُ الْكَاهِنَ قَائِلًا׃ قَدْ ظَهَرَ لِي شِبْهُ ضَرْبَةٍ فِي الْبَيْتِ.', 'لاويين 14:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 36, 'فَيَأْمُرُ الْكَاهِنُ أَنْ يُفْرِغُوا الْبَيْتَ قَبْلَ دُخُولِ الْكَاهِنِ لِيَرَى الضَّرْبَةَ، لِئَلَّا يَتَنَجَّسَ كُلُّ مَا فِي الْبَيْتِ. وَبَعْدَ ذَلِكَ يَدْخُلُ الْكَاهِنُ لِيَرَى الْبَيْتَ.', 'لاويين 14:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 37, 'فَإِذَا رَأَى الضَّرْبَةَ، وَإِذَا الضَّرْبَةُ فِي حِيطَانِ الْبَيْتِ نُقَرٌ ضَارِبَةٌ إِلَى الْخُضْرَةِ أَوْ إِلَى الْحُمْرَةِ، وَمَنْظَرُهَا أَعْمَقُ مِنَ الْحَائِطِ،', 'لاويين 14:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 38, 'يَخْرُجُ الْكَاهِنُ مِنَ الْبَيْتِ إِلَى بَابِ الْبَيْتِ، وَيُغْلِقُ الْبَيْتَ سَبْعَةَ أَيَّامٍ.', 'لاويين 14:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 39, 'فَإِذَا رَجَعَ الْكَاهِنُ فِي الْيَوْمِ السَّابِعِ وَرَأَى وَإِذَا الضَّرْبَةُ قَدِ امْتَدَّتْ فِي حِيطَانِ الْبَيْتِ،', 'لاويين 14:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 40, 'يَأْمُرُ الْكَاهِنُ أَنْ يَقْلَعُوا الْحِجَارَةَ الَّتِي فِيهَا الضَّرْبَةُ وَيَطْرَحُوهَا خَارِجَ الْمَدِينَةِ فِي مَكَانٍ نَجِسٍ.', 'لاويين 14:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 41, 'وَيُقَشِّرُ الْبَيْتَ مِنْ دَاخِلٍ حَوَالَيْهِ، وَيَطْرَحُونَ التُّرَابَ الَّذِي يُقَشِّرُونَهُ خَارِجَ الْمَدِينَةِ فِي مَكَانٍ نَجِسٍ.', 'لاويين 14:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 42, 'وَيَأْخُذُونَ حِجَارَةً أُخْرَى وَيُدْخِلُونَهَا فِي مَكَانِ الْحِجَارَةِ، وَيَأْخُذُ تُرَابًا آخَرَ وَيُطَيِّنُ الْبَيْتَ.', 'لاويين 14:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 43, 'فَإِنْ رَجَعَتِ الضَّرْبَةُ وَأَفْرَخَتْ فِي الْبَيْتِ بَعْدَ قَلْعِ الْحِجَارَةِ وَقَشْرِ الْبَيْتِ وَتَطْيِينِهِ،', 'لاويين 14:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 44, 'وَأَتَى الْكَاهِنُ وَرَأَى وَإِذَا الضَّرْبَةُ قَدِ امْتَدَّتْ فِي الْبَيْتِ، فَهِيَ بَرَصٌ مُفْسِدٌ فِي الْبَيْتِ. إِنَّهُ نَجِسٌ.', 'لاويين 14:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 45, 'فَيَهْدِمُ الْبَيْتَ׃ حِجَارَتَهُ وَأَخْشَابَهُ وَكُلَّ تُرَابِ الْبَيْتِ، وَيُخْرِجُهَا إِلَى خَارِجِ الْمَدِينَةِ إِلَى مَكَانٍ نَجِسٍ.', 'لاويين 14:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 46, 'وَمَنْ دَخَلَ إِلَى الْبَيْتِ فِي كُلِّ أَيَّامِ انْغِلَاقِهِ، يَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 14:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 47, 'وَمَنْ نَامَ فِي الْبَيْتِ يَغْسِلُ ثِيَابَهُ. وَمَنْ أَكَلَ فِي الْبَيْتِ يَغْسِلُ ثِيَابَهُ.', 'لاويين 14:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 48, 'لَكِنْ إِنْ أَتَى الْكَاهِنُ وَرَأَى وَإِذَا الضَّرْبَةُ لَمْ تَمْتَدَّ فِي الْبَيْتِ بَعْدَ تَطْيِينِ الْبَيْتِ، يُطَهِّرُ الْكَاهِنُ الْبَيْتَ. لِأَنَّ الضَّرْبَةَ قَدْ بَرِئَتْ.', 'لاويين 14:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 49, 'فَيَأْخُذُ لِتَطْهِيرِ الْبَيْتِ عُصْفُورَيْنِ وَخَشَبَ أَرْزٍ وَقِرْمِزًا وَزُوفَا.', 'لاويين 14:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 50, 'وَيَذْبَحُ الْعُصْفُورَ الْوَاحِدَ فِي إِنَاءِ خَزَفٍ عَلَى مَاءٍ حَيٍّ،', 'لاويين 14:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 51, 'وَيَأْخُذُ خَشَبَ الْأَرْزِ وَالزُّوفَا وَالْقِرْمِزَ وَالْعُصْفُورَ الْحَيَّ وَيَغْمِسُهَا فِي دَمِ الْعُصْفُورِ الْمَذْبُوحِ وَفِي الْمَاءِ الْحَيِّ، وَيَنْضِحُ الْبَيْتَ سَبْعَ مَرَّاتٍ،', 'لاويين 14:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 52, 'وَيُطَهِّرُ الْبَيْتَ بِدَمِ الْعُصْفُورِ وَبِالْمَاءِ الْحَيِّ وَبِالْعُصْفُورِ الْحَيِّ وَبِخَشَبِ الْأَرْزِ وَبِالزُّوفَا وَبِالْقِرْمِزِ.', 'لاويين 14:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 53, 'ثُمَّ يُطْلِقُ الْعُصْفُورَ الْحَيَّ إِلَى خَارِجِ الْمَدِينَةِ عَلَى وَجْهِ الصَّحْرَاءِ وَيُكَفِّرُ عَنِ الْبَيْتِ فَيَطْهُرُ.', 'لاويين 14:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 54, '«هَذِهِ هِيَ الشَّرِيعَةُ لِكُلِّ ضَرْبَةٍ مِنَ الْبَرَصِ وَلِلْقَرَعِ،', 'لاويين 14:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 55, 'وَلِبَرَصِ الثَّوْبِ وَالْبَيْتِ،', 'لاويين 14:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 56, 'وَلِلنَّاتِئِ وَلِلْقُوبَاءِ وَلِلُّمْعَةِ،', 'لاويين 14:56');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 14, 57, 'لِلتَّعْلِيمِ فِي يَوْمِ النَّجَاسَةِ وَيَوْمِ الطَّهَارَةِ. هَذِهِ شَرِيعَةُ الْبَرَصِ».', 'لاويين 14:57');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'لاويين 15:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 2, '«كَلِّمَا بَنِي إِسْرَائِيلَ وَقُولَا لَهُمْ׃ كُلُّ رَجُلٍ يَكُونُ لَهُ سَيْلٌ مِنْ لَحْمِهِ، فَسَيْلُهُ نَجِسٌ.', 'لاويين 15:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 3, 'وَهَذِهِ تَكُونُ نَجَاسَتُهُ بِسَيْلِهِ׃ إِنْ كَانَ لَحْمُهُ يَبْصُقُ سَيْلَهُ، أَوْ يَحْتَبِسُ لَحْمُهُ عَنْ سَيْلِهِ، فَذَلِكَ نَجَاسَتُهُ.', 'لاويين 15:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 4, 'كُلُّ فِرَاشٍ يَضْطَجِعُ عَلَيْهِ الَّذِي لَهُ السَّيْلُ يَكُونُ نَجِسًا، وَكُلُّ مَتَاعٍ يَجْلِسُ عَلَيْهِ يَكُونُ نَجِسًا.', 'لاويين 15:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 5, 'وَمَنْ مَسَّ فِرَاشَهُ يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 6, 'وَمَنْ جَلَسَ عَلَى الْمَتَاعِ الَّذِي يَجْلِسُ عَلَيْهِ ذُو السَّيْلِ، يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 7, 'وَمَنْ مَسَّ لَحْمَ ذِي السَّيْلِ يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 8, 'وَإِنْ بَصَقَ ذُو السَّيْلِ عَلَى طَاهِرٍ، يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 9, 'وَكُلُّ مَا يَرْكَبُ عَلَيْهِ ذُو السَّيْلِ يَكُونُ نَجِسًا.', 'لاويين 15:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 10, 'وَكُلُّ مَنْ مَسَّ كُلَّ مَا كَانَ تَحْتَهُ يَكُونُ نَجِسًا إِلَى الْمَسَاءِ، وَمَنْ حَمَلَهُنَّ يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 11, 'وَكُلُّ مَنْ مَسَّهُ ذُو السَّيْلِ وَلَمْ يَغْسِلْ يَدَيْهِ بِمَاءٍ، يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 12, 'وَإِنَاءُ الْخَزَفِ الَّذِي يَمَسُّهُ ذُو السَّيْلِ يُكْسَرُ. وَكُلُّ إِنَاءِ خَشَبٍ يُغْسَلُ بِمَاءٍ.', 'لاويين 15:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 13, 'وَإِذَا طَهُرَ ذُو السَّيْلِ مِنْ سَيْلِهِ، يُحْسَبُ لَهُ سَبْعَةُ أَيَّامٍ لِطُهْرِهِ، وَيَغْسِلُ ثِيَابَهُ وَيَرْحَضُ جَسَدَهُ بِمَاءٍ حَيٍّ فَيَطْهُرُ.', 'لاويين 15:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 14, 'وَفِي الْيَوْمِ الثَّامِنِ يَأْخُذُ لِنَفْسِهِ يَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ، وَيَأْتِي إِلَى أَمَامِ الرَّبِّ، إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ، وَيُعْطِيهِمَا لِلْكَاهِنِ،', 'لاويين 15:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 15, 'فَيَعْمَلُهُمَا الْكَاهِنُ׃ الْوَاحِدَ ذَبِيحَةَ خَطِيَّةٍ، وَالْآخَرَ مُحْرَقَةً. وَيُكَفِّرُ عَنْهُ الْكَاهِنُ أَمَامَ الرَّبِّ مِنْ سَيْلِهِ.', 'لاويين 15:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 16, '«وَإِذَا حَدَثَ مِنْ رَجُلٍ اضْطِجَاعُ زَرْعٍ، يَرْحَضُ كُلَّ جَسَدِهِ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 17, 'وَكُلُّ ثَوْبٍ وَكُلُّ جِلْدٍ يَكُونُ عَلَيْهِ اضْطِجَاعُ زَرْعٍ يُغْسَلُ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 18, 'وَالْمَرْأَةُ الَّتِي يَضْطَجِعُ مَعَهَا رَجُلٌ اضْطِجَاعَ زَرْعٍ، يَسْتَحِمَّانِ بِمَاءٍ، وَيَكُونَانِ نَجِسَيْنِ إِلَى الْمَسَاءِ.', 'لاويين 15:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 19, '«وَإِذَا كَانَتِ امْرَأَةٌ لَهَا سَيْلٌ، وَكَانَ سَيْلُهَا دَمًا فِي لَحْمِهَا، فَسَبْعَةَ أَيَّامٍ تَكُونُ فِي طَمْثِهَا. وَكُلُّ مَنْ مَسَّهَا يَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 20, 'وَكُلُّ مَا تَضْطَجِعُ عَلَيْهِ فِي طَمْثِهَا يَكُونُ نَجِسًا، وَكُلُّ مَا تَجْلِسُ عَلَيْهِ يَكُونُ نَجِسًا.', 'لاويين 15:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 21, 'وَكُلُّ مَنْ مَسَّ فِرَاشَهَا يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 22, 'وَكُلُّ مَنْ مَسَّ مَتَاعًا تَجْلِسُ عَلَيْهِ، يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 23, 'وَإِنْ كَانَ عَلَى الْفِرَاشِ أَوْ عَلَى الْمَتَاعِ الَّذِي هِيَ جَالِسَةٌ عَلَيْهِ عِنْدَمَا يَمَسُّهُ، يَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 24, 'وَإِنِ اضْطَجَعَ مَعَهَا رَجُلٌ فَكَانَ طَمْثُهَا عَلَيْهِ يَكُونُ نَجِسًا سَبْعَةَ أَيَّامٍ. وَكُلُّ فِرَاشٍ يَضْطَجِعُ عَلَيْهِ يَكُونُ نَجِسًا.', 'لاويين 15:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 25, '«وَإِذَا كَانَتِ امْرَأَةٌ يَسِيلُ سَيْلُ دَمِهَا أَيَّامًا كَثِيرَةً فِي غَيْرِ وَقْتِ طَمْثِهَا، أَوْ إِذَا سَالَ بَعْدَ طَمْثِهَا، فَتَكُونُ كُلَّ أَيَّامِ سَيَلَانِ نَجَاسَتِهَا كَمَا فِي أَيَّامِ طَمْثِهَا. إِنَّهَا نَجِسَةٌ.', 'لاويين 15:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 26, 'كُلُّ فِرَاشٍ تَضْطَجِعُ عَلَيْهِ كُلَّ أَيَّامِ سَيْلِهَا يَكُونُ لَهَا كَفِرَاشِ طَمْثِهَا. وَكُلُّ الْأَمْتِعَةِ الَّتِي تَجْلِسُ عَلَيْهَا تَكُونُ نَجِسَةً كَنَجَاسَةِ طَمْثِهَا.', 'لاويين 15:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 27, 'وَكُلُّ مَنْ مَسَّهُنَّ يَكُونُ نَجِسًا، فَيَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَكُونُ نَجِسًا إِلَى الْمَسَاءِ.', 'لاويين 15:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 28, 'وَإِذَا طَهُرَتْ مِنْ سَيْلِهَا تَحْسُبُ، لِنَفْسِهَا سَبْعَةَ أَيَّامٍ ثُمَّ تَطْهُرُ.', 'لاويين 15:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 29, 'وَفِي الْيَوْمِ الثَّامِنِ تَأْخُذُ لِنَفْسِهَا يَمَامَتَيْنِ أَوْ فَرْخَيْ حَمَامٍ، وَتَأْتِي بِهِمَا إِلَى الْكَاهِنِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 15:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 30, 'فَيَعْمَلُ الْكَاهِنُ׃ الْوَاحِدَ ذَبِيحَةَ خَطِيَّةٍ، وَالْآخَرَ مُحْرَقَةً. وَيُكَفِّرُ عَنْهَا الْكَاهِنُ أَمَامَ الرَّبِّ مِنْ سَيْلِ نَجَاسَتِهَا.', 'لاويين 15:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 31, 'فَتَعْزِلَانِ بَنِي إِسْرَائِيلَ عَنْ نَجَاسَتِهِمْ لِئَلَّا يَمُوتُوا فِي نَجَاسَتِهِمْ بِتَنْجِيسِهِمْ مَسْكَنِيَ الَّذِي فِي وَسَطِهِمْ.', 'لاويين 15:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 32, '«هَذِهِ شَرِيعَةُ ذِي السَّيْلِ، وَالَّذِي يَحْدُثُ مِنْهُ اضْطِجَاعُ زَرْعٍ فَيَتَنَجَّسُ بِهَا،', 'لاويين 15:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 15, 33, 'وَالْعَلِيلَةِ فِي طَمْثِهَا، وَالسَّائِلِ سَيْلُهُ׃ الذَّكَرِ وَالْأُنْثَى، وَالرَّجُلِ الَّذِي يَضْطَجِعُ مَعَ نَجِسَةٍ».', 'لاويين 15:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى بَعْدَ مَوْتِ ابْنَيْ هَارُونَ عِنْدَمَا اقْتَرَبَا أَمَامَ الرَّبِّ وَمَاتَا.', 'لاويين 16:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 2, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «كَلِّمْ هَارُونَ أَخَاكَ أَنْ لَا يَدْخُلَ كُلَّ وَقْتٍ إِلَى الْقُدْسِ دَاخِلَ الْحِجَابِ أَمَامَ الْغِطَاءِ الَّذِي عَلَى التَّابُوتِ لِئَلَّا يَمُوتَ، لِأَنِّي فِي السَّحَابِ أَتَرَاءَى عَلَى الْغِطَاءِ.', 'لاويين 16:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 3, 'بِهَذَا يَدْخُلُ هَارُونُ إِلَى الْقُدْسِ׃ بِثَوْرِ ابْنِ بَقَرٍ لِذَبِيحَةِ خَطِيَّةٍ، وَكَبْشٍ لِمُحْرَقَةٍ.', 'لاويين 16:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 4, 'يَلْبَسُ قَمِيصَ كَتَّانٍ مُقَدَّسًا، وَتَكُونُ سَرَاوِيلُ كَتَّانٍ عَلَى جَسَدِهِ، وَيَتَنَطَّقُ بِمِنْطَقَةِ كَتَّانٍ، وَيَتَعَمَّمُ بِعِمَامَةِ كَتَّانٍ. إِنَّهَا ثِيَابٌ مُقَدَّسَةٌ. فَيَرْحَضُ جَسَدَهُ بِمَاءٍ وَيَلْبَسُهَا.', 'لاويين 16:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 5, 'وَمِنْ جَمَاعَةِ بَنِي إِسْرَائِيلَ يَأْخُذُ تَيْسَيْنِ مِنَ الْمَعْزِ لِذَبِيحَةِ خَطِيَّةٍ، وَكَبْشًا وَاحِدًا لِمُحْرَقَةٍ.', 'لاويين 16:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 6, 'وَيُقَرِّبُ هَارُونُ ثَوْرَ الْخَطِيَّةِ الَّذِي لَهُ، وَيُكَفِّرُ عَنْ نَفْسِهِ وَعَنْ بَيْتِهِ.', 'لاويين 16:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 7, 'وَيَأْخُذُ التَّيْسَيْنِ وَيُوقِفُهُمَا أَمَامَ الرَّبِّ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ.', 'لاويين 16:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 8, 'وَيُلْقِي هَارُونُ عَلَى التَّيْسَيْنِ قُرْعَتَيْنِ׃ قُرْعَةً لِلرَّبِّ وَقُرْعَةً لِعَزَازِيلَ.', 'لاويين 16:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 9, 'وَيُقَرِّبُ هَارُونُ التَّيْسَ الَّذِي خَرَجَتْ عَلَيْهِ الْقُرْعَةُ لِلرَّبِّ وَيَعْمَلُهُ ذَبِيحَةَ خَطِيَّةٍ.', 'لاويين 16:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 10, 'وَأَمَّا التَّيْسُ الَّذِي خَرَجَتْ عَلَيْهِ الْقُرْعَةُ لِعَزَازِيلَ فَيُوقَفُ حَيًّا أَمَامَ الرَّبِّ، لِيُكَفِّرَ عَنْهُ لِيُرْسِلَهُ إِلَى عَزَازِيلَ إِلَى الْبَرِّيَّةِ.', 'لاويين 16:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 11, '«وَيُقَدِّمُ هَارُونُ ثَوْرَ الْخَطِيَّةِ الَّذِي لَهُ وَيُكَفِّرُ عَنْ نَفْسِهِ وَعَنْ بَيْتِهِ، وَيَذْبَحُ ثَوْرَ الْخَطِيَّةِ الَّذِي لَهُ،', 'لاويين 16:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 12, 'وَيَأْخُذُ مِلْءَ الْمَجْمَرَةِ جَمْرَ نَارٍ عَنِ الْمَذْبَحِ مِنْ أَمَامِ الرَّبِّ، وَمِلْءَ رَاحَتَيْهِ بَخُورًا عَطِرًا دَقِيقًا، وَيَدْخُلُ بِهِمَا إِلَى دَاخِلِ الْحِجَابِ', 'لاويين 16:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 13, 'وَيَجْعَلُ الْبَخُورَ عَلَى النَّارِ أَمَامَ الرَّبِّ، فَتُغَشِّي سَحَابَةُ الْبَخُورِ الْغِطَاءَ الَّذِي عَلَى الشَّهَادَةِ فَلَا يَمُوتُ.', 'لاويين 16:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 14, 'ثُمَّ يَأْخُذُ مِنْ دَمِ الثَّوْرِ وَيَنْضِحُ بِإِصْبَعِهِ عَلَى وَجْهِ الْغِطَاءِ إِلَى الشَّرْقِ. وَقُدَّامَ الْغِطَاءِ يَنْضِحُ سَبْعَ مَرَّاتٍ مِنَ الدَّمِ بِإِصْبَعِهِ.', 'لاويين 16:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 15, '«ثُمَّ يَذْبَحُ تَيْسَ الْخَطِيَّةِ الَّذِي لِلشَّعْبِ، وَيَدْخُلُ بِدَمِهِ إِلَى دَاخِلِ الْحِجَابِ. وَيَفْعَلُ بِدَمِهِ كَمَا فَعَلَ بِدَمِ الثَّوْرِ׃ يَنْضِحُهُ عَلَى الْغِطَاءِ وَقُدَّامَ الْغِطَاءِ،', 'لاويين 16:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 16, 'فَيُكَفِّرُ عَنِ الْقُدْسِ مِنْ نَجَاسَاتِ بَنِي إِسْرَائِيلَ وَمِنْ سَيِّئَاتِهِمْ مَعَ كُلِّ خَطَايَاهُمْ. وَهَكَذَا يَفْعَلُ لِخَيْمَةِ الِاجْتِمَاعِ الْقَائِمَةِ بَيْنَهُمْ فِي وَسَطِ نَجَاسَاتِهِمْ.', 'لاويين 16:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 17, 'وَلَا يَكُنْ إِنْسَانٌ فِي خَيْمَةِ الِاجْتِمَاعِ مِنْ دُخُولِهِ لِلتَّكْفِيرِ فِي الْقُدْسِ إِلَى خُرُوجِهِ، فَيُكَفِّرُ عَنْ نَفْسِهِ وَعَنْ بَيْتِهِ وَعَنْ كُلِّ جَمَاعَةِ إِسْرَائِيلَ.', 'لاويين 16:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 18, 'ثُمَّ يَخْرُجُ إِلَى الْمَذْبَحِ الَّذِي أَمَامَ الرَّبِّ وَيُكَفِّرُ عَنْهُ. يَأْخُذُ مِنْ دَمِ الثَّوْرِ وَمِنْ دَمِ التَّيْسِ وَيَجْعَلُ عَلَى قُرُونِ الْمَذْبَحِ مُسْتَدِيرًا.', 'لاويين 16:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 19, 'وَيَنْضِحُ عَلَيْهِ مِنَ الدَّمِ بِإِصْبَعِهِ سَبْعَ مَرَّاتٍ، وَيُطَهِّرُهُ وَيُقَدِّسُهُ مِنْ نَجَاسَاتِ بَنِي إِسْرَائِيلَ.', 'لاويين 16:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 20, '«وَمَتَى فَرَغَ مِنَ التَّكْفِيرِ عَنِ الْقُدْسِ وَعَنْ خَيْمَةِ الِاجْتِمَاعِ وَعَنِ الْمَذْبَحِ، يُقَدِّمُ التَّيْسَ الْحَيَّ.', 'لاويين 16:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 21, 'وَيَضَعُ هَارُونُ يَدَيْهِ عَلَى رَأْسِ التَّيْسِ الْحَيِّ وَيُقِرُّ عَلَيْهِ بِكُلِّ ذُنُوبِ بَنِي إِسْرَائِيلَ، وَكُلِّ سَيِّئَاتِهِمْ مَعَ كُلِّ خَطَايَاهُمْ، وَيَجْعَلُهَا عَلَى رَأْسِ التَّيْسِ، وَيُرْسِلُهُ بِيَدِ مَنْ يُلَاقِيهِ إِلَى الْبَرِّيَّةِ،', 'لاويين 16:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 22, 'لِيَحْمِلَ التَّيْسُ عَلَيْهِ كُلَّ ذُنُوبِهِمْ إِلَى أَرْضٍ مُقْفِرَةٍ، فَيُطْلِقُ التَّيْسَ فِي الْبَرِّيَّةِ.', 'لاويين 16:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 23, 'ثُمَّ يَدْخُلُ هَارُونُ إِلَى خَيْمَةِ الِاجْتِمَاعِ وَيَخْلَعُ ثِيَابَ الْكَتَّانِ الَّتِي لَبِسَهَا عِنْدَ دُخُولِهِ إِلَى الْقُدْسِ وَيَضَعُهَا هُنَاكَ.', 'لاويين 16:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 24, 'وَيَرْحَضُ جَسَدَهُ بِمَاءٍ فِي مَكَانٍ مُقَدَّسٍ، ثُمَّ يَلْبَسُ ثِيَابَهُ وَيَخْرُجُ وَيَعْمَلُ مُحْرَقَتَهُ وَمُحْرَقَةَ الشَّعْبِ، وَيُكَفِّرُ عَنْ نَفْسِهِ وَعَنِ الشَّعْبِ.', 'لاويين 16:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 25, 'وَشَحْمُ ذَبِيحَةِ الْخَطِيَّةِ يُوقِدُهُ عَلَى الْمَذْبَحِ.', 'لاويين 16:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 26, 'وَالَّذِي أَطْلَقَ التَّيْسَ إِلَى عَزَازِيلَ يَغْسِلُ ثِيَابَهُ وَيَرْحَضُ جَسَدَهُ بِمَاءٍ، وَبَعْدَ ذَلِكَ يَدْخُلُ إِلَى الْمَحَلَّةِ.', 'لاويين 16:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 27, 'وَثَوْرُ الْخَطِيَّةِ وَتَيْسُ الْخَطِيَّةِ اللَّذَانِ أُتِيَ بِدَمِهِمَا لِلتَّكْفِيرِ فِي الْقُدْسِ يُخْرِجُهُمَا إِلَى خَارِجِ الْمَحَلَّةِ، وَيُحْرِقُونَ بِالنَّارِ جِلْدَيْهِمَا وَلَحْمَهُمَا وَفَرْثَهُمَا.', 'لاويين 16:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 28, 'وَالَّذِي يُحْرِقُهُمَا يَغْسِلُ ثِيَابَهُ وَيَرْحَضُ جَسَدَهُ بِمَاءٍ، وَبَعْدَ ذَلِكَ يَدْخُلُ إِلَى الْمَحَلَّةِ.', 'لاويين 16:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 29, '«وَيَكُونُ لَكُمْ فَرِيضَةً دَهْرِيَّةً، أَنَّكُمْ فِي الشَّهْرِ السَّابِعِ فِي عَاشِرِ الشَّهْرِ تُذَلِّلُونَ نُفُوسَكُمْ، وَكُلَّ عَمَلٍ لَا تَعْمَلُونَ׃ الْوَطَنِيُّ وَالْغَرِيبُ النَّازِلُ فِي وَسَطِكُمْ.', 'لاويين 16:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 30, 'لِأَنَّهُ فِي هَذَا الْيَوْمِ يُكَفِّرُ عَنْكُمْ لِتَطْهِيرِكُمْ. مِنْ جَمِيعِ خَطَايَاكُمْ أَمَامَ الرَّبِّ تَطْهُرُونَ.', 'لاويين 16:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 31, 'سَبْتُ عُطْلَةٍ هُوَ لَكُمْ، وَتُذَلِّلُونَ نُفُوسَكُمْ فَرِيضَةً دَهْرِيَّةً.', 'لاويين 16:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 32, 'وَيُكَفِّرُ الْكَاهِنُ الَّذِي يَمْسَحُهُ، وَالَّذِي يَمْلَأُ يَدَهُ لِلْكَهَانَةِ عِوَضًا عَنْ أَبِيهِ. يَلْبَسُ ثِيَابَ الْكَتَّانِ، الثِّيَابَ الْمُقَدَّسَةَ،', 'لاويين 16:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 33, 'وَيُكَفِّرُ عَنْ مَقْدِسِ الْقُدْسِ. وَعَنْ خَيْمَةِ الِاجْتِمَاعِ وَالْمَذْبَحِ يُكَفِّرُ. وَعَنِ الْكَهَنَةِ وَكُلِّ شَعْبِ الْجَمَاعَةِ يُكَفِّرُ.', 'لاويين 16:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 16, 34, 'وَتَكُونُ هَذِهِ لَكُمْ فَرِيضَةً دَهْرِيَّةً لِلتَّكْفِيرِ عَنْ بَنِي إِسْرَائِيلَ مِنْ جَمِيعِ خَطَايَاهُمْ مَرَّةً فِي السَّنَةِ». فَفَعَلَ كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 16:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 17:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 2, '«كَلِّمْ هَارُونَ وَبَنِيهِ وَجَمِيعَ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ هَذَا هُوَ الْأَمْرُ الَّذِي يُوصِي بِهِ الرَّبُّ قَائِلًا׃', 'لاويين 17:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 3, 'كُلُّ إِنْسَانٍ مِنْ بَيْتِ إِسْرَائِيلَ يَذْبَحُ بَقَرًا أَوْ غَنَمًا أَوْ مِعْزًى فِي الْمَحَلَّةِ، أَوْ يَذْبَحُ خَارِجَ الْمَحَلَّةِ،', 'لاويين 17:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 4, 'وَإِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ لَا يَأْتِي بِهِ لِيُقَرِّبَ قُرْبَانًا لِلرَّبِّ أَمَامَ مَسْكَنِ الرَّبِّ، يُحْسَبُ عَلَى ذَلِكَ الْإِنْسَانِ دَمٌ. قَدْ سَفَكَ دَمًا. فَيُقْطَعُ ذَلِكَ الْإِنْسَانُ مِنْ شَعْبِهِ.', 'لاويين 17:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 5, 'لِكَيْ يَأْتِيَ بَنُو إِسْرَائِيلَ بِذَبَائِحِهِمِ الَّتِي يَذْبَحُونَهَا عَلَى وَجْهِ الصَّحْرَاءِ وَيُقَدِّمُوهَا لِلرَّبِّ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ إِلَى الْكَاهِنِ، وَيَذْبَحُوهَا ذَبَائِحَ سَلَامَةٍ لِلرَّبِّ.', 'لاويين 17:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 6, 'وَيَرُشُّ الْكَاهِنُ الدَّمَ عَلَى مَذْبَحِ الرَّبِّ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ، وَيُوقِدُ الشَّحْمَ لِرَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 17:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 7, 'وَلَا يَذْبَحُوا بَعْدُ ذَبَائِحَهُمْ لِلتُّيُوسِ الَّتِي هُمْ يَزْنُونَ وَرَاءَهَا. فَرِيضَةً دَهْرِيَّةً تَكُونُ هَذِهِ لَهُمْ فِي أَجْيَالِهِمْ.', 'لاويين 17:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 8, '«وَتَقُولُ لَهُمْ׃ كُلُّ إِنْسَانٍ مِنْ بَيْتِ إِسْرَائِيلَ وَمِنَ الْغُرَبَاءِ الَّذِينَ يَنْزِلُونَ فِي وَسَطِكُمْ يُصْعِدُ مُحْرَقَةً أَوْ ذَبِيحَةً،', 'لاويين 17:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 9, 'وَلَا يَأْتِي بِهَا إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ لِيَصْنَعَهَا لِلرَّبِّ، يُقْطَعُ ذَلِكَ الْإِنْسَانُ مِنْ شَعْبِهِ.', 'لاويين 17:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 10, 'وَكُلُّ إِنْسَانٍ مِنْ بَيْتِ إِسْرَائِيلَ وَمِنَ الْغُرَبَاءِ النَّازِلِينَ فِي وَسَطِكُمْ يَأْكُلُ دَمًا، أَجْعَلُ وَجْهِي ضِدَّ النَّفْسِ الْآكِلَةِ الدَّمِ وَأَقْطَعُهَا مِنْ شَعْبِهَا،', 'لاويين 17:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 11, 'لِأَنَّ نَفْسَ الْجَسَدِ هِيَ فِي الدَّمِ، فَأَنَا أَعْطَيْتُكُمْ إِيَّاهُ عَلَى الْمَذْبَحِ لِلتَّكْفِيرِ عَنْ نُفُوسِكُمْ، لِأَنَّ الدَّمَ يُكَفِّرُ عَنِ النَّفْسِ.', 'لاويين 17:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 12, 'لِذَلِكَ قُلْتُ لِبَنِي إِسْرَائِيلَ׃ لَا تَأْكُلْ نَفْسٌ مِنْكُمْ دَمًا، وَلَا يَأْكُلِ الْغَرِيبُ النَّازِلُ فِي وَسَطِكُمْ دَمًا.', 'لاويين 17:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 13, 'وَكُلُّ إِنْسَانٍ مِنْ بَنِي إِسْرَائِيلَ وَمِنَ الْغُرَبَاءِ النَّازِلِينَ فِي وَسَطِكُمْ يَصْطَادُ صَيْدًا، وَحْشًا أَوْ طَائِرًا يُؤْكَلُ، يَسْفِكُ دَمَهُ وَيُغَطِّيهِ بِالتُّرَابِ.', 'لاويين 17:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 14, 'لِأَنَّ نَفْسَ كُلِّ جَسَدٍ دَمُهُ هُوَ بِنَفْسِهِ، فَقُلْتُ لِبَنِي إِسْرَائِيلَ׃ لَا تَأْكُلُوا دَمَ جَسَدٍ مَّا، لِأَنَّ نَفْسَ كُلِّ جَسَدٍ هِيَ دَمُهُ. كُلُّ مَنْ أَكَلَهُ يُقْطَعُ.', 'لاويين 17:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 15, 'وَكُلُّ إِنْسَانٍ يَأْكُلُ مَيْتَةً أَوْ فَرِيسَةً، وَطَنِيًّا كَانَ أَوْ غَرِيبًا، يَغْسِلُ ثِيَابَهُ وَيَسْتَحِمُّ بِمَاءٍ، وَيَبْقَى نَجِسًا إِلَى الْمَسَاءِ ثُمَّ يَكُونُ طَاهِرًا.', 'لاويين 17:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 17, 16, 'وَإِنْ لَمْ يَغْسِلْ وَلَمْ يَرْحَضْ جَسَدَهُ يَحْمِلْ ذَنْبَهُ».', 'لاويين 17:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 18:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 18:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 3, 'مِثْلَ عَمَلِ أَرْضِ مِصْرَ الَّتِي سَكَنْتُمْ فِيهَا لَا تَعْمَلُوا، وَمِثْلَ عَمَلِ أَرْضِ كَنْعَانَ الَّتِي أَنَا آتٍ بِكُمْ إِلَيْهَا لَا تَعْمَلُوا، وَحَسَبَ فَرَائِضِهِمْ لَا تَسْلُكُوا.', 'لاويين 18:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 4, 'أَحْكَامِي تَعْمَلُونَ، وَفَرَائِضِي تَحْفَظُونَ لِتَسْلُكُوا فِيهَا. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 18:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 5, 'فَتَحْفَظُونَ فَرَائِضِي وَأَحْكَامِي، الَّتِي إِذَا فَعَلَهَا الْإِنْسَانُ يَحْيَا بِهَا. أَنَا الرَّبُّ.', 'لاويين 18:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 6, '«لَا يَقْتَرِبْ إِنْسَانٌ إِلَى قَرِيبِ جَسَدِهِ لِيَكْشِفَ الْعَوْرَةَ. أَنَا الرَّبُّ.', 'لاويين 18:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 7, 'عَوْرَةَ أَبِيكَ وَعَوْرَةَ أُمِّكَ لَا تَكْشِفْ. إِنَّهَا أُمُّكَ لَا تَكْشِفْ عَوْرَتَهَا.', 'لاويين 18:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 8, 'عَوْرَةَ امْرَأَةِ أَبِيكَ لَا تَكْشِفْ. إِنَّهَا عَوْرَةُ أَبِيكَ.', 'لاويين 18:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 9, 'عَوْرَةَ أُخْتِكَ بِنْتِ أَبِيكَ أَوْ بِنْتِ أُمِّكَ، الْمَوْلُودَةِ فِي الْبَيْتِ أَوِ الْمَوْلُودَةِ خَارِجًا، لَا تَكْشِفْ عَوْرَتَهَا.', 'لاويين 18:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 10, 'عَوْرَةَ ابْنَةِ ابْنِكَ، أَوِ ابْنَةِ بِنْتِكَ لَا تَكْشِفْ عَوْرَتَهَا. إِنَّهَا عَوْرَتُكَ.', 'لاويين 18:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 11, 'عَوْرَةَ بِنْتِ امْرَأَةِ أَبِيكَ الْمَوْلُودَةِ مِنْ أَبِيكَ لَا تَكْشِفْ عَوْرَتَهَا. إِنَّهَا أُخْتُكَ.', 'لاويين 18:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 12, 'عَوْرَةَ أُخْتِ أَبِيكَ لَا تَكْشِفْ. إِنَّهَا قَرِيبَةُ أَبِيكَ.', 'لاويين 18:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 13, 'عَوْرَةَ أُخْتِ أُمِّكَ لَا تَكْشِفْ. إِنَّهَا قَرِيبَةُ أُمِّكَ.', 'لاويين 18:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 14, 'عَوْرَةَ أَخِي أَبِيكَ لَا تَكْشِفْ. إِلَى امْرَأَتِهِ لَا تَقْتَرِبْ. إِنَّهَا عَمَّتُكَ.', 'لاويين 18:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 15, 'عَوْرَةَ كَنَّتِكَ لَا تَكْشِفْ. إِنَّهَا امْرَأَةُ ابْنِكَ. لَا تَكْشِفْ عَوْرَتَهَا.', 'لاويين 18:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 16, 'عَوْرَةَ امْرَأَةِ أَخِيكَ لَا تَكْشِفْ. إِنَّهَا عَوْرَةُ أَخِيكَ.', 'لاويين 18:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 17, 'عَوْرَةَ امْرَأَةٍ وَبِنْتِهَا لَا تَكْشِفْ. وَلَا تَأْخُذِ ابْنَةَ ابْنِهَا، أَوِ ابْنَةَ بِنْتِهَا لِتَكْشِفَ عَوْرَتَهَا. إِنَّهُمَا قَرِيبَتَاهَا. إِنَّهُ رَذِيلَةٌ.', 'لاويين 18:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 18, 'وَلَا تَأْخُذِ امْرَأَةً عَلَى أُخْتِهَا لِلضِّرِّ لِتَكْشِفَ عَوْرَتَهَا مَعَهَا فِي حَيَاتِهَا.', 'لاويين 18:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 19, '«وَلَا تَقْتَرِبْ إِلَى امْرَأَةٍ فِي نَجَاسَةِ طَمْثِهَا لِتَكْشِفَ عَوْرَتَهَا.', 'لاويين 18:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 20, 'وَلَا تَجْعَلْ مَعَ امْرَأَةِ صَاحِبِكَ مَضْجَعَكَ لِزَرْعٍ، فَتَتَنَجَّسَ بِهَا.', 'لاويين 18:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 21, 'وَلَا تُعْطِ مِنْ زَرْعِكَ لِلْإِجَازَةِ لِمُولَكَ لِئَلَّا تُدَنِّسَ اسْمَ إِلَهِكَ. أَنَا الرَّبُّ.', 'لاويين 18:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 22, 'وَلَا تُضَاجِعْ ذَكَرًا مُضَاجَعَةَ امْرَأَةٍ. إِنَّهُ رِجْسٌ.', 'لاويين 18:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 23, 'وَلَا تَجْعَلْ مَعَ بَهِيمَةٍ مَضْجَعَكَ فَتَتَنَجَّسَ بِهَا. وَلَا تَقِفِ امْرَأَةٌ أَمَامَ بَهِيمَةٍ لِنِزَائِهَا. إِنَّهُ فَاحِشَةٌ.', 'لاويين 18:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 24, '«بِكُلِّ هَذِهِ لَا تَتَنَجَّسُوا، لِأَنَّهُ بِكُلِّ هَذِهِ قَدْ تَنَجَّسَ الشُّعُوبُ الَّذِينَ أَنَا طَارِدُهُمْ مِنْ أَمَامِكُمْ', 'لاويين 18:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 25, 'فَتَنَجَّسَتِ الْأَرْضُ. فَأَجْتَزِي ذَنْبَهَا مِنْهَا، فَتَقْذِفُ الْأَرْضُ سُكَّانَهَا.', 'لاويين 18:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 26, 'لَكِنْ تَحْفَظُونَ أَنْتُمْ فَرَائِضِي وَأَحْكَامِي، وَلَا تَعْمَلُونَ شَيْئًا مِنْ جَمِيعِ هَذِهِ الرَّجَسَاتِ، لَا الْوَطَنِيُّ وَلَا الْغَرِيبُ النَّازِلُ فِي وَسَطِكُمْ،', 'لاويين 18:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 27, 'لِأَنَّ جَمِيعَ هَذِهِ الرَّجَسَاتِ قَدْ عَمِلَهَا أَهْلُ الْأَرْضِ الَّذِينَ قَبْلَكُمْ فَتَنَجَّسَتِ الْأَرْضُ.', 'لاويين 18:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 28, 'فَلَا تَقْذِفُكُمُ الْأَرْضُ بِتَنْجِيسِكُمْ إِيَّاهَا كَمَا قَذَفَتِ الشُّعُوبَ الَّتِي قَبْلَكُمْ.', 'لاويين 18:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 29, 'بَلْ كُلُّ مَنْ عَمِلَ شَيْئًا مِنْ جَمِيعِ هَذِهِ الرَّجَسَاتِ تُقْطَعُ الْأَنْفُسُ الَّتِي تَعْمَلُهَا مِنْ شَعْبِهَا.', 'لاويين 18:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 18, 30, 'فَتَحْفَظُونَ شَعَائِرِي لِكَيْ لَا تَعْمَلُوا شَيْئًا مِنَ الرُّسُومِ الرَّجِسَةِ الَّتِي عُمِلَتْ قَبْلَكُمْ وَلَا تَتَنَجَّسُوا بِهَا. أَنَا الرَّبُّ إِلَهُكُمْ».', 'لاويين 18:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 19:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 2, '«كَلِّمْ كُلَّ جَمَاعَةِ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ تَكُونُونَ قِدِّيسِينَ لِأَنِّي قُدُّوسٌ الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 3, 'تَهَابُونَ كُلُّ إِنْسَانٍ أُمَّهُ وَأَبَاهُ، وَتَحْفَظُونَ سُبُوتِي. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 4, 'لَا تَلْتَفِتُوا إِلَى الْأَوْثَانِ، وَآلِهَةً مَسْبُوكَةً لَا تَصْنَعُوا لِأَنْفُسِكُمْ. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 5, 'وَمَتَى ذَبَحْتُمْ ذَبِيحَةَ سَلَامَةٍ لِلرَّبِّ فَلِلرِّضَا عَنْكُمْ تَذْبَحُونَهَا.', 'لاويين 19:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 6, 'يَوْمَ تَذْبَحُونَهَا تُؤْكَلُ، وَفِي الْغَدِ. وَالْفَاضِلُ إِلَى الْيَوْمِ الثَّالِثِ يُحْرَقُ بِالنَّارِ.', 'لاويين 19:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 7, 'وَإِذَا أُكِلَتْ فِي الْيَوْمِ الثَّالِثِ فَذَلِكَ نَجَاسَةٌ لَا يُرْضَى بِهِ.', 'لاويين 19:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 8, 'وَمَنْ أَكَلَ مِنْهَا يَحْمِلُ ذَنْبَهُ لِأَنَّهُ قَدْ دَنَّسَ قُدْسَ الرَّبِّ. فَتُقْطَعُ تِلْكَ النَّفْسُ مِنْ شَعْبِهَا.', 'لاويين 19:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 9, '«وَعِنْدَمَا تَحْصُدُونَ حَصِيدَ أَرْضِكُمْ لَا تُكَمِّلْ زَوَايَا حَقْلِكَ فِي الْحَصَادِ. وَلُقَاطَ حَصِيدِكَ لَا تَلْتَقِطْ.', 'لاويين 19:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 10, 'وَكَرْمَكَ لَا تُعَلِّلْهُ، وَنِثَارَ كَرْمِكَ لَا تَلْتَقِطْ. لِلْمِسْكِينِ وَالْغَرِيبِ تَتْرُكُهُ. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 11, '«لَا تَسْرِقُوا، وَلَا تَكْذِبُوا، وَلَا تَغْدُرُوا أَحَدُكُمْ بِصَاحِبِهِ.', 'لاويين 19:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 12, 'وَلَا تَحْلِفُوا بِاسْمِي لِلْكَذِبِ، فَتُدَنِّسَ اسْمَ إِلَهِكَ. أَنَا الرَّبُّ.', 'لاويين 19:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 13, '«لَا تَغْصِبْ قَرِيبَكَ وَلَا تَسْلُبْ، وَلَا تَبِتْ أُجْرَةُ أَجِيرٍ عِنْدَكَ إِلَى الْغَدِ.', 'لاويين 19:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 14, 'لَا تَشْتِمِ الْأَصَمَّ، وَقُدَّامَ الْأَعْمَى لَا تَجْعَلْ مَعْثَرَةً، بَلِ اخْشَ إِلَهَكَ. أَنَا الرَّبُّ.', 'لاويين 19:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 15, 'لَا تَرْتَكِبُوا جَوْرًا فِي الْقَضَاءِ. لَاتَأْخُذُوا بِوَجْهِ مِسْكِينٍ وَلَا تَحْتَرِمْ وَجْهَ كَبِيرٍ. بِالْعَدْلِ تَحْكُمُ لِقَرِيبِكَ.', 'لاويين 19:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 16, 'لَا تَسْعَ فِي الْوِشَايَةِ بَيْنَ شَعْبِكَ. لَا تَقِفْ عَلَى دَمِ قَرِيبِكَ. أَنَا الرَّبُّ.', 'لاويين 19:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 17, 'لَا تُبْغِضْ أَخَاكَ فِي قَلْبِكَ. إِنْذَارًا تُنْذِرُ صَاحِبَكَ، وَلَا تَحْمِلْ لِأَجْلِهِ خَطِيَّةً.', 'لاويين 19:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 18, 'لَا تَنْتَقِمْ وَلَا تَحْقِدْ عَلَى أَبْنَاءِ شَعْبِكَ، بَلْ تُحِبُّ قَرِيبَكَ كَنَفْسِكَ. أَنَا الرَّبُّ.', 'لاويين 19:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 19, 'فَرَائِضِي تَحْفَظُونَ. لَا تُنَزِّ بَهَائِمَكَ جِنْسَيْنِ، وَحَقْلَكَ لَا تَزْرَعْ صِنْفَيْنِ، وَلَا يَكُنْ عَلَيْكَ ثَوْبٌ مُصَنَّفٌ مِنْ صِنْفَيْنِ.', 'لاويين 19:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 20, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ امْرَأَةٍ اضْطِجَاعَ زَرْعٍ وَهِيَ أَمَةٌ مَخْطُوبَةٌ لِرَجُلٍ، وَلَمْ تُفْدَ فِدَاءً وَلَا أُعْطِيَتْ حُرِّيَّتَهَا، فَلْيَكُنْ تَأْدِيبٌ. لَا يُقْتَلَا لِأَنَّهَا لَمْ تُعْتَقْ.', 'لاويين 19:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 21, 'وَيَأْتِي إِلَى الرَّبِّ بِذَبِيحَةٍ لِإِثْمِهِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ׃ كَبْشًا، ذَبِيحَةَ إِثْمٍ.', 'لاويين 19:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 22, 'فَيُكَفِّرُ عَنْهُ الْكَاهِنُ بِكَبْشِ الْإِثْمِ أَمَامَ الرَّبِّ مِنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ، فَيُصْفَحُ لَهُ عَنْ خَطِيَّتِهِ الَّتِي أَخْطَأَ.', 'لاويين 19:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 23, '«وَمَتَى دَخَلْتُمُ الْأَرْضَ وَغَرَسْتُمْ كُلَّ شَجَرَةٍ لِلطَّعَامِ، تَحْسِبُونَ ثَمَرَهَا غُرْلَتَهَا. ثَلَاثَ سِنِينَ تَكُونُ لَكُمْ غَلْفَاءَ. لَا يُؤْكَلْ مِنْهَا.', 'لاويين 19:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 24, 'وَفِي السَّنَةِ الرَّابِعَةِ يَكُونُ كُلُّ ثَمَرِهَا قُدْسًا لِتَمْجِيدِ الرَّبِّ.', 'لاويين 19:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 25, 'وَفِي السَّنَةِ الْخَامِسَةِ تَأْكُلُونَ ثَمَرَهَا، لِتَزِيدَ لَكُمْ غَلَّتَهَا. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 26, '«لَا تَأْكُلُوا بِالدَّمِ. لَا تَتَفَاءَلُوا وَلَا تَعِيفُوا.', 'لاويين 19:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 27, 'لَا تُقَصِّرُوا رُؤُوسَكُمْ مُسْتَدِيرًا، وَلَا تُفْسِدْ عَارِضَيْكَ.', 'لاويين 19:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 28, 'وَلَا تَجْرَحُوا أَجْسَادَكُمْ لِمَيْتٍ. وَكِتَابَةَ وَسْمٍ لَا تَجْعَلُوا فِيكُمْ. أَنَا الرَّبُّ.', 'لاويين 19:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 29, 'لَا تُدَنِّسِ ابْنَتَكَ بِتَعْرِيضِهَا لِلزِّنَى لِئَلَّا تَزْنِيَ الْأَرْضُ وَتَمْتَلِئَ الْأَرْضُ رَذِيلَةً.', 'لاويين 19:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 30, 'سُبُوتِي تَحْفَظُونَ، وَمَقْدِسِي تَهَابُونَ. أَنَا الرَّبُّ.', 'لاويين 19:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 31, 'لَا تَلْتَفِتُوا إِلَى الْجَانِّ وَلَا تَطْلُبُوا التَّوَابِعَ، فَتَتَنَجَّسُوا بِهِمْ. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 32, 'مِنْ أَمَامِ الْأَشْيَبِ تَقُومُ وَتَحْتَرِمُ وَجْهَ الشَّيْخِ، وَتَخْشَى إِلَهَكَ. أَنَا الرَّبُّ.', 'لاويين 19:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 33, '«وَإِذَا نَزَلَ عِنْدَكَ غَرِيبٌ فِي أَرْضِكُمْ فَلَا تَظْلِمُوهُ.', 'لاويين 19:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 34, 'كَالْوَطَنِيِّ مِنْكُمْ يَكُونُ لَكُمُ الْغَرِيبُ النَّازِلُ عِنْدَكُمْ، وَتُحِبُّهُ كَنَفْسِكَ، لِأَنَّكُمْ كُنْتُمْ غُرَبَاءَ فِي أَرْضِ مِصْرَ. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 19:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 35, 'لَا تَرْتَكِبُوا جَوْرًا فِي الْقَضَاءِ، لَا فِي الْقِيَاسِ، وَلَا فِي الْوَزْنِ، وَلَا فِي الْكَيْلِ.', 'لاويين 19:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 36, 'مِيزَانُ حَقٍّ، وَوَزْنَاتُ حَقٍّ، وَإِيفَةُ حَقٍّ، وَهِينُ حَقٍّ تَكُونُ لَكُمْ. أَنَا الرَّبُّ إِلَهُكُمُ الَّذِي أَخْرَجَكُمْ مِنْ أَرْضِ مِصْرَ.', 'لاويين 19:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 19, 37, 'فَتَحْفَظُونَ كُلَّ فَرَائِضِي، وَكُلَّ أَحْكَامِي، وَتَعْمَلُونَهَا. أَنَا الرَّبُّ».', 'لاويين 19:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 20:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 2, '«وَتَقُولُ لِبَنِي إِسْرَائِيلَ׃ كُلُّ إِنْسَانٍ مِنْ بَنِي إِسْرَائِيلَ وَمِنَ الْغُرَبَاءِ النَّازِلِينَ فِي إِسْرَائِيلَ أَعْطَى مِنْ زَرْعِهِ لِمُولَكَ فَإِنَّهُ يُقْتَلُ. يَرْجُمُهُ شَعْبُ الْأَرْضِ بِالْحِجَارَةِ.', 'لاويين 20:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 3, 'وَأَجْعَلُ أَنَا وَجْهِي ضِدَّ ذَلِكَ الْإِنْسَانِ، وَأَقْطَعُهُ مِنْ شَعْبِهِ، لِأَنَّهُ أَعْطَى مِنْ زَرْعِهِ لِمُولَكَ لِكَيْ يُنَجِّسَ مَقْدِسِي، وَيُدَنِّسَ اسْمِيَ الْقُدُّوسَ.', 'لاويين 20:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 4, 'وَإِنْ غَمَّضَ شَعْبُ الْأَرْضِ أَعْيُنَهُمْ عَنْ ذَلِكَ الْإِنْسَانِ عِنْدَمَا يُعْطِي مِنْ زَرْعِهِ لِمُولَكَ، فَلَمْ يَقْتُلُوهُ،', 'لاويين 20:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 5, 'فَإِنِّي أَضَعُ وَجْهِي ضِدَّ ذَلِكَ الْإِنْسَانِ، وَضِدَّ عَشِيرَتِهِ، وَأَقْطَعُهُ وَجَمِيعَ الْفَاجِرِينَ وَرَاءَهُ، بِالزِّنَى وَرَاءَ مُولَكَ مِنْ شَعْبِهِمْ.', 'لاويين 20:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 6, 'وَالنَّفْسُ الَّتِي تَلْتَفِتُ إِلَى الْجَانِّ، وَإِلَى التَّوَابِعِ لِتَزْنِيَ وَرَاءَهُمْ، أَجْعَلُ وَجْهِي ضِدَّ تِلْكَ النَّفْسِ وَأَقْطَعُهَا مِنْ شَعْبِهَا.', 'لاويين 20:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 7, 'فَتَتَقَدَّسُونَ وَتَكُونُونَ قِدِّيسِينَ، لِأَنِّي أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 20:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 8, 'وَتَحْفَظُونَ فَرَائِضِي وَتَعْمَلُونَهَا. أَنَا الرَّبُّ مُقَدِّسُكُمْ.', 'لاويين 20:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 9, '«كُلُّ إِنْسَانٍ سَبَّ أَبَاهُ أَوْ أُمَّهُ فَإِنَّهُ يُقْتَلُ. قَدْ سَبَّ أَبَاهُ أَوْ أُمَّهُ. دَمُهُ عَلَيْهِ.', 'لاويين 20:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 10, 'وَإِذَا زَنَى رَجُلٌ مَعَ امْرَأَةٍ، فَإِذَا زَنَى مَعَ امْرَأَةِ قَرِيبِهِ، فَإِنَّهُ يُقْتَلُ الزَّانِي وَالزَّانِيَةُ.', 'لاويين 20:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 11, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ امْرَأَةِ أَبِيهِ، فَقَدْ كَشَفَ عَوْرَةَ أَبِيهِ. إِنَّهُمَا يُقْتَلَانِ كِلَاهُمَا. دَمُهُمَا عَلَيْهِمَا.', 'لاويين 20:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 12, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ كَنَّتِهِ، فَإِنَّهُمَا يُقْتَلَانِ كِلَاهُمَا. قَدْ فَعَلَا فَاحِشَةً. دَمُهُمَا عَلَيْهِمَا.', 'لاويين 20:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 13, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ ذَكَرٍ اضْطِجَاعَ امْرَأَةٍ، فَقَدْ فَعَلَا كِلَاهُمَا رِجْسًا. إِنَّهُمَا يُقْتَلَانِ. دَمُهُمَا عَلَيْهِمَا.', 'لاويين 20:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 14, 'وَإِذَا اتَّخَذَ رَجُلٌ امْرَأَةً وَأُمَّهَا فَذَلِكَ رَذِيلَةٌ. بِالنَّارِ يُحْرِقُونَهُ وَإِيَّاهُمَا، لِكَيْ لَا يَكُونَ رَذِيلَةٌ بَيْنَكُمْ.', 'لاويين 20:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 15, 'وَإِذَا جَعَلَ رَجُلٌ مَضْجَعَهُ مَعَ بَهِيمَةٍ، فَإِنَّهُ يُقْتَلُ، وَالْبَهِيمَةُ تُمِيتُونَهَا.', 'لاويين 20:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 16, 'وَإِذَا اقْتَرَبَتِ امْرَأَةٌ إِلَى بَهِيمَةٍ لِنِزَائِهَا، تُمِيتُ الْمَرْأَةَ وَالْبَهِيمَةَ. إِنَّهُمَا يُقْتَلَانِ. دَمُهُمَا عَلَيْهِمَا.', 'لاويين 20:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 17, 'وَإِذَا أَخَذَ رَجُلٌ أُخْتَهُ بِنْتَ أَبِيهِ أَوْ بِنْتَ أُمِّهِ، وَرَأَى عَوْرَتَهَا وَرَأَتْ هِيَ عَوْرَتَهُ، فَذَلِكَ عَارٌ. يُقْطَعَانِ أَمَامَ أَعْيُنِ بَنِي شَعْبِهِمَا. قَدْ كَشَفَ عَوْرَةَ أُخْتِهِ. يَحْمِلُ ذَنْبَهُ.', 'لاويين 20:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 18, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ امْرَأَةٍ طَامِثٍ وَكَشَفَ عَوْرَتَهَا، عَرَّى يَنْبُوعَهَا وَكَشَفَتْ هِيَ يَنْبُوعَ دَمِهَا، يُقْطَعَانِ كِلَاهُمَا مِنْ شَعِبْهِمَا.', 'لاويين 20:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 19, 'عَوْرَةَ أُخْتِ أُمِّكَ، أَوْ أُخْتِ أَبِيكَ لَا تَكْشِفْ. إِنَّهُ قَدْ عَرَّى قَرِيبَتَهُ. يَحْمِلَانِ ذَنْبَهُمَا.', 'لاويين 20:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 20, 'وَإِذَا اضْطَجَعَ رَجُلٌ مَعَ امْرَأَةِ عَمِّهِ فَقَدْ كَشَفَ عَوْرَةَ عَمِّهِ. يَحْمِلَانِ ذَنْبَهُمَا. يَمُوتَانِ عَقِيمَيْنِ.', 'لاويين 20:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 21, 'وَإِذَا أَخَذَ رَجُلٌ امْرَأَةَ أَخِيهِ، فَذَلِكَ نَجَاسَةٌ. قَدْ كَشَفَ عَوْرَةَ أَخِيهِ. يَكُونَانِ عَقِيمَيْنِ.', 'لاويين 20:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 22, '«فَتَحْفَظُونَ جَمِيعَ فَرَائِضِي وَجَمِيعَ أَحْكَامِي، وَتَعْمَلُونَهَا لِكَيْ لَا تَقْذِفَكُمُ الْأَرْضُ الَّتِي أَنَا آتٍ بِكُمْ إِلَيْهَا لِتَسْكُنُوا فِيهَا.', 'لاويين 20:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 23, 'وَلَا تَسْلُكُونَ فِي رُسُومِ الشُّعُوبِ الَّذِينَ أَنَا طَارِدُهُمْ مِنْ أَمَامِكُمْ. لِأَنَّهُمْ قَدْ فَعَلُوا كُلَّ هَذِهِ، فَكَرِهْتُهُمْ.', 'لاويين 20:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 24, 'وَقُلْتُ لَكُمْ׃ تَرِثُونَ أَنْتُمْ أَرْضَهُمْ، وَأَنَا أُعْطِيكُمْ إِيَّاهَا لِتَرِثُوهَا، أَرْضًا تَفِيضُ لَبَنًا وَعَسَلًا. أَنَا الرَّبُّ إِلَهُكُمُ الَّذِي مَيَّزَكُمْ مِنَ الشُّعُوبِ.', 'لاويين 20:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 25, 'فَتُمَيِّزُونَ بَيْنَ الْبَهَائِمِ الطَّاهِرَةِ وَالنَّجِسَةِ، وَبَيْنَ الطُّيُورِ النَّجِسَةِ وَالطَّاهِرَةِ. فَلَا تُدَنِّسُوا نُفُوسَكُمْ بِالْبَهَائِمِ وَالطُّيُورِ، وَلَا بِكُلِّ مَا يَدِبُّ عَلَى الْأَرْضِ مِمَّا مَيَّزْتُهُ لَكُمْ لِيَكُونَ نَجِسًا.', 'لاويين 20:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 26, 'وَتَكُونُونَ لِي قِدِّيسِينَ لِأَنِّي قُدُّوسٌ أَنَا الرَّبُّ، وَقَدْ مَيَّزْتُكُمْ مِنَ الشُّعُوبِ لِتَكُونُوا لِي.', 'لاويين 20:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 20, 27, '«وَإِذَا كَانَ فِي رَجُلٍ أَوِ امْرَأَةٍ جَانٌّ أَوْ تَابِعَةٌ فَإِنَّهُ يُقْتَلُ. بِالْحِجَارَةِ يَرْجُمُونَهُ. دَمُهُ عَلَيْهِ».', 'لاويين 20:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 1, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «كَلِّمِ الْكَهَنَةَ بَنِي هَارُونَ وَقُلْ لَهُمْ׃ لَا يَتَنَجَّسْ أَحَدٌ مِنْكُمْ لِمَيْتٍ فِي قَوْمِهِ،', 'لاويين 21:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 2, 'إِلَّا لِأَقْرِبَائِهِ الْأَقْرَبِ إِلَيْهِ׃ أُمِّهِ وَأَبِيهِ وَابْنِهِ وَابْنَتِهِ وَأَخِيهِ', 'لاويين 21:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 3, 'وَأُخْتِهِ الْعَذْرَاءِ الْقَرِيبَةِ إِلَيْهِ الَّتِي لَمْ تَصِرْ لِرَجُلٍ. لِأَجْلِهَا يَتَنَجَّسُ.', 'لاويين 21:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 4, 'كَزَوْجٍ لَا يَتَنَجَّسْ بِأَهْلِهِ لِتَدْنِيسِهِ.', 'لاويين 21:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 5, 'لَا يَجْعَلُوا قَرْعَةً فِي رُؤُوسِهِمْ، وَلَا يَحْلِقُوا عَوَارِضَ لِحَاهُمْ، وَلَا يَجْرَحُوا جِرَاحَةً فِي أَجْسَادِهِمْ.', 'لاويين 21:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 6, 'مُقَدَّسِينَ يَكُونُونَ لِإِلَهِهِمْ، وَلَا يُدَنِّسُونَ اسْمَ إِلَهِهِمْ، لِأَنَّهُمْ يُقَرِّبُونَ وَقَائِدَ الرَّبِّ طَعَامَ إِلَهِهِمْ، فَيَكُونُونَ قُدْسًا.', 'لاويين 21:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 7, 'اِمْرَأَةً زَانِيَةً أَوْ مُدَنَّسَةً لَا يَأْخُذُوا، وَلَا يَأْخُذُوا امْرَأَةً مُطَلَّقَةً مِنْ زَوْجِهَا. لِأَنَّهُ مُقَدَّسٌ لِإِلَهِهِ.', 'لاويين 21:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 8, 'فَتَحْسِبُهُ مُقَدَّسًا لِأَنَّهُ يُقَرِّبُ خُبْزَ إِلَهِكَ. مُقَدَّسًا يَكُونُ عِنْدَكَ لِأَنِّي قُدُّوسٌ أَنَا الرَّبُّ مُقَدِّسُكُمْ.', 'لاويين 21:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 9, 'وَإِذَا تَدَنَّسَتِ ابْنَةُ كَاهِنٍ بِالزِّنَى فَقَدْ دَنَّسَتْ أَبَاهَا. بِالنَّارِ تُحْرَقُ.', 'لاويين 21:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 10, '«وَالْكَاهِنُ الْأَعْظَمُ بَيْنَ إِخْوَتِهِ الَّذِي صُبَّ عَلَى رَأْسِهِ دُهْنُ الْمَسْحَةِ، وَمُلِئَتْ يَدُهُ لِيَلْبَسَ الثِّيَابَ، لَا يَكْشِفُ رَأْسَهُ، وَلَا يَشُقُّ ثِيَابَهُ،', 'لاويين 21:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 11, 'وَلَا يَأْتِي إِلَى نَفْسٍ مَيْتَةٍ، وَلَا يَتَنَجَّسُ لِأَبِيهِ أَوْ أُمِّهِ،', 'لاويين 21:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 12, 'وَلَا يَخْرُجُ مِنَ الْمَقْدِسِ لِئَلَّا يُدَنِّسَ مَقْدِسَ إِلَهِهِ، لِأَنَّ إِكْلِيلَ دُهْنِ مَسْحَةِ إِلَهِهِ عَلَيْهِ. أَنَا الرَّبُّ.', 'لاويين 21:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 13, 'هَذَا يَأْخُذُ امْرَأَةً عَذْرَاءَ.', 'لاويين 21:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 14, 'أَمَّا الْأَرْمَلَةُ وَالْمُطَلَّقَةُ وَالْمُدَنَّسَةُ وَالزَّانِيَةُ فَمِنْ هَؤُلَاءِ لَا يَأْخُذُ، بَلْ يَتَّخِذُ عَذْرَاءَ مِنْ قَوْمِهِ امْرَأَةً.', 'لاويين 21:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 15, 'وَلَا يُدَنِّسُ زَرْعَهُ بَيْنَ شَعْبِهِ لِأَنِّي أَنَا الرَّبُّ مُقَدِّسُهُ».', 'لاويين 21:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 16, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 21:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 17, '«كَلِّمْ هَارُونَ قَائِلًا׃ إِذَا كَانَ رَجُلٌ مِنْ نَسْلِكَ فِي أَجْيَالِهِمْ فِيهِ عَيْبٌ فَلَا يَتَقَدَّمْ لِيُقَرِّبَ خُبْزَ إِلَهِهِ.', 'لاويين 21:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 18, 'لِأَنَّ كُلَّ رَجُلٍ فِيهِ عَيْبٌ لَا يَتَقَدَّمْ. لَا رَجُلٌ أَعْمَى وَلَا أَعْرَجُ، وَلَا أَفْطَسُ وَلَا زَوَائِدِيٌّ،', 'لاويين 21:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 19, 'وَلَا رَجُلٌ فِيهِ كَسْرُ رِجْلٍ أَوْ كَسْرُ يَدٍ،', 'لاويين 21:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 20, 'وَلَا أَحْدَبُ وَلَا أَكْشَمُ، وَلَا مَنْ فِي عَيْنِهِ بَيَاضٌ، وَلَا أَجْرَبُ وَلَا أَكْلَفُ، وَلَا مَرْضُوضُ الْخُصَى.', 'لاويين 21:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 21, 'كُلُّ رَجُلٍ فِيهِ عَيْبٌ مِنْ نَسْلِ هَارُونَ الْكَاهِنِ لَا يَتَقَدَّمْ لِيُقَرِّبَ وَقَائِدَ الرَّبِّ. فِيهِ عَيْبٌ لَا يَتَقَدَّمْ لِيُقَرِّبَ خُبْزَ إِلَهِهِ.', 'لاويين 21:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 22, 'خُبْزَ إِلَهِهِ مِنْ قُدْسِ الْأَقْدَاسِ وَمِنَ الْقُدْسِ يَأْكُلُ.', 'لاويين 21:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 23, 'لَكِنْ إِلَى الْحِجَابِ لَا يَأْتِي، وَإِلَى الْمَذْبَحِ لَا يَقْتَرِبُ، لِأَنَّ فِيهِ عَيْبًا، لِئَلَّا يُدَنِّسَ مَقْدِسِي، لِأَنِّي أَنَا الرَّبُّ مُقَدِّسُهُمْ».', 'لاويين 21:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 21, 24, 'فَكَلَّمَ مُوسَى هَارُونَ وَبَنِيهِ وَكُلَّ بَنِي إِسْرَائِيلَ.', 'لاويين 21:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 22:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 2, '«كَلِّمْ هَارُونَ وَبَنِيهِ أَنْ يَتَوَقَّوْا أَقْدَاسَ بَنِي إِسْرَائِيلَ الَّتِي يُقَدِّسُونَهَا لِي وَلَا يُدَنِّسُوا اسْمِي الْقُدُّوسَ. أَنَا الرَّبُّ.', 'لاويين 22:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 3, 'قُلْ لَهُمْ׃ فِي أَجْيَالِكُمْ كُلُّ إِنْسَانٍ مِنْ جَمِيعِ نَسْلِكُمُ اقْتَرَبَ إِلَى الْأَقْدَاسِ الَّتِي يُقَدِّسُهَا بَنُو إِسْرَائِيلَ لِلرَّبِّ، وَنَجَاسَتُهُ عَلَيْهِ، تُقْطَعُ تِلْكَ النَّفْسُ مِنْ أَمَامِي. أَنَا الرَّبُّ.', 'لاويين 22:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 4, 'كُلُّ إِنْسَانٍ مِنْ نَسْلِ هَارُونَ وَهُوَ أَبْرَصُ أَوْ ذُو سَيْلٍ، لَا يَأْكُلْ مِنَ الْأَقْدَاسِ حَتَّى يَطْهُرَ. وَمَنْ مَسَّ شَيْئًا نَجِسًا لِمَيْتٍ، أَوْ إِنْسَانٌ حَدَثَ مِنْهُ اضْطِجَاعُ زَرْعٍ،', 'لاويين 22:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 5, 'أَوْ إِنْسَانٌ مَسَّ دَبِيبًا يَتَنَجَّسُ بِهِ، أَوْ إِنْسَانًا يَتَنَجَّسُ بِهِ لِنَجَاسَةٍ فِيهِ،', 'لاويين 22:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 6, 'فَالَّذِي يَمَسُّ ذَلِكَ يَكُونُ نَجِسًا إِلَى الْمَسَاءِ، وَلَا يَأْكُلْ مِنَ الْأَقْدَاسِ، بَلْ يَرْحَضُ جَسَدَهُ بِمَاءٍ.', 'لاويين 22:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 7, 'فَمَتَى غَرَبَتِ الشَّمْسُ يَكُونُ طَاهِرًا، ثُمَّ يَأْكُلُ مِنَ الْأَقْدَاسِ لِأَنَّهَا طَعَامُهُ.', 'لاويين 22:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 8, 'مِيْتَةً أَوْ فَرِيسَةً لَا يَأْكُلْ فَيَتَنَجَّسَ بِهَا. أَنَا الرَّبُّ.', 'لاويين 22:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 9, 'فَيَحْفَظُونَ شَعَائِرِي لِكَيْ لَا يَحْمِلُوا لِأَجْلِهَا خَطِيَّةً يَمُوتُونَ بِهَا لِأَنَّهُمْ يُدَنِّسُونَهَا. أَنَا الرَّبُّ مُقَدِّسُهُمْ.', 'لاويين 22:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 10, '«وَكُلُّ أَجْنَبِيٍّ لَا يَأْكُلُ قُدْسًا. نَزِيلُ كَاهِنٍ وَأَجِيرُهُ لَا يَأْكُلُونَ قُدْسًا.', 'لاويين 22:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 11, 'لَكِنْ إِذَا اشْتَرَى كَاهِنٌ أَحَدًا شِرَاءَ فِضَّةٍ، فَهُوَ يَأْكُلُ مِنْهُ، وَالْمَوْلُودُ فِي بَيْتِهِ. هُمَا يَأْكُلَانِ مِنْ طَعَامِهِ.', 'لاويين 22:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 12, 'وَإِذَا صَارَتِ ابْنَةُ كَاهِنٍ لِرَجُلٍ أَجْنَبِيٍّ لَا تَأْكُلُ مِنْ رَفِيعَةِ الْأَقْدَاسِ.', 'لاويين 22:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 13, 'وَأَمَّا ابْنَةُ كَاهِنٍ قَدْ صَارَتْ أَرْمَلَةً أَوْ مُطَلَّقَةً، وَلَمْ يَكُنْ لَهَا نَسْلٌ، وَرَجَعَتْ إِلَى بَيْتِ أَبِيهَا كَمَا فِي صِبَاهَا، فَتَأْكُلُ مِنْ طَعَامِ أَبِيهَا. لَكِنَّ كُلَّ أَجْنَبِيٍّ لَا يَأْكُلُ مِنْهُ.', 'لاويين 22:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 14, 'وَإِذَا أَكَلَ إِنْسَانٌ قُدْسًا سَهْوًا، يَزِيدُ عَلَيْهِ خُمْسَهُ وَيَدْفَعُ الْقُدْسَ لِلْكَاهِنِ.', 'لاويين 22:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 15, 'فَلَا يُدَنِّسُونَ أَقْدَاسَ بَنِي إِسْرَائِيلَ الَّتِي يَرْفَعُونَهَا لِلرَّبِّ،', 'لاويين 22:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 16, 'فَيُحَمِّلُونَهُمْ ذَنْبَ إِثْمٍ بِأَكْلِهِمْ أَقْدَاسَهُمْ. لِأَنِّي أَنَا الرَّبُّ مُقَدِّسُهُمْ».', 'لاويين 22:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 17, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 22:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 18, '«كَلِّمْ هَارُونَ وَبَنِيهِ وَجَمِيعَ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ كُلُّ إِنْسَانٍ مِنْ بَيْتِ إِسْرَائِيلَ وَمِنَ الْغُرَبَاءِ فِي إِسْرَائِيلَ، قَرَّبَ قُرْبَانَهُ مِنْ جَمِيعِ نُذُورِهِمْ وَجَمِيعِ نَوَافِلِهِمِ الَّتِي يُقَرِّبُونَهَا لِلرَّبِّ مُحْرَقَةً،', 'لاويين 22:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 19, 'فَلِلرِّضَا عَنْكُمْ يَكُونُ ذَكَرًا صَحِيحًا مِنَ الْبَقَرِ أَوِ الْغَنَمِ أَوِ الْمَعْزِ.', 'لاويين 22:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 20, 'كُلُّ مَا كَانَ فِيهِ عَيْبٌ لَا تُقَرِّبُوهُ لِأَنَّهُ لَا يَكُونُ لِلرِّضَا عَنْكُمْ.', 'لاويين 22:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 21, 'وَإِذَا قَرَّبَ إِنْسَانٌ ذَبِيحَةَ سَلَامَةٍ لِلرَّبِّ وَفَاءً لِنَذْرٍ، أَوْ نَافِلَةً مِنَ الْبَقَرِ أَوِ الْأَغْنَامِ، تَكُونُ صَحِيحَةً لِلرِّضَا. كُلُّ عَيْبٍ لَا يَكُونُ فِيهَا.', 'لاويين 22:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 22, 'الْأَعْمَى وَالْمَكْسُورُ وَالْمَجْرُوحُ وَالْبَثِيرُ وَالْأَجْرَبُ وَالْأَكْلَفُ، هَذِهِ لَا تُقَرِّبُوهَا لِلرَّبِّ، وَلَا تَجْعَلُوا مِنْهَا وَقُودًا عَلَى الْمَذْبَحِ لِلرَّبِّ.', 'لاويين 22:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 23, 'وَأَمَّا الثَّوْرُ أَوِ الشَّاةُ الزَّوَائِدِيُّ أَوِ الْقُزُمُ فَنَافِلَةً تَعْمَلُهُ، وَلَكِنْ لِنَذْرٍ لَا يُرْضَى بِهِ.', 'لاويين 22:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 24, 'وَمَرْضُوضَ الْخِصْيَةِ وَمَسْحُوقَهَا وَمَقْطُوعَهَا لَا تُقَرِّبُوا لِلرَّبِّ. وَفِي أَرْضِكُمْ لَا تَعْمَلُوهَا.', 'لاويين 22:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 25, 'وَمِنْ يَدِ ابْنِ الْغَرِيبِ لَا تُقَرِّبُوا خُبْزَ إِلَهِكُمْ مِنْ جَمِيعِ هَذِهِ، لِأَنَّ فِيهَا فَسَادَهَا. فِيهَا عَيْبٌ لَا يُرْضَى بِهَا عَنْكُمْ».', 'لاويين 22:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 26, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 22:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 27, '«مَتَى وُلِدَ بَقَرٌ أَوْ غَنَمٌ أَوْ مِعْزًى يَكُونُ سَبْعَةَ أَيَّامٍ تَحْتَ أُمِّهِ، ثُمَّ مِنَ الْيَوْمِ الثَّامِنِ فَصَاعِدًا يُرْضَى بِهِ قُرْبَانَ وَقُودٍ لِلرَّبِّ.', 'لاويين 22:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 28, 'وَأَمَّا الْبَقَرَةُ أَوِ الشَّاةُ فَلَا تَذْبَحُوهَا وَابْنَهَا فِي يَوْمٍ وَاحِدٍ.', 'لاويين 22:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 29, 'وَمَتَى ذَبَحْتُمْ ذَبِيحَةَ شُكْرٍ لِلرَّبِّ، فَلِلرِّضَا عَنْكُمْ تَذْبَحُونَهَا.', 'لاويين 22:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 30, 'فِي ذَلِكَ الْيَوْمِ تُؤْكَلُ. لَا تُبْقُوا مِنْهَا إِلَى الْغَدِ. أَنَا الرَّبُّ.', 'لاويين 22:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 31, 'فَتَحْفَظُونَ وَصَايَايَ وَتَعْمَلُونَهَا. أَنَا الرَّبُّ.', 'لاويين 22:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 32, 'وَلَا تُدَنِّسُونَ اسْمِي الْقُدُّوسَ، فَأَتَقَدَّسُ فِي وَسَطِ بَنِي إِسْرَائِيلَ. أَنَا الرَّبُّ مُقَدِّسُكُمُ', 'لاويين 22:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 22, 33, 'الَّذِي أَخْرَجَكُمْ مِنْ أَرْضِ مِصْرَ لِيَكُونَ لَكُمْ إِلَهًا. أَنَا الرَّبُّ».', 'لاويين 22:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 23:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ مَوَاسِمُ الرَّبِّ الَّتِي فِيهَا تُنَادُونَ مَحَافِلَ مُقَدَّسَةً. هَذِهِ هِيَ مَوَاسِمِي׃', 'لاويين 23:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 3, 'سِتَّةَ أَيَّامٍ يُعْمَلُ عَمَلٌ، وَأَمَّا الْيَوْمُ السَّابِعُ فَفِيهِ سَبْتُ عُطْلَةٍ مَحْفَلٌ مُقَدَّسٌ. عَمَلًا مَّا لَا تَعْمَلُوا. إِنَّهُ سَبْتٌ لِلرَّبِّ فِي جَمِيعِ مَسَاكِنِكُمْ.', 'لاويين 23:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 4, '«هَذِهِ مَوَاسِمُ الرَّبِّ، الْمَحَافِلُ الْمُقَدَّسَةُ الَّتِي تُنَادُونَ بِهَا فِي أَوْقَاتِهَا׃', 'لاويين 23:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 5, 'فِي الشَّهْرِ الْأَوَّلِ، فِي الرَّابِعَ عَشَرَ مِنَ الشَّهْرِ، بَيْنَ الْعِشَاءَيْنِ فِصْحٌ لِلرَّبِّ.', 'لاويين 23:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 6, 'وَفِي الْيَوْمِ الْخَامِسَ عَشَرَ مِنْ هَذَا الشَّهْرِ عِيدُ الْفَطِيرِ لِلرَّبِّ. سَبْعَةَ أَيَّامٍ تَأْكُلُونَ فَطِيرًا.', 'لاويين 23:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 7, 'فِي الْيَوْمِ الْأَوَّلِ يَكُونُ لَكُمْ مَحْفَلٌ مُقَدَّسٌ. عَمَلًا مَّا مِنَ الشُّغْلِ لَا تَعْمَلُوا.', 'لاويين 23:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 8, 'وَسَبْعَةَ أَيَّامٍ تُقَرِّبُونَ وَقُودًا لِلرَّبِّ. فِي الْيَوْمِ السَّابِعِ يَكُونُ مَحْفَلٌ مُقَدَّسٌ. عَمَلًا مَّا مِنَ الشُّغْلِ لَا تَعْمَلُوا».', 'لاويين 23:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 9, 'وكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 23:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 10, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ مَتَى جِئْتُمْ إِلَى الْأَرْضِ الَّتِي أَنَا أُعْطِيكُمْ وَحَصَدْتُمْ حَصِيدَهَا، تَأْتُونَ بِحُزْمَةِ أَوَّلِ حَصِيدِكُمْ إِلَى الْكَاهِنِ.', 'لاويين 23:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 11, 'فَيُرَدِّدُ الْحُزْمَةَ أَمَامَ الرَّبِّ لِلرِّضَا عَنْكُمْ. فِي غَدِ السَّبْتِ يُرَدِّدُهَا الْكَاهِنُ.', 'لاويين 23:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 12, 'وَتَعْمَلُونَ يَوْمَ تَرْدِيدِكُمُ الْحُزْمَةَ خَرُوفًا صَحِيحًا حَوْلِيًّا مُحْرَقَةً لِلرَّبِّ.', 'لاويين 23:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 13, 'وَتَقْدِمَتَهُ عُشْرَيْنِ مِنْ دَقِيقٍ مَلْتُوتٍ بِزَيْتٍ، وَقُودًا لِلرَّبِّ رَائِحَةَ سَرُورٍ، وَسَكِيبَهُ رُبْعَ الْهِينِ مِنْ خَمْرٍ.', 'لاويين 23:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 14, 'وَخُبْزًا وَفَرِيكًا وَسَوِيقًا لَا تَأْكُلُوا إِلَى هَذَا الْيَوْمِ عَيْنِهِ، إِلَى أَنْ تَأْتُوا بِقُرْبَانِ إِلَهِكُمْ، فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ فِي جَمِيعِ مَسَاكِنِكُمْ.', 'لاويين 23:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 15, '«ثُمَّ تَحْسُبُونَ لَكُمْ مِنْ غَدِ السَّبْتِ مِنْ يَوْمِ إِتْيَانِكُمْ بِحُزْمَةِ التَّرْدِيدِ سَبْعَةَ أَسَابِيعَ تَكُونُ كَامِلَةً.', 'لاويين 23:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 16, 'إِلَى غَدِ السَّبْتِ السَّابِعِ تَحْسُبُونَ خَمْسِينَ يَوْمًا، ثُمَّ تُقَرِّبُونَ تَقْدِمَةً جَدِيدَةً لِلرَّبِّ.', 'لاويين 23:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 17, 'مِنْ مَسَاكِنِكُمْ تَأْتُونَ بِخُبْزِ تَرْدِيدٍ، رَغِيفَيْنِ عُشْرَيْنِ يَكُونَانِ مِنْ دَقِيقٍ، وَيُخْبَزَانِ خَمِيرًا بَاكُورَةً لِلرَّبِّ.', 'لاويين 23:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 18, 'وَتُقَرِّبُونَ مَعَ الْخُبْزِ سَبْعَةَ خِرَافٍ صَحِيحَةٍ حَوْلِيَّةٍ، وَثَوْرًا وَاحِدًا ابْنَ بَقَرٍ، وَكَبْشَيْنِ مُحْرَقَةً لِلرَّبِّ مَعَ تَقْدِمَتِهَا وَسَكِيبِهَا وَقُودَ رَائِحَةِ سَرُورٍ لِلرَّبِّ.', 'لاويين 23:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 19, 'وَتَعْمَلُونَ تَيْسًا وَاحِدًا مِنَ الْمَعْزِ ذَبِيحَةَ خَطِيَّةٍ، وَخَرُوفَيْنِ حَوْلِيَّيْنِ ذَبِيحَةَ سَلَامَةٍ.', 'لاويين 23:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 20, 'فَيُرَدِّدُهَا الْكَاهِنُ مَعَ خُبْزِ الْبَاكُورَةِ تَرْدِيدًا أَمَامَ الرَّبِّ مَعَ الْخَرُوفَيْنِ، فَتَكُونُ لِلْكَاهِنِ قُدْسًا لِلرَّبِّ.', 'لاويين 23:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 21, 'وَتُنَادُونَ فِي ذَلِكَ الْيَوْمِ عَيْنِهِ مَحْفَلًا مُقَدَّسًا يَكُونُ لَكُمْ. عَمَلًا مَّا مِنَ الشُّغْلِ لَا تَعْمَلُوا. فَرِيضَةً دَهْرِيَّةً فِي جَمِيعِ مَسَاكِنِكُمْ فِي أَجْيَالِكُمْ.', 'لاويين 23:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 22, 'وَعِنْدَمَا تَحْصُدُونَ حَصِيدَ أَرْضِكُمْ، لَا تُكَمِّلْ زَوَايَا حَقْلِكَ فِي حَصَادِكَ، وَلُقَاطَ حَصِيدِكَ لَا تَلْتَقِطْ. لِلْمِسْكِينِ وَالْغَرِيبِ تَتْرُكُهُ. أَنَا الرَّبُّ إِلَهُكُمْ».', 'لاويين 23:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 23, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 23:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 24, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ فِي الشَّهْرِ السَّابِعِ، فِي أَوَّلِ الشَّهْرِ يَكُونُ لَكُمْ عُطْلَةٌ، تَذْكَارُ هُتَافِ الْبُوقِ، مَحْفَلٌ مُقَدَّسٌ.', 'لاويين 23:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 25, 'عَمَلًا مَّا مِنَ الشُّغْلِ لَا تَعْمَلُوا، لَكِنْ تُقَرِّبُونَ وَقُودًا لِلرَّبِّ».', 'لاويين 23:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 26, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 23:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 27, '«أَمَّا الْعَاشِرُ مِنْ هَذَا الشَّهْرِ السَّابِعِ، فَهُوَ يَوْمُ الْكَفَّارَةِ. مَحْفَلًا مُقَدَّسًا يَكُونُ لَكُمْ. تُذَلِّلُونَ نُفُوسَكُمْ وَتُقَرِّبُونَ وَقُودًا لِلرَّبِّ.', 'لاويين 23:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 28, 'عَمَلًا مَّا لَا تَعْمَلُوا فِي هَذَا الْيَوْمِ عَيْنِهِ، لِأَنَّهُ يَوْمُ كَفَّارَةٍ لِلتَّكْفِيرِ عَنْكُمْ أَمَامَ الرَّبِّ إِلَهِكُمْ.', 'لاويين 23:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 29, 'إِنَّ كُلَّ نَفْسٍ لَا تَتَذَلَّلُ فِي هَذَا الْيَوْمِ عَيْنِهِ تُقْطَعُ مِنْ شَعْبِهَا.', 'لاويين 23:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 30, 'وَكُلَّ نَفْسٍ تَعْمَلُ عَمَلًا مَّا فِي هَذَا الْيَوْمِ عَيْنِهِ أُبِيدُ تِلْكَ النَّفْسَ مِنْ شَعْبِهَا.', 'لاويين 23:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 31, 'عَمَلًا مَّا لَا تَعْمَلُوا. فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ فِي جَمِيعِ مَسَاكِنِكُمْ.', 'لاويين 23:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 32, 'إِنَّهُ سَبْتُ عُطْلَةٍ لَكُمْ، فَتُذَلِّلُونَ نُفُوسَكُمْ. فِي تَاسِعِ الشَّهْرِ عِنْدَ الْمَسَاءِ. مِنَ الْمَسَاءِ إِلَى الْمَسَاءِ تَسْبِتُونَ سَبْتَكُمْ».', 'لاويين 23:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 33, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 23:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 34, '«كَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ فِي الْيَوْمِ الْخَامِسَ عَشَرَ مِنْ هَذَا الشَّهْرِ السَّابِعِ عِيدُ الْمَظَالِّ سَبْعَةَ أَيَّامٍ لِلرَّبِّ.', 'لاويين 23:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 35, 'فِي الْيَوْمِ الْأَوَّلِ مَحْفَلٌ مُقَدَّسٌ. عَمَلًا مَّا مِنَ الشُّغْلِ لَا تَعْمَلُوا.', 'لاويين 23:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 36, 'سَبْعَةَ أَيَّامٍ تُقَرِّبُونَ وَقُودًا لِلرَّبِّ. فِي الْيَوْمِ الثَّامِنِ يَكُونُ لَكُمْ مَحْفَلٌ مُقَدَّسٌ تُقَرِّبُونَ وَقُودًا لِلرَّبِّ. إِنَّهُ اعْتِكَافٌ. كُلُّ عَمَلِ شُغْلٍ لَا تَعْمَلُوا.', 'لاويين 23:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 37, '«هَذِهِ هِيَ مَوَاسِمُ الرَّبِّ الَّتِي فِيهَا تُنَادُونَ مَحَافِلَ مُقَدَّسَةً لِتَقْرِيبِ وَقُودٍ لِلرَّبِّ، مُحْرَقَةً وَتَقْدِمَةً وَذَبِيحَةً وَسَكِيبًا أَمْرَ الْيَوْمِ بِيَوْمِهِ،', 'لاويين 23:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 38, 'عَدَا سُبُوتِ الرَّبِّ، وَعَدَا عَطَايَاكُمْ وَجَمِيعِ نُذُورِكُمْ، وَجَمِيعِ نَوَافِلِكُمُ الَّتِي تُعْطُونَهَا لِلرَّبِّ.', 'لاويين 23:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 39, 'أَمَّا الْيَوْمُ الْخَامِسَ عَشَرَ مِنَ الشَّهْرِ السَّابِعِ فَفِيهِ، عِنْدَمَا تَجْمَعُونَ غَلَّةَ الْأَرْضِ، تُعَيِّدُونَ عِيدًا لِلرَّبِّ سَبْعَةَ أَيَّامٍ. فِي الْيَوْمِ الْأَوَّلِ عُطْلَةٌ وَفِي الْيَوْمِ الثَّامِنِ عُطْلَةٌ.', 'لاويين 23:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 40, 'وَتَأْخُذُونَ لِأَنْفُسِكُمْ فِي الْيَوْمِ الْأَوَّلِ ثَمَرَ أَشْجَارٍ بَهِجَةٍ وَسَعَفَ النَّخْلِ وَأَغْصَانَ أَشْجَارٍ غَبْيَاءَ وَصَفْصَافَ الْوَادِي، وَتَفْرَحُونَ أَمَامَ الرَّبِّ إِلَهِكُمْ سَبْعَةَ أَيَّامٍ.', 'لاويين 23:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 41, 'تُعَيِّدُونَهُ عِيدًا لِلرَّبِّ سَبْعَةَ أَيَّامٍ فِي السَّنَةِ فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ. فِي الشَّهْرِ السَّابِعِ تُعَيِّدُونَهُ.', 'لاويين 23:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 42, 'فِي مَظَالَّ تَسْكُنُونَ سَبْعَةَ أَيَّامٍ. كُلُّ الْوَطَنِيِّينَ فِي إِسْرَائِيلَ يَسْكُنُونَ فِي الْمَظَالِّ.', 'لاويين 23:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 43, 'لِكَيْ تَعْلَمَ أَجْيَالُكُمْ أَنِّي فِي مَظَالَّ أَسْكَنْتُ بَنِي إِسْرَائِيلَ لَمَّا أَخْرَجْتُهُمْ مِنْ أَرْضِ مِصْرَ. أَنَا الرَّبُّ إِلَهُكُمْ».', 'لاويين 23:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 23, 44, 'فَأَخْبَرَ مُوسَى بَنِي إِسْرَائِيلَ بِمَوَاسِمِ الرَّبِّ.', 'لاويين 23:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 24:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 2, '«أَوْصِ بَنِي إِسْرَائِيلَ أَنْ يُقَدِّمُوا إِلَيْكَ زَيْتَ زَيْتُونٍ مَرْضُوضٍ نَقِيًّا لِلضَّوْءِ لِإِيقَادِ السُّرُجِ دَائِمًا.', 'لاويين 24:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 3, 'خَارِجَ حِجَابِ الشَّهَادَةِ فِي خَيْمَةِ الِاجْتِمَاعِ يُرَتِّبُهَا هَارُونُ مِنَ الْمَسَاءِ إِلَى الصَّبَاحِ أَمَامَ الرَّبِّ دَائِمًا فَرِيضَةً دَهْرِيَّةً فِي أَجْيَالِكُمْ.', 'لاويين 24:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 4, 'عَلَى الْمَنَارَةِ الطَّاهِرَةِ يُرَتِّبُ السُّرُجَ أَمَامَ الرَّبِّ دَائِمًا.', 'لاويين 24:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 5, '«وَتَأْخُذُ دَقِيقًا وَتَخْبِزُهُ اثْنَيْ عَشَرَ قُرْصًا. عُشْرَيْنِ يَكُونُ الْقُرْصُ الْوَاحِدُ.', 'لاويين 24:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 6, 'وَتَجْعَلُهَا صَفَّيْنِ، كُلَّ صَفٍّ سِتَّةً عَلَى الْمَائِدَةِ الطَّاهِرَةِ أَمَامَ الرَّبِّ.', 'لاويين 24:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 7, 'وَتَجْعَلُ عَلَى كُلِّ صَفٍّ لُبَانًا نَقِيًّا فَيَكُونُ لِلْخُبْزِ تَذْكَارًا وَقُودًا لِلرَّبِّ.', 'لاويين 24:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 8, 'فِي كُلِّ يَوْمِ سَبْتٍ يُرَتِّبُهُ أَمَامَ الرَّبِّ دَائِمًا، مِنْ عِنْدِ بَنِي إِسْرَائِيلَ مِيثَاقًا دَهْرِيًّا.', 'لاويين 24:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 9, 'فَيَكُونُ لِهَارُونَ وَبَنِيهِ، فَيَأْكُلُونَهُ فِي مَكَانٍ مُقَدَّسٍ، لِأَنَّهُ قُدْسُ أَقْدَاسٍ لَهُ مِنْ وَقَائِدِ الرَّبِّ فَرِيضَةً دَهْرِيَّةً».', 'لاويين 24:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 10, 'وَخَرَجَ ابْنُ امْرَأَةٍ إِسْرَائِيلِيَّةٍ، وَهُوَ ابْنُ رَجُلٍ مِصْرِيٍّ، فِي وَسَطِ بَنِي إِسْرَائِيلَ. وَتَخَاصَمَ فِي الْمَحَلَّةِ ابْنُ الْإِسْرَائِيلِيَّةِ وَرَجُلٌ إِسْرَائِيلِيٌّ.', 'لاويين 24:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 11, 'فَجَدَّفَ ابْنُ الْإِسْرَائِيلِيَّةِ عَلَى الِاسْمِ وَسَبَّ. فَأَتَوْا بِهِ إِلَى مُوسَى. وَكَانَ اسْمُ أُمِّهِ شَلُومِيَةَ بِنْتَ دِبْرِي مِنْ سِبْطِ دَانَ.', 'لاويين 24:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 12, 'فَوَضَعُوهُ فِي الْمَحْرَسِ لِيُعْلَنَ لَهُمْ عَنْ فَمِ الرَّبِّ.', 'لاويين 24:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 13, 'فَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 24:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 14, '«أَخْرِجِ الَّذِي سَبَّ إِلَى خَارِجِ الْمَحَلَّةِ، فَيَضَعَ جَمِيعُ السَّامِعِينَ أَيْدِيَهُمْ عَلَى رَأْسِهِ، وَيَرْجُمَهُ كُلُّ الْجَمَاعَةِ.', 'لاويين 24:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 15, 'وَكَلِّمْ بَنِي إِسْرَائِيلَ قَائِلًا׃ كُلُّ مَنْ سَبَّ إِلَهَهُ يَحْمِلُ خَطِيَّتَهُ،', 'لاويين 24:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 16, 'وَمَنْ جَدَّفَ عَلَى اسْمِ الرَّبِّ فَإِنَّهُ يُقْتَلُ. يَرْجُمُهُ كُلُّ الْجَمَاعَةِ رَجْمًا. الْغَرِيبُ كَالْوَطَنِيِّ عِنْدَمَا يُجَدِّفُ عَلَى الِاسْمِ يُقْتَلُ.', 'لاويين 24:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 17, 'وَإِذَا أَمَاتَ أَحَدٌ إِنْسَانًا فَإِنَّهُ يُقْتَلُ.', 'لاويين 24:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 18, 'وَمَنْ أَمَاتَ بَهِيمَةً يُعَوِّضُ عَنْهَا نَفْسًا بِنَفْسٍ.', 'لاويين 24:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 19, 'وَإِذَا أَحْدَثَ إِنْسَانٌ فِي قَرِيبِهِ عَيْبًا، فَكَمَا فَعَلَ كَذَلِكَ يُفْعَلُ بِهِ.', 'لاويين 24:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 20, 'كَسْرٌ بِكَسْرٍ، وَعَيْنٌ بِعَيْنٍ، وَسِنٌّ بِسِنٍّ. كَمَا أَحْدَثَ عَيْبًا فِي الْإِنْسَانِ كَذَلِكَ يُحْدَثُ فِيهِ.', 'لاويين 24:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 21, 'مَنْ قَتَلَ بَهِيمَةً يُعَوِّضُ عَنْهَا، وَمَنْ قَتَلَ إِنْسَانًا يُقْتَلْ.', 'لاويين 24:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 22, 'حُكْمٌ وَاحِدٌ يَكُونُ لَكُمْ. الْغَرِيبُ يَكُونُ كَالْوَطَنِيِّ. إِنِّي أَنَا الرَّبُّ إِلَهُكُمْ».', 'لاويين 24:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 24, 23, 'فَكَلَّمَ مُوسَى بَنِي إِسْرَائِيلَ أَنْ يُخْرِجُوا الَّذِي سَبَّ إِلَى خَارِجِ الْمَحَلَّةِ وَيَرْجُمُوهُ بِالْحِجَارَةِ. فَفَعَلَ بَنُو إِسْرَائِيلَ كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'لاويين 24:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى فِي جَبَلِ سِينَاءَ قَائِلًا׃', 'لاويين 25:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ مَتَى أَتَيْتُمْ إِلَى الْأَرْضِ الَّتِي أَنَا أُعْطِيكُمْ تَسْبِتُ الْأَرْضُ سَبْتًا لِلرَّبِّ.', 'لاويين 25:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 3, 'سِتَّ سِنِينَ تَزْرَعُ حَقْلَكَ، وَسِتَّ سِنِينَ تَقْضِبُ كَرْمَكَ وَتَجْمَعُ غَلَّتَهُمَا.', 'لاويين 25:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 4, 'وَأَمَّا السَّنَةُ السَّابِعَةُ فَفِيهَا يَكُونُ لِلْأَرْضِ سَبْتُ عُطْلَةٍ، سَبْتًا لِلرَّبِّ. لَا تَزْرَعْ حَقْلَكَ وَلَا تَقْضِبْ كَرْمَكَ.', 'لاويين 25:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 5, 'زِرِّيعَ حَصِيدِكَ لَا تَحْصُدْ، وَعِنَبَ كَرْمِكَ الْمُحْوِلِ لَا تَقْطِفْ. سَنَةَ عُطْلَةٍ تَكُونُ لِلْأَرْضِ.', 'لاويين 25:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 6, 'وَيَكُونُ سَبْتُ الْأَرْضِ لَكُمْ طَعَامًا. لَكَ وَلِعَبْدِكَ وَلِأَمَتِكَ وَلِأَجِيرِكَ وَلِمُسْتَوْطِنِكَ النَّازِلِينَ عِنْدَكَ،', 'لاويين 25:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 7, 'وَلِبَهَائِمِكَ وَلِلْحَيَوَانِ الَّذِي فِي أَرْضِكَ تَكُونُ كُلُّ غَلَّتِهَا طَعَامًا.', 'لاويين 25:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 8, '«وَتَعُدُّ لَكَ سَبْعَةَ سُبُوتِ سِنِينَ. سَبْعَ سِنِينَ سَبْعَ مَرَّاتٍ. فَتَكُونُ لَكَ أَيَّامُ السَّبْعَةِ السُّبُوتِ السَّنَوِيَّةِ تِسْعًا وَأَرْبَعِينَ سَنَةً.', 'لاويين 25:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 9, 'ثُمَّ تُعَبِّرُ بُوقَ الْهُتَافِ فِي الشَّهْرِ السَّابِعِ فِي عَاشِرِ الشَّهْرِ. فِي يَوْمِ الْكَفَّارَةِ تُعَبِّرُونَ الْبُوقَ فِي جَمِيعِ أَرْضِكُمْ.', 'لاويين 25:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 10, 'وَتُقَدِّسُونَ السَّنَةَ الْخَمْسِينَ، وَتُنَادُونَ بِالْعِتْقِ فِي الْأَرْضِ لِجَمِيعِ سُكَّانِهَا. تَكُونُ لَكُمْ يُوبِيلًا، وَتَرْجِعُونَ كُلٌّ إِلَى مُلْكِهِ، وَتَعُودُونَ كُلٌّ إِلَى عَشِيرَتِهِ.', 'لاويين 25:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 11, 'يُوبِيلًا تَكُونُ لَكُمُ السَّنَةُ الْخَمْسُونَ. لَا تَزْرَعُوا وَلَا تَحْصُدُوا زِرِّيعَهَا، وَلَا تَقْطِفُوا كَرْمَهَا الْمُحْوِلَ.', 'لاويين 25:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 12, 'إِنَّهَا يُوبِيلٌ. مُقَدَّسَةً تَكُونُ لَكُمْ. مِنَ الْحَقْلِ تَأْكُلُونَ غَلَّتَهَا.', 'لاويين 25:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 13, 'فِي سَنَةِ الْيُوبِيلِ هَذِهِ تَرْجِعُونَ كُلٌّ إِلَى مُلْكِهِ.', 'لاويين 25:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 14, 'فَمَتَى بِعْتَ صَاحِبَكَ مَبِيعًا، أَوِ اشْتَرَيْتَ مِنْ يَدِ صَاحِبِكَ، فَلَا يَغْبِنْ أَحَدُكُمْ أَخَاهُ.', 'لاويين 25:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 15, 'حَسَبَ عَدَدِ السِّنِينَ بَعْدَ الْيُوبِيلِ تَشْتَرِي مِنْ صَاحِبِكَ، وَحَسَبَ سِنِي الْغَلَّةِ يَبِيعُكَ.', 'لاويين 25:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 16, 'عَلَى قَدْرِ كَثْرَةِ السِّنِينَ تُكَثِّرُ ثَمَنَهُ، وَعَلَى قَدْرِ قِلَّةِ السِّنِينَ تُقَلِّلُ ثَمَنَهُ، لِأَنَّهُ عَدَدَ الْغَلَّاتِ يَبِيعُكَ.', 'لاويين 25:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 17, 'فَلَا يَغْبِنْ أَحَدُكُمْ صَاحِبَهُ، بَلِ اخْشَ إِلَهَكَ. إِنِّي أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 25:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 18, 'فَتَعْمَلُونَ فَرَائِضِي وَتَحْفَظُونَ أَحْكَامِي وَتَعْمَلُونَهَا لِتَسْكُنُوا عَلَى الْأَرْضِ آمِنِينَ.', 'لاويين 25:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 19, 'وَتُعْطِي الْأَرْضُ ثَمَرَهَا فَتَأْكُلُونَ لِلشِّبَعِ، وَتَسْكُنُونَ عَلَيْهَا آمِنِينَ.', 'لاويين 25:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 20, 'وَإِذَا قُلْتُمْ׃ مَاذَا نَأْكُلُ فِي السَّنَةِ السَّابِعَةِ إِنْ لَمْ نَزْرَعْ وَلَمْ نَجْمَعْ غَلَّتَنَا؟', 'لاويين 25:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 21, 'فَإِنِّي آمُرُ بِبَرَكَتِي لَكُمْ فِي السَّنَةِ السَّادِسَةِ، فَتَعْمَلُ غَلَّةً لِثَلَاثِ سِنِينَ.', 'لاويين 25:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 22, 'فَتَزْرَعُونَ السَّنَةَ الثَّامِنَةَ وَتَأْكُلُونَ مِنَ الْغَلَّةِ الْعَتِيقَةِ إِلَى السَّنَةِ التَّاسِعَةِ. إِلَى أَنْ تَأْتِيَ غَلَّتُهَا تَأْكُلُونَ عَتِيقًا.', 'لاويين 25:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 23, '«وَالْأَرْضُ لَا تُبَاعُ بَتَّةً، لِأَنَّ لِيَ الْأَرْضَ، وَأَنْتُمْ غُرَبَاءُ وَنُزَلَاءُ عِنْدِي.', 'لاويين 25:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 24, 'بَلْ فِي كُلِّ أَرْضِ مُلْكِكُمْ تَجْعَلُونَ فِكَاكًا لِلْأَرْضِ.', 'لاويين 25:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 25, 'إِذَا افْتَقَرَ أَخُوكَ فَبَاعَ مِنْ مُلْكِهِ، يَأْتِي وَلِيُّهُ الْأَقْرَبُ إِلَيْهِ وَيَفُكُّ مَبِيعَ أَخِيهِ.', 'لاويين 25:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 26, 'وَمَنْ لَمْ يَكُنْ لَهُ وَلِيٌّ، فَإِنْ نَالَتْ يَدُهُ وَوَجَدَ مِقْدَارَ فِكَاكِهِ،', 'لاويين 25:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 27, 'يَحْسُبُ سِنِي بَيْعِهِ، وَيَرُدُّ الْفَاضِلَ لِلْإِنْسَانِ الَّذِي بَاعَ لَهُ، فَيَرْجِعُ إِلَى مُلْكِهِ.', 'لاويين 25:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 28, 'وَإِنْ لَمْ تَنَلْ يَدُهُ كِفَايَةً لِيَرُدَّ لَهُ، يَكُونُ مَبِيعُهُ فِي يَدِ شَارِيهِ إِلَى سَنَةِ الْيُوبِيلِ، ثُمَّ يَخْرُجُ فِي الْيُوبِيلِ فَيَرْجِعُ إِلَى مُلْكِهِ.', 'لاويين 25:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 29, '«وَإِذَا بَاعَ إِنْسَانٌ بَيْتَ سَكَنٍ فِي مَدِينَةٍ ذَاتِ سُورٍ، فَيَكُونُ فِكَاكُهُ إِلَى تَمَامِ سَنَةِ بَيْعِهِ. سَنَةً يَكُونُ فِكَاكُهُ.', 'لاويين 25:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 30, 'وَإِنْ لَمْ يُفَكَّ قَبْلَ أَنْ تَكْمُلَ لَهُ سَنَةٌ تَامَّةٌ، وَجَبَ الْبَيْتُ الَّذِي فِي الْمَدِينَةِ ذَاتِ السُّورِ بَتَّةً لِشَارِيهِ فِي أَجْيَالِهِ. لَا يَخْرُجُ فِي الْيُوبِيلِ.', 'لاويين 25:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 31, 'لَكِنَّ بُيُوتَ الْقُرَى الَّتِي لَيْسَ لَهَا سُورٌ حَوْلَهَا، فَمَعَ حُقُولِ الْأَرْضِ تُحْسَبُ. يَكُونُ لَهَا فِكَاكٌ، وَفِي الْيُوبِيلِ تَخْرُجُ.', 'لاويين 25:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 32, 'وَأَمَّا مُدُنُ اللَّاوِيِّينَ، بُيُوتُ مُدُنِ مُلْكِهِمْ، فَيَكُونُ لَهَا فِكَاكٌ مُؤَبَّدٌ لِلَّاوِيِّينَ.', 'لاويين 25:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 33, 'وَالَّذِي يَفُكُّهُ مِنَ اللَّاوِيِّينَ الْمَبِيعَ مِنْ بَيْتٍ أَوْ مِنْ مَدِينَةِ مُلْكِهِ يَخْرُجُ فِي الْيُوبِيلِ، لِأَنَّ بُيُوتَ مُدُنِ اللَّاوِيِّينَ هِيَ مُلْكُهُمْ فِي وَسَطِ بَنِي إِسْرَائِيلَ.', 'لاويين 25:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 34, 'وَأَمَّا حُقُولُ الْمَسَارِحِ لِمُدُنِهِمْ فَلَا تُبَاعُ، لِأَنَّهَا مُلْكٌ دَهْرِيٌّ لَهُمْ.', 'لاويين 25:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 35, '«وَإِذَا افْتَقَرَ أَخُوكَ وَقَصُرَتْ يَدُهُ عِنْدَكَ، فَاعْضُدْهُ غَرِيبًا أَوْ مُسْتَوْطِنًا فَيَعِيشَ مَعَكَ.', 'لاويين 25:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 36, 'لَا تَأْخُذْ مِنْهُ رِبًا وَلَا مُرَابَحَةً، بَلِ اخْشَ إِلَهَكَ، فَيَعِيشَ أَخُوكَ مَعَكَ.', 'لاويين 25:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 37, 'فِضَّتَكَ لَا تُعْطِهِ بِالرِّبَا، وَطَعَامَكَ لَا تُعْطِ بِالْمُرَابَحَةِ.', 'لاويين 25:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 38, 'أَنَا الرَّبُّ إِلَهُكُمُ الَّذِي أَخْرَجَكُمْ مِنْ أَرْضِ مِصْرَ لِيُعْطِيَكُمْ أَرْضَ كَنْعَانَ، فَيَكُونَ لَكُمْ إِلَهًا.', 'لاويين 25:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 39, '«وَإِذَا افْتَقَرَ أَخُوكَ عِنْدَكَ وَبِيعَ لَكَ، فَلَا تَسْتَعْبِدْهُ اسْتِعْبَادَ عَبْدٍ.', 'لاويين 25:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 40, 'كَأَجِيرٍ، كَنَزِيلٍ يَكُونُ عِنْدَكَ. إِلَى سَنَةِ الْيُوبِيلِ يَخْدِمُ عِنْدَكَ،', 'لاويين 25:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 41, 'ثُمَّ يَخْرُجُ مِنْ عِنْدِكَ هُوَ وَبَنُوهُ مَعَهُ وَيَعُودُ إِلَى عَشِيرَتِهِ، وَإِلَى مُلْكِ آبَائِهِ يَرْجِعُ.', 'لاويين 25:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 42, 'لِأَنَّهُمْ عَبِيدِي الَّذِينَ أَخْرَجْتُهُمْ مِنْ أَرْضِ مِصْرَ، لَا يُبَاعُونَ بَيْعَ الْعَبِيدِ.', 'لاويين 25:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 43, 'لَا تَتَسَلَّطْ عَلَيْهِ بِعُنْفٍ، بَلِ اخْشَ إِلَهَكَ.', 'لاويين 25:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 44, 'وَأَمَّا عَبِيدُكَ وَإِمَاؤُكَ الَّذِينَ يَكُونُونَ لَكَ، فَمِنَ الشُّعُوبِ الَّذِينَ حَوْلَكُمْ. مِنْهُمْ تَقْتَنُونَ عَبِيدًا وَإِمَاءً.', 'لاويين 25:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 45, 'وَأَيْضًا مِنْ أَبْنَاءِ الْمُسْتَوْطِنِينَ النَّازِلِينَ عِنْدَكُمْ، مِنْهُمْ تَقْتَنُونَ وَمِنْ عَشَائِرِهِمِ الَّذِينَ عِنْدَكُمُ الَّذِينَ يَلِدُونَهُمْ فِي أَرْضِكُمْ، فَيَكُونُونَ مُلْكًا لَكُمْ.', 'لاويين 25:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 46, 'وَتَسْتَمْلِكُونَهُمْ لِأَبْنَائِكُمْ مِنْ بَعْدِكُمْ مِيرَاثَ مُلْكٍ. تَسْتَعْبِدُونَهُمْ إِلَى الدَّهْرِ. وَأَمَّا إِخْوَتُكُمْ بَنُو إِسْرَائِيلَ فَلَا يَتَسَلَّطْ إِنْسَانٌ عَلَى أَخِيهِ بِعُنْفٍ.', 'لاويين 25:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 47, '«وَإِذَا طَالَتْ يَدُ غَرِيبٍ أَوْ نَزِيلٍ عِنْدَكَ، وَافْتَقَرَ أَخُوكَ عِنْدَهُ وَبِيعَ لِلْغَرِيبِ الْمُسْتَوْطِنِ عِنْدَكَ أَوْ لِنَسْلِ عَشِيرَةِ الْغَرِيبِ،', 'لاويين 25:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 48, 'فَبَعْدَ بَيْعِهِ يَكُونُ لَهُ فِكَاكٌ. يَفُكُّهُ وَاحِدٌ مِنْ إِخْوَتِهِ،', 'لاويين 25:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 49, 'أَوْ يَفُكُّهُ عَمُّهُ أَوِ ابْنُ عَمِّهِ، أَوْ يَفُكُّهُ وَاحِدٌ مِنْ أَقْرِبَاءِ جَسَدِهِ مِنْ عَشِيرَتِهِ، أَوْ إِذَا نَالَتْ يَدُهُ يَفُكُّ نَفْسَهُ.', 'لاويين 25:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 50, 'فَيُحَاسِبُ شَارِيَهُ مِنْ سَنَةِ بَيْعِهِ لَهُ إِلَى سَنَةِ الْيُوبِيلِ، وَيَكُونُ ثَمَنُ بَيْعِهِ حَسَبَ عَدَدِ السِّنِينَ. كَأَيَّامِ أَجِيرٍ يَكُونُ عِنْدَهُ.', 'لاويين 25:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 51, 'إِنْ بَقِيَ كَثِيرٌ مِنَ السِّنِينِ فَعَلَى قَدْرِهَا يَرُدُّ فِكَاكَهُ مِنْ ثَمَنِ شِرَائِهِ.', 'لاويين 25:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 52, 'وَإِنْ بَقِيَ قَلِيلٌ مِنَ السِّنِينَ إِلَى سَنَةِ الْيُوبِيلِ يَحْسُبُ لَهُ وَعَلَى قَدْرِ سِنِيهِ يَرُدُّ فِكَاكَهُ.', 'لاويين 25:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 53, 'كَأَجِيرٍ مِنْ سَنَةٍ إِلَى سَنَةٍ يَكُونُ عِنْدَهُ. لَا يَتَسَلَّطْ عَلَيْهِ بِعُنْفٍ أَمَامَ عَيْنَيْكَ.', 'لاويين 25:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 54, 'وَإِنْ لَمْ يُفَكَّ بِهَؤُلَاءِ، يَخْرُجُ فِي سَنَةِ الْيُوبِيلِ هُوَ وَبَنُوهُ مَعَهُ،', 'لاويين 25:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 25, 55, 'لِأَنَّ بَنِي إِسْرَائِيلَ لِي عَبِيدٌ. هُمْ عَبِيدِي الَّذِينَ أَخْرَجْتُهُمْ مِنْ أَرْضِ مِصْرَ. أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 25:55');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 1, '«لَا تَصْنَعُوا لَكُمْ أَوْثَانًا، وَلَا تُقِيمُوا لَكُمْ تِمْثَالًا مَنْحُوتًا أَوْ نَصَبًا، وَلَا تَجْعَلُوا فِي أَرْضِكُمْ حَجَرًا مُصَوَّرًا لِتَسْجُدُوا لَهُ. لِأَنِّي أَنَا الرَّبُّ إِلَهُكُمْ.', 'لاويين 26:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 2, 'سُبُوتِي تَحْفَظُونَ وَمَقْدِسِي تَهَابُونَ. أَنَا الرَّبُّ.', 'لاويين 26:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 3, '«إِذَا سَلَكْتُمْ فِي فَرَائِضِي وَحَفِظْتُمْ وَصَايَايَ وَعَمِلْتُمْ بِهَا،', 'لاويين 26:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 4, 'أُعْطِي مَطَرَكُمْ فِي حِينِهِ، وَتُعْطِي الْأَرْضُ غَلَّتَهَا، وَتُعْطِي أَشْجَارُ الْحَقْلِ أَثْمَارَهَا،', 'لاويين 26:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 5, 'وَيَلْحَقُ دِرَاسُكُمْ بِالْقِطَافِ، وَيَلْحَقُ الْقِطَافُ بِالزَّرْعِ، فَتَأْكُلُونَ خُبْزَكُمْ لِلشِّبَعِ وَتَسْكُنُونَ فِي أَرْضِكُمْ آمِنِينَ.', 'لاويين 26:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 6, 'وَأَجْعَلُ سَلَامًا فِي الْأَرْضِ، فَتَنَامُونَ وَلَيْسَ مَنْ يُزْعِجُكُمْ. وَأُبِيدُ الْوُحُوشَ الرَّدِيئَةَ مِنَ الْأَرْضِ، وَلَا يَعْبُرُ سَيْفٌ فِي أَرْضِكُمْ.', 'لاويين 26:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 7, 'وَتَطْرُدُونَ أَعْدَاءَكُمْ فَيَسْقُطُونَ أَمَامَكُمْ بِالسَّيْفِ.', 'لاويين 26:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 8, 'يَطْرُدُ خَمْسَةٌ مِنْكُمْ مِئَةً، وَمِئَةٌ مِنْكُمْ يَطْرُدُونَ رَبْوَةً، وَيَسْقُطُ أَعْدَاؤُكُمْ أَمَامَكُمْ بِالسَّيْفِ.', 'لاويين 26:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 9, 'وَأَلْتَفِتُ إِلَيْكُمْ وَأُثْمِرُكُمْ وَأُكَثِّرُكُمْ وَأَفِي مِيثَاقِي مَعَكُمْ،', 'لاويين 26:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 10, 'فَتَأْكُلُونَ الْعَتِيقَ الْمُعَتَّقَ، وَتُخْرِجُونَ الْعَتِيقَ مِنْ وَجْهِ الْجَدِيدِ.', 'لاويين 26:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 11, 'وَأَجْعَلُ مَسْكَنِي فِي وَسَطِكُمْ، وَلَا تَرْذُلُكُمْ نَفْسِي.', 'لاويين 26:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 12, 'وَأَسِيرُ بَيْنَكُمْ وَأَكُونُ لَكُمْ إِلَهًا وَأَنْتُمْ تَكُونُونَ لِي شَعْبًا.', 'لاويين 26:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 13, 'أَنَا الرَّبُّ إِلَهُكُمُ الَّذِي أَخْرَجَكُمْ مِنْ أَرْضِ مِصْرَ مِنْ كَوْنِكُمْ لَهُمْ عَبِيدًا، وَقَطَّعَ قُيُودَ نِيرِكُمْ وَسَيَّرَكُمْ قِيَامًا.', 'لاويين 26:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 14, '«لَكِنْ إِنْ لَمْ تَسْمَعُوا لِي وَلَمْ تَعْمَلُوا كُلَّ هَذِهِ الْوَصَايَا،', 'لاويين 26:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 15, 'وَإِنْ رَفَضْتُمْ فَرَائِضِي وَكَرِهَتْ أَنْفُسُكُمْ أَحْكَامِي، فَمَا عَمِلْتُمْ كُلَّ وَصَايَايَ، بَلْ نَكَثْتُمْ مِيثَاقِي،', 'لاويين 26:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 16, 'فَإِنِّي أَعْمَلُ هَذِهِ بِكُمْ׃ أُسَلِّطُ عَلَيْكُمْ رُعْبًا وَسِلًّا وَحُمَّى تُفْنِي الْعَيْنَيْنِ وَتُتْلِفُ النَّفْسَ. وَتَزْرَعُونَ بَاطِلًا زَرْعَكُمْ فَيَأْكُلُهُ أَعْدَاؤُكُمْ.', 'لاويين 26:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 17, 'وَأَجْعَلُ وَجْهِي ضِدَّكُمْ فَتَنْهَزِمُونَ أَمَامَ أَعْدَائِكُمْ، وَيَتَسَلَّطُ عَلَيْكُمْ مُبْغِضُوكُمْ، وَتَهْرُبُونَ وَلَيْسَ مَنْ يَطْرُدُكُمْ.', 'لاويين 26:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 18, '«وَإِنْ كُنْتُمْ مَعَ ذَلِكَ لَا تَسْمَعُونَ لِي، أَزِيدُ عَلَى تَأْدِيبِكُمْ سَبْعَةَ أَضْعَافٍ حَسَبَ خَطَايَاكُمْ،', 'لاويين 26:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 19, 'فَأُحَطِّمُ فَخَارَ عِزِّكُمْ، وَأُصَيِّرُ سَمَاءَكُمْ كَالْحَدِيدِ، وَأَرْضَكُمْ كَالنُّحَاسِ،', 'لاويين 26:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 20, 'فَتُفْرَغُ بَاطِلًا قُوَّتُكُمْ، وَأَرْضُكُمْ لَا تُعْطِي غَلَّتَهَا، وَأَشْجَارُ الْأَرْضِ لَا تُعْطِي أَثْمَارَهَا.', 'لاويين 26:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 21, '«وَإِنْ سَلَكْتُمْ مَعِي بِالْخِلَافِ، وَلَمْ تَشَاءُوا أَنْ تَسْمَعُوا لِي، أَزِيدُ عَلَيْكُمْ ضَرْبَاتٍ سَبْعَةَ أَضْعَافٍ حَسَبَ خَطَايَاكُمْ.', 'لاويين 26:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 22, 'أُطْلِقُ عَلَيْكُمْ وُحُوشَ الْبَرِّيَّةِ فَتُعْدِمُكُمُ الْأَوْلَادَ، وَتَقْرِضُ بَهَائِمَكُمْ، وَتُقَلِّلُكُمْ فَتُوحَشُ طُرُقُكُمْ.', 'لاويين 26:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 23, '«وَإِنْ لَمْ تَتَأَدَّبُوا مِنِّي بِذَلِكَ، بَلْ سَلَكْتُمْ مَعِي بِالْخِلَافِ،', 'لاويين 26:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 24, 'فَإِنِّي أَنَا أَسْلُكُ مَعَكُمْ بِالْخِلَافِ، وَأَضْرِبُكُمْ سَبْعَةَ أَضْعَافٍ حَسَبَ خَطَايَاكُمْ.', 'لاويين 26:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 25, 'أَجْلِبُ عَلَيْكُمْ سَيْفًا يَنْتَقِمُ نَقْمَةَ الْمِيثَاقِ، فَتَجْتَمِعُونَ إِلَى مُدُنِكُمْ وَأُرْسِلُ فِي وَسَطِكُمُ الْوَبَأَ فَتُدْفَعُونَ بِيَدِ الْعَدُوِّ.', 'لاويين 26:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 26, 'بِكَسْرِي لَكُمْ عَصَا الْخُبْزِ. تَخْبِزُ عَشَرُ نِسَاءٍ خُبْزَكُمْ فِي تَنُّورٍ وَاحِدٍ، وَيَرْدُدْنَ خُبْزَكُمْ بِالْوَزْنِ، فَتَأْكُلُونَ وَلَا تَشْبَعُونَ.', 'لاويين 26:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 27, '«وَإِنْ كُنْتُمْ بِذَلِكَ لَا تَسْمَعُونَ لِي بَلْ سَلَكْتُمْ مَعِي بِالْخِلَافِ،', 'لاويين 26:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 28, 'فَأَنَا أَسْلُكُ مَعَكُمْ بِالْخِلَافِ سَاخِطًا، وَأُؤَدِّبُكُمْ سَبْعَةَ أَضْعَافٍ حَسَبَ خَطَايَاكُمْ،', 'لاويين 26:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 29, 'فَتَأْكُلُونَ لَحْمَ بَنِيكُمْ، وَلَحْمَ بَنَاتِكُمْ تَأْكُلُونَ.', 'لاويين 26:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 30, 'وَأُخْرِبُ مُرْتَفَعَاتِكُمْ، وَأَقْطَعُ شَمْسَاتِكُمْ، وَأُلْقِي جُثَثَكُمْ عَلَى جُثَثِ أَصْنَامِكُمْ، وَتَرْذُلُكُمْ نَفْسِي.', 'لاويين 26:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 31, 'وَأُصَيِّرُ مُدُنَكُمْ خَرِبَةً، وَمَقَادِسَكُمْ مُوحِشَةً، وَلَا أَشْتَمُّ رَائِحَةَ سَرُورِكُمْ.', 'لاويين 26:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 32, 'وَأُوحِشُ الْأَرْضَ فَيَسْتَوْحِشُ مِنْهَا أَعْدَاؤُكُمُ السَّاكِنُونَ فِيهَا.', 'لاويين 26:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 33, 'وَأُذَرِّيكُمْ بَيْنَ الْأُمَمِ، وَأُجَرِّدُ وَرَاءَكُمُ السَّيْفَ فَتَصِيرُ أَرْضُكُمْ مُوحَشَةً، وَمُدُنُكُمْ تَصِيرُ خَرِبَةً.', 'لاويين 26:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 34, 'حِينَئِذٍ تَسْتَوْفِي الْأَرْضُ سُبُوتَهَا كُلَّ أَيَّامِ وَحْشَتِهَا وَأَنْتُمْ فِي أَرْضِ أَعْدَائِكُمْ. حِينَئِذٍ تَسْبِتُ الْأَرْضُ وَتَسْتَوْفِي سُبُوتَهَا.', 'لاويين 26:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 35, 'كُلَّ أَيَّامِ وَحْشَتِهَا تَسْبِتُ مَا لَمْ تَسْبِتْهُ مِنْ سُبُوتِكُمْ فِي سَكَنِكُمْ عَلَيْهَا.', 'لاويين 26:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 36, 'وَالْبَاقُونَ مِنْكُمْ أُلْقِي الْجَبَانَةَ فِي قُلُوبِهِمْ فِي أَرَاضِي أَعْدَائِهِمْ، فَيَهْزِمُهُمْ صَوْتُ وَرَقَةٍ مُنْدَفِعَةٍ، فَيَهْرُبُونَ كَالْهَرَبِ مِنَ السَّيْفِ، وَيَسْقُطُونَ وَلَيْسَ طَارِدٌ.', 'لاويين 26:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 37, 'وَيَعْثُرُ بَعْضُهُمْ بِبَعْضٍ كَمَا مِنْ أَمَامِ السَّيْفِ وَلَيْسَ طَارِدٌ، وَلَا يَكُونُ لَكُمْ قِيَامٌ أَمَامَ أَعْدَائِكُمْ،', 'لاويين 26:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 38, 'فَتَهْلِكُونَ بَيْنَ الشُّعُوبِ وَتَأْكُلُكُمْ أَرْضُ أَعْدَائِكُمْ.', 'لاويين 26:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 39, 'وَالْبَاقُونَ مِنْكُمْ يَفْنَوْنَ بِذُنُوبِهِمْ فِي أَرَاضِي أَعْدَائِكُمْ. وَأَيْضًا بِذُنُوبِ آبَائِهِمْ مَعَهُمْ يَفْنَوْنَ.', 'لاويين 26:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 40, 'لَكِنْ إِنْ أَقَرُّوا بِذُنُوبِهِمْ وَذُنُوبِ آبَائِهِمْ فِي خِيَانَتِهِمِ الَّتِي خَانُونِي بِهَا، وَسُلُوكِهِمْ مَعِيَ الَّذِي سَلَكُوا بِالْخِلَافِ،', 'لاويين 26:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 41, 'وَإِنِّي أَيْضًا سَلَكْتُ مَعَهُمْ بِالْخِلَافِ وَأَتَيْتُ بِهِمْ إِلَى أَرْضِ أَعْدَائِهِمْ. إِلَّا أَنْ تَخْضَعَ حِينَئِذٍ قُلُوبُهُمُ الْغُلْفُ، وَيَسْتَوْفُوا حِينَئِذٍ عَنْ ذُنُوبِهِمْ،', 'لاويين 26:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 42, 'أَذْكُرُ مِيثَاقِي مَعَ يَعْقُوبَ، وَأَذْكُرُ أَيْضًا مِيثَاقِي مَعَ إِسْحَاقَ، وَمِيثَاقِي مَعَ إِبْرَاهِيمَ، وَأَذْكُرُ الْأَرْضَ.', 'لاويين 26:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 43, 'وَالْأَرْضُ تُتْرَكُ مِنْهُمْ وَتَسْتَوْفِي سُبُوتَهَا فِي وَحْشَتِهَا مِنْهُمْ، وَهُمْ يَسْتَوْفُونَ عَنْ ذُنُوبِهِمْ لِأَنَّهُمْ قَدْ أَبَوْا أَحْكَامِي وَكَرِهَتْ أَنْفُسُهُمْ فَرَائِضِي.', 'لاويين 26:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 44, 'وَلَكِنْ مَعَ ذَلِكَ أَيْضًا مَتَى كَانُوا فِي أَرْضِ أَعْدَائِهِمْ، مَا أَبَيْتُهُمْ وَلَا كَرِهْتُهُمْ حَتَّى أُبِيدَهُمْ وَأَنْكُثَ مِيثَاقِي مَعَهُمْ، لِأَنِّي أَنَا الرَّبُّ إِلَهُهُمْ.', 'لاويين 26:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 45, 'بَلْ أَذْكُرُ لَهُمْ الْمِيثَاقَ مَعَ الْأَوَّلِينَ الَّذِينَ أَخْرَجْتُهُمْ مِنْ أَرْضِ مِصْرَ أَمَامَ أَعْيُنِ الشُّعُوبِ لِأَكُونَ لَهُمْ إِلَهًا. أَنَا الرَّبُّ».', 'لاويين 26:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 26, 46, 'هَذِهِ هِيَ الْفَرَائِضُ وَالْأَحْكَامُ وَالشَّرَائِعُ الَّتِي وَضَعَهَا الرَّبُّ بَيْنَهُ وَبَيْنَ بَنِي إِسْرَائِيلَ فِي جَبَلِ سِينَاءَ بِيَدِ مُوسَى.', 'لاويين 26:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'لاويين 27:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ إِذَا أَفْرَزَ إِنْسَانٌ نَذْرًا حَسَبَ تَقْوِيمِكَ نُفُوسًا لِلرَّبِّ،', 'لاويين 27:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 3, 'فَإِنْ كَانَ تَقْوِيمُكَ لِذَكَرٍ مِنِ ابْنِ عِشْرِينَ سَنَةً إِلَى ابْنِ سِتِّينَ سَنَةً، يَكُونُ تَقْوِيمُكَ خَمْسِينَ شَاقِلَ فِضَّةٍ عَلَى شَاقِلِ الْمَقْدِسِ.', 'لاويين 27:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 4, 'وَإِنْ كَانَ أُنْثَى يَكُونُ تَقْوِيمُكَ ثَلَاثِينَ شَاقِلًا.', 'لاويين 27:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 5, 'وَإِنْ كَانَ مِنِ ابْنِ خَمْسِ سِنِينَ إِلَى ابْنِ عِشْرِينَ سَنَةً يَكُونُ تَقْوِيمُكَ لِذَكَرٍ عِشْرِينَ شَاقِلًا، وَلِأُنْثَى عَشَرَةَ شَوَاقِلَ.', 'لاويين 27:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 6, 'وَإِنْ كَانَ مِنِ ابْنِ شَهْرٍ إِلَى ابْنِ خَمْسِ سِنِينَ يَكُونُ تَقْوِيمُكَ لِذَكَرٍ خَمْسَةَ شَوَاقِلِ فِضَّةٍ، وَلِأُنْثَى يَكُونُ تَقْوِيمُكَ ثَلَاثَةَ شَوَاقِلِ فِضَّةٍ.', 'لاويين 27:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 7, 'وَإِنْ كَانَ مِنِ ابْنِ سِتِّينَ سَنَةً فَصَاعِدًا فَإِنْ كَانَ ذَكَرًا يَكُونُ تَقْوِيمُكَ خَمْسَةَ عَشَرَ شَاقِلًا، وَأَمَّا لِلْأُنْثَى فَعَشَرَةَ شَوَاقِلَ.', 'لاويين 27:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 8, 'وَإِنْ كَانَ فَقِيرًا عَنْ تَقْوِيمِكَ يُوقِفُهُ أَمَامَ الْكَاهِنِ فَيُقَوِّمُهُ الْكَاهِنُ. عَلَى قَدْرِ مَا تَنَالُ يَدُ النَّاذِرِ يُقَوِّمُهُ الْكَاهِنُ.', 'لاويين 27:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 9, '«وَإِنْ كَانَ بَهِيمَةً مِمَّا يُقَرِّبُونَهُ قُرْبَانًا لِلرَّبِّ، فَكُلُّ مَا يُعْطِي مِنْهُ لِلرَّبِّ يَكُونُ قُدْسًا.', 'لاويين 27:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 10, 'لَا يُغَيِّرُهُ وَلَا يُبْدِلُهُ جَيِّدًا بِرَدِيءٍ، أَوْ رَدِيئًا بِجَيِّدٍ. وَإِنْ أَبْدَلَ بَهِيمَةً بِبَهِيمَةٍ تَكُونُ هِيَ وَبَدِيلُهَا قُدْسًا.', 'لاويين 27:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 11, 'وَإِنْ كَانَ بَهِيمَةً نَجِسَةً مِمَّا لَا يُقَرِّبُونَهُ قُرْبَانًا لِلرَّبِّ يُوقِفُ الْبَهِيمَةَ أَمَامَ الْكَاهِنِ،', 'لاويين 27:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 12, 'فَيُقَوِّمُهَا الْكَاهِنُ جَيِّدَةً أَمْ رَدِيئَةً. فَحَسَبَ تَقْوِيمِكَ يَا كَاهِنُ هَكَذَا يَكُونُ.', 'لاويين 27:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 13, 'فَإِنْ فَكَّهَا يَزِيدُ خُمْسَهَا عَلَى تَقْوِيمِكَ.', 'لاويين 27:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 14, '«وَإِذَا قَدَّسَ إِنْسَانٌ بَيْتَهُ قُدْسًا لِلرَّبِّ، يُقَوِّمُهُ الْكَاهِنُ جَيِّدًا أَمْ رَدِيئًا. وَكَمَا يُقَوِّمُهُ الْكَاهِنُ هَكَذَا يَقُومُ.', 'لاويين 27:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 15, 'فَإِنْ كَانَ الْمُقَدِّسُ يَفُكُّ بَيْتَهُ، يَزِيدُ خُمْسَ فِضَّةِ تَقْوِيمِكَ عَلَيْهِ فَيَكُونُ لَهُ.', 'لاويين 27:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 16, 'وَإِنْ قَدَّسَ إِنْسَانٌ بَعْضَ حَقْلِ مُلْكِهِ لِلرَّبِّ، يَكُونُ تَقْوِيمُكَ عَلَى قَدَرِ بِذَارِهِ. بِذَارُ حُومَرٍ مِنَ الشَّعِيرِ بِخَمْسِينَ شَاقِلِ فِضَّةٍ.', 'لاويين 27:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 17, 'إِنْ قَدَّسَ حَقْلَهُ مِنْ سَنَةِ الْيُوبِيلِ فَحَسَبَ تَقْوِيمِكَ يَقُومُ.', 'لاويين 27:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 18, 'وَإِنْ قَدَّسَ حَقْلَهُ بَعْدَ سَنَةِ الْيُوبِيلِ يَحْسُبُ لَهُ الْكَاهِنُ الْفِضَّةَ عَلَى قَدَرِ السِّنِينَ الْبَاقِيَةِ إِلَى سَنَةِ الْيُوبِيلِ، فَيُنَقَّصُ مِنْ تَقْوِيمِكَ.', 'لاويين 27:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 19, 'فَإِنْ فَكَّ الْحَقْلَ مُقَدِّسُهُ، يَزِيدُ خُمْسَ فِضَّةِ تَقْوِيمِكَ عَلَيْهِ فَيَجِبُ لَهُ.', 'لاويين 27:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 20, 'لَكِنْ إِنْ لَمْ يَفُكَّ الْحَقْلَ وَبِيعَ الْحَقْلُ لِإِنْسَانٍ آخَرَ لَا يُفَكُّ بَعْدُ،', 'لاويين 27:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 21, 'بَلْ يَكُونُ الْحَقْلُ عِنْدَ خُرُوجِهِ فِي الْيُوبِيلِ قُدْسًا لِلرَّبِّ كَالْحَقْلِ الْمُحَرَّمِ. لِلْكَاهِنِ يَكُونُ مُلْكُهُ.', 'لاويين 27:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 22, '«وَإِنْ قَدَّسَ لِلرَّبِّ حَقْلًا مِنْ شِرَائِهِ لَيْسَ مِنْ حُقُولِ مُلْكِهِ،', 'لاويين 27:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 23, 'يَحْسُبُ لَهُ الْكَاهِنُ مَبْلَغَ تَقْوِيمِكَ إِلَى سَنَةِ الْيُوبِيلِ، فَيُعْطِي تَقْوِيمَكَ فِي ذَلِكَ الْيَوْمِ قُدْسًا لِلرَّبِّ.', 'لاويين 27:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 24, 'وَفِي سَنَةِ الْيُوبِيلِ يَرْجِعُ الْحَقْلُ إِلَى الَّذِي اشْتَرَاهُ مِنْهُ، إِلَى الَّذِي لَهُ مُلْكُ الْأَرْضِ.', 'لاويين 27:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 25, 'وَكُلُّ تَقْوِيمِكَ يَكُونُ عَلَى شَاقِلِ الْمَقْدِسِ. عِشْرِينَ جِيرَةً يَكُونُ الشَّاقِلُ.', 'لاويين 27:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 26, '«لَكِنَّ الْبِكْرَ الَّذِي يُفْرَزُ بِكْرًا لِلرَّبِّ مِنَ الْبَهَائِمِ فَلَا يُقَدِّسُهُ أَحَدٌ. ثَوْرًا كَانَ أَوْ شَاةً فَهُوَ لِلرَّبِّ.', 'لاويين 27:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 27, 'وَإِنْ كَانَ مِنَ الْبَهَائِمِ النَّجِسَةِ يَفْدِيهِ حَسَبَ تَقْوِيمِكَ وَيَزِيدُ خُمْسَهُ عَلَيْهِ. وَإِنْ لَمْ يُفَكَّ، فَيُبَاعُ حَسَبَ تَقْوِيمِكَ.', 'لاويين 27:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 28, 'أَمَّا كُلُّ مُحَرَّمٍ يُحَرِّمُهُ إِنْسَانٌ لِلرَّبِّ مِنْ كُلِّ مَا لَهُ مِنَ النَّاسِ وَالْبَهَائِمِ وَمِنْ حُقُولِ مُلْكِهِ فَلَا يُبَاعُ وَلَا يُفَكُّ. إِنَّ كُلَّ مُحَرَّمٍ هُوَ قُدْسُ أَقْدَاسٍ لِلرَّبِّ.', 'لاويين 27:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 29, 'كُلُّ مُحَرَّمٍ يُحَرَّمُ مِنَ النَّاسِ لَا يُفْدَى. يُقْتَلُ قَتْلًا.', 'لاويين 27:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 30, '«وَكُلُّ عُشْرِ الْأَرْضِ مِنْ حُبُوبِ الْأَرْضِ وَأَثْمَارِ الشَّجَرِ فَهُوَ لِلرَّبِّ. قُدْسٌ لِلرَّبِّ.', 'لاويين 27:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 31, 'وَإِنْ فَكَّ إِنْسَانٌ بَعْضَ عُشْرِهِ يَزِيدُ خُمْسَهُ عَلَيْهِ.', 'لاويين 27:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 32, 'وَأَمَّا كُلُّ عُشْرِ الْبَقَرِ وَالْغَنَمِ فَكُلُّ مَا يَعْبُرُ تَحْتَ الْعَصَا يَكُونُ الْعَاشِرُ قُدْسًا لِلرَّبِّ.', 'لاويين 27:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 33, 'لَا يُفْحَصُ أَجَيِّدٌ هُوَ أَمْ رَدِيءٌ، وَلَا يُبْدِلُهُ. وَإِنْ أَبْدَلَهُ يَكُونُ هُوَ وَبَدِيلُهُ قُدْسًا. لَا يُفَكُّ».', 'لاويين 27:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'لاويين', 27, 34, 'هَذِهِ هِيَ الْوَصَايَا الَّتِي أَوْصَى الرَّبُّ بِهَا مُوسَى إِلَى بَنِي إِسْرَائِيلَ فِي جَبَلِ سِينَاءَ.', 'لاويين 27:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى فِي بَرِّيَّةِ سِينَاءَ، فِي خَيْمَةِ الِاجْتِمَاعِ، فِي أَوَّلِ الشَّهْرِ الثَّانِي فِي السَّنَةِ الثَّانِيَةِ لِخُرُوجِهِمْ مِنْ أَرْضِ مِصْرَ قَائِلًا׃', 'عدد 1:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 2, '«أَحْصُوا كُلَّ جَمَاعَةِ بَنِي إِسْرَائِيلَ بِعَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ، كُلَّ ذَكَرٍ بِرَأْسِهِ،', 'عدد 1:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 3, 'مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلَّ خَارِجٍ لِلْحَرْبِ فِي إِسْرَائِيلَ. تَحْسُبُهُمْ أَنْتَ وَهَارُونُ حَسَبَ أَجْنَادِهِمْ.', 'عدد 1:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 4, 'وَيَكُونُ مَعَكُمَا رَجُلٌ لِكُلِّ سِبْطٍ، رَجُلٌ هُوَ رَأْسٌ لِبَيْتِ آبَائِهِ.', 'عدد 1:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 5, 'وَهَذِهِ أَسْمَاءُ الرِّجَالِ الَّذِينَ يَقِفُونَ مَعَكُمَا׃ لِرَأُوبَيْنَ أَلِيصُورُ بْنُ شَدَيْئُورَ.', 'عدد 1:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 6, 'لِشِمْعُونَ شَلُومِيئِيلُ بْنُ صُورِيشَدَّاي.', 'عدد 1:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 7, 'لِيَهُوذَا نَحْشُونُ بْنُ عَمِّينَادَابَ.', 'عدد 1:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 8, 'لِيَسَّاكَرَ نَثَنَائِيلُ بْنُ صُوغَرَ.', 'عدد 1:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 9, 'لِزَبُولُونَ أَلِيآبُ بْنُ حِيلُونَ.', 'عدد 1:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 10, 'لِابْنَيْ يُوسُفَ׃ لِأَفْرَايِمَ أَلِيشَمَعُ بْنُ عَمِّيهُودَ، وَلِمَنَسَّى جَمْلِيئِيلُ بْنُ فَدَهْصُورَ.', 'عدد 1:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 11, 'لِبَنْيَامِينَ أَبِيدَنُ بْنُ جِدْعُونِي.', 'عدد 1:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 12, 'لِدَانَ أَخِيعَزَرُ بْنُ عَمِّيشَدَّاي.', 'عدد 1:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 13, 'لِأَشِيرَ فَجْعِيئِيلُ بْنُ عُكْرَنَ.', 'عدد 1:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 14, 'لِجَادَ أَلِيَاسَافُ بْنُ دَعُوئِيلَ.', 'عدد 1:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 15, 'لِنَفْتَالِي أَخِيرَعُ بْنُ عِينَنَ».', 'عدد 1:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 16, 'هَؤُلَاءِ هُمْ مَشَاهِيرُ الْجَمَاعَةِ، رُؤَسَاءُ أَسْبَاطِ آبَائِهِمْ. رُؤُوسُ أُلُوفِ إِسْرَائِيلَ.', 'عدد 1:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 17, 'فَأَخَذَ مُوسَى وَهَارُونُ هَؤُلَاءِ الرِّجَالَ الَّذِينَ تَعَيَّنُوا بِأَسْمَائِهِمْ،', 'عدد 1:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 18, 'وَجَمَعَا كُلَّ الْجَمَاعَةِ فِي أَوَّلِ الشَّهْرِ الثَّانِي، فَانْتَسَبُوا إِلَى عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ بِعَدَدِ الْأَسْمَاءِ، مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا بِرُؤُوسِهِمْ،', 'عدد 1:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 19, 'كَمَا أَمَرَ الرَّبُّ مُوسَى. فَعَدَّهُمْ فِي بَرِّيَّةِ سِينَاءَ.', 'عدد 1:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 20, 'فَكَانَ بَنُو رَأُوبَيْنَ بِكْرِ إِسْرَائِيلَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ بِرُؤُوسِهِمْ، كُلُّ ذَكَرٍ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 21, 'كَانَ الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ رَأُوبَيْنَ سِتَّةً وَأَرْبَعِينَ أَلْفًا وَخَمْسَ مِئَةٍ.', 'عدد 1:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 22, 'بَنُو شِمْعُونَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمِ، الْمَعْدُودُونَ مِنْهُمْ بِعَدَدِ الْأَسْمَاءِ بِرُؤُوسِهِمْ، كُلُّ ذَكَرٍ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 23, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ شِمْعُونَ تِسْعَةٌ وَخَمْسُونَ أَلْفًا وَثَلَاثُ مِئَةٍ.', 'عدد 1:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 24, 'بَنُو جَادَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 25, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ جَادَ خَمْسَةٌ وَأَرْبَعُونَ أَلْفًا وَسِتُّ مِئَةٍ وَخَمْسُونَ.', 'عدد 1:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 26, 'بَنُو يَهُوذَا، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 27, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ يَهُوذَا أَرْبَعَةٌ وَسَبْعُونَ أَلْفًا وَسِتُّ مِئَةٍ.', 'عدد 1:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 28, 'بَنُو يَسَّاكَرَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 29, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ يَسَّاكَرَ أَرْبَعَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 1:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 30, 'بَنُو زَبُولُونَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 31, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ زَبُولُونَ سَبْعَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 1:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 32, 'بَنُو يُوسُفَ׃ بَنُو أَفْرَايِمَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 33, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ أَفْرَايِمَ أَرْبَعُونَ أَلْفًا وَخَمْسُ مِئَةٍ.', 'عدد 1:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 34, 'بَنُو مَنَسَّى، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 35, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ مَنَسَّى اثْنَانِ وَثَلَاثُونَ أَلْفًا وَمِئَتَانِ.', 'عدد 1:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 36, 'بَنُو بَنْيَامِينَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 37, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ بَنْيَامِينَ خَمْسَةٌ وَثَلَاثُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 1:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 38, 'بَنُو دَانَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 39, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ دَانَ اثْنَانِ وَسِتُّونَ أَلْفًا وَسَبْعُ مِئَةٍ.', 'عدد 1:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 40, 'بَنُو أَشِيرَ، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 41, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ أَشِيرَ وَاحِدٌ وأَرْبَعُونَ أَلْفًا وَخَمْسُ مِئَةٍ.', 'عدد 1:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 42, 'بَنُو نَفْتَالِي، تَوَالِيدُهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ، بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ،', 'عدد 1:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 43, 'الْمَعْدُودُونَ مِنْهُمْ لِسِبْطِ نَفْتَالِي ثَلَاثَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 1:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 44, 'هَؤُلَاءِ هُمُ الْمَعْدُودُونَ الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ وَرُؤَسَاءُ إِسْرَائِيلَ، اثْنَا عَشَرَ رَجُلًا، رَجُلٌ وَاحِدٌ لِبَيْتِ آبَائِهِ.', 'عدد 1:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 45, 'فَكَانَ جَمِيعُ الْمَعْدُودِينَ مِنْ بَنِي إِسْرَائِيلَ حَسَبَ بُيُوتِ آبَائِهِمْ مِنِ ابْنِ عِشْرِينَ سَنَةً فَصَاعِدًا، كُلُّ خَارِجٍ لِلْحَرْبِ فِي إِسْرَائِيلَ.', 'عدد 1:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 46, 'كَانَ جَمِيعُ الْمَعْدُودِينَ سِتَّ مِئَةِ أَلْفٍ وَثَلَاثَةَ آلَافٍ وَخَمْسَ مِئَةٍ وَخَمْسِينَ.', 'عدد 1:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 47, 'وَأَمَّا اللَّاوِيُّونَ حَسَبَ سِبْطِ آبَائِهِمْ فَلَمْ يُعَدُّوا بَيْنَهُمْ،', 'عدد 1:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 48, 'إِذْ كَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 1:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 49, '«أَمَّا سِبْطُ لَاوِي فَلَا تَحْسُبُهُ وَلَا تَعُدَّهُ بَيْنَ بَنِي إِسْرَائِيلَ.', 'عدد 1:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 50, 'بَلْ وَكِّلِ اللَّاوِيِّينَ عَلَى مَسْكَنِ الشَّهَادَةِ وَعَلَى جَمِيعِ أَمْتِعَتِهِ وَعَلَى كُلِّ مَا لَهُ. هُمْ يَحْمِلُونَ الْمَسْكَنَ وَكُلَّ أَمْتِعَتِهِ، وَهُمْ يَخْدِمُونَهُ، وَحَوْلَ الْمَسْكَنِ يَنْزِلُونَ.', 'عدد 1:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 51, 'فَعِنْدَ ارْتِحَالِ الْمَسْكَنِ يُنَزِّلُهُ اللَّاوِيُّونَ وَعِنْدَ نُزُولِ الْمَسْكَنِ يُقِيمُهُ اللَّاوِيُّونَ. وَالْأَجْنَبِيُّ الَّذِي يَقْتَرِبُ يُقْتَلُ.', 'عدد 1:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 52, 'وَيَنْزِلُ بَنُو إِسْرَائِيلَ كُلٌّ فِي مَحَلَّتِهِ وَكُلٌّ عِنْدَ رَايَتِهِ بِأَجْنَادِهِمْ.', 'عدد 1:52');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 53, 'وَأَمَّا اللَّاوِيُّونَ فَيَنْزِلُونَ حَوْلَ مَسْكَنِ الشَّهَادَةِ لِكَيْ لَا يَكُونَ سَخَطٌ عَلَى جَمَاعَةِ بَنِي إِسْرَائِيلَ، فَيَحْفَظُ اللَّاوِيُّونَ شَعَائِرَ مَسْكَنِ الشَّهَادَةِ».', 'عدد 1:53');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 1, 54, 'فَفَعَلَ بَنُو إِسْرَائِيلَ حَسَبَ كُلِّ مَا أَمَرَ الرَّبُّ مُوسَى كَذَلِكَ فَعَلُوا.', 'عدد 1:54');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ َقَائِلًا׃', 'عدد 2:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 2, '«يَنْزِلُ بَنُو إِسْرَائِيلَ كُلٌّ عِنْدَ رَايَتِهِ بِأَعْلَامٍ لِبُيُوتِ آبَائِهِمْ. قُبَالَةَ خَيْمَةِ الِاجْتِمَاعِ حَوْلَهَا يَنْزِلُونَ.', 'عدد 2:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 3, 'فَالنَّازِلُونَ إِلَى الشَّرْقِ، نَحْوَ الشُّرُوقِ، رَايَةُ مَحَلَّةِ يَهُوذَا حَسَبَ أَجْنَادِهِمْ، وَالرَّئِيسُ لِبَنِي يَهُوذَا نَحْشُونُ بْنُ عَمِّينَادَابَ،', 'عدد 2:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 4, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ أَرْبَعَةٌ وَسَبْعُونَ أَلْفًا وَسِتُّ مِئَةٍ.', 'عدد 2:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 5, 'وَالنَّازِلُونَ مَعَهُ سِبْطُ يَسَّاكَرَ، وَالرَّئِيسُ لِبَنِي يَسَّاكَرَ نَثَنَائِيلُ بْنُ صُوغَرَ،', 'عدد 2:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 6, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُ أَرْبَعَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 2:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 7, 'وَسِبْطُ زَبُولُونَ، وَالرَّئِيسُ لِبَنِي زَبُولُونَ أَلِيآبُ بْنُ حِيلُونَ،', 'عدد 2:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 8, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُ سَبْعَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 2:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 9, 'جَمِيعُ الْمَعْدُودِينَ لِمَحَلَّةِ يَهُوذَا مِئَةُ أَلْفٍ وَسِتَّةٌ وَثَمَانُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ بِأَجْنَادِهِمْ. يَرْتَحِلُونَ أَوَّلًا.', 'عدد 2:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 10, '«رَايَةُ مَحَلَّةِ رَأُوبَيْنَ إِلَى التَّيْمَنِ حَسَبَ أَجْنَادِهِمْ، وَالرَّئِيسُ لِبَنِي رَأُوبَيْنَ أَلِيصُورُ بْنُ شَدَيْئُورَ،', 'عدد 2:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 11, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُ سِتَّةٌ وَأَرْبَعُونَ أَلْفًا وَخَمْسُ مِئَةٍ.', 'عدد 2:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 12, 'وَالنَّازِلُونَ مَعَهُ سِبْطُ شِمْعُونَ، وَالرَّئِيسُ لِبَنِي شِمْعُونَ شَلُومِيئِيلُ بْنُ صُورِيشَدَّاي،', 'عدد 2:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 13, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ تِسْعَةٌ وَخَمْسُونَ أَلْفًا وَثَلَاثُ مِئَةٍ.', 'عدد 2:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 14, 'وَسِبْطُ جَادَ، وَالرَّئِيسُ لِبَنِي جَادْ أَلِيَاسَافُ بْنُ رَعُوئِيلَ،', 'عدد 2:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 15, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ خَمْسَةٌ وَأَرْبَعُونَ أَلْفًا وَسِتُّ مِئَةٍ وَخَمْسُونَ.', 'عدد 2:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 16, 'جَمِيعُ الْمَعْدُودِينَ لِمَحَلَّةِ رَأُوبَيْنَ مِئَةُ أَلْفٍ وَوَاحِدٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ وَخَمْسُونَ بِأَجْنَادِهِمْ، وَيَرْتَحِلُونَ ثَانِيَةً.', 'عدد 2:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 17, '«ثُمَّ تَرْتَحِلُ خَيْمَةُ الِاجْتِمَاعِ. مَحَلَّةُ اللَّاوِيِّينَ فِي وَسَطِ الْمَحَلَّاتِ. كَمَا يَنْزِلُونَ كَذَلِكَ يَرْتَحِلُونَ. كُلٌّ فِي مَوْضِعِهِ بِرَايَاتِهِمْ.', 'عدد 2:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 18, '«رَايَةُ مَحَلَّةِ أَفْرَايِمَ حَسَبَ أَجْنَادِهِمْ إِلَى الْغَرْبِ، وَالرَّئِيسُ لِبَنِي أَفْرَايِمَ أَلِيشَمَعُ بْنُ عَمِّيهُودَ،', 'عدد 2:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 19, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ أَرْبَعُونَ أَلْفًا وَخَمْسُ مِئَةٍ.', 'عدد 2:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 20, 'وَمَعَهُ سِبْطُ مَنَسَّى، وَالرَّئِيسُ لِبَنِي مَنَسَّى جَمْلِيئِيلُ بْنُ فَدَهْصُورَ،', 'عدد 2:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 21, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمُ اثْنَانِ وَثَلَاثُونَ أَلْفًا وَمِئَتَانِ.', 'عدد 2:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 22, 'وَسِبْطُ بَنْيَامِينَ، وَالرَّئِيسُ لِبَنِي بَنْيَامِينَ أَبِيدَنُ بْنُ جِدْعُونِي،', 'عدد 2:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 23, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ خَمْسَةٌ وَثَلَاثُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 2:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 24, 'جَمِيعُ الْمَعْدُودِينَ لِمَحَلَّةِ أَفْرَايِمَ مِئَةُ أَلْفٍ وَثَمَانِيَةُ آلَافٍ وَمِئَةٌ بِأَجْنَادِهِمْ، وَيَرْتَحِلُونَ ثَالِثَةً.', 'عدد 2:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 25, '«رَايَةُ مَحَلَّةِ دَانَ إِلَى الشِّمَالِ حَسَبَ أَجْنَادِهِمْ، وَالرَّئِيسُ لِبَنِي دَانَ أَخِيعَزَرُ بْنُ عَمِّيشَدَّاي،', 'عدد 2:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 26, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمُ اثْنَانِ وَسِتُّونَ أَلْفًا وَسَبْعُ مِئَةٍ.', 'عدد 2:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 27, 'وَالنَّازِلُونَ مَعَهُ سِبْطُ أَشِيرَ، وَالرَّئِيسُ لِبَنِي أَشِيرَ فَجْعِيئِيلُ بْنُ عُكْرَنَ،', 'عدد 2:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 28, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ وَاحِدٌ وَأَرْبَعُونَ أَلْفًا وَخَمْسُ مِئَةٍ.', 'عدد 2:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 29, 'وَسِبْطُ نَفْتَالِي، وَالرَّئِيسُ لِبَنِي نَفْتَالِي أَخِيرَعُ بْنُ عِينَنَ،', 'عدد 2:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 30, 'وَجُنْدُهُ الْمَعْدُودُونَ مِنْهُمْ ثَلَاثَةٌ وَخَمْسُونَ أَلْفًا وَأَرْبَعُ مِئَةٍ.', 'عدد 2:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 31, 'جَمِيعُ الْمَعْدُودِينَ لِمَحَلَّةِ دَانَ مِئَةُ أَلْفٍ وَسَبْعَةٌ وَخَمْسُونَ أَلْفًا وَسِتُّ مِئَةٍ. يَرْتَحِلُونَ أَخِيرًا بِرَايَاتِهِمْ».', 'عدد 2:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 32, 'هَؤُلَاءِ هُمُ الْمَعْدُودُونَ مِنْ بَنِي إِسْرَائِيلَ حَسَبَ بُيُوتِ آبَائِهِمْ. جَمِيعُ الْمَعْدُودِينَ مِنَ الْمَحَلَّاتِ بِأَجْنَادِهِمْ سِتُّ مِئَةِ أَلْفٍ وَثَلَاثَةُ آلَافٍ وَخَمْسُ مِئَةٍ وَخَمْسُونَ.', 'عدد 2:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 33, 'وَأَمَّا اللَّاوِيُّونَ فَلَمْ يُعَدُّوا بَيْنَ بَنِي إِسْرَائِيلَ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'عدد 2:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 2, 34, 'فَفَعَلَ بَنُو إِسْرَائِيلَ حَسَبَ كُلِّ مَا أَمَرَ بِهِ الرَّبُّ مُوسَى. هَكَذَا نَزَلُوا بِرَايَاتِهِمْ، وَهَكَذَا ارْتَحَلُوا. كُلٌّ حَسَبَ عَشَائِرِهِ مَعَ بَيْتِ آبَائِهِ.', 'عدد 2:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 1, 'وَهَذِهِ تَوَالِيدُ هَارُونَ وَمُوسَى يَوْمَ كَلَّمَ الرَّبُّ مُوسَى فِي جَبَلِ سِينَاءَ.', 'عدد 3:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 2, 'وَهَذِهِ أَسْمَاءُ بَنِي هَارُونَ׃ نَادَابُ الْبِكْرُ، وَأَبِيهُو وَأَلِعَازَارُ وَإِيثَامَارُ.', 'عدد 3:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 3, 'هَذِهِ أَسْمَاءُ بَنِي هَارُونَ الْكَهَنَةِ الْمَمْسُوحِينَ الَّذِينَ مَلَأَ أَيْدِيَهُمْ لِلْكَهَانَةِ.', 'عدد 3:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 4, 'وَلَكِنْ مَاتَ نَادَابُ وَأَبِيهُو أَمَامَ الرَّبِّ عِنْدَمَا قَرَّبَا نَارًا غَرِيبَةً أَمَامَ الرَّبِّ فِي بَرِّيَّةِ سِينَاءَ، وَلَمْ يَكُنْ لَهُمَا بَنُونَ. وَأَمَّا أَلِعَازَارُ وَإِيثَامَارُ فَكَهَنَا أَمَامَ هَارُونَ أَبِيهِمَا.', 'عدد 3:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 5, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 3:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 6, '«قَدِّمْ سِبْطَ لَاوِي وَأَوْقِفْهُمْ قُدَّامَ هَارُونَ الْكَاهِنِ وَلْيَخْدِمُوهُ.', 'عدد 3:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 7, 'فَيَحْفَظُونَ شَعَائِرَهُ وَشَعَائِرَ كُلِّ الْجَمَاعَةِ قُدَّامَ خَيْمَةِ الِاجْتِمَاعِ، وَيَخْدِمُونَ خِدْمَةَ الْمَسْكَنِ،', 'عدد 3:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 8, 'فَيَحْرُسُونَ كُلَّ أَمْتِعَةِ خَيْمَةِ الِاجْتِمَاعِ، وَحِرَاسَةِ بَنِي إِسْرَائِيلَ وَيَخْدِمُونَ خِدْمَةَ الْمَسْكَنِ.', 'عدد 3:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 9, 'فَتُعْطِي اللَّاوِيِّينَ لِهَارُونَ وَلِبَنِيهِ. إِنَّهُمْ مَوْهُوبُونَ لَهُ هِبَةً مِنْ عِنْدِ بَنِي إِسْرَائِيلَ.', 'عدد 3:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 10, 'وَتُوَكِّلُ هَارُونَ وَبَنِيهِ فَيَحْرُسُونَ كَهَنُوتَهُمْ، وَالْأَجْنَبِيُّ الَّذِي يَقْتَرِبُ يُقْتَلُ».', 'عدد 3:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 11, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 3:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 12, '«وَهَا إِنِّي قَدْ أَخَذْتُ اللَّاوِيِّينَ مِنْ بَيْنِ بَنِي إِسْرَائِيلَ، بَدَلَ كُلِّ بِكْرٍ فَاتِحِ رَحِمٍ مِنْ بَنِي إِسْرَائِيلَ فَيَكُونُ اللَّاوِيُّونَ لِي.', 'عدد 3:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 13, 'لِأَنَّ لِي كُلَّ بِكْرٍ. يَوْمَ ضَرَبْتُ كُلَّ بِكْرٍ فِي أَرْضِ مِصْرَ قَدَّسْتُ لِي كُلَّ بِكْرٍ فِي إِسْرَائِيلَ مِنَ النَّاسِ وَالْبَهَائِمِ. لِي يَكُونُونَ. أَنَا الرَّبُّ».', 'عدد 3:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 14, 'وَكَلَّمَ الرَّبُّ مُوسَى فِي بَرِّيَّةِ سِينَاءَ قَائِلًا׃', 'عدد 3:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 15, '«عُدَّ بَنِي لَاوِي حَسَبَ بُيُوتِ آبَائِهِمْ وَعَشَائِرِهِمْ. كُلَّ ذَكَرٍ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا تَعُدُّهُمْ».', 'عدد 3:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 16, 'فَعَدَّهُمْ مُوسَى حَسَبَ قَوْلِ الرَّبِّ كَمَا أُمِرَ.', 'عدد 3:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 17, 'وَكَانَ هَؤُلَاءِ بَنِي لَاوِي بِأَسْمَائِهِمْ׃ جَرْشُونُ وَقَهَاتُ وَمَرَارِي.', 'عدد 3:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 18, 'وَهَذَانِ اسْمَا ابْنَيْ جَرْشُونَ حَسَبَ عَشَائِرِهِمَا׃ لِبْنِي وَشِمْعِي.', 'عدد 3:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 19, 'وَبَنُو قَهَاتَ حَسَبَ عَشَائِرِهِمْ׃ عَمْرَامُ وَيِصْهَارُ وَحَبْرُونُ وَعُزِّيئِيلُ.', 'عدد 3:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 20, 'وَابْنَا مَرَارِي حَسَبَ عَشَائِرِهِمَا׃ مَحْلِي وَمُوشِي. هَذِهِ هِيَ عَشَائِرُ اللَّاوِيِّينَ حَسَبَ بُيُوتِ آبَائِهِمْ.', 'عدد 3:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 21, 'لِجَرْشُونَ عَشِيرَةُ اللِّبْنِيِّينَ وَعَشِيرَةُ الشِّمْعِيِّينَ. هَذِهِ هِيَ عَشَائِرُ الْجَرْشُونِيِّينَ.', 'عدد 3:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 22, 'الْمَعْدُودُونَ مِنْهُمْ بِعَدَدِ كُلِّ ذَكَرٍ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا، الْمَعْدُودُونَ مِنْهُمْ سَبْعَةُ آلَافٍ وَخَمْسُ مِئَةٍ.', 'عدد 3:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 23, 'عَشَائِرُ الْجَرْشُونِيِّينَ يَنْزِلُونَ وَرَاءَ الْمَسْكَنِ إِلَى الْغَرْبِ،', 'عدد 3:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 24, 'وَالرَّئِيسُ لِبَيْتِ أَبِي الْجَرْشُونِيِّينَ أَلِيَاسَافُ بْنُ لَايِلَ.', 'عدد 3:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 25, 'وَحِرَاسَةُ بَنِي جَرْشُونَ فِي خَيْمَةِ الِاجْتِمَاعِ׃ الْمَسْكَنُ، وَالْخَيْمَةُ وَغِطَاؤُهَا، وَسَجْفُ بَابِ خَيْمَةِ الِاجْتِمَاعِ،', 'عدد 3:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 26, 'وَأَسْتَارُ الدَّارِ وَسَجْفُ بَابِ الدَّارِ اللَّوَاتِي حَوْلَ الْمَسْكَنِ وَحَوْلَ الْمَذْبَحِ مُحِيطًا وَأَطْنَابُهُ مَعَ كُلِّ خِدْمَتِهِ.', 'عدد 3:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 27, 'وَلِقَهَاتَ عَشِيرَةُ الْعَمْرَامِيِّينَ وَعَشِيرَةُ الْيِصْهَارِيِّينَ وَعَشِيرَةُ الْحَبْرُونِيِّينَ وَعَشِيرَةُ الْعُزِّيئِيلِيِّينَ. هَذِهِ عَشَائِرُ الْقَهَاتِيِّينَ،', 'عدد 3:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 28, 'بِعَدَدِ كُلِّ ذَكَرٍ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا ثَمَانِيَةُ آلَافٍ وَسِتُّ مِئَةٍ حَارِسِينَ حِرَاسَةَ الْقُدْسِ.', 'عدد 3:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 29, 'وَعَشَائِرُ بَنِي قَهَاتَ يَنْزِلُونَ عَلَى جَانِبِ الْمَسْكَنِ إِلَى التَّيْمَنِ،', 'عدد 3:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 30, 'وَالرَّئِيسُ لِبَيْتِ أَبِي عَشِيرَةِ الْقَهَاتِيِّينَ أَلِيصَافَانُ بْنُ عُزِّيئِيلَ.', 'عدد 3:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 31, 'وَحِرَاسَتُهُمُ التَّابُوتُ وَالْمَائِدَةُ وَالْمَنَارَةُ وَالْمَذْبَحَانِ وَأَمْتِعَةُ الْقُدْسِ الَّتِي يَخْدِمُونَ بِهَا، وَالْحِجَابُ وَكُلُّ خِدْمَتِهِ.', 'عدد 3:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 32, 'وَلِرَئِيسِ رُؤَسَاءِ اللَّاوِيِّينَ أَلِعَازَارَ بْنِ هَارُونَ الْكَاهِنِ وَكَالَةُ حُرَّاسِ حِرَاسَةِ الْقُدْسِ.', 'عدد 3:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 33, 'وَلِمَرَارِي عَشِيرَةُ الْمَحْلِيِّينَ وَعَشِيرَةُ الْمُوشِيِّينَ. هَذِهِ هِيَ عَشَائِرُ مَرَارِي.', 'عدد 3:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 34, 'وَالْمَعْدُودُونَ مِنْهُمْ بِعَدَدِ كُلِّ ذَكَرٍ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا سِتَّةُ آلَافٍ وَمِئَتَانِ،', 'عدد 3:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 35, 'وَالرَّئِيسُ لِبَيْتِ أَبِي عَشَائِرِ مَرَارِي صُورِيئِيلُ بْنُ أَبِيَحَايِلَ. يَنْزِلُونَ عَلَى جَانِبِ الْمَسْكَنِ إِلَى الشِّمَالِ.', 'عدد 3:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 36, 'وَوَكَالَةُ حِرَاسَةِ بَنِي مَرَارِي׃ أَلْوَاحُ الْمَسْكَنِ وَعَوَارِضُهُ وَأَعْمِدَتُهُ وَفُرَضُهُ وَكُلُّ أَمْتِعَتِهِ وَكُلُّ خِدْمَتِهِ،', 'عدد 3:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 37, 'وَأَعْمِدَةُ الدَّارِ حَوَالَيْهَا وَفُرَضُهَا وَأَوْتَادُهَا وَأَطْنَابُهَا.', 'عدد 3:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 38, 'وَالنَّازِلُونَ قُدَّامَ الْمَسْكَنِ إِلَى الشَّرْقِ قُدَّامَ خَيْمَةِ الِاجْتِمَاعِ، نَحْوَ الشُّرُوقِ، هُمْ مُوسَى وَهَارُونُ وَبَنُوهُ، حَارِسِينَ حِرَاسَةَ الْمَقْدِسِ لِحِرَاسَةِ بَنِي إِسْرَائِيلَ، وَالْأَجْنَبِيُّ الَّذِي يَقْتَرِبُ يُقْتَلُ.', 'عدد 3:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 39, 'جَمِيعُ الْمَعْدُودِينَ مِنَ اللَّاوِيِّينَ الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ حَسَبَ قَوْلِ الرَّبِّ بِعَشَائِرِهِمْ، كُلُّ ذَكَرٍ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا، اثْنَانِ وَعِشْرُونَ أَلْفًا.', 'عدد 3:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 40, 'وَقَالَ الرَّبُّ لِمُوسَى׃ «عُدَّ كُلَّ بِكْرٍ ذَكَرٍ مِنْ بَنِي إِسْرَائِيلَ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا، وَخُذْ عَدَدَ أَسْمَائِهِمْ.', 'عدد 3:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 41, 'فَتَأْخُذُ اللَّاوِيِّينَ لِي. أَنَا الرَّبُّ. بَدَلَ كُلِّ بِكْرٍ فِي بَنِي إِسْرَائِيلَ. وَبَهَائِمَ اللَّاوِيِّينَ بَدَلَ كُلِّ بِكْرٍ فِي بَهَائِمِ بَنِي إِسْرَائِيلَ».', 'عدد 3:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 42, 'فَعَدَّ مُوسَى كَمَا أَمَرَهُ الرَّبُّ كُلَّ بِكْرٍ فِي بَنِي إِسْرَائِيلَ.', 'عدد 3:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 43, 'فَكَانَ جَمِيعُ الْأَبْكَارِ الذُّكُورِ بِعَدَدِ الْأَسْمَاءِ مِنِ ابْنِ شَهْرٍ فَصَاعِدًا، الْمَعْدُودِينَ مِنْهُمُ اثْنَيْنِ وَعِشْرِينَ أَلْفًا وَمِئَتَيْنِ وَثَلَاثَةً وَسَبْعِينَ.', 'عدد 3:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 44, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 3:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 45, '«خُذِ اللَّاوِيِّينَ بَدَلَ كُلِّ بِكْرٍ فِي بَنِي إِسْرَائِيلَ، وَبَهَائِمَ اللَّاوِيِّينَ بَدَلَ بَهَائِمِهِمْ، فَيَكُونَ لِيَ اللَّاوِيُّونَ. أَنَا الرَّبُّ.', 'عدد 3:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 46, 'وَأَمَّا فِدَاءُ الْمِئَتَيْنِ وَالثَّلَاثَةِ وَالسَّبْعِينَ الزَّائِدِينَ عَلَى اللَّاوِيِّينَ مِنْ أَبْكَارِ بَنِي إِسْرَائِيلَ،', 'عدد 3:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 47, 'فَتَأْخُذُ خَمْسَةَ شَوَاقِلَ لِكُلِّ رَأْسٍ. عَلَى شَاقِلِ الْقُدْسِ تَأْخُذُهَا. عِشْرُونَ جِيرَةً الشَّاقِلُ.', 'عدد 3:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 48, 'وَتُعْطِي الْفِضَّةَ لِهَارُونَ وَبَنِيهِ فِدَاءَ الزَّائِدِينَ عَلَيْهِمْ».', 'عدد 3:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 49, 'فَأَخَذَ مُوسَى فِضَّةَ فِدَائِهِمْ مِنَ الزَّائِدِينَ عَلَى فِدَاءِ اللَّاوِيِّينَ.', 'عدد 3:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 50, 'مِنْ أَبْكَارِ بَنِي إِسْرَائِيلَ أَخَذَ الْفِضَّةَ أَلْفًا وَثَلَاثَ مِئَةٍ وَخَمْسَةً وَسِتِّينَ عَلَى شَاقِلِ الْقُدْسِ،', 'عدد 3:50');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 3, 51, 'وَأَعْطَى مُوسَى فِضَّةَ الْفِدَاءِ لِهَارُونَ وَبَنِيهِ حَسَبَ قَوْلِ الرَّبِّ، كَمَا أَمَرَ الرَّبُّ مُوسَى.', 'عدد 3:51');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'عدد 4:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 2, '«خُذْ عَدَدَ بَنِي قَهَاتَ مِنْ بَيْنِ بَنِي لَاوِي حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ،', 'عدد 4:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 3, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً، كُلِّ دَاخِلٍ فِي الْجُنْدِ لِيَعْمَلَ عَمَلًا فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 4, 'هَذِهِ خِدْمَةُ بَنِي قَهَاتَ فِي خَيْمَةِ الِاجْتِمَاعِ׃ قُدْسُ الْأَقْدَاسِ.', 'عدد 4:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 5, 'يَأْتِي هَارُونُ وَبَنُوهُ عِنْدَ ارْتِحَالِ الْمَحَلَّةِ وَيُنَزِّلُونَ حِجَابَ السَّجْفِ وَيُغَطُّونَ بِهِ تَابُوتَ الشَّهَادَةِ،', 'عدد 4:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 6, 'وَيَجْعَلُونَ عَلَيْهِ غِطَاءً مِنْ جِلْدِ تُخَسٍ، وَيَبْسُطُونَ مِنْ فَوْقُ ثَوْبًا كُلُّهُ أَسْمَانْجُونِيٌّ، وَيَضَعُونَ عِصِيَّهُ.', 'عدد 4:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 7, 'وَعَلَى مَائِدَةِ الْوُجُوهِ يَبْسُطُونَ ثَوْبَ أَسْمَانْجُونٍ، وَيَضَعُونَ عَلَيْهِ الصِّحَافَ وَالصُّحُونَ وَالْأَقْدَاحَ وَكَاسَاتِ السَّكِيبِ، وَيَكُونُ الْخُبْزُ الدَّائِمُ عَلَيْهِ،', 'عدد 4:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 8, 'وَيَبْسُطُونَ عَلَيْهَا ثَوْبَ قِرْمِزٍ وَيُغَطُّونَهُ بِغِطَاءٍ مِنْ جِلْدِ تُخَسٍ وَيَضَعُونَ عِصِيَّهُ.', 'عدد 4:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 9, 'وَيَأْخُذُونَ ثَوْبَ أَسْمَانْجُونٍ وَيُغَطُّونَ مَنَارَةَ الضَّوْءِ وَسُرُجَهَا وَمَلَاقِطَهَا وَمَنَافِضَهَا وَجَمِيعَ آنِيَةِ زَيْتِهَا الَّتِي يَخْدِمُونَهَا بِهَا.', 'عدد 4:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 10, 'وَيَجْعَلُونَهَا وَجَمِيعَ آنِيَتَهَا فِي غِطَاءٍ مِنْ جِلْدِ تُخَسٍ، وَيَجْعَلُونَهُ عَلَى الْعَتَلَةِ.', 'عدد 4:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 11, 'وَعَلَى مَذْبَحِ الذَّهَبِ يَبْسُطُونَ ثَوْبَ أَسْمَانْجُونٍ، وَيُغَطُّونَهُ بِغِطَاءٍ مِنْ جِلْدِ تُخَسٍ وَيَضَعُونَ عِصِيَّهُ.', 'عدد 4:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 12, 'وَيَأْخُذُونَ جَمِيعَ أَمْتِعَةِ الْخِدْمَةِ الَّتِي يَخْدِمُونَ بِهَا فِي الْقُدْسِ، وَيَجْعَلُونَهَا فِي ثَوْبِ أَسْمَانْجُونٍ وَيُغَطُّونَهَا بِغِطَاءٍ مِنْ جِلْدِ تُخَسٍ، وَيَجْعَلُونَهَا عَلَى الْعَتَلَةِ.', 'عدد 4:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 13, 'وَيَرْفَعُونَ رَمَادَ الْمَذْبَحِ، وَيَبْسُطُونَ عَلَيْهِ ثَوْبَ أُرْجُوانٍ،', 'عدد 4:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 14, 'وَيَجْعَلُونَ عَلَيْهِ جَمِيعَ أَمْتِعَتِهِ الَّتِي يَخْدِمُونَ عَلَيْهِ بِهَا׃ الْمَجَامِرَ وَالْمَنَاشِلَ وَالرُّفُوشَ وَالْمَنَاضِحَ، كُلَّ أَمْتِعَةِ الْمَذْبَحِ، وَيَبْسُطُونَ عَلَيْهِ غِطَاءً مِنْ جِلْدِ تُخَسٍ، وَيَضَعُونَ عِصِيَّهُ.', 'عدد 4:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 15, 'وَمَتَى فَرَغَ هَارُونُ وَبَنُوهُ مِنْ تَغْطِيَةِ الْقُدْسِ وَجَمِيعِ أَمْتِعَةِ الْقُدْسِ عِنْدَ ارْتِحَالِ الْمَحَلَّةِ، يَأْتِي بَعْدَ ذَلِكَ بَنُو قَهَاتَ لِلْحَمْلِ وَلَكِنْ لَا يَمَسُّوا الْقُدْسَ لِئَلَّا يَمُوتُوا. ذَلِكَ حِمْلُ بَنِي قَهَاتَ فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 16, 'وَوِكَالَةُ أَلِعَازَارَ بْنِ هَارُونَ الْكَاهِنِ هِيَ زَيْتُ الضَّوْءِ وَالْبَخُورُ الْعَطِرُ وَالتَّقْدِمَةُ الدَّائِمَةُ وَدُهْنُ الْمَسْحَةِ، وَوِكَالَةُ كُلِّ الْمَسْكَنِ وَكُلِّ مَا فِيهِ بِالْقُدْسِ وَأَمْتِعَتِهِ».', 'عدد 4:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 17, 'وَكَلَّمَ الرَّبُّ مُوسَى وَهَارُونَ قَائِلًا׃', 'عدد 4:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 18, '«لَا تَقْرِضَا سِبْطَ عَشَائِرِ الْقَهَاتِيِّينَ مِنْ بَيْنِ اللَّاوِيِّينَ،', 'عدد 4:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 19, 'بَلِ افْعَلَا لَهُمْ هَذَا فَيَعِيشُوا وَلَا يَمُوتُوا عِنْدَ اقْتِرَابِهِمْ إِلَى قُدْسِ الْأَقْدَاسِ׃ يَدْخُلُ هَارُونُ وَبَنُوهُ وَيُقِيمُونَهُمْ كُلَّ إِنْسَانٍ عَلَى خِدْمَتِهِ وَحِمْلِهِ.', 'عدد 4:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 20, 'وَلَا يَدْخُلُوا لِيَرَوْا الْقُدْسَ لَحْظَةً لِئَلَّا يَمُوتُوا».', 'عدد 4:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 21, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 4:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 22, '«خُذْ عَدَدَ بَنِي جَرْشُونَ أَيْضًا حَسَبَ بُيُوتِ آبَائِهِمْ وَعَشَائِرِهِمْ،', 'عدد 4:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 23, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً تَعُدُّهُمْ، كُلَّ الدَّاخِلِينَ لِيَتَجَنَّدُوا أَجْنَادًا، لِيَخْدِمُوا خِدْمَةً فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 24, 'هَذِهِ خِدْمَةُ عَشَائِرِ الْجَرْشُونِيِّينَ مِنَ الْخِدْمَةِ وَالْحِمْلِ׃', 'عدد 4:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 25, 'يَحْمِلُونَ شُقَقَ الْمَسْكَنِ، وَخَيْمَةَ الِاجْتِمَاعِ وَغِطَاءَهَا، وَغِطَاءَ التُّخَسِ الَّذِي عَلَيْهَا مِنْ فَوْقُ، وَسَجْفَ بَابِ خَيْمَةِ الِاجْتِمَاعِ،', 'عدد 4:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 26, 'وَأَسْتَارَ الدَّارِ وَسَجْفَ مَدْخَلِ بَابِ الدَّارِ اللَّوَاتِي حَوْلَ الْمَسْكَنِ وَحَوْلَ الْمَذْبَحِ مُحِيطَةً، وَأَطْنَابَهُنَّ وَكُلَّ أَمْتِعَةِ خِدْمَتِهِنَّ. وَكُلُّ مَا يُعْمَلُ لَهُنَّ فَهُمْ يَصْنَعُونَهُ،', 'عدد 4:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 27, 'حَسَبَ قَوْلِ هَارُونَ وَبَنِيهِ تَكُونُ جَمِيعُ خِدْمَةِ بَنِي الْجَرْشُونِيِّينَ مِنْ كُلِّ حَمْلِهِمْ وَمِنْ كُلِّ خِدْمَتِهِمْ. وَتُوَكِّلُهُمْ بِحِرَاسَةِ كُلِّ أَحْمَالِهِمْ.', 'عدد 4:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 28, 'هَذِهِ خِدْمَةُ عَشَائِرِ بَنِي الْجَرْشُونِيِّينَ فِي خَيْمَةِ الِاجْتِمَاعِ، وَحِرَاسَتُهُمْ بِيَدِ إِيثَامَارَ بْنِ هَارُونَ الكَاهِنِ.', 'عدد 4:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 29, '«بَنُو مَرَارِي حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ تَعُدُّهُمْ،', 'عدد 4:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 30, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً تَعُدُّهُمْ، كُلَّ الدَّاخِلِينَ فِي الْجُنْدِ لِيَخْدِمُوا خِدْمَةَ خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 31, 'وَهَذِهِ حِرَاسَةُ حَمْلِهِمْ وَكُلُّ خِدْمَتِهِمْ فِي خَيْمَةِ الِاجْتِمَاعِ׃ أَلْوَاحُ الْمَسْكَنِ وَعَوَارِضُهُ وَأَعْمِدَتُهُ وَفُرَضُهُ،', 'عدد 4:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 32, 'وَأَعْمِدَةُ الدَّارِ حَوَالَيْهَا وَفُرَضُهَا وَأَوْتَادُهَا وَأَطْنَابُهَا مَعَ كُلِّ أَمْتِعَتِهَا وَكُلِّ خِدْمَتِهَا. وَبِالْأَسْمَاءِ تَعُدُّونَ أَمْتِعَةَ حِرَاسَةِ حَمْلِهِمْ.', 'عدد 4:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 33, 'هَذِهِ خِدْمَةُ عَشَائِرِ بَنِي مَرَارِي. كُلُّ خِدْمَتِهِمْ فِي خَيْمَةِ الِاجْتِمَاعِ بِيَدِ إِيثَامَارَ بْنِ هَارُونَ الْكَاهِنِ».', 'عدد 4:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 34, 'فَعَدَّ مُوسَى وَهَارُونُ وَرُؤَسَاءُ الْجَمَاعَةِ بَنِي الْقَهَاتِيِّينَ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ،', 'عدد 4:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 35, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً، كُلَّ الدَّاخِلِينَ فِي الْجُنْدِ لِلْخِدْمَةِ فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:35');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 36, 'فَكَانَ الْمَعْدُودُونَ مِنْهُمْ حَسَبَ عَشَائِرِهِمْ أَلْفَيْنِ وَسَبْعَ مِئَةٍ وَخَمْسِينَ.', 'عدد 4:36');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 37, 'هَؤُلَاءِ هُمُ الْمَعْدُودُونَ مِنْ عَشَائِرِ الْقَهَاتِيِّينَ، كُلُّ الْخَادِمِينَ فِي خَيْمَةِ الِاجْتِمَاعِ الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ حَسَبَ قَوْلِ الرَّبِّ عَنْ يَدِ مُوسَى.', 'عدد 4:37');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 38, 'وَالْمَعْدُودُونَ مِنْ بَنِي جَرْشُونَ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ،', 'عدد 4:38');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 39, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً، كُلُّ الدَّاخِلِينَ فِي الْجُنْدِ لِلْخِدْمَةِ فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:39');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 40, 'كَانَ الْمَعْدُودُونَ مِنْهُمْ حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ أَلْفَيْنِ وَسِتَّ مِئَةٍ وَثَلَاثِينَ.', 'عدد 4:40');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 41, 'هَؤُلَاءِ هُمُ الْمَعْدُودُونَ مِنْ عَشَائِرِ بَنِي جَرْشُونَ، كُلُّ الْخَادِمِينَ فِي خَيْمَةِ الِاجْتِمَاعِ الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ حَسَبَ قَوْلِ الرَّبِّ.', 'عدد 4:41');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 42, 'وَالْمَعْدُودُونَ مِنْ عَشَائِرِ بَنِي مَرَارِي حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ،', 'عدد 4:42');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 43, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً، كُلُّ الدَّاخِلْينَ فِي الْجُنْدِ لِلْخِدْمَةِ فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:43');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 44, 'كَانَ الْمَعْدُودُونَ مِنْهُمْ حَسَبَ عَشَائِرِهِمْ ثَلَاثَةَ آلَافٍ وَمِئَتَيْنِ.', 'عدد 4:44');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 45, 'هَؤُلَاءِ هُمُ الْمَعْدُودُونَ مِنْ عَشَائِرِ بَنِي مَرَارِي الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ حَسَبَ قَوْلِ الرَّبِّ عَنْ يَدِ مُوسَى.', 'عدد 4:45');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 46, 'جَمِيعُ الْمَعْدُودِينَ اللَّاوِيِّينَ الَّذِينَ عَدَّهُمْ مُوسَى وَهَارُونُ وَرُؤَسَاءُ إِسْرَائِيلَ، حَسَبَ عَشَائِرِهِمْ وَبُيُوتِ آبَائِهِمْ،', 'عدد 4:46');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 47, 'مِنِ ابْنِ ثَلَاثِينَ سَنَةً فَصَاعِدًا إِلَى ابْنِ خَمْسِينَ سَنَةً، كُلُّ الدَّاخِلِينَ لِيَعْمَلُوا عَمَلَ الْخِدْمَةِ وَعَمَلَ الْحَمْلِ فِي خَيْمَةِ الِاجْتِمَاعِ.', 'عدد 4:47');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 48, 'كَانَ الْمَعْدُودُونَ مِنْهُمْ ثَمَانِيَةَ آلَافٍ وَخَمْسَ مِئَةٍ وَثَمَانِينَ.', 'عدد 4:48');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 4, 49, 'حَسَبَ قَوْلِ الرَّبِّ عَنْ يَدِ مُوسَى عُدَّ كُلُّ إِنْسَانٍ عَلَى خِدْمَتِهِ وَعَلَى حَمْلِهِ، الَّذِينَ عَدَّهُمْ مُوسَى كَمَا أَمَرَهُ الرَّبُّ.', 'عدد 4:49');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 5:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 2, '«أَوْصِ بَنِي إِسْرَائِيلَ أَنْ يَنْفُوا مِنَ الْمَحَلَّةِ كُلَّ أَبْرَصَ، وَكُلَّ ذِي سَيْلٍ، وَكُلَّ مُتَنَجِّسٍ لِمَيْتٍ.', 'عدد 5:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 3, 'الذَّكَرَ وَالْأُنْثَى تَنْفُونَ. إِلَى خَارِجِ الْمَحَلَّةِ تَنْفُونَهُمْ لِكَيْلَا يُنَجِّسُوا مَحَلَّاتِهِمْ حَيْثُ أَنَا سَاكِنٌ فِي وَسَطِهِمْ».', 'عدد 5:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 4, 'فَفَعَلَ هَكَذَا بَنُو إِسْرَائِيلَ وَنَفَوْهُمْ إِلَى خَارِجِ الْمَحَلَّةِ. كَمَا كَلَّمَ الرَّبُّ مُوسَى هَكَذَا فَعَلَ بَنُو إِسْرَائِيلَ.', 'عدد 5:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 5, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 5:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 6, '«قُلْ لِبَنِي إِسْرَائِيلَ׃ إِذَا عَمِلَ رَجُلٌ أَوِ امْرَأَةٌ شَيْئًا مِنْ جَمِيعِ خَطَايَا الْإِنْسَانِ، وَخَانَ خِيَانَةً بِالرَّبِّ، فَقَدْ أَذْنَبَتْ تِلْكَ النَّفْسُ.', 'عدد 5:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 7, 'فَلْتُقِرَّ بِخَطِيَّتِهَا الَّتِي عَمِلَتْ، وَتَرُدَّ مَا أَذْنَبَتْ بِهِ بِعَيْنِهِ، وَتَزِدْ عَلَيْهِ خُمْسَهُ، وَتَدْفَعْهُ لِلَّذِي أَذْنَبَتْ إِلَيْهِ.', 'عدد 5:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 8, 'وَإِنْ كَانَ لَيْسَ لِلرَّجُلِ وَلِيٌّ لِيَرُدَّ إِلَيْهِ الْمُذْنَبَ بِهِ، فَالْمُذْنَبُ بِهِ الْمَرْدُودُ يَكُونُ لِلرَّبِّ لِأَجْلِ الْكَاهِنِ، فَضْلًا عَنْ كَبْشِ الْكَفَّارَةِ الَّذِي يُكَفِّرُ بِهِ عَنْهُ.', 'عدد 5:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 9, 'وَكُلُّ رَفِيعَةٍ مَعَ كُلِّ أَقْدَاسِ بَنِي إِسْرَائِيلَ الَّتِي يُقَدِّمُونَهَا لِلْكَاهِنِ تَكُونُ لَهُ.', 'عدد 5:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 10, 'وَالْإِنْسَانُ أَقْدَاسُهُ تَكُونُ لَهُ. إِذَا أَعْطَى إِنْسَانٌ شَيْئًا لِلْكَاهِنِ فَلَهُ يَكُونُ».', 'عدد 5:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 11, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 5:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 12, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ إِذَا زَاغَتِ امْرَأَةُ رَجُلٍ وَخَانَتْهُ خِيَانَةً،', 'عدد 5:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 13, 'وَاضْطَجَعَ مَعَهَا رَجُلٌ اضْطِجَاعَ زَرْعٍ، وَأُخْفِيَ ذَلِكَ عَنْ عَيْنَيْ رَجُلِهَا، وَاسْتَتَرَتْ وَهِيَ نَجِسَةٌ وَلَيْسَ شَاهِدٌ عَلَيْهَا، وَهِيَ لَمْ تُؤْخَذْ،', 'عدد 5:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 14, 'فَاعْتَرَاهُ رُوحُ الْغَيْرَةِ وَغَارَ عَلَى امْرَأَتِهِ وَهِيَ نَجِسَةٌ، أَوِ اعْتَرَاهُ رُوحُ الْغَيْرَةِ وَغَارَ عَلَى امْرَأَتِهِ وَهِيَ لَيْسَتْ نَجِسَةً،', 'عدد 5:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 15, 'يَأْتِي الرَّجُلُ بِامْرَأَتِهِ إِلَى الْكَاهِنِ، وَيَأْتِي بِقُرْبَانِهَا مَعَهَا׃ عُشْرِ الْإِيفَةِ مِنْ طَحِينِ شَعِيرٍ، لَا يَصُبُّ عَلَيْهِ زَيْتًا وَلَا يَجْعَلُ عَلَيْهِ لُبَانًا، لِأَنَّهُ تَقْدِمَةُ غَيْرَةٍ، تَقْدِمَةُ تَذْكَارٍ تُذَكِّرُ ذَنْبًا.', 'عدد 5:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 16, 'فَيُقَدِّمُهَا الْكَاهِنُ وَيُوقِفُهَا أَمَامَ الرَّبِّ،', 'عدد 5:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 17, 'وَيَأْخُذُ الْكَاهِنُ مَاءً مُقَدَّسًا فِي إِنَاءِ خَزَفٍ، وَيَأْخُذُ الْكَاهِنُ مِنَ الْغُبَارِ الَّذِي فِي أَرْضِ الْمَسْكَنِ وَيَجْعَلُ فِي الْمَاءِ،', 'عدد 5:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 18, 'وَيُوقِفُ الْكَاهِنُ الْمَرْأَةَ أَمَامَ الرَّبِّ، وَيَكْشِفُ رَأْسَ الْمَرْأَةِ، وَيَجْعَلُ فِي يَدَيْهَا تَقْدِمَةَ التَّذْكَارِ الَّتِي هِيَ تَقْدِمَةُ الْغَيْرَةِ، وَفِي يَدِ الْكَاهِنِ يَكُونُ مَاءُ اللَّعْنَةِ الْمُرُّ.', 'عدد 5:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 19, 'وَيَسْتَحْلِفُ الْكَاهِنُ الْمَرْأَةَ وَيَقُولُ لَهَا׃ إِنْ كَانَ لَمْ يَضْطَجِعْ مَعَكِ رَجُلٌ، وَإِنْ كُنْتِ لَمْ تَزِيغِي إِلَى نَجَاسَةٍ مِنْ تَحْتِ رَجُلِكِ، فَكُونِي بَرِيئَةً مِنْ مَاءِ اللَّعْنَةِ هَذَا الْمُرِّ.', 'عدد 5:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 20, 'وَلَكِنْ إِنْ كُنْتِ قَدْ زُغْتِ مِنْ تَحْتِ رَجُلِكِ وَتَنَجَّسْتِ، وَجَعَلَ مَعَكِ رَجُلٌ غَيْرُ رَجُلِكِ مَضْجَعَهُ.', 'عدد 5:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 21, 'يَسْتَحْلِفُ الْكَاهِنُ الْمَرْأَةَ بِحَلْفِ اللَّعْنَةِ، وَيَقُولُ الْكَاهِنُ لِلْمَرْأَةِ׃ يَجْعَلُكِ الرَّبُّ لَعْنَةً وَحَلْفًا بَيْنَ شَعْبِكِ، بِأَنْ يَجْعَلَ الرَّبُّ فَخْذَكِ سَاقِطَةً وَبَطْنَكِ وَارِمًا.', 'عدد 5:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 22, 'وَيَدْخُلُ مَاءُ اللَّعْنَةِ هَذَا فِي أَحْشَائِكِ لِوَرَمِ الْبَطْنِ، وَلِإِسْقَاطِ الْفَخْذِ. فَتَقُولُ الْمَرْأَةُ׃ آمِينَ، آمِينَ.', 'عدد 5:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 23, 'وَيَكْتُبُ الْكَاهِنُ هَذِهِ اللَّعْنَاتِ فِي الْكِتَابِ ثُمَّ يَمْحُوهَا فِي الْمَاءِ الْمُرِّ،', 'عدد 5:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 24, 'وَيَسْقِي الْمَرْأَةَ مَاءَ اللَّعْنَةِ الْمُرَّ، فَيَدْخُلُ فِيهَا مَاءُ اللَّعْنَةِ لِلْمَرَارَةِ.', 'عدد 5:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 25, 'وَيَأْخُذُ الْكَاهِنُ مِنْ يَدِ الْمَرْأَةِ تَقْدِمَةَ الْغَيْرَةِ، وَيُرَدِّدُ التَّقْدِمَةَ أَمَامَ الرَّبِّ وَيُقَدِّمُهَا إِلَى الْمَذْبَحِ.', 'عدد 5:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 26, 'وَيَقْبِضُ الْكَاهِنُ مِنَ التَّقْدِمَةِ تَذْكَارَهَا وَيُوقِدُهُ عَلَى الْمَذْبَحِ، وَبَعْدَ ذَلِكَ يَسْقِي الْمَرْأَةَ الْمَاءَ.', 'عدد 5:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 27, 'وَمَتَى سَقَاهَا الْمَاءَ، فَإِنْ كَانَتْ قَدْ تَنَجَّسَتْ وَخَانَتْ رَجُلَهَا، يَدْخُلُ فِيهَا مَاءُ اللَّعْنَةِ لِلْمَرَارَةِ، فَيَرِمُ بَطْنُهَا وَتَسْقُطُ فَخْذُهَا، فَتَصِيرُ الْمَرْأَةُ لَعْنَةً فِي وَسَطِ شَعْبِهَا.', 'عدد 5:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 28, 'وَإِنْ لَمْ تَكُنِ الْمَرْأَةُ قَدْ تَنَجَّسَتْ بَلْ كَانَتْ طَاهِرَةً، تَتَبَرَّأُ وَتَحْبَلُ بِزَرْعٍ.', 'عدد 5:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 29, '«هَذِهِ شَرِيعَةُ الْغَيْرَةِ، إِذَا زَاغَتِ امْرَأَةٌ مِنْ تَحْتِ رَجُلِهَا وَتَنَجَّسَتْ،', 'عدد 5:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 30, 'أَوْ إِذَا اعْتَرَى رَجُلًا رُوحُ غَيْرَةٍ فَغَارَ عَلَى امْرَأَتِهِ، يُوقِفُ الْمَرْأَةَ أَمَامَ الرَّبِّ، وَيَعْمَلُ لَهَا الْكَاهِنُ كُلَّ هَذِهِ الشَّرِيعَةِ.', 'عدد 5:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 5, 31, 'فَيَتَبَرَّأُ الرَّجُلُ مِنَ الذَّنْبِ، وَتِلْكَ الْمَرْأَةُ تَحْمِلُ ذَنْبَهَا».', 'عدد 5:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 1, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 6:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 2, '«كَلِّمْ بَنِي إِسْرَائِيلَ وَقُلْ لَهُمْ׃ إِذَا انْفَرَزَ رَجُلٌ أَوِ امْرَأَةٌ لِيَنْذُرَ نَذْرَ النَّذِيرِ، لِيَنْتَذِرَ لِلرَّبِّ،', 'عدد 6:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 3, 'فَعَنِ الْخَمْرِ وَالْمُسْكِرِ يَفْتَرِزُ، وَلَا يَشْرَبْ خَلَّ الْخَمْرِ وَلَا خَلَّ الْمُسْكِرِ، وَلَا يَشْرَبْ مِنْ نَقِيعِ الْعِنَبِ، وَلَا يَأْكُلْ عِنَبًا رَطْبًا وَلَا يَابِسًا.', 'عدد 6:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 4, 'كُلَّ أَيَّامِ نَذْرِهِ لَا يَأْكُلْ مِنْ كُلِّ مَا يُعْمَلُ مِنْ جَفْنَةِ الْخَمْرِ مِنَ الْعَجَمِ حَتَّى الْقِشْرِ.', 'عدد 6:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 5, 'كُلَّ أَيَّامِ نَذْرِ افْتِرَازِهِ لَا يَمُرُّ مُوسَى عَلَى رَأْسِهِ. إِلَى كَمَالِ الْأَيَّامِ الَّتِي انْتَذَرَ فِيهَا لِلرَّبِّ يَكُونُ مُقَدَّسًا، وَيُرَبِّي خُصَلَ شَعْرِ رَأْسِهِ.', 'عدد 6:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 6, 'كُلَّ أَيَّامِ انْتِذَارِهِ لِلرَّبِّ لَا يَأْتِي إِلَى جَسَدِ مَيْتٍ.', 'عدد 6:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 7, 'أَبُوهُ وَأُمُّهُ وَأَخُوهُ وَأُخْتُهُ لَا يَتَنَجَّسْ مِنْ أَجْلِهِمْ عِنْدَ مَوْتِهِمْ، لِأَنَّ انْتِذَارَ إِلَهِهِ عَلَى رَأْسِهِ.', 'عدد 6:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 8, 'إِنَّهُ كُلَّ أَيَّامِ انْتِذَارِهِ مُقَدَّسٌ لِلرَّبِّ.', 'عدد 6:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 9, 'وَإِذَا مَاتَ مَيْتٌ عِنْدَهُ بَغْتَةً عَلَى فَجْأَةٍ فَنَجَّسَ رَأْسَ انْتِذَارِهِ، يَحْلِقُ رَأْسَهُ يَوْمَ طُهْرِهِ. فِي الْيَوْمِ السَّابِعِ يَحْلِقُهُ.', 'عدد 6:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 10, 'وَفِي الْيَوْمِ الثَّامِنِ يَأْتِي بِيَمَامَتَيْنِ أَوْ بِفَرْخَيْ حَمَامٍ إِلَى الْكَاهِنِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ،', 'عدد 6:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 11, 'فَيَعْمَلُ الْكَاهِنُ وَاحِدًا ذَبِيحَةَ خَطِيَّةٍ، وَالْآخَرَ مُحْرَقَةً وَيُكَفِّرُ عَنْهُ مَا أَخْطَأَ بِسَبَبِ الْمَيْتِ، وَيُقَدِّسُ رَأْسَهُ فِي ذَلِكَ الْيَوْمِ.', 'عدد 6:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 12, 'فَمَتَى نَذَرَ لِلرَّبِّ أَيَّامَ انْتِذَارِهِ يَأْتِي بِخَرُوفٍ حَوْلِيٍّ ذَبِيحَةَ إِثْمٍ، وَأَمَّا الْأَيَّامُ الْأُولَى فَتَسْقُطُ لِأَنَّهُ نَجَّسَ انْتِذَارَهُ.', 'عدد 6:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 13, '«وَهَذِهِ شَرِيعَةُ النَّذِيرِ׃ يَوْمَ تَكْمُلُ أَيَّامُ انْتِذَارِهِ يُؤْتَى بِهِ إِلَى بَابِ خَيْمَةِ الِاجْتِمَاعِ،', 'عدد 6:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 14, 'فَيُقَرِّبُ قُرْبَانَهُ لِلرَّبِّ خَرُوفًا وَاحِدًا حَوْلِيًّا صَحِيحًا مُحْرَقَةً، وَنَعْجَةً وَاحِدَةً حَوْلِيَّةً صَحِيحَةً ذَبِيحَةَ خَطِيَّةٍ، وَكَبْشًا وَاحِدًا صَحِيحًا ذَبِيحَةَ سَلَامَةٍ،', 'عدد 6:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 15, 'وَسَلَّ فَطِيرٍ مِنْ دَقِيقٍ أَقْرَاصًا مَلْتُوتَةً بِزَيْتٍ، وَرِقَاقَ فَطِيرٍ مَدْهُونَةً بِزَيْتٍ مَعَ تَقْدِمَتِهَا وَسَكَائِبِهَا.', 'عدد 6:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 16, 'فَيُقَدِّمُهَا الْكَاهِنُ أَمَامَ الرَّبِّ وَيَعْمَلُ ذَبِيحَةَ خَطِيَّتِهِ وَمُحْرَقَتَهُ.', 'عدد 6:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 17, 'وَالْكَبْشُ يَعْمَلُهُ ذَبِيحَةَ سَلَامَةٍ لِلرَّبِّ مَعَ سَلِّ الْفَطِيرِ، وَيَعْمَلُ الْكَاهِنُ تَقْدِمَتَهُ وَسَكِيبَهُ.', 'عدد 6:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 18, 'وَيَحْلِقُ النَّذِيرُ لَدَى بَابِ خَيْمَةِ الِاجْتِمَاعِ رَأْسَ انْتِذَارِهِ، وَيَأْخُذُ شَعْرَ رَأْسِ انْتِذَارِهِ وَيَجْعَلُهُ عَلَى النَّارِ الَّتِي تَحْتَ ذَبِيحَةِ السَّلَامَةِ.', 'عدد 6:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 19, 'وَيَأْخُذُ الْكَاهِنُ السَّاعِدَ مَسْلُوقًا مِنَ الْكَبْشِ، وَقُرْصَ فَطِيرٍ وَاحِدًا مِنَ السَّلِّ، وَرُقَاقَةَ فَطِيرٍ وَاحِدَةً، وَيَجْعَلُهَا فِي يَدَيِ النَّذِيرِ بَعْدَ حَلْقِهِ شَعْرَ انْتِذَارِهِ،', 'عدد 6:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 20, 'وَيُرَدِّدُهَا الْكَاهِنُ تَرْدِيدًا أَمَامَ الرَّبِّ. إِنَّهُ قُدْسٌ لِلْكَاهِنِ مَعَ صَدْرِ التَّرْدِيدِ وَسَاقِ الرَّفِيعَةِ. وَبَعْدَ ذَلِكَ يَشْرَبُ النَّذِيرُ خَمْرًا.', 'عدد 6:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 21, 'هَذِهِ شَرِيعَةُ النَّذِيرِ الَّذِي يَنْذُرُ، قُرْبَانُهُ لِلرَّبِّ عَنِ انْتِذَارِهِ فَضْلًا عَمَّا تَنَالُ يَدُهُ. حَسَبَ نَذْرِهِ الَّذِي نَذَرَ كَذَلِكَ يَعْمَلُ حَسَبَ شَرِيعَةِ انْتِذَارِهِ».', 'عدد 6:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 22, 'وَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 6:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 23, '«كَلِّمْ هَارُونَ وَبَنِيهِ قَائِلًا׃ هَكَذَا تُبَارِكُونَ بَنِي إِسْرَائِيلَ قَائِلِينَ لَهُمْ׃', 'عدد 6:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 24, 'يُبَارِكُكَ الرَّبُّ وَيَحْرُسُكَ.', 'عدد 6:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 25, 'يُضِيءُ الرَّبُّ بِوَجْهِهِ عَلَيْكَ وَيَرْحَمُكَ.', 'عدد 6:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 26, 'يَرْفَعُ الرَّبُّ وَجْهَهُ عَلَيْكَ وَيَمْنَحُكَ سَلَامًا.', 'عدد 6:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 6, 27, 'فَيَجْعَلُونَ اسْمِي عَلَى بَنِي إِسْرَائِيلَ، وَأَنَا أُبَارِكُهُمْ».', 'عدد 6:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 1, 'وَيَوْمَ فَرَغَ مُوسَى مِنْ إِقَامَةِ الْمَسْكَنِ، وَمَسَحَهُ وَقَدَّسَهُ وَجَمِيعَ أَمْتِعَتِهِ، وَالْمَذْبَحَ وَجَمِيعَ أَمْتِعَتِهِ وَمَسَحَهَا وَقَدَّسَهَا،', 'عدد 7:1');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 2, 'قَرَّبَ رُؤَسَاءُ إِسْرَائِيلَ، رُؤُوسُ بُيُوتِ آبَائِهِمْ، هُمْ رُؤَسَاءُ الْأَسْبَاطِ الَّذِينَ وَقَفُوا عَلَى الْمَعْدُودِينَ.', 'عدد 7:2');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 3, 'أَتَوْا بِقَرَابِينِهِمْ أَمَامَ الرَّبِّ׃ سِتَّ عَجَلَاتٍ مُغَطَّاةً، وَاثْنَيْ عَشَرَ ثَوْرًا. لِكُلِّ رَئِيسَيْنِ عَجَلَةٌ، وَلِكُلِّ وَاحِدٍ ثَوْرٌ، وَقَدَّمُوهَا أَمَامَ الْمَسْكَنِ.', 'عدد 7:3');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 4, 'فَكَلَّمَ الرَّبُّ مُوسَى قَائِلًا׃', 'عدد 7:4');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 5, '«خُذْهَا مِنْهُمْ فَتَكُونَ لِعَمَلِ خِدْمَةِ خَيْمَةِ الِاجْتِمَاعِ، وَأَعْطِهَا لِلَّاوِيِّينَ، لِكُلِّ وَاحِدٍ حَسَبَ خِدْمَتِهِ».', 'عدد 7:5');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 6, 'فَأَخَذَ مُوسَى الْعَجَلَاتِ وَالثِّيرَانَ وَأَعْطَاهَا لِلَّاوِيِّينَ׃', 'عدد 7:6');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 7, 'اثْنَتَانِ مِنَ الْعَجَلَاتِ وَأَرْبَعَةٌ مِنَ الثِّيرَانِ أَعْطَاهَا لِبَنِي جَرْشُونَ حَسَبَ خِدْمَتِهِمْ،', 'عدد 7:7');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 8, 'وَأَرْبَعٌ مِنَ الْعَجَلَاتِ وَثَمَانِيَةٌ مِنَ الثِّيرَانِ أَعْطَاهَا لِبَنِي مَرَارِي حَسَبَ خِدْمَتِهِمْ بِيَدِ إِيثَامَارَ بْنِ هَارُونَ الْكَاهِنِ.', 'عدد 7:8');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 9, 'وَأَمَّا بَنُو قَهَاتَ فَلَمْ يُعْطِهِمْ، لِأَنَّ خِدْمَةَ الْقُدْسِ كَانَتْ عَلَيْهِمْ، عَلَى الْأَكْتَافِ كَانُوا يَحْمِلُونَ.', 'عدد 7:9');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 10, 'وَقَرَّبَ الرُّؤَسَاءُ لِتَدْشِينِ الْمَذْبَحِ يَوْمَ مَسْحِهِ. وَقَدَّمَ الرُّؤَسَاءُ قَرَابِينَهُمْ أَمَامَ الْمَذْبَحِ.', 'عدد 7:10');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 11, 'فَقَالَ الرَّبُّ لِمُوسَى׃ «رَئِيسًا رَئِيسًا فِي كُلِّ يَوْمٍ يُقَرِّبُونَ قَرَابِينَهُمْ لِتَدْشِينِ الْمَذْبَحِ».', 'عدد 7:11');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 12, 'وَالَّذِي قَرَّبَ قُرْبَانَهُ فِي الْيَوْمِ الْأَوَّلِ نَحْشُونُ بْنُ عَمِّينَادَابَ، مِنْ سِبْطِ يَهُوذَا.', 'عدد 7:12');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 13, 'وَقُرْبَانُهُ طَبَقٌ وَاحِدٌ مِنْ فِضَّةٍ وَزْنُهُ مِئَةٌ وَثَلَاثُونَ شَاقِلًا، وَمِنْضَحَةٌ وَاحِدَةٌ مِنْ فِضَّةٍ سَبْعُونَ شَاقِلًا عَلَى شَاقِلِ الْقُدْسِ، كِلْتَاهُمَا مَمْلُوءَتَانِ دَقِيقًا مَلْتُوتًا بِزَيْتٍ لِتَقْدِمَةٍ،', 'عدد 7:13');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 14, 'وَصَحْنٌ وَاحِدٌ عَشَرَةُ شَوَاقِلَ مِنْ ذَهَبٍ مَمْلُوءٌ بَخُورًا،', 'عدد 7:14');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 15, 'وَثَوْرٌ وَاحِدٌ ابْنُ بَقَرٍ وَكَبْشٌ وَاحِدٌ وَخَرُوفٌ وَاحِدٌ حَوْلِيٌّ لِمُحْرَقَةٍ،', 'عدد 7:15');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 16, 'وَتَيْسٌ وَاحِدٌ مِنَ الْمَعَزِ لِذَبِيحَةِ خَطِيَّةٍ،', 'عدد 7:16');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 17, 'وَلِذَبِيحَةِ السَّلَامَةِ ثَوْرَانِ وَخَمْسَةُ كِبَاشٍ وَخَمْسَةُ تُيُوسٍ وَخَمْسَةُ خِرَافٍ حَوْلِيَّةٍ. هَذَا قُرْبَانُ نَحْشُونَ بْنِ عَمِّينَادَابَ.', 'عدد 7:17');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 18, 'وَفِي الْيَوْمِ الثَّانِي قَرَّبَ نَثَنَائِيلُ بْنُ صُوغَرَ رَئِيسُ يَسَّاكَرَ.', 'عدد 7:18');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 19, 'قَرَّبَ قُرْبَانَهُ طَبَقًا وَاحِدًا مِنْ فِضَّةٍ وَزْنُهُ مِئَةٌ وَثَلَاثُونَ شَاقِلًا، وَمِنْضَحَةً وَاحِدَةً مِنْ فِضَّةٍ سَبْعِينَ شَاقِلًا عَلَى شَاقِلِ الْقُدْسِ، كِلْتَاهُمَا مَمْلُوءَتَانِ دَقِيقًا مَلْتُوتًا بِزَيْتٍ لِتَقْدِمَةٍ،', 'عدد 7:19');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 20, 'وَصَحْنًا وَاحِدًا عَشَرَةَ شَوَاقِلَ مِنْ ذَهَبٍ مَمْلُوًّا بَخُورًا،', 'عدد 7:20');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 21, 'وَثَوْرًا وَاحِدًا ابْنَ بَقَرٍ وَكَبْشًا وَاحِدًا وَخَرُوفًا وَاحِدًا حَوْلِيًّا لِمُحْرَقَةٍ،', 'عدد 7:21');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 22, 'وَتَيْسًا وَاحِدًا مِنَ الْمَعْزِ لِذَبِيحَةِ خَطِيَّةٍ،', 'عدد 7:22');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 23, 'وَلِذَبِيحَةِ السَّلَامَةِ ثَوْرَانِ وَخَمْسَةَ كِبَاشٍ وَخَمْسَةُ تُيُوسٍ وَخَمْسَةُ خِرَافٍ حَوْلِيَّةٍ. هَذَا قُرْبَانُ نَثَنَائِيلَ بْنِ صُوغَرَ.', 'عدد 7:23');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 24, 'وَفِي الْيَوْمِ الثَّالِثِ رَئِيسُ بَنِي زَبُولُونَ أَلِيآبُ بْنُ حِيلُونَ.', 'عدد 7:24');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 25, 'قُرْبَانُهُ طَبَقٌ وَاحِدٌ مِنْ فِضَّةٍ وَزْنُهُ مِئَةٌ وَثَلَاثُونَ شَاقِلًا وَمِنْضَحَةٌ وَاحِدَةٌ مِنْ فِضَّةٍ سَبْعُونَ شَاقِلًا عَلَى شَاقِلِ الْقُدْسِ، كِلْتَاهُمَا مَمْلُوءَتَانِ دَقِيقًا مَلْتُوتًا بِزَيْتٍ لِتَقْدِمَةٍ،', 'عدد 7:25');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 26, 'وَصَحْنٌ وَاحِدٌ عَشَرَةُ شَوَاقِلَ مِنْ ذَهَبٍ مَمْلُوءٌ بَخُورًا،', 'عدد 7:26');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 27, 'وَثَوْرٌ وَاحِدٌ ابْنُ بَقَرٍ وَكَبْشٌ وَاحِدٌ وَخَرُوفٌ وَاحِدٌ حَوْلِيٌّ لِمُحْرَقَةٍ،', 'عدد 7:27');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 28, 'وَتَيْسٌ وَاحِدٌ مِنَ الْمَعْزِ لِذَبِيحَةِ خَطِيَّةٍ،', 'عدد 7:28');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 29, 'وَلِذَبِيحَةِ السَّلَامَةِ ثَوْرَانِ وَخَمْسَةُ كِبَاشٍ وَخَمْسَةُ تُيُوسٍ وَخَمْسَةُ خِرَافٍ حَوْلِيَّةٍ. هَذَا قُرْبَانُ أَلِيآبَ بْنِ حِيلُونَ.', 'عدد 7:29');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 30, 'وَفِي الْيَوْمِ الرَّابِعِ رَئِيسُ بَنِي رَأُوبَيْنَ أَلِيصُورُ بْنُ شَدَيْئُورَ.', 'عدد 7:30');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 31, 'قُرْبَانُهُ طَبَقٌ وَاحِدٌ مِنْ فِضَّةٍ وَزْنُهُ مِئَةٌ وَثَلَاثُونَ شَاقِلًا، وَمِنْضَحَةٌ وَاحِدَةٌ مِنْ فِضَّةٍ سَبْعُونَ شَاقِلًا عَلَى شَاقِلِ الْقُدْسِ، كِلْتَاهُمَا مَمْلُوءَتَانِ دَقِيقًا مَلْتُوتًا بِزَيْتٍ لِتَقْدِمَةٍ،', 'عدد 7:31');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 32, 'وَصَحْنٌ وَاحِدٌ عَشَرَةُ شَوَاقِلَ مِنْ ذَهَبٍ مَمْلُوءٌ بَخُورًا،', 'عدد 7:32');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 33, 'وَثَوْرٌ وَاحِدٌ ابْنُ بَقَرٍ وَكَبْشٌ وَاحِدٌ وَخَرُوفٌ وَاحِدٌ حَوْلِيٌّ لِمُحْرَقَةٍ،', 'عدد 7:33');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
                                VALUES ('العهد القديم', 'عدد', 7, 34, 'وَتَيْسٌ وَاحِدٌ مِنَ الْمَعْزِ لِذَبِيحَةِ خَطِيَّةٍ،', 'عدد 7:34');
INSERT INTO wp_bible_verses (testament, book, chapter, verse, text, reference) 
